// ═══ 935 — YILDIZLAR ═══
//   Oyuncu / takım / milli takım: o anki en yüksek yetenek 5 yıldız, 10 yetenek 1 yıldız; arası doğrusal, aşağı çeyreğe yuvarlanır.
//   En yüksek değer 150'ye ulaşınca ölçek 150'de sabitlenir ve 6. (turuncu) yıldız açılır.
//   En yüksek değerler sunucudan tek küçük istekle (yildiz_ref) gelir, cihazda 30 dk saklanır; eski değer beklemeden kullanılır.
var _yzRef = null, _yzYuk = false, _yzBekle = 0, _oyOvr = {};
try { var _yzO0 = JSON.parse(localStorage.getItem('csc_yz_ref') || 'null'); if (_yzO0 && typeof _yzO0 === 'object' && _yzO0.at) _yzRef = _yzO0; } catch (e) {}
function _yzRefYukle() {
  if (_yzYuk || !window.sb || Date.now() < _yzBekle) return;
  if (_yzRef && Date.now() - (_yzRef.at || 0) < 1800000) return;
  _yzYuk = true;
  Promise.resolve(window.sb.rpc('yildiz_ref')).then(({ data, error }) => {
    _yzYuk = false;
    if (error || !data || typeof data !== 'object') { _yzBekle = Date.now() + 300000; return; }
    const eski = _yzRef ? [_yzT('p'), _yzT('t'), _yzT('n')].join('|') : '';
    _yzRef = { p: Number(data.p) || 0, t: Number(data.t) || 0, n: Number(data.n) || 0, nt: (data.nt && typeof data.nt === 'object') ? data.nt : {}, at: Date.now() };
    try { localStorage.setItem('csc_yz_ref', JSON.stringify(_yzRef)); } catch (e) {}
    if (eski !== [_yzT('p'), _yzT('t'), _yzT('n')].join('|')) _yzTazele();
  }, () => { _yzYuk = false; _yzBekle = Date.now() + 300000; });
}
// tip: 'p' oyuncu · 't' takım · 'n' milli takım
function _yzT(tip) {
  if (!_yzRef) return 0;
  let T = Number(_yzRef[tip]) || 0;
  if (tip === 'n') { try { if (_rkNtOvr) for (const k in _rkNtOvr) if (Number(_rkNtOvr[k]) > T) T = Number(_rkNtOvr[k]); } catch (e) {} }
  return Math.round(T);
}
function _yzDeger(o, T) {   // 935b — 10 yetenek = 1 yıldız, en yüksek = 5 (150'de 6); 10'un altı (veri yok) orantılı
  const ust = T >= 150 ? 6 : 5, ref = T >= 150 ? 150 : T, v = Math.round(Number(o) || 0);
  const y = v < 10 ? v / 10 : (ref > 10 ? 1 + (ust - 1) * (v - 10) / (ref - 10) : 1);
  return Math.max(0, Math.min(ust, Math.floor(4 * y + 1e-9) / 4));
}
function _yzArka(y, alti) {
  const n = alti ? 6 : 5, g = Math.min(y, 5) / n * 100, b = 5 / n * 100, t = y / n * 100;
  return alti ? `linear-gradient(90deg,var(--yzA) ${g}%,var(--yzB) ${g}% ${b}%,var(--yzT) ${b}% ${t}%,var(--yzB) ${t}%)`
              : `linear-gradient(90deg,var(--yzA) ${g}%,var(--yzB) ${g}%)`;
}
