// 🔊 BUTON SESİ SİSTEMİ
// Web Audio API ile tüm butonlarda hafif tık sesi
// Ayarlar > Buton Sesi toggle ile kontrol edilir
// localStorage: cft_button_sound (true/false)
// ═══════════════════════════════════════════
let _cftAudioCtx = null;
let _cftButtonSoundEnabled = (localStorage.getItem('cft_button_sound') !== 'false');

function _cftGetAudioCtx(){
  if(!_cftAudioCtx){
    _cftAudioCtx = new (window.AudioContext || window.webkitAudioContext)();
  }
  if(_cftAudioCtx.state !== 'running'){
    _cftAudioCtx.resume().catch(() => {});
  }
  return _cftAudioCtx;
}

function cftPlayClickSound(){
  if(!_cftButtonSoundEnabled) return;
  try {
    const c = _cftGetAudioCtx();
    const t = c.currentTime;
    const o = c.createOscillator();
    const g = c.createGain();
    o.type = 'sine';
    o.frequency.setValueAtTime(900, t);
    o.frequency.exponentialRampToValueAtTime(300, t + 0.05);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(0.18, t + 0.005);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.08);
    o.connect(g).connect(c.destination);
    o.start(t);
    o.stop(t + 0.1);
  } catch(e){}
}

function cftToggleButtonSound(el){
  el.classList.toggle('on');
  _cftButtonSoundEnabled = el.classList.contains('on');
  localStorage.setItem('cft_button_sound', _cftButtonSoundEnabled ? 'true' : 'false');
  // Açıldığında onay sesi çal
  if(_cftButtonSoundEnabled) cftPlayClickSound();
}

