// ═══════════════════════════════════════════
// 🆕 614 — OYUN SESLERİ: ana müzik + maç ambiyansı (tribün, devre arası müziği)
//   Dosyalar index.html'in yanında. Her biri başına/sonuna 1 sn sarmal pay eklenmiş dikişsiz döngü.
//   Müzik anahtarı (varsayılan açık): ana müzik, antrenman sayfasında antrenman sesi · Tribün + devre arası: Maç Sesi anahtarı
// ═══════════════════════════════════════════
const _SES_DONGU = {
  muzik:     { url: 'muzik.mp3?v=614',       uz: 12.8,      seviye: 0.20, katman: 1 },
  antrenman: { url: 'antrenman.mp3?v=615',   uz: 69.8,      seviye: 0.45, katman: 1, ortam: true },
  tribun:    { url: 'tribun.mp3?v=614',      uz: 34.288005, seviye: 0.30, katman: 2, ortam: true },
  devre:     { url: 'devre-arasi.mp3?v=614', uz: 7.5,       seviye: 0.22, katman: 1 },
  duello:    { url: 'pd/duello-tribun.mp3?v=665', uz: 18,   seviye: 0.26, katman: 1, ortam: true }   // 665 · 666 biraz kısıldı
};
const _sesBuf = {};
const _muzikKanal = { ad: null, g: null, kaynak: [] }, _macKanal = { ad: null, g: null, kaynak: [] };
let _cftMusicEnabled = (localStorage.getItem('cft_music_enabled') !== 'false');
let _cftMusicPlaying = false;
let _macDurum = null;

function _sesYukle(ad) {
  if (!_sesBuf[ad]) _sesBuf[ad] = fetch(_SES_DONGU[ad].url).then(r => r.arrayBuffer())
    .then(b => _cftGetAudioCtx().decodeAudioData(b))
    .catch(e => { _sesBuf[ad] = null; throw e; });
  return _sesBuf[ad];
}
function _sesCal(k, ad) {
  _sesDurdur(k, 2);
  const c = _cftGetAudioCtx(), d = _SES_DONGU[ad], g = c.createGain();
  g.gain.value = 0; g.connect(c.destination);
  k.ad = ad; k.g = g;
  _sesYukle(ad).then(buf => {
    if (k.g !== g) return;
    const bas = d.ortam ? Math.random() * d.uz : 0;
    [[1, bas], [0.955, (bas * 0.955 + d.uz / 2) % d.uz]].slice(0, d.katman).forEach(([oran, ofs]) => {
      const src = c.createBufferSource(), kg = c.createGain();
      src.buffer = buf; src.loop = true; src.loopStart = 1; src.loopEnd = 1 + d.uz; src.playbackRate.value = oran;
      kg.gain.value = d.katman === 2 ? 0.72 : 1;
      src.connect(kg); kg.connect(g); src.start(0, 1 + ofs);
      k.kaynak.push(src);
    });
    g.gain.setValueAtTime(0, c.currentTime);
    g.gain.linearRampToValueAtTime(d.seviye, c.currentTime + 1.5);
  }).catch(() => {});
}
function _sesDurdur(k, sure) {
  if (!k.g) return;
  const c = _cftAudioCtx, g = k.g, kaynak = k.kaynak;
  k.ad = null; k.g = null; k.kaynak = [];
  g.gain.cancelScheduledValues(c.currentTime);
  g.gain.setValueAtTime(g.gain.value, c.currentTime);
  g.gain.linearRampToValueAtTime(0, c.currentTime + sure);
  setTimeout(() => { kaynak.forEach(src => src.stop()); g.disconnect(); }, sure * 1000 + 100);
}
// Maç ekranı durumu: 'tribun' (oyun sürerken) · 'devre' (devre arası) · null (maç yok/bitti/ekran kapalı)
function _macSesDurum(durum) {
  if (durum !== _macDurum) {
    _macDurum = durum;
    if (durum) _cftMusicStop(); else if (_cftMusicEnabled) _cftMusicStart();
  }
  const ses = window._resGoalSoundOff ? null : durum;
  if (_macKanal.ad === ses) return;
  if (ses) _sesCal(_macKanal, ses); else _sesDurdur(_macKanal, 2);
}
// Golde tribün kısa süre coşar, sonra eski seviyesine iner
function _macSesCos() {
  const g = _macKanal.ad === 'tribun' && _macKanal.g;
  if (!g) return;
  const t = _cftAudioCtx.currentTime, sv = _SES_DONGU.tribun.seviye;
  g.gain.cancelScheduledValues(t);
  g.gain.setValueAtTime(g.gain.value, t);
  g.gain.linearRampToValueAtTime(sv * 1.9, t + 0.35);
  g.gain.setTargetAtTime(sv, t + 2.2, 1.1);
}
// 634 · Elmas fişi yazdırılırken müzik ve ortam sesi iyice kısılır (kapanmaz), ödeme sesiyle eski seviyesine döner
function _sesKis(oran, sure) {
  [_muzikKanal, _macKanal].forEach(k => {
    if (!k.g) return;
    const t = _cftAudioCtx.currentTime;
    k.g.gain.cancelScheduledValues(t);
    k.g.gain.setValueAtTime(k.g.gain.value, t);
    k.g.gain.linearRampToValueAtTime(_SES_DONGU[k.ad].seviye * oran, t + sure);
  });
}
document.addEventListener('visibilitychange', () => {
  if (!_cftAudioCtx) return;
  (document.hidden ? _cftAudioCtx.suspend() : _cftAudioCtx.resume()).catch(() => {});
});

function _cftMusicStart() {
  if (window._cftMatchInProgress || _macDurum || window._pdSesAcik) return;
  const _auEk = document.getElementById('auth-screen'); if (_auEk && !_auEk.classList.contains('hidden')) return;   // 876   // 665 — düelloda tribün çalar
  const ad = document.getElementById('page-training').classList.contains('active') ? 'antrenman' : 'muzik';
  if (_cftMusicPlaying && _muzikKanal.ad === ad) return;
  _cftMusicPlaying = true;
  _sesCal(_muzikKanal, ad);
}

function _cftMusicStop() {
  _cftMusicPlaying = false;
  _sesDurdur(_muzikKanal, 1);
}

function cftToggleMusic(el) {
  el.classList.toggle('on');
  _cftMusicEnabled = el.classList.contains('on');
  localStorage.setItem('cft_music_enabled', _cftMusicEnabled ? 'true' : 'false');
  if (_cftMusicEnabled) {
    _cftMusicStart();
  } else {
    _cftMusicStop();
  }
}

// Sayfa açılışında: ayar açıksa müzik başlat (ilk kullanıcı etkileşimi sonrası)
document.addEventListener('DOMContentLoaded', function(){
  const togM = document.getElementById('set-toggle-music');
  if (togM) {
    if (_cftMusicEnabled) togM.classList.add('on');
    else togM.classList.remove('on');
  }
  // Ayar açıksa müzik başlat (ilk dokunuştan sonra)
  if (_cftMusicEnabled) {
    function tryStart() {
      // 876 — giriş / kayıt ekranında ve ana sayfadan önceki pencerelerde (sözleşme, tanıtım) müzik çalmaz
      const _au = document.getElementById('auth-screen'), _ev = document.getElementById('page-home');
      if ((_au && !_au.classList.contains('hidden')) || !(typeof authUser !== 'undefined' && authUser && authUser.id)
          || !(_ev && _ev.classList.contains('active')) || document.querySelector('#szOv.open, .tnt-ov.open')) return;
      _cftMusicStart();
      document.removeEventListener('click', tryStart, true);
      document.removeEventListener('touchstart', tryStart, true);
    }
    document.addEventListener('click', tryStart, true);
    document.addEventListener('touchstart', tryStart, true);
  }
});

