// 🌍 DİL SEÇİM SİSTEMİ
// localStorage: cft_language (default 'tr')
// Şu an sadece Türkçe destekli — altyapı hazır
// ═══════════════════════════════════════════


// ═══════════════════════════════════════════════════════════════════
// 🔬 PERFORMANS ÖLÇER — telefonda konsol açılamadığı için ekranda gösterir
//   Açmak için adresin sonuna ?perf=1 ekle:  citysoccer.club/?perf=1
//   Kapatmak için parametreyi kaldır. Normalde HİÇBİR maliyeti yoktur.
// ═══════════════════════════════════════════════════════════════════
// ═══════════════════════════════════════════════════════════════════
// 🔋 ARKA PLAN FRENİ
//   Uygulama görünmüyorken (telefon kilitli, başka sekme/uygulama)
//   yoklama ve geri sayım işleri boşuna çalışıp pil yakıyordu.
//   Bu bayrak açıkken ağır işler atlanır; ekrana dönünce hemen tazelenir.
// ═══════════════════════════════════════════════════════════════════
function _sayfaGizli() {
  try { return document.visibilityState === 'hidden' || document.hidden === true; }
  catch(e) { return false; }
}
window._sayfaGizli = _sayfaGizli;

document.addEventListener('visibilitychange', function() {
  if (_sayfaGizli()) return;
  if (_kisaDonus956()) return;   // 956 — kısa dönüşte maç verisi / ana sayfa kartı yeniden çekilmez (canlı tur sürüyor)
  // Görünür oldu → sunucudan taze veri çek, ekranı tazele
  // 🆕 563 — 1 saatten kısa ayrılıkta TÜM maç verisi (~5 bin satır, 5-8 istek) yerine
  //   yalnız bu arada oynanan/başlayan maçlar çekilir (değişebilecek tek dilim).
  try {
    const _sc = window._msScope || {};
    const _son = _sc.syncAt || _sc.coreAt || 0;
    if (_son && (Date.now() - _son) < 60 * 60 * 1000 && typeof _msTazeleDelta === 'function') _msTazeleDelta(_son);
    else if (typeof _loadAllMatchStateFromServer === 'function') _loadAllMatchStateFromServer();
  } catch(e) {}
  try {
    const aktif = document.querySelector('.page.active');
    if (aktif && aktif.id === 'page-home' && typeof renderHomeNextMatch === 'function') {
      renderHomeNextMatch(true);
    }
  } catch(e) {}
});

window._perfSayac = window._perfSayac || {};
function perfSay(ad) {
  if (!window._perfAcik) return;
  window._perfSayac[ad] = (window._perfSayac[ad] || 0) + 1;
}
window.perfSay = perfSay;

(function(){
  try {
    if (location.search.indexOf('perf=1') < 0) return;
    window._perfAcik = true;

    const kutu = document.createElement('div');
    kutu.id = 'perfKutu';
    kutu.style.cssText = 'position:fixed;left:6px;bottom:6px;z-index:2147483600;'
      + 'background:rgba(0,0,0,.86);color:#00e676;border:1px solid #00e676;border-radius:8px;'
      + 'padding:7px 9px;font:11px/1.45 monospace;max-width:70vw;white-space:pre;'
      + 'pointer-events:auto;box-shadow:0 4px 18px rgba(0,0,0,.6)';
    kutu.onclick = function(){ window._perfSayac = {}; _perfKare.n = 0; };
    const bas = () => { if (document.body) document.body.appendChild(kutu); else setTimeout(bas, 300); };
    bas();

    // Kare hızı (FPS) — düşükse ana iş parçacığı doludur
    const _perfKare = { n: 0, fps: 0, son: performance.now() };
    (function sayKare(){
      _perfKare.n++;
      const t = performance.now();
      if (t - _perfKare.son >= 1000) {
        _perfKare.fps = _perfKare.n;
        _perfKare.n = 0;
        _perfKare.son = t;
      }
      requestAnimationFrame(sayKare);
    })();

    // Ağ isteği sayacı
    window._perfFetch = 0;
    const _fetchAsil = window.fetch;
    window.fetch = function() { window._perfFetch++; return _fetchAsil.apply(this, arguments); };

    let gecen = 0;
    setInterval(() => {
      gecen += 3;
      const c = window._perfSayac;
      const sirali = Object.keys(c).sort((a,b) => c[b] - c[a]).slice(0, 7);
      let m = 'FPS ' + _perfKare.fps + '  ·  ' + gecen + 'sn  ·  ağ ' + window._perfFetch + '\n';
      m += 'dil: ' + (typeof i18nLang === 'function' ? i18nLang() : '?')
         + (typeof i18nAktif === 'function' && i18nAktif() ? ' (çeviri AÇIK)' : ' (çeviri kapalı)') + '\n';
      m += sirali.length ? sirali.map(k => '  ' + k + ': ' + c[k]).join('\n') : '  (henüz sayaç yok)';
      m += '\n[dokun = sıfırla]';
      kutu.textContent = m;
    }, 3000);
  } catch(e) {}
})();

// ═══════════════════════════════════════════════════════════════════
// 🌍 ÇEVİRİ MOTORU (i18n)
