// Country code → flag emoji (regional indicator letters)
function ccToFlag(cc){
  if(!cc) return '🏳️';
  cc = String(cc).toUpperCase();
  // Özel app-içi kodlar (ISO dışı)
  if(cc === 'EN') return '🏴󠁧󠁢󠁥󠁮󠁧󠁿';
  if(cc === 'SC') return '🏴󠁧󠁢󠁳󠁣󠁴󠁿';
  if(cc === 'XK') return '🇽🇰'; // Kosova (ISO dışı ama emoji destekli)
  // Standart 2-harfli ISO kodlar
  if(!/^[A-Z]{2}$/.test(cc)) return '🏳️';
  return cc.replace(/./g, c => String.fromCodePoint(0x1F1E6 + c.charCodeAt(0) - 65));
}

// 652 — uyruk (ligi olmayan ülkeler dahil): ad + bayrak
function _uyrukUlke(cc) {
  const c = (typeof _cftGetCountry === 'function') ? _cftGetCountry(cc) : null;
  if (c) return c;
  const k = CFT_ALL_COUNTRIES.find(x => x.code === String(cc || '').toUpperCase());
  if (!k) return {};
  const ad = (i18nAktif() && typeof Intl.DisplayNames === 'function') ? new Intl.DisplayNames([_i18nLang], { type: 'region' }).of(k.code) : k.name;
  return { name: ad, flag: ccToFlag(k.code) };
}

// Global lookup mapleri (eski FLAG_BY_CC ve NAT_LABELS yerine kullanılır)
const CFT_FLAG_BY_CC = {};
const CFT_NAT_LABELS = {};
CFT_ALL_COUNTRIES.forEach(c => {
  CFT_FLAG_BY_CC[c.code] = ccToFlag(c.code);
  CFT_NAT_LABELS[c.code] = `${ccToFlag(c.code)} ${c.name}`;
});

// Kayıt formundaki uyruk select'ini doldur
function cftPopulateNationalitySelect(){
  const sel = document.getElementById('regNationality');
  if(!sel) return;
  const cur = sel.value; // mevcut seçimi koru
  sel.innerHTML = '<option value="">Seçin...</option>' +
    CFT_ALL_COUNTRIES.map(c =>
      `<option value="${c.code}">${ccToFlag(c.code)} ${c.name}</option>`
    ).join('');
  if(cur) sel.value = cur;
}

document.addEventListener('DOMContentLoaded', cftPopulateNationalitySelect);

// ── SPLASH SCREEN otomatik kaldırma ──
// CSS animation 1.6s + 0.6s fade = 2.2s sonra display:none yap
window.addEventListener('load', function() {
  setTimeout(function() {
    var sp = document.getElementById('splash-screen');
    if(sp) sp.classList.add('done');
  }, 2300);

  // Eski v1 roster cache'lerini temizle (cft_roster_ → cft_r2_ formatına geçiş)
  try {
    const toDelete = [];
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      if (key && key.startsWith('cft_roster_')) toDelete.push(key);
    }
    toDelete.forEach(k => localStorage.removeItem(k));
  } catch(e) {}

  // 🆕 Uygulama (Capacitor WebView) içinde miyiz? Öyleyse <body>'ye
//   `app-native` sınıfı ekle — ağır görsel efektler orada kapatılıyor.
(function appNativeIsaretle(){
  function uygula(){
    try {
      const kapsayici = !!(window.Capacitor || window.cordova)
        || / wv\)|; wv;/i.test(navigator.userAgent || '');
      if (kapsayici && document.body) document.body.classList.add('app-native');
    } catch(e) {}
  }
  if (document.body) uygula();
  else document.addEventListener('DOMContentLoaded', uygula);
})();

// 🆕 Odaklanılan alan klavyenin altında kalırsa görünür alana kaydır.
  //   Android'de tarayıcı bunu her zaman kendi yapmıyor; özellikle
  //   `position:absolute` bir katmanın (giriş/kayıt ekranı) içindeyken.
  (function odakKaydir(){
    let zaman = null;
    document.addEventListener('focusin', function(e){
      const el = e.target;
      if (!el || !el.matches || !el.matches('input, textarea, select')) return;
      if (el.id === 'teamChatInput' || el.id === 'ntChatInput') return;  // sohbet kendi yönetiyor
      clearTimeout(zaman);
      // Klavyenin açılıp görünür alanın küçülmesini bekle
      zaman = setTimeout(function(){
        try {
          const r = el.getBoundingClientRect();
          const gorunen = (window.visualViewport && window.visualViewport.height) || window.innerHeight;
          if (r.bottom > gorunen - 12 || r.top < 8) {
            el.scrollIntoView({ block: 'center', behavior: 'smooth' });
          }
        } catch(err) {}
      }, 320);
    }, true);
    document.addEventListener('focusout', function(){ clearTimeout(zaman); }, true);
  })();

  // 🆕 Mobil klavye tespiti — visualViewport API + Input focus (en güvenilir)
  // Klavye açıldığında body.kbd-open eklenir → bottom nav gizle, chat'i tam ekrana al
  (function setupKeyboardDetection(){
    let kbdOpen = false;

    // 🆕 Hangi sohbet açık? Milli takım sohbeti aktifse onun kutusu/alanı,
    //    değilse (varsayılan) kulüp sohbeti — kulüp davranışı AYNEN korunur.
    function _aktifSohbet(){
      if(document.body.classList.contains('nt-chat-active')){
        return { kutu: document.getElementById('nt-chat'),
                 alan: document.getElementById('ntChatArea') };
      }
      return { kutu: document.getElementById('team-chat'),
               alan: document.getElementById('teamChatArea') };
    }
    function _sohbetInputMu(el){
      return !!(el && (el.id === 'teamChatInput' || el.id === 'ntChatInput'));
    }

    // 🆕 Klavye yüksekliğini ölçüp CSS variable olarak yaz
    // Böylece #team-chat / #nt-chat bottom:var(--kbd-h) ile klavyenin üst kenarına yapışır
    function adjustChatArea(){
      const _s = _aktifSohbet();
      const chat = _s.kutu;
      const ca = _s.alan;

      // 🔴 ÖLÇÜM HER ZAMAN YAPILIR
      //   Eskiden burada `if(!chat || !ca) return;` vardı: sohbet kutusu
      //   yoksa fonksiyon hemen çıkıyor ve `--kbd-h` HİÇ yazılmıyordu.
      //   Giriş/kayıt ekranında sohbet olmadığı için klavye yüksekliği
      //   bilinmiyor, alanlar klavyenin altında kalıyordu (Android).
      if(!document.body.classList.contains('kbd-open')){
        document.documentElement.style.setProperty('--kbd-h', '0px');
        return;
      }

      // Klavye yüksekliği = layoutViewport - visualViewport - offsetTop
      // (offsetTop iOS'ta sayfa yukarı scroll olduğunda > 0)
      let kbdHeight = 0;
      if(window.visualViewport){
        const vv = window.visualViewport;
        kbdHeight = Math.max(0, window.innerHeight - vv.height - vv.offsetTop);
      }
      document.documentElement.style.setProperty('--kbd-h', kbdHeight + 'px');

      // Sohbet kutusu yoksa (giriş/kayıt, form ekranları) burada biter
      if(!chat || !ca) return;

      // En alta scroll — DOM güncellemesi sonrası garantili (çift RAF)
      requestAnimationFrame(() => {
        ca.scrollTop = ca.scrollHeight;
        requestAnimationFrame(() => { ca.scrollTop = ca.scrollHeight; });
      });
    }

    function setKbdOpen(open){
      if(open === kbdOpen) return;
      kbdOpen = open;
      document.body.classList.toggle('kbd-open', open);
      if(open){
        // Klavye açıldı → chat-area yüksekliğini ayarla + scroll
        setTimeout(() => {
          adjustChatArea();
          const ca = _aktifSohbet().alan;
          if(ca && ca.offsetParent !== null){
            ca.scrollTop = ca.scrollHeight;
          }
        }, 200);
      } else {
        // Kapandı → height'ı sıfırla
        adjustChatArea();
      }
    }

    // 691 — iOS: klavye kapanıp kutu büyüyünce mesaj alanının kaydırma konumu yeni boya uymuyor,
    //   son mesajın altında boşluk kalıyordu. En alttaysa klavye kapanınca yeniden en alta oturtulur.
    const _ios = (() => { try { return (window.Capacitor && window.Capacitor.getPlatform && window.Capacitor.getPlatform() === 'ios') || /iP(hone|ad|od)/.test(navigator.userAgent); } catch(e) { return false; } })();
    function _iosAltaOtur(){
      if(!_ios) return;
      const ca = _aktifSohbet().alan;
      if(!ca || ca.scrollHeight - ca.scrollTop - ca.clientHeight > 60) return;
      [60, 380].forEach(ms => setTimeout(() => {
        const enAlt = Math.max(0, ca.scrollHeight - ca.clientHeight);
        ca.scrollTop = Math.max(0, enAlt - 1);
        requestAnimationFrame(() => { ca.scrollTop = ca.scrollHeight; });
      }, ms));
    }

    // Yöntem 1: Direkt input focus/blur (en güvenilir, iOS+Android)
    const chatInp = document.getElementById('teamChatInput');
    if(chatInp){
      chatInp.addEventListener('focus', () => setKbdOpen(true));
      chatInp.addEventListener('blur', () => { _iosAltaOtur(); setKbdOpen(false); });
    }
    // 🆕 Milli takım sohbeti girişi DOM'a sonradan ekleniyor (ntRenderChat) →
    //    doğrudan dinleyici yerine delegasyon. Kulüp yolu değişmedi.
    document.addEventListener('focusin', (e) => {
      if(e.target && e.target.id === 'ntChatInput') setKbdOpen(true);
    });
    document.addEventListener('focusout', (e) => {
      if(e.target && e.target.id === 'ntChatInput') { _iosAltaOtur(); setKbdOpen(false); }
    });

    // Sıralama arama alanı — aynı sistem: focus'ta anında kbd-open (nav gizle + arka plan dondur → titreme yok)
    const rkInp = document.getElementById('rkSearchInput');
    if(rkInp){
      rkInp.addEventListener('focus', () => setKbdOpen(true));
      rkInp.addEventListener('blur', () => setKbdOpen(false));
    }

    // Yöntem 2: VisualViewport API yedek (genel klavye tespiti + dinamik yükseklik)
    if(window.visualViewport){
      let baseHeight = window.innerHeight;
      const checkKeyboard = () => {
        const vv = window.visualViewport;
        if(!vv) return;
        const heightDiff = baseHeight - vv.height;
        // Sadece chat input focus yoksa setKbdOpen çağır (yöntem 1 öncelikli)
        const _ozelAlan = _sohbetInputMu(document.activeElement)
          || (document.activeElement && document.activeElement.id === 'rkSearchInput');
        if(!_ozelAlan){
          // 🆕 GENEL KLAVYE TESPİTİ ARTIK SADECE SOHBET EKRANLARINDA
          //    Eskiden HERHANGİ bir alana yazarken klavye açılınca body.kbd-open
          //    ekleniyordu; bu sınıf body'ye position:fixed + overflow:hidden
          //    uyguladığı için giriş/kayıt ekranı gibi sayfalarda içerik
          //    kayboluyordu (mobil uygulamada "ekran karardı" belirtisi).
          //    Giriş ekranının kendi klavye yönetimi zaten var (auth-kbd-lock).
          const _sohbetEkrani = document.body.classList.contains('team-chat-active')
                             || document.body.classList.contains('nt-chat-active');
          if (_sohbetEkrani) setKbdOpen(heightDiff > 150);
          else if (kbdOpen) setKbdOpen(false);
        } else {
          // Klavye açıldıysa yüksekliği yenile (özellikle iOS'ta)
          adjustChatArea();
        }
      };
      window.addEventListener('orientationchange', () => {
        setTimeout(() => { baseHeight = window.innerHeight; checkKeyboard(); }, 300);
      });
      window.visualViewport.addEventListener('resize', checkKeyboard);
      window.visualViewport.addEventListener('scroll', checkKeyboard);
    }
  })();

  // 🆕 Kayıt/giriş ekranı klavye yönetimi — odaklanan alan klavyenin üstünde kalsın
  (function setupAuthKeyboard(){
    const scr = document.getElementById('auth-screen');
    if(!scr) return;
    let active = false, blurT = 0;
    const vv = window.visualViewport;
    const isField = el => el && (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA');
    const kbdHeight = () => vv ? Math.max(0, window.innerHeight - vv.height - vv.offsetTop) : 0;
    // 🔴 Kutunun yüksekliğini GÖRÜNÜR alana sabitle.
    //   Android'de `vh` klavyeyle küçülmediği için ekran tam boy kalıyor,
    //   gövde de kırpıyordu → alt alanlara ulaşılamıyordu. Yüksekliği
    //   `visualViewport.height` yapınca kutu gerçek bir kaydırma kabına
    //   dönüşüyor; hem otomatik kaydırma hem parmakla kaydırma çalışıyor.
    const setKbdVar = () => {
      scr.style.setProperty('--auth-kbd-h', (kbdHeight() || 300) + 'px');
      if (vv && vv.height) {
        scr.style.setProperty('--auth-vh', Math.round(vv.height) + 'px');
        scr.classList.add('vv-ok');
      }
    };
    const bringIntoView = () => {
      const el = document.activeElement;
      if(!vv || !isField(el) || !scr.contains(el)) return;
      const r = el.getBoundingClientRect();
      // Kutu artık görünür alana sabit → klavyenin üst kenarı = kutunun altı
      const altSinir = vv.height - 16;
      const ustSinir = 12;
      if (r.bottom > altSinir) {
        scr.scrollTop += (r.bottom - altSinir);
      } else if (r.top < ustSinir) {
        scr.scrollTop -= (ustSinir - r.top);
      }
    };
    scr.addEventListener('focusin', (e) => {
      if(!isField(e.target)) return;
      clearTimeout(blurT);
      active = true;
      scr.classList.add('kbd-active');
      document.body.classList.add('auth-kbd-lock');
      setKbdVar();
      // Klavye animasyonu 150-500 ms sürebiliyor; ölçümü birkaç kez tazele
      [120, 300, 550, 850].forEach(ms => setTimeout(() => {
        setKbdVar();
        bringIntoView();
      }, ms));
    });
    scr.addEventListener('focusout', () => {
      clearTimeout(blurT);
      blurT = setTimeout(() => {
        if(isField(document.activeElement) && scr.contains(document.activeElement)) return;
        active = false;
        scr.classList.remove('kbd-active');
        scr.classList.remove('vv-ok');
        document.body.classList.remove('auth-kbd-lock');
        scr.style.removeProperty('--auth-kbd-h');
        scr.style.removeProperty('--auth-vh');
        scr.scrollTop = 0;
      }, 120);
    });
    if(vv){
      vv.addEventListener('resize', () => { if(active){ setKbdVar(); bringIntoView(); } });
      vv.addEventListener('scroll', () => { if(active) setKbdVar(); });
    }
  })();
});

