// 🆕 KL/STB/SB/DOS/OS/SAK/FWD → GK/DEF/MID/FWD (geriye uyumluluk için)
const POS_GROUP = { KL:'GK', STB:'DEF', SB:'DEF', DOS:'MID', OS:'MID', SAK:'MID', SOK:'MID', FWD:'FWD',
  GK:'GK', RB:'DEF', CB:'DEF', LB:'DEF', DM:'MID', CM:'MID', RM:'MID', LM:'MID', AM:'MID', RF:'FWD', LF:'FWD', ST:'FWD' };

// 🆕 ALT MEVKİ SİSTEMİ (12 mevki) — ana grubun (GK/DEF/MID/FWD) ALTINDA.
//   Ana grup hat/yetenek/antrenmanı sürdürür; alt mevki SADECE kayıt seçimi + kart gösterimi.
const SUB_POS = {
  GK:  [{c:'GK', t:'Kaleci'}],
  DEF: [{c:'RB', t:'Sağ Bek'}, {c:'CB', t:'Stoper'}, {c:'LB', t:'Sol Bek'}],
  MID: [{c:'DM', t:'Defansif Orta Saha'}, {c:'CM', t:'Merkez Orta Saha'}, {c:'RM', t:'Sağ Kanat'}, {c:'LM', t:'Sol Kanat'}, {c:'AM', t:'Forvet Arkası'}],
  FWD: [{c:'RF', t:'Sağ Forvet'}, {c:'LF', t:'Sol Forvet'}, {c:'ST', t:'Forvet'}]
};
const SUBPOS_GROUP = { GK:'GK', RB:'DEF',CB:'DEF',LB:'DEF', DM:'MID',CM:'MID',RM:'MID',LM:'MID',AM:'MID', RF:'FWD',LF:'FWD',ST:'FWD' };
const SUBPOS_LABEL = { GK:'Kaleci', RB:'Sağ Bek', CB:'Stoper', LB:'Sol Bek', DM:'Defansif Orta Saha', CM:'Merkez Orta Saha', RM:'Sağ Kanat', LM:'Sol Kanat', AM:'Forvet Arkası', RF:'Sağ Forvet', LF:'Sol Forvet', ST:'Forvet' };
const _OLD2SUB = { KL:'GK', STB:'CB', SB:'RB', DOS:'DM', OS:'CM', SAK:'RM', SOK:'LM', FWD:'ST' };
function subPosOf(p) {
  if (!p) return 'CM';
  const s = p.subPos || p.sub_pos;
  if (s && SUBPOS_GROUP[s]) return s;
  if (_OLD2SUB[p.pos]) return _OLD2SUB[p.pos];
  const g = p.posGroup || p.pos_group || (POS_GROUP[p.pos]) || p.pos;
  return ({ GK:'GK', DEF:'CB', MID:'CM', FWD:'ST' })[g] || 'CM';
}
function subPosGroupOf(sub) { return SUBPOS_GROUP[sub] || 'MID'; }
function subPosClass(p) { return 'pos-' + subPosGroupOf(subPosOf(p)).toLowerCase(); }
// 🆕 MEVKİ-DIŞI OVR CEZASI (diziliş kartı)
function _zoneIdx(z){ return z==='GK'?0 : z==='DEF'?1 : z==='MID'?2 : 3; }
// Ceza çarpanı: kendi alt mevkisi (ownSub) ↔ slot alt mevkisi (slotSub)
function posPenaltyFactor(ownSub, slotSub) {
  if (!ownSub || !slotSub) return 1;
  if (ownSub === slotSub) return 1;                 // tam kendi mevkisi
  const oz = subPosGroupOf(ownSub), sz = subPosGroupOf(slotSub);
  if (oz === sz) return 0.85;                        // aynı bölge, farklı alt mevki → -%15
  const d = Math.abs(_zoneIdx(oz) - _zoneIdx(sz));
  return d === 1 ? 0.80 : d === 2 ? 0.70 : 0.60;     // -%20 / -%30 / -%40
}
// Bir slotta gösterilecek efektif OVR (baz = slot bölgesi yeteneği × ceza çarpanı)
function pitchSlotOvr(p, slotSub) {
  if (!slotSub || !SUBPOS_GROUP[slotSub]) slotSub = (typeof subPosOf === 'function') ? subPosOf(p) : 'CM';
  const base = (p && (p.overall != null ? p.overall : (p.rating || 10))) || 10;  // 🆕 VAR OLAN stored OVR (yeniden hesap YOK); mevki-dışı cezası aşağıda uygulanır
  return Math.max(1, Math.round(base * glSlotCarpan(p, slotSub)));   // 943 — edinilen mevkide ceza yok
}

