// 828 — isteğe başka bir yönetici (kaptan / yardımcı) senden önce karar verdi: kopya güncellenir, kimin verdiği gösterilir
function _jrKararGeldi(msg, msgs, durum, veren) {
  const red = durum === 'rejected';
  msg.offerStatus = red ? 'rejected' : 'approved';
  msg.kararVeren = veren || null;
  msg.read = true;
  if (typeof saveInboxMsgs === 'function') saveInboxMsgs(msgs);
  if (typeof inboxUpdateBadge === 'function') inboxUpdateBadge();
  if (typeof inboxRenderDetail === 'function') inboxRenderDetail(msg);
  showInfoModal({ icon: red ? '❌' : '✅', iconColor: red ? '#ef4444' : '#22c55e',
    title: red ? 'Zaten Reddedildi' : 'Zaten Onaylandı',
    subtitle: veren ? `${veren} senden önce karar verdi.` : 'Bu isteğe başka bir yönetici karar verdi.', body: '' });
}

window.inboxApproveJoinRequest = async function(msgId){
  const msgs = (typeof getInboxMsgs === 'function') ? getInboxMsgs() : null;
  if(!msgs) return;
  const idx = msgs.findIndex(m => m.id === msgId);
  if(idx === -1) return;
  const msg = msgs[idx];
  const d   = msg.joinReqIncomingData;
  if(!d) return;

  if(!d.requestorUserId){
    showInfoModal({
      icon:'⚠️', iconColor:'#f59e0b',
      title:'Eski Format Mesaj',
      subtitle:'Bu istek mesajında kullanıcı ID yok',
      body:'<div class="info-modal-note">Bu istek, sistem güncellemesinden önce gönderilmiş. Oyuncudan yeni istek göndermesini iste.</div>'
    });
    return;
  }

  const captainName = (typeof getTeamRealCaptainName === 'function')
    ? getTeamRealCaptainName(d.countryCode, d.teamName) : 'Kaptan';
  const myUserId = (window.authUser || {}).id;
  if(!myUserId){
    showInfoModal({icon:'⚠️',iconColor:'#f59e0b',title:'Oturum Hazır Değil',subtitle:'Sayfayı yenileyip tekrar deneyin',body:''});
    return;
  }

  // 🆕 Edge Function çağrısı — atomik işlem, RLS bypass
  const SUPABASE_URL = 'https://fkmpkfhikhludkgrzvtd.supabase.co';
  let resData = null;
  try {
    const session = await window.sb.auth.getSession();
    const token = session?.data?.session?.access_token;
    const resp = await fetch(SUPABASE_URL + '/functions/v1/approve-join-request', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': 'Bearer ' + (token || ''),
      },
      body: JSON.stringify({
        requestor_user_id: d.requestorUserId,
        captain_user_id: myUserId,
        country_code: d.countryCode,
        team_name: d.teamName,
        signing_bonus: d.signingBonus || 0,   // 859
        tip: d.tip || null,
        signing_diamond: d.signingDiamond || 0,
        yearly_salary: (d.seasonSalary != null ? d.seasonSalary : (d.yearlySalary || 0)),
        duration_seasons: d.durationSeasons || 1,
        captain_name: captainName,
      })
    });
    resData = await resp.json();
    console.info('[approve] edge function sonuç:', resData);
  } catch(e){
    console.error('[approve] edge function exception:', e);
    showInfoModal({icon:'❌',iconColor:'#ef4444',title:'Bağlantı Hatası',subtitle:'Onay servisi yanıt vermedi',body:'<div class="info-modal-note">İnternet bağlantını kontrol et, tekrar dene.</div>'});
    return;
  }

  if (resData && resData.error === 'already_decided') { _jrKararGeldi(msg, msgs, resData.durum, resData.veren); return; }   // 828
  if(!resData || !resData.ok){
    const errMap = {
      missing_params: { t:'Eksik Bilgi', s:'Form alanlarını kontrol et' },
      captain_not_in_team: { t:'Yetkin Yok', s:'Bu takımın kaptanı değilsin' },
      captain_team_mismatch: { t:'Takım Uyumsuz', s:'Sen artık bu takımın kaptanı değilsin' },
      not_authorized: { t:'Yetki Yok', s:'Sadece kaptan veya yardımcı kaptan onaylayabilir' },
      requestor_not_found: { t:'Oyuncu Bulunamadı', s:'İstek yapan kullanıcı sistemde yok' },
      already_in_team: { t:'Zaten Takımda', s:'Bu oyuncu zaten takımda' },
      insufficient_treasury: { t:'Yetersiz Bakiye', s:`Kasada ${resData.treasury}€, gereken ${resData.needed}€` },
      insufficient_diamond: { t:'Yetersiz Elmas', s:`İmza elması için kasada yeterli elmas yok (mevcut: ${resData.treasury||0} 💎)` },
      roster_full: { t:'Kadro Dolu', s:`${resData.current} / ${resData.max} oyuncu — önce kadroda yer aç` },
      players_update_failed: { t:'Veritabanı Hatası', s:resData.detail || 'Oyuncu kaydı yazılamadı' },
      no_pending_request: { t:'İstek Bulunamadı', s:'Oyuncunun bu takıma bekleyen bir isteği yok (geri çekilmiş, onaylanmış ya da 14 günü geçmiş olabilir)' },
      terms_mismatch: { t:'Şartlar Değişmiş', s:'İsteğin şartları değişmiş. Oyuncudan yeni istek göndermesini iste.' },
      requestor_contract_active: { t:'Sözleşmesi Sürüyor', s:'Oyuncunun başka bir takımla sözleşmesi sürüyor' },
      sozlesmesiz_kabul_yok: { t:'Sözleşmeli Takım', s:'Bu takım sözleşmesiz oyuncu almıyor.' },   // 859
      imza_tavani_asildi: { t:'Hata', s:'İmza bedeli fazla yüksek.' },
    };
    const _mdm = (typeof _mevkiDoluMetin === 'function') ? _mevkiDoluMetin(String(resData.detail || resData.error || '')) : null;   // 686
    const e = /yabanci_dolu/.test(String(resData.detail || resData.error || '')) ? { t:'Yabancı Kontenjanı Dolu', s:'Takımının yabancı oyuncu kontenjanı dolu (10/10).' }
      : _mdm ? { t:'Mevki Kontenjanı Dolu', s:_mdm }
      : errMap[resData.error] || { t:'Hata', s:resData.error || 'Bilinmeyen hata' };
    showInfoModal({icon:'❌',iconColor:'#ef4444',title:e.t,subtitle:e.s,body:''});
    return;
  }

  // BAŞARILI ✅
  // Kaptanın UI'sını güncelle (kasa, inbox, real captains cache)
  msg.offerStatus = 'approved';
  msg.kararVeren = resData.karar_veren || null;   // 828
  msg.read = true;
  if(typeof saveInboxMsgs === 'function') saveInboxMsgs(msgs);
  if(typeof _trsLoadFromServer === 'function') await _trsLoadFromServer();
  if(typeof _inboxLoadFromServer === 'function') await _inboxLoadFromServer();
  if(typeof _invalidateRealCaptainsCache === 'function') _invalidateRealCaptainsCache();
  if(typeof trsSyncHeader === 'function') trsSyncHeader();
  if(typeof inboxUpdateBadge === 'function') inboxUpdateBadge();
  if(typeof inboxRenderDetail === 'function') inboxRenderDetail(msg);
  // 🆕 Kadroyu sunucudan tazele → onaylanan oyuncu kaptanın ekranında ANINDA görünür (sayfa yenilemeye gerek yok)
  if(typeof rosterBuildTeam === 'function' && _userTeam && _userTeam.countryCode){ try{ rosterBuildTeam(_userTeam.countryCode); }catch(e){} }
  if(typeof applyUserTeamUI === 'function') applyUserTeamUI();

  // Toast
  try {
    const fmt = (v) => v >= 1e6 ? (v/1e6).toFixed(2)+'M €' : Math.round(v/1000)+'K €';
    const t = document.createElement('div');
    t.style.cssText = 'position:fixed;bottom:90px;left:50%;transform:translateX(-50%);background:linear-gradient(135deg,#00c853,#43a047);color:#fff;padding:14px 24px;border-radius:24px;font-size:14px;font-weight:700;z-index:9999;font-family:Twemoji Country Flags,"Barlow Condensed",sans-serif;letter-spacing:.4px;box-shadow:0 8px 24px rgba(0,0,0,.4)';
    const _kz = resData.contract || {};   // 859 — kasadan düşen imza parası (💎 + €) sunucunun yazdığı sözleşmeden
    const _dia = Number(_kz.signingDiamond) || 0, _eur = Number(_kz.signingBonus) || 0;
    const _odenen = [_dia > 0 ? `${_dia.toLocaleString('tr')} 💎` : '', _eur > 0 ? `${_eur.toLocaleString('tr')} €` : ''].filter(Boolean).join(' + ');
    t.textContent = _odenen ? `✅ ${resData.requestor_name} takıma katıldı! ${_odenen} kasadan ödendi.`
                            : `✅ ${resData.requestor_name} takıma katıldı!`;
    document.body.appendChild(t);
    setTimeout(() => { t.style.transition='opacity .4s'; t.style.opacity='0'; setTimeout(()=>t.remove(),400); }, 3500);
  } catch(e){}
};


window.inboxRejectJoinRequest = async function(msgId){
  const msgs = (typeof getInboxMsgs === 'function') ? getInboxMsgs() : null;
  if(!msgs) return;
  const msg = msgs.find(m => m.id === msgId);
  const d = msg && msg.joinReqIncomingData;
  if(!d) return;
  const myUserId = (window.authUser || {}).id;
  if(!d.requestorUserId || !myUserId){
    showInfoModal({icon:'⚠️',iconColor:'#f59e0b',title:'Oturum Hazır Değil',subtitle:'Sayfayı yenileyip tekrar deneyin',body:''});
    return;
  }
  // 828 — red de sunucudan: ilk karar geçerli, oyuncuya red mesajını ve diğer yöneticilerin kopyalarını sunucu işler
  let r = null;
  try {
    const session = await window.sb.auth.getSession();
    const token = session?.data?.session?.access_token;
    const resp = await fetch('https://fkmpkfhikhludkgrzvtd.supabase.co/functions/v1/approve-join-request', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + (token || '') },
      body: JSON.stringify({ karar: 'red', requestor_user_id: d.requestorUserId, captain_user_id: myUserId, country_code: d.countryCode, team_name: d.teamName })
    });
    r = await resp.json();
  } catch(e) {
    showInfoModal({icon:'❌',iconColor:'#ef4444',title:'Bağlantı Hatası',subtitle:'Onay servisi yanıt vermedi',body:'<div class="info-modal-note">İnternet bağlantını kontrol et, tekrar dene.</div>'});
    return;
  }
  if (r && r.error === 'already_decided') { _jrKararGeldi(msg, msgs, r.durum, r.veren); return; }
  if (!r || (!r.ok && r.error !== 'no_pending_request')) {   // süresi geçmiş / geri çekilmiş istekte yalnız kopya kapanır
    const e = {
      not_authorized: { t:'Yetki Yok', s:'Sadece kaptan veya yardımcı kaptan onaylayabilir' },
      captain_not_in_team: { t:'Yetkin Yok', s:'Bu takımın kaptanı değilsin' },
      captain_team_mismatch: { t:'Takım Uyumsuz', s:'Sen artık bu takımın kaptanı değilsin' },
    }[r && r.error] || { t:'Bağlantı Hatası', s:'Onay servisi yanıt vermedi' };
    showInfoModal({icon:'❌',iconColor:'#ef4444',title:e.t,subtitle:e.s,body:''});
    return;
  }
  msg.offerStatus = 'rejected';
  msg.kararVeren = (r && r.karar_veren) || null;
  msg.read = true;
  if(typeof saveInboxMsgs === 'function') saveInboxMsgs(msgs);
  if(typeof inboxUpdateBadge === 'function') inboxUpdateBadge();
  if(typeof inboxRenderDetail === 'function') inboxRenderDetail(msg);

  try {
    const t = document.createElement('div');
    t.style.cssText = 'position:fixed;bottom:90px;left:50%;transform:translateX(-50%);background:#ef5350;color:#fff;padding:12px 22px;border-radius:24px;font-size:13px;font-weight:700;z-index:9999;font-family:Twemoji Country Flags,"Barlow Condensed",sans-serif;letter-spacing:.4px;box-shadow:0 8px 24px rgba(0,0,0,.4)';
    t.textContent = `❌ İstek reddedildi.`;
    document.body.appendChild(t);
    setTimeout(() => t.remove(), 2400);
  } catch(e){}
};

// Maç sonu moral güncelleme (processMatchOutcome'dan çağrılır)
function applyMatchMorale(script, userIsHome) {
  if (!script || !script.evs || typeof ROSTER_DATA === 'undefined') return;

  const userSide = userIsHome ? 'home' : 'away';
  const userScore = userIsHome ? (MS.scoreH || 0) : (MS.scoreA || 0);
  const oppScore  = userIsHome ? (MS.scoreA || 0) : (MS.scoreH || 0);
  const matchResult = userScore > oppScore ? 'win' : (userScore < oppScore ? 'loss' : 'draw');

  // Sahaya çıkan top 11 (bench değil) — match etkisi
  const eligible = ROSTER_DATA.filter(p => !isPlayerSuspended(p) && !isPlayerInjured(p));
  const top11 = eligible.sort((a,b) => (b.overall||0) - (a.overall||0)).slice(0, 11);
  const top11Set = new Set(top11.map(p => p.num));

  // Top 11 için sonuç bonusu
  top11.forEach(p => {
    if (matchResult === 'win') adjustMorale(p, 5, 'Galibiyet');
    else if (matchResult === 'loss') adjustMorale(p, -8, 'Mağlubiyet');
    // beraberlik: 0
  });

  // Yedek kalanlar -1 moral
  ROSTER_DATA.forEach(p => {
    if (!top11Set.has(p.num) && !isPlayerSuspended(p) && !isPlayerInjured(p)) {
      adjustMorale(p, -1, 'Yedek kaldı');
    }
  });

  // Olay bazlı moral
  const userEvs = script.evs.filter(e => e.team === userSide);
  userEvs.forEach(ev => {
    // Oyuncu adından eşleştir
    const evPlayer = (ev.player || '').toLowerCase();
    const matched = top11.find(p => {
      const np = (p.name || '').toLowerCase();
      return np === evPlayer || np.startsWith(evPlayer.split(' ')[0]);
    });
    if (!matched) return;

    if (ev.type === 'goal' && !ev.isOwnGoal) adjustMorale(matched, 6, 'Gol attı');
    else if (ev.type === 'yellow') adjustMorale(matched, -3, 'Sarı kart');
    else if (ev.type === 'red') adjustMorale(matched, -10, 'Kırmızı kart');
    else if (ev.type === 'injury') adjustMorale(matched, -8, 'Sakatlandı');
    else if (ev.type === 'save') adjustMorale(matched, 1, 'Kurtarış');

    // Asist
    if (ev.assist && ev.type === 'goal' && !ev.isOwnGoal) {
      const assister = top11.find(p => {
        const np = (p.name || '').toLowerCase();
        const ap = (ev.assist || '').toLowerCase();
        return np === ap || np.startsWith(ap.split(' ')[0]);
      });
      if (assister) adjustMorale(assister, 3, 'Asist yaptı');
    }
  });
}



// 🆕 shortenPlayerName eski isim kısaltma yardımcısı — kart event eşleştirmesi Edge'e
// taşındığı için artık kullanılmıyor (event.player adı doğrudan players tablosuyla eşleşir).

// 🆕 _matchEventPlayer — eski isim eşleştirme yardımcısı, Edge function _processMatchDiscipline
// kullanmıyor (direkt name eşleşmesi). Frontend processMatchOutcome'tan da çıkarıldı.

// Maç sonu: oyuncu istatistiklerini güncelle (moral, stamina, ratings)
// 🆕 Disiplin (kart/sakatlık) Edge function _processMatchDiscipline tarafından işlenir.
// Frontend tarafında ROSTER_DATA in-memory güncellemesi gerekmiyor — bir sonraki
// _loadTeamRosterFromServer ile yeni veri çekilir (sayfa açıldığında veya bootstrap'ta).
function processMatchOutcome(script, userIsHome) {
  if(!script || !script.evs) return;
  if(typeof ROSTER_DATA === 'undefined' || !ROSTER_DATA.length) return;

  // Oyuncu morali güncelle
  if (typeof applyMatchMorale === 'function') {
    try { applyMatchMorale(script, userIsHome); } catch(e) {}
  }

  // Stamina güncelle (yorgunluk düşüşü + dinlenme)
  if (typeof applyMatchStamina === 'function') {
    try {
      // İlk 11'de sahaya çıkanları al
      const userTeam = userIsHome ? curHome : curAway;
      const startersNums = (userTeam && userTeam.players)
        ? userTeam.players.map(p => p.num)
        : [];
      // Sub history'yi MS state'inden topla
      const subs = (MS.subsHistory || []).map(s => ({
        outNum: s.outNum, inNum: s.inNum, minute: s.minute || 60
      }));
      // Strateji
      const strat = (MS.tactic && (userIsHome ? MS.tactic.home : MS.tactic.away))
        ? (userIsHome ? MS.tactic.home.strategy : MS.tactic.away.strategy)
        : null;
      applyMatchStamina(strat, startersNums, subs);
    } catch(e) { console.warn('Stamina uygulanamadı:', e); }
  }

  // 6d) Bireysel maç notları KALDIRILDI — reyting TEK kaynak: Edge (players.match_ratings).
  //   Frontend ratePlayers/_recordMatchToSupabase çift hesap+yazma idi (çakışma+yük), silindi.

  // 🆕 7) MAÇ XP KAZANIMI — kullanıcı oyuncusu için
  try {
    const userPlayer = ROSTER_DATA.find(p => p.role === 'user' && !p.isBot);
    if (userPlayer && !MS._isFriendly) {
      // Maç katılım: 30 XP
      let totalXp = 30;
      let bonuses = [];

      // Kullanıcının kendi olayları (sahaya çıktıysa)
      const meName = userPlayer.name;
      const myEvs = userEvs.filter(ev => {
        const evPlayer = (ev.player || '').toLowerCase();
        return evPlayer === meName.toLowerCase()
            || evPlayer.includes(meName.split(' ')[0].toLowerCase());
      });

      // Gol = +50 XP
      const goals = myEvs.filter(e => e.type === 'goal' && !e.isOwnGoal).length;
      if (goals > 0) { totalXp += goals * 50; bonuses.push(`${goals} gol +${goals*50}XP`); }

      // Asist = +30 XP (e.assist alanı kontrol)
      const assists = userEvs.filter(e =>
        e.assist && e.assist.toLowerCase().includes(meName.split(' ')[0].toLowerCase()) && e.type === 'goal'
      ).length;
      if (assists > 0) { totalXp += assists * 30; bonuses.push(`${assists} asist +${assists*30}XP`); }

      // Galibiyet bonusu = +20 XP
      const userScore = userIsHome ? (MS.scoreH || 0) : (MS.scoreA || 0);
      const oppScore  = userIsHome ? (MS.scoreA || 0) : (MS.scoreH || 0);
      if (userScore > oppScore) { totalXp += 20; bonuses.push('Galibiyet +20XP'); }
      else if (userScore === oppScore) { totalXp += 5; bonuses.push('Beraberlik +5XP'); }

      // Kart cezası (Fix 8: motor 'yellow/red', CFC 'yellowCard/redCard' destekle)
      const yellowCnt = myEvs.filter(e => e.type === 'yellow' || e.type === 'yellowCard').length;
      const redCnt = myEvs.filter(e => e.type === 'red' || e.type === 'redCard').length;
      if (yellowCnt > 0) { totalXp = Math.max(0, totalXp - yellowCnt * 5); }
      if (redCnt > 0) { totalXp = Math.max(0, totalXp - 20); }

      // 🆕 Maç istatistiklerini MS._userStats'e yaz (cft_user_match_log için)
      MS._userStats = {
        goals,
        assists,
        yellowCards: yellowCnt,
        redCards: redCnt,
        played: true,
        xpEarned: totalXp,
      };

      if (totalXp > 0 && typeof rosterAwardXp === 'function') {
        const result = rosterAwardXp(userPlayer.num, totalXp);
        // Maç XP log'u
        try {
          const xpLog = getUserXpLog();
          xpLog.push({
            ts: Date.now(),
            player: meName,
            totalXp,
            bonuses,
            leveled: result.leveled,
            newLevel: result.newLevel,
          });
          saveUserXpLog(xpLog.slice(-50));
        } catch(e) {}

        // İnbox bildirimi (level atladıysa)
        if (result.leveled && typeof getInboxMsgs === 'function') {
          try {
            const inbox = getInboxMsgs();
            inbox.unshift({
              id: 'levelup_' + Date.now(),
              from: '🎯 Antrenör',
              subject: `Seviye ${result.newLevel}'a Yükseldin!`,
              body: `Tebrikler! Maçtaki performansınla ${totalXp} XP kazanarak ${result.newLevel}. seviyeye yükseldin.\n\nKazandığın bonuslar:\n${bonuses.join('\n')}`,
              ts: Date.now(),
              read: false,
              type: 'system'
            });
            saveInboxMsgs(inbox);
            if (typeof inboxUpdateBadge === 'function') inboxUpdateBadge();
          } catch(e) {}
        }
      }
    }
  } catch(e) { console.warn('Maç XP kazanım hatası:', e); }

  // 8) Persist + UI tazele
  if(typeof rosterSavePersist === 'function') rosterSavePersist();
  if(typeof renderRoster === 'function') {
    const rosterEl = document.getElementById('rosterList');
    if(rosterEl) renderRoster(typeof rosterCurrentFilter !== 'undefined' ? (rosterCurrentFilter || 'all') : 'all');
  }
}


