// 🆕 MAÇ İÇİ ANLIK STRATEJİ DEĞİŞİKLİĞİ
const STRAT_GROUP_NAMES = {
  style:   '🎯 Oyun Stili',
  tempo:   '⚡ Tempo',
  attack:  '🏃 Hücum Yönü',
  defense: '🛡️ Defans Hattı',
  press:   '🤝 Pressing',
  shoot:   '🎯 Şut Tercihi',
};

// Strateji parametre değiştir (style, tempo, attack, defense, press, shoot)
function setMatchStrategy(group, value) {
  // 586 — oyun planı boyutu (mentalite, savunma, pas, yon, tempo, mudahale) ya da hazır stil
  if (group === 'stil') tkStil('mac', value); else tkSec('mac', group, value);
}

// Formasyon değiştir
function setMatchFormation(name) {
  if (!MS._tacticControlsActive) {
    showTacticFlash('Bu maçta taktik kontrolü yok!');
    return;
  }
  if (!name || typeof FORMATIONS === 'undefined' || !FORMATIONS[name]) {
    showTacticFlash('Geçersiz formasyon');
    return;
  }

  currentFormation = name;
  const slots = FORMATIONS[name];

  // Maçtaki saha oyuncuları (curHome veya curAway)
  const isUserHome = !!(typeof _userTeam !== 'undefined' && _userTeam && curHome && curHome.name === _userTeam.teamName)
                  || !!(MS && MS._testForceCaptain);
  const _wFm = (typeof _whichSideIsUser === 'function') ? _whichSideIsUser() : null;
  const myTeam = (_wFm && _wFm.myTeam) || (isUserHome ? curHome : curAway);
  // 587 — oyuncular yeni dizilişte KENDİ mevkilerine en yakın yuvalara (Macar yöntemi); eskiden sıra ile
  //   (i. oyuncu → i. yuva) dağıtılıyor, sağ bek orta sahaya, stoper kanada düşebiliyordu.
  const _ata = (myTeam && Array.isArray(myTeam.players) && typeof mkYuvaAta === 'function') ? mkYuvaAta(name, myTeam.players) : null;
  const _yuvaNo = {};
  if (myTeam && myTeam.players && Array.isArray(myTeam.players)) {
    myTeam.players.forEach((p, i) => {
      const k = (_ata && _ata[i] != null) ? _ata[i] : i;
      const slot = slots[k] || slots[0];
      if (slot && p) {
        p.pos = slot.pos; p.x = slot.x; p.y = slot.y; p.slotPos = slot.s; p._slotIdx = k; p.slotIdx = k;
        if (typeof p.num === 'number') _yuvaNo[p.num] = k;
      }
    });
    myTeam._mkFormasyon = name;   // 853
  }
  // activePitchPlayers (maç dizilişi aynası) — aynı oyuncu aynı yuvaya
  if (typeof activePitchPlayers !== 'undefined' && Array.isArray(activePitchPlayers)) {
    activePitchPlayers.forEach((entry, i) => {
      const num = entry && entry.player && entry.player.num;
      const k = (num != null && _yuvaNo[num] != null) ? _yuvaNo[num] : (typeof entry.slotIdx === 'number' ? entry.slotIdx : i);
      const slot = slots[k] || slots[0];
      if (slot) { entry.slotIdx = k; entry.x = slot.x; entry.y = slot.y; entry.pos = slot.pos; entry.s = slot.s; }
    });
  }

  // 584 — kalıcı kayıt yok; yeni diziliş maça gider (yalnız bu maç)
  if (typeof macTaktikGonder === 'function') macTaktikGonder('dizilis');

  // UI güncelle
  refreshQuickStratUI();
  if (typeof updateMatchTacticSummary === 'function') updateMatchTacticSummary();
  renderMatchSubPitch();
  renderMatchSubBench();
  if (typeof renderTacFormationMaps === 'function') renderTacFormationMaps();

  // Bildirim
  showTacticFlash(`📋 Formasyon: ${name}`);

  // 587 — canlı akıştaki "Diziliş değişti" satırı sunucudan gelir (maça işlendiği dakikada)
}

