// 🆕 Maç motoru içinden strateji panelini aç

// 🆕 TEK YETKİ KAYNAĞI — bu maçta taktik müdahalesi yapabilir miyim?
//   Şart: izleyici değil + maçtaki iki takımdan biri benim takımım + rolüm kaptan/yardımcı.
//   (Eskiden drag/sub kodları MS._tacticControlsActive'i koşulsuz true yapıyordu →
//    başkasının maçını izlerken müdahale edilebiliyordu.)
function _msCanControlTactics() {
  try {
    if (typeof MS === 'undefined' || !MS) return false;
    if (MS._spectatorMode) return false;
    // 573 — milli maç: federasyon başkanı (T.D.) ve seçtiği yardımcılar
    if (MS._isNational) return MS._ntTaraf === 'home' || MS._ntTaraf === 'away';
    const ut = (typeof _userTeam !== 'undefined') ? _userTeam : null;
    if (!ut || !ut.teamName) return false;
    if (ut.role !== 'captain' && ut.role !== 'vice') return false;
    const inHome = !!(typeof curHome !== 'undefined' && curHome && (curHome.name === ut.teamName
                  || (curHome.players || []).some(p => p && p.isUser)));
    const inAway = !!(typeof curAway !== 'undefined' && curAway && (curAway.name === ut.teamName
                  || (curAway.players || []).some(p => p && p.isUser)));
    return inHome || inAway;
  } catch(e) { return false; }
}

// İzleyicinin müdahale denemesinde tek tip uyarı
function _msDenyTactic() {
  try { showTacticFlash('👁️ İzleyici modu — bu takımda değişiklik yapamazsın'); } catch(e) {}
  return false;
}

// Maç başında: kullanıcı kaptansa kontrol panelini aktif et, değilse izleyici göster
function initTacticControls() {
  if (!MS.tactic) MS.tactic = {};
  MS.tactic.home = MS.tactic.home || { mentality: 'balanced', formation: '4-3-3' };

  // 🆕 İzleyici modu — kullanıcı yabancı maça izleyici olarak girdi.
  //   Hiçbir kontrol açılmaz, hiçbir takım kontrolü atanmaz.
  const isSpectator = !!(MS && MS._spectatorMode);

  // Kullanıcı bu maçta mı?
  const userInHome = !isSpectator && (!!(curHome && (curHome.players||[]).some(p => p.isUser))
                  || !!(typeof _userTeam !== 'undefined' && _userTeam && curHome && curHome.name === _userTeam.teamName));
  const userInAway = !isSpectator && (!!(curAway && (curAway.players||[]).some(p => p.isUser))
                  || !!(typeof _userTeam !== 'undefined' && _userTeam && curAway && curAway.name === _userTeam.teamName));

  // Kaptan/yardımcı mı?
  const isCaptain = (typeof _userTeam !== 'undefined' && _userTeam &&
                     (_userTeam.role === 'captain' || _userTeam.role === 'vice'));

  // 🎯 Test modu: forceCaptain açıksa kontroller her durumda aktif
  // ❌ İzleyici modunda forceCaptain de geçersiz
  const forceCaptain = !isSpectator && !!(MS && MS._testForceCaptain);
  // 573 — milli maçta kulüp kaptanlığı yetki vermez: yalnız T.D. (federasyon başkanı) ve seçtiği yardımcılar
  const canControl = (MS && MS._isNational)
    ? (!isSpectator && (MS._ntTaraf === 'home' || MS._ntTaraf === 'away'))
    : (forceCaptain || ((userInHome || userInAway) && isCaptain));

  const cap = document.getElementById('tacCaptainPanel');
  const view = document.getElementById('tacViewerPanel');
  if (cap && view) {
    // 🆕 Panel görünür kalır (izleyici sahası onun içine basılıyor) ama yetkisizken
    //   yedek listesi / değişiklik başlıkları / formasyon-strateji sekmeleri GİZLENİR.
    //   Eskiden izleyici hem yedekleri hem çift sahayı görüyordu.
    cap.style.display = 'block';
    cap.classList.toggle('tac-readonly', !canControl);
    view.style.display = canControl ? 'none' : 'flex';
    if (!canControl) {
      // izleyicide her zaman diziliş alt sekmesi açık olsun
      try {
        const _l = document.getElementById('tacSub-lineup');
        const _f = document.getElementById('tacSub-formation');
        const _s = document.getElementById('tacSub-strategy');
        if (_l) _l.style.display = '';
        if (_f) _f.style.display = 'none';
        if (_s) _s.style.display = 'none';
      } catch(e) {}
    }
  }

  // 🆕 Aktif Strateji özetini + hızlı düğmeleri güncelle
  if (typeof updateMatchTacticSummary === 'function') updateMatchTacticSummary();
  if (typeof refreshQuickStratUI === 'function') refreshQuickStratUI();

  // Sub sayısını sıfırla
  MS.subsLeft = 5;

  MS._tacticControlsActive = canControl;
  // 584 — maç taktiği modu: bu maçta yapılan değişiklikler yalnız bu maç (kayıtlı taktik korunur)
  try { if (typeof macTaktikModuAc === 'function') macTaktikModuAc(canControl); } catch(e) {}
}

