function updateScore(team){
  if(team==='home'){
    MS.scoreH++;
    const el=document.getElementById('scoreH');
    el.textContent=MS.scoreH;el.classList.add('pop');
    document.getElementById('homeCrest').classList.add('scoring');
    setTimeout(()=>{el.classList.remove('pop');document.getElementById('homeCrest').classList.remove('scoring');},600);
  }else{
    MS.scoreA++;
    const el=document.getElementById('scoreA');
    el.textContent=MS.scoreA;el.classList.add('pop');
    document.getElementById('awayCrest').classList.add('scoring');
    setTimeout(()=>{el.classList.remove('pop');document.getElementById('awayCrest').classList.remove('scoring');},600);
  }
}

// 574 — CANLI SKOR SENKRONU: skorbord, saatin gösterdiği dakikaya kadarki gollerden hesaplanır
//   ve gol sesi + titreşim skor DEĞİŞTİĞİ AN çalar. Saat 250 ms'de bir ilerler, olaylar 7 sn'lik
//   poll ile gelir; ikisi de bu fonksiyonu çağırır → ses, skor ve olay aynı anda görünür.
//   İlk çağrı (maça ortadan girildi) sessizdir: önceki goller için ses çalmaz.
function _msSkorSenkron(tumu) {
  if (typeof MS === 'undefined' || !MS || MS.finished) return;
  const evs = (MS.script && Array.isArray(MS.script.evs)) ? MS.script.evs : null;
  if (!evs) return;
  const dk = tumu ? 1e9 : ((MS._displayMin && MS._displayMin > 0) ? MS._displayMin : (MS._serverSimMin || 0));
  if (!dk) return;
  let h = 0, a = 0, son = null;
  for (const ev of evs) {
    if (!ev || ev.type !== 'goal' || ev.cancelled === true) continue;
    const m = (ev.min !== undefined ? ev.min : ev.minute) || 0;
    if (m > dk) continue;
    if (!tumu && typeof _g9Tutulu === 'function' && _g9Tutulu(ev)) continue;   // 948 — top ağlara girince sayılır
    if (ev.team === 'home') h++; else if (ev.team === 'away') a++; else continue;
    son = ev;
  }
  const _yaz = (id, crestId, v) => {
    const el = document.getElementById(id); if (!el || el.textContent === String(v)) return false;
    const artti = Number(el.textContent) < v;
    el.textContent = v;
    if (artti && MS._skorGorulen !== undefined) {
      el.classList.add('pop');
      const cr = document.getElementById(crestId); if (cr) cr.classList.add('scoring');
      setTimeout(() => { el.classList.remove('pop'); if (cr) cr.classList.remove('scoring'); }, 600);
    }
    return true;
  };
  _yaz('scoreH', 'homeCrest', h); _yaz('scoreA', 'awayCrest', a);
  MS.scoreH = h; MS.scoreA = a;
  if (MS.script) { MS.script.homeGoals = h; MS.script.awayGoals = a; }
  const toplam = h + a;
  if (MS._skorGorulen !== undefined && toplam > MS._skorGorulen && son) {
    try { showGoal(son.player || 'Oyuncu', Math.floor(son.min || son.minute || 0)); } catch(e) {}
    try { _gmGolAni(son.team); } catch(e) {}
  }
  MS._skorGorulen = toplam;
  try { _gmGolculer(tumu ? null : dk); } catch(e) {}
}

