function updateClock(min){
  const el=document.getElementById('matchClock');
  // 🆕 Uzatma göstergesi — 90+ dakika veya extraTime olayı varsa saatin yanında UZT
  try {
    if (el) {
      const _evs = (MS && MS.script && Array.isArray(MS.script.evs)) ? MS.script.evs : [];
      const _mn = Math.floor((MS && (MS._displayMin || MS.minute)) || 0);
      const _et = (typeof _msExtraTimeBadge === 'function') ? _msExtraTimeBadge(_evs, _mn) : '';
      el.setAttribute('data-et', _et ? '1' : '0');
      if (_et && el.querySelector && !el.querySelector('.ms-et-badge')) el.insertAdjacentHTML('beforeend', _et);
      if (!_et && el.querySelector) { const _b = el.querySelector('.ms-et-badge'); if (_b) _b.remove(); }
    }
  } catch(e) {}
  const badge=document.getElementById('statusBadge');
  if(min===0){el.textContent="0'";el.className='match-clock';badge.className='status-badge sb-live';badge.innerHTML='<div class="live-dot"></div> CANLI';}
  else if(min===45 && MS && MS.inHalftime){el.textContent='HT';el.className='match-clock ht';badge.className='status-badge sb-ht';badge.innerHTML='⏸ DEVRE ARASI';}
  else if(min>=90){el.textContent='FT';el.className='match-clock ft';badge.className='status-badge sb-ft';badge.innerHTML='✔ TAM SÜRÜ';}
  else{
    el.textContent=min+"'";el.className='match-clock';
    // 🆕 2. yarı başında badge hâlâ HT'de takılı kaldıysa CANLI'ya çevir
    if(badge && badge.className.indexOf('sb-ht')!==-1){
      badge.className='status-badge sb-live';
      badge.innerHTML='<div class="live-dot"></div> CANLI';
    }
  }
}

