// STATE ŞEMASI:
//   {
//     schemaVersion: 1,
//     bot_promrel:      { [seasonNum]: { [cc]: [{tier, teamNames[]}] } },
//     final_standings:  { [seasonNum]: { [cc]: [name1..name6] } },
//     // Gelecekteki uzantılar için yer ayrıldı:
//     // team_ratings:  { [teamName]: rating },
