  const dol = s => s.replace(/\{(\w+)\}/g, (_, k) => t[k] != null ? t[k] : '');
  const tek = (a, on) => { let i = h % a.length; h = Math.imul(h ^ (h >>> 15), 2246822519) >>> 0;
    for (let n = 0; n < a.length && kullanilan.has(on + i); n++) i = (i + 1) % a.length;
    kullanilan.add(on + i); return a[i]; };
