  const s3i = h % _CN_ROP.s3.length; h = Math.imul(h ^ (h >>> 13), 3266489917) >>> 0;
  const h3 = s3i === 1 ? _CN_ROP.c3.taraftar : (t.avrupa ? _CN_ROP.c3.avrupa.concat(_CN_ROP.c3.zirve) : t.tier > 1 ? _CN_ROP.c3.alt : _CN_ROP.c3.zirve);
  const sorular = [{ s: dol(s1), c: dol(c1) }, { s: dol(q2.s), c: dol(sec(q2.c)) }, { s: dol(_CN_ROP.s3[s3i]), c: dol(sec(h3)) }];
