  const ust = `<div class="cn-bas">
      <div class="cn-ust"><button class="cn-geri" onclick="goBackPage()" aria-label="Geri">${_CN_IK.geri}</button><img class="cn-logo" src="csc-news-logo.webp?v=748" alt="CSC News">
        <span class="cn-tarih"><b>${info.preSeason ? 'Sezon <span>Başlıyor</span>' : `Sezon <span>${info.season}</span> · Gün ${info.dayInSeason}`}</b><i>${_cnEsc(formatTrDate(new Date()))}</i></span></div>
      <div class="cn-sekmeler"><button class="cn-sk${_cnSekme === 'global' ? ' on' : ''}" onclick="cnSekmeSec('global')">GLOBAL</button><button class="cn-sk${_cnSekme === 'ulusal' ? ' on' : ''}" onclick="cnSekmeSec('ulusal')">ULUSAL</button></div>
    </div>`;
  if (!_cnVeri) { _cnYaz(pg, ust + `<div id="cnCanli">${_cnCanliHtml()}</div><div id="cnAa" data-k="cn-aa">${_cnAaHtml()}</div><div class="cn-ic">${_cnIskelet()}</div>`, yerinde); return; }
  const ulusal = _cnSekme === 'ulusal';
  const blok = ulusal ? _cnVeri.u : _cnVeri.g;
  const ek = _cnEkler = (blok && blok.ek) || {};
  // 769 — Haber ömrü 3 gün: son 24 saatin haberleri manşette, daha eskiler alt başlıklarda, 3 günü dolan gösterilmez
  const simdi = Date.now(), birGun = simdi - 864e5, ucGun = simdi - 3 * 864e5, taze = z => Number(z) > ucGun;
  _cnRop = _cnRopHazirla(_cnRopSec((ek.rop || []).filter(r => Number(r.z) > birGun), simdi));   // 776
  {   // 958 — RAM: artık gösterilmeyen röportaj sahneleri (her biri 1112×1240 ≈ 5,5 MB) bırakılır.
      //   İki sekmenin güncel röportajları kalır (sekme değişince sahne eskisi gibi beklemeden görünür).
    const _o = ulusal ? _cnVeri.g : _cnVeri.u, _tut = new Set(_cnRop.map(o => String(o.r.id)));
    try { _cnRopSec(((_o && _o.ek && _o.ek.rop) || []).filter(r => Number(r.z) > birGun), simdi).forEach(r => _tut.add(String(r.id))); } catch (e) {}
    for (const id in _cnSahne) if (!_tut.has(id)) { _cnSahne[id].width = 0; delete _cnSahne[id]; }
  }
  const liste = ((blok && blok.h) || []).filter(h => taze(h.z) && !_cnUzHaber(h)).map(h => ({ h, x: _cnHaber(h) })).filter(o => o.x);   // 883
  if (!liste.length && !(blok && blok.l && blok.l.length) && !Object.keys(ek).length && !(_cnVeri.g && _cnVeri.g.ek && (_cnVeri.g.ek.kup || _cnVeri.g.ek.kura2))) {   // 852 — kupa/kura paketi globalde
    _cnYaz(pg, ust + `<div class="cn-ic"><div class="cn-bos"><img src="csc-news-logo.webp?v=748" alt=""><span>Henüz haber yok</span></div></div>`, yerinde);
    return;
  }
  // Manşet sırası (önem): özel haber (kulüp satın alma) · milli takım · Avrupa (en önemli 2–3 haber tek tabloda) · lig · alt ligler · istatistik · röportajlar
  // 769 — manşette yalnız son 24 saatin haberleri; aynı konuda yeni haber gelince eskisi kalkar
  const guncel = _cnGuncel(liste), yeni = o => o.h.z > birGun, onIki = simdi - 12 * 36e5;
  // 782 — maç haberi manşette 12 saat; ligde yalnız liderin puan kaybı ve zirve maçı
  const ligMac = guncel.filter(o => o.h.t === 'mac' && !o.h.k && (o.h.tier || 1) === 1 && o.h.z > onIki && (o.h.n || []).some(x => x === 'lider' || x === 'zirve'))[0];
  const kul = new Set(), sl = [];
  const ropKisi = new Set(_cnRop.map(o => o.r.ad + '|' + o.r.yt));
  const ropMu = o => (o.h.t === 'transfer' || o.h.t === 'imza') && ropKisi.has(o.h.ad + '|' + o.h.yt);
  const onemli = l => l.sort((a, b) => _cnOnem(b.h) - _cnOnem(a.h) || b.h.z - a.h.z);
  // 838 — kupa finali manşetin başında: maçtan önce "final bu akşam", sürerken canlı skor; bitince yerine sonucu (12 saat)
  const fin = _cnFinaller(); _cnFinalSon = _cnFinalImza(fin);
  fin.forEach(f => sl.push(_cnFinalSlayt(f)));
  // 851 — takvim gündemi: EURO döneminde EURO masası, transfer penceresinde transfer masası en önde (kupa finali yine başta)
  const gd = _cnGundem(), kulYz = new Set();
  if (gd.ys) { const y = _cnYsSlayt(gd, ulusal); if (y) sl.push(y); }   // 896
  if (gd.fedOn) { const f = _cnFedOnSlayt(ulusal); if (f) sl.push(f); }   // 896
  const ekG = (_cnVeri.g && _cnVeri.g.ek) || {};   // 852 — kupa ve kura paketi globalde gelir, iki sekme de onu okur
  const A = gd.euro && ek.enc && Array.isArray(ek.enc.m) ? _cnEncAnaliz(ek.enc) : null;
  const trG = gd.transfer && _cnTrPencere() && ek.tr && taze(ek.tr.z) && ek.tr.n > 0 ? ek.tr : null;
  const eM = A ? _cnEncManset(A, ulusal, kulYz) : { ilk: [], son: [], mr: new Set() };
  // 852 — Avrupa kupaları masası (play-off, gruplar, eleme turları, finaller), federasyon seçimi (1–6. gün), EURO kurası (17–19. gün)
  const KP = gd.kup && ekG.kup && ekG.kup.k ? Object.keys(ekG.kup.k).map(k => _cnKpAnaliz(k, ekG.kup.k[k])).filter(x => x.m.length || x.gm.length)
    .sort((a, b) => _CN_KP[b.k].sira - _CN_KP[a.k].sira) : [];
  const kpSet = new Set(KP.map(x => x.k)), kpM = KP.length ? _cnKpManset(KP, ulusal, kulYz, new Set(fin.map(([m]) => m.k))) : { ilk: [], son: [], mr: new Set() };
  const fedSl = gd.fed && ek.fed ? _cnFedSlayt(ek.fed, ulusal) : '';
  const kuraSl2 = gd.kura && ekG.kura2 && Array.isArray(ekG.kura2.gr) ? _cnKuraSlaytlari(ekG.kura2, ulusal) : [];
  kuraSl2.forEach(s => sl.push(s));
  if (fedSl && gd.d <= 4) sl.push(fedSl);
  eM.ilk.forEach(s => sl.push(s));
  kpM.ilk.forEach(s => sl.push(s));
  if (fedSl && gd.d > 4) sl.push(fedSl);
  if (trG) sl.push(_cnTrSlayt(trG, ulusal, kulYz));
  eM.son.forEach(s => sl.push(s));
  kpM.son.forEach(s => sl.push(s));
  // Masanın yazdığı kupa maçları ve tur haberleri tekrar edilmez; final raporu varsa şampiyonluk haberi de
  const kpFinal = new Set(KP.filter(x => x.bit.some(m => m.f === 'final' && Date.now() - m.z < 864e5)).map(x => x.k));
  const kpMi = o => !!o.h.k && kpSet.has(o.h.k) && (o.h.t === 'mac' || o.h.t === 'ko' || (o.h.t === 'kupa' && kpFinal.has(o.h.k)));
  guncel.forEach(o => { if (kpMi(o)) kul.add(o); });
  onemli(guncel.filter(o => o.h.t === 'kupa' && !kul.has(o) && o.h.z > onIki && !fin.some(([m]) => m.k === o.h.k))).slice(0, 2)
    .forEach(o => { sl.push(_cnMansetHtml(o.h, o.x)); kul.add(o); });
  // 838 — sezon sonu: şampiyonlar (ulusal: üst lig manşette, alt ligler bölümde · global: en güçlü 3 lig manşette)
  const ssB = _cnSsBlok(ulusal), spL = ssB && Array.isArray(ssB.samp) ? ssB.samp.filter(x => x && x.w && taze(x.z)) : [];
  const spM = spL.filter(x => x.z > birGun && (!ulusal || (x.tier || 1) === 1)).slice(0, ulusal ? 1 : 3);
  if (spL.some(x => (x.tier || 1) === 1)) guncel.forEach(o => { if (o.h.t === 'ligsamp') kul.add(o); });   // yerini kutlama haberi alır
  // 755 — Özel haber (kulüp satın alma): en fazla 3 kulüp tek manşette
  const alimM = guncel.filter(o => o.h.t === 'alim' && yeni(o)).slice(0, 3);
