  const kura = ek.kura && taze(ek.kura.z) ? ek.kura : null, kuraYeni = !!kura && kura.z > birGun;
  let milliO = A ? null : onemli(guncel.filter(o => !kul.has(o) && o.x.ms && (o.h.t === 'milli' || o.h.k === 'enc') && yeni(o)))[0];   // 851 — EURO masası açıkken yerini EURO manşetleri alır
  if (milliO && kuraYeni && kura.z > milliO.h.z) milliO = null;
  const kuraSl = !milliO && kuraYeni && !kuraSl2.length;   // 852 — kura günlerinde yerini analiz alır
  if (milliO) { sl.push(_cnMansetHtml(milliO.h, milliO.x)); kul.add(milliO); }
  else if (kuraSl) sl.push(_cnKuraSlayt(kura));
  // 773 — milli takıma çağrılanlar (son 24 saat) · 819: her oyuncu kendi manşet sayfasında (en yeni önce, en çok 3);
  //   daha fazlası varsa kalanlar bir sayfada toplu
  const mc = (Array.isArray(ek.mc) ? ek.mc : []).filter(m => m && m.cc && taze(m.z)).sort((a, b) => b.z - a.z);
  const mcY = mc.filter(m => m.z > birGun);
  mcY.slice(0, 3).forEach(m => sl.push(_cnCagriSlayt([m])));
  if (mcY.length > 3) sl.push(_cnCagriSlayt(mcY.slice(3)));
  // 787 — federasyon: ulusalda seçim / yeni başkan, globalde seçimlerin başlaması
  const fedM = fedSl ? null : guncel.find(o => (o.h.t === 'fedbaskan' || o.h.t === 'fedsecim') && yeni(o) && (ulusal || !o.h.cc));   // 852 — federasyon masası varken o yazar
  if (fedM) { sl.push(_cnMansetHtml(fedM.h, fedM.x)); kul.add(fedM); }
  if (fedSl) guncel.forEach(o => { if ((o.h.t === 'fedbaskan' || o.h.t === 'fedsecim') && (ulusal ? o.h.cc === _cnUlkeKod || !o.h.cc : !o.h.cc)) kul.add(o); });
  const av = onemli(guncel.filter(o => !kul.has(o) && (((o.h.t === 'ko' || o.h.t === 'kupa') && o.h.k !== 'enc' && yeni(o)) || (o.h.t === 'mac' && o.h.k && o.h.z > onIki)))).slice(0, 3);
  if (av.length) { sl.push(av.length > 1 ? _cnAvrupaSlayt(av) : _cnMansetHtml(av[0].h, av[0].x)); av.forEach(o => kul.add(o)); }
  if (spM.length) spM.forEach(x => sl.push(_cnSpSlayt(x, !ulusal)));   // 838
  else if (ulusal) {
    const l = guncel.find(o => !kul.has(o) && (o.h.t === 'lider' || o.h.t === 'ligsamp') && yeni(o));
    if (l) { sl.push(_cnMansetHtml(l.h, l.x)); kul.add(l); }
  } else if (ek.lig && ek.lig.z > birGun) sl.push(_cnLigSlayt(ek.lig, true));
