  if (ulusal && ek.alt && ek.alt.z > birGun && !spL.some(x => (x.tier || 1) > 1)) sl.push(_cnLigSlayt(ek.alt, false));   // 838 — alt lig şampiyonları bölümde
  const kral = _cnKralVeri(), ssSon = spL.length > 0;   // 838 — sezon bitince krallıklar manşetin son sayfalarında
