    + (ulusal && ek.ss && taze(ek.ss.z) ? bolum('SEZON SONU', _CN_KAT.sezon[1], _cnSezonSonuHtml(ek.ss)) : '')
    + bolum('AVRUPA', '#60a5fa', haberler(G.avrupa))
