    + bolum('MİLLİ TAKIM', '#f87171', (ulusal && kura && !kuraSl ? _cnKuraKart(kura) : '') + haberler(G.milli))
    + (gd.transfer ? '' : trBol)
    + bolum('TOPLULUK', '#fb7185', (yaris ? _cnYarisKart(yaris) : '') + haberler(G.topluluk));
  _cnYaz(pg, ust
    + `<div id="cnCanli">${_cnCanliHtml()}</div>`
    + `<div id="cnAa" data-k="cn-aa">${_cnAaHtml()}</div>`   // 900
    + `<div class="cn-ic">${_cnKarusel(sl)}${govde}</div>`, yerinde);
  const kar = pg.querySelector('.cn-kar-ic');
  if (kar) _cnKarNokta(kar);
  const stad = document.getElementById('hmStadBg');
