function goBackPage(){
  if (typeof _visitedPlayerData !== 'undefined' && _visitedPlayerData && typeof exitVisitorMode === 'function') { exitVisitorMode(); return; }
  // 735 — misafir takım sayfasında Geri: misafir modundan çık (girilmeden önceki sayfaya)
  if (typeof _viewingTeam !== 'undefined' && _viewingTeam && document.getElementById('page-team').classList.contains('active')) { exitGuestMode(); return; }
  try {
    const h = window._pageHist || [];
    let prev = null;
    while (h.length) { const p = h.pop(); if (p) { prev = p; break; } }
    window._navBack = true;
    if (prev) showPage(prev, (typeof findNavBtn==='function') ? findNavBtn(prev) : null);
    else showPage('home', (typeof findNavBtn==='function') ? findNavBtn('home') : null);
    window._navBack = false;
  } catch(e){ try{ showPage('home'); }catch(_){} }
}
