// Türkçe → ASCII normalize (ç→c, ğ→g, ı→i, ö→o, ş→s, ü→u, İ→i, vs)
function _trToAscii(s) {
  const map = {'ç':'c','Ç':'c','ğ':'g','Ğ':'g','ı':'i','I':'i','İ':'i','ö':'o','Ö':'o','ş':'s','Ş':'s','ü':'u','Ü':'u'};
  return String(s || '').split('').map(c => map[c] || c).join('')
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
}
// Takım adından slug (URL-safe)
function _teamSlug(name) {
  return _trToAscii(name).replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
}
// Takım için logo key (cc-slug)
function _teamLogoKey(team) {
  if (!team) return null;
  const cc = (team.countryCode || team.cc || team.countryKey || '').toLowerCase();
  const slug = _teamSlug(team.name || '');
  if (!cc || !slug) return null;
  return cc + '-' + slug;
}
// 916 — LOGO BELLEK ÖNBELLEĞİ: bir kez inip çözülen logo yeniden çizimde beklemeden (lazy/async olmadan) aynı karede basılır.
//   Eskiden her çizimde yeni bir "lazy" resim doğuyor, gelene kadar kutu boş kalıyordu (çerçeve/renk de kaldırıldığı için bomboş).
const _lgHazir = new Set(), _lgTut = [];
function _lgOk(img) {
  try {
    if (!img || !(img.naturalWidth > 0)) return;
    const u = img.getAttribute('src'); if (u) _lgHazir.add(u);
    const p = img.parentNode; if (p && p.classList) p.classList.remove('lg-bekle');
  } catch (e) {}
}
window._lgOk = _lgOk;
function _lgIndir(u) {
  return new Promise(function (r) {
    try {
      const im = new Image();
      _lgTut.push(im); if (_lgTut.length > 400) _lgTut.shift();
      im.onload = function () { (im.decode ? im.decode() : Promise.resolve()).catch(function () {}).then(function () { _lgHazir.add(u); r(); }); };
      im.onerror = function () { r(); };
      im.src = u;
    } catch (e) { r(); }
  });
}
// Açılış ekranı kalkmadan ana sayfadaki logolar istenir ve çözülür — en çok ms beklenir (açılışın kalkışı zaten ~1 sn sürer)
function _lgAnaSayfa(ms) {
  try {
    const ps = [], gor = new Set();
    document.querySelectorAll('#page-home img[src*="/team-logos/"]').forEach(function (im) {
      try { if (im.loading === 'lazy') im.loading = 'eager'; } catch (e) {}
      const u = im.getAttribute('src');
      if (!u || gor.has(u) || _lgHazir.has(u)) return;
      gor.add(u); ps.push(_lgIndir(u));
    });
    if (!ps.length) return Promise.resolve();
    return Promise.race([Promise.all(ps), new Promise(function (r) { setTimeout(r, ms || 600); })]);
  } catch (e) { return Promise.resolve(); }
}
window._lgAnaSayfa = _lgAnaSayfa;
// 949 — ana sayfadaki diğer resimler (logolar hariç) açılışta iner ve çözülür; kaydırırken inip takılmaz
function _hmResimHazir() {
  try {
    const ps = [];
    document.querySelectorAll('#page-home img').forEach(function (im) {
      const u = im.getAttribute('src') || ''; if (!u || u.indexOf('/team-logos/') !== -1) return;
      try { if (im.loading === 'lazy') im.loading = 'eager'; } catch (e) {}
      const coz = function () { return im.decode ? im.decode().catch(function () {}) : null; };
      ps.push(im.complete ? coz() : new Promise(function (r) { im.addEventListener('load', r, { once: true }); im.addEventListener('error', r, { once: true }); }).then(coz));
    });
    return Promise.all(ps);
  } catch (e) { return Promise.resolve(); }
}
// 949 — futbolcu odası resmi çizilene kadar (kart yoksa beklemez)
async function _oySahneBekle(ms) {
  try {
    if (typeof authUser === 'undefined' || !authUser || !document.getElementById('oyKart')) return;
    const t = Date.now();
    while (!window._oySahneSoz && !_oySahneImza && Date.now() - t < ms) await new Promise(function (r) { setTimeout(r, 50); });
    if (window._oySahneSoz) await window._oySahneSoz;
  } catch (e) {}
}
// Takım için logo URL (varsa) — yoksa null (caller eski badge'i göstermeli)
var _tlOnb958 = null;
function teamLogoUrl(team) {
  // 958 — sonuç yalnız ülke kodu + ada bağlı: (ülke, ad) başına önbellek (her rozette ad normalize ediliyordu)
  const _c958 = team ? (team.countryCode || team.cc || team.countryKey || '') : null;
  const _k958 = (typeof _c958 === 'string') ? _c958 + '\u0001' + String(team.name || '') : null;
  const _o958 = _tlOnb958 || (_tlOnb958 = new Map());
  if (_k958 !== null && _o958.has(_k958)) return _o958.get(_k958);
  const key = _teamLogoKey(team);
  const _r958 = (!key || !TEAM_LOGO_SET.has(key)) ? null : TEAM_LOGO_BASE + key + '.webp';
  if (_k958 !== null) { if (_o958.size > 20000) _o958.clear(); _o958.set(_k958, _r958); }
  return _r958;
}
// Takım badge HTML'i — logo varsa logo, yoksa renkli kısa-isim badge'i.
// sizePx = badge boyutu (square). Caller container'a yerleştirir.
function teamBadgeHTML(team, sizePx) {
  const s = sizePx || 28;
  const url = teamLogoUrl(team);
  if (url) {
    return `<div class="tm-badge tm-badge-logo" style="width:${s}px;height:${s}px"><img src="${url}" alt=""${_lgHazir.has(url) ? '' : ' loading="lazy" onload="_lgOk(this)"'}></div>`;
  }
  const bg = (team && team.bg) || '#333';
  const tc = (team && team.tc) || '#fff';
  const short = (team && team.short) || '?';
  const fontSize = Math.max(8, Math.round(s * 0.36));
  return `<div class="tm-badge tm-badge-text" style="width:${s}px;height:${s}px;background:${bg};color:${tc};font-size:${fontSize}px">${short}</div>`;
}
// Inline badge HTML — render edilen string template'lerde kullanılır.
// Render eden yerler team objesini veya {name, bg, tc, short} verilerini geçer.
// Logo varsa <img> ile gösterir + parent'a crest-has-logo class ekler (CSS çerçeveyi kaldırır).
function inlineBadge(opts) {
  const tag = opts.tag || 'span';
  const cls = opts.cls || '';
  let team = opts.team;
  // Team objesi yoksa name'den bul (cc verilmişse o ülkeyle eşle — aynı isimli takımlar karışmasın)
  if (!team && opts.name) {
    const wantCc = (opts.cc || '').toUpperCase();
    const _e958 = _tmBul(wantCc ? 'buyuk' : 'genel', wantCc, opts.name);   // 958 — takım dizini (ilk eşleşme aynı)
    if (_e958 !== undefined) { if (_e958) team = _e958.t; }
    else for (const cc of _cftGetCountryCodes()) {
      if (wantCc && String(cc).toUpperCase() !== wantCc) continue;
      for (const lg of (_cftGetCountry(cc).leagues || [])) {
        const t = (lg.teams || []).find(x => x.name === opts.name);
        if (t) { team = t; break; }
      }
      if (team) break;
    }
  }
  const bg = (team && team.bg) || opts.bg || '#333';
  const tc = (team && team.tc) || opts.tc || '#fff';
  const short = (team && team.short) || opts.short || '?';
  const url = team ? teamLogoUrl(team) : null;
  if (url) {
    // Logo dosyası storage'da yoksa renkli kısa-isim rozetine düş (kırık img gösterme)
    const sh = String(short).replace(/['\\]/g, '');
    const fb = `var p=this.parentNode;p.classList.remove('crest-has-logo');p.style.background='${bg}';p.style.color='${tc}';p.textContent='${sh}'`;
    const _hz = _lgHazir.has(url);   // 916
    return `<${tag} class="${cls} crest-has-logo${_hz ? '' : ' lg-bekle'}"><img src="${url}" alt=""${_hz ? '' : ' loading="lazy" decoding="async" onload="_lgOk(this)"'} onerror="${fb}"></${tag}>`;
  }
  return `<${tag} class="${cls}" style="background:${bg};color:${tc}">${short}</${tag}>`;
}

// Mevcut bir crest <div>'inin içeriğini set eder: logo varsa <img>, yoksa renkli short text.
// Mevcut setCrest local fonksiyonlarının tek doğru implementasyonu.
function applyCrestToEl(el, name, shortTxt) {
  if (!el) return;
  let team = null;
  const _e958 = _tmBul('genel', null, name);   // 958 — takım dizini (ilk eşleşme aynı)
  if (_e958 !== undefined) team = _e958 ? _e958.t : null;
  else for (const cc of _cftGetCountryCodes()) {
    for (const lg of (_cftGetCountry(cc).leagues || [])) {
      const t = (lg.teams || []).find(x => x.name === name);
      if (t) { team = t; break; }
    }
    if (team) break;
  }
  const logoUrl = team ? teamLogoUrl(team) : null;
  if (logoUrl) {
    // 🆕 Aynı logo zaten basılıysa <img>'i YENİDEN YARATMA → blink (kaybol/gel) önlenir.
    //   İçeriği yazıya çevirmiş çağrılarda (örn. guestRenderHeader) img child olmaz → normal basar.
    const _cur = el.firstElementChild;
    if (_cur && _cur.tagName === 'IMG' && _cur.getAttribute('src') === logoUrl) {
      el.classList.add('crest-has-logo');
      return;
    }
    // 🆕 Logo varsa parent'a crest-has-logo class — çerçeve/background CSS ile kaldırılır
    el.classList.add('crest-has-logo');
    const _hz = _lgHazir.has(logoUrl);   // 916 — inmiş logo beklemeden; inmemişse silik yer tutucu, gelince kalkar
    if (_hz) el.classList.remove('lg-bekle'); else el.classList.add('lg-bekle');
    el.innerHTML = `<img src="${logoUrl}" alt="" style="width:100%;height:100%;object-fit:contain;display:block"${_hz ? '' : ' loading="lazy" onload="_lgOk(this)"'}>`;
    return;
  }
  // Logo yok → eski renkli badge
  el.classList.remove('crest-has-logo'); el.classList.remove('lg-bekle');
  el.textContent = shortTxt;
  if (team) {
    el.style.background = team.bg || 'var(--bg3)';
    el.style.color = team.tc || '#fff';
  }
}

