// ──────── Lig adından ülke bayrağı bulma ────────
function getLeagueFlag(leagueName) {
  if (!leagueName || false) return '';
  for (const code of _cftGetCountryCodes()) {
    const country = _cftGetCountry(code);
    if (country && country.leagues && Array.isArray(country.leagues)) {
      if (country.leagues.some(l => l.name === leagueName)) {
        return country.flag || '';
      }
    }
  }
  return '';
}

// ═══════════════════════════════════════════════════════════════════
//  LİG KADEME ADLARI — TEK KAYNAK
//  Kural (tier 1 TABANLI):
//     tier 1 → Süper Lig
//     tier 2 → 1. Lig
//     tier 3 → 2. Lig
//     tier 4 → 3. Lig   … yani tier ≥ 2 için (tier - 1) + ". Lig"
//
//  ⚠️ Buradaki fonksiyon eskiden bir IIFE idi ve `if(false) return;`
//     satırı olmasa bile hiç işe yaramıyordu: script çözümlenirken
//     ANINDA çalışıyor, oysa ülke/lig verisi `bootstrapWorld()` ile
//     ÇOK SONRA yükleniyordu. Yani _cftDb o an bomboştu ve döngü
//     hiç dönmüyordu. Artık bootstrapWorld verileri yükledikten
//     HEMEN SONRA çağrılıyor.
// ═══════════════════════════════════════════════════════════════════
function _ligTierEtiketi(tier){
  const t = Number(tier);
  if (!isFinite(t) || t <= 1) return 'Süper Lig';
  return (t - 1) + '. Lig';
}
window._ligTierEtiketi = _ligTierEtiketi;

function _ligAdlariniDuzelt(){
  let duzeltilen = 0;
  try {
    for (const code of _cftGetCountryCodes()){
      const country = _cftGetCountry(code);
      if(!country || !Array.isArray(country.leagues)) continue;
      // Dizi sırası = kademe sırası olsun (bazı yerler leagues[idx] ile eriyor)
      country.leagues.sort((a,b) => (Number(a && a.tier)||0) - (Number(b && b.tier)||0));
      country.leagues.forEach((lg, idx) => {
        if(!lg) return;
        const tier = Number.isFinite(Number(lg.tier)) ? Number(lg.tier) : (idx + 1);
        lg.tier = tier;
        const dogru  = _ligTierEtiketi(tier);
        const mevcut = String(lg.name || '').trim();
        if (!mevcut){ lg.name = dogru; duzeltilen++; return; }
        // SADECE standart kalıptaki adları düzeltiriz ("2. Lig", "Türkiye 1. Lig",
        // "Süper Lig" gibi). Özel/elle verilmiş bir isim varsa dokunmayız.
        const m = /^(.*?)\s*(S[üu]per\s*Lig|\d+\.\s*Lig)\s*$/i.exec(mevcut);
        if (!m) return;
        const onek = (m[1] || '').trim();
        const yeni = onek ? (onek + ' ' + dogru) : dogru;
        if (yeni !== mevcut){ lg.name = yeni; duzeltilen++; }
      });
    }
  } catch(e){}
  if (duzeltilen) console.info('[lig] kademe adı düzeltildi:', duzeltilen);
  return duzeltilen;
}
window._ligAdlariniDuzelt = _ligAdlariniDuzelt;

const LG_REGIONS = {
  west:['EN','IE','SC','FR','DE','NL','BE','AT','CH'],
  east:['PL','CZ','SK','HU','RO','BG','UA','RS','HR'],
  north:['SE','NO','DK','FI'],
  south:['ES','IT','PT','GR','AL'],
  other:['TR','RU','AZ','KZ','IL']
};
const LG_COLORS = ['#ffd600','#00b0ff','#00e676','#ff6d00','#ab47bc','#78909c'];

let lgFilter_cur = 'all';
let lgCurrentTeam = null;
let lgUserTeam = null;

// 🆕 lgUserTeam artık _userTeam RAM cache'inden alınır (Supabase tek kaynak)
try{ if (typeof _userTeam !== 'undefined' && _userTeam) lgUserTeam = _userTeam; }catch(e){}

function lgRatColor(r){ return r>=85?'#ffd600':r>=75?'#00e676':r>=65?'#00b0ff':r>=55?'#ff6d00':'#7a8099'; }
function lgPopStr(p){ if(!p)return '?'; if(p>=1000000)return (p/1000000).toFixed(1)+'M'; if(p>=1000)return Math.round(p/1000)+'B'; return p; }

function lgBuildCountry(code, d, searchQ){
  const sec = document.createElement('div');
  sec.className = 'country-sec';

  let leaguesHtml = '';
  let totalMatch = 0;

  d.leagues.forEach(lg => {
    let teamsHtml = '';
    let lgMatch = 0;
    lg.teams.forEach(t => {
      const q = searchQ.toLowerCase();
      if(q && !t.name.toLowerCase().includes(q) && !t.city.toLowerCase().includes(q)) return;
      lgMatch++; totalMatch++;
      const isMyTeam = lgUserTeam && lgUserTeam.code===code && lgUserTeam.city===t.city;
      teamsHtml += `<div class="tm-card${isMyTeam?' my-team':''}" onclick="lgOpenSheet('${code}','${lg.tier}','${t.city.replace(/'/g,"\\'")}')">
        ${inlineBadge({tag:'div', cls:'tm-logo', team:t})}
        <div class="tm-body">
          <div class="tm-name" style="${isMyTeam?'color:#00e676;font-weight:800':''}">${t.name}</div>
          <div class="tm-city">${t.city}</div>
        </div>
        <div class="tm-rat" style="color:${lgRatColor(t.rating)}">${t.rating}</div>
      </div>`;
    });

    if(!teamsHtml && searchQ) return;

    const tierBadge = lg.tier===1
      ? '<span class="lh-bdg bdg-sl">ŞL/AVL/KL</span>'
      : lg.tier < d.leagues.length
        ? '<span class="lh-bdg bdg-eu">Yükselme</span>'
        : '<span class="lh-bdg bdg-rl">Son Klasman</span>';

    leaguesHtml += `<div class="league-blk">
      <div class="league-hd" onclick="lgToggleLeague(this)">
        <div class="lh-dot" style="background:${lg.color}"></div>
        <div class="lh-nm">${lg.name}</div>
        <div class="lh-tier">${lg.tier}. Klas.</div>
        ${tierBadge}
        <span class="lh-arr">›</span>
      </div>
      <div class="teams-grid hidden">${teamsHtml}</div>
    </div>`;
  });

  if(!leaguesHtml && searchQ) return null;

  const isOpen = searchQ.length > 0;
  sec.innerHTML = `
    <div class="country-hdr${isOpen?' open':''}" onclick="lgToggleCountry(this)">
      <span class="ch-flag">${d.flag}</span>
      <span class="ch-cname">${d.name}</span>
      <div class="ch-cmeta">${d.total} şehir · ${d.leagues.length} lig</div>
      <span class="ch-carr">›</span>
    </div>
    <div class="country-bdy${isOpen?' open':''}">${leaguesHtml}</div>`;
  return sec;
}

function lgRender(searchQ=''){
  const container = document.getElementById('lgContainer');
  if(!container) return;
  container.innerHTML = '';
  let shown = 0;

  const entries = _cftAllEntries().sort((a,b)=>{
    if(a[0]==='TR') return -1; if(b[0]==='TR') return 1;
    return a[1].name.localeCompare(b[1].name,'tr');
  });

  entries.forEach(([code, d]) => {
    if(lgFilter_cur !== 'all'){
      if(!(LG_REGIONS[lgFilter_cur]||[]).includes(code)) return;
    }
    const q = searchQ.toLowerCase();
    const nameMatch = d.name.toLowerCase().includes(q);
    const sec = lgBuildCountry(code, d, q && !nameMatch ? q : '');
    if(sec){ container.appendChild(sec); shown++; }
  });

  const badge = document.getElementById('lgBadge');
  if(badge) badge.textContent = shown + ' Ülke';
}

function lgToggleCountry(hdr){
  hdr.classList.toggle('open');
  hdr.nextElementSibling.classList.toggle('open');
}

function lgToggleLeague(hdr){
  hdr.classList.toggle('open');
  hdr.nextElementSibling.classList.toggle('hidden');
}

function lgFilter(r, btn){
  lgFilter_cur = r;
  document.querySelectorAll('.lg-pill').forEach(p=>p.classList.remove('on'));
  btn.classList.add('on');
  lgRender(document.getElementById('lgSearch').value);
}

let lgSearchTimer;
function lgDoSearch(){
  clearTimeout(lgSearchTimer);
  lgSearchTimer = setTimeout(()=>lgRender(document.getElementById('lgSearch').value), 250);
}

function lgOpenSheetFromEl(el){
  lgOpenSheet(el.dataset.code, el.dataset.tier, el.dataset.city);
}
function lgOpenSheet(code, tier, city){
  const d = _cftGetCountry(code); if(!d) return;
  const lg = d.leagues.find(l=>l.tier===parseInt(tier)); if(!lg) return;
  const t = lg.teams.find(t=>t.city===city); if(!t) return;
  lgCurrentTeam = {code, tier:parseInt(tier), t, lg, d};

  const logo = document.getElementById('lgShLogo');
  logo.textContent=t.short; logo.style.background=t.bg; logo.style.color=t.tc;
  document.getElementById('lgShName').textContent=t.name;
  document.getElementById('lgShLeague').textContent=lg.name;
  document.getElementById('lgShCountry').textContent=d.flag+' '+d.name;
  const ratEl=document.getElementById('lgShRating');
  ratEl.textContent=t.rating; ratEl.style.color=lgRatColor(t.rating);
  document.getElementById('lgShOZ').textContent=t.oz.toLocaleString('tr');
  document.getElementById('lgShPop').textContent=lgPopStr(t.pop);
  document.getElementById('lgShTier').textContent=tier+'. Klasman';

  let promoHtml='';
  if(parseInt(tier)===1){
    promoHtml=`<b>${lg.name}</b> — Avrupa kupalarına katılım hakkı.<br>
    <b>İlk 2:</b> Şampiyonlar Ligi &nbsp;|&nbsp; <b>3-4:</b> Avrupa Ligi &nbsp;|&nbsp; <b>5-6:</b> Konferans Ligi<br>
    <b>Son 4:</b> Küme düşme · Başlangıç Kasası: <b>${(t.oz*1000).toLocaleString('tr')} €</b>`;
  } else {
    const upper = d.leagues.find(l=>l.tier===parseInt(tier)-1);
    promoHtml=`<b>Yükselme:</b> İlk 4 takım ${upper?upper.name:'üst lig'}e yükselir.<br>
    <b>Küme düşme:</b> Son 4 takım bir alt klasmana iner.<br>
    <b>Başlangıç Kasası: ${(t.oz*1000).toLocaleString('tr')} €</b>`;
  }
  document.getElementById('lgShPromo').innerHTML=promoHtml;

  const isMyTeam = lgUserTeam && lgUserTeam.code===code && lgUserTeam.city===city;
  const btn=document.getElementById('lgJoinBtn');
  btn.textContent = isMyTeam ? '✅ Zaten Bu Takımdasın' : '⭐ Bu Takıma Katıl';
  btn.className = 'lg-join-btn' + (isMyTeam?' taken':'');

  document.getElementById('lgOverlay').classList.add('open');
}

function lgCloseSheet(){
  document.getElementById('lgOverlay').classList.remove('open');
  lgCurrentTeam=null;
}

function lgJoinTeam(){
  if(!lgCurrentTeam) return;
  const {code,tier,t,lg,d}=lgCurrentTeam;
  lgUserTeam={code,tier,city:t.city,name:t.name};
  // RAM cache (localStorage YOK; gerçek takım kayıt akışı _userTeam üzerinden Supabase'e yazar)
  const btn=document.getElementById('lgJoinBtn');
  btn.textContent='✅ Katıldın!'; btn.className='lg-join-btn taken';
  setTimeout(()=>{
    lgCloseSheet();
    lgRender(document.getElementById('lgSearch').value);
    alert('✅ '+t.name+' takımına katıldın!\n\nLig: '+lg.name+'\nRating: '+t.rating+'\nBaşlangıç Kasası: '+(t.oz*1000).toLocaleString('tr')+' €');
  }, 500);
}

