  if (_userTeam) {
    await _rosterRefreshFromServer(_userTeam.countryCode);
    syncUserToRoster();
    rosterBuildTeam(_userTeam.countryCode);
  } else if (eski) rosterClearTeam();
  const enerji = degisti ? recomputeUserEnergyBonus().delta : 0;
  for (const k in window._fedKaptanOnb) window._fedKaptanOnb[k].t = 0;
