          // 🆕 SUPABASE'TE AKTİF OTURUM VAR — profil + user_player çek
          _kararVer();                         // 🆕 oturum bulundu → splash kapanabilir
          if (sess.session.user.is_anonymous) { _msfAcilis(sess.session.user); return; }   // 960 — misafir
          const userId = sess.session.user.id;
          const userEmail = sess.session.user.email;

