  try { _energyCache = { current: 0, max: (typeof ENERGY_MAX !== 'undefined' ? ENERGY_MAX : 0), dayKey: (typeof getUserDayKey === 'function') ? getUserDayKey() : new Date().toDateString() }; } catch (e) {}
  window._userProgressCache = { level: 0, xp: 0, overall: 10 };
  let hv = null; try { hv = localStorage.getItem('csc_hesap'); } catch (e) {}
  hideAuthScreen();
