  const { data: _eng } = await window.sb.from('profiles').select('ban_until, ban_reason').eq('id', user.id).maybeSingle();
  const _bt = _eng && _eng.ban_until ? new Date(_eng.ban_until) : null;
  if (_bt && !isNaN(_bt) && _bt > new Date()) {
    try { await window.sb.auth.signOut({ scope: 'local' }); } catch (e) {}
    authShowMsg('error', _hesapEngelMetni(_bt, _eng.ban_reason));
    return;
  }
  authShowMsg('success', 'Giriş başarılı, oyun yükleniyor…');
  try { sessionStorage.setItem('cft_girisYeni', '1'); } catch (e) {} _izYaz('giris');
