// ── PROFİLDEN AVATAR DEĞİŞTİRME ──
let _avatarModalSelected = null;

function openAvatarChangeModal() {
  if(!authUser) return;
  _avatarModalSelected = authUser.avatarId || null;
  _avatarCins.modal = _avatarKendiCins() || 'M';
  renderAvatarModalGrid();
  // Onay butonu — başlangıçta mevcut avatar seçili olabilir, ama değişiklik yoksa disabled
  const btn = document.getElementById('avatarModalConfirm');
  if(btn) btn.disabled = true;
  document.getElementById('avatarModal').classList.add('open');
}

function closeAvatarChangeModal() {
  document.getElementById('avatarModal').classList.remove('open');
  _avatarModalSelected = null;
}

function renderAvatarModalGrid() {
  const wrap = document.getElementById('avatarModalGrid');
  if(!wrap) return;
  const mevcut = authUser && authUser.avatarId;
  const curA = AVATAR_OPTIONS.find(a => a.id === mevcut);
  const yeniA = _avatarModalSelected !== mevcut ? AVATAR_OPTIONS.find(a => a.id === _avatarModalSelected) : null;
  const bos = '<svg viewBox="0 0 24 24"><circle cx="12" cy="9" r="3.4"/><path d="M5.5 19.5c.6-3.6 3.2-5.6 6.5-5.6s5.9 2 6.5 5.6"/></svg>';
  const yuz = (a, sinif) => a ? `<div class="kmd-yz ${sinif}"><img src="${_avatarSrc(a)}" alt=""></div>` : `<div class="kmd-yz bos">${bos}</div>`;
  document.getElementById('avatarModalKars').innerHTML =
    `<figure>${yuz(curA, '')}<figcaption>Mevcut</figcaption></figure><svg viewBox="0 0 24 24"><path d="M4 12h15M13 6l6 6-6 6"/></svg>`
    + `<figure>${yuz(yeniA, 'yeni')}<figcaption class="${yeniA ? 'y' : ''}">Yeni</figcaption></figure>`;
  const _kc = _avatarKendiCins();
  if (_kc) _avatarCins.modal = _kc;
  const _sek = document.getElementById('avatarModalSekme');
  _sek.style.display = _kc ? 'none' : '';
  _sek.innerHTML = _kc ? '' : [['M', 'Erkek'], ['F', 'Kadın']].map(([g, ad]) =>
    `<button class="${_avatarCins.modal === g ? 'on' : ''}" onclick="avatarCinsSec('modal','${g}')">${ad} <small>${AVATAR_OPTIONS.filter(a => a.gender === g).length}</small></button>`).join('');
  wrap.innerHTML = AVATAR_OPTIONS.filter(a => a.gender === _avatarCins.modal).map(a => {
    const m = a.id === mevcut, s = a.id === _avatarModalSelected && !m;
    return `<div class="kmd-av${m ? ' mevcut' : ''}${s ? ' secili' : ''}" onclick="selectAvatarInModal('${a.id}')">`
      + `<img src="${_avatarSrc(a)}" alt="" loading="lazy"><span class="kmd-av-kd" data-noi18n>${a.label}</span>${m ? '<span class="kmd-mv">Mevcut</span>' : ''}</div>`;
  }).join('');
}

function selectAvatarInModal(id) {
  const _sa = AVATAR_OPTIONS.find(a => a.id === id);
  if (!_sa || (_avatarKendiCins() && _sa.gender !== _avatarKendiCins())) return;
  _avatarModalSelected = id;
  renderAvatarModalGrid();
  // Onay butonu: mevcut avatar'la farklıysa aktif
  const btn = document.getElementById('avatarModalConfirm');
  if(btn) btn.disabled = (id === (authUser && authUser.avatarId));
}

function confirmAvatarChange() {
  if(!_avatarModalSelected || !authUser) return;
  if(_avatarModalSelected === authUser.avatarId) { closeAvatarChangeModal(); return; }
  { const _sa = AVATAR_OPTIONS.find(a => a.id === _avatarModalSelected);
    if (!_sa || (_avatarKendiCins() && _sa.gender !== _avatarKendiCins())) return; }

  // 🆕 Avatar değişim ücreti — CÜZDAN (user_wallet)
  const AVATAR_CHANGE_COST = 100;
  const _wlBal = (typeof wlGetData === 'function') ? (wlGetData().dia || 0) : 0;
  if (_wlBal < AVATAR_CHANGE_COST) {
    if (typeof cftConfirm === 'function') {
      cftConfirm({
        title: 'Yetersiz Diamond',
        message: `Avatar değişimi için ${AVATAR_CHANGE_COST} 💎 gerekli ama sende sadece ${_wlBal.toLocaleString('tr')} 💎 var.`,
        confirmText: 'Tamam',
        cancelText: '',
        danger: true,
        onConfirm: () => {}
      });
    }
    return;
  }
  const _wlOk = (typeof wlDeduct === 'function')
    ? wlDeduct('dia', AVATAR_CHANGE_COST, `Avatar Değişimi`)
    : false;
  if (!_wlOk) return;

  authUser.avatarId = _avatarModalSelected;

  // 🆕 Supabase'e KALICI yaz — players kanonik (avatar_id)
  (async () => {
    try {
      if (!window.sb || !authUser.id) return;
      await window.sb.from('players').update({ avatar_id: _avatarModalSelected }).eq('user_id', authUser.id);
    } catch(e) { console.warn('[avatarChange] Supabase update hata:', e); }
  })();

  // Player sayfasındaki avatarı yenile
  if(typeof renderPlayerPage === 'function') renderPlayerPage();

  // 🆕 CFC Media sayfası açıksa avatar görünümünü tazele
  try {
    const cfcPage = document.getElementById('page-cfc-media');
    if (cfcPage && cfcPage.classList.contains('active') && typeof cfcMdRender === 'function') {
      cfcMdRender();
    }
  } catch(e) {}

  closeAvatarChangeModal();

  // Toast
  const t = document.createElement('div');
  t.style.cssText = 'position:fixed;bottom:90px;left:50%;transform:translateX(-50%);background:linear-gradient(135deg,#388e3c,#4caf50);color:#fff;padding:12px 22px;border-radius:24px;font-size:13px;font-weight:700;z-index:9999;font-family:Twemoji Country Flags,"Barlow Condensed",sans-serif;letter-spacing:.4px;box-shadow:0 8px 24px rgba(0,0,0,.4)';
  t.textContent = '🎭 Avatar güncellendi!';
  document.body.appendChild(t);
  setTimeout(() => { t.style.transition='opacity .4s'; t.style.opacity='0'; setTimeout(()=>t.remove(),400); }, 2000);
}

