// AŞAMA 1: Ülke grid'i
// Sıralama: Kullanıcının ülkesi ilk → sonra UEFA katsayısına göre güçlü ülkeler
function tbmRenderCountryGrid() {
  const grid = document.getElementById('tbmCountryGrid');
  if(!grid || false) return;

  const userCC = (authUser && authUser.nationality) ? authUser.nationality : null;
  const myBudget = _tbmButce();   // 911 — elmas + kaptanlık puanı

  // Tüm ülkeleri topla, en ucuz takım fiyatını hesapla
  const countries = _cftGetCountryCodes().map(cc => {
    const c = _cftGetCountry(cc);
    let cheapest = Infinity;
    let teamCount = 0;
    let topTierAvgRating = 0;
    let mostExpensive = 0;

    // Tier 1 (en üst lig) ortalama rating'i — ülkenin "kalitesi"
    if(c.leagues[0] && c.leagues[0].teams.length) {
      const t1 = c.leagues[0].teams;
      const sum = t1.reduce((s, t) => s + (t.rating || 0), 0);
      topTierAvgRating = Math.round(sum / t1.length);
    }

    c.leagues.forEach((lg, tierIdx) => {
      lg.teams.forEach(t => {
        teamCount++;
        const price = kmpFiyat('takim', calcTeamPrice(t.pop, t.rating, tierIdx), cc + '|' + t.name);
        if(price < cheapest) cheapest = price;
        if(price > mostExpensive) mostExpensive = price;
      });
    });

    // UEFA katsayısı (varsa)
    let coef = 0;
    { const _cp = (typeof _countryPts === 'function') ? _countryPts(cc) : null; if(_cp) coef = _cp.total; }

    return {
      cc, name: c.name, flag: c.flag,
      teamCount, cheapest, mostExpensive, topTierAvgRating, coef,
      isUserCountry: cc === userCC,
    };
  });

  // Sıralama: kullanıcının ülkesi ilk → coef azalan → tier 1 avgRating azalan → mostExpensive azalan
  // Sezon 1'de coef hep 0, dolayısıyla pratik sıralama: tier 1 kalitesi + en pahalı takım
  countries.sort((a, b) => {
    if(a.isUserCountry && !b.isUserCountry) return -1;
    if(!a.isUserCountry && b.isUserCountry) return 1;
    if(b.coef !== a.coef) return b.coef - a.coef;
    if(b.topTierAvgRating !== a.topTierAvgRating) return b.topTierAvgRating - a.topTierAvgRating;
    return b.mostExpensive - a.mostExpensive;
  });

  grid.innerHTML = countries.map(c => {
    const userCls = c.isUserCountry ? 'user-country' : '';
    const cheapStr = c.cheapest === Infinity ? '—' : c.cheapest.toLocaleString('tr');
    const cheapColor = c.cheapest <= myBudget ? '#81c784' : 'var(--text3)';
    return `<button class="tbm-country-card ${userCls}" onclick="tbmSelectCountry('${c.cc}')">
      <div class="tbm-country-card-flag">${c.flag}</div>
      <div class="tbm-country-card-info">
        <div class="tbm-country-card-name">${c.name}</div>
        <div class="tbm-country-card-meta">${c.teamCount} takım · ★${c.topTierAvgRating}</div>
        <div class="tbm-country-card-cheap" style="color:${cheapColor}">💎 ${cheapStr}'den başlıyor</div>
      </div>
    </button>`;
  }).join('');
}

