function tbmRenderList() {
  const list = document.getElementById('tbmList');
  if(!list || false || !_tbmSelectedCountry) return;

  const country = _cftGetCountry(_tbmSelectedCountry);
  if(!country) return;

  const teams = [];
  country.leagues.forEach((lg, tierIdx) => {
    if(_tbmSelectedTier !== 'all' && _tbmSelectedTier !== tierIdx) return;
    lg.teams.forEach(t => {
      const _sahip = _realCaptainsCache[_tbmSelectedCountry + ':' + t.name];
      if (_sahip && _sahip.captainUserId) return;
      const price = kmpFiyat('takim', calcTeamPrice(t.pop, t.rating, tierIdx), _tbmSelectedCountry + '|' + t.name);
      teams.push({
        countryCode: _tbmSelectedCountry,
        countryName: country.name,
        flag: country.flag,
        leagueName: lg.name,
        tierIdx,
        rank: t.rank,
        name: t.name,
        rating: t.rating || 50,
        pop: t.pop || 0,
        price,
      });
    });
  });

  // Arama filtresi
  let filtered = teams;
  if(_tbmSearchText) {
    filtered = teams.filter(t => t.name.toLowerCase().includes(_tbmSearchText));
  }

  // Önce karşılayabildiklerini üste, sonra fiyata göre azalan
  const myBudget = _tbmButce();   // 911 — elmas + kaptanlık puanı
  filtered.sort((a, b) => {
    const aAfford = myBudget >= a.price;
    const bAfford = myBudget >= b.price;
    if(aAfford !== bAfford) return aAfford ? -1 : 1;
    return b.price - a.price;
  });

  if(!filtered.length) {
    list.innerHTML = '<div class="tsm-empty">Eşleşen takım bulunamadı.</div>';
    return;
  }

  list.innerHTML = filtered.map((t, idx) => {
    const affordable = myBudget >= t.price;
    const rowCls = affordable ? 'affordable' : 'unaffordable';
    const priceCls = affordable ? 'afford' : '';
    const ratingColor = t.rating >= 85 ? '#ffd600' : t.rating >= 75 ? '#81c784' : t.rating >= 65 ? '#90caf9' : '#b39ddb';
    const popLabel = t.pop >= 1000000
      ? (t.pop/1000000).toFixed(1) + 'M'
      : t.pop >= 1000
      ? Math.round(t.pop/1000) + 'K'
      : String(t.pop);

    const onclickAttr = affordable
      ? `onclick="tbmShowBuyConfirm('${t.countryCode}',${t.tierIdx},'${t.name.replace(/'/g,"\\'")}')"`
      : `onclick="showNeedMoreDiamondToast(${t.price})"`;

    return `<div class="tbm-team-row ${rowCls}" ${onclickAttr}>
      <div class="tbm-team-rank">${idx+1}</div>
      <div class="tbm-team-info">
        <div class="tbm-team-name">
          ${t.flag} ${t.name}
          <span class="tbm-rating-mini" style="color:${ratingColor}">★${t.rating}</span>
        </div>
        <div class="tbm-team-meta">
          <span>${t.leagueName}</span>
          <span class="tbm-pop">👥 ${popLabel}</span>
        </div>
      </div>
      <div class="tbm-team-price ${priceCls}">💎 ${t.price.toLocaleString('tr')}</div>
    </div>`;
  }).join('');
}

function showNeedMoreDiamondToast(price) {
  const need = kpOdemePlan(price).eksik;   // 911 — kaptanlık puanı düşüldükten sonra
  showNeedTeamToast(`💎 Yetersiz elmas! ${need.toLocaleString('tr')} 💎 daha gerekli.`);
}

function tbmShowBuyConfirm(countryCode, tierIdx, teamName) {
  if (aaTakimda(countryCode, teamName)) { aaTakimAc(countryCode, teamName); return; }   // 900 — açık artırmada
  // 639 — herhangi bir rolde takımdayken takım satın alınamaz
  //   663 — istisna: kaptanı bot olan kendi takımı (sunucu da doğrular)
  if(userHasTeam()){
    const _kendi = _userTeam && _userTeam.countryCode === countryCode && _userTeam.teamName === teamName
      && _userTeam.role !== 'captain' && getTeamCaptainType(countryCode, teamName) === 'bot';
    if(!_kendi){
      showJoinToast('🔒 Önce mevcut takımından ayrılmalısın.');
      return;
    }
  }
  const country = _cftGetCountry(countryCode);
  if(!country) return;
  const lg = country.leagues[tierIdx];
  if(!lg) return;
  const team = lg.teams.find(t => t.name === teamName);
  if(!team) return;

  const liste = calcTeamPrice(team.pop, team.rating, tierIdx), price = kmpFiyat('takim', liste, countryCode + '|' + teamName);
  _tbmBuyTarget = {
    countryCode, tierIdx, teamName, price,
    teamRating: team.rating,
    teamPop: team.pop,
    leagueName: lg.name,
    flag: country.flag,
    countryName: country.name,
  };

  const popLabel = team.pop >= 1000000
    ? (team.pop/1000000).toFixed(1) + 'M kişi'
    : team.pop >= 1000
    ? Math.round(team.pop/1000) + 'K kişi'
    : team.pop + ' kişi';
  const myBudget = _tbmButce();   // 911 — elmas + kaptanlık puanı
  const _kpP = kpOdemePlan(price);   // 911
  szAc({
    tur: 'sistem', cc: countryCode, takim: teamName, ulke: country.name, onay: confirmTeamBuy,
    satirlar: [['Lig', lg.name], ['Şehir Nüfusu', popLabel], ['Takım Gücü', `★ ${team.rating}/100`],
               ['Mevcut Bütçe', '…', 'yesil', 'szKasa'], ['Senin Rolün', 'Kaptan', 'altin']],
    fiyat: price, eski: liste > price ? liste : 0, eksik: _kpP.eksik, kp: _kpP,
    sonra: _kpP.kp ? _kpOdemeMetin(_kpP) : `Satın aldıktan sonra bütçen: <b data-noi18n>${(_kpP.bal - price).toLocaleString('tr')}</b> ${_SZ_ELMAS}`,
    satici: 'Sistem', saticiImza: 'CSC',
  });
  // Satın alınacak takımın kasası (mevcut bütçe)
  window.sb.from('team_data').select('data')
    .eq('country_code', countryCode).eq('team_name', teamName).eq('data_key', 'treasury').maybeSingle()
    .then(({ data }) => {
      const eur = (data && data.data && Number(data.data.eur)) || 0;
      const kasa = eur >= 1e6 ? (eur / 1e6).toFixed(2).replace(/\.?0+$/, '') + 'M €' : eur >= 1e3 ? Math.round(eur / 1e3) + 'K €' : Math.round(eur).toLocaleString('tr') + ' €';
      if (!_sz || _sz.takim !== teamName) return;
      _sz.satirlar.find(r => r[3] === 'szKasa')[1] = kasa;   // imzadan sonra yeniden çizilince de kalsın
      const el = document.getElementById('szKasa');
      if (el) el.textContent = kasa;
    });
}

