// ── XP & Level Sistemi ──
// Sınırsız seviye, her seviye bir öncekinden zorlaşır.
// Formül: Level L'den L+1'e ulaşmak için gereken XP = 60 + 30*L + 8*L²
//
// Örnekler:
//   Lv 0→1:    60 XP        (~1 antrenman 9dk veya 6 antrenman 3dk)
//   Lv 1→2:    98 XP
//   Lv 5→6:   308 XP        (toplam Lv 5 = 840 XP → casual ~5 gün)
//   Lv 9→10:  978 XP        (toplam Lv 10 = 4.230 XP → casual ~28 gün)
//   Lv 24→25: 5.808 XP      (toplam Lv 25 = 49.700 XP → casual ~330 gün)
//   Lv 49→50: 20.738 XP     (toplam Lv 50 = 363.150 XP → 2 yıl aktif)
//   Lv 99→100: 81.438 XP    (toplam Lv 100 = 2.78M XP)
//
// Sıralamalardaki yıldız oyuncular: ~Lv 30-60 arası (overall 70+)
// Pro-grindin Lv 100+ ulaşılabilir
function rosterXpForLevel(level) {
  // Level L'den L+1'e geçmek için gereken XP
  return Math.round(60 + 30 * level + 8 * level * level);
}

// Toplam XP hesabı (level 0'dan level N'e — istatistik/UI için)
function rosterTotalXpForLevel(targetLevel) {
  let total = 0;
  for(let i = 0; i < targetLevel; i++) total += rosterXpForLevel(i);
  return total;
}

// Oyuncuya XP ekle ve gerekirse seviye atlat. Döner: {leveled, oldLevel, newLevel, gainedXp}
// Sınırsız seviye — cap yok. Tek seferde çoklu level-up mümkün.
// Her seviye atladığında overall +1 artar (10'dan başlar, level 89'da 99 cap'e ulaşır).

// ══ SEVİYE ATLAMA TEBRİK ANIMASYONU ══
// Kullanıcı oyuncusu seviye atladığında çağrılır.
// Birden fazla seviye atladıysa (XP yığılması) en yüksek seviyeyi gösterir.
function showLevelUpAnimation(newLevel, oldLevel) {
  // Önceden açık olan animasyonu kapat (üst üste binmeyi önle)
  const existing = document.getElementById('lvlupOverlay');
  if(existing) existing.remove();

  // Motivasyon mesajları seviyeye göre
  let msg, ord;
  if(newLevel <= 3)        msg = '🚀 Harika bir başlangıç! Devam et, yükselişin başladı.';
  else if(newLevel <= 9)   msg = '⚡ Süper ilerliyorsun! Antrenmana devam.';
  else if(newLevel <= 19)  msg = '🔥 Süper performans! Takımının yıldızı oluyorsun.';
  else if(newLevel <= 39)  msg = '⭐ Mükemmel! Profesyonel seviyeye çok yakınsın.';
  else if(newLevel <= 59)  msg = '👑 Efsane oluyorsun! Sahanın hakimi sensin.';
  else if(newLevel <= 79)  msg = '🏆 İnanılmaz! Top oyunculardan birisin.';
  else                     msg = '💎 SEN BİR EFSANESİN! Tüm dünya seni izliyor.';

  // Atladığı seviye sayısı (multi-level XP yığılmasında 1+ olabilir)
  const skipped = Math.max(1, newLevel - oldLevel);
  const skippedTxt = skipped > 1 ? ` (+${skipped} seviye!)` : '';

  // Yıldız parıltıları için pozisyonlar (etrafa serpilir)
  const sparkCount = 8;
  let sparks = '';
  for(let i = 0; i < sparkCount; i++) {
    const angle = (360 / sparkCount) * i;
    const delay = (i * 0.18).toFixed(2);
    const ic = ['⭐','✨','🌟','💫'][i % 4];
    sparks += `<span class="lvlup-spark" style="
      left:${50 + Math.cos(angle * Math.PI/180) * 38}%;
      top:${50 + Math.sin(angle * Math.PI/180) * 38}%;
      animation-delay:${delay}s">${ic}</span>`;
  }

  const overlay = document.createElement('div');
  overlay.id = 'lvlupOverlay';
  overlay.className = 'lvlup-overlay';
  overlay.innerHTML = `
    <div class="lvlup-card">
      <div class="lvlup-trophy">🏆</div>
      <div class="lvlup-title">Tebrikler!</div>
      <div class="lvlup-big-num">${newLevel}</div>
      <div class="lvlup-big-sub">Seviye Atladın</div>
      <div class="lvlup-msg">${msg}</div>
      <div class="lvlup-hint">Devam etmek için dokun</div>
      ${sparks}
    </div>
  `;

  // Tıklayınca veya 4.5 saniye sonra otomatik kapan
  const close = () => {
    if(overlay.classList.contains('closing')) return;
    overlay.classList.add('closing');
    setTimeout(() => overlay.remove(), 350);
  };
  overlay.addEventListener('click', close);
  document.body.appendChild(overlay);
  setTimeout(close, 4500);
}


function rosterAwardXp(playerNum, xpAmount) {
  const p = ROSTER_DATA.find(x => x.num === playerNum);
  if(!p) return { leveled:false, oldLevel:0, newLevel:0 };
  if(typeof p.xp !== 'number') p.xp = 0;
  if(typeof p.level !== 'number') p.level = 0;
  if(typeof p.overall !== 'number') p.overall = 10;
  const oldLevel = p.level;
  p.xp += xpAmount;
  // Çoklu level-up döngüsü, sınırsız (cap yok)
  while(p.xp >= rosterXpForLevel(p.level)) {
    p.xp -= rosterXpForLevel(p.level);
    p.level++;
    // 🆕 KURAL: overall buradan +1 artırılmaz. OVR yalnızca yetenek ortalamasından
    // hesaplanır (getPlayerMainOverall). Seviye atlamada yetenekler ayrı artıyor
    // (rosterUserApplyLevelUp vs.), o yüzden bu döngünün sadece görevi level/xp tutmak.
    // Güvenlik: aşırı XP enjeksiyonu durumunda sonsuz döngü engeli
    if(p.level > 9999) break;
  }
  // 🆕 Skill'ler değişmiş olabilir (seviye atlamada) → overall'ı YENİDEN HESAPLA
  // (getPlayerMainOverall 4 mevki ortalamasının ortalamasını döndürür)
  if (typeof getPlayerMainOverall === 'function') {
    p.overall = getPlayerMainOverall(p);
  }
  // Kullanıcının kendi roster'ını localStorage'a kaydet (kalıcılık)
  rosterPersistUserProgress();
  // Overall değiştiyse RK player cache'ini geçersiz kıl (sıralamalar tazelenir)
  if(typeof invalidateRkPlayerCache === 'function') invalidateRkPlayerCache();

  const leveled = p.level > oldLevel;
  // 🆕 Kullanıcı oyuncusu seviye atladıysa tebrik animasyonu göster
  if(leveled && p.role === 'user' && typeof showLevelUpAnimation === 'function') {
    // Animasyon DOM hazır olduğunda gösterilsin (akış kesilmesin)
    setTimeout(() => showLevelUpAnimation(p.level, oldLevel), 50);
  }

  return { leveled, oldLevel, newLevel: p.level, gainedXp: xpAmount };
}

// Kullanıcının kendi seviyesini/XP'sini localStorage'a yaz (oturum sonrası kaybolmasın)
