// ══════ OYUNCU PROFİL MODAL ══════
// Guest takımının son render edilen kadrosunu cache'le (modal açarken referans için)
let _lastGuestRoster = [];

// Kullanıcı (gerçek user) teklif sunmaya yetkili mi?
// Yetki kuralı: kullanıcı bir takıma KATILMIŞ olmalı VE _userTeam.role'ü
// 'captain' veya 'vice' olmalı. Sıradan üye (member) teklif sunamaz.
// Takım satın alındığında otomatik captain rolü verilir.
function userCanMakeOffer() {
  if(!userHasTeam()) return false;
  if(!_userTeam) return false;
  return _userTeam.role === 'captain' || _userTeam.role === 'vice';
}

// Kullanıcının rolüne göre gösterilecek metin (kilit notu için)
function userRoleLabel() {
  if(!userHasTeam()) return 'Takımsız';
  if(_userTeam) {
    if(_userTeam.role === 'captain') return 'Kaptan';
    if(_userTeam.role === 'vice') return 'Yardımcı Kaptan';
    if(_userTeam.role === 'member') return 'Üye';
  }
  return 'Üye';
}

function posLabelLong(p) {
  return p === 'GK' ? 'Kaleci'
       : p === 'DEF' ? 'Defans'
       : p === 'MID' ? 'Orta Saha'
       : p === 'FWD' ? 'Forvet' : p;
}

// ── Basit deterministik hash ──
function _hashStr(s) {
  let h = 0;
  for(let i = 0; i < s.length; i++) h = ((h << 5) - h + s.charCodeAt(i)) | 0;
  return Math.abs(h);
}

// ── Bayrak → Ülke kodu eşlemesi (teams DB ile) ──
const FLAG_TO_CC = {
  '🇹🇷':'TR','🇪🇸':'ES','🇩🇪':'DE','🇫🇷':'FR','🇮🇹':'IT','🇵🇹':'PT',
  '🇳🇱':'NL','🇧🇪':'BE','🇨🇭':'CH','🇸🇪':'SE','🇳🇴':'NO','🇩🇰':'DK',
  '🇫🇮':'FI','🇮🇪':'IE','🇨🇿':'CZ','🇸🇰':'SK','🇦🇹':'AT','🇵🇱':'PL',
  '🇭🇺':'HU','🇷🇴':'RO','🇧🇬':'BG','🇷🇺':'RU','🇺🇦':'UA','🇷🇸':'RS',
  '🇭🇷':'HR','🇬🇷':'GR','🇮🇱':'IL','🇦🇿':'AZ','🇰🇿':'KZ','🇦🇱':'AL',
  '🏴󠁧󠁢󠁥󠁮󠁧󠁿':'EN','🏴󠁧󠁢󠁳󠁣󠁴󠁿':'SC'
};

// ── teams DB'de ülke + takım adıyla ara ──
function findTeamInDB(cc, query) {
  if(!cc || false || !_cftGetCountry(cc)) return null;
  const q = (query||'').toLowerCase().trim();
  if(!q) return null;
  for(const lg of _cftGetCountry(cc).leagues) {
    for(const t of lg.teams) {
      if((t.name||'').toLowerCase() === q || (t.city||'').toLowerCase() === q) return t;
    }
  }
  // Kısmi eşleşme (örn "Madrid CF" → teams DB'de "Madrid")
  // Sondaki uzantıyı sil ve yeniden ara
  const stripped = q.replace(/\s+(fc|cf|sk|sc|fk|bk|city|united|athletic|sporting|liman|norte|ege|sg)$/i, '').trim();
  if(stripped !== q) {
    for(const lg of _cftGetCountry(cc).leagues) {
      for(const t of lg.teams) {
        if((t.name||'').toLowerCase() === stripped || (t.city||'').toLowerCase() === stripped) return t;
      }
    }
  }
  return null;
}

// ── RK player için takım referansı bul (bayrak + isim) ──
// Geri dönüş: { countryCode, teamName } veya null (bulunamadıysa)
function rkPlayerLookupTeam(rk) {
  if(!rk || !rk.f) return null;
  const cc = FLAG_TO_CC[rk.f];
  if(!cc) return null;
  const team = findTeamInDB(cc, rk.c);
  if(team) return { countryCode: cc, teamName: team.name };
  // Bulunamazsa bayrağa göre ülkenin 1. takımına yönlendir (best effort)
  if(true && _cftGetCountry(cc) && _cftGetCountry(cc).leagues[0] && _cftGetCountry(cc).leagues[0].teams[0]) {
    return { countryCode: cc, teamName: _cftGetCountry(cc).leagues[0].teams[0].name, fallback: true };
  }
  return null;
}

// ── 592 · Sözleşmeler SEZON bazlı ────────────────────────────────────
//   Bitiş = bitiş sezonunun 40. günü (gerçek tarih). Gerçek oyuncunun sözleşmesini sunucu yazar
//   (players.user_team_data.contract). Botların sözleşme kaydı yok: oyuncuya göre sabit fazlı
//   4 sezonluk döngü — sezon ilerledikçe kısalır, bitince yenilenir (hiçbir takım botu "boşta" görünmez).
function sezonSonuTarihi(sezon) {
  const d = new Date(SEASON_EPOCH);
  d.setUTCDate(d.getUTCDate() + (Math.max(1, sezon) - 1) * SEASON_LEN + (SEASON_LEN - 1));
  return d;
}
function sozlesmeBitisEtiketi(sezon) {
  const d = sezonSonuTarihi(sezon), p = (n) => String(n).padStart(2, '0');
  return `${sezon}. sezon sonu · ${p(d.getUTCDate())}/${p(d.getUTCMonth() + 1)}/${d.getUTCFullYear()}`;
}
// Yeni imzalanan sözleşmenin bitiş sezonu (sunucudaki kuralın aynısı: sezon sonu transfer günlerinde imza → sayım sonraki sezondan)
function sozlesmeBitisSezonu(sure) {
  const info = getSeasonInfo();
  return (info.season || 1) + Math.max(1, Math.min(4, Number(sure) || 1)) - ((info.dayInSeason || 0) >= 34 ? 0 : 1);
}
function getPlayerContract(player, teamName) {
  const info = getSeasonInfo();
  const sezon = info.season || 1, gun = info.dayInSeason || 0;
  const uid = (typeof authUser !== 'undefined' && authUser && authUser.id) || null;
  const benim = !!(player && (player.role === 'user' || (uid && (player.userId || player.user_id) === uid)));
  if (benim ? !!(_userTeam && _userTeam.role === 'captain') : !!(player && !player.isBot && player.role === 'captain')) {
    return { type: 'owner', label: '👑 Takım Sahibi · Kontrat Yok' };
  }
  if (!teamName) return { type: 'free', label: '🆓 Boşta · Serbest Transfer' };
  return { type: 'none', label: '' };   // 963 — sözleşme yok: takımdaki oyuncu da kararı kendisi verir
  let bitis, c = null;
  if (player && player.isBot) {
    const faz = _hashStr((player.name || '') + '|' + teamName) % 4;
    bitis = sezon + ((4 - ((sezon + faz) % 4)) % 4);
  } else {
    c = benim ? (_userTeam && _userTeam.contract) : ((player && player.user_team_data && player.user_team_data.contract) || (player && player.contract) || null);
    if (!sozlesmeAktifMi(c, sezon)) return { type: 'none', label: 'Sözleşmesiz' };   // 854 — sunucuyla aynı kural
    bitis = c.endsSeason;
  }
  const kalanSezon = Math.max(0, bitis - sezon);
  return {
    type: 'active', endsSeason: bitis, endDate: sezonSonuTarihi(bitis), label: sozlesmeBitisEtiketi(bitis),
    tarih: sozlesmeBitisEtiketi(bitis).split(' · ').pop(),
    bitti: bitis < sezon, expiring: bitis === sezon && (SEASON_LEN - gun) <= 10,
    seasonsLeft: kalanSezon, daysLeft: bitis < sezon ? 0 : kalanSezon * SEASON_LEN + Math.max(0, SEASON_LEN - gun),
    contract: c
  };
}

// Kendi takımındaki oyuncuya tıklayınca
function openPlayerModalSelf(num) {
  const p = ROSTER_DATA.find(x => x.num === num);
  if(!p) return;
  // 🆕 Kullanıcının gerçek takım adı (eski hardcoded "Ankara" kaldırıldı)
  const teamName = (typeof _userTeam !== 'undefined' && _userTeam && _userTeam.teamName) ? _userTeam.teamName : '—';
  const cc = (typeof _userTeam !== 'undefined' && _userTeam && _userTeam.countryCode) ? _userTeam.countryCode : 'TR';
  openPlayerModal(p, { teamName, countryCode: cc, isOwnTeam: true });
}

// Ziyaret edilen takımdaki oyuncuya tıklayınca (cache'den bul)
function openPlayerModalGuest(num) {
  const p = _lastGuestRoster.find(x => x.num === num);
  if(!p) return;
  const teamName = _viewingTeam ? _viewingTeam.teamRef.name : '—';
  const cc = _viewingTeam ? _viewingTeam.countryCode : '';
  openPlayerModal(p, { teamName, countryCode: cc, isOwnTeam: false });
}

// Sıralamalardaki oyuncuya tıklayınca (dinamik liste index ile)
function openPlayerModalRanking(idx) {
  // 🆕 BUG FIX: render sırasındaki sıralı top50'yi kullan, yoksa fallback
  // (Eskiden buildRkPlayerList()'i tekrar çağırıp filter yapıyordu —
  //  sıralama farklı + filter yüzünden YANLIŞ oyuncu açılıyordu)
  // 🆕 buildRkPlayerList() fallback KALDIRILDI — mobilde ~8000 oyuncuyu bellekte üretip OOM/çökmeye
  //   yol açıyordu. _rkPlayersTop50 zaten render'da kurulur; yoksa modal açma.
  const rk = (window._rkPlayersTop50 && window._rkPlayersTop50[idx]) || null;
  if(!rk) return;

  // Eğer ROSTER_DATA'daki bir oyuncu ise tam objeyi kullan
  if(rk._rosterPlayer) {
    const myTeamName = (typeof _userTeam !== 'undefined' && _userTeam && _userTeam.teamName) ? _userTeam.teamName : '—';
    openPlayerModal(rk._rosterPlayer, { teamName: myTeamName, countryCode: 'TR', isOwnTeam: true });
    return;
  }

  const player = {
    num: idx + 1,
    name: rk.n,
    nation: rk.f,
    nationality: rk.cc || '',
    pos: rk.p,          // zaten GK/DEF/MID/FWD
    level: rk.lv || 0,
    xp: 0,
    overall: rk.o,      // deterministik hesaplanmış overall
    avatar: rk.av || '⚽',
    avatar_id: rk.avatar_id || null,   // 🆕 avatar_id taşı (fallback'te de avatar görünsün)
    gender: rk.gender || null,
    userId: rk.userId || null,         // 🆕 user_id → resolve uid ile kesin bulsun (team_name'e takılmaz)
    user_id: rk.userId || null,
    role: 'member'
    // 🆕 isBot KALDIRILDI — kanonik resolver (openPlayerModal) doğru değeri set eder
    // Eskiden sahte isBot:true geliyordu → gerçek user'ı bot sanıyordu → skills 10 görünüyordu
  };
  openPlayerModal(player, {
    teamName: rk.c,
    countryCode: rk.cc || '',
    teamLookupName: rk.teamName || rk.c,
    isOwnTeam: false
  });
}

// "Senin sıran" satırına tıklayınca → kendi profili
function openPlayerModalSelfFromRanking() {
  const me = ROSTER_DATA.find(p => p.role === 'user');
  if(!me) return;
  const teamName = (typeof _userTeam !== 'undefined' && _userTeam && _userTeam.teamName) ? _userTeam.teamName : '—';
  openPlayerModal(me, { teamName, countryCode: 'TR', isOwnTeam: true });
}

// Genel modal açma
// 🆕 Serbest/dış-kaynaklı oyuncuyu DB'den canlı çöz (takım cache'inde yoksa).
//   _buildRosterFromPlayers ile aynı kanonik objeyi üretir → is_bot/avatar/abilities/userId/level doğru.
async function _resolvePlayerFromServer(player, ctx){
  if(!window.sb || !player) return null;
  try {
    const cols='id, user_id, team_name, num, name, pos, pos_group, sub_pos, ek_mevki, ozel_yetenek, ozel_aktif, nationality, nation, level, xp, overall, rating, abilities, role, avatar, avatar_id, gender, is_bot, last_seen, user_team_data, goals_total, assists_total, matches_played, match_ratings, stats_by_comp, season_yellow, suspend_matches, suspend_reason, injury_until';
    let q=window.sb.from('players').select(cols);
    const uid=player.userId||player.user_id;
    if(uid) q=q.eq('user_id',uid);
    else if(typeof player.id==='number') q=q.eq('id',player.id);
    else if(player.name){
      q=q.eq('name',player.name);
      // 🆕 Aynı isimli birden çok oyuncu olabilir → takım + ülke ile daralt (varsa)
      const _tn=(ctx&&(ctx.teamLookupName||ctx.teamName))||player.team_name||null;
      const _cc=(ctx&&(ctx.countryCode||ctx.cc))||player.country_code||null;
      if(_tn) q=q.eq('team_name',_tn);
      if(_cc) q=q.eq('country_code',String(_cc).toUpperCase().slice(0,2));
    }
    else return null;
    const { data, error }=await q.limit(1);
    if(error||!Array.isArray(data)||!data.length) return null;
    const mapped=_buildRosterFromPlayers([data[0]], data[0].nationality);
    const out=(mapped&&mapped[0])||null;
    if(out) out.team_name = (data[0].team_name == null ? null : data[0].team_name);
    return out;
  } catch(e){ return null; }
}

// 🆕 Oyuncu milli takım kadrosunda mı? (uuid seti yüklüyse true/false, değilse null)
function _isNtSquadPlayerSync(player, cc) {
  // 572 — başkanın kadrosu + sunucunun güncel çağrı listesi (otomatik kadrodaki gerçek oyuncular)
  try {
    const uset = (typeof _ntSquadUuidByCc !== 'undefined') ? _ntSquadUuidByCc[cc] : null;
    const snap = (typeof _ntSnapUidByCc !== 'undefined') ? _ntSnapUidByCc[cc] : null;
    if (!uset && !snap) return null;
    if (player && player.id && uset && uset.has(player.id)) return true;
    const uid = player && (player.user_id || player.userId);
    return !!(uid && snap && snap.has(String(uid)));
  } catch(e) { return null; }
}
// 🆕 Profil modalında 'Milli Takım Oyuncusu' rozetini doldur (gerekiyorsa kadroyu async yükle)
async function _ntFillProfileNtBadge(player) {
  try {
    if (!player) return;
    const cc = player.nationality || player._cc || player.country_code;
    if (!cc) return;
    let member = _isNtSquadPlayerSync(player, cc);
    if (member === null && typeof _loadNtSquadFromServer === 'function') {
      await _loadNtSquadFromServer(cc);
      member = _isNtSquadPlayerSync(player, cc);
    }
    const el = document.getElementById('pmNtBadge');
    if (el && member) el.style.display = '';
  } catch(e) {}
}


