var _KUPA_RES = {"super": "medya/g957/kupa3b-super.220a096c.webp", "l1": "medya/g957/kupa3b-l1.8f618e46.webp", "l2": "medya/g957/kupa3b-l2.8f3674c7.webp", "l3": "medya/g957/kupa3b-l3.f38e3f22.webp", "l4": "medya/g957/kupa3b-l4.3ac93983.webp", "l5": "medya/g957/kupa3b-l5.6893f4eb.webp", "champ": "medya/g957/kupa3b-champ.11fabacc.webp", "elite": "medya/g957/kupa3b-elite.8aa488bf.webp", "conv": "medya/g957/kupa3b-conv.49d8993f.webp", "enc": "medya/g957/kupa3b-enc.0e29dae2.webp"};
