// ── Tepkiler: sahip olunanlar (oturumda bir kez okunur)
let _tpSahip = null, _tpSahipYuk = null;
function tpSahipYukle() {
  if (_tpSahip) return Promise.resolve(_tpSahip);
  if (_tpSahipYuk) return _tpSahipYuk;
  if (!window.sb || !_bgnGiris()) return Promise.resolve(new Set(['kalp']));
  _tpSahipYuk = window.sb.rpc('tepki_benim').then(({ data, error }) => {
    if (error) throw error;
    _tpSahip = new Set(['kalp'].concat(Array.isArray(data) ? data : []));
    return _tpSahip;
  }).catch(() => new Set(['kalp'])).finally(() => { _tpSahipYuk = null; });
  return _tpSahipYuk;
}
// Mağaza › Tepki (sekme ve canlı maçta kilitli tepkiye dokununca pencere)
let _tpMagSec = 'gol', _tpAliyor = false;
function _tpMagazaKur(kok, sec) {
  const sahip = _tpSahip || new Set(['kalp']);
  const liste = TP_LISTE.filter(t => t.f);
  if (sec) _tpMagSec = sec;
  kok.innerHTML = `${_hdSecimHtml(liste, _tpMagSec, sahip)}<div class="mg-tp-alt"><button id="tpAlBtn"></button></div>`;
  const yaz = () => {
    const t = _TPk[_tpMagSec], s = _tpSahip || new Set(['kalp']);
    _hdSahneYaz(kok, t);
    kok.querySelectorAll('.sc-c').forEach(c => {
      const v = s.has(c.dataset.k); c.classList.toggle('sec', c.dataset.k === _tpMagSec); c.classList.toggle('var', v);
      c.querySelector('span').innerHTML = v ? `<span data-noi18n>${_hdSende()}</span>` : `<span data-noi18n>${_bgnSayi(_TPk[c.dataset.k].f)}</span>${_HD_EL}`;
    });
    const b = kok.querySelector('#tpAlBtn'), v = s.has(_tpMagSec), yet = wlGetBalance('dia') >= t.f;
    b.className = v ? 'var' : (yet ? '' : 'yok');
    b.innerHTML = v ? `<span data-noi18n>${_hdSende()}</span>` : (yet ? `<span>Satın Al</span><b data-noi18n>${_bgnSayi(t.f)}</b>${_HD_EL}` : '<span>Elmas Al</span>');
  };
  kok.querySelectorAll('.sc-c').forEach(c => c.onclick = () => { _tpMagSec = c.dataset.k; yaz(); });
  kok.querySelector('#tpAlBtn').onclick = async () => {
    const t = _TPk[_tpMagSec], s = _tpSahip || new Set(['kalp']), b = kok.querySelector('#tpAlBtn');
    if (s.has(_tpMagSec) || _tpAliyor || !window.sb) return;
    if (wlGetBalance('dia') < t.f) { _hdElmasAl(); return; }
    _tpAliyor = true; b.disabled = true;
    try {
      const { data, error } = await window.sb.rpc('tepki_satin_al', { p_tur: _tpMagSec, p_istek: _hdIstek() });
      if (error) throw error;
      if (!data || !data.ok) { showToast(T(data && data.hata === 'elmas' ? 'Elmas yetersiz' : 'Satın alma yapılamadı'), 'err'); return; }
      if (!data.tekrar) _hdElmasDus(data.fiyat || t.f);
      _tpSahip = new Set(['kalp'].concat(Array.isArray(data.sahip) ? data.sahip : []));
      showToast(T(`${t.ad} tepkisi artık sende`), 'ok');
      _tpTepsiCiz();
    } catch (e) {
      showToast(T('Satın alma yapılamadı'), 'err');
    } finally {
      _tpAliyor = false; b.disabled = false; yaz();
    }
  };
  yaz();
}
function tpMagazaCiz() {
  const el = document.getElementById('shop-tepki'); if (!el) return;
  if (!el.querySelector('.mg-tp')) el.innerHTML = '<div class="shop-section-note">Canlı maçta tribüne tepki gönder. Kalp herkese ücretsiz.</div><div class="mg-tp"></div>';
  const kok = el.querySelector('.mg-tp');
  _tpMagazaKur(kok);
  tpSahipYukle().then(() => _tpMagazaKur(kok));
}
window.tpMagazaCiz = tpMagazaCiz;
function _tpSatinAlAc(k) {
  const ov = _hdModal(_hdBas(_TP_IKy, 'tp', 'Tepki', 'Mağaza') + '<div class="kmd-gov"><div class="mg-tp"></div></div><div class="kmd-alt"><button class="kmd-vaz" style="flex:1" data-kapat>Kapat</button></div>');
  _tpMagazaKur(ov.querySelector('.mg-tp'), k);
}

// ── Canlı maç: tepki tepsisi, uçan tepkiler, maç kanalı
//   Veritabanına yazılmaz; gönderen 2 sn'de en çok bir mesaj (içinde en çok 5 tepki), ekranda aynı anda en çok 8 uçan tepki.
let _tpKanal = null, _tpTaraf = 'yok', _tpUcan = 0, _tpKuyruk = [], _tpGonderT = null, _tpSon = 0;
function _tpTarafBul(o) {
  try {
    if (o.national) {
      if (o.ntTaraf === 'home') return 'ev';
      if (o.ntTaraf === 'away') return 'dep';
      const cc = typeof getUserNationalityCC === 'function' ? getUserNationalityCC() : null;
      if (cc && o.home && o.home.countryCode === cc) return 'ev';
      if (cc && o.away && o.away.countryCode === cc) return 'dep';
      return 'yok';
    }
    const t = (typeof _userTeam !== 'undefined' && _userTeam) ? _userTeam : null;
    if (t && t.teamName && o.home && o.home.name === t.teamName) return 'ev';
    if (t && t.teamName && o.away && o.away.name === t.teamName) return 'dep';
  } catch (e) {}
  return 'yok';
}
function tpAc(opts) {
  tpKapat();
  const mk = opts && opts.matchKey, ms = document.getElementById('match-screen');
  if (!mk || !ms || !window.sb || !_bgnGiris()) return;
  _tpTaraf = _tpTarafBul(opts);
  ms.insertAdjacentHTML('afterend', `<div class="tp-ucus" id="tpUcus"></div><div class="tp-tepsi" id="tpTepsi"></div>
    <div class="tp-kok" id="tpKok"><button class="tp-btn" id="tpAcBtn" aria-label="Tepkiler">${_TP_IKy}</button>
      <button class="tp-btn kalp" id="tpKalp" aria-label="Kalp">${_hdImg(_TPk.kalp, true)}</button></div>`);
  const tepsi = document.getElementById('tpTepsi'), ac = document.getElementById('tpAcBtn'), kalp = document.getElementById('tpKalp');
  ac.onclick = e => { e.stopPropagation(); const a = !tepsi.classList.contains('acik'); tepsi.classList.toggle('acik', a); ac.innerHTML = a ? _HD_IKx : _TP_IKy; };
  ms._tpKapa = () => { tepsi.classList.remove('acik'); ac.innerHTML = _TP_IKy; };
  ms.addEventListener('click', ms._tpKapa);
  kalp.onclick = () => { _tpGonder('kalp'); kalp.classList.remove('pop'); void kalp.offsetWidth; kalp.classList.add('pop'); };
  _tpTepsiCiz();
  tpSahipYukle().then(_tpTepsiCiz);
  try {
    _tpKanal = window.sb.channel('tp:' + mk, { config: { broadcast: { self: false } } })
      .on('broadcast', { event: 't' }, m => _tpGeldi(m && m.payload))
      .subscribe();
  } catch (e) { _tpKanal = null; }
}
function tpKapat() {
  clearTimeout(_tpGonderT); _tpGonderT = null; _tpKuyruk = []; _tpUcan = 0;
  const ms = document.getElementById('match-screen');
  if (ms && ms._tpKapa) { ms.removeEventListener('click', ms._tpKapa); ms._tpKapa = null; }
  ['tpUcus', 'tpTepsi', 'tpKok'].forEach(id => { const e = document.getElementById(id); if (e) e.remove(); });
  if (_tpKanal) { try { const r = window.sb.removeChannel(_tpKanal); if (r && r.catch) r.catch(() => {}); } catch (e) {} _tpKanal = null; }
}
function _tpTepsiCiz() {
  const tepsi = document.getElementById('tpTepsi'); if (!tepsi) return;
  const s = _tpSahip || new Set(['kalp']);
  tepsi.innerHTML = TP_LISTE.filter(t => t.f).map(t => `<div class="tp-h${s.has(t.k) ? '' : ' kilit'}" data-k="${t.k}">${_hdImg(t, true)}
    <span>${s.has(t.k) ? t.ad : `<span data-noi18n>${_bgnSayi(t.f)}</span>${_HD_EL}`}</span></div>`).join('');
  tepsi.querySelectorAll('.tp-h').forEach(h => h.onclick = e => {
    e.stopPropagation();
    const k = h.dataset.k;
    if ((_tpSahip || new Set(['kalp'])).has(k)) _tpGonder(k); else _tpSatinAlAc(k);
  });
}
const _tpCanli = () => { const ms = document.getElementById('match-screen'); return !!(ms && ms.classList.contains('open') && ms.classList.contains('is-live')); };
function _tpGonder(k) {
  if (!_tpCanli()) return;
  _tpUcur(k, true, _tpTaraf);
  if (_tpKuyruk.length < 5) _tpKuyruk.push(k);
  if (!_tpGonderT) _tpGonderT = setTimeout(_tpYolla, Math.max(0, 2000 - (Date.now() - _tpSon)));
}
function _tpYolla() {
  _tpGonderT = null;
  if (!_tpKanal || !_tpKuyruk.length) { _tpKuyruk = []; return; }
  const k = _tpKuyruk.splice(0, 5); _tpSon = Date.now();
  try { _tpKanal.send({ type: 'broadcast', event: 't', payload: { k, t: _tpTaraf } }); } catch (e) {}
}
function _tpGeldi(p) {
  if (!p || !Array.isArray(p.k) || document.hidden || !_tpCanli()) return;
  const t = (p.t === 'ev' || p.t === 'dep') ? p.t : 'yok';
  p.k.slice(0, 5).forEach((k, i) => { if (_TPk[k]) setTimeout(() => _tpUcur(k, false, t), i * 160); });
}
function _tpUcur(k, ben, taraf) {
  if (_tpUcan >= (ben ? 12 : 8)) return;            // aynı anda en çok 8 (kendi tepkilerinle 12) uçan tepki
  const kat = document.getElementById('tpUcus'), x = _TPk[k]; if (!kat || !x) return;
  const u = document.createElement('div');
  u.className = 'tp-u' + (ben ? ' ben' : '');
  const kenar = 10 + Math.random() * (ben ? 40 : 100), kay = 15 + Math.random() * 70;
  if (taraf === 'ev') { u.style.left = kenar + 'px'; u.style.setProperty('--x', kay + 'px'); }
  else if (taraf === 'dep') { u.style.right = kenar + 'px'; u.style.setProperty('--x', -kay + 'px'); }
  else { u.style.left = `calc(50% - 27px + ${(Math.random() * 60 - 30).toFixed(0)}px)`; u.style.setProperty('--x', (Math.random() * 60 - 30).toFixed(0) + 'px'); }
  u.style.setProperty('--y', (-(320 + Math.random() * 220)).toFixed(0) + 'px');
  u.style.setProperty('--s', (2.3 + Math.random() * .9).toFixed(2) + 's');
  if (!ben) u.style.setProperty('--b', (30 + Math.random() * 14).toFixed(0) + 'px');
  u.innerHTML = _hdImg(x, false, 'durgun a-' + x.ha);
  _tpUcan++;
  u.addEventListener('animationend', e => { if (e.target === u) { u.remove(); _tpUcan--; } });
  kat.appendChild(u);
}
function _bgnTakimHero(cc, ad, ziyaret) {
  const el = document.getElementById('teamHeroBgn'); if (!el) return;
  el.innerHTML = cc && ad ? _bgnPill('takim', cc + '|' + ad, _bgnGiris()) : '';   // 785 — kendi takımı da beğenilir
}
function _bgnMilliHero(cc) {
  const el = document.getElementById('ntHeroBgn'); if (!el) return;
  el.innerHTML = cc ? _bgnPill('milli', cc, _bgnGiris()) : '';   // 785 — kendi milli takımı da beğenilir
}
function _escapeHtml(s) {
  return String(s||'')
    .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
    .replace(/"/g,'&quot;').replace(/'/g,'&#39;');
}

// 🆕 Inbox'a mesaj ekle (DM thread'i + body/time güncelle)
function _dmAppendToInbox(threadItem, opts) {
  if (!_dmCurrent || typeof getInboxMsgs !== 'function') return;
  const msgs = getInboxMsgs();
  const e = msgs.find(m => m.id === _dmCurrent.msgId);
  if (!e) return;
  e.thread = e.thread || [];
  e.thread.push(threadItem);
  // Inbox listesinde önizleme: son mesaj
  e.body = threadItem.body || threadItem.text || '';
  e.time = threadItem.time || _dmCurrentTimeStr();
  // En yeni mesaj başa gelsin (inbox listesinde üstte gözüksün)
  const idx = msgs.indexOf(e);
  if (idx > 0) { msgs.splice(idx, 1); msgs.unshift(e); }
  // Bot cevap geldiyse okunmamış işaretle (modal kapalıysa badge artar)
  if (opts && opts.unread) e.read = false; else e.read = true;
  if (typeof saveInboxMsgs === 'function') saveInboxMsgs(msgs);
  if (opts && opts.unread && typeof inboxUpdateBadge === 'function') inboxUpdateBadge();
}

function dmSendMessage() {
  if (!_dmCurrent) return;
  const inp = document.getElementById('dmInput');
  if (!inp) return;
  const text = (inp.value || '').trim();
  if (!text) return;
  inp.value = '';

  const myName = (typeof authUser !== 'undefined' && authUser && authUser.name) ? authUser.name : 'Sen';
  const time = _dmCurrentTimeStr();

  // Kullanıcı mesajı
  _dmAppendToInbox({ from: myName, body: text, time, ts: Date.now() }, { unread: false });
  _dmRenderThread();

  // Bot yanıtı
  _dmShowTyping();
  const delay = 800 + Math.floor(Math.random() * 1200);
  const partnerMsgId = _dmCurrent.msgId;
  const partnerPlayer = _dmCurrent.player;
  setTimeout(() => {
    if (!_dmCurrent || _dmCurrent.msgId !== partnerMsgId) {
      // Modal kapalıysa veya başka konuşmaya geçildiyse: yine inbox'a yaz ama burada render yok
      // (güvenli yol: doğrudan inbox'a ekle)
      try {
        if (typeof getInboxMsgs === 'function' && typeof saveInboxMsgs === 'function') {
          const msgs2 = getInboxMsgs();
          const e2 = msgs2.find(m => m.id === partnerMsgId);
          if (e2) {
            const reply2 = _dmGenerateBotReply(partnerPlayer, text);
            const t2 = _dmCurrentTimeStr();
            e2.thread = e2.thread || [];
            e2.thread.push({ from: partnerPlayer.name, body: reply2, time: t2, ts: Date.now() });
            e2.body = reply2;
            e2.time = t2;
            e2.read = false;
            const idx2 = msgs2.indexOf(e2);
            if (idx2 > 0) { msgs2.splice(idx2,1); msgs2.unshift(e2); }
            saveInboxMsgs(msgs2);
            if (typeof inboxUpdateBadge === 'function') inboxUpdateBadge();
          }
        }
      } catch(e3) {}
      return;
    }
    _dmHideTyping();
    const reply = _dmGenerateBotReply(partnerPlayer, text);
    _dmAppendToInbox({ from: partnerPlayer.name, body: reply, time: _dmCurrentTimeStr(), ts: Date.now() }, { unread: false });
    _dmRenderThread();
  }, delay);
}

function _dmShowTyping() {
  const threadEl = document.getElementById('dmThread');
  if (!threadEl) return;
  if (threadEl.querySelector('.dm-empty')) threadEl.innerHTML = '';
  const old = threadEl.querySelector('.dm-typing');
  if (old) return;
  const div = document.createElement('div');
  div.className = 'dm-typing';
  div.id = 'dmTypingIndicator';
  div.innerHTML = '<span class="dm-typing-dot"></span><span class="dm-typing-dot"></span><span class="dm-typing-dot"></span>';
  threadEl.appendChild(div);
  threadEl.scrollTop = threadEl.scrollHeight;
}

function _dmHideTyping() {
  const t = document.getElementById('dmTypingIndicator');
  if (t) t.remove();
}

// Bot cevap üreteci — basit anahtar kelime + role bazlı
function _dmGenerateBotReply(player, userText) {
  const t = (userText || '').toLowerCase();
  const isCap = player.role === 'captain';
  const isVice = player.role === 'vice';
  const role = isCap ? 'captain' : (isVice ? 'vice' : 'member');

  const greetings = ['merhaba','selam','hey','sa ','s.a','selamün','iyi günler','günaydın','iyi akşamlar','naber'];
  const thanks = ['teşekkür','sağ ol','sagol','sağol','eyvallah'];
  const transferKw = ['transfer','teklif','takım','kadro','sözleşme','kontrat','ayrıl','katıl'];
  const matchKw = ['maç','antrenman','idman','form','sakat','sakatl','performans'];
  const compliments = ['harika','süper','muhteşem','tebrik','helal','aferin','güzel oyna','iyi maç'];
  const questions = ['?','nasıl','niye','neden','kim','ne zaman','nerede'];

  function pick(arr) { return arr[Math.floor(Math.random() * arr.length)]; }

  if (greetings.some(g => t.includes(g))) {
    return pick(['Selam! Hoşbuldum.','Merhaba, nasıl gidiyor?','Selamlar, iyi misin?','Hey! Ne haber?']);
  }
  if (thanks.some(g => t.includes(g))) {
    return pick(['Rica ederim.','Ne demek, her zaman.','Estağfurullah.','Önemli değil dostum.']);
  }
  if (transferKw.some(g => t.includes(g))) {
    if (isCap) return pick([
      'Takım için en doğru karar neyse onu yaparım.',
      'Kadro dengesini düşünmem lazım, sonra konuşalım.',
      'Bu konuda yönetimle görüşeceğim.'
    ]);
    return pick([
      'Şu an takımımla mutluyum aslında.',
      'Kontrat süresi bitmeden net bir şey diyemem.',
      'Düşüneyim, sonra dönerim sana.',
      'Menajerimle konuşman daha iyi olur.'
    ]);
  }
  if (matchKw.some(g => t.includes(g))) {
    return pick([
      'Form üzerinde çalışıyorum, iyi gidiyor.',
      'Antrenmanlar yoğun ama keyifli.',
      'Maç günü hazır olacağım, merak etme.',
      'Takımın başarısı için elimden geleni yapıyorum.'
    ]);
  }
  if (compliments.some(g => t.includes(g))) {
    return pick([
      'Çok teşekkür ederim, motive oldum!',
      'Sağ ol, devamı gelecek.',
      'Eyvallah, takım çalışması her şey.',
      'Memnun ettin beni, teşekkürler.'
    ]);
  }
  if (questions.some(g => t.includes(g))) {
    return pick([
      'İyi soru, biraz düşüneyim.',
      'Tam emin değilim aslında.',
      'Bu konuyu sonra konuşalım istersen.',
      'Antrenmanda detaylı anlatırım.'
    ]);
  }

  const generalCaptain = [
    'Anladım, takım için değerlendiririm.',
    'Görüşün için teşekkürler, dikkate alacağım.',
    'Doğru söylüyorsun, üzerinde duracağım.',
    'Antrenmandan sonra detaylı konuşalım.'
  ];
  const generalMember = [
    'Anladım, teşekkürler.',
    'Tamam, aklımda olacak.',
    'Söylediğin mantıklı geliyor.',
    'Sonra detaylı konuşalım istersen.',
    'Eyvallah, görüşmek üzere.'
  ];
  return pick(role === 'captain' ? generalCaptain : generalMember);
}

