// 🆕 Klavye açıldığında DM modal + inbox overlay'i klavye üstüne pin'le
// (dvh CSS'i modern browser'larda yeterli, JS fallback eski iOS Safari için)
(function() {
  if (!window.visualViewport) return;
  function _updateForKeyboard() {
    const vv = window.visualViewport;
    const keyboardHeight = window.innerHeight - vv.height - vv.offsetTop;
    const keyboardOpen = keyboardHeight > 50;
    // DM modal
    const dm = document.getElementById('dmModal');
    if (dm && dm.classList.contains('open')) {
      if (keyboardOpen) {
        dm.style.height = vv.height + 'px';
        dm.style.top = vv.offsetTop + 'px';
      } else {
        dm.style.height = '';
        dm.style.top = '';
      }
    }
    // Inbox overlay
    const ix = document.getElementById('inboxOverlay');
    if (ix && ix.classList.contains('open')) {
      if (keyboardOpen) {
        ix.style.height = vv.height + 'px';
        ix.style.top = vv.offsetTop + 'px';
      } else {
        ix.style.height = '';
        ix.style.top = '';
      }
    }
  }
  window.visualViewport.addEventListener('resize', _updateForKeyboard);
  window.visualViewport.addEventListener('scroll', _updateForKeyboard);
})();

// 🆕 Ziyaretçi modu — başka oyuncunun profilini görüntüle
var _visitedPlayerData = null;
var _visitedReturnAction = null; // { type:'guestTeam', cc, tn } veya { type:'page', name }

async function playerViewProfile(playerJson) {
  let player, ctx;
  try {
    const data = JSON.parse(playerJson);
    player = data.player;
    ctx = data.ctx;
  } catch(e) { return; }
  if(!player) return;

  // 🆕 Player JSON'dan parse edilince abilities/userId gibi field'lar kaybolabilir (büyük objeler)
  // → Kanonik objeyi cache'ten tekrar çöz, böylece ziyaretçi modu doğru veriye sahip olur
  try {
    if (player.role !== 'user') {
      const cc = ((ctx && (ctx.countryCode || ctx.cc)) || '').toUpperCase().slice(0,2);
      const teamName = (ctx && (ctx.teamLookupName || ctx.teamName)) || '';
      if (cc && teamName && typeof _loadTeamRosterFromServer === 'function') {
        let roster = _teamRosterCache[cc + ':' + teamName];
        if (!Array.isArray(roster) || roster.length === 0) {
          roster = await _loadTeamRosterFromServer(cc, teamName);
        }
        if (Array.isArray(roster) && roster.length) {
          const canonical = roster.find(r => r && r.name === player.name);
          if (canonical) player = canonical;
        }
      }
    }
  } catch(e) {}

  // 🆕 Return action snapshot: ne geldiğine göre nasıl döneceğini kaydet
  // Sadece henüz set edilmemişse (zincirleme ziyaret oturumunda eski action'ı koru)
  if (!_visitedReturnAction) {
    if (typeof _viewingTeam !== 'undefined' && _viewingTeam && _viewingTeam.teamRef) {
      // Misafir takım modunda → geri dönüşte viewTeam ile aynı takımı tekrar aç
      // ÖNEMLİ: Misafir takımın kendi prevPage'ini de yedekle ki restore edebilelim
      _visitedReturnAction = {
        type: 'guestTeam',
        cc: _viewingTeam.countryCode,
        tn: _viewingTeam.teamRef.name,
        prevPage: (typeof _viewingTeamPrevPage !== 'undefined') ? _viewingTeamPrevPage : null,
        hl: (window._pageHist || []).length, ghl: _viewingTeamHl   // 735
      };
      // Ziyaretçi profil moduna geçerken misafir takım state'ini temizle
      // (exitVisitorMode'da viewTeam tekrar çağrılıp restore edilecek)
      const _gtPage = document.getElementById('page-team');
      if (_gtPage) {
        _gtPage.classList.remove('guest-mode');
        _gtPage.classList.remove('no-join-chip');
      }
      _viewingTeam = null;
      if (typeof _viewingTeamPrevPage !== 'undefined') _viewingTeamPrevPage = null;
    } else {
      // Normal sayfadan geliş → o anki aktif sayfayı kaydet
      let fromName = window._lastNonPlayerPage || null;
      if (!fromName) {
        const ap = document.querySelector('.page.active');
        const an = ap ? ap.id.replace('page-','') : null;
        if (an && an !== 'player') fromName = an;
      }
      _visitedReturnAction = { type: 'page', name: fromName || 'home', hl: (window._pageHist || []).length };   // 735
    }
  }

  // Ziyaretçi modu state'i kaydet
  _visitedPlayerData = { player, ctx };
  try { _loadVisitorEq(player); } catch(e){}
  closePlayerModal();

  // Player sayfasına git (renderPlayerPage ziyaretçi modunu algılar)
  // ÖNEMLİ: btn=null geç — yoksa showPage içinde ziyaretçi sıfırlanır
  if(typeof showPage === 'function') {
    showPage('player', null);
    // Bottom nav highlight'ı manuel ekle
    const navBtn = (typeof findNavBtn === 'function') ? findNavBtn('player') : null;
    if(navBtn) navBtn.classList.add('active');
  }
}

// Ziyaretçi modundan çıkış — return action'a göre geri dön
function exitVisitorMode() {
  try { _visitorEqCache = null; } catch(e){}
  // 🆕 Ziyaretçi ekipman kalıntısını hemen temizle (kendi profiline dönünce eskisi görünmesin)
  try { if (typeof _eqData !== 'undefined') _eqData = null; } catch(e){}
  const action = _visitedReturnAction;
  // State'leri temizle (showPage/viewTeam çağrılırken yeni state set edilebilir)
  _visitedPlayerData = null;
  _visitedReturnAction = null;
  window._pmFromPage = null;

  if (!action) { goBackPage(); return; }   // 735 — ana sayfa yerine bir önceki sayfa

  // 735 — dönüş bir geri adımıdır: geçmiş ziyaretçi profile girilmeden önceki hâline döner
  const _h = window._pageHist || [];
  if (typeof action.hl === 'number' && _h.length > action.hl) _h.length = action.hl;
  window._navBack = true;
  try {
  if (action.type === 'guestTeam' && typeof viewTeam === 'function') {
    // Misafir takıma geri dön (viewTeam yeni state ile sayfayı yeniden kurar)
    viewTeam(action.cc, action.tn);
    // viewTeam içinde _viewingTeamPrevPage = 'player' olarak set edildi (çünkü ziyaret modundan dönüşteyiz)
    // Bunu DÜZELT: snapshot'tan gelen GERÇEK prevPage'i restore et
    // (Aksi halde misafir takımdan exitGuestMode → showPage('player') → kendi profile gider)
    if (typeof _viewingTeamPrevPage !== 'undefined') {
      _viewingTeamPrevPage = action.prevPage || null;
    }
    if (typeof action.ghl === 'number') _viewingTeamHl = action.ghl;   // 735
  } else if (action.type === 'page' && typeof showPage === 'function') {
    // Normal sayfaya geri dön
    const navBtn = (typeof findNavBtn === 'function') ? findNavBtn(action.name) : null;
    showPage(action.name, navBtn);
  } else if (typeof showPage === 'function') {
    showPage('home', (typeof findNavBtn === 'function') ? findNavBtn('home') : null);
  }
  } finally { window._navBack = false; }
}

// 934 — ziyaretçi oyuncu sayfası: tek düğme. Kaptan / yardımcı için Mesaj Gönder + Teklif Sun baloncuğu, diğerlerine doğrudan mesaj
let _plZiyPayload = null;
function _plZiyEylemGuncelle(vp) {
  const b = document.getElementById('plZiyEylem'); if (!b) return;
  const uid = vp && !vp.isBot && (vp.userId || vp.user_id);
  const ben = !!(uid && typeof authUser !== 'undefined' && authUser && String(uid) === String(authUser.id));
  b.classList.toggle('var', !!(uid && !ben));
}
function plZiyaretMenu(btn) {
  const d = (typeof _visitedPlayerData !== 'undefined') ? _visitedPlayerData : null;
  if (!d || !d.player) return;
  const player = d.player, ctx = d.ctx || {};
  _plZiyPayload = JSON.stringify({ player, ctx });
  const ik = (ad) => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${_PMK_IK[ad]}</svg>`;
  let teklif = '';
  if (typeof userCanMakeOffer === 'function' && userCanMakeOffer() && !player.isBot && !ctx.isOwnTeam) {
    const ilan = (typeof _tfIlanBul === 'function') ? _tfIlanBul(player, ctx.teamName || '') : null;
    teklif = ilan
      ? `<button class="mod-satir" onclick="_modKapat();tfSatinAlAc('${ilan.id}')">${ik('etiket')}<span>Satın Al</span><span data-noi18n>· ${_tf854Eur(Number(ilan.feeEur ?? ilan.fee) || 0)}</span></button>`
      : player.role === 'captain'
      ? `<button class="mod-satir" onclick="_modKapat();tfShowToast('Kaptana teklif yapılamaz.','var(--red)')">${ik('hediye')}<span>Teklif Sun</span></button>`
      : `<button class="mod-satir" onclick="_modKapat();playerSendOffer(_plZiyPayload)">${ik('hediye')}<span>Teklif Sun</span></button>`;
  }
  // 934d — Takımını Gör: oyuncunun takımı varsa (kendi takımın değilse)
  const tcc = String(ctx.countryCode || ctx.cc || '').toUpperCase().slice(0, 2), tn = ctx.teamLookupName || (ctx.teamName !== 'Serbest' ? ctx.teamName : '') || '';
  const takim = (tcc && tn && !ctx.isOwnTeam) ? `<button class="mod-satir" onclick="_modKapat();plZiyTakimAc()">${ik('takim')}<span>Takımını Gör</span></button>` : '';
  if (!teklif && !takim) { playerSendMessage(_plZiyPayload); return; }
  _modPopEl = btn;
  _modSheet(`<button class="mod-satir" onclick="_modKapat();playerSendMessage(_plZiyPayload)">${ik('mesaj')}<span>Mesaj Gönder</span></button>` + teklif + takim);
}
// 934d — ziyaret edilen oyuncunun takımına geç; takım sayfasında Geri, yine bu oyuncunun sayfasına döner
function plZiyTakimAc() {
  const d = (typeof _visitedPlayerData !== 'undefined') ? _visitedPlayerData : null;
  if (!d || !d.player) return;
  const ctx = d.ctx || {};
  const cc = String(ctx.countryCode || ctx.cc || '').toUpperCase().slice(0, 2), tn = ctx.teamLookupName || ctx.teamName || '';
  if (!cc || !tn || tn === 'Serbest') return;
  if (typeof userHasTeam === 'function' && userHasTeam() && _userTeam.countryCode === cc && _userTeam.teamName === tn) { showPage('team', findNavBtn('team')); return; }
  window._plZiyGeri = { d, r: (typeof _visitedReturnAction !== 'undefined') ? _visitedReturnAction : null, t: Date.now() };
  viewTeam(cc, tn);
}

