      const sunucu = new Set(data.map(r => r.id)), yerel = new Set(ROSTER_DATA.filter(Boolean).map(p => p.id));
      const yeni = [...sunucu].filter(id => !yerel.has(id)), giden = [...yerel].filter(id => !sunucu.has(id));
