function _teamChatUnsubscribe() {
  if (_teamChatChannel) {
    try { window.sb.removeChannel(_teamChatChannel); } catch(e) {}
    _teamChatChannel = null;
    _teamChatChannelKey = null;
  }
}

// Sayfa açılışında kadroyu render et
document.addEventListener('DOMContentLoaded', () => {
  // Önce kullanıcı takımı bilgisini yükle (auth henüz hazır değilse zaten null kalır)
  if(typeof userTeamLoad === 'function') userTeamLoad();
  if(typeof renderRoster === 'function') renderRoster('all');
  if(typeof applyUserTeamUI === 'function') applyUserTeamUI();
  if(typeof trsSyncHeader === 'function') trsSyncHeader();
  if(typeof updateHero === 'function') updateHero();
  if(typeof syncEnergyDisplay === 'function') syncEnergyDisplay();
  // Tarih dakikada bir kontrol et — gece yarısı sezon günü kayar. SADECE ana sayfa açıkken.
  setInterval(() => {
    const _pg = document.querySelector('.page.active');
    if (!(_pg && _pg.id === 'page-home' && typeof updateHero === 'function')) return;
    // 956 — arka plandayken ağır ana sayfa çizimi ve sıralama sorguları yok; bildirim / sezon kontrolleri aynen sürer;
    //   görünür olunca bir kez tazelenir
    if (document.hidden) {
      try { if (typeof checkSeasonEndTrigger === 'function') checkSeasonEndTrigger(); } catch(e) {}
      try { if (typeof checkContractExpiration === 'function') checkContractExpiration(); } catch(e) {}
      try { if (typeof runAllNotificationChecks === 'function') runAllNotificationChecks(); } catch(e) {}
      window._hmGizliKacti = true;
      return;
    }
    updateHero();
  }, 60000);
  document.addEventListener('visibilitychange', () => {   // 956
    if (document.hidden || !window._hmGizliKacti) return;
    window._hmGizliKacti = false;
    const _pg = document.querySelector('.page.active');
    if (_pg && _pg.id === 'page-home' && typeof updateHero === 'function') { try { updateHero(); } catch(e) {} }
  });
});


