// ── Formasyon Uygula ──
function applyFormation(name) {
  // 🆕 İZOLASYON GARANTİSİ — Milli takım state snapshot
  const _ntFormSnap = (typeof _ntCurrentFormation !== 'undefined') ? _ntCurrentFormation : null;
  const _ntLineupSnap = (typeof _ntActivePitchPlayers !== 'undefined' && Array.isArray(_ntActivePitchPlayers))
    ? _ntActivePitchPlayers.map(e => ({ ...e })) : null;

  name = formasyonTasi(name).ad;   // 585
  currentFormation = name;
  const slots = FORMATIONS[name];
  activePitchPlayers.forEach((entry, i) => {
    const slot = slots[i] || slots[0];
    entry.x   = slot.x;
    entry.y   = slot.y;
    entry.pos = slot.pos;
    entry.s   = slot.s;
  });
  renderPitch();
  saveTeamStrategy();

  // 🆕 İZOLASYON KONTROLÜ — Milli takım bozulduysa restore
  if (_ntFormSnap !== null && typeof _ntCurrentFormation !== 'undefined' && _ntCurrentFormation !== _ntFormSnap) {
    console.warn('[club-isolation] Milli takım formasyonu yan etkiyle değişti, restore ediliyor:', _ntFormSnap);
    _ntCurrentFormation = _ntFormSnap;
    try {
      const _pl = document.getElementById('ntFormationPickLabel');
      if (_pl) _pl.textContent = _ntFormSnap;
    } catch(e) {}
  }
  if (_ntLineupSnap && typeof _ntActivePitchPlayers !== 'undefined' && Array.isArray(_ntActivePitchPlayers)) {
    let changed = false;
    if (_ntActivePitchPlayers.length !== _ntLineupSnap.length) changed = true;
    else {
      for (let i = 0; i < _ntLineupSnap.length; i++) {
        const cur = _ntActivePitchPlayers[i], snap = _ntLineupSnap[i];
        if (!cur || cur.x !== snap.x || cur.y !== snap.y || cur.pos !== snap.pos || cur.slotIdx !== snap.slotIdx) {
          changed = true; break;
        }
      }
    }
    if (changed) {
      console.warn('[club-isolation] Milli takım dizilişi yan etkiyle değişti, restore ediliyor');
      _ntLineupSnap.forEach((snap, i) => {
        if (_ntActivePitchPlayers[i]) Object.assign(_ntActivePitchPlayers[i], snap);
      });
    }
  }
}

async function flushTeamStrategySave() {
  if (typeof takimTaktikYazilamaz === 'function' && takimTaktikYazilamaz()) return;   // 584
  // Bekleyen debounce yazmayı iptal edip son cache'i ANINDA Supabase'e yaz.
  // Böylece sayfadan çıkış/maç başlangıcında en son kayıt garanti geçerli olur.
  // 899 — yalnız yazılmamış değişiklik varsa (eskiden her sayfa geçişinde herkes için yazma deneniyordu)
  if (!_teamStrategySaveTimer) return;
  clearTimeout(_teamStrategySaveTimer);
  _teamStrategySaveTimer = null;
  if (!_canManageSquad()) return;
  if (window.sb && _userTeam && _userTeam.countryCode && _userTeam.teamName && _teamStrategyCache) {
    const _kayit = _teamStrategyCache;
    const { error: _dzErr } = await window.sb.from('team_data').upsert({
      country_code: _userTeam.countryCode,
      team_name: _userTeam.teamName,
      data_key: 'strategy',
      data: _kayit,
      updated_at: new Date().toISOString()
    }, { onConflict: 'country_code,team_name,data_key' });
    if (!_dzErr) _kadroDizilisYayinla(_kayit);   // 768
  }
}

async function saveFormation() {
  if (typeof takimTaktikKilitUyari === 'function' && takimTaktikKilitUyari()) return;   // 584 — canlı maç kilidi
  // 🆕 Sadece kaptan/yardımcı kaydedebilir
  if (typeof _canManageSquad === 'function' && !_canManageSquad()) {
    if (typeof showToast === 'function') showToast('Sadece kaptan veya yardımcı diziliş kaydedebilir');
    return;
  }
  // 🆕 İlk 11 tam dolu değilse kaydetme
  const _liveCnt = Array.isArray(activePitchPlayers) ? activePitchPlayers.filter(e => e && e.player).length : 0;
  if (_liveCnt < 11) {
    if (typeof showToast === 'function') showToast('İlk 11 tamamlanmadan kaydedilemez (' + _liveCnt + '/11)');
    return;
  }
  // 🆕 GERÇEK KAYIT — strateji + formasyon + diziliş
  // saveTeamStrategy() debounce'lu (500ms). Manuel "Kaydet" tıklanınca
  // pending timer'ı iptal edip ANINDA yazıp toast'ı write sonrası göster.
  try { saveTeamStrategy(); } catch(e){}
  try { await flushTeamStrategySave(); } catch(e) { console.warn('[saveFormation] write hata:', e); }

  // Toast
  const toast = document.createElement('div');
  toast.style.cssText = 'position:fixed;bottom:90px;left:50%;transform:translateX(-50%);background:var(--accent);color:var(--bg);padding:8px 18px;border-radius:20px;font-size:12px;font-weight:700;z-index:9999;font-family:Twemoji Country Flags,"Barlow Condensed",sans-serif;letter-spacing:.5px';
  toast.textContent = '✅ Diziliş kaydedildi!';
  document.body.appendChild(toast);
  setTimeout(()=>toast.remove(), 2000);
}

