  // İlk başkan: 1. tier en yüksek influence — en büyük kulüp kaptanı
  const sorted = members.slice().sort((a,b) => b.influence - a.influence);
  const presId = sorted[0] ? sorted[0].id : null;
  const vpIds = sorted.slice(1, 4).map(m => m.id); // 3 yardımcı
