function fedActiveCountry() {
  // 862 — FEDERASYON = uyruğun federasyonu (kaptan olsun olmasın; 825'te yalnız kaptanlar içindi).
  //   Üyelik değişmez: kulübü başka ülkedeki kaptan uyruğunun federasyonuna üye (825), diğerleri İzleyici.
  //   Uyruk oyundaki ülkelerden değilse kulübünün ülkesi; takımsızsa uyruğu. Milli takım sayfası ntActiveCountry() ile.
  try {
    const _uy = (typeof authUser !== 'undefined' && authUser && authUser.nationality) ? String(authUser.nationality).toUpperCase() : '';
    if (_uy && typeof _cftGetCountry === 'function' && _cftGetCountry(_uy)) return _uy;
    if(typeof _userTeam !== 'undefined' && _userTeam && _userTeam.countryCode) return _userTeam.countryCode;
    if(typeof authUser !== 'undefined' && authUser && authUser.nationality) return authUser.nationality;
  } catch(e) {}
  return 'TR';
}

// 572 — KENDİ MİLLİ TAKIMIN = UYRUĞUN (kulübün hangi ülkede olduğu fark etmez)
function ntOwnCountry() {
  try {
    if (typeof authUser !== 'undefined' && authUser && authUser.nationality) return authUser.nationality;
    if (typeof _userTeam !== 'undefined' && _userTeam && _userTeam.countryCode) return _userTeam.countryCode;
  } catch(e) {}
  return 'TR';
}
// Milli takım sayfasında görüntülenen ülke
function ntActiveCountry() {
  try { if (window._ntViewingCC) return window._ntViewingCC; } catch(e) {}
  return ntOwnCountry();
}
window.ntActiveCountry = ntActiveCountry;
window.ntOwnCountry = ntOwnCountry;

// Görüntülenen ülke değişince eski ülkenin diziliş/yedek/strateji durumunu bırak
let _ntSonCC = null;
function _ntUlkeDegistiKontrol() {
  const cc = ntActiveCountry();
  if (_ntSonCC === cc) return false;
  _ntSonCC = cc;
  try { NT_ROSTER_DATA = []; _ntCachedCC = null; } catch(e) {}
  try { _ntActivePitchPlayers = []; } catch(e) {}
  try { _ntMatchSquadBench = []; _ntBenchUserManaged = false; } catch(e) {}
  try { _ntStrategyCache = null; _ntStrategyCC = null; _ntDizilisDurum = 'yok'; } catch(e) {}
  try { if (typeof _ntChatAboneKapat === 'function') _ntChatAboneKapat(); } catch(e) {}
  return true;
}

// 🆕 Başka bir ülkenin milli takımını aç — ziyaretçi, ya da o ülkede başkan/yardımcıysan yönetici
function ntViewAsGuest(cc) {
  if (!cc || typeof _cftGetCountry !== 'function' || !_cftGetCountry(cc)) return;
  window._ntViewingCC = (cc === ntOwnCountry()) ? null : cc;
  _ntUlkeDegistiKontrol();
  try { if (typeof ntRolYukle === 'function') ntRolYukle(cc); } catch(e) {}
  const pageEl = document.getElementById('page-national');
  if (pageEl) pageEl.classList.toggle('nt-guest-mode', !!window._ntViewingCC && !(typeof ntRol === 'function' && ntRol(cc)));
  if (typeof showPage === 'function') showPage('national');
  setTimeout(() => { try { _ntZiyaretciModuUygula(); } catch(e) {} }, 30);
}
// 572 — Federasyon başkanı / yardımcısı: yönettiği milli takımı aç (başka ülkenin milli takımı olabilir)
function ntYonet(cc) { ntViewAsGuest(cc || fedActiveCountry()); }
window.ntYonet = ntYonet;

// Kendi milli takımına dön
function ntExitGuest() {
  window._ntViewingCC = null;
  _ntUlkeDegistiKontrol();
  const pageEl = document.getElementById('page-national');
  if (pageEl) pageEl.classList.remove('nt-guest-mode');
  if (typeof ntRender === 'function') ntRender();
  try { _ntZiyaretciModuUygula(); } catch(e) {}
  const activeTab = document.querySelector('#page-national .team-tab.active');
  if (activeTab) {
    const tab = activeTab.dataset.ntTab;
    if (tab && typeof ntTab === 'function') ntTab(tab, activeTab);
  }
}

function fedTab(name, el) {
  const PANES = ['board','members','election','powers'];
  PANES.forEach(t => {
    const e = document.getElementById('fed-' + t);
    if(e) e.style.display = t === name ? 'block' : 'none';
  });
  document.querySelectorAll('#page-federation .team-tab').forEach(t => t.classList.remove('active'));
  if(el) el.classList.add('active');
  if(name === 'members') fedRenderMembers();
  if(name === 'board')   fedRenderBoard();
  if(name === 'powers')  fedRenderPowers();
  if(name === 'election'){ fedTickElection(fedActiveCountry()); fedRenderElection(); }
}

