// 🆕 T.D. Profil Düzenleme Modal
function openCoachEditModal() {
  if (typeof getCoachProfile !== 'function') return;
  const cc = fedActiveCountry();
  const pres = fedGetPresident(cc);
  if (!pres || !pres.isUser) return;
  const profile = getCoachProfile(pres.id, true);

  // Trait grid doldur
  const grid = document.getElementById('coachTraitGrid');
  if (grid && typeof COACH_TRAITS !== 'undefined') {
    grid.innerHTML = Object.entries(COACH_TRAITS).map(([key, t]) => {
      const sel = profile.trait === key ? 'selected' : '';
      return `<button class="coach-trait-opt ${sel}" data-trait="${key}" onclick="selectCoachTrait('${key}')">
        <div class="coach-trait-lbl">${t.label}</div>
      </button>`;
    }).join('');
  }
  // Slider'ı set et
  const slider = document.getElementById('coachSkillSlider');
  const sliderVal = document.getElementById('coachSkillSliderVal');
  if (slider) slider.value = profile.skill;
  if (sliderVal) sliderVal.textContent = profile.skill;
  // Mevcut seçim kaydedilmiş trait
  window._coachEditTrait = profile.trait;

  const ov = document.getElementById('coachEditOverlay');
  if (ov) ov.classList.add('open');
}

function selectCoachTrait(key) {
  window._coachEditTrait = key;
  const grid = document.getElementById('coachTraitGrid');
  if (grid) {
    grid.querySelectorAll('.coach-trait-opt').forEach(b => {
      b.classList.toggle('selected', b.dataset.trait === key);
    });
  }
}

function closeCoachEditModal() {
  const ov = document.getElementById('coachEditOverlay');
  if (ov) ov.classList.remove('open');
}

function saveCoachProfile() {
  const slider = document.getElementById('coachSkillSlider');
  const skill = slider ? parseInt(slider.value, 10) : 60;
  const trait = window._coachEditTrait || 'tactician';
  // 🆕 Supabase user_player.coach_profile
  _coachProfileCache = { skill, trait };
  if (window.sb && authUser && authUser.id) {
    clearTimeout(_coachProfileSaveTimer);
    _coachProfileSaveTimer = setTimeout(async () => {
      try {
        await window.sb.from('user_player').update({
          coach_profile: { skill, trait }
        }).eq('user_id', authUser.id);
      } catch(e) { console.warn('[coach_profile] save hata:', e); }
    }, 500);
  }
  closeCoachEditModal();
  // Re-render panel
  // 🆕 T.D. profil paneli kaldırıldı
  // Toast
  if (typeof fedShowToast === 'function') {
    fedShowToast('T.D. profilin güncellendi ✓', 'ok');
  }
}

