      // sayfa kapalıyken kurulmuş kadro eski T.D. ile kalmasın: bir dahaki açılışta yeniden kurulur
      if (_ntCachedCC === cc && _ntRosterTD[cc] !== _ntTdNtId(cc, ntPlayerPool(cc) || [])) { NT_ROSTER_DATA = []; _ntCachedCC = null; }
      return;
