  { const _pg = document.getElementById('page-national'); if (_pg && !_pg.classList.contains('active')) return; }
  _ntUlkeDegistiKontrol();
  const cc = ntActiveCountry();
  if (typeof _loadNtPoolFromServer === 'function') _loadNtPoolFromServer(cc).catch(()=>{});
  if (typeof ntRolYukle === 'function') ntRolYukle(cc).then(() => { try { _ntZiyaretciModuUygula(); } catch(e) {} }).catch(()=>{});
  if (typeof _loadNtSquadFromServer === 'function') _loadNtSquadFromServer(cc)
    .then(() => { try { _ntZiyaretciModuUygula(); } catch(e) {} }).catch(()=>{});
  // Federasyon durumu ilk kez gelince başlık (T.D.) bir kez yenilenir — önbellekten dönüşte döngü olmasın
  const _fedVardi = !!(typeof _fedStateLoaded !== 'undefined' && _fedStateLoaded[cc]);
  if (typeof _loadFedStateFromServer === 'function') _loadFedStateFromServer(cc)
