    const avg = arr => arr.length ? Math.round(arr.reduce((s,v)=>s+v,0)/arr.length) : 0;
    const ls = { GK:avg(buckets.GK), DEF:avg(buckets.DEF), MID:avg(buckets.MID), FWD:avg(buckets.FWD) };
