// ─────────────────────────────────────────────────────────
// MİLLİ TAKIM Bot Kadrosu (şimdilik %100 bot, gerçek oyuncular geldiğinde silinecek)
// ─────────────────────────────────────────────────────────

// 583 — 20 kişilik kadro: 2 GK + 6 DEF + 6 MID + 6 FWD (maç günü 11 + 7 yedek = 18 kişi).
//   Yeni forvet yerleri (18, 20) SONA eklendi: kayıtlı kadrolardaki yer sırası değişmez.
const NT_SQUAD_SLOTS = [
  // Kaleci (2)
  { num:1,  pos:'GK',  role:'starter' },
  { num:12, pos:'GK',  role:'sub'     },
  // Defans (6)
  { num:2,  pos:'DEF', role:'starter' }, { num:3,  pos:'DEF', role:'starter' },
  { num:4,  pos:'DEF', role:'starter' }, { num:5,  pos:'DEF', role:'starter' },
  { num:13, pos:'DEF', role:'sub'     }, { num:14, pos:'DEF', role:'sub'     },
  // Orta saha (6)
  { num:6,  pos:'MID', role:'starter' }, { num:8,  pos:'MID', role:'starter' },
  { num:10, pos:'MID', role:'starter' }, { num:7,  pos:'MID', role:'starter' },
  { num:15, pos:'MID', role:'sub'     }, { num:16, pos:'MID', role:'sub'     },
  // Forvet (4)
  { num:9,  pos:'FWD', role:'starter' }, { num:11, pos:'FWD', role:'starter' },
  { num:17, pos:'FWD', role:'sub'     }, { num:19, pos:'FWD', role:'sub'     },
  { num:18, pos:'FWD', role:'sub'     }, { num:20, pos:'FWD', role:'sub'     }
];

function _ntSeed(cc, idx) {
  let h = 0;
  for(let i = 0; i < cc.length; i++) h = ((h << 5) - h + cc.charCodeAt(i)) & 0x7fffffff;
  h = ((h * 31) ^ (idx * 2654435761)) & 0x7fffffff;
  return h / 0x7fffffff;
}

// ═══════════════════════════════════════════════════════════════════
// 572 — MİLLİ TAKIM HAVUZU / KADRO / YETKİ (sunucu kuralıyla birebir)
//   • Havuz: uyruğu bu ülke olan TÜM oyuncular (kulübü hangi ülkede olursa olsun),
//     sayfalı okuma (en fazla 4000), gerçek güce göre sıralı. Kimlik (ntId) = oyuncu
//     uuid'i; kullanıcının kendisi 'USER'.
//   • Kadro: başkanın kaydı (nt_squad, 20 yer) varsa o; boş yerleri maç anında sunucu
//     aynı mevkiden en güçlü BOT oyuncuyla doldurur (ekranda "OTO"). Kayıt yoksa en
//     güçlü 20 (2 KL · 6 DF · 6 OS · 6 FV). 583: seçili kadro esnek (12–20), boş yer boş kalır.
//   • Yetki: federasyon başkanı (kulüp kaptanı) + başkanın seçtiği en fazla 3 yardımcı.
//     Yetki sunucudan okunur (nt_rolum); yazmalar sunucu RPC'leriyle denetlenir.
// ═══════════════════════════════════════════════════════════════════
const _ntPoolCache = {};      // cc -> [entry]
const _ntPoolLoading = {};    // cc -> Promise
const _ntPoolT = {};          // cc -> okuma zamanı
const _ntPoolBekleSay = {};   // 798 — oturum beklerken deneme sayısı
const NT_HAVUZ_KOLON = 'id, user_id, country_code, team_name, num, name, pos, pos_group, sub_pos, ek_mevki, ozel_yetenek, ozel_aktif, nationality, nation, level, xp, overall, rating, abilities, role, avatar, avatar_id, gender, is_bot, last_seen, user_team_data, injury_until, nt_ban, kondisyon, kondisyon_at, kondisyon_hiz, motivasyon, motivasyon_at';
const _NT_POSG = { KL:'GK', GK:'GK', STB:'DEF', SB:'DEF', CB:'DEF', RB:'DEF', LB:'DEF', DEF:'DEF',
  DOS:'MID', OS:'MID', SAK:'MID', SOK:'MID', CAM:'MID', DM:'MID', CM:'MID', RM:'MID', LM:'MID', AM:'MID', MID:'MID',
  FWD:'FWD', RF:'FWD', LF:'FWD', ST:'FWD' };
// Mevki grubu — sunucudaki _pg ile aynı öncelik (pos_group, sonra pos)
function _ntGrp(p) {
  if (!p) return 'MID';
  const g = p.posGroup || p.pos_group;
  if (g && _NT_POSG[g]) return _NT_POSG[g];
  return _NT_POSG[p.pos] || 'MID';
}
const _NT_MEVKI_AD = { GK:'Kaleci', DEF:'Defans', MID:'Orta saha', FWD:'Forvet' };
const _NT_MEVKI_KOTA = { GK:2, DEF:6, MID:6, FWD:6 };   // 583 — 20 kişi
function _ntUlkeAdi(cc) { const c = (typeof _cftGetCountry === 'function') ? _cftGetCountry(cc) : null; return (c && c.name) || cc; }

function _ntHavuzSatiri(r, cc, myUid) {
  let bg = '#222', tc = '#fff', short = (r.team_name || '—').slice(0, 3).toUpperCase();
  const oc = (typeof _cftGetCountry === 'function') ? _cftGetCountry(r.country_code) : null;
  const _e958 = (oc && oc.leagues) ? _tmBul('ulke', r.country_code, r.team_name) : null;   // 958 — takım dizini
  if (_e958) { const t = _e958.t; bg = t.bg || bg; tc = t.tc || tc; short = t.short || short; }
  else if (_e958 === undefined && oc && oc.leagues) {
    for (const lg of oc.leagues) {
      const t = (lg.teams || []).find(x => x.name === r.team_name);
      if (t) { bg = t.bg || bg; tc = t.tc || tc; short = t.short || short; break; }
    }
  }
  const benim = !!(myUid && r.user_id === myUid);
  return {
    id: r.id, num: r.num, name: r.name, pos: r.pos, posGroup: r.pos_group, subPos: r.sub_pos, ekMevki: r.ek_mevki || [], oy: r.ozel_yetenek || [], oyAktif: r.ozel_aktif,
    overall: r.overall || 10, rating: r.rating || 10, level: r.level || 0, xp: r.xp || 0,
    abilities: r.abilities, role: r.role || 'member',
    nation: r.nation || ccToFlag(r.nationality || cc), nationality: r.nationality || cc,
    avatar: r.avatar || (r.is_bot ? '🤖' : '👤'),
    avatar_id: r.avatar_id || null, user_id: r.user_id || null, userId: r.user_id || null,
    lastSeen: r.last_seen || null,
    injuryUntil: r.injury_until || null, ntBan: Number(r.nt_ban) || 0,
    _kd: (typeof konHam === 'function') ? konHam(r) : null,                                          // 580
    stamina: (typeof konHam === 'function' && konHam(r)) ? konSimdiC(konHam(r)) : undefined,
    _mt: (typeof motHam === 'function') ? motHam(r) : null,                                     // 845 — moral
    motivasyon: (typeof motHam === 'function') ? motSimdiC(motHam(r)) : undefined,
    isBot: !!r.is_bot, isUser: benim,
    ntId: benim ? 'USER' : r.id,
    sourceClub: r.team_name || 'Serbest', clubCC: r.country_code || cc,
    clubBg: bg, clubTc: tc, clubShort: short
  };
}
function _ntHavuzSirala(pool) {
  pool.forEach(p => { try { p._ntG = (typeof _ntPlayerSkill === 'function') ? _ntPlayerSkill(p) : (p.overall || 0); } catch(e) { p._ntG = p.overall || 0; } });
  // Kararlı sıralama: eşit güçte sunucudaki gibi id sırası korunur
  return pool.sort((a, b) => (b._ntG || 0) - (a._ntG || 0));
}

async function _loadNtPoolFromServer(cc, zorla) {
  if (!window.sb || !cc) return null;
  if (_ntPoolCache[cc] && !zorla) return _ntPoolCache[cc];
  if (_ntPoolLoading[cc]) return _ntPoolLoading[cc];
  if (!((typeof authUser !== 'undefined' && authUser && authUser.id))) {   // 798
    _ntPoolBekleSay[cc] = (_ntPoolBekleSay[cc] || 0) + 1;
    if (_ntPoolBekleSay[cc] <= 15) setTimeout(() => { _loadNtPoolFromServer(cc, zorla).catch(()=>{}); }, 2000);
    return _ntPoolCache[cc] || null;
  }
  _ntPoolBekleSay[cc] = 0;
  _ntPoolLoading[cc] = (async () => {
    const rows = [];
    let hata = false;
    for (let from = 0; from < 4000; from += 1000) {
      const { data, error } = await window.sb.from('players').select(NT_HAVUZ_KOLON)
        .eq('nationality', cc).order('id', { ascending: true }).range(from, from + 999);
      if (error) { console.warn('[ntPool] hata:', error.message || error); hata = true; break; }
      if (!data || !data.length) break;
      rows.push(...data);
      if (data.length < 1000) break;
    }
    _ntPoolLoading[cc] = null;
    if (hata && !rows.length) return _ntPoolCache[cc] || null;
    const myUid = (typeof authUser !== 'undefined' && authUser && authUser.id) || null;
    if (!myUid) { setTimeout(() => { _loadNtPoolFromServer(cc, true).catch(()=>{}); }, 1200); return _ntPoolCache[cc] || null; }   // 585
    const pool = _ntHavuzSirala(rows.map(r => _ntHavuzSatiri(r, cc, myUid)));
    _ntPoolCache[cc] = pool;
    _ntPoolT[cc] = Date.now();
    try { await _ntEksikOyunculariGetir(cc); } catch(e) {}
    if (cc === ntActiveCountry()) {
      NT_ROSTER_DATA = []; _ntCachedCC = null;
      if (typeof ntRender === 'function') ntRender();
      if (typeof _ntRefreshActivePane === 'function') _ntRefreshActivePane();
    }
    return pool;
  })();
  return _ntPoolLoading[cc];
}

function ntPlayerPool(cc) {
  if (_ntPoolCache[cc]) {
    // 10 dakikada bir arka planda tazele (sakatlık / ceza / yeni oyuncular)
    if (window.sb && Date.now() - (_ntPoolT[cc] || 0) > 600000 && !_ntPoolLoading[cc]) _loadNtPoolFromServer(cc, true).catch(()=>{});
    return _ntPoolCache[cc];
  }
  if (window.sb) _loadNtPoolFromServer(cc).catch(()=>{});
  return [];
}

// Kadroda/yardımcıda olup havuzda olmayan (havuz sınırı) oyuncuları ayrıca getir
async function _ntEksikOyunculariGetir(cc) {
  const pool = _ntPoolCache[cc];
  if (!pool || !window.sb) return;
  const var_ = new Set(pool.map(p => p.id));
  const iste = [].concat(_ntSquadCache[cc] || [], _ntVicesCache[cc] || []).filter(u => u && !var_.has(u));
  if (!iste.length) return;
  const { data } = await window.sb.from('players').select(NT_HAVUZ_KOLON).in('id', Array.from(new Set(iste)));
  if (!Array.isArray(data) || !data.length) return;
  const myUid = (typeof authUser !== 'undefined' && authUser && authUser.id) || null;
  data.forEach(r => { if (r && r.nationality === cc && !var_.has(r.id)) pool.push(_ntHavuzSatiri(r, cc, myUid)); });
  _ntHavuzSirala(pool);
}

// ── Sunucu kayıtları (tek sorgu): başkanın kadrosu, yardımcılar, sunucunun güncel çağrı listesi
const _ntSquadCache = {};      // cc -> [uuid|null] (20 yer) | null (kayıt yok)
const _ntSquadLoading = {};
const _ntSquadLoaded = {};     // cc -> okuma zamanı
const _ntSquadUuidByCc = {};   // cc -> Set(uuid) — profil 'Milli Takım Oyuncusu' rozeti
const _ntSnapUidByCc = {};     // cc -> Set(user_id) — sunucunun son çağrı listesi (gerçek kullanıcılar)
const _ntVicesCache = {};      // cc -> [uuid]
const _ntVicesLoaded = {};
let _ntSquadSaveTimer = null;

const _ntSquadBekle = {}, _ntSquadBekleSay = {};
async function _loadNtSquadFromServer(cc, zorla) {
  if (!window.sb || !cc) return _ntSquadCache[cc] || null;
  if (_ntSquadLoaded[cc] && !zorla && Date.now() - _ntSquadLoaded[cc] < 60000) return _ntSquadCache[cc] || null;
  if (_ntSquadLoading[cc]) return _ntSquadLoading[cc];
  // 585 — ülke listesi ya da oturum henüz hazır değilken okunan boş sonuç "kayıt yok" sayılıyor,
  //   kayıtlı kadro yerine otomatik 20'li kadro gösteriliyordu (sayfa değişince düzeliyordu).
  //   Hazır olana kadar yükleme sayılmaz; kısa aralıkla yeniden denenir.
  const _ad = (typeof _cftGetCountry === 'function' && _cftGetCountry(cc)) ? _cftGetCountry(cc).name : null;
  const _uid = (typeof authUser !== 'undefined' && authUser && authUser.id) || null;
  if (!_ad || !_uid) {
    _ntSquadBekleSay[cc] = (_ntSquadBekleSay[cc] || 0) + 1;   // 798 — sonsuz bekleme yok
    if (!_ntSquadBekle[cc] && _ntSquadBekleSay[cc] <= 25) _ntSquadBekle[cc] = setTimeout(() => { _ntSquadBekle[cc] = null; _loadNtSquadFromServer(cc, true).catch(()=>{}); }, 1200);
    return _ntSquadCache[cc] || null;
  }
  _ntSquadLoading[cc] = (async () => {
    const { data, error } = await window.sb.from('team_data').select('data_key, data')
      .eq('country_code', cc).eq('team_name', _ad)
      .in('data_key', ['nt_squad', 'nt_vices', 'nt_notify_snapshot']);
    _ntSquadLoading[cc] = null;
    if (error) { console.warn('[ntSquad] hata:', error.message || error); return _ntSquadCache[cc] || null; }
    const eski = JSON.stringify([_ntSquadCache[cc] || null, _ntVicesCache[cc] || []]);
    const by = {}; (data || []).forEach(r => { if (r && r.data_key) by[r.data_key] = r.data; });
    const sq = Array.isArray(by.nt_squad) ? by.nt_squad.slice(0, NT_SQUAD_SLOTS.length).map(x => x || null) : null;
    _ntSquadCache[cc] = (sq && sq.some(Boolean)) ? sq : null;
    _ntSquadUuidByCc[cc] = new Set((sq || []).filter(Boolean));
    _ntVicesCache[cc] = Array.isArray(by.nt_vices) ? by.nt_vices.filter(Boolean) : [];
    _ntVicesLoaded[cc] = true;
    _ntSnapUidByCc[cc] = new Set(Array.isArray(by.nt_notify_snapshot) ? by.nt_notify_snapshot.map(String) : []);
    _ntSquadLoaded[cc] = Date.now();
    try { await _ntEksikOyunculariGetir(cc); } catch(e) {}
    if (cc === ntOwnCountry() && typeof oyKartTazele === 'function') setTimeout(() => { try { oyKartTazele(); } catch(e) {} }, 0);   // 838
    if (cc === ntActiveCountry()) {
      if (eski !== JSON.stringify([_ntSquadCache[cc] || null, _ntVicesCache[cc] || []])) { NT_ROSTER_DATA = []; _ntCachedCC = null; }
      try { if (typeof ntRender === 'function') ntRender(); } catch(e) {}
      try { if (typeof _ntRefreshActivePane === 'function') _ntRefreshActivePane(); } catch(e) {}
    }
    return _ntSquadCache[cc];
  })();
  return _ntSquadLoading[cc];
}

// Başkanın kayıtlı kadrosu (ntId, 20 yer) — kayıt yoksa null
function ntLoadSquadIds(cc) {
  if (window.sb && (!_ntSquadLoaded[cc] || Date.now() - _ntSquadLoaded[cc] > 60000)) _loadNtSquadFromServer(cc).catch(()=>{});
  const sq = _ntSquadCache[cc];
  if (!Array.isArray(sq)) return null;
  const me = (_ntPoolCache[cc] || []).find(p => p && p.isUser);
  const out = sq.map(u => (u && me && me.id === u) ? 'USER' : (u || null));
  while (out.length < NT_SQUAD_SLOTS.length) out.push(null);
  return out;
}

// Sunucu hata kodları → okunur mesaj
function ntHataMetni(error, varsayilan) {
  const h = String((error && (error.message || error.hint || error)) || '');
  const M = [
    ['nt_yalniz_baskan', 'Yardımcıları yalnız federasyon başkanı seçer'],
    ['nt_yardimci_3', 'En fazla 3 yardımcı seçilebilir'],
    ['nt_kadro_20', 'Milli takım kadrosu en fazla 20 kişi olabilir'],
    ['nt_turnuva_kilit', _NT_TURNUVA_KILIT],
    ['nt_kadro_18', 'Milli takım kadrosu en fazla 18 kişi olabilir'],
    ['nt_sohbet_yetkisiz', 'Milli takım sohbetine yalnızca kadrodakiler ve teknik ekip yazabilir.'],
    ['nt_yetkisiz', 'Bu milli takımda yetkin yok (yalnız başkan ve yardımcıları)'],
    ['milli_mac_saati', 'Bu saatte milli maç var — hazırlık maçı oynanamaz']
  ];
  const b = M.find(x => h.indexOf(x[0]) !== -1);
  return b ? b[1] : (varsayilan || 'İşlem yapılamadı');
}

function ntSaveSquadIds(cc, ids) {
  const pool = _ntPoolCache[cc] || [];
  const me = pool.find(p => p && p.isUser);
  const uuids = (ids || []).slice(0, NT_SQUAD_SLOTS.length)
    .map(id => id === 'USER' ? (me ? me.id : null) : (id || null));
  while (uuids.length < NT_SQUAD_SLOTS.length) uuids.push(null);
  const onceki = Array.isArray(_ntSquadCache[cc]) ? _ntSquadCache[cc].slice() : null;
  _ntSquadCache[cc] = uuids;                                  // ekrana anında yansır
  _ntSquadUuidByCc[cc] = new Set(uuids.filter(Boolean));
  if (!window.sb) return;
  if (_ntSquadSaveTimer) clearTimeout(_ntSquadSaveTimer);
  _ntSquadSaveTimer = setTimeout(() => {
    _ntSquadSaveTimer = null;
    window.sb.rpc('nt_kadro_kaydet', { p_cc: cc, p_ids: uuids }).then(({ error }) => {
      if (!error) return;
      console.warn('[ntSquad] kayıt reddedildi:', error.message || error);
      _ntSquadCache[cc] = onceki;
      _ntSquadUuidByCc[cc] = new Set((onceki || []).filter(Boolean));
      if (typeof showToast === 'function') showToast(ntHataMetni(error, 'Kadro kaydedilemedi'));
      _ntKadroDegisti(cc, true);
      _loadNtSquadFromServer(cc, true).catch(()=>{});
    }, (e) => {
      console.warn('[ntSquad] kayıt bağlantı hatası:', e);
      if (typeof showToast === 'function') showToast('Kadro kaydedilemedi — bağlantını kontrol et');
    });
  }, 400);
}

// ── Yardımcılar (başkan seçer, en fazla 3, milli takım oyuncusu gerçek kullanıcılar)
function ntLoadVices(cc) {
  if (window.sb && !_ntVicesLoaded[cc]) _loadNtSquadFromServer(cc).catch(()=>{});
  return _ntVicesCache[cc] || [];
}
function ntSaveVices(cc, uuids) {
  if (!window.sb) return;
  if (ntRol(cc) !== 'baskan') { if (typeof showToast === 'function') showToast('Yardımcıları yalnız federasyon başkanı seçer'); return; }
  const onceki = (_ntVicesCache[cc] || []).slice();
  _ntVicesCache[cc] = (uuids || []).filter(Boolean).slice(0, 3);
  _ntKadroDegisti(cc, true);
  window.sb.rpc('nt_yardimci_ata', { p_cc: cc, p_ids: _ntVicesCache[cc] }).then(({ data, error }) => {
    if (error) {
      _ntVicesCache[cc] = onceki;
      if (typeof showToast === 'function') showToast(ntHataMetni(error, 'Yardımcı kaydedilemedi'));
    } else if (data && Array.isArray(data.yardimci)) {
      _ntVicesCache[cc] = data.yardimci;
    }
    try { delete _fedYrdOnb[cc]; } catch(e) {}
    _ntKadroDegisti(cc, true);
  }, () => { _ntVicesCache[cc] = onceki; _ntKadroDegisti(cc, true); });
}
// Kullanıcının kendi oyuncu uuid'i
function _ntUserUuid(cc) {
  try {
    if (window._benimOyuncuId) return window._benimOyuncuId;
    const u = (ntPlayerPool(cc) || []).find(p => p && p.isUser);
    return u ? u.id : null;
  } catch(e) { return null; }
}
// Kullanıcı bu milli takımda başkanın seçtiği YARDIMCI mı?
function _ntIsViceUser(cc) {
  const uid = _ntUserUuid(cc);
  if (!uid) return false;
  return (ntLoadVices(cc) || []).includes(uid);
}

// ── Yetki: sunucudan (nt_rolum) — 'baskan' | 'yardimci' | null
const _ntRolCache = {};        // cc -> { rol, t, yerel }
const _ntRolYukleniyor = {};
function _ntYerelRol(cc) {
  try {
    if (typeof fedUserRole === 'function' && fedUserRole(cc) === 'president') return 'baskan';
    if (_ntIsViceUser(cc)) return 'yardimci';
  } catch(e) {}
  return null;
}
function ntRolYukle(cc, zorla) {
  if (!window.sb || !cc) return Promise.resolve(null);
  const c = _ntRolCache[cc];
  if (c && !zorla && Date.now() - c.t < 60000) return Promise.resolve(c.yerel ? _ntYerelRol(cc) : c.rol);
  if (_ntRolYukleniyor[cc]) return _ntRolYukleniyor[cc];
  _ntRolYukleniyor[cc] = window.sb.rpc('nt_rolum', { p_cc: cc }).then(({ data, error }) => {
    _ntRolYukleniyor[cc] = null;
    const eski = c ? (c.yerel ? _ntYerelRol(cc) : c.rol) : undefined;
    if (error) { _ntRolCache[cc] = { rol: null, t: Date.now(), yerel: true }; return _ntYerelRol(cc); }
    const rol = (data === 'baskan' || data === 'yardimci') ? data : null;
    _ntRolCache[cc] = { rol, t: Date.now() };
    if (eski !== rol) {
      try {
        if (cc === ntActiveCountry()) {
          NT_ROSTER_DATA = []; _ntCachedCC = null;
          if (typeof ntRender === 'function') ntRender();
          if (typeof _ntZiyaretciModuUygula === 'function') _ntZiyaretciModuUygula();
          if (typeof _ntRefreshActivePane === 'function') _ntRefreshActivePane();
        }
        if (typeof fedActiveCountry === 'function' && fedActiveCountry() === cc) {
          const fp = document.getElementById('page-federation');
          if (fp && fp.classList.contains('active') && typeof fedRender === 'function') fedRender();
        }
      } catch(e) {}
    }
    return rol;
  }, () => { _ntRolYukleniyor[cc] = null; return null; });
  return _ntRolYukleniyor[cc];
}
function ntRol(cc) {
  cc = cc || ntActiveCountry();
  const c = _ntRolCache[cc];
  if (!c || Date.now() - c.t > 60000) ntRolYukle(cc).catch(()=>{});
  if (c && !c.yerel) return c.rol;
  return _ntYerelRol(cc);   // sunucu cevabı gelene kadar (yalnız görünüm; yazma sunucuda denetlenir)
}
// Kullanıcı bu milli takımın başkanı (T.D.) mı?
function _ntIsUserCaptain() { return ntRol(ntActiveCountry()) === 'baskan'; }

// Başkan: oyuncuyu yardımcı yap / yardımcılıktan al
function ntAddVice(rosterNtId) {
  const cc = ntActiveCountry();
  if (ntRol(cc) !== 'baskan') { if (typeof showToast === 'function') showToast('Yardımcıları yalnız federasyon başkanı seçer'); return; }
  const p = (ntPlayerPool(cc) || []).find(x => x && x.ntId === rosterNtId);
  if (!p || !p.id) { if (typeof showToast === 'function') showToast('Oyuncu bulunamadı'); return; }
  if (p.isBot || !p.user_id) { if (typeof showToast === 'function') showToast('Yalnız gerçek oyuncular yardımcı olabilir'); return; }
  if (p.isUser) { if (typeof showToast === 'function') showToast('Kendini yardımcı yapamazsın'); return; }
  const vices = (ntLoadVices(cc) || []).slice();
  if (vices.includes(p.id)) return;
  if (vices.length >= 3) { if (typeof showToast === 'function') showToast('En fazla 3 yardımcı seçilebilir'); return; }
  vices.push(p.id);
  ntSaveVices(cc, vices);
  if (typeof showToast === 'function') showToast('⭐ ' + p.name + ' yardımcı yapıldı');
}
function ntRemoveVice(rosterNtId) {
  const cc = ntActiveCountry();
  if (ntRol(cc) !== 'baskan') { if (typeof showToast === 'function') showToast('Yardımcıları yalnız federasyon başkanı seçer'); return; }
  const p = (ntPlayerPool(cc) || []).find(x => x && x.ntId === rosterNtId);
  const uid = p ? p.id : null;
  ntSaveVices(cc, (ntLoadVices(cc) || []).filter(u => u !== uid));
  if (typeof showToast === 'function') showToast((p ? p.name : 'Oyuncu') + ' yardımcılıktan alındı');
}

// Federasyon başkanının kulübünü gerçek bir kullanıcı mı yönetiyor? (yalnız bilgi amaçlı)
function ntCaptainIsUser(cc) {
  try {
    if (ntRol(cc) === 'baskan') return true;
    if (Array.isArray(_ntSquadCache[cc])) return true;   // kayıtlı kadro yalnız gerçek başkanda olur
    const st = (typeof fedLoad === 'function') ? fedLoad(cc) : null;
    if (st && st.vekilUid) return true;
    const pt = st && st.serverPresidentTeam;
    if (!pt) return false;
    const o = window._fedKaptanOnb && window._fedKaptanOnb[cc];
    if (o && o.liderGercek) return !!o.liderGercek[pt];
    if (typeof _fedKaptanlariYukle === 'function') _fedKaptanlariYukle(cc);
    return false;
  } catch(e) { return false; }
}

// ── ETKİN KADRO — sunucudaki _ntKadroKur ile aynı kural. Dönüş: 20 yerlik ntId dizisi,
//    otomatik dolan yerler ve kayıtlı kadro olup olmadığı. `kayitOverride` = varsayımsal kayıt.
function _ntEtkinKadroYer(cc, pool, kayitOverride) {
  const S = NT_SQUAD_SLOTS;
  pool = pool || ntPlayerPool(cc) || [];
  const byNt = {}; pool.forEach(p => { if (p && p.ntId) byNt[p.ntId] = p; });
  const kayit = (kayitOverride !== undefined) ? kayitOverride : ntLoadSquadIds(cc);
  const secili = Array.isArray(kayit) && kayit.some(id => id && byNt[id]);
  const ids = new Array(S.length).fill(null), oto = new Array(S.length).fill(false);
  const used = new Set();
  if (secili) {
    // 583 — başkanın kadrosu ESNEK (12–20): boş bıraktığı yerler boş kalır, ekrana ve maça
    //   otomatik oyuncu gelmez. Yalnız kadro 12'nin altındaysa ya da kaleci yoksa aynı
    //   kuralla (sunucuyla birebir) en güçlü uygun botla tamamlanır (ekranda "OTO").
    kayit.forEach((id, i) => { if (i < S.length && id && byNt[id] && !used.has(id)) { ids[i] = id; used.add(id); } });
    _ntAsgariTamamla(ids, oto, used, pool.filter(p => p.isBot), byNt);
    return { ids, oto, secili };
  }
  // Kayıt yok (başkan kadro kurmadı): en güçlü 20 (2 KL · 6 DF · 6 OS · 6 FV)
  const kaynak = pool;
  for (const g of ['GK', 'DEF', 'MID', 'FWD']) {
    for (let i = 0; i < S.length; i++) {
      if (ids[i] || S[i].pos !== g) continue;
      const p = kaynak.find(x => !used.has(x.ntId) && _ntGrp(x) === g);
      if (!p) break;
      ids[i] = p.ntId; used.add(p.ntId);
    }
  }
  for (let i = 0; i < S.length; i++) {           // mevkide oyuncu kalmadıysa diğer mevkilerin en iyileri
    if (ids[i]) continue;
    const p = kaynak.find(x => !used.has(x.ntId) && _ntGrp(x) !== 'GK');
    if (!p) break;
    ids[i] = p.ntId; used.add(p.ntId);
  }
  if (!ids.some(id => id && _ntGrp(byNt[id]) === 'GK')) {   // kalecisiz kadro olmaz
    const gk = kaynak.find(x => !used.has(x.ntId) && _ntGrp(x) === 'GK');
    if (gk) { let i = ids.findIndex(x => !x); if (i < 0) i = 1; ids[i] = gk.ntId; }
  }
  return { ids, oto, secili };
}

// 583 — Seçili kadroyu asgariye tamamla (sunucudaki _ntAsgariTamamla ile aynı kural):
//   1) kaleci yoksa en güçlü uygun kaleci, 2) kadro 12'ye ulaşana kadar en çok boş yeri
//   olan mevkiden (eşitlikte DF → OS → FV → KL) en güçlü uygun oyuncu. Boş yer = o mevkinin
//   son boş kadro yeri (forma numarası o yerinki olur).
function _ntAsgariTamamla(ids, oto, used, kaynak, byNt) {
  const S = NT_SQUAD_SLOTS;
  const yerle = (g) => {
    let i = -1;
    for (let k = S.length - 1; k >= 0; k--) if (!ids[k] && S[k].pos === g) { i = k; break; }
    if (i < 0) return false;
    const p = kaynak.find(x => x && !used.has(x.ntId) && _ntGrp(x) === g);
    if (!p) return false;
    ids[i] = p.ntId; used.add(p.ntId); oto[i] = true;
    return true;
  };
  if (!ids.some(id => id && byNt[id] && _ntGrp(byNt[id]) === 'GK')) yerle('GK');
  for (let tur = 0; tur < S.length && ids.filter(Boolean).length < NT_MIN_KADRO; tur++) {
    const bos = { GK: 0, DEF: 0, MID: 0, FWD: 0 };
    S.forEach((sl, i) => { if (!ids[i]) bos[sl.pos]++; });
    const sira = ['DEF', 'MID', 'FWD', 'GK'].filter(g => bos[g] > 0).sort((a, b) => bos[b] - bos[a]);
    if (!sira.some(g => yerle(g))) break;
  }
}

// Başkanın/yardımcının düzenlemesinin esası: kayıt varsa OTO yerler boş sayılır
// (maç anında sunucu doldurur); kayıt yoksa mevcut otomatik kadro esas alınır.
function _ntDuzenlemeTabani(cc) {
  const { ids, oto, secili } = _ntEtkinKadroYer(cc);
  return secili ? ids.map((id, i) => oto[i] ? null : id) : ids.slice();
}

// Kadro değişince ekranı ve dizilişi tazele
function _ntKadroDegisti(cc, sadeceEkran) {
  if (cc !== ntActiveCountry()) return;
  NT_ROSTER_DATA = []; _ntCachedCC = null;
  if (!sadeceEkran) {
    try { _ntPruneInvalidLineup(); _ntCompleteLineup(); ntSaveStrategy(true); } catch(e) {}
  }
  try { if (typeof ntRender === 'function') ntRender(); } catch(e) {}
  try { if (typeof _ntRefreshActivePane === 'function') _ntRefreshActivePane(); } catch(e) {}
}

// 637 — EURO Cup sürerken (34.–40. gün) milli kadroya yeni oyuncu alınamaz (sunucu da engeller)
const _NT_TURNUVA_KILIT = '🔒 EURO Cup sürüyor — turnuva bitene kadar milli kadroya yeni oyuncu alınamaz';
function ntTurnuvaKilitli() {
  const si = getSeasonInfo();
  return !si.preSeason && si.dayInSeason >= 34;
}

// Kadroya çağır (Analiz listesi / profil / diziliş)
function ntKadroCagir(ntId, cc) {
  cc = cc || ntActiveCountry();
  if (typeof ntTaktikKilitUyari === 'function' && ntTaktikKilitUyari(cc)) return false;   // 584
  if (!ntRol(cc)) { if (typeof _ntNoPermToast === 'function') _ntNoPermToast(); return false; }
  const pool = ntPlayerPool(cc);
  const player = pool.find(p => p && p.ntId === ntId);
  if (!player) { if (typeof showToast === 'function') showToast('Oyuncu havuzda bulunamadı'); return false; }
  const etkin = _ntEtkinKadroYer(cc, pool);
  const mevcut = etkin.ids.indexOf(ntId);
  if (mevcut !== -1 && !etkin.oto[mevcut]) { if (typeof showToast === 'function') showToast('Zaten milli takımda'); return false; }
  if (mevcut === -1 && ntTurnuvaKilitli()) { showToast(_NT_TURNUVA_KILIT); return false; }
  const base = _ntDuzenlemeTabani(cc);
  let hedef = -1;
  if (mevcut !== -1) hedef = mevcut;              // otomatik gelen oyuncu artık seçilmiş sayılır
  else {
    const g = _ntGrp(player);
    for (let i = NT_SQUAD_SLOTS.length - 1; i >= 0; i--) {
      if (NT_SQUAD_SLOTS[i].pos === g && !base[i]) { hedef = i; break; }
    }
    if (hedef === -1) {
      if (typeof showToast === 'function') showToast(`${_NT_MEVKI_AD[g] || 'Bu mevki'} yerleri dolu (${_NT_MEVKI_KOTA[g] || ''}/${_NT_MEVKI_KOTA[g] || ''}) — önce bu mevkiden birini çıkar`);
      return false;
    }
  }
  base[hedef] = ntId;
  ntSaveSquadIds(cc, base);
  _ntKadroDegisti(cc);
  if (typeof showToast === 'function') showToast('🎽 ' + player.name + ' milli takıma çağrıldı');
  return true;
}

// 583 — Çıkarma önizlemesi: kadro 12'nin altına inecekse ya da son kaleci çıkıyorsa
//   aynı mevkiden en güçlü uygun (bot) oyuncu o yere otomatik gelir. Onay penceresi ve
//   ntKadroCikar aynı hesabı kullanır.
function _ntCikarOnizle(ntId, cc) {
  const pool = ntPlayerPool(cc) || [];
  const etkin = _ntEtkinKadroYer(cc, pool);
  const idx = etkin.ids.indexOf(ntId);
  if (idx === -1) return { hata: 'yok' };
  if (etkin.oto[idx]) return { hata: 'oto' };
  const byNt = {}; pool.forEach(p => { if (p && p.ntId) byNt[p.ntId] = p; });
  const base = _ntDuzenlemeTabani(cc);
  const once = base.filter(Boolean).length;
  base[idx] = null;
  const g = _ntGrp(byNt[ntId] || {});
  const kalanKL = base.some(id => id && byNt[id] && _ntGrp(byNt[id]) === 'GK');
  let yerine = null;
  if (base.filter(Boolean).length < NT_MIN_KADRO || (g === 'GK' && !kalanKL)) {
    const kul = new Set(base.filter(Boolean)); kul.add(ntId);
    yerine = pool.find(x => x && x.isBot && !kul.has(x.ntId) && _ntGrp(x) === g) || null;
    if (!yerine) return { hata: 'yerine_yok', idx, g };
    base[idx] = yerine.ntId;
  }
  return { idx, base, yerine, g, once, sonra: base.filter(Boolean).length, oyuncu: byNt[ntId] || null };
}

// Kadrodan çıkar
function ntKadroCikar(ntId, cc) {
  cc = cc || ntActiveCountry();
  if (typeof ntTaktikKilitUyari === 'function' && ntTaktikKilitUyari(cc)) return false;   // 584
  if (!ntRol(cc)) { if (typeof _ntNoPermToast === 'function') _ntNoPermToast(); return false; }
  const r = _ntCikarOnizle(ntId, cc);
  if (r.hata === 'yok') { if (typeof showToast === 'function') showToast('Kadroda değil'); return false; }
  if (r.hata === 'oto') {
    if (typeof showToast === 'function') showToast('Bu oyuncu kadroyu 12’ye tamamlamak için otomatik geldi — yerine başka birini çağırabilirsin');
    return false;
  }
  if (r.hata === 'yerine_yok') {
    if (typeof showToast === 'function') showToast('Kadro en az ' + NT_MIN_KADRO + ' kişi olmalı ve yerine gelecek uygun oyuncu yok — önce başka birini çağır');
    return false;
  }
  const ad = (r.oyuncu && r.oyuncu.name) || '';
  ntSaveSquadIds(cc, r.base);
  _ntKadroDegisti(cc);
  if (typeof showToast === 'function') {
    if (r.yerine) showToast('🔁 ' + ad + ' çıkarıldı · yerine ' + r.yerine.name + ' otomatik geldi (kadro en az ' + NT_MIN_KADRO + ')');
    else showToast(ad + ' kadrodan çıkarıldı · kadro ' + r.sonra + '/' + NT_SQUAD_SLOTS.length);
  }
  return true;
}

// T.D. rozeti: başkan bu milli takımın oyuncusuysa (yalnız gerçek başkan)
function _ntTdNtId(cc, pool) {
  try {
    if (ntRol(cc) === 'baskan') { const me = pool.find(p => p && p.isUser); return me ? me.ntId : null; }
    const st = (typeof fedLoad === 'function') ? fedLoad(cc) : null;
    if (!st || (!st.serverPresidentId && !st.vekilUid)) return null;
    const pres = (typeof fedGetPresident === 'function') ? fedGetPresident(cc) : null;
    const uid = st.vekilUid || (pres && pres.captainUid) || null;   // 826 — başkanın kimliğiyle
    if (uid) { const u = pool.find(x => x && x.userId === uid); if (u) return u.ntId; }
    if (!pres || pres.isBotCaptain) return null;
    const p = pool.find(x => x && !x.isBot && x.name === pres.captainName && x.sourceClub === pres.teamName);
    return p ? p.ntId : null;
  } catch(e) { return null; }
}

// Kaptan (pazubandı): 826 — federasyon başkanı (T.D.) ilk 11'deyse o; değilse ilk 11'deki en güçlü oyuncu
const _ntKapOnb = { a: '', t: 0, v: null };
function _ntKaptanNtId() {
  try {
    const ilk = (Array.isArray(_ntActivePitchPlayers) ? _ntActivePitchPlayers : []).map(e => e && e.player).filter(Boolean);
    if (!ilk.length) return null;
    const cc = ntActiveCountry(), a = cc + ':' + ilk.map(p => p.ntId).join(',');
    if (_ntKapOnb.a === a && Date.now() - _ntKapOnb.t < 800) return _ntKapOnb.v;   // tek çizimde her oyuncu için yeniden hesaplanmasın
    const td = _ntTdNtId(cc, ilk);
    if (td) { _ntKapOnb.a = a; _ntKapOnb.t = Date.now(); _ntKapOnb.v = td; return td; }
    const g = (p) => (typeof p._ntG === 'number') ? p._ntG : ((typeof _ntPlayerSkill === 'function') ? _ntPlayerSkill(p) : 0);
    const best = ilk.slice().sort((a, b) => (g(b) - g(a)) || ((b.level || 0) - (a.level || 0)))[0];
    _ntKapOnb.a = a; _ntKapOnb.t = Date.now(); _ntKapOnb.v = best ? (best.ntId || null) : null;
    return _ntKapOnb.v;
  } catch(e) { return null; }
}
function _ntKaptanMi(p) { const k = _ntKaptanNtId(); return !!(p && k && p.ntId === k); }

// 584 — oyuncu kendi kulübündeyse (kadro yüklü) güncel kulüp kaydından: milli takım ayrı oyuncu üretmez
function _ntKulupCanli(p) {
  try {
    if (typeof ROSTER_DATA === 'undefined' || !Array.isArray(ROSTER_DATA)) return {};
    const k = p.isUser ? ROSTER_DATA.find(x => x && x.role === 'user') : (p.id != null ? ROSTER_DATA.find(x => x && x.id === p.id) : null);
    if (!k) return {};
    const o = { level: k.level, xp: k.xp };
    if (!p.isUser && k.abilities) o.abilities = k.abilities;
    if (k._kd) { o._kd = k._kd; o.stamina = k.stamina; }
    return o;
  } catch(e) { return {}; }
}
const _ntOtoKayit = {};
function ntBuildRoster(cc) {
  const pool = ntPlayerPool(cc);
  if (!pool.length) return [];
  // Sunucu kaydı henüz okunmadıysa bekle (otomatik kadroyu bir an gösterip değiştirmeyelim)
  if (window.sb && !_ntSquadLoaded[cc]) { _loadNtSquadFromServer(cc).catch(()=>{}); return []; }
  const { ids, oto, secili } = _ntEtkinKadroYer(cc, pool);
  // 585 — kadro sabit kalsın: T.D. (ya da yardımcısı) kadro kurmamışsa gösterilen otomatik kadro bir kez
  //   kaydedilir. Böylece girişten girişe botlar değişmez; seçilen (otomatik gelen) bot da kadroda kalır.
  if (!secili && window.sb && ntRol(cc) && !_ntOtoKayit[cc] && !ntTurnuvaKilitli() && !(typeof ntTaktikKilitli === 'function' && ntTaktikKilitli(cc)) && ids.filter(Boolean).length >= NT_MIN_KADRO) {
    _ntOtoKayit[cc] = true;
    ntSaveSquadIds(cc, ids);
  }
  const byNt = {}; pool.forEach(p => { byNt[p.ntId] = p; });
  let numOverrides = {};
  try { numOverrides = ((typeof _ntJerseyOverridesCache !== 'undefined' && _ntJerseyOverridesCache) || {})[cc] || {}; } catch(e) {}
  const vices = ntLoadVices(cc) || [];
  const tdId = _ntTdNtId(cc, pool);
  _ntRosterTD[cc] = tdId;   // 826
  const simdi = Date.now();
  return ids.map((id, slotIdx) => {
    if (!id) return null;
    const player = byNt[id];
    if (!player) return null;
    const slot = NT_SQUAD_SLOTS[slotIdx];
    const finalNum = (typeof numOverrides[slotIdx] === 'number') ? numOverrides[slotIdx] : slot.num;
    const sakat = (typeof _tsMsC === 'function' ? _tsMsC(player.injuryUntil) : Number(player.injuryUntil) || 0) > simdi;
    return {
      ...player,
      ..._ntKulupCanli(player),
      num: finalNum,
      slotIdx,
      ntSlotRole: slot.role,
      isNtAuto: !!oto[slotIdx],
      isNtTD: !!(tdId && id === tdId),
      isNtCaptain: false,        // pazubandı dizilişe göre (_ntKaptanMi)
      isNtVice: !!(player.id && vices.includes(player.id)),
      ntMusait: !sakat && !(player.ntBan > 0)
    };
  }).filter(x => x !== null);
}

// Kullanıcı (kendi uyruğunun) milli takım kadrosunda mı?
function ntKullaniciKadrodaMi(cc) {
  const own = ntOwnCountry();
  cc = cc || own;
  if (cc !== own) return false;
  try { if (_ntCachedCC === cc && NT_ROSTER_DATA.length) return NT_ROSTER_DATA.some(p => p && p.isUser); } catch(e) {}
  const uid = (typeof authUser !== 'undefined' && authUser) ? authUser.id : null;
  // Havuz yüklüyse ekrandaki kuralla hesapla
  if (_ntPoolCache[cc] && _ntSquadLoaded[cc]) {
    const r = _ntEtkinKadroYer(cc, _ntPoolCache[cc]);
    return r.ids.includes('USER');
  }
  // Değilse: sunucunun son çağrı listesi / başkanın kaydı
  if (window.sb && !_ntSquadLoaded[cc]) _loadNtSquadFromServer(cc).catch(()=>{});
  const snap = _ntSnapUidByCc[cc];
  if (uid && snap && snap.has(uid)) return true;
  const mid = window._benimOyuncuId;
  return !!(mid && _ntSquadUuidByCc[cc] && _ntSquadUuidByCc[cc].has(mid));
}

// Eski adlar — tek kurala yönlendirilir
function ntInvitePlayer(ntId) { return ntKadroCagir(ntId); }
function ntRemovePlayer(ntId) { return ntKadroCikar(ntId); }

let NT_ROSTER_DATA = [];
let _ntCachedCC = null;

function ntEnsureRoster() {
  const cc = ntActiveCountry();
  if(NT_ROSTER_DATA.length === 0 || _ntCachedCC !== cc) {
    NT_ROSTER_DATA = ntBuildRoster(cc);
    _ntCachedCC = cc;
  }
  return NT_ROSTER_DATA;
}

// 583 — Milli takım kadrosu en az 12 kişi (11 + 1 yedek). Başkan 12–20 arasında istediği
//   kadar oyuncu seçer; 12'nin altına inerse aynı mevkiden otomatik oyuncu gelir.
const NT_MIN_KADRO = 12;

// 572 — Eksik yerleri artık maç anında sunucu aynı kuralla dolduruyor (ekranda "OTO" rozeti).
//   İstemciden otomatik kadro YAZILMAZ (eskiden kimin tarayıcısı açıksa ortak kadroyu yazıyordu).
function ntAutoFillSquadIfStale(cc) { return; }

// ────────── KADRO render — gerçek oyuncu havuzu + TD davet/çıkar ──────────
// 🆕 Maç kadrosu yedek havuzu — kadrodaki oyunculardan maça çıkacak 7 yedek (num'lar).
// Boş set → otomatik default (ilk 11 dışından overall sıralamasıyla 7 yedek).
// Kalıcı: ntSaveStrategy ile localStorage'a yazılır.
let _ntMatchSquadBench = [];

// 🆕 Kaptan/yardımcı bench listesini elle değiştirdiyse true.
// Bu durumda _ntEnsureBench otomatik tamamlama yapmaz — kaptan kararı korunur.
let _ntBenchUserManaged = false;

// Default bench listesi otomatik üret (kadrodan ilk 11 hariç en iyi 7)
function _ntComputeDefaultBench() {
  if (typeof ntEnsureRoster !== 'function') return [];
  const roster = ntEnsureRoster();
  const usedNums = new Set();
  if (typeof _ntActivePitchPlayers !== 'undefined' && Array.isArray(_ntActivePitchPlayers)) {
    _ntActivePitchPlayers.forEach(e => { if (e && e.player && typeof e.player.num === 'number') usedNums.add(e.player.num); });
  }
  const _g = (p) => (typeof p._ntG === 'number') ? p._ntG : (p.overall || 0);
  const aday = roster.filter(p => !usedNums.has(p.num)).sort((a, b) => _g(b) - _g(a));
  const sec = aday.slice(0, 7);
  if (!sec.some(p => _ntGrp(p) === 'GK')) { const gk = aday.find(p => _ntGrp(p) === 'GK'); if (gk) { if (sec.length >= 7) sec.pop(); sec.push(gk); } }
  return sec.map(p => p.num);
}

// 🆕 Bench listesi sağlıklı tut:
// 1. Kadroda olmayan/silinmiş num'ları temizle
// 2. İlk 11'e geçmiş num'ları yedekten kaldır
// 3. Hiçbir zaman OTOMATİK eklemez — kaptan kendi kararıyla "+ Maç Kadrosu" ile ekler
// İSTİSNA: ilk açılış (bench listesi tamamen boş VE hiç kullanıcı kararı yok) →
// Bir kerelik default 7 yedek doldur. Kullanıcı bir kez yedek değişikliği yaparsa,
// sonradan otomatik tamamlama olmaz.
function _ntEnsureBench() {
  if (!Array.isArray(_ntMatchSquadBench)) _ntMatchSquadBench = [];
  if (typeof ntEnsureRoster !== 'function') return _ntMatchSquadBench;

  const roster = ntEnsureRoster();
  const rosterNums = new Set(roster.map(p => p && p.num).filter(n => typeof n === 'number'));
  const usedNums = new Set();
  if (typeof _ntActivePitchPlayers !== 'undefined' && Array.isArray(_ntActivePitchPlayers)) {
    _ntActivePitchPlayers.forEach(e => {
      if (e && e.player && typeof e.player.num === 'number') usedNums.add(e.player.num);
    });
  }

  // 1. Kadrodan ayrılmış veya ilk 11'e geçmiş num'ları temizle
  _ntMatchSquadBench = _ntMatchSquadBench.filter(num =>
    rosterNums.has(num) && !usedNums.has(num)
  );

  // 2. SADECE ilk açılış (bench tamamen boş + bayrak yok) → bir kerelik default doldur
  // Kaptan bir kez sub edip listeyi azaltırsa, _ntBenchUserManaged=true olur ve
  // bir daha otomatik dolma olmaz.
  // 583 — kaptan elle yönetmediyse yedek her zaman 7'ye tamamlanır (sunucu da maçta 7'ye
  //   tamamlıyor: sahaya 11 + 7 = 18 kişi). Eskiden yalnız liste tamamen boşken doluyordu;
  //   ilk 11 sonradan değişince yedek 4–5 kişide kalıyordu.
  if (!_ntBenchUserManaged && _ntMatchSquadBench.length < 7) {
    const BENCH_SIZE = 7;
    // 572 — sunucu kuralı: güç sırasıyla 7 yedek, aralarında bir kaleci
    const _g = (p) => (typeof p._ntG === 'number') ? p._ntG : (p.overall || 0);
    const candidates = roster
      .filter(p => p && typeof p.num === 'number' && !usedNums.has(p.num) && !_ntMatchSquadBench.includes(p.num))
      .sort((a, b) => _g(b) - _g(a));
    const bos = BENCH_SIZE - _ntMatchSquadBench.length;
    const sec = candidates.slice(0, bos);
    const kaleciVar = roster.some(p => p && _ntMatchSquadBench.includes(p.num) && _ntGrp(p) === 'GK');
    if (!kaleciVar && !sec.some(p => _ntGrp(p) === 'GK')) { const gk = candidates.find(p => _ntGrp(p) === 'GK'); if (gk) { if (sec.length >= bos) sec.pop(); sec.push(gk); } }
    sec.forEach(p => _ntMatchSquadBench.push(p.num));
  }

  return _ntMatchSquadBench;
}

// 🆕 Milli takım için kadro durumu: 'starter' (ilk 11) | 'bench' (yedek) | 'reserve' (maç kadrosu dışı)
function getNtPlayerSquadStatus(p) {
  if (!p) return 'reserve';
  // İlk 11 kontrolü — _ntActivePitchPlayers içinde mi?
  if (typeof _ntActivePitchPlayers !== 'undefined' && Array.isArray(_ntActivePitchPlayers)) {
    const inFirstXI = _ntActivePitchPlayers.some(e => {
      if (!e || !e.player) return false;
      if (p.ntId && e.player.ntId === p.ntId) return true;
      if (e.player.num === p.num && e.player.name === p.name) return true;
      return false;
    });
    if (inFirstXI) return 'starter';
  }
  // Yedek listesinde mi?
  _ntEnsureBench();
  if (Array.isArray(_ntMatchSquadBench) && _ntMatchSquadBench.includes(p.num)) {
    return 'bench';
  }
  // Kadroda ama maç kadrosu dışında
  return 'reserve';
}

// ════════════════════════════════════════════════════════════
// 🆕 MİLLİ TAKIM — MAÇ KADROSU YÖNETİMİ (yedek ekle/çıkar)
// MEVCUT "ÇIKAR" butonu havuzdan tamamen çıkarır (ntKadroConfirmRemove).
// BU fonksiyonlar ise kadrodaki oyuncuyu maç kadrosundan ekleme/çıkarma içindir.
// ════════════════════════════════════════════════════════════

// Kadrodaki oyuncuyu maç kadrosu YEDEKLERINE ekle (ilk 11'den ayrı)
function ntMatchSquadAdd(num) {
  if (typeof ntTaktikKilitUyari === 'function' && ntTaktikKilitUyari()) return;   // 584
  if (typeof fedUserIsOfficial !== 'function' || !fedUserIsOfficial()) {
    if (typeof showToast === 'function') showToast('Sadece başkan/yardımcı maç kadrosu değiştirebilir');
    return;
  }
  _ntEnsureBench();
  const BENCH_SIZE = 7;
  if (_ntMatchSquadBench.length >= BENCH_SIZE) {
    if (typeof showToast === 'function') showToast('Yedek dolu! Önce birini maç kadrosundan çıkar');
    return;
  }
  // Zaten ilk 11'de mi?
  if (typeof _ntActivePitchPlayers !== 'undefined' && _ntActivePitchPlayers.some(e => e && e.player && e.player.num === num)) {
    if (typeof showToast === 'function') showToast('Bu oyuncu zaten ilk 11\'de');
    return;
  }
  if (_ntMatchSquadBench.includes(num)) {
    if (typeof showToast === 'function') showToast('Bu oyuncu zaten yedekte');
    return;
  }
  // Kadroda mı?
  const roster = (typeof ntEnsureRoster === 'function') ? ntEnsureRoster() : [];
  const player = roster.find(p => p && p.num === num);
  if (!player) {
    if (typeof showToast === 'function') showToast('Oyuncu kadroda yok');
    return;
  }
  _ntMatchSquadBench.push(num);
  _ntBenchUserManaged = true;
  try { if (typeof ntSaveStrategy === 'function') ntSaveStrategy(true); } catch(e){}
  if (typeof ntRenderRoster === 'function') ntRenderRoster();
  if (typeof ntRenderPitch === 'function') ntRenderPitch();
  if (typeof showToast === 'function') showToast(`${player.name} maç kadrosuna alındı`);
}

// Kadrodaki oyuncuyu maç kadrosundan çıkar (yedekten kaldır → reserve)
function ntMatchSquadRemove(num) {
  if (typeof ntTaktikKilitUyari === 'function' && ntTaktikKilitUyari()) return;   // 584
  if (typeof fedUserIsOfficial !== 'function' || !fedUserIsOfficial()) {
    if (typeof showToast === 'function') showToast('Sadece başkan/yardımcı maç kadrosu değiştirebilir');
    return;
  }
  _ntEnsureBench();
  const idx = _ntMatchSquadBench.indexOf(num);
  if (idx === -1) return;
  const roster = (typeof ntEnsureRoster === 'function') ? ntEnsureRoster() : [];
  const player = roster.find(p => p && p.num === num);
  _ntMatchSquadBench.splice(idx, 1);
  _ntBenchUserManaged = true;
  try { if (typeof ntSaveStrategy === 'function') ntSaveStrategy(true); } catch(e){}
  if (typeof ntRenderRoster === 'function') ntRenderRoster();
  if (typeof ntRenderPitch === 'function') ntRenderPitch();
  if (typeof showToast === 'function') showToast(`${player ? player.name : 'Oyuncu'} maç kadrosundan çıkarıldı`);
}

// Onay diyaloğu — maç kadrosundan çıkar
function confirmNtMatchSquadRemove(num, evt) {
  if (evt) { try { evt.stopPropagation(); evt.preventDefault(); } catch(e) {} }
  if (typeof fedUserIsOfficial !== 'function' || !fedUserIsOfficial()) {
    if (typeof showToast === 'function') showToast('Sadece başkan/yardımcı maç kadrosu değiştirebilir');
    return;
  }
  const roster = (typeof ntEnsureRoster === 'function') ? ntEnsureRoster() : [];
  const player = roster.find(p => p && p.num === num);
  if (!player) return;
  if (typeof squadConfirmOpen === 'function') {
    squadConfirmOpen({
      title: 'Maç Kadrosundan Çıkar',
      msg: `<b>${player.name}</b> oyuncusunu maç kadrosundan çıkarıp <b>kadro dışı</b> yapmak istiyor musun?<br><br><span style="color:var(--text3);font-size:11px">Oyuncu hâlâ milli takım havuzunda kalır, daha sonra geri alabilirsin.</span>`,
      confirmText: 'Maç Kadrosundan Çıkar',
      confirmClass: 'scb-btn-confirm',
      onConfirm: () => ntMatchSquadRemove(num)
    });
  } else {
    ntMatchSquadRemove(num);
  }
}

// Onay diyaloğu — maç kadrosuna al
function confirmNtMatchSquadAdd(num, evt) {
  if (evt) { try { evt.stopPropagation(); evt.preventDefault(); } catch(e) {} }
  if (typeof fedUserIsOfficial !== 'function' || !fedUserIsOfficial()) {
    if (typeof showToast === 'function') showToast('Sadece başkan/yardımcı maç kadrosu değiştirebilir');
    return;
  }
  const BENCH_SIZE = 7;
  _ntEnsureBench();
  if (_ntMatchSquadBench.length >= BENCH_SIZE) {
    if (typeof showToast === 'function') showToast('Yedek dolu! Önce birini maç kadrosundan çıkar');
    return;
  }
  const roster = (typeof ntEnsureRoster === 'function') ? ntEnsureRoster() : [];
  const player = roster.find(p => p && p.num === num);
  if (!player) return;
  if (typeof squadConfirmOpen === 'function') {
    squadConfirmOpen({
      title: 'Maç Kadrosuna Al',
      msg: `<b>${player.name}</b> oyuncusunu maç kadrosu yedeğine almak istiyor musun?<br><br><span style="color:var(--text3);font-size:11px">Yedek doluluk: ${_ntMatchSquadBench.length}/${BENCH_SIZE}</span>`,
      confirmText: '+ Maç Kadrosuna Al',
      confirmClass: 'scb-btn-add',
      onConfirm: () => ntMatchSquadAdd(num)
    });
  } else {
    ntMatchSquadAdd(num);
  }
}

function ntRenderRoster() {
  const list = document.getElementById('nt-roster');
  if(!list) return;
  { const _pg = document.getElementById('page-national'); if (_pg && !_pg.classList.contains('active')) return; }   // 839 — sayfa kapalıyken çizilmez
  const isCoach = ntIsUserCoach();
  const cc = ntActiveCountry();

  let squad = ntEnsureRoster().slice();
  // 572 — ilk 11 / yedek / kaptan rozetleri için diziliş hazır olsun (kaydedilmez)
  try {
    const _slotN = ((typeof NT_FORMATIONS !== 'undefined' && NT_FORMATIONS[_ntCurrentFormation]) || []).length;
    if (squad.length && _slotN && (!Array.isArray(_ntActivePitchPlayers) || _ntActivePitchPlayers.length < _slotN)) {
      _ntPruneInvalidLineup(); _ntCompleteLineup();
    }
  } catch(e) {}

  // Pro görev: kullanıcı KENDİ milli takım kadrosunda mı?
  try {
    const _userNat = (authUser && authUser.nationality) || null;
    if (_userNat && cc === _userNat && squad.some(p => p && p.isUser) && typeof achSetFlag === 'function') achSetFlag('national_pick');
  } catch(e) {}

  // Sıralama: mevki (KL → DF → OS → FV), mevki içinde güç
  const _MS = { GK:0, DEF:1, MID:2, FWD:3 };
  const _gg = (p) => _ntPlayerSkill(p);
  squad.sort((a, b) => ((_MS[_ntGrp(a)] || 0) - (_MS[_ntGrp(b)] || 0)) || (_gg(b) - _gg(a)));

  const POSGRP = (typeof POS_GROUP !== 'undefined') ? POS_GROUP : { KL:'GK', STB:'DEF', SB:'DEF', DOS:'MID', OS:'MID', SAK:'MID', FWD:'FWD' };
  // 572 — yetki görüntülenen ülke için sunucudan (başkan / yardımcı)
  const isFedOfficial = !!ntRol(cc);

  const _ntKitA = ntFormaSetleri(cc).setA, _ntKitK = ntKaleciKiti(cc);   // 771
  const _row = (p) => {
    const _ovr = _ntPlayerSkill(p);
    const ovrColor = (typeof overallColor === 'function') ? overallColor(_ovr) : '#ffd600';
    const subPos = (typeof subPosOf === 'function') ? subPosOf(p) : p.pos;
    const subPosCls = (typeof subPosClass === 'function') ? subPosClass(p) : '';
    const isCap = _ntKaptanMi(p);

    // Rozetler: Sen / T.D. / Kaptan (ilk 11'in en güçlüsü) / Yardımcı / Bot / OTO
    let badge = '';
    if (p.isUser)   badge += '<span class="pr-badge badge-you">Sen</span>';
    if (p.isNtTD)   badge += '<span class="pr-badge badge-cap">🎩 T.D.</span>';
    if (isCap)      badge += '<span class="pr-badge badge-cap">© KAPTAN</span>';
    if (p.isNtVice) badge += '<span class="pr-badge badge-ast">🎽 Yardımcı</span>';
    if (p.isBot && !isCap) badge += '<span class="pr-badge badge-bot">Bot</span>';
    if (p.isNtAuto) badge += '<span class="pr-badge badge-bot nt-oto" title="Boş yere otomatik geldi">OTO</span>';

    // Kadro durumu (kulüp ile AYNI — emojisiz, getSquadStatusBadgeHtml)
    const st = (typeof getNtPlayerSquadStatus === 'function') ? getNtPlayerSquadStatus(p) : 'reserve';
    const squadBadge = (typeof getSquadStatusBadgeHtml === 'function') ? getSquadStatusBadgeHtml(st) : '';

    // Durum rozetleri (sarı kart / ceza / sakatlık / moral) — kulüp ile AYNI
    // 572 — kulüp kart cezaları milli maçı etkilemez; milli maç cezası ayrı (players.nt_ban)
    let statusBadges = '';
    const injured = isPlayerInjured(p);
    if (p.ntBan > 0) statusBadges += `<span class="pr-status-susp" title="Milli maçta kırmızı kart">🟥 Milli maç cezalı</span>`;
    if(injured && typeof _sakatlikSayacHtml === 'function') {
      statusBadges += `<span class="pr-status-inj" title="Sakatlık iyileşme süresi">🚑 ${_sakatlikSayacHtml(p)}</span>`;
    }
    const morale = (typeof p.morale === 'number') ? p.morale : 70;
    if (morale < 40) statusBadges += `<span class="pr-status-morale-low" title="Moral: ${morale}/100">😞 Düşük Moral</span>`;
    else if (morale >= 90) statusBadges += `<span class="pr-status-morale-high" title="Moral: ${morale}/100">🔥 Yüksek Moral</span>`;

    // Kulüp logosu: GERÇEK logo varsa (teamLogoUrl), yoksa renkli kısa-isim badge — MT'ye özel
    const _cbg = p.clubBg || '#222', _ctc = p.clubTc || '#fff', _csh = p.clubShort || (p.sourceClub || '—').slice(0,3).toUpperCase();
    const _clubLogoUrl = (typeof teamLogoUrl === 'function') ? teamLogoUrl({ name: p.sourceClub, cc: p.clubCC }) : null;
    const _clubLogoHtml = _clubLogoUrl
      ? `<img class="futc-club-logo-img" src="${_clubLogoUrl}" alt="" loading="lazy">`
      : `<span class="futc-club-logo" style="background:${_cbg};color:${_ctc}">${_csh}</span>`;
    const clubHtml = p.sourceClub
      ? `<span class="futc-club" title="Kulübü: ${p.sourceClub}">${_clubLogoHtml}<span class="futc-club-ad">${p.sourceClub}</span></span>`
      : '';

    // Piyasa değeri (kulüp ile AYNI — futc-mv)
    const mvHtml = (typeof formatMV === 'function' && typeof getPlayerMarketValue === 'function')
      ? `<span class="futc-mv">${formatMV(getPlayerMarketValue(p))}</span>` : '';

    // Avatar (kulüp ile AYNI)
    const avatarClass = isCap ? 'captain-av' : (p.isBot ? 'bot-av' : '');
    let avatarHTML = p.avatar || (p.isUser ? '⭐' : '🤖');
    try {
      if (p.isUser && typeof authUser !== 'undefined' && authUser && authUser.avatarId && typeof getAvatarEmoji === 'function') {
        const r = getAvatarEmoji(authUser.avatarId, p.pos); if (typeof r === 'string' && r.indexOf('<img') === 0) avatarHTML = r;
      } else if (!p.isUser && !p.isBot && p.avatar_id && typeof getAvatarEmoji === 'function') {
        const r = getAvatarEmoji(p.avatar_id, p.pos); if (typeof r === 'string' && r.indexOf('<img') === 0) avatarHTML = r;
      }
    } catch(e) {}
    const onlineDot = (typeof isPlayerOnline === 'function' && isPlayerOnline(p)) ? '<span class="pr-online-dot" title="Çevrimiçi"></span>' : '';

    // 🆕 Aksiyon: SADECE başkan/yardımcı → oyuncu işlemleri menüsü (⋮) → modal
    let actionBtn = '';
    if (isFedOfficial) {
      const _smid = String(p.ntId || '').replace(/'/g, "\\'");
      actionBtn = `<button class="nt-kadro-menu-btn" onclick="event.stopPropagation();ntKadroMenu('${_smid}')" title="Oyuncu işlemleri" aria-label="Menü">⋮</button>`;
    }

    // Forma no (kulüp ile AYNI — T.D. düzenler) · 771 — küçük sırt formasında, kaleci kaleci formasında
    const _ntKf = _kfHtml(p.name, p.num, _kfKaleciMi(p) ? _ntKitK : _ntKitA);
    const numHtml = (isCoach && !p.isUser)
      ? `<div class="futc-num kf" onclick="event.stopPropagation();ntEditJerseyNumber(${p.num}, event)" title="Forma numarasını düzenle (T.D.)">${_ntKf}</div>`
      : `<div class="futc-num kf">${_ntKf}</div>`;

    const safeNtId = String(p.ntId || '').replace(/'/g, "\\'");
    const cardCls = ['player-row','fut-card','clickable'];
    if (isCap) cardCls.push('is-cap'); else if (p.isUser) cardCls.push('is-user');
    if (p.ntMusait === false) cardCls.push('nt-musait-degil');

    return `<div class="${cardCls.join(' ')}" data-pos="${POSGRP[p.pos] || p.pos}" onclick="ntKadroOpenProfile('${safeNtId}')">
      <div class="futc-lcol">
        <div class="futc-ovr" style="color:${ovrColor}">${_ovr}</div>
        <div class="futc-pos mvy ${subPosCls}" data-noi18n>${mvEtiketler([subPos].concat(glEk(p).filter(c => c !== subPos)))}</div>
      </div>
      <div class="futc-rcol">
        <div class="futc-av ${avatarClass}">${avatarHTML}${onlineDot}</div>
        <div class="futc-info">
          <div class="futc-name"><span class="futc-ad">${p.name}</span>${_cinsIk(p)}</div>
          ${_kdRolSatiri(badge + squadBadge)}
          <div class="futc-meta">
            ${clubHtml}
            <span>${p.nation || ''}</span>
            <span>Sv.${p.level || 0}</span>
            ${mvHtml}
          </div>
        </div>
        <div class="futc-right">
          ${_kdDugmeHtml('n' + (p.ntId || p.num), p, p.sourceClub || null)}
          ${actionBtn}
          ${numHtml}
        </div>
      </div>
    </div>`;
  };

  // 582 — başlığın sağında (i): milli takım kuralları (OTO / sakat-cezalı bilgisi de orada)
  let html = `<div class="nt-section-title nt-baslik-i"><span>⭐ Milli Takım Kadrosu (${squad.length}/${NT_SQUAD_SLOTS.length})</span><button type="button" class="nt-info-btn" onclick="ntKuralAc()" aria-label="Milli takım kuralları">i</button></div>`;
  // 585 — otomatik kadro bilgisi yalnız (i) kurallarında (ortada bilgi kutusu yok)
  const _havuzHazir = !!(_ntPoolCache[cc]) && !!_ntSquadLoaded[cc];
  if (!squad.length) {
    html += _havuzHazir
      ? `<div style="text-align:center;padding:40px 16px;color:var(--text2)"><div style="font-size:38px;margin-bottom:8px">🏳️</div><div style="font-size:13px">Bu ülkenin uyruğunda oyuncu bulunamadı.</div></div>`
      : `<div style="text-align:center;padding:40px 16px;color:var(--text2)"><div style="font-size:38px;margin-bottom:8px">⏳</div><div style="font-size:13px">Kadro yükleniyor…</div></div>`;
  } else {
    html += squad.map(p => _row(p)).join('');
  }
  list.innerHTML = html;
}

// ════ Milli Takım Forma Numarası Düzenleme — sadece T.D. ════
let _ntPendingJerseyEdit = null;

function ntEditJerseyNumber(currentNum, ev) {
  if(ev) { try { ev.stopPropagation(); } catch(e){} }
  if(!ntIsUserCoach()) {
    _ntNoPermToast();
    return;
  }
  const roster = ntEnsureRoster();
  const player = roster.find(p => p && p.num === currentNum);
  if(!player) return;

  _ntPendingJerseyEdit = { currentNum, playerName: player.name };

  const infoEl = document.getElementById('ntJerseyPlayerInfo');
  if(infoEl) infoEl.textContent = player.name;
  const curEl = document.getElementById('ntJerseyCurrentNum');
  if(curEl) curEl.textContent = '#' + currentNum;
  const inputEl = document.getElementById('ntJerseyInput');
  if(inputEl) {
    inputEl.value = String(currentNum);
    setTimeout(() => { inputEl.focus(); inputEl.select(); }, 200);
  }

  ntOnJerseyInputChange();

  const ov = document.getElementById('ntJerseyEditOverlay');
  if(ov) ov.classList.add('open');
}

function ntOnJerseyInputChange() {
  const input = document.getElementById('ntJerseyInput');
  const warn  = document.getElementById('ntJerseyWarn');
  const btn   = document.getElementById('ntJerseySaveBtn');
  if(!input || !warn || !btn || !_ntPendingJerseyEdit) return;

  const valStr = (input.value || '').trim();
  const newNum = parseInt(valStr, 10);
  const cur = _ntPendingJerseyEdit.currentNum;

  warn.classList.remove('has-conflict','ok');

  if(valStr === '' || isNaN(newNum)) {
    warn.textContent = 'Bir sayı gir (1-99 arası).';
    btn.disabled = true;
    return;
  }
  if(newNum < 1 || newNum > 99) {
    warn.textContent = '⛔ Numara 1-99 arasında olmalı.';
    warn.classList.add('has-conflict');
    btn.disabled = true;
    return;
  }
  if(newNum === cur) {
    warn.textContent = 'Mevcut numarayla aynı — değişiklik yapılmayacak.';
    btn.disabled = true;
    return;
  }
  // Çakışma kontrolü
  const roster = ntEnsureRoster();
  const conflict = roster.find(p => p && p.num === newNum && p.num !== cur);
  if(conflict) {
    warn.innerHTML = `⚠️ Bu numara <b>${conflict.name}</b> oyuncusunda zaten kullanılıyor.`;
    warn.classList.add('has-conflict');
    btn.disabled = true;
    return;
  }
  warn.innerHTML = `✅ <b>#${newNum}</b> kullanılabilir.`;
  warn.classList.add('ok');
  btn.disabled = false;
}

function ntCloseJerseyEdit() {
  const ov = document.getElementById('ntJerseyEditOverlay');
  if(ov) ov.classList.remove('open');
  _ntPendingJerseyEdit = null;
}

function ntExecuteJerseyEdit() {
  if(!_ntPendingJerseyEdit) { ntCloseJerseyEdit(); return; }
  if(!ntIsUserCoach()) { _ntNoPermToast(); ntCloseJerseyEdit(); return; }

  const cur = _ntPendingJerseyEdit.currentNum;
  const input = document.getElementById('ntJerseyInput');
  const valStr = input ? (input.value || '').trim() : '';
  const newNum = parseInt(valStr, 10);

  if(isNaN(newNum) || newNum < 1 || newNum > 99) return;
  if(newNum === cur) { ntCloseJerseyEdit(); return; }

  const roster = ntEnsureRoster();
  const conflict = roster.find(p => p && p.num === newNum && p.num !== cur);
  if(conflict) return;

  const player = roster.find(p => p && p.num === cur);
  if(!player) { ntCloseJerseyEdit(); return; }

  // Numarayı güncelle (in-memory)
  player.num = newNum;

  // Persist: ülke bazlı override map'ine kaydet (Supabase user_player.nt_jersey_overrides)
  const cc = ntActiveCountry();
  const all = _ntJerseyOverridesCache || {};
  if (!all[cc]) all[cc] = {};
  if(typeof player.slotIdx === 'number') {
    all[cc][player.slotIdx] = newNum;
    _saveNtJerseyOverrides(all);
  }

  // Diziliş lineup snapshot'ı güncelle (saha üzerindeki oyuncunun num'u değişebilir)
  if(typeof ntSaveStrategy === 'function') ntSaveStrategy();

  // Re-render
  ntRenderRoster();
  if(typeof ntRenderPitch === 'function') ntRenderPitch();

  // Toast
  const t = document.createElement('div');
  t.style.cssText = 'position:fixed;bottom:90px;left:50%;transform:translateX(-50%);background:#00e676;color:#000;padding:8px 16px;border-radius:20px;font-size:12px;font-weight:700;z-index:9999;font-family:Twemoji Country Flags,"Barlow Condensed",sans-serif;letter-spacing:.5px;white-space:nowrap';
  t.textContent = `✅ ${player.name} → #${newNum}`;
  document.body.appendChild(t);
  setTimeout(() => t.remove(), 2200);

  ntCloseJerseyEdit();
}

// ═══════════════════════════════════════════════════════════════════════
// MİLLİ TAKIM DİZİLİŞ — TAKIMIM ile birebir aynı tüm fonksiyonlarla
// State'ler ve fonksiyonlar "nt" prefix'iyle ayrı tutulur
// ═══════════════════════════════════════════════════════════════════════

// NT Diziliş state — takımım ile aynı yapı, ayrı kopyalar
const NT_FORMATIONS = FORMATIONS;   // 585 — milli takım kulüple aynı 12'li seti kullanır

let _ntActivePitchPlayers = []; // [{rosterIdx, slotIdx, pos, x, y, player}]
let _ntCurrentFormation   = '4-3-3';
let _ntSwapMode           = null;
let _ntSwapIdx            = null;
let _ntSelectedTooltipIdx = null;
let _ntTooltipScope       = null; // 'pitch'|'bench'
const _ntActiveStrategy   = {
  stil:'Dengeli', mentalite:'Dengeli', savunma:'Orta blok', pas:'Karışık', yon:'Karışık', tempo:'Normal', mudahale:'Normal'
};

// Roster pozisyon sembollerini diziliş slotuna eşleştir
// Roster sadece GK/DEF/MID/FWD; pitch slot'ta SB/STB/DOS/OS/SAK/CAM/FWD var
function _ntPosFamily(slotPos) {
  if(slotPos === 'GK') return 'GK';
  if(['SB','STB','DEF'].includes(slotPos)) return 'DEF';
  if(['DOS','OS','CAM','MID'].includes(slotPos)) return 'MID';
  if(['SAK','FWD'].includes(slotPos)) return 'FWD';
  return 'MID';
}

// NT için kullanıcı düzenleme yetkisi
// T.D. = federasyon başkanı. Sadece T.D. olan kullanıcı diziliş, taktik,
// formasyon, oyuncu değişikliği ve forma numarası değişikliği yapabilir.
function ntCanEditFormation() {
  // 🆕 YETKİ: Federasyon BAŞKANI VEYA YARDIMCISI düzenleyebilir (kulüpteki kaptan+yardımcı mantığı).
  //   Üyeler sadece görüntüler. Ziyaretçi modunda (başka ülkeye bakarken) asla düzenleme yok.
  // 572 — yetki GÖRÜNTÜLENEN ülke için sunucudan: başkan (T.D.) ya da başkanın seçtiği yardımcı
  return (typeof ntRol === 'function') && !!ntRol(ntActiveCountry());
}
// Alias — semantik açıdan açık
function ntIsUserCoach() { return ntCanEditFormation(); }

// Storage key — her ülke için ayrı
// _ntStrategyKey kaldırıldı — milli takım stratejisi artık Supabase team_data tablosunda
// (country_code + team_name=ülke_adı + data_key='strategy')

// 🆕 Milli takım country adı (Supabase team_data'da team_name olarak kullanılır)
// Edge Function maç başlatınca team_data'dan stratejiyi okur → maça yansır
function _ntCountryName() {
  return _ntUlkeAdi(ntActiveCountry());
}

// RAM cache + debounced save (kulüp strategy ile aynı pattern)
let _ntStrategyCache = null;
let _ntStrategyCC = null;          // 572 — önbellekteki diziliş hangi ülkenin
let _ntStrategySaveTimer = null;

async function _ntStrategyLoadFromServer() {
  if (!window.sb) { _ntStrategyCache = null; return; }
  const cc = ntActiveCountry();
  if (typeof _cftGetCountry === 'function' && !_cftGetCountry(cc)) return;   // 585 — ülke listesi hazır değil: yanlış satırı okuma
  const ntName = _ntCountryName();
  _ntStrategyCC = cc;
  try {
    const { data, error } = await window.sb.from('team_data')
      .select('data')
      .eq('country_code', cc)
      .eq('team_name', ntName)
      .eq('data_key', 'strategy')
      .maybeSingle();
    if (error) { console.warn('[nt_strategy] load hata:', error); _ntStrategyCache = null; return; }
    _ntStrategyCache = (data && data.data) ? data.data : null;
  } catch(e) { console.warn('[nt_strategy] load hata:', e); _ntStrategyCache = null; }
}

function ntLoadStrategy() {
  try {
    // 572 — başka ülkenin dizilişi uygulanmasın
    if (_ntStrategyCC && _ntStrategyCC !== ntActiveCountry()) { _ntStrategyCache = null; _ntStrategyCC = null; }
    const data = _ntStrategyCache || {};
    if(data.strategy) planYaz(_ntActiveStrategy, data.strategy);   // 586
    const _fy = formasyonTasi(data.formation || _ntCurrentFormation);   // 585 — eski formasyon kaydı yeni sete
    _ntCurrentFormation = _fy.ad;
    // Maç kadrosu yedek listesi
    if (Array.isArray(data.matchBench)) {
      _ntMatchSquadBench = data.matchBench.filter(n => typeof n === 'number');
    }
    if (typeof data.benchUserManaged === 'boolean') {
      _ntBenchUserManaged = data.benchUserManaged;
    }
    if(data.lineup && Array.isArray(data.lineup)) {
      const roster = ntEnsureRoster();
      const slots = NT_FORMATIONS[_ntCurrentFormation];
      if(slots && roster.length) {
        // 🆕 EŞLEŞTİRME ÖNCELİĞİ: id (players.uuid, kalıcı) → ntId → num (SON ÇARE)
        //    Eski kod `id || num` yazıyordu; `num` oyuncunun değil KADRO SLOTUNUN
        //    numarası olduğu için kadro değişince yanlış oyuncuya ya da hiçbirine
        //    eşleşiyor, diziliş boş kalıyordu.
        const restored = [];
        const kullanilan = new Set();
        const bul = (saved) => {
          let p = null;
          if (saved.id != null)  p = roster.find(x => x && x.id === saved.id && !kullanilan.has(x));
          if (!p && saved.ntId)  p = roster.find(x => x && x.ntId === saved.ntId && !kullanilan.has(x));
          if (!p && saved.ad)    p = roster.find(x => x && x.name === saved.ad && !kullanilan.has(x));
          if (!p && saved.num != null) p = roster.find(x => x && x.num === saved.num && !kullanilan.has(x));
          return p || null;
        };
        data.lineup.forEach(saved => {
          const player = bul(saved);
          const _yer = _fy.yer(saved.slotIdx);
          const slot = slots[_yer];
          if(player && slot) {
            kullanilan.add(player);
            restored.push({
              rosterIdx: roster.indexOf(player),
              slotIdx: _yer,
              pos: slot.pos, s: slot.s, x: slot.x, y: slot.y,
              player
            });
          }
        });
        if(restored.length > 0) {
          _ntActivePitchPlayers = restored;
          _ntDizilisDurum = 'yuklendi';
        } else {
          // 🆕 Kayıt vardı ama tek oyuncu bile eşleşmedi → OTOMATİK DİZİLİŞİ
          //    SUNUCUYA YAZMA. Eskiden auto-fill hemen kaydedilip kullanıcının
          //    kaydını kalıcı olarak siliyordu.
          _ntDizilisDurum = 'eslesmedi';
          console.warn('[nt_strategy] kayıtlı diziliş eşleşmedi — otomatik diziliş kaydedilmeyecek');
        }
      }
    }
  } catch(e){}
}

// 🆕 Kayıtlı dizilişin durumu:
//    'yok'       → sunucuda kayıt yok, otomatik diziliş kaydedilebilir
//    'yuklendi'  → kayıt bulundu ve eşleşti, serbestçe kaydedilir
//    'eslesmedi' → kayıt VAR ama hiçbir oyuncu eşleşmedi → otomatik dizilişi
//                  SUNUCUYA YAZMA, kullanıcının kaydını ezmesin
let _ntDizilisDurum = 'yok';

// kullaniciEylemi = true → kullanıcı bilerek değiştirdi, her durumda kaydet
// 🆕 506: Milli takım stratejisini SUNUCUYA yazma yetkisi var mı?
//   Yalnızca federasyon başkanı/yardımcısı yazabilir; diğer herkeste RAM cache kullanılır.
function _ntStratYazabilir() {
  try {
    if (!window.sb) return false;
    if (typeof ntTaktikKilitli === 'function' && ntTaktikKilitli()) return false;   // 584 — milli maç sürüyor
    return !!ntRol(ntActiveCountry());
  } catch (e) { return false; }
}
// 572 — diziliş/taktik yalnız yetki denetimli RPC ile yazılır
async function _ntTaktikYaz(cc, blob) {
  if (!window.sb || !blob) return false;
  const { error } = await window.sb.rpc('nt_taktik_kaydet', { p_cc: cc, p_data: blob });
  if (error) {
    console.warn('[nt_strategy] kayıt reddedildi:', error.message || error);
    if (typeof showToast === 'function') showToast(ntHataMetni(error, 'Diziliş kaydedilemedi'));
    return false;
  }
  return true;
}

function _ntSlotAlt(e) {
  if (e.s) return e.s;
  const sl = (typeof NT_FORMATIONS !== 'undefined' && NT_FORMATIONS[_ntCurrentFormation]) ? NT_FORMATIONS[_ntCurrentFormation][e.slotIdx] : null;
  return (sl && sl.s) || null;
}
function ntSaveStrategy(kullaniciEylemi) {
  try {
    // 🆕 Kayıtlı diziliş eşleşmediyse (kadro/roster bayat) otomatik üretilmiş
    //    dizilişi sunucuya YAZMA — kullanıcının kaydını silmesin. RAM'de tutulur.
    if (_ntDizilisDurum === 'eslesmedi' && !kullaniciEylemi) {
      try {
        _ntStrategyCache = {
          strategy: { ..._ntActiveStrategy },
          formation: _ntCurrentFormation,
          lineup: (_ntActivePitchPlayers || []).map(e => ({
            num: e.player && e.player.num, slotIdx: e.slotIdx,
            id: e.player && e.player.id, ntId: (e.player && e.player.ntId) || null,
            ad: (e.player && e.player.name) || null, x: e.x, y: e.y, pos: e.pos, s: _ntSlotAlt(e) })),
          matchBench: Array.isArray(_ntMatchSquadBench) ? _ntMatchSquadBench.slice() : [],
          benchUserManaged: !!_ntBenchUserManaged
        };
      } catch(e) {}
      return;
    }
    // 🆕 Kalıcı kimlikleri de yaz: id (uuid) + ntId + ad. Sadece num'a güvenmek
    //    kadro değişince eşleşmeyi bozuyordu.
    const lineupSnapshot = (Array.isArray(_ntActivePitchPlayers) ? _ntActivePitchPlayers : [])
      .filter(e => e && e.player)
      .map(e => ({ num: e.player.num, slotIdx: e.slotIdx, id: e.player.id,
                   ntId: e.player.ntId || null, ad: e.player.name || null,
                   x: e.x, y: e.y, pos: e.pos, s: _ntSlotAlt(e) }));
    // 🆕 Yedekleri KALICI KİMLİKLE de yaz — maç motoru forma numarasıyla değil
    //    uuid ile eşleştirsin (numaralar kadro değişince kayıyor).
    let matchBenchIds = [];
    try {
      const _rost = (typeof ntEnsureRoster === 'function') ? ntEnsureRoster() : [];
      matchBenchIds = (Array.isArray(_ntMatchSquadBench) ? _ntMatchSquadBench : [])
        .map(n => { const q = _rost.find(x => x && x.num === n); return q ? q.id : null; })
        .filter(Boolean);
    } catch(e) {}
    const blob = {
      strategy: { ..._ntActiveStrategy },
      formation: _ntCurrentFormation,
      lineup: lineupSnapshot,
      matchBench: Array.isArray(_ntMatchSquadBench) ? _ntMatchSquadBench.slice() : [],
      matchBenchIds,
      benchUserManaged: !!_ntBenchUserManaged
    };
    // Anında RAM cache'i güncelle (load'ta tutarlı)
    _ntStrategyCache = blob;
    _ntStrategyCC = ntActiveCountry();
    // 🆕 506: Yetki yoksa zamanlayıcıyı HİÇ kurma. Eskiden kontrol setTimeout'un
    //   içindeydi; flushNtStrategySave() bekleyen zamanlayıcıyı iptal edip isteği
    //   kontrolsüz gönderdiği için her açılışta 403 düşüyordu.
    if (!_ntStratYazabilir()) return;
    // Debounced Supabase save (500ms)
    if (_ntStrategySaveTimer) clearTimeout(_ntStrategySaveTimer);
    const _ccK = ntActiveCountry();
    _ntStrategySaveTimer = setTimeout(async () => {
      _ntStrategySaveTimer = null;
      if (!window.sb || !_ntStratYazabilir()) return;
      try {
        if (await _ntTaktikYaz(_ccK, blob)) _ntDizilisDurum = 'yuklendi';
      } catch(e) { console.warn('[nt_strategy] save hata:', e); }
    }, 500);
  } catch(e){}
}

// 🆕 Sıralama yardımcısı — players.overall herkeste 10 olduğu için otomatik
//    ilk 11 seçimi fiilen rastgeleydi. Gerçek güç _ntPlayerSkill'den gelir.
function _ntG2(p) {
  return (typeof _ntPlayerSkill === 'function') ? _ntPlayerSkill(p) : ((p && p.overall) || 0);
}

// Otomatik ilk diziliş — gerçek yeteneğe göre en iyi 11
function _ntAutoFillLineup() {
  // 572 — önce oynayabilecekler (sakat / milli cezalı olanlar maçta oynamaz)
  const _tum = ntEnsureRoster();
  const _musait = _tum.filter(p => p && p.ntMusait !== false);
  const roster = (_musait.length >= 11) ? _musait : _tum;
  const slots = NT_FORMATIONS[_ntCurrentFormation];
  if(!slots) return;

  // 🆕 Ortak akıllı yerleştirme — pozisyon-uyumlu, GK ↔ KL eşleştirmesi dahil
  if (typeof _computeSmartLineup === 'function') {
    // NT için unique-id: ntId varsa onu, yoksa num+name
    const ntIdOf = (p) => p && (p.ntId || (p.num + '|' + p.name));
    const { lineup } = _computeSmartLineup(roster, slots, {
      idOf: ntIdOf,
      skipBench: true,
    });
    // NT format'a çevir (rosterIdx ekle)
    _ntActivePitchPlayers = lineup.map(l => ({
      rosterIdx: _tum.indexOf(l.player),
      slotIdx:   l.slotIdx,
      pos:       l.pos,
      x:         l.x,
      y:         l.y,
      player:    l.player,
    }));
    return;
  }

  // Fallback: eski grup-bazlı dolgu (helper yoksa)
  const POSGRP = (typeof POS_GROUP !== 'undefined') ? POS_GROUP : null;
  const _grp = (p) => p.posGroup || (POSGRP && POSGRP[p.pos]) || _ntPosFamily(p.pos);
  const used = new Set();
  const result = [];
  slots.forEach((slot, slotIdx) => {
    const fam = _ntPosFamily(slot.pos);
    const candidates = roster
      .map((p, i) => ({ p, i }))
      .filter(({ p, i }) => !used.has(i) && _grp(p) === fam)
      .sort((a, b) => _ntG2(b.p) - _ntG2(a.p));   // 🆕 gerçek yetenek
    if(candidates.length > 0) {
      const pick = candidates[0];
      used.add(pick.i);
      result.push({
        rosterIdx: _tum.indexOf(pick.p), slotIdx, pos: slot.pos,
        x: slot.x, y: slot.y, player: pick.p
      });
    }
  });
  _ntActivePitchPlayers = result;
}

// 🆕 Kadrodan çıkarılmış / artık var olmayan oyuncuları lineup'tan temizle
function _ntPruneInvalidLineup() {
  const roster = ntEnsureRoster();
  // ntId varsa onu kullan, yoksa num+name kombinasyonu
  const validKeys = new Set(roster.map(p => p && (p.ntId || (p.num + '|' + p.name))).filter(Boolean));
  _ntActivePitchPlayers = (_ntActivePitchPlayers || []).filter(e => {
    if(!e || !e.player) return false;
    const key = e.player.ntId || (e.player.num + '|' + e.player.name);
    return validKeys.has(key);
  });
  // Roster oyuncusu hala kadroda ama referans bayatladıysa güncelle
  _ntActivePitchPlayers.forEach(e => {
    const fresh = roster.find(p => (p.ntId && p.ntId === e.player.ntId) || (p.num === e.player.num && p.name === e.player.name));
    if(fresh) { e.player = fresh; e.rosterIdx = roster.indexOf(fresh); }
  });
}

// 🆕 Eksik slotları otomatik doldur (mevcut yerleşimi koruyarak)
function _ntCompleteLineup() {
  const roster = ntEnsureRoster();
  const slots = NT_FORMATIONS[_ntCurrentFormation];
  if(!slots) return;
  const POSGRP = (typeof POS_GROUP !== 'undefined') ? POS_GROUP : null;
  const _grp = (p) => p.posGroup || (POSGRP && POSGRP[p.pos]) || _ntPosFamily(p.pos);

  const filledSlotIdx = new Set((_ntActivePitchPlayers || []).map(e => e && e.slotIdx).filter(i => i != null));
  const usedRosterIdx = new Set((_ntActivePitchPlayers || []).map(e => e && e.rosterIdx).filter(i => i != null));

  slots.forEach((slot, slotIdx) => {
    if(filledSlotIdx.has(slotIdx)) return;
    const fam = _ntPosFamily(slot.pos);
    // Önce aynı pozisyon grubundan
    // 572 — önce oynayabilecek (sakat / milli cezalı olmayan) oyuncular
    let candidates = roster
      .map((p, i) => ({ p, i }))
      .filter(({ p, i }) => !usedRosterIdx.has(i) && _grp(p) === fam && p.ntMusait !== false)
      .sort((a, b) => _ntG2(b.p) - _ntG2(a.p));   // 🆕 gerçek yetenek
    if(candidates.length === 0) {
      candidates = roster
        .map((p, i) => ({ p, i }))
        .filter(({ p, i }) => !usedRosterIdx.has(i) && _grp(p) === fam)
        .sort((a, b) => _ntG2(b.p) - _ntG2(a.p));
    }
    // 🆕 Uygun yoksa HERHANGİ boşta oyuncu (kaleci dahil — saha asla eksik kalmasın)
    if(candidates.length === 0) {
      candidates = roster
        .map((p, i) => ({ p, i }))
        .filter(({ p, i }) => !usedRosterIdx.has(i))
        .sort((a, b) => _ntG2(b.p) - _ntG2(a.p));   // 🆕 gerçek yetenek
    }
    if(candidates.length > 0) {
      const pick = candidates[0];
      usedRosterIdx.add(pick.i);
      _ntActivePitchPlayers.push({
        rosterIdx: pick.i, slotIdx, pos: slot.pos,
        x: slot.x, y: slot.y, player: pick.p
      });
    }
  });
  _ntActivePitchPlayers.sort((a, b) => a.slotIdx - b.slotIdx);
}

// ────────── DİZİLİŞ render ──────────
function ntRenderFormation() {
  const el = document.getElementById('nt-formation');
  if(!el) return;
  const roster = ntEnsureRoster();
  if(roster.length === 0) {
    el.innerHTML = '<div style="padding:24px;text-align:center;color:var(--text3)">Kadro yükleniyor…</div>';
    return;
  }

  // İlk açılışta lineup yoksa otomatik doldur
  if(_ntActivePitchPlayers.length === 0) {
    ntLoadStrategy();
    if(_ntActivePitchPlayers.length === 0) _ntAutoFillLineup();
  }
  // 🆕 Kadrodan çıkarılmış oyuncuları lineup'tan temizle, eksik slotları doldur
  _ntPruneInvalidLineup();
  const slotCount = (NT_FORMATIONS[_ntCurrentFormation] || []).length;
  if(_ntActivePitchPlayers.length < slotCount) _ntCompleteLineup();
  // 588 — sakat / milli cezalı ilk 11'den yedeğe; yerine yuvaya en yakın mevkiden uygun oyuncu
  try {
    const _dgN = (typeof dzMilliUygunsuzDuzelt === 'function') ? dzMilliUygunsuzDuzelt() : [];
    if (_dgN.length) {
      if (typeof _dzDegisBildir === 'function') _dzDegisBildir(_dgN, true);
      const _ccN = (typeof ntActiveCountry === 'function') ? ntActiveCountry() : null;
      if (ntCanEditFormation() && !(typeof ntTaktikKilitli === 'function' && ntTaktikKilitli(_ccN))) { try { ntSaveStrategy(true); } catch(e) {} }
    }
  } catch(e) { console.warn('[dz] milli uygunsuz düzeltme hata:', e); }

  // T.D. yetki kontrolü
  const canEdit = ntCanEditFormation();
  const roBar = document.getElementById('ntFormReadOnlyBar');
  if(roBar) roBar.style.display = canEdit ? 'none' : 'flex';
  el.classList.toggle('nt-form-readonly', !canEdit);

  // Formasyon pick label sync
  const _pl = document.getElementById('ntFormationPickLabel');
  if(_pl) _pl.textContent = _ntCurrentFormation;
  // Strateji pill'leri sync
  ['style','tempo','attack','defense','press','shoot'].forEach(grp => {
    const wrap = document.getElementById('nt-sg-' + grp);
    if(!wrap) return;
    const val = _ntActiveStrategy[grp];
    wrap.querySelectorAll('.sp').forEach(sp => {
      sp.classList.toggle('active', (sp.getAttribute('onclick') || '').includes(",'" + val + "',"));   // 577
    });
  });

  ntRenderPitch();
}

// Pitch ve yedek render
// 🆕 Milli takım — pitch içi sürükle-bırak: başka oyuncuya yakın bırakırsan swap
// Pitch x/y koordinatları formasyon slot'larıdır → swap'ta sadece player değişir.
let _ntDragOriginalLeft = 0, _ntDragOriginalTop = 0;
function ntMakeDraggable(node, idx) {
  let startX, startY, startLeft, startTop, dragging = false;
  let originalLeft, originalTop;
  let didMove = false;
  let lastX = 0, lastY = 0;   // 🆕 son pointer konumu (yedek bırakma algılaması)
  let startPitchTop = 0, startPitchLeft = 0;   // 577 — sayfa kayarsa kart parmağın altında kalsın
  const SWAP_THRESHOLD = 9;

  function _getPitch() {
    // 🆕 Drag hesaplaması için GERÇEK saha container'ı (nt-formPitch).
    // Eski versiyon nt-pitchPlayers kullanıyordu — onun boyutu CSS'e göre 0
    // olabilir (oyuncular .fpitch içinde absolute positioned), bu yüzden
    // dx/pr.width × 100 = Infinity sonucu kontrolsüz hareket çıkıyordu.
    return document.getElementById('nt-formPitch')
        || document.getElementById('nt-pitchPlayers')
        || node.parentElement;
  }

  function onStart(e) {
    if (e.touches && e.touches.length > 1) return;
    if (typeof ntCanEditFormation === 'function' && !ntCanEditFormation()) return;  // 🆕 sadece başkan
    const touch = e.touches ? e.touches[0] : e;
    startX = touch.clientX;
    startY = touch.clientY;
    startLeft   = parseFloat(node.style.left);
    startTop    = parseFloat(node.style.top);
    originalLeft = startLeft;
    originalTop  = startTop;
    try { const _pr0 = _getPitch().getBoundingClientRect(); startPitchTop = _pr0.top; startPitchLeft = _pr0.left; } catch(_) {}
    lastX = 0; lastY = 0;
    dragging  = true;
    didMove   = false;
    if (typeof _dzAktif === 'function' && _dzAktif('nt') && typeof _dzOtoBasla === 'function') {
      _dzOtoBasla(() => { if (dragging && (lastX || lastY)) onMove({ clientX: lastX, clientY: lastY, preventDefault(){} }); }, 'nt');
    }
    node.style.transition = 'none';
    node.style.zIndex = '20';
    node.classList.add('is-dragging');
    // 🆕 Move/end listener'ları SADECE drag aktifken doc'a ekle (sızıntı önleme)
    document.addEventListener('mousemove',  onMove);
    document.addEventListener('touchmove',  onMove, { passive: false });
    document.addEventListener('mouseup',    onEnd);
    document.addEventListener('touchend',   onEnd);
    document.addEventListener('touchcancel', onEnd);
  }
  function onMove(e) {
    if(!dragging) return;
    const touch = e.touches ? e.touches[0] : e;
    const pitch = _getPitch();
    if (!pitch) return;
    const pr = pitch.getBoundingClientRect();
    const dx = ((touch.clientX - startX - (pr.left - startPitchLeft)) / pr.width) * 100;
    const dy = ((touch.clientY - startY - (pr.top - startPitchTop)) / pr.height) * 100;
    if (Math.abs(touch.clientX - startX) > 4 || Math.abs(touch.clientY - startY) > 4) {
      didMove = true;
      e.preventDefault();
    }
    // 577 — yedekler sahanın ALTINDA: kart aşağı doğru yedek alanına inebilir
    const _dz = (typeof _dzAktif === 'function') && _dzAktif('nt');
    const nx = _dz ? Math.max(-4, Math.min(104, startLeft + dx)) : Math.max(2, Math.min(135, startLeft + dx));   // 🆕 sağ: yedeğe taşabilsin
    const ny = _dz ? Math.max(-6, Math.min(260, startTop + dy)) : Math.max(2, Math.min(108, startTop  + dy));
    if (_dz && typeof _dzOtoY === 'function') _dzOtoY(touch.clientY);
    node.style.left = nx + '%';
    node.style.top  = ny + '%';
    node.style.zIndex = '99999';   // 🆕 yedek panelinin üstünde görünsün
    lastX = touch.clientX; lastY = touch.clientY;
    try {
      const _bl = document.querySelector('#nt-formation .form-side-panel');
      if (_bl) { const _r = _bl.getBoundingClientRect(); _bl.classList.toggle('bench-drop-active', touch.clientX >= _r.left && touch.clientX <= _r.right && touch.clientY >= _r.top && touch.clientY <= _r.bottom); }
    } catch(_){}

    const targetIdx = _ntFindSwapTarget(idx, nx, ny, SWAP_THRESHOLD);
    document.querySelectorAll('#nt-pitchPlayers .fpn.swap-target').forEach(el => el.classList.remove('swap-target'));
    if (targetIdx !== -1) {
      const targetEl = document.getElementById('nt-fpn_' + targetIdx);
      if (targetEl) targetEl.classList.add('swap-target');
    }
  }
  function onEnd(e) {
    try { if (typeof _dzOtoDur === 'function') _dzOtoDur(); } catch(_) {}
    if(!dragging) return;
    dragging = false;
    // 🆕 Listener'ları KALDIR (artık gerek yok)
    document.removeEventListener('mousemove',  onMove);
    document.removeEventListener('touchmove',  onMove);
    document.removeEventListener('mouseup',    onEnd);
    document.removeEventListener('touchend',   onEnd);
    document.removeEventListener('touchcancel', onEnd);

    node.style.transition = '';
    node.style.zIndex = '5';
    node.classList.remove('is-dragging');
    document.querySelectorAll('#nt-pitchPlayers .fpn.swap-target').forEach(el => el.classList.remove('swap-target'));
    try { const _bl0 = document.querySelector('#nt-formation .form-side-panel'); if (_bl0) _bl0.classList.remove('bench-drop-active'); } catch(_){}

    if (!didMove) {
      // Sadece tıklama → click handler tetiklenir, drag yok (891: mevki OVR penceresi)
      return;
    }
    node._moTas = Date.now();   // 891 — sürüklemenin ardından gelen tıklama pencere açmasın

    // 🆕 Yedek paneline bırakıldı mı? → sahadan çıkar, maç kadrosu yedeğine ekle (kulüp ile aynı)
    {
      let _cx = lastX, _cy = lastY;
      try { if ((!_cx || !_cy) && e) { const _t = (e.changedTouches && e.changedTouches[0]) ? e.changedTouches[0] : e; if (_t) { _cx = _t.clientX; _cy = _t.clientY; } } } catch(_){}
      if (typeof _ntMovePitchToBenchIfDropped === 'function' && _ntMovePitchToBenchIfDropped(idx, _cx, _cy)) return;
    }

    const curLeft = parseFloat(node.style.left);
    const curTop  = parseFloat(node.style.top);
    const targetIdx = _ntFindSwapTarget(idx, curLeft, curTop, SWAP_THRESHOLD);

    if (targetIdx !== -1 && Array.isArray(_ntActivePitchPlayers)) {
      // SWAP: sadece player değişir, slot (x,y,pos) sabit
      const tmp = _ntActivePitchPlayers[idx].player;
      _ntActivePitchPlayers[idx].player = _ntActivePitchPlayers[targetIdx].player;
      _ntActivePitchPlayers[targetIdx].player = tmp;
      // 🆕 Slot data'sına dokunma (x/y/pos sabit) — sadece görsel olarak orijinale dön
      try { if (typeof ntSaveStrategy === 'function') ntSaveStrategy(true); } catch(_) {}
      if (typeof ntRenderPitch === 'function') ntRenderPitch();
    } else {
      // 🆕 BOŞ SLOTA bırakıldı mı? → oyuncuyu o boş slota taşı (eski slot "+" olur)
      const _eIdx = (typeof _ntFindEmptySlotTarget === 'function') ? _ntFindEmptySlotTarget(curLeft, curTop, SWAP_THRESHOLD + 6) : -1;
      if (_eIdx !== -1 && Array.isArray(_ntActivePitchPlayers) && _ntActivePitchPlayers[idx]) {
        const _sl = (NT_FORMATIONS[_ntCurrentFormation] || [])[_eIdx];
        if (_sl) {
          _ntActivePitchPlayers[idx].slotIdx = _eIdx;
          _ntActivePitchPlayers[idx].x = _sl.x; _ntActivePitchPlayers[idx].y = _sl.y; _ntActivePitchPlayers[idx].pos = _sl.pos;
          try { if (typeof ntSaveStrategy === 'function') ntSaveStrategy(); } catch(_){}
          if (typeof ntRenderPitch === 'function') ntRenderPitch();
          return;
        }
      }
      // Swap/boş slot yok → orijinal pozisyona kayma (slot sabit)
      node.style.left = originalLeft + '%';
      node.style.top  = originalTop + '%';
    }
  }
  // Sadece START listener'ları node'a bağlı (move/end drag boyunca eklenir/silinir)
  node.addEventListener('mousedown',  onStart);
  node.addEventListener('touchstart', onStart, { passive: false });
}

function _ntFindSwapTarget(srcIdx, x, y, threshold) {
  if (!Array.isArray(_ntActivePitchPlayers)) return -1;
  const adaylar = [];
  for (let i = 0; i < _ntActivePitchPlayers.length; i++) {
    if (i === srcIdx) continue;
    const e = _ntActivePitchPlayers[i];
    if (!e || !e.player) continue;
    if (typeof e.x !== 'number' || typeof e.y !== 'number') continue;
    adaylar.push({ i, x: e.x, y: e.y });
  }
  const _p = document.getElementById('nt-formPitch') || document.getElementById('formPitch');
  return _dndEnYakin(adaylar, x, y, _p, 0);
}

// 🆕 NT: yakındaki BOŞ formasyon slotunu bul
function _ntFindEmptySlotTarget(x, y, threshold) {
  const slots = (typeof NT_FORMATIONS !== 'undefined' && NT_FORMATIONS[_ntCurrentFormation]) ? NT_FORMATIONS[_ntCurrentFormation] : [];
  const used = new Set((_ntActivePitchPlayers||[]).map(e => (e && e.player) ? e.slotIdx : null));
  const adaylar = [];
  slots.forEach((sl, i) => { if (!used.has(i)) adaylar.push({ i, x: sl.x, y: sl.y }); });
  const _p = document.getElementById('nt-formPitch') || document.getElementById('formPitch');
  return _dndEnYakin(adaylar, x, y, _p, 8);
}

// 🆕 NT: bench oyuncusunu boş slota ekle (sürükle-bırak)
// 🆕 Saha oyuncusu yedek paneline bırakıldıysa → sahadan çıkar, maç kadrosu yedeğine ekle (kulüp _movePitchToBenchIfDropped birebir)
function _ntMovePitchToBenchIfDropped(pitchIdx, cx, cy) {
  if (typeof ntCanEditFormation === 'function' && !ntCanEditFormation()) return false;
  const benchEl = document.getElementById('nt-benchList');
  if (!benchEl || typeof cx !== 'number' || typeof cy !== 'number') return false;
  let over = false;
  try { const br = benchEl.getBoundingClientRect(); if (cx >= br.left && cx <= br.right && cy >= br.top && cy <= br.bottom) over = true; } catch(_){}
  if (!over) {
    try {
      const _node = document.getElementById('nt-fpn_' + pitchIdx);
      const _disp = _node ? _node.style.display : null;
      if (_node) _node.style.display = 'none';
      const elAt = document.elementFromPoint(cx, cy);
      if (_node) _node.style.display = _disp || '';
      if (elAt && (elAt === benchEl || benchEl.contains(elAt) || (elAt.closest && elAt.closest('.form-side-panel')))) over = true;
    } catch(_){}
  }
  if (!over) {
    try {
      const _dzA = (typeof _dzAktif === 'function') && _dzAktif('nt');
      const pw = _dzA ? document.getElementById('nt-formPitch') : (document.querySelector('#nt-formation .form-pitch-wrap') || document.getElementById('nt-formPitch'));
      if (pw) {
        const pr = pw.getBoundingClientRect();
        if (pr.width > 0) {
          if (_dzA) { if (cy >= pr.bottom + 2) over = true; }        // 577 — yedekler sahanın altında
          else if (cx >= pr.right - 8) over = true;
        }
      }
    } catch(_){}
  }
  if (!over) return false;
  const entry = (_ntActivePitchPlayers || [])[pitchIdx];
  if (!entry || !entry.player) return false;
  const pl = entry.player;
  _ntActivePitchPlayers.splice(pitchIdx, 1);   // sahadan çıkar → slot "+" olur
  try {
    if (typeof _ntEnsureBench === 'function') _ntEnsureBench();
    if (Array.isArray(_ntMatchSquadBench) && _ntMatchSquadBench.length < 7 && !_ntMatchSquadBench.includes(pl.num)) {
      _ntMatchSquadBench.push(pl.num);
    }
    _ntBenchUserManaged = true;
  } catch(_){}
  try { if (typeof ntSaveStrategy === 'function') ntSaveStrategy(true); } catch(_){}
  if (typeof ntRenderPitch === 'function') ntRenderPitch();
  try { if (typeof showToast === 'function') showToast('Yedeğe alındı: ' + (pl.name.split('_')[1] || pl.name)); } catch(_){}
  return true;
}

function ntDoBenchToEmptySlot(slotIdx) {
  if (typeof ntCanEditFormation === 'function' && !ntCanEditFormation()) { if (typeof _ntNoPermToast==='function') _ntNoPermToast(); _ntDragBenchIdx = null; return; }
  if (_ntDragBenchIdx === null) return;
  const _sl = (NT_FORMATIONS[_ntCurrentFormation] || [])[slotIdx]; if (!_sl) return;
  const bPlayer = _ntCurrentSubs && _ntCurrentSubs[_ntDragBenchIdx]; if (!bPlayer) return;
  const roster = ntEnsureRoster();
  _ntActivePitchPlayers.push({ rosterIdx: roster.indexOf(bPlayer), slotIdx, pos: _sl.pos, s: _sl.s, x: _sl.x, y: _sl.y, player: bPlayer });
  // maç kadrosu yedeğinden çıkar (artık ilk 11'de)
  try { if (typeof _ntEnsureBench === 'function') _ntEnsureBench(); const _bi = _ntMatchSquadBench.indexOf(bPlayer.num); if(_bi!==-1){ _ntMatchSquadBench.splice(_bi,1); _ntBenchUserManaged = true; } } catch(_){}
  _ntDragBenchIdx = null;
  try { ntSaveStrategy(true); } catch(_){}
  ntRenderPitch();
}

// 🆕 NT: boş slota tek-tıkla en uygun oyuncuyu yerleştir
function ntOpenSlotPicker(slotIdx) {
  if (typeof ntCanEditFormation === 'function' && !ntCanEditFormation()) { if (typeof _ntNoPermToast==='function') _ntNoPermToast(); return; }
  const _sl = (NT_FORMATIONS[_ntCurrentFormation] || [])[slotIdx]; if (!_sl) return;
  const roster = ntEnsureRoster();
  const onPitch = new Set((_ntActivePitchPlayers||[]).map(e => e && e.player && e.player.num));
  const avail = (roster||[]).filter(p => p && !onPitch.has(p.num));
  if (!avail.length) return;
  const POSGRP = (typeof POS_GROUP !== 'undefined') ? POS_GROUP : null;
  const _grp = p => p.posGroup || (POSGRP && POSGRP[p.pos]) || (typeof _ntPosFamily==='function'?_ntPosFamily(p.pos):p.pos);
  const fam = (typeof _ntPosFamily === 'function') ? _ntPosFamily(_sl.pos) : _sl.pos;
  const _g = (p) => (typeof p._ntG === 'number') ? p._ntG : _ntG2(p);
  const _uy = avail.filter(p => p.ntMusait !== false);
  const _av = _uy.length ? _uy : avail;
  let pool = _av.filter(p => _grp(p) === fam).sort((a,b)=>_g(b)-_g(a));
  if (!pool.length) pool = [..._av].sort((a,b)=>_g(b)-_g(a));
  const chosen = pool[0]; if (!chosen) return;
  _ntActivePitchPlayers.push({ rosterIdx: roster.indexOf(chosen), slotIdx, pos: _sl.pos, x: _sl.x, y: _sl.y, player: chosen });
  try { ntSaveStrategy(true); } catch(_){}
  ntRenderPitch();
}

// 🆕 NT: İlk 11 dolmadan Kaydet pasif + başkan değilse gizle
function _ntUpdateSaveBtn() {
  const btn = document.getElementById('ntSaveFormationBtn');
  if (!btn) return;
  if (typeof ntCanEditFormation === 'function' && !ntCanEditFormation()) { btn.style.display = 'none'; return; }
  btn.style.display = '';
  const cnt = Array.isArray(_ntActivePitchPlayers) ? _ntActivePitchPlayers.filter(e=>e&&e.player).length : 0;
  const full = (cnt === 11);
  btn.disabled = !full;
  btn.classList.toggle('disabled', !full);
  btn.title = full ? 'Dizilişi kaydet' : ('İlk 11 tamamlanmalı (' + cnt + '/11)');
}

function ntRenderPitch() {
  const pitchEl = document.getElementById('nt-pitchPlayers');
  const benchEl = document.getElementById('nt-benchList');
  if(!pitchEl || !benchEl) return;
  const roster = ntEnsureRoster();

  // 🆕 Pos → grup helper (NT'de pos zaten grup ismi olabilir: GK/DEF/MID/FWD)
  const _toPosGroup = (pos) => {
    if (!pos) return 'MID';
    if (typeof POS_GROUP !== 'undefined' && POS_GROUP[pos]) return POS_GROUP[pos];
    if (['GK','DEF','MID','FWD'].includes(pos)) return pos;
    return 'MID';
  };

  // Pitch oyuncular — TÜM formasyon slotları (boş olana "+")
  pitchEl.innerHTML = '';
  const _ntSlots = (typeof NT_FORMATIONS !== 'undefined' && NT_FORMATIONS[_ntCurrentFormation]) ? NT_FORMATIONS[_ntCurrentFormation] : [];
  const _ntCanEdit = (typeof ntCanEditFormation === 'function') ? ntCanEditFormation() : false;
  const _ntBySlot = {};
  (_ntActivePitchPlayers||[]).forEach((e, ai) => { if (e && e.player && typeof e.slotIdx === 'number') _ntBySlot[e.slotIdx] = { entry:e, ai }; });
  _ntSlots.forEach((_slot, _si) => {
    const _hit = _ntBySlot[_si];
    if (!(_hit && _hit.entry && _hit.entry.player)) {
      const en = document.createElement('div');
      en.className = 'fpn fpn-empty';
      en.id = 'nt-fpn_empty_' + _si;
      en.style.left = _slot.x + '%';
      en.style.top  = _slot.y + '%';
      en.dataset.slot = _si;
      en.innerHTML = '<div class="fpn-empty-card"><div class="fpn-empty-plus">+</div><div class="fpn-empty-pos">' + (_slot.s || _slot.pos) + '</div></div>';
      en.addEventListener('dragover', e => { e.preventDefault(); en.classList.add('drop-hover'); });
      en.addEventListener('dragleave', () => en.classList.remove('drop-hover'));
      en.addEventListener('drop', e => { e.preventDefault(); en.classList.remove('drop-hover'); if (typeof ntDoBenchToEmptySlot === 'function') ntDoBenchToEmptySlot(_si); });
      if (_ntCanEdit) { en.style.cursor = 'pointer'; en.addEventListener('click', () => { if (typeof ntOpenSlotPicker === 'function') ntOpenSlotPicker(_si); }); }
      pitchEl.appendChild(en);
      return;
    }
    const entry = _hit.entry;
    const idx = _hit.ai;
    entry.x = _slot.x; entry.y = _slot.y; entry.pos = _slot.pos; entry.s = _slot.s; entry.slotIdx = _si;
    let p = entry.player;
    // Tam oyuncu objesini roster'dan çöz (abilities dahil — mevki-OVR için)
    try { const _full = roster.find(x => x && (x.num === p.num || (p.id != null && x.id === p.id))); if (_full) p = _full; } catch(e){}
    const isUser = !!p.isUser;
    const isCap  = _ntKaptanMi(p);
    const shortName = p.name.split('_')[1] || p.name;
    const node = document.createElement('div');
    node.className = 'fpn';
    node.id = 'nt-fpn_' + idx;
    node.style.left = entry.x + '%';
    node.style.top  = entry.y + '%';
    node.dataset.idx = idx;

    // Avatar kaynağı (kulüp ile aynı): kullanıcı→avatarId, gerçek→avatar_id, bot→emoji
    let userAvatarHTML = null;
    try {
      if (isUser && typeof authUser !== 'undefined' && authUser && authUser.avatarId && typeof getAvatarEmoji === 'function') {
        const result = getAvatarEmoji(authUser.avatarId, p.pos);
        if (typeof result === 'string' && result.indexOf('<img') === 0) userAvatarHTML = result;
      } else if (!isUser && !p.isBot && p.avatar_id && typeof getAvatarEmoji === 'function') {
        const result = getAvatarEmoji(p.avatar_id, p.pos);
        if (typeof result === 'string' && result.indexOf('<img') === 0) userAvatarHTML = result;
      }
    } catch(e) { userAvatarHTML = null; }

    // Mevki-dışı OVR cezası: slotun alt mevkisine (s) göre
    const _slotSub = entry.s || ((typeof subPosOf === 'function') ? subPosOf(p) : 'CM');
    const ovr = pitchSlotOvr({ ...p, overall: _ntPlayerSkill(p) }, _slotSub);

    // Kart etiketi/rengi oyuncunun KENDİ alt mevkisine göre (slot'a değil)
    const posGroup = (typeof POS_GROUP !== 'undefined' && POS_GROUP[entry.pos]) || 'MID';
    const _ownSub = (typeof subPosOf === 'function') ? subPosOf(p) : (p.subPos || p.sub_pos || p.pos || 'CM');
    const posClass = 'pos-' + ((typeof subPosGroupOf === 'function') ? subPosGroupOf(_ownSub) : posGroup);

    const avatarInner = (typeof _dzYuzHtml === 'function') ? _dzYuzHtml(p, isUser) : (userAvatarHTML || (p.avatar || '⚽'));   // 577 — Kart 1
    const _dzDis = glSlotCarpan(p, _slotSub) < 1;   // 943

    // İsim: ilk ad tam, kalan baş harf (Özcan Yılmaz → Özcan Y.)
    const _np = shortName.trim().split(/\s+/);
    const displayName = _np.length > 1
      ? _np[0] + ' ' + _np.slice(1).map(w => w.charAt(0).toUpperCase() + '.').join(' ')
      : shortName;

    const flagHtml = p.nation ? `<span class="fpn-flag">${p.nation}</span>` : '';

    // Cezalı/sakat badge — 588: milli maçta kulüp kart cezası geçmez; sakatlık + MİLLİ ceza
    let pitchStatus = '';
    const _inj = isPlayerInjured(p);
    if (_inj) {
      const _kt = (typeof _sakatlikKalanMetin === 'function') ? (_sakatlikKalanMetin(_tsMsC(p.injuryUntil)) || '') : '';
      pitchStatus = `<span class="fpn-status fpn-inj" title="🚑 ${_kt}">🚑</span>`;
    } else if ((p.ntBan || 0) > 0) {
      pitchStatus = `<span class="fpn-status fpn-susp" title="Milli ceza">🟥</span>`;
    }
    if (_inj || (p.ntBan || 0) > 0 || p.ntMusait === false) node.classList.add('dz-uygunsuz');

    const circleClasses = ['fpn-circle', posClass];
    if (typeof getOvrTier === 'function') circleClasses.push(getOvrTier(ovr));
    if (isUser) circleClasses.push('is-user');
    else if (isCap) circleClasses.push('is-captain');
    if (_dzDis) circleClasses.push('dz-dis');
    if (isCap) circleClasses.push('dz-kap');

    node.innerHTML = `
      <div class="${circleClasses.join(' ')}">
        <div class="fpn-top">
          <span class="fpn-ovr">${ovr}</span>
          ${flagHtml}
        </div>
        <div class="fpn-avatar">${avatarInner}</div>
        <div class="fpn-name">${displayName}</div>
        <div class="fpn-bottom">
          <div class="fpn-pos">${_ownSub}</div>
          <div class="fpn-num2">#${p.num}</div>
        </div>
        ${(typeof _dzKdHtml === 'function') ? _dzKdHtml(p, 'fpn-kd') : ''}
        ${_dzDis ? '<span class="fpn-uyari">!</span>' : ''}
        ${pitchStatus}
      </div>
    `;

    // 🆕 Tıklama davranışı kaldırıldı — sadece sürükle-bırak ile değişim
    // 891 — tek dokunuş: mevki OVR penceresi (sürükleme bunu açmaz)
    node._moP = p; node._moS = _slotSub;
    node.addEventListener('click', () => { if (Date.now() - (node._moTas || 0) < 600) return; if (typeof moAc === 'function') moAc(node._moP, node._moS, null, node); });
    // Bench → pitch drop hedefi
    node.addEventListener('dragover',  e => { e.preventDefault(); node.classList.add('drop-hover'); });
    node.addEventListener('dragleave', e => { node.classList.remove('drop-hover'); });
    node.addEventListener('drop', e => {
      e.preventDefault();
      node.classList.remove('drop-hover');
      ntDoBenchToPitchSwap(idx);
    });
    // Pitch içi sürükle-bırak: başka oyuncunun üzerine bırakılırsa swap
    ntMakeDraggable(node, idx);
    pitchEl.appendChild(node);
  });

  // Yedekler — drag'lanabilir
  // 🆕 Maç kadrosu yedek listesine göre filtrele (tüm kadro DEĞİL, _ntMatchSquadBench)
  const usedNums = new Set(_ntActivePitchPlayers.map(e => e.player?.num).filter(Boolean));
  _ntEnsureBench();
  const benchOrder = (Array.isArray(_ntMatchSquadBench) ? _ntMatchSquadBench : [])
    .filter(num => !usedNums.has(num));
  const subs = benchOrder
    .map(num => roster.find(p => p && p.num === num))
    .filter(Boolean);
  // Cache for ntDoBenchToPitchSwap (idx → player)
  _ntCurrentSubs = subs;
  // Yetki: sadece başkan/yardımcı çıkarabilir
  const _ntCanRemoveBench = (typeof fedUserIsOfficial === 'function') && fedUserIsOfficial();
  let benchHtml = '';
  const BENCH_SIZE = 7;
  const _now = Date.now();
  for(let i = 0; i < BENCH_SIZE; i++) {
    if(i < subs.length) {
      const p = subs[i];
      const _bn = (p.name.split('_')[1] || p.name).trim().split(/\s+/);
      const shortName = _bn.length > 1
        ? _bn[0] + ' ' + _bn.slice(1).map(w => w.charAt(0).toUpperCase() + '.').join(' ')
        : (p.name.split('_')[1] || p.name);
      const pgrp = (typeof POS_GROUP !== 'undefined' && POS_GROUP[p.pos]) || _toPosGroup(p.pos);
      // 🆕 gerçek yetenek (overall herkeste 10)
      const ovr = (typeof _ntPlayerSkill === 'function')
        ? _ntPlayerSkill(p) : (p.overall != null ? p.overall : (p.rating || 10));
      const tier = (typeof getOvrTier === 'function') ? getOvrTier(ovr) : '';

      let avatarHTML = null;
      try {
        if(p.isUser && typeof authUser !== 'undefined' && authUser && authUser.avatarId && typeof getAvatarEmoji === 'function') {
          const r = getAvatarEmoji(authUser.avatarId, p.pos);
          if(typeof r === 'string' && r.indexOf('<img') === 0) avatarHTML = r;
        } else if(!p.isUser && !p.isBot && p.avatar_id && typeof getAvatarEmoji === 'function') {
          const r = getAvatarEmoji(p.avatar_id, p.pos);
          if(typeof r === 'string' && r.indexOf('<img') === 0) avatarHTML = r;
        }
      } catch(e) { avatarHTML = null; }
      const avatarInner = (typeof _dzYuzHtml === 'function') ? _dzYuzHtml(p, !!p.isUser) : (avatarHTML || (p.avatar || '⚽'));   // 577

      // 588 — milli maçta kulüp kart cezası geçmez: sakatlık ve MİLLİ ceza
      let statusHtml = '';
      const _inj = (typeof isPlayerInjured === 'function') ? isPlayerInjured(p) : ((p.injuryUntil || 0) > _now);
      const _ntCz = (p.ntBan || 0) > 0;
      if (_inj) statusHtml = `<span class="bench-card-status" title="Sakat">🚑</span>`;
      else if (_ntCz) statusHtml = `<span class="bench-card-status" title="Milli ceza">🟥</span>`;

      const removeBtn = (_ntCanRemoveBench && !p.isUser)
        ? `<div class="bench-card-remove" title="Maç kadrosundan çıkar" onclick="confirmNtMatchSquadRemove(${p.num}, event)">✕</div>` : '';

      const flagHtml = p.nation ? `<span class="bench-card-flag">${p.nation}</span>` : '';

      const _renkGrp = (() => { try { return subPosGroupOf(subPosOf(p)); } catch(e) { return pgrp; } })();   // 823 — renk yazan mevkiden
      const classes = ['bench-card', 'pos-' + _renkGrp];
      if (tier) classes.push(tier);
      if (p.isUser) classes.push('dz-ben');
      if (typeof _ntKaptanMi === 'function' && _ntKaptanMi(p)) classes.push('dz-kap');
      if (_inj || _ntCz || p.ntMusait === false) classes.push('dz-uygunsuz');   // 588

      benchHtml += `<div class="${classes.join(' ')}" id="nt-bench_${i}" data-posgroup="${pgrp}"
        draggable="true" ondragstart="ntBenchDragStart(event,${i})" ondragend="ntBenchDragEnd(event)">
        ${removeBtn}
        <div class="bench-card-top"><span class="bench-card-ovr">${ovr}</span>${flagHtml}</div>
        <div class="bench-card-avatar">${avatarInner}</div>
        <div class="bench-card-name">${shortName}</div>
        <div class="bench-card-bottom"><div class="bench-card-pos">${subPosOf(p)}</div><div class="bench-card-num">#${p.num}</div></div>
        ${(typeof _dzKdHtml === 'function') ? _dzKdHtml(p, 'bench-card-kd') : ''}
        ${statusHtml}
      </div>`;
    } else {
      benchHtml += `<div class="bench-card bench-card-empty bench-empty-slot">
        <div class="bench-card-avatar bench-plus">+</div>
        <div class="bench-card-name" style="color:var(--text3)">Boş</div>
      </div>`;
    }
  }
  benchEl.innerHTML = benchHtml;
  if (typeof _ntUpdateSaveBtn === 'function') _ntUpdateSaveBtn();

  // Ortalamalar
  const ratings = { atk:[], mid:[], def:[], gk:[] };
  const _ntG = (p) => (typeof _ntPlayerSkill === 'function') ? _ntPlayerSkill(p) : ((p && p.overall) || 0);
  _ntActivePitchPlayers.forEach(entry => {
    const fam = _ntPosFamily(entry.pos);
    const v = _ntG(entry.player);   // 🆕 gerçek yetenek (overall herkeste 10)
    if(fam === 'GK') ratings.gk.push(v);
    else if(fam === 'DEF') ratings.def.push(v);
    else if(fam === 'MID') ratings.mid.push(v);
    else if(fam === 'FWD') ratings.atk.push(v);
  });
  const avg = arr => arr.length ? Math.round(arr.reduce((a,b)=>a+b,0)/arr.length) : 0;
  const setBar = (id, val) => {
    const fill = document.getElementById('nt-trbFill'+id);
    const txt = document.getElementById('nt-trbVal'+id);
    if(fill) fill.style.width = val + '%';
    if(txt) txt.textContent = val || '--';
  };
  setBar('Atk', avg(ratings.atk));
  setBar('Mid', avg(ratings.mid));
  setBar('Def', avg(ratings.def));
  setBar('GK', avg(ratings.gk));

  // İlk 11 ortalaması — 🆕 gerçek yetenekten
  const allOvr = _ntActivePitchPlayers.map(e => _ntG(e.player));
  const lineupAvg = avg(allOvr);
  const elAvg = document.getElementById('nt-lineupAvg');
  if(elAvg) {
    elAvg.textContent = lineupAvg || '--';
    if(lineupAvg >= 80) elAvg.style.color = 'var(--accent)';
    else if(lineupAvg >= 70) elAvg.style.color = '#ffd54f';
    else if(lineupAvg >= 60) elAvg.style.color = '#ff9800';
    else elAvg.style.color = '#ef5350';
  }

  tkOzetCiz();   // 586 — aktif plan çipleri
  try { if (typeof _dzSahaBoy === 'function') { _dzSahaBoy('nt'); _dzYedekBaslik('nt'); _dzYedekBagla('nt'); } } catch(e) {}
}

// ── NT Bench → Pitch Sürükle-Bırak ──
let _ntDragBenchIdx = null;
let _ntCurrentSubs = []; // bench render sırasında oluşan subs cache'i

function ntBenchDragStart(e, idx) {
  _ntDragBenchIdx = idx;
  e.dataTransfer.effectAllowed = 'move';
  e.dataTransfer.setData('text/plain', idx);
  // Tüm pitch oyuncularını drop hedefi olarak vurgula
  if (!((typeof _dzAktif === 'function') && _dzAktif('nt'))) document.querySelectorAll('#nt-pitchPlayers .fpn').forEach(n => n.classList.add('swap-target'));
  setTimeout(() => {
    const el = document.getElementById('nt-bench_' + idx);
    if(el) el.style.opacity = '0.4';
  }, 0);
}

function ntBenchDragEnd(e) {
  _ntDragBenchIdx = null;
  document.querySelectorAll('#nt-pitchPlayers .fpn').forEach(n => n.classList.remove('swap-target','drop-hover'));
  document.querySelectorAll('#nt-benchList .bench-item, #nt-benchList .bench-card').forEach(b => b.style.opacity = '');
}

function ntDoBenchToPitchSwap(pitchIdx) {
  if(!ntCanEditFormation()) { _ntNoPermToast(); _ntDragBenchIdx = null; return; }
  if(_ntDragBenchIdx === null) return;
  const bPlayer = _ntCurrentSubs[_ntDragBenchIdx];
  const pEntry  = _ntActivePitchPlayers[pitchIdx];
  if(!bPlayer || !pEntry) return;
  const displaced = pEntry.player;
  // Bench oyuncuyu sahaya yaz
  const roster = ntEnsureRoster();
  pEntry.player = bPlayer;
  pEntry.rosterIdx = roster.indexOf(bPlayer);
  // 🆕 İki yönlü: bench oyuncu maç kadrosundan çıkar, sahadan inen oyuncu yedeğe iner
  try {
    if (typeof _ntEnsureBench === 'function') _ntEnsureBench();
    if (Array.isArray(_ntMatchSquadBench)) {
      const _bi = _ntMatchSquadBench.indexOf(bPlayer.num);
      if (_bi !== -1) _ntMatchSquadBench.splice(_bi, 1);
      if (displaced && displaced.num != null && !_ntMatchSquadBench.includes(displaced.num) && _ntMatchSquadBench.length < 7) {
        _ntMatchSquadBench.push(displaced.num);
      }
      _ntBenchUserManaged = true;
    }
  } catch(_){}
  _ntDragBenchIdx = null;
  const shortB = bPlayer.name.split('_')[1] || bPlayer.name.split(' ').pop();
  ntShowSwapToast(shortB + ' sahaya alındı');
  ntSaveStrategy(true);
  ntRenderPitch();
}

function ntShowSwapToast(msg) {
  const t = document.createElement('div');
  t.style.cssText = 'position:fixed;bottom:90px;left:50%;transform:translateX(-50%);background:var(--accent2);color:var(--bg);padding:7px 16px;border-radius:20px;font-size:11px;font-weight:700;z-index:9999;font-family:Twemoji Country Flags,"Barlow Condensed",sans-serif;letter-spacing:.5px;white-space:nowrap';
  t.textContent = '🔄 ' + msg;
  document.body.appendChild(t);
  setTimeout(() => t.remove(), 2000);
}

// Tooltip göster
function ntShowTooltip(idx, scope, event) {
  if(event) event.stopPropagation();
  const tt = document.getElementById('nt-playerTooltip');
  if(!tt) return;
  const roster = ntEnsureRoster();
  let p = null;
  if(scope === 'pitch') p = _ntActivePitchPlayers[idx]?.player;
  else if(scope === 'bench') {
    const usedNums = new Set(_ntActivePitchPlayers.map(e => e.player?.num).filter(Boolean));
    const subs = roster.filter(pp => !usedNums.has(pp.num));
    p = subs[idx];
  }
  if(!p) return;
  _ntSelectedTooltipIdx = idx;
  _ntTooltipScope = scope;
  document.getElementById('nt-ptName').textContent = p.name;
  document.getElementById('nt-ptRole').textContent = p.nation + ' · #' + p.num;
  document.getElementById('nt-ptOvr').textContent = _ntPlayerSkill(p);
  document.getElementById('nt-ptPos').textContent = p.pos;
  tt.style.display = 'block';
}

function ntHideTooltip() {
  const tt = document.getElementById('nt-playerTooltip');
  if(tt) tt.style.display = 'none';
  _ntSelectedTooltipIdx = null;
  _ntTooltipScope = null;
}

// Pitch <-> bench takas
function ntSwapTooltipPlayer() {
  if(!ntCanEditFormation()) { _ntNoPermToast(); ntHideTooltip(); return; }
  if(_ntSelectedTooltipIdx === null) return;
  const roster = ntEnsureRoster();
  if(_ntTooltipScope === 'bench') {
    // Yedekten saha'ya: aynı pozisyon ailesinde olan ilk pitch oyuncusuyla takas
    const usedNums = new Set(_ntActivePitchPlayers.map(e => e.player?.num).filter(Boolean));
    const subs = roster.filter(pp => !usedNums.has(pp.num));
    const benchPlayer = subs[_ntSelectedTooltipIdx];
    if(!benchPlayer) return;
    const fam = benchPlayer.pos;
    const target = _ntActivePitchPlayers.find(e => _ntPosFamily(e.pos) === fam);
    if(!target) {
      alert(fam + ' pozisyonunda saha oyuncusu yok');
      return;
    }
    target.player = benchPlayer;
    target.rosterIdx = roster.indexOf(benchPlayer);
  } else if(_ntTooltipScope === 'pitch') {
    // Saha'dan yedeğe: kullanıcıya alternatif yedek seçtirmek karmaşık, basit takas
    // İlk uygun yedeği getir
    const target = _ntActivePitchPlayers[_ntSelectedTooltipIdx];
    if(!target) return;
    const usedNums = new Set(_ntActivePitchPlayers.map(e => e.player?.num).filter(Boolean));
    const subs = roster.filter(pp => !usedNums.has(pp.num));
    const fam = _ntPosFamily(target.pos);
    const replacement = subs.find(s => s.pos === fam);
    if(!replacement) {
      alert(fam + ' pozisyonunda yedek yok');
      return;
    }
    target.player = replacement;
    target.rosterIdx = roster.indexOf(replacement);
  }
  ntHideTooltip();
  ntSaveStrategy(true);
  ntRenderPitch();
}

// Helper: yetkisi olmayanlar için toast
function _ntNoPermToast() {
  const t = document.createElement('div');
  t.style.cssText = 'position:fixed;bottom:90px;left:50%;transform:translateX(-50%);background:#ef5350;color:#fff;padding:8px 16px;border-radius:20px;font-size:12px;font-weight:700;z-index:9999;font-family:Twemoji Country Flags,"Barlow Condensed",sans-serif;letter-spacing:.5px;white-space:nowrap';
  t.textContent = '🔒 ' + ((typeof T === 'function') ? T('Yalnız teknik direktör ve yardımcıları değiştirebilir') : 'Yalnız teknik direktör ve yardımcıları değiştirebilir');
  document.body.appendChild(t);
  setTimeout(() => t.remove(), 2200);
}

// Formasyon değiştir
function ntApplyFormation(name) {
  if(!ntCanEditFormation()) { _ntNoPermToast(); return; }

  // 🆕 İZOLASYON GARANTİSİ — Kulüp state'i snapshot al, sonunda restore et
  // Milli takım operasyonu yan etki ile kulübü asla etkilemez.
  const _clubFormSnap = (typeof currentFormation !== 'undefined') ? currentFormation : null;
  const _clubLineupSnap = (typeof activePitchPlayers !== 'undefined' && Array.isArray(activePitchPlayers))
    ? activePitchPlayers.map(e => ({ ...e })) : null;

  name = formasyonTasi(name).ad;   // 585
  _ntCurrentFormation = name;
  const slots = NT_FORMATIONS[name];
  // Mevcut oyuncuları yeni slotlara dağıt
  _ntActivePitchPlayers.forEach((entry, i) => {
    const slot = slots[i] || slots[0];
    entry.x = slot.x;
    entry.y = slot.y;
    entry.pos = slot.pos;
    entry.slotIdx = i;
  });
  ntSaveStrategy(true);
  ntRenderPitch();

  // 🆕 İZOLASYON KONTROLÜ — Kulüp state'i bozulduysa restore
  if (typeof currentFormation !== 'undefined' && _clubFormSnap !== null && currentFormation !== _clubFormSnap) {
    console.warn('[nt-isolation] Kulüp formasyonu yan etkiyle değişti, restore ediliyor:', _clubFormSnap);
    currentFormation = _clubFormSnap;
    try {
      const _fpl = document.getElementById('formationPickLabel');
      if (_fpl) _fpl.textContent = _clubFormSnap;
    } catch(e) {}
  }
  if (_clubLineupSnap && typeof activePitchPlayers !== 'undefined' && Array.isArray(activePitchPlayers)) {
    let lineupChanged = false;
    if (activePitchPlayers.length !== _clubLineupSnap.length) lineupChanged = true;
    else {
      for (let i = 0; i < _clubLineupSnap.length; i++) {
        const cur = activePitchPlayers[i], snap = _clubLineupSnap[i];
        if (!cur || cur.x !== snap.x || cur.y !== snap.y || cur.pos !== snap.pos || cur.slotIdx !== snap.slotIdx) {
          lineupChanged = true; break;
        }
      }
    }
    if (lineupChanged) {
      console.warn('[nt-isolation] Kulüp dizilişi yan etkiyle değişti, restore ediliyor');
      _clubLineupSnap.forEach((snap, i) => {
        if (activePitchPlayers[i]) Object.assign(activePitchPlayers[i], snap);
      });
    }
  }
}

