// ────────── SOHBET render ──────────
// ═══════════════════════════════════════════════════════════════════════
// 🆕 MİLLİ TAKIM SOHBETİ — GERÇEK MESAJLAŞMA
//   Eskiden bu bölüm sabit-kodlu sahte mesajlar basıyordu; gönder butonunun
//   çağırdığı ntSendChat fonksiyonu HİÇ TANIMLI DEĞİLDİ (ReferenceError).
//   Artık kulüp sohbetiyle aynı `team_chat` tablosunu kullanır:
//     country_code = ülke kodu · team_name = milli takım adı (ör. "Türkiye")
//   Mesaj kartlarını kulüp sohbetinin _teamChatAppendMsg'i çizer (aynı görünüm).
// ═══════════════════════════════════════════════════════════════════════
function _ntChatTakimAdi() {
  return (typeof _ntCountryName === 'function') ? _ntCountryName()
       : (ntActiveCountry());
}
function _ntChatUlke() {
  return ntActiveCountry();
}

function ntRenderChat() {
  const el = document.getElementById('nt-chat');
  if(!el) return;
  // 🆕 526 — kadroda olmayan sohbeti göremez / yazamaz
  if (typeof _ntTamErisim === 'function' && !_ntTamErisim()) {
    el.innerHTML = '';
    try { _ntZiyaretciModuUygula(); } catch(e) {}
    return;
  }
  el.innerHTML = `
    <div class="vt-section nt-chat-section">
      <div class="chat-header-row">
        <div class="vt-title" style="margin:0">💬 Milli Takım Sohbeti</div>
      </div>
      <div class="chat-area" id="ntChatArea"></div>
      <div class="chat-input-row">
        <input class="chat-input" type="text" id="ntChatInput" maxlength="300" autocomplete="off" autocorrect="off" autocapitalize="sentences" enterkeyhint="send" name="csc-sohbet-mesaji" data-lpignore="true" data-1p-ignore data-form-type="other"
               placeholder="Milli takıma mesaj yaz..." onkeydown="if(event.key==='Enter')ntSendChat()"/>
        <button class="chat-send" onmousedown="event.preventDefault()" tabindex="-1" onclick="ntSendChat()">→</button>
      </div>
    </div>
  `;
  try { _ntChatYukleVeCiz(); } catch(e) { console.warn('[nt_chat] render hata:', e); }
  try { _msCiz(); if (_msAcikMi()) _msOkundu(); } catch(e) {}   // 834
}

async function _ntChatYukleVeCiz() {
  const area = document.getElementById('ntChatArea');
  if (!area || !window.sb) return;
  const cc = _ntChatUlke();
  const ntName = _ntChatTakimAdi();
  try {
    const { data, error } = await window.sb.from('team_chat')
      .select('user_id, username, display_name, avatar_id, message, created_at')
      .eq('country_code', cc)
      .eq('team_name', ntName)
      .order('created_at', { ascending: false })
      .limit(200);
    if (error) { console.warn('[nt_chat] okuma hata:', error.message || error); return; }
    const myId = (typeof authUser !== 'undefined' && authUser) ? authUser.id : null;
    area.innerHTML = '';
    area._adRenk = null;   // 770
    const msgs = (data || []).slice().reverse();
    if (!msgs.length) {
      area.innerHTML = '<div style="padding:18px 10px;text-align:center;color:var(--text3);font-size:11.5px">'
        + 'Henüz mesaj yok — ilk yazan sen ol.</div>';
    } else {
      for (const m of msgs) {
        if (typeof _teamChatAppendMsg === 'function') {
          _teamChatAppendMsg(area, m, m.user_id && m.user_id === myId);
        }
      }
    }
    area.scrollTop = area.scrollHeight;
    requestAnimationFrame(() => { area.scrollTop = area.scrollHeight; });
    _ntChatAbone();
  } catch(e) { console.warn('[nt_chat] okuma hata:', e); }
}

// Realtime — kulüp sohbetiyle aynı desen, ayrı kanal
let _ntChatChannel = null;
let _ntChatChannelKey = null;
function _ntChatAbone() {
  if (!window.sb) return;
  const cc = _ntChatUlke();
  const ntName = _ntChatTakimAdi();
  const key = cc + ':' + ntName;
  if (_ntChatChannelKey === key && _ntChatChannel) return;
  if (_ntChatChannel) { try { window.sb.removeChannel(_ntChatChannel); } catch(e) {} _ntChatChannel = null; }
  const benId = () => (typeof authUser !== 'undefined' && authUser && authUser.id) || null;   // 721
  _ntChatChannelKey = key;
  // 690 — kulüp sohbetiyle aynı: veritabanı yayını ('mesaj': kimlik) → içerik tablodan, sırayla
  let _ntSira = Promise.resolve();
  const _ntIsle = (payload) => {
      const m = payload.new;
      if (!m || m.country_code !== cc || m.team_name !== ntName) return;
      if (m.user_id && m.user_id === benId()) return;   // kendi mesajım zaten eklendi
      const area = document.getElementById('ntChatArea');
      if (!area) return;
      const bos = area.querySelector('div[style*="Henüz mesaj yok"]');
      if (bos) area.innerHTML = '';
      if (typeof _teamChatAppendMsg === 'function') _teamChatAppendMsg(area, m, false);
      area.scrollTop = area.scrollHeight;
      try { if (_msAcikMi()) _msOkunduErtele(); } catch(e) {}   // 834
  };
  _ntChatChannel = window.sb.channel('nt_chat:' + key)
    .on('broadcast', { event: 'mesaj' }, (msg) => {
      const p = msg && msg.payload;
      if (!p || p.mid == null || (p.u && p.u === benId())) return;
      _ntSira = _ntSira.then(async () => {
        const { data } = await window.sb.from('team_chat')
          .select('id, country_code, team_name, user_id, username, display_name, avatar_id, message, created_at')
          .eq('id', p.mid).maybeSingle();
        if (data) _ntIsle({ new: data });
      }).catch((e) => console.warn('[nt_chat] mesaj okunamadı:', e));
    })
    .subscribe();
}
function _ntChatAboneKapat() {
  if (_ntChatChannel) { try { window.sb.removeChannel(_ntChatChannel); } catch(e) {} }
  _ntChatChannel = null; _ntChatChannelKey = null;
}
window._ntChatAboneKapat = _ntChatAboneKapat;

async function ntSendChat() {
  const inp = document.getElementById('ntChatInput');
  if (!inp || !inp.value.trim()) return;
  // 🆕 526 — yalnızca kadrodakiler (ve T.D. / yardımcılar) yazabilir
  if (typeof _ntTamErisim === 'function' && !_ntTamErisim()) {
    if (typeof showToast === 'function') showToast('Milli takım sohbetine yalnızca kadrodaki oyuncular yazabilir.');
    return;
  }
  const area = document.getElementById('ntChatArea');
  if (!area) return;
  const text = modFiltre(inp.value.trim().slice(0, 300));
  inp.value = '';

  const me = (typeof authUser !== 'undefined' && authUser) ? authUser : {};
  // Anında kendi mesajını göster
  const bos = area.querySelector('div[style*="Henüz mesaj yok"]');
  if (bos) area.innerHTML = '';
  if (typeof _teamChatAppendMsg === 'function') {
    _teamChatAppendMsg(area, {
      user_id: me.id || null,
      display_name: me.name || me.username || 'Sen',
      avatar_id: me.avatarId || null,
      message: text,
      created_at: new Date().toISOString()
    }, true);
  }
  area.scrollTop = area.scrollHeight;
  requestAnimationFrame(() => { area.scrollTop = area.scrollHeight; });
  inp.focus();

  if (!window.sb) return;
  try {
    const { error } = await window.sb.from('team_chat').insert({
      country_code: _ntChatUlke(),
      team_name: _ntChatTakimAdi(),
      user_id: me.id || null,
      username: me.username || null,
      display_name: me.name || me.username || null,
      avatar_id: me.avatarId || null,
      message: text
    });
    if (error) {
      console.warn('[nt_chat] gönderilemedi:', error.message || error);
      if (typeof showToast === 'function') showToast(ntHataMetni(error, 'Mesaj gönderilemedi'));
    } else if (typeof achBump === 'function') { achBump('chat'); }
  } catch(e) {
    console.warn('[nt_chat] gönderilemedi:', e);
    if (typeof showToast === 'function') showToast('Mesaj gönderilemedi');
  }
}
window.ntSendChat = ntSendChat;

// ═══════════════════════════════════════════════════════════════════════
// FEDERASYON YETKİLİSİ — Milli Takıma Davet
// Yetki: kullanıcının kendi ülkesinin federasyon başkanı veya 3 yardımcısından biri
// Şart: davet edilen oyuncunun uyruğu (= takımının ülkesi) kullanıcının ülkesi olmalı
// Onay gerekmez — milli takım daveti zorunludur. Oyuncuya inbox mesajı gider.
// ═══════════════════════════════════════════════════════════════════════

// 572 — Kullanıcı bu milli takımda yetkili mi (başkan / başkanın seçtiği yardımcı)?
//   cc verilmezse görüntülenen milli takım.
function fedUserIsOfficial(cc) {
  return (typeof ntRol === 'function') && !!ntRol(cc || ntActiveCountry());
}

// Bir oyuncu milli takıma çağrılabilir mi? Ölçüt oyuncunun UYRUĞU (kulübünün ülkesi değil).
// Dönen obj: { allowed:bool, reason:string, alreadyInSquad:bool }
function fedCallupCheck(player, ctx) {
  if (!player) return { allowed: false, reason: 'Oyuncu yok' };
  const cc = (ctx && ctx.playerNationality) || player.nationality || null;
  if (!cc) return { allowed: false, reason: 'Oyuncu uyruğu belirsiz' };
  if (!fedUserIsOfficial(cc)) return { allowed: false, reason: 'Yetkin yok' };
  const pool = ntPlayerPool(cc);
  const pp = _ntHavuzdaBul(cc, player, ctx);
  if (!pp) return { allowed: false, reason: pool.length ? 'Oyuncu havuzda bulunamadı' : 'Havuz yükleniyor…' };
  const e = _ntEtkinKadroYer(cc, pool);
  const i = e.ids.indexOf(pp.ntId);
  if (i !== -1 && !e.oto[i]) return { allowed: false, reason: 'Zaten milli takımda', alreadyInSquad: true };
  return { allowed: true, reason: 'OK' };
}

// 🆕 Uyruk denetimi — Almanya'da oynayan Türk ✔ / Türkiye'de oynayan Alman ✘
function _ntEligible(cc, p) {
  if (!p) return false;
  const nat = p.nationality || null;
  if (!nat) return false;
  return String(nat).toUpperCase() === String(cc).toUpperCase();
}

// Havuzda oyuncuyu bul: ntId → uuid → ad + kulüp
function _ntHavuzdaBul(cc, player, ctx) {
  const pool = ntPlayerPool(cc);
  let pp = null;
  if (player.ntId) pp = pool.find(p => p && p.ntId === player.ntId);
  if (!pp && player.id) pp = pool.find(p => p && p.id === player.id);
  const takim = (ctx && ctx.teamName) || player._team || player.sourceClub || null;
  if (!pp) pp = pool.find(p => p && p.name === player.name && (!takim || p.sourceClub === takim));
  return pp || null;
}

// Yetkili: oyuncuyu milli takıma çağır (zorunlu, onay gerekmez).
//   Bildirimi SUNUCU gönderir ("Milli Takıma Seçildin") — istemci ayrıca mesaj yazmaz.
function fedCallupPlayer(payloadStr) {
  let payload;
  try { payload = JSON.parse(payloadStr); } catch(e) { return; }
  const { player, ctx } = payload || {};
  if (!player) return;
  const cc = (ctx && ctx.playerNationality) || player.nationality || ntActiveCountry();
  if (!_ntEligible(cc, player) && !(ctx && ctx.playerNationality)) {
    if (typeof showToast === 'function') showToast('Bu oyuncu bu ülkenin uyruğunda değil');
    return;
  }
  const check = fedCallupCheck(player, ctx);
  if (!check.allowed) { if (typeof showToast === 'function') showToast(check.reason); return; }
  const pp = _ntHavuzdaBul(cc, player, ctx);
  if (!pp) return;
  if (ntKadroCagir(pp.ntId, cc) && typeof closePlayerModal === 'function') closePlayerModal();
}

// Yetkili: oyuncuyu milli takım kadrosundan çıkar
function fedRemoveFromNT(payloadStr) {
  let payload;
  try { payload = JSON.parse(payloadStr); } catch(e) { return; }
  const { player, ctx } = payload || {};
  if (!player) return;
  const cc = (ctx && ctx.playerNationality) || player.nationality || ntActiveCountry();
  if (!fedUserIsOfficial(cc)) { if (typeof showToast === 'function') showToast('Yetkin yok'); return; }
  const pp = _ntHavuzdaBul(cc, player, ctx);
  if (!pp) { if (typeof showToast === 'function') showToast('Kadroda değil'); return; }
  if (ntKadroCikar(pp.ntId, cc) && typeof closePlayerModal === 'function') closePlayerModal();
}

// ═══════════════════════════════════════════════════════════════════════

// ═══════════════════════════════════════════════════════════════════════
// MİLLİ TAKIM: GRUP / DAVET / VİTRİN — render fonksiyonları
// ═══════════════════════════════════════════════════════════════════════

// EURO National Cup'ta kullanıcının ülkesinin yer aldığı grubu bul
// Dönen: { letter, group, matches, standings, season } veya null (sezon < 2)
function _ntFindUserGroup(cc) {
  // 🆕 Sezon bilgisi Supabase'ten (getSeasonInfo)
  const _si = (typeof getSeasonInfo === 'function') ? getSeasonInfo() : { season: 1 };
  const season = _si.season || 1;
  // Sezon 2'den önce EURO National Cup yok
  if (season < 2) return { season, notStarted: true };
  if (typeof encEnsureState !== 'function') return null;

  let state;
  try { state = encEnsureState(season); }
  catch(e) { return null; }
  if (!state || !state.groups) return null;

  // Kullanıcının ülkesini içeren grubu bul
  const userGroup = state.groups.find(g =>
    g.teams && g.teams.some(t => t.code === cc)
  );
  if (!userGroup) return { season, notQualified: true };

  // Standings hesapla (her ülke için P/W/D/L/GF/GA/GD/Pts)
  let standings = userGroup.standings;
  if (!standings || !standings.length) {
    standings = (typeof encCalcStandings === 'function') ? encCalcStandings(userGroup) : [];
  }

  return {
    season,
    letter: userGroup.id,
    group: userGroup,
    matches: userGroup.matches || [],
    standings,
    userCC: cc
  };
}

let _ntEncLoadTried = {};   // 🆕 EURO Cup state bir kez async yükleme bayrağı
function ntRenderStandings(acilis) {
  // 736 — Turnuvalar › EURO Cup ile aynı bileşen (trn2RenderEuroNation); yalnız kendi alt sekmesi
  const box = document.getElementById('ntStandingsContent');
  if (!box) return;
  const info = (typeof getSeasonInfo === 'function') ? getSeasonInfo() : null;
  const _season = info ? info.season : 1;
  const _preSeason = info ? info.preSeason : false;

  // State yüklü değilse async yükle + tekrar render (Turnuvalar > EURO Cup ile AYNI kaynak)
  if (!_preSeason && typeof _encLoadFromServer === 'function' && typeof encLoad === 'function' && !encLoad(_season) && !_ntEncLoadTried[_season]) {
    _ntEncLoadTried[_season] = true;
    _encLoadFromServer(_season).then(() => { try { if (document.getElementById('ntStandingsContent')) ntRenderStandings(acilis); } catch(e){} }).catch(()=>{});
  }
  const state = _preSeason ? null : encEnsureState(_season);

  // Sekme açılışı: güncel aşama + görüntülenen milli takımın grubu
  if (acilis || !_ntEncSekme) {
    _ntEncSekme = (state && state.phase && state.phase !== 'group') ? 'knockout' : 'groups';
    const cc = ntActiveCountry();
    const gi = state ? (state.groups || []).findIndex(g => g.teams && g.teams.some(t => t.code === cc)) : -1;
    if (gi >= 0) (_trkSecim.enc = _trkSecim.enc || {}).grup = gi;
  }
  const subtab = _ntEncSekme;
  let ic;
  if (subtab === 'groups')        ic = _trkEncGruplar(state, _season);
  else if (subtab === 'knockout') ic = _trkEncAgac(state, _season);
  else if (subtab === 'schedule') ic = _trkTakvimHtml('enc', _season);
  else                            ic = _trkIstatHtml('enc', subtab);
  box.innerHTML = `<div class="trn2-detail"><div class="trn2-banner is-natcup"><img src="${_CUP_BANNERS.natcup || ''}" alt=""></div>`
    + `<div class="trk gece" style="${_trkStil('enc')}">${_trkSekmeBar(['groups', 'knockout', 'schedule', 'goals', 'assists', 'rating'], subtab, s => `ntEncSekme('${s}')`)}<div class="trk-ic">${ic}</div></div></div>`;
  _trn2ScrollActiveStab(box);
}
let _ntEncSekme = null;   // 736 — Milli Takım › EURO Cup alt sekmesi
function ntEncSekme(tab) {
  if (!['groups', 'knockout', 'schedule', 'goals', 'assists', 'rating'].includes(tab)) tab = 'groups';
  _ntEncSekme = tab;
  ntRenderStandings();
}

// Kullanıcının knockout yolundaki maçlarını sırala
function _ntUserKnockoutPath(cc, knockout) {
  if (!knockout) return [];
  const path = [];
  const phases = [
    { key:'r16',   matches: knockout.r16   || [] },
    { key:'qf',    matches: knockout.qf    || [] },
    { key:'sf',    matches: knockout.sf    || [] },
    { key:'final', matches: knockout.final ? [knockout.final] : [] }
  ];
  for (const ph of phases) {
    const m = ph.matches.find(x => x && (x.home === cc || x.away === cc));
    if (!m) break;
    path.push({ phase: ph.key, match: m });
  }
  return path;
}

// ── KADRO satırı tıklama: Profil modal aç ──
function ntKadroOpenProfile(ntId) {
  if (!ntId) return;
  const cc = ntActiveCountry();
  if (typeof ntPlayerPool !== 'function') return;
  const pool = ntPlayerPool(cc);
  const p = pool.find(x => x && x.ntId === ntId);
  if (!p) return;

  // Kullanıcı kendisi ise standart "Bu Sensin" modal akışı
  // ROSTER_DATA'dan canlı user oyuncusunu kullan (canlı stats için)
  let player = p;
  if (p.isUser && typeof ROSTER_DATA !== 'undefined' && Array.isArray(ROSTER_DATA)) {
    const live = ROSTER_DATA.find(x => x && x.role === 'user');
    if (live) player = { ...live, ...p, role: 'user' };
  }

  const ctx = {
    teamName: p.sourceClub || '',
    countryCode: cc,
    playerNationality: cc,
    isOwnTeam: !!(p.isUser),
    teamLookupName: p.sourceClub || ''
  };
  if (typeof openPlayerModal === 'function') openPlayerModal(player, ctx);
}

// ── KADRO satırı ÇIKAR butonu: Onay modalı ──
// 🆕 Modal avatarı: gerçek kullanıcı/bot avatarı (roster ile aynı)
function _ntModalAvatarHTML(p) {
  if (!p) return '🤖';
  let a = p.avatar || (p.isUser ? '⭐' : '🤖');
  try {
    if (p.isUser && typeof authUser !== 'undefined' && authUser && authUser.avatarId && typeof getAvatarEmoji === 'function') {
      const r = getAvatarEmoji(authUser.avatarId, p.pos); if (typeof r === 'string' && r.indexOf('<img') === 0) a = r;
    } else if (!p.isUser && !p.isBot && p.avatar_id && typeof getAvatarEmoji === 'function') {
      const r = getAvatarEmoji(p.avatar_id, p.pos); if (typeof r === 'string' && r.indexOf('<img') === 0) a = r;
    }
  } catch(e){}
  return a;
}

// 🆕 Oyuncu işlemleri menüsü (modal) — sadece başkan/yardımcı görür
function ntKadroMenu(ntId) {
  if (!ntId) return;
  const cc = ntActiveCountry();
  if (!ntRol(cc)) return;
  const roster = (typeof ntEnsureRoster === 'function') ? ntEnsureRoster() : [];
  const p = roster.find(x => x && x.ntId === ntId);
  if (!p) return;
  const ov = document.getElementById('ntConfirmModal');
  const card = document.getElementById('ntConfirmCard');
  if (!ov || !card) return;

  const isCapUser = !!p.isNtAuto;   // 572 — otomatik gelen oyuncu çıkarılamaz (yerine başkası çağrılır)
  const st = (typeof getNtPlayerSquadStatus === 'function') ? getNtPlayerSquadStatus(p) : 'reserve';
  const statusLbl = st === 'starter' ? '⚽ İlk 11' : (st === 'bench' ? '🪑 Yedek (maç kadrosu)' : '📋 Kadro Dışı');
  const POS_CLS = { GK:'kl', DEF:'df', MID:'os', FWD:'fw' };
  const posShort = subPosOf(p);
  const posClsKey = POS_CLS[SUBPOS_GROUP[posShort]] || 'os';
  const tBg = p.clubBg || '#1976d2', tTc = p.clubTc || '#fff', tShort = p.clubShort || (p.sourceClub || 'TM').slice(0,3).toUpperCase();
  const safeId = String(ntId).replace(/'/g, "\\'");

  // Kontekst aksiyonlar
  let actions = '';
  if (st === 'reserve') actions += `<button class="nt-cf-menu-btn add" onclick="ntCloseConfirm();confirmNtMatchSquadAdd(${p.num})">🎽 Maç Kadrosuna Al</button>`;
  if (st === 'bench')   actions += `<button class="nt-cf-menu-btn" onclick="ntCloseConfirm();confirmNtMatchSquadRemove(${p.num})">🪑 Maç Kadrosundan Çıkart</button>`;
  if (!isCapUser)       actions += `<button class="nt-cf-menu-btn danger" onclick="ntDoKadroRemove('${safeId}')">✕ Milli Takımdan Çıkart</button>`;
  // 572 — yardımcıları yalnız başkan seçer; yalnız gerçek oyuncular (kendisi hariç)
  if (!p.isUser && !p.isBot && p.user_id && typeof _ntIsUserCaptain === 'function' && _ntIsUserCaptain()) {
    const _pIsVice = !!(p && p.id && (ntLoadVices(cc) || []).includes(p.id));
    actions += _pIsVice
      ? `<button class="nt-cf-menu-btn" onclick="ntCloseConfirm();ntRemoveVice('${safeId}')">⛔ Yardımcılıktan Al</button>`
      : `<button class="nt-cf-menu-btn" onclick="ntCloseConfirm();ntAddVice('${safeId}')">⭐ Yardımcı Yap</button>`;
  }
  if (isCapUser) actions += `<div style="color:var(--text3);font-size:11px;text-align:center;padding:6px 10px">Bu oyuncu boş yere otomatik geldi. Yerine Analiz sekmesinden başka birini çağırabilirsin.</div>`;
  if (!actions) actions = `<div style="color:var(--text3);font-size:11px;text-align:center;padding:10px">Bu oyuncu için işlem yok.${st==='starter'?' (Sahadan çıkarmak için diziliş ekranında yedeğe sürükleyin.)':''}</div>`;

  card.innerHTML = `
    <div class="nt-cf-h">
      <div class="tx"><div class="ti">Oyuncu İşlemleri</div><div class="sb">${statusLbl}</div></div>
    </div>
    <div class="nt-cf-player">
      <div class="av">${_ntModalAvatarHTML(p)}</div>
      <div class="info">
        <div class="nm">${p.name || '—'}</div>
        <div class="meta">
          <span class="pos pos-${posClsKey}">${posShort}</span>
          ${inlineBadge({cls:'nt-an-tbadge', name:p.sourceClub, bg:tBg, tc:tTc, short:tShort})}
          <span style="color:var(--text2,#90caf9);font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${p.sourceClub || ''}</span>
        </div>
      </div>
      <div class="ovr">${_ntPlayerSkill(p)}</div>
    </div>
    <div class="nt-cf-menu-actions">${actions}</div>
    <div class="nt-cf-actions"><button class="nt-cf-btn cancel" onclick="ntCloseConfirm()">Kapat</button></div>
  `;
  ov.classList.add('open');
}

// 583 — Çıkarma onayı mesajı: kadro sayısı + (12'nin altına inecekse) yerine gelecek oyuncu
function _ntCikarMesajHtml(ntId, cc, ad) {
  const esc = (x) => String(x == null ? '' : x).replace(/[&<>"]/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;' }[c]));
  let r = null;
  try { r = ntId ? _ntCikarOnizle(ntId, cc) : null; } catch(e) {}
  if (r && r.hata === 'oto') return `<div class="nt-cf-msg warn"><span>Bu oyuncu kadroyu 12’ye tamamlamak için otomatik geldi.</span> <span>Yerine Analiz sekmesinden başka birini çağırabilirsin.</span></div>`;
  if (r && r.hata === 'yerine_yok') return `<div class="nt-cf-msg warn"><b>Kadro en az 12 kişi olmalı.</b> <span>Yerine gelecek uygun oyuncu yok — önce başka birini çağır.</span></div>`;
  if (r && r.yerine) {
    const y = r.yerine;
    const PC = { GK:'kl', DEF:'df', MID:'os', FWD:'fw' };
    const ya = subPosOf(y);
    const guc = (typeof _ntPlayerSkill === 'function') ? _ntPlayerSkill(y) : (y.overall || '—');
    return `<div class="nt-cf-msg warn"><b>Kadro en az 12 kişi olmalı.</b> <span>Bu oyuncu çıkarılırsa yerine aynı mevkiden en güçlü uygun oyuncu otomatik gelir:</span></div>
    <div class="nt-cf-yerine-lbl">↻ <span>Yerine gelecek</span></div>
    <div class="nt-cf-player nt-cf-yerine">
      <div class="av">${_ntModalAvatarHTML(y)}</div>
      <div class="info">
        <div class="nm" data-noi18n>${esc(y.name || '—')}</div>
        <div class="meta"><span class="pos pos-${PC[SUBPOS_GROUP[ya]] || 'os'}">${ya}</span><span class="nt-cf-oto">OTO</span><span data-noi18n style="white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(y.sourceClub || '')}</span></div>
      </div>
      <div class="ovr">${guc}</div>
    </div>`;
  }
  const n = r && !r.hata ? r.once : null;
  return `<div class="nt-cf-msg warn"><b data-noi18n>${esc(ad)}</b> <span>milli takımdan çıkarılacak.</span> <span>Yeri boş kalır; istersen Analiz sekmesinden başka birini çağırabilirsin.</span>`
    + (n ? `<div class="nt-cf-sayi"><span>Kadro</span> <b data-noi18n>${n} → ${n - 1}</b> <span>· en az 12</span></div>` : '') + `</div>`;
}

