// ── ANALİZ ───────────────────────────────────────────────────────
// Tüm oyundaki o uyruktan oyunculardan en iyi 50'sini
// yetenek / reyting / antrenman kriterlerine göre listeler.
// Mevki filtresi: tümü / KL / DF / OS / FW
// Tıklanabilir — federasyon yetkilisi modaldan davet butonu görür.
window._ntAnalysisSort = window._ntAnalysisSort || 'overall';
window._ntAnalysisPos  = window._ntAnalysisPos  || 'all'; // all | GK | DEF | MID | FWD

// Bir oyuncuya ait sentetik antrenman enerji puanı üret (50-95 arası)
function _ntPlayerEnergy(p, teamName) {
  // Kullanıcı için gerçek enerji
  if (p && p.role === 'user') {
    try {
      if (typeof trGetEnergy === 'function') {
        const e = trGetEnergy();
        if (e && typeof e.current === 'number') return e.current;
      }
    } catch(e) {}
    return 100;
  }
  // Bot için seed-deterministik
  const seed = (p.name || '') + '|' + (teamName || '') + '|' + (p.num || 0);
  let h = 0;
  for (let i = 0; i < seed.length; i++) h = ((h << 5) - h + seed.charCodeAt(i)) & 0x7fffffff;
  // 50-95 arası dağıt
  return 50 + (h % 46);
}

// Oyuncunun yetenek toplamı (DİNAMİK — abilities ortalaması, kullanıcı için level/skill bazlı).
// 🆕 Statik p.overall artık ÖNCELİK DEĞİL — gerçek dinamik hesap kullanılır.
// 584 — Milli takımdaki oyuncu kulübündeki oyuncunun aynısı: OVR kulüpteki kuralla hesaplanır
//   (sen → kendi yeteneklerin, kulüp arkadaşın → kulüp kadrosundaki kaydı, diğerleri → aynı formül)
function _ntKulupOvr(p) {
  let k = null;
  try { if (typeof ROSTER_DATA !== 'undefined' && Array.isArray(ROSTER_DATA)) k = p.isUser ? ROSTER_DATA.find(x => x && x.role === 'user') : (p.id != null ? ROSTER_DATA.find(x => x && x.id === p.id) : null); } catch(e) {}
  if (k) return getPlayerMainOverall(k);
  return getPlayerMainOverall(p.isUser ? { ...p, role: 'user' } : p);
}
function _ntPlayerSkill(p) {
  if (!p) return 10;
  // 1) Yeni dinamik fonksiyon (kullanıcı için skill levels, bot için abilities ortalaması)
  if (typeof getPlayerMainOverall === 'function') {
    const v = _ntKulupOvr(p);
    if (typeof v === 'number' && v > 0) return v;
  }
  // 2) Geriye dönük: pozisyon ortalaması
  if (typeof getPlayerPositionAvg === 'function') {
    const v = getPlayerPositionAvg(p);
    if (v) return Math.round(v);
  }
  // 3) Son çare: statik overall
  if (typeof p.overall === 'number' && p.overall > 0) return p.overall;
  // 4) Eski flat abilities yapısı
  if (p.abilities && typeof p.abilities === 'object') {
    const vals = Object.values(p.abilities).filter(v => typeof v === 'number');
    if (vals.length) return Math.round(vals.reduce((a,b)=>a+b,0) / vals.length);
  }
  return 10;
}

// O uyruktan TÜM oyuncuları topla — hangi ülkenin liginde oynadığı önemli değil.
// Tek şart: oyuncunun nationality === cc (veya nation flag eşleşmesi).
// Her oyuncuya: _team, _lg, _lgIdx, _cc (oynadığı kulübün ülkesi), _teamCC metadata eklenir.
// 🆕 Aktif milli takım pane'ini yeniden render et (async havuz/kadro gelince çağrılır)
function _ntRefreshActivePane() {
  try {
    const page = document.getElementById('page-national');
    if (!page || !page.classList.contains('active')) return;   // 956 — sayfalar .page sınıfıyla gizlenir; style.display hiç 'none' olmuyordu
    const vis = (id) => { const e = document.getElementById(id); return e && e.style.display !== 'none'; };
    if (vis('nt-callup') && typeof ntRenderCallup === 'function') ntRenderCallup();
    else if (vis('nt-roster') && typeof ntRenderRoster === 'function') ntRenderRoster();
    else if (vis('nt-formation') && typeof ntRenderFormation === 'function') ntRenderFormation();
  } catch(e) {}
}

function _ntAllNationalPlayers(cc) {
  // 🆕 TEK KAYNAK: Supabase players havuzu (kadro ile AYNI kaynak).
  //   Eski client-seed taraması kaldırıldı → kadro↔callup uyuşmazlığı ve
  //   "Oyuncu havuzda bulunamadı" hatası bitti. Havuz async yüklenir;
  //   geldiğinde _ntRefreshActivePane callup'ı otomatik yeniler.
  const pool = (typeof ntPlayerPool === 'function') ? (ntPlayerPool(cc) || []) : [];
  return pool.map(p => Object.assign({}, p, {
    role:       p.isUser ? 'user' : (p.role || 'member'),
    _team:      p.sourceClub,
    _teamShort: p.clubShort,
    _teamBg:    p.clubBg,
    _teamTc:    p.clubTc,
    _lg:        '',
    _lgIdx:     0,
    _cc:        cc,
    _teamCC:    p.clubCC || cc
  }));
}

// SORT MODE: 'overall' | 'rating' | 'energy'
function _ntSortAnalysis(list, mode, sk) {
  // 958 — sk (Map) verilirse yetenek oyuncu başına bir kez hesaplanır; karşılaştırıcı aynı → sıra aynı
  const S = sk ? (p => { let v = sk.get(p); if (v === undefined) { v = _ntPlayerSkill(p); sk.set(p, v); } return v; }) : _ntPlayerSkill;
  return list.slice().sort((a, b) => {
    if (mode === 'rating') {
      const ar = (typeof a.rating === 'number' && a.rating > 0) ? a.rating : 0;
      const br = (typeof b.rating === 'number' && b.rating > 0) ? b.rating : 0;
      if (br !== ar) return br - ar;
      return S(b) - S(a);
    }
    // default: overall (yetenek)
    const ao = S(a);
    const bo = S(b);
    if (bo !== ao) return bo - ao;
    if ((b.level||0) !== (a.level||0)) return (b.level||0) - (a.level||0);
    return (a.name || '').localeCompare(b.name || '', 'tr');
  });
}

function ntSetAnalysisSort(mode) {
  window._ntAnalysisSort = mode;
  ntRenderCallup();
}

function ntSetAnalysisPos(pos) {
  window._ntAnalysisPos = pos;
  ntRenderCallup();
}

// ── DAVET ONAY MODALI ────────────────────────────────────────────
