// Onay verildiğinde gerçek aksiyon
function ntDoCallup(idx) {
  const list = window._ntAnalysisLastList;
  if (!Array.isArray(list)) return;
  const p = list[idx];
  if (!p) return;
  const ctx = {
    teamName: p._team,
    countryCode: p._teamCC || p._cc,
    playerNationality: p._cc,
    isOwnTeam: false,
    teamLookupName: p._team
  };
  ntCloseConfirm();
  if (typeof fedCallupPlayer === 'function') {
    const payload = JSON.stringify({ player: p, ctx });
    fedCallupPlayer(payload);
  }
  // Liste yenile (kart "Kadroda" rozetiyle gözüksün)
  setTimeout(() => { if (typeof ntRenderCallup === 'function') ntRenderCallup(); }, 50);
}

function ntDoRemove(idx) {
  const list = window._ntAnalysisLastList;
  if (!Array.isArray(list)) return;
  const p = list[idx];
  if (!p) return;
  const ctx = {
    teamName: p._team,
    countryCode: p._teamCC || p._cc,
    playerNationality: p._cc,
    isOwnTeam: false,
    teamLookupName: p._team
  };
  ntCloseConfirm();
  if (typeof fedRemoveFromNT === 'function') {
    const payload = JSON.stringify({ player: p, ctx });
    fedRemoveFromNT(payload);
  }
  setTimeout(() => { if (typeof ntRenderCallup === 'function') ntRenderCallup(); }, 50);
}

// ESC ile onay modalını kapat
document.addEventListener('keydown', function(e) {
  if (e.key === 'Escape') {
    const ov = document.getElementById('ntConfirmModal');
    if (ov && ov.classList.contains('open')) ntCloseConfirm();
  }
});

// Oyuncu kartına tıklayınca standart profil modalını aç
// Federasyon yetkilisi ise modal içinde "Milli Takıma Al" butonu otomatik görünür
// (uyruk kontrolü modal tarafında oyuncunun nationality'sine göre yapılır)
function ntOpenAnalysisPlayer(idx) {
  const list = window._ntAnalysisLastList;
  if (!Array.isArray(list)) return;
  const p = list[idx];
  if (!p) return;
  // ctx.countryCode = oynadığı kulübün ülkesi (modal "Takımını Gör" butonunu doğru yapar)
  // ctx.playerNationality = oyuncunun gerçek uyruğu (federasyon davet kontrolü için)
  const ctx = {
    teamName: p._team,
    countryCode: p._teamCC || p._cc,
    playerNationality: p._cc,
    isOwnTeam: (typeof _userTeam !== 'undefined' && _userTeam &&
                _userTeam.countryCode === p._teamCC && _userTeam.teamName === p._team),
    teamLookupName: p._team
  };
  if (typeof openPlayerModal === 'function') openPlayerModal(p, ctx);
}

const NT_ANALIZ_MEVKI_BASI = 20;   // 586 — analiz listesi: alt mevki başına en iyi 20
function ntRenderCallup() {
  const box = document.getElementById('ntCallupContent');
  if (!box) return;
  const cc = ntActiveCountry();
  const cName = (true && _cftGetCountry(cc)) ? _cftGetCountry(cc).name : cc;
  const flag  = (true && _cftGetCountry(cc)) ? _cftGetCountry(cc).flag : '🏳️';

  // Yetkili mi? (görüntülenen milli takımın başkanı / yardımcısı)
  const isOfficial = !!ntRol(cc);

  // Tüm uyruklu oyuncuları topla
  const all = _ntAllNationalPlayers(cc);
  let sortMode = window._ntAnalysisSort || 'overall';
  if (sortMode !== 'overall' && sortMode !== 'rating') sortMode = window._ntAnalysisSort = 'overall';
  const posFilter = window._ntAnalysisPos || 'all';

  // 586 — her alt mevkiden (GK, CB, LB, RB, DM, CM, LM, RM, AM, LF, RF, ST) en iyi 20 oyuncu.
  //   Mevki filtresi (KL/DF/OS/FW) hangi alt mevkilerin listeleneceğini seçer.
  const _ALT_SIRA = ['GK', 'CB', 'LB', 'RB', 'DM', 'CM', 'LM', 'RM', 'AM', 'LF', 'RF', 'ST'];
  const _altlar = _ALT_SIRA.filter(a => posFilter === 'all' || SUBPOS_GROUP[a] === posFilter);
  const _bolum = [];
  const top = [];
  // 958 — yetenek oyuncu başına bir kez hesaplanır (_sk958); alt mevkiler tek geçişte kovalanır (havuz sırası korunur)
  const _sk958 = new Map(), _alt958 = new Map();
  all.forEach(p => { const a = subPosOf(p), l = _alt958.get(a); if (l) l.push(p); else _alt958.set(a, [p]); });
  _altlar.forEach(a => {
    const l = _ntSortAnalysis(_alt958.get(a) || [], sortMode, _sk958).slice(0, NT_ANALIZ_MEVKI_BASI);
    if (l.length) { _bolum.push({ a, bas: top.length, n: l.length }); top.push(...l); }
  });
  window._ntAnalysisLastList = top;

  // Kadrodakiler (sunucuyla aynı kural: kayıt + otomatik dolan yerler)
  const _etkin = (typeof _ntEtkinKadroYer === 'function') ? _ntEtkinKadroYer(cc) : { ids: [], oto: [] };
  const squadIds = new Set(_etkin.ids.filter(Boolean));
  const otoIds = new Set(_etkin.ids.filter((id, i) => id && _etkin.oto[i]));

  // Sıralama filtre pill'leri (572 — sahte "Antrenman" sıralaması kaldırıldı)
  const SORT_PILLS = [
    { key:'overall', icon:'⭐', label:'Yetenek' },
    { key:'rating',  icon:'📊', label:'Reyting' }
  ];
  const sortHtml = `
    <div class="nt-an-filters">
      ${SORT_PILLS.map(p => `
        <button class="nt-an-pill ${sortMode === p.key ? 'active' : ''}"
                onclick="ntSetAnalysisSort('${p.key}')">
          <span>${p.icon}</span><span>${p.label}</span>
        </button>
      `).join('')}
    </div>
  `;

  // Mevki filtre pill'leri (renkli)
  const POS_PILLS = [
    { key:'all', label:'Tümü', cls:'pall' },
    { key:'GK',  label:'KL',   cls:'pkl'  },
    { key:'DEF', label:'DF',   cls:'pdf'  },
    { key:'MID', label:'OS',   cls:'pos'  },
    { key:'FWD', label:'FW',   cls:'pfw'  }
  ];
  const posHtml = `
    <div class="nt-an-pos-filters">
      ${POS_PILLS.map(p => `
        <button class="nt-an-pos-pill ${p.cls} ${posFilter === p.key ? 'active' : ''}"
                onclick="ntSetAnalysisPos('${p.key}')">${p.label}</button>
      `).join('')}
    </div>
  `;

  // Liste kartları
  let listHtml = '';
  if (!top.length) {
    listHtml = (_ntPoolCache[cc])
      ? `<div class="nt-an-empty">Bu uyruktan${posFilter !== 'all' ? ' bu mevkide' : ''} oyuncu bulunamadı.</div>`
      : `<div class="nt-an-empty">Oyuncular yükleniyor…</div>`;
  } else {
    listHtml = `<div class="nt-an-list">` + top.map((p, i) => {
      const _b = _bolum.find(b => b.bas === i);
      const _baslik = _b ? `<div class="nt-an-alt"><b>${_b.a}</b><span>${SUBPOS_LABEL[_b.a] || _b.a}</span><em data-noi18n>${_b.n}</em></div>` : '';
      const _sira = i - (_bolum.filter(b => b.bas <= i).pop() || { bas: 0 }).bas;
      const isUser = p.role === 'user';
      const isCallup = squadIds.has(p.ntId);
      const isOto = otoIds.has(p.ntId);

      let valNum, valCls;
      if (sortMode === 'rating') {
        valNum = (typeof p.rating === 'number' && p.rating > 0) ? p.rating.toFixed(1) : '—';
        valCls = 'rat';
      } else {
        valNum = _sk958.has(p) ? _sk958.get(p) : _ntPlayerSkill(p);   // 958 — sıralamada hesaplanan değer
        valCls = 'ovr';
      }

      const POS_CLS = { GK:'kl', DEF:'df', MID:'os', FWD:'fw' };
      const posShort = subPosOf(p);                                  // 586 — alt mevki (LB, CB, CM, LF…)
      const posClsKey = POS_CLS[SUBPOS_GROUP[posShort]] || 'os';

      // Takım rozeti (renkli short-code) — bayrak değil
      const tBg = p._teamBg || '#1976d2';
      const tTc = p._teamTc || '#ffffff';
      const tShort = p._teamShort || (p._team || 'TM').slice(0,3).toUpperCase();
      const teamBadge = inlineBadge({cls:'nt-an-tbadge', name:p._team, bg:tBg, tc:tTc, short:tShort});

      const cardCls = [
        'nt-an-card',
        isUser ? 'is-user' : '',
        isCallup ? 'is-callup' : '',
        _sira < 3 ? 'is-top3' : ''
      ].filter(x=>x).join(' ');

      const avatar = (typeof _ntModalAvatarHTML === 'function') ? _ntModalAvatarHTML(p) : (p.avatar || '🤖');

      let nameTag = '';
      if (isUser) nameTag = '<span class="b-tag">Sen</span>';
      if (isCallup) nameTag += isOto ? '<span class="b-tag cu">Kadroda · OTO</span>' : '<span class="b-tag cu">Kadroda</span>';
      if (isPlayerInjured(p)) nameTag += '<span class="b-tag" title="Sakat">🚑</span>';
      if (p.ntBan > 0) nameTag += '<span class="b-tag" title="Milli maç cezalı">🟥</span>';

      // Sağdaki aksiyon: yetkili ise davet/çıkar butonu, değilse arrow
      let actionEl;
      if (isOfficial) {
        if (isCallup && !isOto) {
          actionEl = `<button class="nt-an-btn rmv" onclick="event.stopPropagation();ntConfirmRemove(${i})" title="Milli takımdan çıkar">✕</button>`;
        } else if (!isCallup && ntTurnuvaKilitli()) {
          actionEl = `<button class="nt-an-btn add kilit" onclick="event.stopPropagation();showToast(_NT_TURNUVA_KILIT)">Davet</button>`;
        } else {
          actionEl = `<button class="nt-an-btn add" onclick="event.stopPropagation();ntConfirmCallup(${i})">Davet</button>`;
        }
      } else {
        actionEl = `<span class="arrow">›</span>`;
      }

      return `${_baslik}
        <div class="${cardCls}" onclick="ntOpenAnalysisPlayer(${i})">
          <span class="rk">${_sira + 1}</span>
          <span class="av">${avatar}</span>
          <div class="info">
            <div class="nm">${p.name || '—'}${nameTag}</div>
            <div class="meta">
              <span class="pos pos-${posClsKey}">${posShort}</span>
              ${teamBadge}
              <span class="tname">${p._team || ''}</span>
            </div>
          </div>
          <span class="val ${valCls}">${valNum}</span>
          ${actionEl}
        </div>
      `;
    }).join('') + `</div>`;
  }

  const totalNum = all.length;
  const officialBadge = isOfficial
    ? `<span style="display:inline-block;background:rgba(77,213,153,.18);color:var(--success,#4dd599);font-size:9px;padding:2px 7px;border-radius:5px;font-weight:800;letter-spacing:.4px;text-transform:uppercase;margin-left:5px">✓ Yetkili</span>`
    : '';
  const filterDesc = `Her mevkiden en iyi ${NT_ANALIZ_MEVKI_BASI}`;

  box.innerHTML = `
    <div class="nt-pane-hero">
      <div class="h-row">
        <div class="h-ic">🔍</div>
        <div class="h-tx">
          <div class="h-ti">Oyuncu Analizi ${officialBadge}</div>
          <div class="h-sb">${flag} ${cName} uyruklu · ${totalNum} oyuncu havuzu · ${filterDesc}</div>
        </div>
      </div>
    </div>

    ${sortHtml}
    ${posHtml}
    <div class="nt-an-meta">${
      sortMode === 'overall' ? '⭐ Yetenek puanına göre sıralı' : '📊 Maç reytingine göre sıralı (eşitlikte yetenek)'
    }${isOfficial ? ' · Davet ile oyuncuyu kadroya çağırabilirsin' : ' · Oyuncu profilini incelemek için tıkla'}</div>
    ${listHtml}
  `;
}

// ── VİTRİN ───────────────────────────────────────────────────────────
// 572 — Milli takım kupaları SUNUCUDAN: tournament_state (enc) fixture.champion (tüm sezonlar)
const _ntKupaCache = { t: 0, liste: null, yukleniyor: null };
function _ntKupalariYukle(zorla) {
  if (!window.sb) return Promise.resolve([]);
  if (_ntKupaCache.liste && !zorla && Date.now() - _ntKupaCache.t < 10 * 60 * 1000) return Promise.resolve(_ntKupaCache.liste);
  if (_ntKupaCache.yukleniyor) return _ntKupaCache.yukleniyor;
  _ntKupaCache.yukleniyor = window.sb.from('tournament_state')
    .select('season, phase, sampiyon:fixture->champion, ikinci:fixture->runnerUp, skor:fixture->finalScore')
    .eq('tournament_key', 'enc').order('season', { ascending: false }).limit(200)
    .then(({ data, error }) => {
      _ntKupaCache.yukleniyor = null;
      if (error) { console.warn('[nt kupa] hata:', error.message || error); return _ntKupaCache.liste || []; }
      _ntKupaCache.liste = (data || []).filter(r => r && r.sampiyon).map(r => ({
        season: r.season, champion: String(r.sampiyon), runnerUp: r.ikinci ? String(r.ikinci) : null,
        score: Array.isArray(r.skor) ? r.skor : null }));
      _ntKupaCache.t = Date.now();
      try {
        const pg = document.getElementById('page-national');
        if (pg && pg.classList.contains('active')) {
          ntRender();
          const tp = document.getElementById('nt-trophies');
          if (tp && tp.style.display !== 'none') ntRenderTrophies();
        }
      } catch(e) {}
      return _ntKupaCache.liste;
    }, () => { _ntKupaCache.yukleniyor = null; return _ntKupaCache.liste || []; });
  return _ntKupaCache.yukleniyor;
}
function _ntAdEslesir(ad, cc) {
  if (!ad) return false;
  if (ad === _ntUlkeAdi(cc)) return true;
  try { return (typeof _ulkeKodu === 'function') && _ulkeKodu(ad) === cc; } catch(e) { return false; }
}
// Bu ülkenin kazandığı kupalar (null = henüz yüklenmedi)
function ntKupalar(cc) {
  const L = _ntKupaCache.liste;
  if (!L || Date.now() - _ntKupaCache.t > 10 * 60 * 1000) _ntKupalariYukle().catch(()=>{});
  if (!L) return null;
  return L.filter(k => _ntAdEslesir(k.champion, cc));
}

function ntRenderTrophies() {
  const box = document.getElementById('ntTrophiesContent');
  if (!box) return;
  const cc = ntActiveCountry();
  const ulke = _cftGetCountry(cc);
  const kupalar = ntKupalar(cc);
  const finaller = (_ntKupaCache.liste || []).filter(k => _ntAdEslesir(k.runnerUp, cc));

  let html = `
    <div class="nt-pane-hero">
      <div class="h-row">
        <div class="h-ic">${_kupaIk('kupa')}</div>
        <div class="h-tx">
          <div class="h-ti">Milli Takım Vitrini</div>
          <div class="h-sb">${(ulke && ulke.name) || cc} milli takımının kazandığı kupalar</div>
        </div>
      </div>
    </div>
    <div class="nt-tr-summary">
      <div class="nt-tr-sumbox"><div class="v">${kupalar ? kupalar.length : '—'}</div><div class="l">${_kupaIk('kupa')}EURO Nations Cup</div></div>
      <div class="nt-tr-sumbox"><div class="v">${kupalar ? finaller.length : '—'}</div><div class="l">${_kupaIk('madalya')}Final</div></div>
    </div>
  `;
  if (!kupalar) {
    html += `<div class="nt-tr-empty"><div class="ic">${_kupaIk('kumsaati')}</div><div class="ti">Yükleniyor…</div></div>`;
  } else if (!kupalar.length) {
    html += `
      <div class="nt-tr-empty">
        <div class="ic">${_kupaIk('kupa')}</div>
        <div class="ti">Henüz Kupa Yok</div>
        <div class="sb">EURO Nations Cup'ı kazanınca kupa burada görünür. Turnuvaya her ülke katılır: 8 grup, ardından Son 16, Çeyrek Final, Yarı Final ve Final.</div>
      </div>
    `;
  } else {
    // 638 — Kupa dolabı: her şampiyonluk rafta, altında final rakibi ve skoru
    html += `<div class="nt-tr-dolap">${_kupaDolabiHtml(kupalar.map(t => {
      let skor = '';
      if (Array.isArray(t.score) && t.score.length === 2) {
        const a1 = Number(t.score[0]), b1 = Number(t.score[1]);
        skor = (a1 === b1) ? `${a1}-${b1} (pen.)` : `${Math.max(a1, b1)}-${Math.min(a1, b1)}`;
      }
      return { tur: 'enc', adet: 1, sezonlar: [t.season], det: t.runnerUp
        ? `Final: <span data-noi18n>${_escapeHtml(t.runnerUp)}</span>${skor ? ' · <span data-noi18n>' + skor + '</span>' : ''}` : '' };
    }))}</div>`;
  }
  // Tüm sezonların şampiyonları
  const tum = _ntKupaCache.liste || [];
  if (tum.length) {
    html += `<div class="nt-section-title" style="margin-top:14px">${_kupaIk('liste')}EURO Nations Cup Şampiyonları</div><div class="nt-tr-gecmis">` +
      tum.map(k => {
        const kod = (typeof _ulkeKodu === 'function') ? _ulkeKodu(k.champion) : null;
        const c = kod ? _cftGetCountry(kod) : null;
        return `<div class="nt-tr-row${kod === cc ? ' is-me' : ''}"><span class="s">S${k.season}</span><span class="f">${c ? c.flag : '🏳️'}</span><span class="n" data-noi18n>${_escapeHtml(k.champion)}</span><span class="r">${k.runnerUp ? _kupaIk('madalya') + '<span data-noi18n>' + _escapeHtml(k.runnerUp) + '</span>' : ''}</span></div>`;
      }).join('') + `</div>`;
  }
  box.innerHTML = html;
}

// ────────── FİKSTÜR render ──────────
function ntRenderFixture() {
  const el = document.getElementById('nt-fixture');
  if(!el) return;

  const info = (typeof getSeasonInfo === 'function') ? getSeasonInfo() : null;
  if(!info) { el.innerHTML = ''; return; }
  const { season, dayInSeason, preSeason } = info;
  const cc = ntActiveCountry();

  if(preSeason) {
    el.innerHTML = `<div style="text-align:center;padding:48px 16px;color:var(--text2)">
      <div style="font-size:48px;margin-bottom:12px">⏳</div>
      <div style="font-family:Twemoji Country Flags,'Barlow Condensed',sans-serif;font-size:18px;font-weight:900;color:var(--text);margin-bottom:6px">SEZON HENÜZ BAŞLAMADI</div>
      <div style="font-size:12px">Milli takım fikstürü sezon başında oluşturulur.</div>
    </div>`;
    return;
  }

  // 🆕 State yüklü değilse async yükle + tekrar render (Turnuvalar ile AYNI kaynak; sezon/gün guard YOK)
  if (typeof _encLoadFromServer === 'function' && typeof encLoad === 'function' && !encLoad(season) && !_ntEncLoadTried[season]) {
    _ntEncLoadTried[season] = true;
    _encLoadFromServer(season).then(() => { try { if (document.getElementById('nt-fixture')) ntRenderFixture(); } catch(e){} }).catch(()=>{});
  }
  const state = (typeof encEnsureState === 'function') ? encEnsureState(season) : null;
  if(!state || !state.groups) {
    el.innerHTML = `<div style="text-align:center;padding:48px 16px;color:var(--text2)"><div style="font-size:46px;margin-bottom:10px">🎲</div><div style="font-size:13px;line-height:1.5">EURO Cup kurası henüz çekilmedi — fikstür belli olunca burada görünür.</div></div>`;
    return;
  }

  const myGroup = state.groups.find(g => g.teams.some(t => t.code === cc));
  let myMatches = [];
  let groupName = '';

  if(myGroup) {
    groupName = myGroup.name;
    const groupGames = myGroup.matches.filter(m => m.home === cc || m.away === cc);
    groupGames.forEach((m, idx) => {
      myMatches.push({ ...m, stage: 'Grup ' + groupName, stageDay: 34 + idx });
    });
  }

  // Knockout (anahtarlar encEnsureState ile uyumlu; final tek obje)
  if(state.knockout) {
    const stageDayMap = { r16:37, qf:38, sf:39, final:40 };
    const stageNameMap = { r16:'Son 16', qf:'Çeyrek Final', sf:'Yarı Final', final:'Final 🏆' };
    ['r16','qf','sf','final'].forEach(round => {
      let matches = state.knockout[round] || [];
      if(!Array.isArray(matches)) matches = matches ? [matches] : [];
      matches.forEach(m => {
        if(m.home === cc || m.away === cc) {
          myMatches.push({ ...m, stage: stageNameMap[round], stageDay: stageDayMap[round] });
        }
      });
    });
  }

  if(myMatches.length === 0) {
    el.innerHTML = `<div style="text-align:center;padding:48px 16px;color:var(--text2)">
      <div style="font-size:48px;margin-bottom:12px">📅</div>
      <div style="font-size:13px">Bu sezon ${(_cftGetCountry(cc)?.name)||'milli takım'} maçı yok</div>
    </div>`;
    return;
  }

  let html = `<div class="nt-fix-list">`;
  myMatches.forEach(m => {
    const home = _cftGetCountry(m.home);
    const away = _cftGetCountry(m.away);
    const day = m.stageDay;
    const _hasScore = (m.hg !== null && m.hg !== undefined && m.ag !== null && m.ag !== undefined) && !m.uz;   // 886
    const isPast = dayInSeason > day || (dayInSeason === day && _hasScore);
    const isToday = dayInSeason === day && !_hasScore;

    const cardCls = isToday ? 'lg2-fix-card today-card' : isPast ? 'lg2-fix-card is-past-card' : 'lg2-fix-card';

    let scorePart;
    if(_hasScore) {
      const draw = m.hg === m.ag;
      const myWin = (m.home === cc && m.hg > m.ag) || (m.away === cc && m.ag > m.hg);
      const cls = draw ? 'd' : (myWin ? 'w' : 'l');
      scorePart = `<div class="lg2-fix-sc"><div class="lg2-fix-scv ${cls}">${m.hg}–${m.ag}</div></div>`;
    } else if(isToday) {
      scorePart = `<div class="lg2-fix-sc"><div class="lg2-fix-time" style="color:var(--accent);font-weight:900">BUGÜN</div></div>`;
    } else {
      scorePart = `<div class="lg2-fix-sc"><div class="lg2-fix-time">Gün ${day}</div></div>`;
    }

    const myIsHome = m.home === cc;
    html += `
      <div class="${cardCls}">
        <div style="font-size:9.5px;font-weight:800;color:var(--g3);padding:0 8px;letter-spacing:.5px;flex-shrink:0;min-width:64px;line-height:1.2">🌍 ${m.stage}</div>
        <div style="flex:1;display:flex;align-items:center;gap:6px;min-width:0">
          <span style="font-size:14px">${home?.flag||'🏳️'}</span>
          <span style="flex:1;font-size:11.5px;font-weight:600;${myIsHome?'color:var(--g3)':''};white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${home?.name||m.home}</span>
          <span style="opacity:.45;font-size:10px">v</span>
          <span style="flex:1;text-align:right;font-size:11.5px;font-weight:600;${!myIsHome?'color:var(--g3)':''};white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${away?.name||m.away}</span>
          <span style="font-size:14px">${away?.flag||'🏳️'}</span>
        </div>
        ${scorePart}
      </div>
    `;
  });
  html += `</div>`;

  el.innerHTML = html;
}

// 🆕 Hero chip'lerinden Kadro sekmesine odaklan
function ntFocusRoster() {
  const b = document.querySelector('#page-national .team-tab[data-nt-tab=\"roster\"]');
  if (typeof ntTab === 'function') ntTab('roster', b);
}

// ──────── MİLLİ TAKIM sekme geçişi ────────
function ntTab(name, el) {
  // 🆕 526 — ziyaretçi modunda kapalı sekmeler (menüden de açılamasın)
  if (['formation','chat','callup'].indexOf(name) !== -1 && typeof _ntTamErisim === 'function' && !_ntTamErisim()) {
    name = 'roster';
    el = document.querySelector('#page-national .team-tab[data-nt-tab="roster"]');
  }
  const PANES = ['roster','formation','chat','fixture','standings','callup','trophies'];
  PANES.forEach(t => {
    const e = document.getElementById('nt-' + t);
    if(e) e.style.display = t === name ? 'block' : 'none';
  });
  const tabs = document.querySelectorAll('#page-national .team-tab');
  tabs.forEach(t => t.classList.remove('active'));
  if(el) el.classList.add('active');

  // 585 — kayıtlı kadro her açılışta sunucudan tazelenir
  if (name === 'roster' || name === 'formation' || name === 'callup') { try { _loadNtSquadFromServer(ntActiveCountry(), true).catch(()=>{}); } catch(e) {} }
  // İçerik render
  if(name === 'roster' && typeof ntRenderRoster === 'function') {
    if (typeof _ntStrategyLoadFromServer === 'function' && _ntStrategyCC !== ntActiveCountry()) {
      _ntStrategyLoadFromServer().then(() => { try { _ntActivePitchPlayers = []; ntLoadStrategy(); } catch(e){} try { ntRenderRoster(); } catch(e){} }).catch(()=>{});
    }
    // 🆕 Diziliş henüz yüklenmemişse SADECE strateji yükle (auto-fill çağrı zinciri tetikler).
    // ntLoadStrategy localStorage'dan _ntActivePitchPlayers'ı geri yükler.
    if (typeof _ntActivePitchPlayers !== 'undefined' && _ntActivePitchPlayers.length === 0
        && typeof ntLoadStrategy === 'function') {
      try { ntLoadStrategy(); } catch(e){}
    }
    ntRenderRoster();
  }
  else if(name === 'formation' && typeof ntRenderFormation === 'function') {
    // 🆕 Her açılışta sunucudan GÜNCEL milli takım dizilişini çek (başkan değişikliği herkese yansır)
    if (typeof _ntStrategyLoadFromServer === 'function') {
      _ntStrategyLoadFromServer().then(() => { try { _ntActivePitchPlayers = []; } catch(e){} ntRenderFormation(); }).catch(() => ntRenderFormation());
    } else { ntRenderFormation(); }
  }
  else if(name === 'chat' && typeof ntRenderChat === 'function') ntRenderChat();
  else if(name === 'fixture' && typeof ntRenderFixture === 'function') ntRenderFixture();
  else if(name === 'standings' && typeof ntRenderStandings === 'function') ntRenderStandings(true);   // 736 — açılış: güncel aşama
  else if(name === 'callup' && typeof ntRenderCallup === 'function') ntRenderCallup();
  else if(name === 'trophies' && typeof ntRenderTrophies === 'function') ntRenderTrophies();

  if(name === 'chat') {
    // ⚠️ SIRA ÖNEMLİ.
    // 1) Önce sınıf: hero bar gizlenir, sayfa kısalır.
    // 2) Sonra başa kaydır: hero bar gidince sekme şeridi zaten üst
    //    barın hemen altına gelir; kaydırma konumuna bağlı ölçüm
    //    yapmaya gerek kalmaz (eski yöntem, sohbet fixed olunca sayfa
    //    kısaldığı için tarayıcı kaydırmayı kırpıyor ve sekmeler
    //    ekrandan kayıyordu).
    // 3) En son ölç.
    document.body.classList.add('nt-chat-active');
    _ntChatSeritHizala();
    _ntChatUstOlc();
    requestAnimationFrame(_ntChatUstOlc);  // render sonrası
    setTimeout(_ntChatUstOlc, 140);        // yazı tipi/görsel oturunca
  } else {
    document.body.classList.remove('nt-chat-active');
  }
}

// 🆕 Milli sohbet kutusunun üst kenarı — sekme şeridinin hemen altı.
//    Kulüp sohbetinde bu değer 193px sabit; milli takım sayfasının başlık
//    yüksekliği farklı olduğu için ölçerek yazıyoruz.
function _ntChatUstOlc(){
  try{
    if(document.body.classList.contains('kbd-open')) return;  // klavye açıkken ölçme
    const tabs = document.querySelector('#page-national .nt-tabs');
    if(!tabs) return;
    let alt = Math.round(tabs.getBoundingClientRect().bottom);
    // ⚠️ getBoundingClientRect EKRANA göre ölçer. Milli takım sayfasının
    //    başlığı + hero barı uzun olduğu için sayfa kaydırılmamışken
    //    sekme şeridi ekranın çok aşağısında kalıyor. Ölçülen değer
    //    doğrudan sohbet kutusunun ÜST kenarı olduğundan, kutuya bir
    //    şerit kadar yer kalıyordu (620 px'lik pencerede 597 px → 23 px).
    //    Güvenlik sınırı: üst kenar ekranın yarısını geçemez; geçerse
    //    üst barın hemen altına sabitlenir.
    const tb    = document.getElementById('topbar');
    const tbAlt = tb ? Math.round(tb.getBoundingClientRect().bottom) : 0;
    const sinir = Math.round((window.innerHeight || 800) * 0.5);
    if(alt <= 0 || alt > sinir) alt = Math.max(0, tbAlt);
    if(alt > 0) document.documentElement.style.setProperty('--nt-chat-top', alt + 'px');
  }catch(e){}
}

// 🆕 Sohbet açılmadan önce sekme şeridini üst barın hemen altına kaydır.
//    Böylece ölçüm her seferinde aynı sonucu verir ve sohbet kutusu
//    ekranın tamamını kullanır — sayfanın nereye kaydırılmış olduğundan
//    bağımsız.
function _ntChatSeritHizala(){
  try{
    if(document.body.classList.contains('kbd-open')) return;
    // Hero bar `nt-chat-active` ile gizlendiği için sayfanın başında
    // artık sadece başlık kutusu + sekme şeridi kalıyor. Başa almak
    // yeterli; şerit üst barın hemen altına oturuyor.
    window.scrollTo(0, 0);
  }catch(e){}
}
window._ntChatSeritHizala = _ntChatSeritHizala;
window._ntChatUstOlc = _ntChatUstOlc;

function teamTab(name, el) {
  if (name === 'trophies' && typeof renderTrophyShelf === 'function') {
    setTimeout(() => renderTrophyShelf(), 50);
  }
  // Sohbet sekmesinde aktif oylamalar
  if (name === 'chat' && typeof vtRenderActiveList === 'function') {
    setTimeout(() => vtRenderActiveList(), 50);
  }
  // 🆕 Manifesto sekmesi — server'dan tazele, sonra render
  if (name === 'manifesto' && typeof mfsRender === 'function') {
    if (typeof _mfsLoadFromServer === 'function') {
      _mfsLoadFromServer().then(() => mfsRender()).catch(() => mfsRender());
    } else {
      setTimeout(() => mfsRender(), 50);
    }
  }
  // 🆕 Forma sekmesi
  if (name === 'jersey' && typeof jrsRender === 'function') {
    setTimeout(() => jrsRender(), 50);
  }
  // 🆕 Finans sekmesi — açılışta kasayı sunucudan tazele (üye dahil herkes gerçek değeri görür)
  if (name === 'treasury') {
    if (typeof fxSekmeVarsayilan === 'function') fxSekmeVarsayilan();   // 692
    if (typeof _trsLoadFromServer === 'function') {
      _trsLoadFromServer().then(() => { if(typeof trsRender === 'function') trsRender(); }).catch(() => { if(typeof trsRender === 'function') trsRender(); });
    } else if (typeof trsRender === 'function') {
      setTimeout(() => trsRender(), 50);
    }
  }
  // Ziyaretçi modunda owner-only sekmelere geçiş engellenir
  const OWNER_ONLY = ['formation','table','fixture','treasury','chat','jersey'];
  if(_viewingTeam && OWNER_ONLY.indexOf(name) !== -1) {
    // Sessizce roster'a yönlendir
    name = 'roster';
    el = document.querySelectorAll('.team-tab')[0];
  }

  ['roster','formation','table','fixture','facility','chat','treasury','trophies','manifesto','jersey'].forEach(t => {
    const e = document.getElementById('team-' + t);
    if(e) e.style.display = t === name ? 'block' : 'none';
  });
  document.querySelectorAll('.team-tab').forEach(t => t.classList.remove('active'));
  if(el) el.classList.add('active');

  // 🆕 Sohbet sekmesi için body class — fixed konum CSS'ini tetikler
  if(name === 'chat') document.body.classList.add('team-chat-active');
  else document.body.classList.remove('team-chat-active');
  if(name === 'chat' && !_viewingTeam && typeof rhSohbet === 'function') rhSohbet();   // 663
  if(typeof rhSekme === 'function') rhSekme(name);   // 668 — Tesis / Finans rehberi

  if(name === 'roster') {
    if(_viewingTeam) {
      guestRenderRoster();
    } else {
      // 🆕 Diziliş henüz yüklenmemişse SADECE strateji yükle (initFormation değil — render zinciri tetikler).
      // loadTeamStrategy localStorage'dan activePitchPlayers'ı geri yükler.
      if (typeof activePitchPlayers !== 'undefined' && activePitchPlayers.length === 0
          && typeof loadTeamStrategy === 'function') {
        try { loadTeamStrategy(); } catch(e){}
      }
      renderRoster(rosterCurrentFilter||'all');
      if(typeof trsRender === 'function') trsRender();
    }
  }
  if(name === 'formation') {
    if(_viewingTeam) return; // guard
    // 957 — Diziliş kapalıyken atlanan saha / yedek / şerit çizimi: sunucu yanıtı beklenmeden güncel hâl
    if (window._g957DzKirli) { window._g957DzKirli = false; try { renderPitch(); renderBench(); } catch(e) {} }
    // 🆕 Her açılışta sunucudan GÜNCEL dizilişi çek → kaptan/yardımcı değişikliği TÜM kullanıcılara yansır
    if (typeof _teamStrategyLoadFromServer === 'function') {
      _teamStrategyLoadFromServer().then(() => {
        try { activePitchPlayers = []; benchPlayers = []; } catch(e){}
        if (typeof initFormation === 'function') initFormation();
      }).catch(() => {
        if(activePitchPlayers.length === 0) initFormation(); else { renderPitch(); renderBench(); }
      });
    } else {
      if(activePitchPlayers.length === 0) initFormation();
      else { renderPitch(); renderBench(); }
    }
  }
  if(name === 'fixture') {
    if(_viewingTeam) return;
    renderFixture();
    // 🆕 Sekme görünür olduktan sonra güncel haftaya ortala
    try { if (typeof _fixScrollToCurrent === 'function') _fixScrollToCurrent(); } catch(e) {}
  }
  if(name === 'table') {
    if(_viewingTeam) return;
    if(typeof renderTeamLeagueTable === 'function') renderTeamLeagueTable();
  }
  if(name === 'facility') {
    if(_viewingTeam) {
      guestRenderFacilities();
    } else {
      renderFacilities();
      if(typeof trsRender === 'function') trsRender();
    }
  }
  if(name === 'treasury') {
    if(_viewingTeam) return;
    trsRender();
  }
  if(name === 'chat') {
    if(_viewingTeam) return;
    _tsOkundu();   // 701
    // 🆕 Server'dan son 200 mesajı yükle
    if (typeof _teamChatLoadAndRender === 'function') {
      _teamChatLoadAndRender().catch(()=>{});
    }
    const ca = document.getElementById('teamChatArea');
    if(ca) ca.scrollTop = ca.scrollHeight;
  }
}

// Kasa özet çubuğundan Kasa sekmesine zıplama yardımcısı
function goToTreasury(){
  const tabs = document.querySelectorAll('.team-tab');
  const btn  = Array.from(tabs).find(b => b.textContent.includes('Kasa'));
  teamTab('treasury', btn || null);
}

// ── Ziyaretçi (guest) modu ──
// Başka takımları yetkisiz görüntüleme. Sadece Kadro ve Tesis erişilebilir.
let _viewingTeam = null; // null = kullanıcının kendi takımı (Ankara), {countryCode, teamRef} = ziyaretçi modu
let _viewingTeamPrevPage = null; // ziyaretçi moduna geçmeden önceki sayfa (geri butonu için)
let _viewingTeamHl = 0;          // 735 — misafir takıma girerken sayfa geçmişinin uzunluğu (dönüşte o hâle döner)

// Bottom nav indeksleri (showPage'in btn parametresi için)
const NAV_PAGE_INDEX = {
  home:0, player:1, team:2, training:3, leagues:4, tournaments:5,
  transfers:6, entertainment:7, rankings:8, shop:9, settings:10
};
function findNavBtn(pageName) {
  const idx = NAV_PAGE_INDEX[pageName];
  if(idx === undefined) return null;
  const btns = document.querySelectorAll('.nav-btn');
  return btns[idx] || null;
}

