function viewTeam(countryCode, teamName) {
  // 🆕 Başka ülkenin takımına bakılıyorsa o ülkenin gerçek oyuncularını yükle
  try { if (countryCode && typeof _loadRealCaptainsFromServer === 'function') _loadRealCaptainsFromServer(countryCode).catch(()=>{}); } catch(e) {}
  if(userHasTeam() && _userTeam.countryCode === countryCode && _userTeam.teamName === teamName) {
    return exitGuestMode(true);
  }
  if(false) return;
  const country = _cftGetCountry(countryCode);
  if(!country) return;
  let teamRef = null;
  let tierIdxFound = 0;
  for(let i = 0; i < country.leagues.length; i++) {
    const t = country.leagues[i].teams.find(x => x.name === teamName);
    if(t) { teamRef = t; tierIdxFound = i; break; }
  }
  if(!teamRef) return;

  // Önceki sayfayı sakla — geri butonunda buraya dönecek
  const activePage = document.querySelector('.page.active');
  let prevId = activePage ? activePage.id.replace('page-', '') : 'home';
  // Eğer zaten guest mode'daysak (takım sayfasında bir başka takıma geçiş), önceki sayfa korunur
  if(!_viewingTeam) {
    _viewingTeamPrevPage = prevId;   // 735 — 'team' = kendi takım sayfası (Geri oraya döner)
    _viewingTeamHl = (window._pageHist || []).length;
  }

  _viewingTeam = {
    countryCode, country, teamRef, tierIdx: tierIdxFound,
    leagueName: country.leagues[tierIdxFound].name
  };

  // Page'i guest moda al, takım sayfasına geç
  const page = document.getElementById('page-team');
  if(page) page.classList.add('guest-mode');

  // 🆕 Banner kaldırıldı; yerine info-chips alanında join chip kullanılıyor
  const joinBtn = document.getElementById('thbJoinChip');
  if(joinBtn) {
    if(userHasTeam()) {
      joinBtn.style.display = 'none';
      page.classList.add('no-join-chip');
    } else {
      joinBtn.style.display = 'inline-flex';
      page.classList.remove('no-join-chip');
      const txtEl = joinBtn.querySelector('.thb-join-text');
      const iconEl = joinBtn.querySelector('.thb-join-icon');
      // Daha önce istek gönderildi mi?
      if(hasJoinRequestFor(countryCode, teamName)) {
        if(iconEl) iconEl.textContent = '✓';
        if(txtEl) txtEl.textContent = 'İstek Gönderildi';
        joinBtn.style.background = 'rgba(102,187,106,.18)';
        joinBtn.style.borderColor = 'rgba(102,187,106,.4)';
        joinBtn.style.borderLeftColor = '#66bb6a';
        joinBtn.style.cursor = 'default';
        joinBtn.style.boxShadow = 'none';
        joinBtn.dataset.disabled = '1';
      } else {
        // 🆕 Buton metni KAPTAN TİPİNE göre: bot kaptan → direkt katıl; gerçek kaptan → talep
        const elig = (typeof evaluateJoinEligibility === 'function')
          ? evaluateJoinEligibility(countryCode, teamName)
          : { canDirect: true, captainType: 'bot' };
        const _isRealCaptain = elig.captainType === 'user';
        if(iconEl) iconEl.textContent = _isRealCaptain ? '🤝' : '🚀';
        if(txtEl) txtEl.textContent = _isRealCaptain ? 'Katılma Talebi' : 'Takıma Katıl';
        // Stil reset (eski state'ten gelmiş olabilir)
        joinBtn.style.background = '';
        joinBtn.style.borderColor = '';
        joinBtn.style.borderLeftColor = '';
        joinBtn.style.cursor = '';
        joinBtn.style.boxShadow = '';
        joinBtn.dataset.disabled = '';
      }
    }
  }

  // Sayfaya git
  showPage('team', null);
  // Bottom nav'ı manuel set et (Takım butonu)
  const navBtns = document.querySelectorAll('.nav-btn');
  navBtns.forEach(b => b.classList.remove('active'));

  // Hero ve içerikleri ziyaretçi moduna göre render et
  guestRenderHeader();
  // Roster sekmesini aç (Kadro)
  const rosterTabBtn = document.querySelectorAll('.team-tab')[0];
  teamTab('roster', rosterTabBtn);
}

function exitGuestMode(silent) {
  const prevPage = _viewingTeamPrevPage, hl = _viewingTeamHl;
  _viewingTeam = null;
  _viewingTeamPrevPage = null;
  const page = document.getElementById('page-team');
  if(page) page.classList.remove('guest-mode');
  if(page) page.classList.remove('no-join-chip');
  // Hero'yu kullanıcı takımına geri al
  guestRestoreHeader();
  if(!silent) {
    // 735 — Geri: misafir takıma girmeden önceki sayfa ('team' = kendi takım sayfası); geçmiş o ana döner
    const h = window._pageHist || [];
    if (h.length > hl) h.length = hl;
    const hedef = prevPage || 'home';
    // 934d — ziyaretçi oyuncu sayfasından "Takımını Gör" ile gelindiyse Geri yine o oyuncunun sayfası
    const zg = window._plZiyGeri; window._plZiyGeri = null;
    if (hedef === 'player' && zg && zg.d && Date.now() - zg.t < 3600000) {
      _visitedPlayerData = zg.d; _visitedReturnAction = zg.r;
      try { _loadVisitorEq(zg.d.player); } catch (e) {}
      window._navBack = true;
      try { showPage('player', null); const nb = findNavBtn('player'); if (nb) nb.classList.add('active'); } finally { window._navBack = false; }
      return;
    }
    window._navBack = true;
    try { showPage(hedef, findNavBtn(hedef)); } finally { window._navBack = false; }
  }
}

// 🆕 Gerçek tesis gelişim % — herhangi bir takımın Supabase tesis seviyelerinden (uydurma seed YOK).
//   calcDevLevel ile aynı ölçek (6 tesis × 10 = 60). Eksik tesis = seviye 1 → gelişmemiş takım %10.
async function _teamRealDevPct(cc, name) {
  if (!window.sb || !cc || !name) return null;
  try {
    const { data } = await window.sb.from('team_data').select('data')
      .eq('country_code', cc).eq('team_name', name).eq('data_key', 'facilities').maybeSingle();
    const levels = (data && data.data) ? data.data : {};
    const facs = (typeof FAC_DATA !== 'undefined') ? FAC_DATA : [];
    if (!facs.length) return null;
    let total = 0;
    for (const fc of facs) {
      const lvl = (levels[fc.id] && levels[fc.id] >= 1) ? levels[fc.id] : 1;
      total += lvl;
    }
    return Math.round((total / (facs.length * 10)) * 100);
  } catch(e) { return null; }
}

// Hero başlığını ziyaret edilen takıma göre güncelle
function guestRenderHeader() {
  if(!_viewingTeam) return;
  const v = _viewingTeam;
  const logo = document.querySelector('#team-roster .thb-logo');
  const name = document.querySelector('#team-roster #teamHeroName');
  const meta = document.querySelector('#team-roster #teamHeroMeta');
  const userEl = document.querySelector('#team-roster #teamHeroUser');
  const stats = null; // eski .thb-stats yapısı yok — rank/power/players id'lerine yazılır (aşağıda)
  if(logo) {
    logo.className = 'thb-logo c1';
    logo.style.background = v.teamRef.bg;
    logo.style.color = v.teamRef.tc;
    logo.textContent = v.teamRef.short;
    // 🆕 Logo varsa <img> ile değiştir
    if (typeof applyCrestToEl === 'function') {
      applyCrestToEl(logo, v.teamRef.name, v.teamRef.short);
    }
  }
  if(name) name.textContent = (typeof takimGorunenAd === 'function') ? takimGorunenAd(v.teamRef.name, v.countryCode) : v.teamRef.name;   // 910
  try { _bgnTakimHero(v.countryCode, v.teamRef.name, true); } catch (e) {}   // 784
  // 🆕 Gerçek tesis gelişim % — Supabase'ten (uydurma seed kaldırıldı)
  v._devPct = null;
  const facEl = document.getElementById('teamHeroFacility');
  if(facEl) facEl.textContent = '%—';
  _teamRealDevPct(v.countryCode, v.teamRef.name).then(pct => {
    const p = (pct != null) ? pct : 10;
    v._devPct = p;
    const fe = document.getElementById('teamHeroFacility');
    if(fe && _viewingTeam === v){ fe.textContent = '%' + p; fe.style.color = p === 100 ? '#ffd11a' : '#9fe06a'; }
  });
  if(meta) meta.textContent = `${v.country.flag} ${v.country.name} · ${v.leagueName}`;
  // Bu takımın kaptanı kim? (deterministic — guest roster ile aynı seed)
  let roster = [];
  try {
    roster = getOrCreateTeamRoster({ countryCode: v.countryCode, name: v.teamRef.name, rank: v.teamRef.rank || 1 });
  } catch(e) {}
  if(userEl) {
    const captain = roster.find(p => p.role === 'captain');
    userEl.textContent = captain ? ('Kaptan: ' + captain.name) : '—';
  }
  // 🆕 Ziyaretçi stats: var olan hero-strip hücrelerine yaz (sıra/güç/kadro) — gerçek değerler
  {
    const playerCount = roster.length || 15;
    const rankEl = document.getElementById('teamHeroRank');
    const powerEl = document.getElementById('teamHeroPower');
    const playersEl = document.getElementById('teamHeroPlayers');
    const playersMaxEl = document.getElementById('teamHeroPlayersMax');
    if (typeof _updateTeamHeroRankPoints === 'function') _updateTeamHeroRankPoints(v.countryCode, v.teamRef.name);
    if (powerEl) powerEl.textContent = String(_teamPowerFromPlayers(v.countryCode, v.teamRef.name, v.teamRef.rank || 1));
    const mvEl = document.getElementById('teamHeroMarket');
    if (mvEl) {
      let _mv = calculateTeamValue({ name: v.teamRef.name, countryCode: v.countryCode }); // 🆕 kadrodaki oyuncuların gösterilen değerlerinin TOPLAMI (tek doğru)
      mvEl.textContent = (typeof _carFmtEUR === 'function') ? _carFmtEUR(_mv) : (_mv + ' €');
    }
    if (playersEl) playersEl.textContent = String(playerCount);
    if (playersMaxEl) playersMaxEl.textContent = String(playerCount);
  }
  // Hat güçleri (KL/DF/OS/FW) — guest roster'dan
  try {
    const POSGRP = (typeof POS_GROUP !== 'undefined') ? POS_GROUP
      : { KL:'GK', GK:'GK', STB:'DEF', SB:'DEF', DEF:'DEF', DOS:'MID', OS:'MID', SAK:'MID', MID:'MID', FWD:'FWD' };
    const buckets = { GK:[], DEF:[], MID:[], FWD:[] };
    roster.forEach(p => {
      const grp = POSGRP[p.pos] || p.pos;
      if (buckets[grp]) buckets[grp].push(p.overall || 0);
    });
    const avg = arr => arr.length ? Math.round(arr.reduce((s,v)=>s+v,0)/arr.length) : 0;
    const ls = { GK:avg(buckets.GK), DEF:avg(buckets.DEF), MID:avg(buckets.MID), FWD:avg(buckets.FWD) };
    const setLine = (idVal, idBar, val) => {
      const valEl = document.getElementById(idVal);
      const barEl = document.getElementById(idBar);
      if (valEl) valEl.textContent = val ? String(val) : '—';
      if (barEl) barEl.style.width = Math.max(0, Math.min(100, val||0)) + '%';
    };
    setLine('thbLineGK', 'thbLineGKBar', ls.GK);
    setLine('thbLineDF', 'thbLineDFBar', ls.DEF);
    setLine('thbLineMD', 'thbLineMDBar', ls.MID);
    setLine('thbLineFW', 'thbLineFWBar', ls.FWD);
  } catch(e) {}
  _tsaGuncelle();   // 699 — "Takımı Al" etiketi
}

