// Ziyaret edilen takımın 15 bot oyuncusunu deterministic üret
// Her oyuncu o ülkenin vatandaşı, yerli isimle
// 🆕 Takım sayfası için kadro üreticisi — getOrCreateTeamRoster'a yönlendirir
// (Maç ekranı ile takım sayfası AYNI kadroyu görür)
// guestGenerateRoster fonksiyonu SİLİNDİ — çağrılar getOrCreateTeamRoster'a yönlendirildi.


// ══ TAKIMA KATILMA ŞARTLARI VE KATILIM SİSTEMİ ══
// Üç tip katılım vardır:
//   1) Direkt katılım: takım kaptanı bot ise → onaysız direkt katılır
//   2) Şartlı direkt katılım: takım user kaptanlı + kullanıcı şartları karşılıyor → onaysız
//   3) Onaylı katılım: user kaptanlı + şartlar karşılanmıyor → kaptan/yardımcı onayı bekler

// Bir takımın kaptan tipini döndür: 'user' (gerçek kullanıcı) veya 'bot'
// 🆕 Bu fonksiyon yukarıda revize edildi (line ~22643). Eski stub burada kaldırıldı.
// (getTeamCaptainType ve userHasActiveContract artık SÖZLEŞME modülünde tanımlanıyor.)

// Bir takımın katılım şartlarını döndür (null = şart yok)
function getTeamJoinRequirements(countryCode, teamName) {
  // Kullanıcının kendi takımı (kaptan iken) → kendi belirlediği şartlar
  if(_userTeam && _userTeam.countryCode === countryCode
     && _userTeam.teamName === teamName) {
    return _userTeam.joinRequirements || null;
  }
  // 🆕 Başka takım → paylaşılan politika cache'i (teams.join_policy)
  try {
    const p = (window._teamJoinPolicyCache||{})[countryCode+':'+teamName];
    if(p) return { minSkill: p.minSkill||0, minLevel: p.minLevel||0, contract: !!p.contract };
  } catch(e){}
  return null;
}

// Kullanıcının yetenek + seviyesi şartı karşılıyor mu?
function userMeetsJoinRequirements(req) {
  if(!req) return true; // Şart yoksa otomatik karşılar
  const me = (typeof ROSTER_DATA !== 'undefined') ? ROSTER_DATA.find(p => p.role === 'user') : null;
  if(!me) return false;
  const userSkill = me.overall || 10;
  const userLevel = me.level || 0;
  return userSkill >= (req.minSkill||0) && userLevel >= (req.minLevel||0);
}

// Kullanıcının takıma katılım için "direkt katılabilir mi" kararı
// Returns: { canDirect: bool, reason: string, captainType: 'user'|'bot', req: {...}|null }
function evaluateJoinEligibility(countryCode, teamName) {
  const captainType = getTeamCaptainType(countryCode, teamName);
  const req = getTeamJoinRequirements(countryCode, teamName);

  // Bot kaptanlı veya kaptansız → direkt katıl
  if(captainType === 'bot') {
    return { canDirect: true, reason: 'bot-captain', captainType, req: null };
  }

  // User kaptanlı → şartları kontrol et
  if(!req || (req.minSkill === 0 && req.minLevel === 0)) {
    return { canDirect: true, reason: 'no-requirements', captainType, req };
  }
  if(userMeetsJoinRequirements(req)) {
    return { canDirect: true, reason: 'meets-requirements', captainType, req };
  }
  return { canDirect: false, reason: 'requires-approval', captainType, req };
}

// Sözleşme kontrolü — kullanıcı sözleşmeli mi?
// 🆕 userHasActiveContract artık SÖZLEŞME modülünde sezon-bazlı tanımlandı.
// Aşağıdaki eski stub kaldırıldı.

// Bir takıma direkt katıl (onaysız) — bot kaptanlı veya şartı karşılayan kullanıcı için
async function joinTeamDirect(countryCode, teamName, opts) {
  // 🆕 TRANSFER DÖNEMİ KONTROLÜ
  // Kural: Sözleşmeli oyuncu (zaten bir takımda) sadece transfer döneminde geçiş yapabilir.
  //        Serbest oyuncu (takımsız) her zaman katılabilir.
  // SEASON_TEMPLATE'deki 'break' tipli günler transfer dönemidir (16-18 + 34-40).
  const _userCurrentlyHasTeam = !!(typeof _userTeam !== 'undefined' && _userTeam && _userTeam.teamName);
  // 592 — sözleşmesi süren oyuncu doğrudan katılmayla da takım değiştiremez (sunucu da engeller)
  if (_userCurrentlyHasTeam && _userTeam.role !== 'captain' && typeof canUserLeaveTeam === 'function') {
    const _ck = canUserLeaveTeam();
    if (_ck && !_ck.allowed) { if (typeof _ayrilamazModal === 'function') _ayrilamazModal(_ck); return false; }
  }
  if (_userCurrentlyHasTeam && typeof _enforceTransferWindow === 'function') {
    const r = _enforceTransferWindow(`${_userTeam.teamName}'dan ${teamName}'a transfer`);
    if (r.blocked) {
      if (typeof showJoinToast === 'function') showJoinToast('⛔ Transfer dönemi kapalı');
      return false;
    }
  }

  const team = (_cftGetCountry(countryCode)||{}).leagues || [];
  let teamObj = null, tierIdx = 0;
  for(let i = 0; i < team.length; i++) {
    const t = (team[i].teams||[]).find(x => x.name === teamName);
    if(t) { teamObj = t; tierIdx = i; break; }
  }

  // 🆕 Atomik slot al (RPC): mevkiye uyan en zayıf slot-botu serbest bırak (free agent),
  //   kullanıcıya o botun numarasını ver → takım 15'te kalır, kullanıcı gerçek slota oturur.
  if (!window.sb || !(authUser && authUser.id)) {
    if (typeof showJoinToast === 'function') showJoinToast('⚠️ Bağlantı yok, sayfayı yenile.');
    return false;
  }
  // _userTeam'i hemen kur (senkron — çağıranlar takım kimliğine await beklemeden erişsin)
  const _prevTeam = _userTeam;
  _userTeam = {
    countryCode,
    teamName,
    role: 'member',         // Direkt katılım her zaman üye rolünde
    tierIdx,
    joinedAt: Date.now(),
  };
  const { data: _assignedNum, error: _joinErr } = await window.sb.rpc('join_team_take_slot', {
    p_user_id: authUser.id,
    p_country_code: countryCode,
    p_team_name: teamName,
    p_user_team_data: _userTeam,
  });
  if (_joinErr || _assignedNum == null) {
    console.warn('[joinTeamDirect] slot RPC hata:', _joinErr && _joinErr.message);
    _userTeam = _prevTeam;   // başarısızsa eski duruma dön
    const _jm = String((_joinErr && _joinErr.message) || '');
    // 598 — katılma kuralları artık sunucuda (onay, şart, kadro sınırı)
    const _jMsg = /sozlesme_aktif/.test(_jm) ? '⛔ Sözleşmen sürüyor, süresi bitmeden ayrılamazsın.'
      : /onay_gerekli/.test(_jm) ? '⛔ Bu takıma katılmak için kaptan onayı gerekiyor.'
      : /sart_karsilanmiyor/.test(_jm) ? '⛔ Takımın katılım şartlarını karşılamıyorsun.'
      : /mevki_dolu/.test(_jm) && typeof _mevkiDoluMetin === 'function' ? '⛔ ' + _mevkiDoluMetin(_jm)
      : /sadece_satin/.test(_jm) ? '⛔ Bu takımda yer yok, sadece satın alınabilir.'   // 931
      : /kadro_dolu/.test(_jm) ? '⛔ Takım kadrosu dolu.'
      : /yabanci_dolu/.test(_jm) ? '⛔ Bu takımın yabancı oyuncu kontenjanı dolu (10/10).'
      : /zaten_takimda/.test(_jm) ? '⛔ Önce mevcut takımından ayrılmalısın.'
      : '⚠️ Takıma katılınamadı, tekrar dene.';
    if (typeof showJoinToast === 'function') showJoinToast(_jMsg);
    return false;
  }
  _userTeam.num = _assignedNum;
  if(typeof achBump === 'function') achBump('join');   // 🆕 başarı: takıma katılma sayacı

  // Career history: bot kaptanlı takıma direkt katılım
  if (typeof pushCareerHistory === 'function') {
    const lgName = (_cftGetCountry(countryCode) && _cftGetCountry(countryCode).leagues && _cftGetCountry(countryCode).leagues[tierIdx])
      ? _cftGetCountry(countryCode).leagues[tierIdx].name : '';
    pushCareerHistory({
      teamName, countryCode,
      leagueName: lgName,
      role: 'member',
      joinDate: new Date().toISOString(),
    });
  }

  // 694 — yeni takımın her şeyi sunucudan (tesis, kasa, diziliş, sohbet, rol, enerji bonusu)
  await userTeamLoadFromServer();
  exitGuestMode(true);
  const _energyDelta = await _takimDurumTazele(_prevTeam ? _prevTeam.countryCode + '|' + _prevTeam.teamName : '');
  updateHero();
  renderForeignBar();

  if(_energyDelta > 0 && typeof showJoinToast === 'function') showJoinToast(`⚡ +${_energyDelta} bonus enerji!`);

  if (typeof sctKapat === 'function') sctKapat();   // 829 — scout raporundan katıldıysa
  // Takım sayfasına yönlendir + 590 tebrik (forma töreni)
  if(typeof showPage === 'function') showPage('team', null);
  ktTebrikAc({ takim: teamName, cc: countryCode, num: _assignedNum, rol: 'member' });
}

// Kaptan: katılım şartları modalını aç
// 🆕 Hazırlık Maçı Düzenle — Kaptan VEYA Yardımcı kaptan yetkisi
function captainScheduleFriendly() {
  if(typeof _viewingTeam !== 'undefined' && _viewingTeam){
    if(typeof showJoinToast === 'function') showJoinToast('⚠️ Bu başkasının takımı.');
    return;
  }
  if (typeof FRM_AKTIF !== 'undefined' && !FRM_AKTIF) {
    if(typeof showJoinToast === 'function')
      showJoinToast('🔧 Hazırlık maçları geçici olarak kapalı — yakında geri geliyor.');
    return;
  }
  if(!_userTeam || (_userTeam.role !== 'captain' && _userTeam.role !== 'vice')) {
    if(typeof showJoinToast === 'function') showJoinToast('⚠️ Sadece kaptan veya yardımcı kaptan hazırlık maçı düzenleyebilir.');
    return;
  }
  frmOpenModal();
}

// ═══════════════════════════════════════════════════════════════════
//  🔴 HAZIRLIK MAÇI — GEÇİCİ OLARAK KAPALI
//
//  Sebep: hazırlık maçı kurulduktan sonra Takımım sayfasında donma
//  bildirildi ve kök neden telefonda ölçülemedi. Eski maç motoru
//  sorunsuz çalıştığı için yayın öncesi bu özellik devre dışı.
//
//  AÇMAK İÇİN: aşağıdaki satırı  true  yap. Kodun tamamı duruyor,
//  hiçbir şey silinmedi.
// ═══════════════════════════════════════════════════════════════════
const FRM_AKTIF = false;

// ── Hazırlık Maçı (FRiendly Match) sistemi ─────────────────────────
const FRM_BUFFER_MS = 60 * 60 * 1000; // ±1 saat

// 🆕 RAM cache: hazırlık maçları (bootstrap'ta Supabase'ten yüklenir)
let _frmMatchesCache = [];

// Server'dan tüm hazırlık maçlarını yükle (bootstrap)
async function _frmLoadFromServer() {
  if (!window.sb) { _frmMatchesCache = []; return; }
  // 🆕 563 — özellik kapalıyken (FRM_AKTIF=false) dakikada bir sorgu atılmasın
  if (typeof FRM_AKTIF !== 'undefined' && !FRM_AKTIF) { _frmMatchesCache = []; return; }
  try {
    // 🆕 SADECE KENDİ DAVETLERİM — eskiden tüm dünyanın hazırlık maçları çekiliyordu.
    //   Başka oyuncuların bekleyen davetlerine de bu istemci bot cevabı üretiyor,
    //   her cevap benim gelen kutuma mesaj düşürüyordu (bitmeyen bildirim yağmuru).
    const _uid = (window.authUser && window.authUser.id)
              || (window._userTeam && window._userTeam.userId) || null;
    const _myTeam = (typeof _userTeam !== 'undefined' && _userTeam && _userTeam.teamName) ? _userTeam.teamName : null;
    // ⛔ Kimlik yoksa (auth henüz hazır değil) HİÇBİR KAYIT YÜKLEME.
    //   Aksi halde tüm dünyanın hazırlık maçları cache'e giriyor, _frmResolveStuck
    //   hepsine bot cevabı üretip gelen kutusunu bildirimle dolduruyor ve açılışı kilitliyordu.
    if (!_uid && !_myTeam) { _frmMatchesCache = []; return; }
    let _q = window.sb.from('friendly_matches').select('id, user_id, match_data, created_at');
    // user_id'si boş ESKİ kayıtlar da gelsin (takım adıyla eleyeceğiz)
    if (_uid) _q = _q.or('user_id.eq.' + _uid + ',user_id.is.null');
    const { data, error } = await _q;
    if (error) { console.warn('[frm] load hata:', error); _frmMatchesCache = []; return; }
    _frmMatchesCache = (data || [])
      .filter(r => {
        if (!r) return false;
        const md = r.match_data || {};
        // Benim kaydım mı? (user_id eşleşmesi VEYA maçın taraflarından biri benim takımım)
        if (_uid && r.user_id === _uid) return true;
        if (_myTeam && (md.fromTeam === _myTeam || md.toTeam === _myTeam)) return true;
        return false;
      })
      .map(r => r.match_data || {});
    window._frmLoaded = true;   // 🆕 temizlik yalnızca gerçek liste geldikten sonra
    console.info('[frm] yüklendi:', _frmMatchesCache.length, 'hazırlık maçı');
  } catch(e) { console.warn('[frm] load hata:', e); _frmMatchesCache = []; }
}

// Sync API - RAM cache döner
function frmGetMatches() {
  return _frmMatchesCache.slice();
}

// Tek bir maçı server'a yaz (upsert)
async function _frmUpsertOne(match) {
  if (!window.sb || !match || !match.id) return;
  try {
    const uid = (window.authUser && window.authUser.id)
             || (window._userTeam && window._userTeam.userId) || null;
    const { error } = await window.sb.from('friendly_matches').upsert({
      id: match.id,
      user_id: uid,
      match_data: match,
      updated_at: new Date().toISOString()
    }, { onConflict: 'id' });
    // 🆕 Yazma başarısızsa durum sunucuda 'pending' kalıyor ve bot cevabı
    //   her yeniden yüklemede tekrar üretiliyordu — sessiz geçme, bildir.
    if (error) console.warn('[frm] upsert REDDEDİLDİ:', error.message, match.id);
  } catch(e) { console.warn('[frm] upsert hata:', e); }
}

// Tek bir maçı sil
// 🆕 HAZIRLIK MAÇI İPTAL — takılı kalmış / oynanmayan maçı temizle
//   Hem friendly_matches kaydını hem match_state satırını siler.
//   Konsoldan: frmCancel()            → oynanmamış TÜM hazırlık maçlarını listeler
//              frmCancel('frm_123')   → o maçı iptal eder
//              frmCancel('all')       → oynanmamış hepsini iptal eder
async function frmCancel(matchId) {
  const all = (typeof frmGetMatches === 'function') ? (frmGetMatches() || []) : [];
  const bekleyen = all.filter(m => m && !m.played && m.status !== 'rejected');
  if (!matchId) {
    if (!bekleyen.length) { console.info('[hazırlık] iptal edilecek maç yok'); return []; }
    console.table(bekleyen.map(m => ({
      id: m.id, rakip: m.toTeam, durum: m.status,
      tarih: m.dateTime ? new Date(m.dateTime).toLocaleString('tr') : '—'
    })));
    console.info("İptal için: frmCancel('<id>')  ·  hepsi için: frmCancel('all')");
    return bekleyen;
  }
  const hedef = (matchId === 'all') ? bekleyen : bekleyen.filter(m => m.id === matchId);
  if (!hedef.length) { console.warn('[hazırlık] maç bulunamadı:', matchId); return; }
  for (const m of hedef) {
    try { await _frmDeleteMatchState(m.id); } catch(e) {}
    try { await _frmDeleteOne(m.id); } catch(e) {}
    const i = _frmMatchesCache.findIndex(x => x && x.id === m.id);
    if (i >= 0) _frmMatchesCache.splice(i, 1);
    // 🆕 İSTEMCİ ÖNBELLEĞİNDEN DE SİL — ana sayfa maç önizlemesi match_state
    //    cache'ini ikinci kaynak olarak kullanıyor; yalnızca sunucudan silmek
    //    yetmiyordu, iptal edilen maç ekranda kalmaya devam ediyordu.
    try {
      const key = 'friendly_' + m.id;
      if (_matchStateCache && _matchStateCache.byKey && _matchStateCache.byKey[key]) {
        const gun = _matchStateCache.byKey[key].day;
        delete _matchStateCache.byKey[key];
        _matchStateCache._ix958 = (_matchStateCache._ix958 || 0) + 1;   // 958 — dizin sürümü (byKey'den silme)
        if (_matchStateCache.dayMap && Array.isArray(_matchStateCache.dayMap[gun])) {
          _matchStateCache.dayMap[gun] = _matchStateCache.dayMap[gun].filter(x => x && x.matchKey !== key);
        }
      }
      if (typeof _liveMatchCache === 'object' && _liveMatchCache) delete _liveMatchCache[key];
    } catch(e) {}
    console.info('[hazırlık] iptal edildi:', m.id, '·', m.toTeam);
  }
  try { if (typeof frmRender === 'function') frmRender(); } catch(e) {}
  // 🆕 Ana sayfa önizlemesini zorla tazele (10 sn'lik yükleme kilidini de sıfırla)
  try { window._frmLastLoad = 0; } catch(e) {}
  try { if (typeof renderHomeNextMatch === 'function') renderHomeNextMatch(); } catch(e) {}
  try { if (typeof updateHero === 'function') updateHero(); } catch(e) {}
  try { if (typeof showJoinToast === 'function') showJoinToast('🗑 Hazırlık maçı iptal edildi'); } catch(e) {}
  return hedef.length;
}
window.frmCancel = frmCancel;

// 🆕 İPTAL MODALI — telefonda konsol gerekmeden hazırlık maçı iptali
function frmOpenCancelModal() {
  const ov = document.getElementById('frmCancelOv');
  if (!ov) return;
  frmRenderCancelList();
  ov.classList.add('on');
  document.body.classList.add('bet-lock');
  // Kaptan menüsü açıksa kapat
  try { document.querySelectorAll('.thb-menu-dropdown.open').forEach(d => d.classList.remove('open')); } catch(e) {}
}
function frmCloseCancelModal() {
  const ov = document.getElementById('frmCancelOv');
  if (ov) ov.classList.remove('on');
  document.body.classList.remove('bet-lock');
}
function frmRenderCancelList() {
  const el = document.getElementById('frmCancelList');
  if (!el) return;
  const all = (typeof frmGetMatches === 'function') ? (frmGetMatches() || []) : [];
  const list = all.filter(m => m && !m.played && m.status !== 'rejected')
                  .sort((a, b) => new Date(a.dateTime).getTime() - new Date(b.dateTime).getTime());
  if (!list.length) {
    el.innerHTML = '<div class="frmc-empty">⚽ Bekleyen hazırlık maçın yok.<br>Oynanmış maçlar burada görünmez.</div>';
    return;
  }
  const AY = ['Oca','Şub','Mar','Nis','May','Haz','Tem','Ağu','Eyl','Eki','Kas','Ara'];
  const iki = n => String(n).padStart(2, '0');
  el.innerHTML = list.map(m => {
    const d = new Date(m.dateTime);
    const tar = isFinite(d.getTime())
      ? `${d.getDate()} ${AY[d.getMonth()]} · ${iki(d.getHours())}:${iki(d.getMinutes())}` : '—';
    const gecti = isFinite(d.getTime()) && d.getTime() < Date.now();
    const st = m.status === 'accepted'
      ? '<span class="frmc-st ok">KABUL</span>'
      : '<span class="frmc-st bek">BEKLİYOR</span>';
    const bg = m.toBg || '#37474f', tc = m.toTc || '#fff';
    const sh = m.toShort || String(m.toTeam || '?').slice(0, 3).toUpperCase();
    return `<div class="frmc-row" id="frmcRow_${m.id}">
        <span class="frmc-cr" style="background:${bg};color:${tc}">${sh}</span>
        <span class="frmc-tt"><b>${m.toTeam || '—'}</b>
          <span>${tar}${gecti ? ' · ⏱ saati geçti' : ''}${m.toLeague ? ' · ' + m.toLeague : ''}</span></span>
        ${st}
        <span class="frmc-del" onclick="frmCancelFromModal('${m.id}')" title="İptal et">🗑</span>
      </div>`;
  }).join('');
}
async function frmCancelFromModal(id) {
  const row = document.getElementById('frmcRow_' + id);
  if (row) { row.style.opacity = '.4'; row.style.pointerEvents = 'none'; }
  try { await frmCancel(id); } catch(e) {}
  frmRenderCancelList();
}
window.frmOpenCancelModal = frmOpenCancelModal;
window.frmCloseCancelModal = frmCloseCancelModal;
window.frmCancelFromModal = frmCancelFromModal;

async function _frmDeleteOne(matchId) {
  if (!window.sb || !matchId) return;
  // 🆕 2026-08-18 · SAHİPLİK FİLTRESİ
  //   Silme yalnızca `id` ile filtreleniyordu; tabloda RLS olup olmadığı da
  //   belirsiz. Konsoldan başkasının hazırlık maçı silinebiliyordu.
  //   Artık kendi satırından başkasına dokunulamıyor. (Tablo tarafında da
  //   RLS gerekiyor — guvenlik-eksik-tablolar.sql içinde.)
  try {
    const uid = (window.authUser && window.authUser.id) || null;
    if (!uid) { console.warn('[frm] delete iptal — oturum yok'); return; }
    const { error } = await window.sb.from('friendly_matches')
      .delete().eq('id', matchId).eq('user_id', uid);
    if (error) console.warn('[frm] delete REDDEDİLDİ:', error.message, matchId);
  } catch(e) { console.warn('[frm] delete hata:', e); }
}

// frmSaveMatches: tüm dizi gelince diff hesaplayıp yalnız değişenleri yaz
// Bu mevcut kodun davranışını korur (frmSaveMatches(updatedArr) çağrıları)
function frmSaveMatches(arr) {
  if (!Array.isArray(arr)) return;
  const oldById = {};
  for (const m of _frmMatchesCache) {
    if (m && m.id) oldById[m.id] = m;
  }
  const newById = {};
  for (const m of arr) {
    if (m && m.id) newById[m.id] = m;
  }
  // Silinen
  for (const id in oldById) {
    if (!newById[id]) _frmDeleteOne(id);
  }
  // Yeni veya değişen
  for (const id in newById) {
    const oldM = oldById[id];
    const newM = newById[id];
    if (!oldM || JSON.stringify(oldM) !== JSON.stringify(newM)) {
      _frmUpsertOne(newM);
    }
  }
  // RAM cache güncelle
  _frmMatchesCache = arr.slice();
}

// 🆕 Hazırlık maçı kabul edildiğinde match_state'e scheduled satır yazılır.
// Edge Function (tick-matches) scheduled status'lü ve kickoff'u geçmiş satırları
// otomatik başlatıp simüle eder — lig/turnuva maçlarıyla aynı akış.
async function _frmUpsertMatchState(fm) {
  if (typeof FRM_AKTIF !== 'undefined' && !FRM_AKTIF) return;   // 🔴 kapalı
  if (!fm || !fm.id) return;
  // 🔒 match_state İSTEMCİYE SALT-OKUNUR.
  //   Bu fonksiyon eskiden doğrudan `match_state`e upsert yapıyordu.
  //   Güvenlik turunda o tabloya yalnızca SELECT politikası kaldı
  //   (INSERT/UPDATE/DELETE yok), dolayısıyla yazma SESSİZCE
  //   reddediliyordu — dönen hata hiç kontrol edilmiyordu.
  //   Sonuç: friendly_matches kaydı oluşuyor, kullanıcı maçı listede
  //   görüyor, ama match_state satırı olmadığı için Edge Function
  //   maçı hiç başlatmıyordu. "Düzenleniyor ama başlamıyor" buydu.
  //   Artık satırı sunucu yazıyor (friendly_schedule).
  if (typeof edgeCall !== 'function') return;
  let r = null;
  try {
    r = await edgeCall('friendly_schedule', { fm: fm.id });
  } catch(e) {
    console.warn('[frm] takvime yazma bağlantı hatası:', e);
    return;
  }
  const d = (r && r.data) || {};
  if (!r.ok || d.error) {
    const MSG = {
      kayit_bulunamadi: 'Hazırlık kaydı sunucuda yok',
      kayit_bozuk: 'Hazırlık kaydı eksik',
      kabul_edilmemis: 'Maç henüz kabul edilmedi',
      yetki_yok: 'Bu maça yetkin yok',
      gecersiz_tarih: 'Tarih geçersiz',
      tarih_gecmis: 'Maç saati geçmiş',
      tarih_cok_ileri: 'Tarih çok ileride',
      milli_mac_saati: 'Bu saatte milli maç var — hazırlık maçı oynanamaz'
    }[d.error] || ('takvime yazılamadı: ' + (d.error || 'bilinmeyen'));
    console.warn('[frm] ' + MSG, fm.id);
    if (d.error === 'milli_mac_saati' && typeof showToast === 'function') showToast(MSG);
    return;
  }
  if (d.olusturuldu) console.info('[frm] takvime yazıldı:', d.match_key, d.kickoff);

  // Yazma sonrası: match_state cache'i yenile + günlük cache'i temizle.
  //   "Hazırlık maçı oluşturunca fikstür ve sonuçlar siliniyor" bug'ı bu adım eksikti.
  try {
    if (typeof _resFixtureDayCache !== 'undefined' && _resFixtureDayCache) {
      Object.keys(_resFixtureDayCache).forEach(k => delete _resFixtureDayCache[k]);
    }
    if (typeof _loadAllMatchStateFromServer === 'function') {
      await _loadAllMatchStateFromServer();
    }
  } catch(e) { console.warn('[frm upsert cache refresh]', e); }
}

// 🆕 Hazırlık reddedildi/iptal edildi → match_state'teki scheduled satır silinir.
// Maç zaten başlamışsa (running/finished) silmeye çalışmayız; Edge Function bitirir.
async function _frmDeleteMatchState(fmId) {
  // 🔒 Silme de istemciden yapılamıyor (match_state salt-okunur) — sunucuya.
  if (!fmId || typeof edgeCall !== 'function') return;
  try {
    const r = await edgeCall('friendly_cancel', { fm: fmId });
    const d = (r && r.data) || {};
    if (!r.ok || d.error) console.warn('[frm] iptal edilemedi:', d.error || r.status, fmId);
  } catch(e) { console.warn('[frm match_state delete]', e); }
}

// 🆕 Verilen takımın gerçek lig + turnuva maçlarının zamanları (datetime ms array)
//   KAYNAK: SADECE _matchStateCache (Supabase). Eski buildLeagueFixture lokal hesabı kaldırıldı.
function frmGetTeamBusyTimes(teamName, cc, lg) {
  const out = [];
  if (!teamName || !_matchStateCache || !_matchStateCache.byKey) return out;
  for (const ms of Object.values(_matchStateCache.byKey)) {
    if (!ms || !ms.matchDateTime) continue;
    if (ms.home !== teamName && ms.away !== teamName) continue;
    if (ms.tournament_key === 'friendly') continue;
    const t = new Date(ms.matchDateTime).getTime();
    if (isNaN(t)) continue;
    out.push({
      t,
      kind: ms.tournament_key ? 'tournament' : 'league',
      label: (ms.home || '') + ' vs ' + (ms.away || '')
    });
  }
  return out;
}

// Kullanıcının takımının gerçek lig + turnuva maçlarının zamanları (hazırlık planlama çakışma kontrol için)
//   🆕 KAYNAK: SADECE _matchStateCache (Supabase). Eski buildFixtureData lokal hesabı kaldırıldı.
function frmGetUserBusyTimes() {
  const times = [];
  if (!_userTeam || !_matchStateCache || !_matchStateCache.byKey) return times;
  const userTeamName = _userTeam.teamName;
  for (const ms of Object.values(_matchStateCache.byKey)) {
    if (!ms || !ms.matchDateTime) continue;
    // Sadece kullanıcının takımının maçları
    if (ms.home !== userTeamName && ms.away !== userTeamName) continue;
    // Hazırlık maçları çakışma kontrolüne dahil DEĞİL (zaten _frmMatchesCache'ten ayrı handle ediliyor)
    if (ms.tournament_key === 'friendly') continue;
    const t = new Date(ms.matchDateTime).getTime();
    if (isNaN(t)) continue;
    times.push({
      t,
      kind: ms.tournament_key ? 'tournament' : 'league',
      label: (ms.home || '') + ' vs ' + (ms.away || '')
    });
  }
  return times;
}

// Çakışma kontrol: ±1 saat aralığında, kendi VEYA rakip takımın gerçek lig maçı var mı?
// Hazırlık maçları çakışma kontrolüne dahil DEĞİL.
function frmCheckConflict(dateTimeStr, opponent /* { team, cc, lg } */) {
  const t = new Date(dateTimeStr).getTime();
  if (isNaN(t)) return { ok: false, reason: 'Geçersiz tarih' };
  if (t < Date.now()) return { ok: false, reason: 'Geçmiş bir tarih seçemezsin' };

  // 572 — EURO Nations Cup günlerinde (34–40) milli maç saatlerinde hazırlık maçı yok
  //   (sunucu kuralı: 11:45–15:30 UTC). Oyuncular aynı anda iki maçta olamaz.
  try {
    const _si = (typeof getSeasonInfo === 'function') ? getSeasonInfo() : null;
    if (_si && _si.seasonStart) {
      const d = new Date(t);
      const gunMs = Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate());
      const basMs = Date.UTC(_si.seasonStart.getUTCFullYear(), _si.seasonStart.getUTCMonth(), _si.seasonStart.getUTCDate());
      const LEN = _si.SEASON_LEN || 40;
      const fark = Math.floor((gunMs - basMs) / 86400000);
      const gun = ((fark % LEN) + LEN) % LEN + 1;
      const dk = d.getUTCHours() * 60 + d.getUTCMinutes();
      if (gun >= 34 && gun <= 40 && dk >= 11 * 60 + 45 && dk <= 15 * 60 + 30) {
        const yerel = (m) => { const x = new Date(gunMs + m * 60000); return String(x.getHours()).padStart(2,'0') + ':' + String(x.getMinutes()).padStart(2,'0'); };
        return { ok: false, reason: `Bu saatlerde milli maçlar oynanıyor (${yerel(11 * 60 + 45)}–${yerel(15 * 60 + 30)}). Başka bir saat seç.` };
      }
    }
  } catch(e) {}

  // 🆕 EN FAZLA 5 GÜN İLERİ TARİH
  const _MAX_ILERI_GUN = 5;
  const _bugun = new Date(); _bugun.setHours(0,0,0,0);
  const _hedef = new Date(t); _hedef.setHours(0,0,0,0);
  const _farkGun = Math.round((_hedef - _bugun) / 86400000);
  if (_farkGun > _MAX_ILERI_GUN) {
    return { ok: false, reason: `En fazla ${_MAX_ILERI_GUN} gün ileri tarihe hazırlık maçı ayarlayabilirsin.` };
  }

  // 🆕 AYNI GÜNDE EN FAZLA 1 HAZIRLIK MAÇI
  if (typeof _userTeam !== 'undefined' && _userTeam) {
    const sameDay = (a, b) => a.getFullYear() === b.getFullYear()
                           && a.getMonth() === b.getMonth()
                           && a.getDate() === b.getDate();
    const all = (typeof frmGetMatches === 'function') ? frmGetMatches() : [];
    const dayConflict = all.find(fm => {
      if (!fm) return false;
      if (fm.status === 'rejected' || fm.status === 'cancelled') return false;
      if (fm.played || fm.playedAt) return false;
      if (fm.fromTeam !== _userTeam.teamName && fm.toTeam !== _userTeam.teamName) return false;
      const fmDate = new Date(fm.dateTime);
      if (isNaN(fmDate.getTime())) return false;
      return sameDay(fmDate, new Date(t));
    });
    if (dayConflict) {
      const fmDate = new Date(dayConflict.dateTime);
      const hh = String(fmDate.getHours()).padStart(2,'0');
      const mm = String(fmDate.getMinutes()).padStart(2,'0');
      const otherTeam = (dayConflict.fromTeam === _userTeam.teamName) ? dayConflict.toTeam : dayConflict.fromTeam;
      return { ok: false, reason: `Bu gün için zaten bir hazırlık maçın var (${hh}:${mm} → ${otherTeam}). Günde en fazla 1 hazırlık maçı yapılabilir.` };
    }
  }

  const userBusy = frmGetUserBusyTimes();
  const oppBusy  = opponent ? frmGetTeamBusyTimes(opponent.team.name, opponent.cc, opponent.lg) : [];

  const fmt = (b) => {
    const at = new Date(b.t);
    const hh = String(at.getHours()).padStart(2,'0');
    const mm = String(at.getMinutes()).padStart(2,'0');
    const dd = String(at.getDate()).padStart(2,'0');
    const mo = String(at.getMonth()+1).padStart(2,'0');
    return `${dd}.${mo} ${hh}:${mm} → ${b.label}`;
  };

  for (const b of userBusy) {
    if (Math.abs(b.t - t) < FRM_BUFFER_MS) {
      return { ok: false, reason: `Senin maçınla çakışıyor: ${fmt(b)}. En az 1 saat boşluk gerekli.` };
    }
  }
  for (const b of oppBusy) {
    if (Math.abs(b.t - t) < FRM_BUFFER_MS) {
      return { ok: false, reason: `Rakip takımın maçıyla çakışıyor: ${fmt(b)}. En az 1 saat boşluk gerekli.` };
    }
  }
  return { ok: true };
}

// Modal
let _frmSelectedTeam = null;
let _frmFilterCC = '';
let _frmFilterTier = '';

function frmOpenModal() {
  let m = document.getElementById('frmModal');
  if (m) m.remove();
  m = document.createElement('div');
  m.id = 'frmModal';
  m.onclick = (e) => { if (e.target === m) frmCloseModal(); };

  // Default tarih: yarın 18:00
  const tomorrow = new Date(Date.now() + 24*60*60*1000);
  tomorrow.setHours(18,0,0,0);
  const dateStr = tomorrow.toISOString().slice(0,10);
  const timeStr = '18:00';

  // Ülkeleri (teams DB) hazırla
  const ccList = (true) ? _cftGetCountryCodes().sort((a,b) => _cftGetCountry(a).name.localeCompare(_cftGetCountry(b).name, 'tr')) : [];

  m.innerHTML = `
    <div class="frm2-card">
      <div class="frm2-header">
        <div class="frm2-icon">⚽</div>
        <div class="frm2-title-wrap">
          <div class="frm2-title">Hazırlık Maçı</div>
          <div class="frm2-subtitle">Rakip seç · tarih ve saat belirle</div>
        </div>
        <button class="frm2-close" onclick="frmCloseModal()" aria-label="Kapat">✕</button>
      </div>

      <div class="frm2-body">

        <div class="frm2-section-label">Rakip Filtresi</div>
        <div class="frm2-selects">
          <select id="frmCountrySel" class="frm2-select" onchange="frmOnCountryChange(this.value)">
            <option value="">🌍 Ülke seç…</option>
            ${ccList.map(cc => `<option value="${cc}">${_cftGetCountry(cc).flag}  ${_cftGetCountry(cc).name}</option>`).join('')}
          </select>
          <select id="frmTierSel" class="frm2-select" onchange="frmOnTierChange(this.value)" disabled>
            <option value="">🏆 Önce ülke seç</option>
          </select>
          <select id="frmTeamSel" class="frm2-select" onchange="frmOnTeamChange(this.value)" disabled>
            <option value="">⚽ Önce klasman seç</option>
          </select>
        </div>

        <div id="frmSelectedInfo" class="frm2-selected"></div>

        <div class="frm2-datetime">
          <div class="frm2-field large">
            <div class="frm2-section-label">Tarih</div>
            <input id="frmDate" class="frm2-input" type="date" value="${dateStr}" min="${new Date().toISOString().slice(0,10)}" max="${new Date(Date.now() + 5*86400000).toISOString().slice(0,10)}">
          </div>
          <div class="frm2-field">
            <div class="frm2-section-label">Saat</div>
            <input id="frmTime" class="frm2-input" type="time" value="${timeStr}">
          </div>
        </div>

        <div class="frm2-info">
          💡 Senin ve rakip takımın gerçek lig maçlarına en az <b>1 saat</b> boşluk olmalı.
          Günde <b>1</b> hazırlık maçı, en fazla <b>5 gün</b> ileri tarih. Hazırlık maçından <b>bilet geliri olmaz</b>.
          Karşı takım kaptanı kabul ederse maç planlanır.
        </div>
      </div>

      <div class="frm2-footer">
        <button class="frm2-btn frm2-btn-cancel" onclick="frmCloseModal()">İptal</button>
        <button id="frmSendBtn" class="frm2-btn frm2-btn-send" onclick="frmSendInvite()" disabled>Davet Gönder</button>
      </div>
    </div>
  `;
  document.body.appendChild(m);
  _frmSelectedTeam = null;
  _frmFilterCC = '';
  _frmFilterTier = '';
}

function frmCloseModal() {
  const m = document.getElementById('frmModal');
  if (m) m.remove();
  _frmSelectedTeam = null;
}

function frmOnCountryChange(cc) {
  _frmFilterCC = cc;
  _frmFilterTier = '';
  _frmSelectedTeam = null;
  const tierSel = document.getElementById('frmTierSel');
  const teamSel = document.getElementById('frmTeamSel');
  const info = document.getElementById('frmSelectedInfo');
  const btn = document.getElementById('frmSendBtn');

  if (info) info.classList.remove('show');
  if (btn) btn.disabled = true;

  if (!cc || false || !_cftGetCountry(cc)) {
    tierSel.innerHTML = '<option value="">🏆 Önce ülke seç</option>';
    tierSel.disabled = true;
    teamSel.innerHTML = '<option value="">⚽ Önce klasman seç</option>';
    teamSel.disabled = true;
    return;
  }
  const country = _cftGetCountry(cc);
  tierSel.innerHTML = '<option value="">🏆 Klasman seç…</option>' +
    (country.leagues || []).map(lg => `<option value="${lg.tier}">T${lg.tier} · ${lg.name}</option>`).join('');
  tierSel.disabled = false;
  teamSel.innerHTML = '<option value="">⚽ Önce klasman seç</option>';
  teamSel.disabled = true;
}

function frmOnTierChange(tier) {
  _frmFilterTier = tier;
  _frmSelectedTeam = null;
  const teamSel = document.getElementById('frmTeamSel');
  const info = document.getElementById('frmSelectedInfo');
  const btn = document.getElementById('frmSendBtn');

  if (info) info.classList.remove('show');
  if (btn) btn.disabled = true;

  if (!tier || !_frmFilterCC || false) {
    teamSel.innerHTML = '<option value="">⚽ Önce klasman seç</option>';
    teamSel.disabled = true;
    return;
  }
  const country = _cftGetCountry(_frmFilterCC);
  const lg = (country.leagues || []).find(l => String(l.tier) === String(tier));
  if (!lg) return;
  const userTeamName = _userTeam ? _userTeam.teamName : null;
  const userCC = _userTeam ? _userTeam.countryCode : null;
  const teams = lg.teams.filter(t => !(_frmFilterCC === userCC && t.name === userTeamName));
  teamSel.innerHTML = '<option value="">⚽ Takım seç…</option>' +
    teams.map(t => `<option value="${t.name}">${t.short} · ${t.name} (${t.city})</option>`).join('');
  teamSel.disabled = false;
}

function frmOnTeamChange(teamName) {
  if (!teamName || !_frmFilterCC || !_frmFilterTier) {
    _frmSelectedTeam = null;
    const info = document.getElementById('frmSelectedInfo');
    const btn = document.getElementById('frmSendBtn');
    if (info) info.classList.remove('show');
    if (btn) btn.disabled = true;
    return;
  }
  const country = _cftGetCountry(_frmFilterCC);
  const lg = (country.leagues || []).find(l => String(l.tier) === String(_frmFilterTier));
  const team = lg && lg.teams.find(t => t.name === teamName);
  if (!team) return;
  _frmSelectedTeam = { cc: _frmFilterCC, country, lg, team };

  const info = document.getElementById('frmSelectedInfo');
  if (info) {
    info.classList.add('show');
    info.innerHTML = `
      <div class="frm2-sel-label">Seçilen Rakip</div>
      <div class="frm2-sel-row">
        ${inlineBadge({tag:'div', cls:'frm2-sel-badge', team})}
        <div class="frm2-sel-meta">
          <div class="frm2-sel-name">${team.name}</div>
          <div class="frm2-sel-league">${country.flag} ${lg.name}</div>
        </div>
      </div>`;
  }
  const btn = document.getElementById('frmSendBtn');
  if (btn) btn.disabled = false;
}

function frmSendInvite() {
  if (!_frmSelectedTeam) return;
  const dateEl = document.getElementById('frmDate');
  const timeEl = document.getElementById('frmTime');
  if (!dateEl || !timeEl || !dateEl.value || !timeEl.value) {
    if (typeof showJoinToast === 'function') showJoinToast('⚠️ Tarih ve saat seçmelisin.');
    return;
  }
  const dt = dateEl.value + 'T' + timeEl.value + ':00';
  const conflict = frmCheckConflict(dt, _frmSelectedTeam);
  if (!conflict.ok) {
    if (typeof showJoinToast === 'function') showJoinToast('⚠️ ' + conflict.reason);
    return;
  }

  const r = _frmSelectedTeam;
  const id = 'frm_' + Date.now() + '_' + Math.random().toString(36).slice(2,7);
  const match = {
    id,
    fromTeam: _userTeam.teamName,
    fromCC: _userTeam.countryCode,
    fromCaptain: (typeof authUser !== 'undefined' && authUser && authUser.name) ? authUser.name : 'Kaptan',
    toTeam: r.team.name,
    toCC: r.cc,
    toLeague: r.lg.name,
    toBg: r.team.bg, toTc: r.team.tc, toShort: r.team.short,
    dateTime: dt,
    status: 'pending',
    createdAt: Date.now()
  };
  const all = frmGetMatches();
  all.push(match);
  frmSaveMatches(all);

  frmCloseModal();
  if (typeof showJoinToast === 'function') showJoinToast('✉️ Davet gönderildi! Karşı takım kaptanının cevabı bekleniyor…');

  // Bot otomatik cevap (3-6 saniye gecikmeyle, gerçekçi)
  const delayMs = 3000 + Math.floor(Math.random() * 3500);
  setTimeout(() => frmBotRespond(id), delayMs);
}

// 🆕 Hazırlık maçı sonuçlarını match_state'ten (Supabase) friendly_matches'a senkron et
// Kullanıcı maç ekranını kapattıysa bile (cron tick maçı bitirdi):
// Bu fonksiyon _matchStateCache'ten finished friendly maçlarını bulup
// friendly_matches.match_data'ya played/hs/as/events yansıtır.
function frmEnsurePlayed() {
  // 🆕 Edge Function (tick-matches) hazırlık maçlarını match_state üzerinden oynar.
  // Burada match_state'te status='finished' olan hazırlık maçlarını bulup
  // friendly_matches.match_data'ya yansıtırız (played, hs, as, events).
  //
  // ⚠️ BUG FIX: _liveMatchCache sadece running+scheduled+enc çekiyor; finished maçlar yok.
  //   Bu yüzden bitmiş hazırlık maçları sonuçlar sayfasında görünmüyordu.
  //   Çözüm: _matchStateCache'i (genel cache, tüm statüler var) öncelikli kaynak yap.
  if (!Array.isArray(_frmMatchesCache) || _frmMatchesCache.length === 0) return;
  let dirty = false;
  for (const fm of _frmMatchesCache) {
    if (!fm || fm.played) continue;
    if (fm.status !== 'accepted') continue;
    // match_state'te bu hazırlık maçının satırını ara — match_key 'friendly_frm_<id>' formatında
    const expectedKey = 'friendly_' + fm.id;
    // Öncelik: _matchStateCache (finished dahil tüm statüler)
    let ms = null;
    if (typeof _matchStateCache === 'object' && _matchStateCache && _matchStateCache.byKey) {
      ms = _matchStateCache.byKey[expectedKey] || null;
    }
    // Yedek: _liveMatchCache (eski canlı cache; sadece running+scheduled)
    if (!ms && typeof _liveMatchCache === 'object' && _liveMatchCache) {
      ms = _liveMatchCache[expectedKey] || null;
    }
    // 🆕 Sunucuda satırı yoksa ve saati 3 saatten fazla geçmişse: OYNANMIŞ say.
    //   Aksi halde eski maç sonsuza dek "bekleyen maç" kalıp her turda yeniden
    //   kurulmaya çalışıyor; ana sayfa da onu göstermeye çalışırken bozuluyordu.
    if (!ms) {
      const _ko = fm.dateTime ? new Date(fm.dateTime).getTime() : 0;
      if (_ko && (Date.now() - _ko) > 3 * 3600 * 1000) {
        fm.played = true;
        fm.playedAt = _ko;
        if (typeof fm.hs !== 'number') { fm.hs = 0; fm.as = 0; }
        dirty = true;
      }
      continue;
    }
    if (ms.status !== 'finished') continue;
    // Bitmiş — friendly_matches'a yansıt.
    //   Not: _matchStateCache.byKey içindeki obje home_score/away_score değil hs/as taşıyor
    //   olabilir (mapping farklı). Her iki alanı da kontrol et.
    fm.played = true;
    fm.hs = (ms.home_score ?? ms.hs ?? 0);
    fm.as = (ms.away_score ?? ms.as ?? 0);
    fm.events = Array.isArray(ms.events) ? ms.events : [];
    fm.playedAt = ms.last_tick_at ? new Date(ms.last_tick_at).getTime()
                  : (ms.kickoff_at ? new Date(ms.kickoff_at).getTime() : Date.now());
    dirty = true;
  }
  if (dirty) {
    try { frmSaveMatches(_frmMatchesCache.slice()); } catch(e) { console.warn('[frmEnsurePlayed] save hata:', e); }
  }
}


function frmBotRespond(matchId) {
  if (typeof FRM_AKTIF !== 'undefined' && !FRM_AKTIF) return;   // 🔴 kapalı
  const all = frmGetMatches();
  const idx = all.findIndex(m => m.id === matchId);
  if (idx === -1) return;
  const match = all[idx];
  if (match.status !== 'pending') return;
  // 🆕 GÜVENLİK: yalnızca BENİM takımımın gönderdiği davete bot cevabı üretilir.
  //   (Aksi halde başka oyuncuların davetleri de bu istemcide cevaplanıp
  //    gelen kutuma bildirim olarak düşüyordu.)
  try {
    const _ben = (typeof _userTeam !== 'undefined' && _userTeam && _userTeam.teamName) || null;
    if (!_ben || match.fromTeam !== _ben) return;
  } catch(e) { return; }
  // 🆕 SAATİ GEÇMİŞ DAVET → bildirim üretmeden kapat
  try {
    const _ko2 = match.dateTime ? new Date(match.dateTime).getTime() : 0;
    if (_ko2 && (Date.now() - _ko2) > 3 * 3600 * 1000) {
      match.status = 'rejected';
      match.played = true;
      match.playedAt = _ko2;
      all[idx] = match;
      frmSaveMatches(all);
      return;
    }
  } catch(e) {}
  // 🆕 AYNI DAVETE İKİNCİ KEZ CEVAP YOK — sunucuya yazma başarısız olsa bile
  //   bu oturumda bir daha cevap üretilmez (bildirim tekrarının kök nedeni).
  if (!window._frmResponded) window._frmResponded = {};
  if (window._frmResponded[matchId]) return;
  window._frmResponded[matchId] = true;

  // %75 onay, %25 ret
  const accept = Math.random() < 0.75;
  match.status = accept ? 'accepted' : 'rejected';
  match.respondedAt = Date.now();
  all[idx] = match;
  frmSaveMatches(all);

  // 🆕 match_state senkronizasyonu — kabul → scheduled satır, ret → satır silme
  if (accept) {
    _frmUpsertMatchState(match);
  } else {
    _frmDeleteMatchState(match.id);
  }

  // İnbox'a cevap mesajı düşür
  const dt = new Date(match.dateTime);
  const dateStr = String(dt.getDate()).padStart(2,'0') + '.' + String(dt.getMonth()+1).padStart(2,'0') + '.' + dt.getFullYear();
  const timeStr = String(dt.getHours()).padStart(2,'0') + ':' + String(dt.getMinutes()).padStart(2,'0');

  const subject = accept ? '✅ Hazırlık Maçı Kabul Edildi' : '❌ Hazırlık Maçı Reddedildi';
  const bodies_accept = [
    `Selam! ${match.toTeam} olarak ${dateStr} ${timeStr}'deki hazırlık maçı teklifini kabul ediyoruz. Hazırız!`,
    `Davet için teşekkürler. ${dateStr} tarihinde ${timeStr}'de sahada görüşürüz.`,
    `${match.toTeam} kadromuz hazır. ${dateStr} ${timeStr}'de iyi bir maç çıkaralım.`
  ];
  const bodies_reject = [
    `Maalesef ${dateStr} ${timeStr}'de takvimimiz uygun değil. Başka bir zaman tekrar deneyebilirsin.`,
    `Davet için teşekkürler ama o tarihte hazırlık programımız dolu. Bir dahaki sefere.`,
    `${match.toTeam} olarak şu an hazırlık maçı için müsait değiliz.`
  ];
  const body = accept ? bodies_accept[Math.floor(Math.random()*bodies_accept.length)]
                      : bodies_reject[Math.floor(Math.random()*bodies_reject.length)];

  const msg = {
    id: 'msg_' + matchId,
    from: match.toTeam + ' Kaptanı',
    fromAvatar: '🤖',
    type: 'friendly_response',
    subject,
    body,
    time: 'Şimdi',
    read: false,
    thread: [],
    friendlyData: {
      matchId, status: match.status,
      opponent: match.toTeam, opponentCC: match.toCC,
      opponentBg: match.toBg, opponentTc: match.toTc, opponentShort: match.toShort,
      league: match.toLeague,
      dateTime: match.dateTime, dateStr, timeStr
    }
  };
  const msgs = getInboxMsgs();
  // 🆕 TEKRAR KORUMASI — aynı maç için gelen kutusunda zaten mesaj varsa ekleme
  if (!msgs.some(x => x && (x.id === msg.id ||
      (x.friendlyData && x.friendlyData.matchId === matchId)))) {
    msgs.unshift(msg);
    saveInboxMsgs(msgs);
  }
  if (typeof inboxUpdateBadge === 'function') inboxUpdateBadge();
  // 🆕 Onaylandıysa: ana sayfa "yaklaşan maç" paneli ve takım fikstür sekmesini yenile
  if (accept) {
    if (typeof renderHomeNextMatch === 'function') {
      try { renderHomeNextMatch(); } catch(e){}
    }
    const fixPane = document.getElementById('team-fixture');
    if (fixPane && fixPane.style.display !== 'none' && typeof renderFixture === 'function') {
      try { renderFixture(); } catch(e){}
    }
  }
  if (typeof showJoinToast === 'function') {
    showJoinToast(accept ? `✅ ${match.toTeam} davetini kabul etti!` : `❌ ${match.toTeam} daveti reddetti.`);
  }
}

// ═══════════ 910 — TAKIM ADI UZANTISI (FK, FC, United, -spor …) ═══════════
//   Takımın asıl adı (lig, maç, transfer, kayıt anahtarı) DEĞİŞMEZ; uzantı yalnız ekranda adın
//   başına / sonuna / bitişiğine eklenir. Kaptan hazır listeden seçer (elle yazılamaz).
//   İlk seçim ücretsiz, sonraki her değişiklik 150 💎 takım kasasından — sunucu: takim_ad_ek_sec.
//   Ekranda: tek başına duran takım adı metinleri (i18n motoru gibi) gözlemciyle görünen ada çevrilir.
