// 🆕 Kullanıcının bu sezonki Avrupa kupasını dinamik döndürür
// Sezon 2+: _userTeam.europeanCup (processSeasonEnd tarafından set edilir)
// Sezon 1: teams DB'deki takım sıralamasına göre (1-2 → champ, 3-4 → eli, 5-6 → conv, 7+ → null)
function getUserTurnuva() {
  if (typeof _userTeam === 'undefined' || !_userTeam) return null;
  // 1. Önce mevcut alanı kontrol et (Sezon 2+ için kalıcı atama)
  if (_userTeam.europeanCup) return _userTeam.europeanCup;

  // 🆕 SEZON 1 ÖZEL: teams DB Süper Lig sırasına göre dinamik ata
  try {
    const info = (typeof getSeasonInfo === 'function') ? getSeasonInfo() : null;
    if (!info || info.season !== 1) return null;
    if (false) return null;
    const cc = _userTeam.countryCode;
    const country = _cftGetCountry(cc);
    if (!country || !country.leagues) return null;
    // Sadece Süper Lig'deyse (tier 0)
    if (getUserRealTierIdx() !== 0) return null;
    const tier1 = country.leagues[0];
    if (!tier1 || !tier1.teams) return null;
    const idx = tier1.teams.findIndex(t => t.name === _userTeam.teamName);
    if (idx < 0) return null;
    // 0-1 → champ, 2-3 → eli, 4-5 → conv, 6+ → yok
    if (idx <= 1) return 'chm';
    if (idx <= 3) return 'eli';
    if (idx <= 5) return 'con';
    return null;
  } catch(e) { return null; }
}

// ─── Ana hesaplama: sezon ve gün ───
// 🆕 SEASON_EPOCH ve SEASON_LEN, _autoResetIfNeeded'den ÖNCE init edildi (TDZ önlemi).
// Buraya yorum bırakıyoruz; gerçek declaration yukarıda (33xxx civarı).

// 🆕 ═══════════════════════════════════════════════════════════════════════
// MAÇ SÜRESİ — gerçek-zamanlı oynanma süresi (5 dk + 100 sn devre arası + 5 dk)
// Maçların sonuçları önceden BELLİ DEĞİL: sadece kickoff + bu süre geçtikten
// sonra simülasyon hesaplanır ve sonuç görünür. Gate buradan çağrılan
// _isMatchEnded(kickoffMs) ile uygulanır — fikstür/lig/sonuçlar hepsinde.
// ═══════════════════════════════════════════════════════════════════════
const MATCH_PLAY_DURATION_MS = 12 * 60 * 1000; // ~12 dk (5+100sn+5)
function _isMatchEnded(kickoffMs) {
  if (typeof kickoffMs !== 'number' || isNaN(kickoffMs) || kickoffMs <= 0) return false;
  return Date.now() >= (kickoffMs + MATCH_PLAY_DURATION_MS);
}
function _isMatchLive(kickoffMs) {
  if (typeof kickoffMs !== 'number' || isNaN(kickoffMs) || kickoffMs <= 0) return false;
  const now = Date.now();
  return now >= kickoffMs && now < (kickoffMs + MATCH_PLAY_DURATION_MS);
}

function getSeasonInfo() {
  // 🆕 UTC BAZLI HESAP — multiplayer için zorunlu.
  //   Local timezone kullanılırsa Türkiye'deki (UTC+3) user ile Almanya'daki (UTC+1)
  //   user farklı "dayInSeason" görür → fikstür çakışır. UTC ile tüm dünya aynı.
  //   SEASON_EPOCH UTC midnight olarak saklanır (Supabase ISO Z formatında geldiği gibi).
  const nowMs = Date.now();
  // UTC midnight'a indirgenmiş bugün (UTC günü)
  const _t = new Date();
  const todayUtcMs = Date.UTC(_t.getUTCFullYear(), _t.getUTCMonth(), _t.getUTCDate());
  const epochUtcMs = Date.UTC(SEASON_EPOCH.getUTCFullYear(), SEASON_EPOCH.getUTCMonth(), SEASON_EPOCH.getUTCDate());
  const diffMs = todayUtcMs - epochUtcMs;

  // Pre-season: sistem henüz başlamadı
  if(diffMs < 0) {
    const daysToStart = Math.ceil(-diffMs / 86400000);
    return {
      season: 1, dayInSeason: 0,
      seasonStart: new Date(SEASON_EPOCH),
      SEASON_LEN, preSeason: true, daysToStart
    };
  }

  const diffDays = Math.floor(diffMs / 86400000);
  const season   = Math.floor(diffDays / SEASON_LEN) + 1;
  const dayInSeason = (diffDays % SEASON_LEN) + 1; // 1-40

  const seasonStart = new Date(SEASON_EPOCH);
  seasonStart.setUTCDate(SEASON_EPOCH.getUTCDate() + (season-1)*SEASON_LEN);

  return { season, dayInSeason, seasonStart, SEASON_LEN, preSeason: false };
}

// Türkçe tarih formatlayıcı
const _DAYS_TR_FULL   = ['Pazar','Pazartesi','Salı','Çarşamba','Perşembe','Cuma','Cumartesi'];
const _MONTHS_TR_FULL = ['Ocak','Şubat','Mart','Nisan','Mayıs','Haziran','Temmuz','Ağustos','Eylül','Ekim','Kasım','Aralık'];
function formatTrDate(d) {
  return `${_DAYS_TR_FULL[d.getDay()]}, ${d.getDate()} ${_MONTHS_TR_FULL[d.getMonth()]} ${d.getFullYear()}`;
}


// ═══════════════════════════════════════════════════════════════════
//  TRANSFER DÖNEMİ HELPER'LARI
// ═══════════════════════════════════════════════════════════════════
// SEASON_TEMPLATE'deki `type:'break'` olarak işaretli günler transfer dönemidir:
//   - Ara Transfer Dönemi: 16, 17, 18. günler
//   - Sezon Arası Transfer: 34-40. günler
//
// Kural:
//   - Sözleşmeli oyuncu (başka takımda) → SADECE transfer döneminde transfer
//   - Serbest oyuncu (takımsız)        → Her zaman bir takıma katılabilir
//
// Bu kontrol joinTeamDirect üzerinden yapılır (kullanıcının başka takıma geçişi).
// ═══════════════════════════════════════════════════════════════════

// Bugün transfer dönemi mi?
function isTransferWindowOpen() {
  if (typeof getSeasonInfo !== 'function') return true; // güvenlik: sezon yoksa engelleme yapma
  const info = getSeasonInfo();
  if (!info || info.preSeason) return false;
  if (typeof SEASON_TEMPLATE === 'undefined') return false;
  const events = SEASON_TEMPLATE[info.dayInSeason] || [];
  return events.some(e => e && e.type === 'break');
}

// Bir sonraki transfer dönemini bul → { startDay, endDay, label }
// Şu an transfer döneminin İÇİNDEYSE: o dönemin sonunu döndürür.
function getNextTransferWindowInfo() {
  if (typeof SEASON_TEMPLATE === 'undefined') return null;
  if (typeof getSeasonInfo !== 'function') return null;
  const info = getSeasonInfo();
  const today = info ? info.dayInSeason : 1;

  // SEASON_TEMPLATE içinde 'break' günlerini grupla → ardışık aralıklar
  const breakDays = [];
  for (let d = 1; d <= 40; d++) {
    const evs = SEASON_TEMPLATE[d] || [];
    if (evs.some(e => e && e.type === 'break')) breakDays.push(d);
  }
  if (!breakDays.length) return null;

  // Ardışık grupları çıkar
  const windows = [];
  let cur = [breakDays[0]];
  for (let i = 1; i < breakDays.length; i++) {
    if (breakDays[i] === breakDays[i-1] + 1) cur.push(breakDays[i]);
    else { windows.push(cur); cur = [breakDays[i]]; }
  }
  windows.push(cur);

  // Bugünden itibaren ilk açık dönemi bul
  for (const w of windows) {
    if (today <= w[w.length - 1]) {
      const evs = SEASON_TEMPLATE[w[0]] || [];
      const breakEv = evs.find(e => e && e.type === 'break');
      return {
        startDay: w[0],
        endDay:   w[w.length - 1],
        label:    (breakEv && breakEv.label) || 'Transfer Dönemi',
        currentDay: today,
        isOpen: today >= w[0] && today <= w[w.length - 1]
      };
    }
  }

  // Hepsi geçtiyse → bir sonraki sezonun ilk transfer dönemi
  const first = windows[0];
  const evs = SEASON_TEMPLATE[first[0]] || [];
  const breakEv = evs.find(e => e && e.type === 'break');
  return {
    startDay: first[0],
    endDay:   first[first.length - 1],
    label:    ((breakEv && breakEv.label) || 'Transfer Dönemi') + ' (sonraki sezon)',
    currentDay: today,
    isOpen: false
  };
}

// Transfer dönemi engelleme — ortak yardımcı.
// Çağrı: const r = _enforceTransferWindow('Teklif'); if(r.blocked) return;
// Kullanıcıya kapalı olduğunu söyleyen bir alert + toast gösterir.
function _enforceTransferWindow(actionLabel) {
  return { blocked: false };   // 963 — transfer dönemi yok
  if (typeof isTransferWindowOpen === 'function' && isTransferWindowOpen()) {
    return { blocked: false };
  }
  const next = (typeof getNextTransferWindowInfo === 'function') ? getNextTransferWindowInfo() : null;
  const info = (typeof getSeasonInfo === 'function') ? getSeasonInfo() : null;
  const lbl = actionLabel || 'Transfer';

  // 🆕 Şık modal (alert yerine)
  showInfoModal({
    icon: '🚫',
    iconColor: '#ef4444',
    title: 'Transfer Dönemi Kapalı',
    subtitle: `${lbl} işlemi sadece transfer dönemlerinde yapılabilir`,
    body: `
      <div class="info-modal-rows">
        <div class="info-modal-row">
          <div class="info-modal-row-ic">📆</div>
          <div class="info-modal-row-body">
            <div class="info-modal-row-lbl">Ara Transfer</div>
            <div class="info-modal-row-val">16-18. günler</div>
          </div>
        </div>
        <div class="info-modal-row">
          <div class="info-modal-row-ic">📆</div>
          <div class="info-modal-row-body">
            <div class="info-modal-row-lbl">Sezon Arası</div>
            <div class="info-modal-row-val">34-40. günler</div>
          </div>
        </div>
      </div>
      <div class="info-modal-divider"></div>
      <div class="info-modal-rows">
        ${info ? `
        <div class="info-modal-row info-modal-row-flat">
          <div class="info-modal-row-body">
            <div class="info-modal-row-lbl">Bugün</div>
            <div class="info-modal-row-val">${info.dayInSeason}. gün</div>
          </div>
        </div>` : ''}
        ${next ? `
        <div class="info-modal-row info-modal-row-flat info-modal-row-highlight">
          <div class="info-modal-row-body">
            <div class="info-modal-row-lbl">Sonraki Dönem</div>
            <div class="info-modal-row-val">${next.label} · ${next.startDay}-${next.endDay}. günler</div>
          </div>
        </div>` : ''}
      </div>
      <div class="info-modal-note">
        💡 Serbest oyuncular bu kuraldan etkilenmez — her zaman katılabilir.
      </div>
    `
  });
  return { blocked: true, message: 'Transfer dönemi kapalı.' };
}

