function _cssBirKez957(id, css) {   // 957
  if (document.getElementById(id)) return;
  const st = document.createElement('style'); st.id = id; st.textContent = css; (document.body || document.head).appendChild(st);
}
function showInfoModal(opts) {
  opts = opts || {};
  const existing = document.getElementById('cftInfoModal');
  if (existing) existing.remove();
  const modal = document.createElement('div');
  modal.id = 'cftInfoModal';
  const icon = opts.icon || 'ℹ️';
  const iconColor = opts.iconColor || '#5fb8ff';
  const title = opts.title || 'Bilgi';
  const subtitle = opts.subtitle || '';
  const body = opts.body || '';
  const btnText = opts.btnText || 'Anladım';

  // 957 — stil kalıcı (ilk açılışta bir kez); renk CSS değişkenleriyle. Eskiden her açılış/kapanışta <style> eklenip çıkıyordu (2 tam belge stil hesabı)
  _cssBirKez957('cftInfoCss', _INFO_CSS957);
  modal.style.cssText = '--ic:' + iconColor + ';--ic11:' + iconColor + '11;--ic22:' + iconColor + '22;--ic33:' + iconColor + '33;--ic55:' + iconColor + '55;--ic77:' + iconColor + '77;--icdd:' + iconColor + 'dd;';
  modal.innerHTML = `
    <div class="info-modal-box">
      <div class="info-modal-header">
        <div class="info-modal-icon-wrap">${icon}</div>
        <div class="info-modal-title">${title}</div>
        ${subtitle ? `<div class="info-modal-subtitle">${subtitle}</div>` : ''}
        <button class="info-modal-close" onclick="closeInfoModal()" aria-label="Kapat">✕</button>
      </div>
      <div class="info-modal-body">${body}</div>
      <div class="info-modal-footer">
        <button class="info-modal-btn" onclick="closeInfoModal()">${btnText}</button>
      </div>
    </div>`;
  modal.addEventListener('click', (e) => { if (e.target === modal) closeInfoModal(); });
  document.body.appendChild(modal);
}

function closeInfoModal() {
  const m = document.getElementById('cftInfoModal');
  if (m) m.remove();
}


// ──────── Ana sayfa oyuncu sayacı (gerçek sayım) ────────
// Toplam: teams DB'deki tüm takımlar × 15 oyuncu/takım (her takım 15 bot ile doldurulur)
// Çevrimiçi: yalnızca gerçek kullanıcı (kullanıcının kendisi). Botlar online sayılmaz.
// 🆕 Heartbeat: kullanıcının last_seen'ini Supabase'te güncelle
async function pingLastSeen() {
  try {
    if (!window.sb || !window.sb.auth) return;
    // 956 — tek presence yazıcısı (_presenceYaz): kimlik yerel oturumdan; az önce yazıldıysa o yazım beklenir (getUser + ikinci PATCH yok)
    if (typeof window._presenceYaz === 'function') { await window._presenceYaz(true); return; }
    const { data: { user } } = await window.sb.auth.getUser();
    if (!user) return;
    await window.sb.from('players')
      .update({ last_seen: new Date().toISOString() })
      .eq('user_id', user.id);
  } catch(e) {}
}

// RAM cache (Supabase çağrısı periyodik, her render'da yeniden çağırma)
let _onlineCache = { total: 0, online: 0, list: [], ts: 0 };

async function fetchOnlineStats() {   // 798
  if (!window.sb) return;
  try {
    const { data, error } = await window.sb.rpc('oyuncu_sayaci');
    if (!error && data && typeof data.toplam === 'number') {
      _onlineCache.total = data.toplam; _onlineCache.online = Number(data.cevrimici) || 0; _onlineCache.ts = Date.now();
      window._olcSayacHata = '';
      updateHomePlayersCounter(); _onlineDeneme = 0;
      return;
    }
    window._olcSayacHata = String((error && (error.message || error.code)) || 'veri yok').slice(0, 120);
  } catch (e) { window._olcSayacHata = String(e && e.message || e).slice(0, 120); }
  return _onlineListeYukle();   // sunucu fonksiyonu yanıt vermezse eski yol
}
async function _onlineListeYukle() {
  if (!window.sb) return;
  try {
    // Toplam (tek SELECT count)
    // 🆕 561 — toplam oyuncu sayısı nadiren değişir: 10 dk önbellek · 753: yalnız gerçek kullanıcılar
    let total = _onlineCache.total || 0;
    if (!_onlineCache.totalTs || Date.now() - _onlineCache.totalTs > 600000) {
      const { count: _tc, error: _tcErr } = await window.sb.from('players')
        .select('id', { count: 'exact', head: true }).eq('is_bot', false).not('user_id', 'is', null);
      if (!_tcErr && typeof _tc === 'number') { total = _tc; _onlineCache.totalTs = Date.now(); }
    }
    // Online kullanıcılar (son 5 dakika, sadece gerçek kullanıcılar)
    const fiveMinAgo = new Date(Date.now() - 5*60*1000).toISOString();
    const { data: list, error } = await window.sb.from('players')
      .select('id,user_id,name,team_name,country_code,nation,pos,pos_group,sub_pos, ek_mevki, ozel_yetenek, ozel_aktif,last_seen,avatar_id,gender')
      .not('user_id', 'is', null)
      .gte('last_seen', fiveMinAgo)
      .order('last_seen', { ascending: false })
      .limit(200);
    if (error) { console.warn('[online] hata:', error.message); if (total) { _onlineCache.total = total; updateHomePlayersCounter(); } _onlineTekrar(); return; }
    // Profillerden username + avatar_id çek
    let enriched = list || [];
    if (enriched.length > 0) {
      const uids = enriched.map(p => p.user_id);
      const { data: profs } = await window.sb.from('profiles')
        .select('id,username').in('id', uids);
      const pmap = {};
      (profs || []).forEach(pr => { pmap[pr.id] = pr; });
      enriched = enriched.map(p => ({
        ...p,
        username: pmap[p.user_id]?.username || '',
        avatar_id: p.avatar_id || null,
        position: p.pos_group || null
      }));
    }
    _onlineCache = {
      listTs: Date.now(),
      totalTs: _onlineCache.totalTs || 0,
      total: total || 0,
      online: enriched.length,
      list: enriched,
      ts: Date.now()
    };
    if (typeof updateHomePlayersCounter === 'function') updateHomePlayersCounter();
    if (!total) _onlineTekrar(); else _onlineDeneme = 0;
  } catch(e) { console.warn('[online] hata:', e); _onlineTekrar(); }
}
// 797 — açılışta istek düşerse sayaç 0'da kalmasın (5, 10, 15 … sn sonra, en çok 6 kez)
let _onlineDeneme = 0, _onlineTekrarT = null;
function _onlineTekrar() {
  if (_onlineTekrarT || _onlineDeneme >= 6) return;
  _onlineDeneme++;
  _onlineTekrarT = setTimeout(() => { _onlineTekrarT = null; fetchOnlineStats(); }, 5000 * _onlineDeneme);
}

function updateHomePlayersCounter() {
  const totalEl = document.getElementById('hmPlayersTotal');
  const onlineEl = document.getElementById('hmPlayersOnlineNum');
  if(!totalEl && !onlineEl) return;

  function fmt(n) {
    if(n >= 1000) return n.toLocaleString('tr-TR');
    return String(n);
  }
  if(totalEl) totalEl.textContent = fmt(_onlineCache.total);
  if(onlineEl) onlineEl.textContent = fmt(_onlineCache.online);
}

