async function showOnlinePlayersModal() {
  if (!_onlineCache.listTs || Date.now() - _onlineCache.listTs > 30000) { try { await _onlineListeYukle(); } catch (e) {} }   // 798 — liste açılınca çekilir
  const existing = document.getElementById('onlinePlayersModal');
  if (existing) existing.remove();

  const list = _onlineCache.list || [];

  function avatarHtml(p) {
    if (typeof getAvatarEmoji === 'function') {
      return getAvatarEmoji(p.avatar_id, p.position);
    }
    return '🧑';
  }

  function posBadge(p) {
    const sub = subPosOf(p);
    const colors = { GK:'#f59e0b', DEF:'#3b82f6', MID:'#22c55e', FWD:'#ef4444' };
    const c = colors[SUBPOS_GROUP[sub]] || '#888';
    return `<span class="mv-sira" data-noi18n>${glMevkiEt(p)}</span>`;   // 962 — her mevki ayrı etiket
  }

  const rowsHtml = list.length === 0
    ? `<div style="text-align:center;padding:40px 20px;color:#666">
         <div style="font-size:36px;opacity:.4;margin-bottom:8px">⚽</div>
         <div style="font-family:Twemoji Country Flags,'Barlow Condensed',sans-serif;font-size:14px;letter-spacing:.5px">ŞU ANDA KIMSE ÇEVRIMIÇI DEĞİL</div>
       </div>`
    : list.map(p => {
        const team = p.team_name || 'SERBEST';
        const teamColor = p.team_name ? '#fff' : '#ff6d00';
        const uname = p.username ? `@${p.username}` : '';
        return `<div class="opm-row" onclick="_opmProfil('${String(p.user_id || '').replace(/[^0-9a-f-]/gi, '')}')">
          <div class="opm-avatar-wrap">
            <div class="opm-avatar">${avatarHtml(p)}</div>
            <span class="opm-dot"></span>
          </div>
          <div class="opm-info">
            <div class="opm-top">
              <span class="opm-flag">${p.nation || '🏳️'}</span>
              <span class="opm-name">${p.name || 'Oyuncu'}</span>${_cinsIk(p)}
              ${posBadge(p)}
            </div>
            <div class="opm-bottom">
              <span class="opm-team" style="color:${teamColor}">${team}</span>
              ${uname ? `<span class="opm-uname">${uname}</span>` : ''}
            </div>
          </div>
        </div>`;
      }).join('');

  const modal = document.createElement('div');
  modal.id = 'onlinePlayersModal';
  _cssBirKez957('opmCss', _OPM_CSS957);   // 957 — stil kalıcı (bir kez)
  modal.innerHTML = `
    <div class="opm-box">
      <div class="opm-header">
        <div class="opm-title"><span class="opm-title-dot"></span>Çevrimiçi Oyuncular</div>
        <div class="opm-subtitle">${list.length} oyuncu sahada</div>
        <button class="opm-close" id="onlineModalClose">✕</button>
      </div>
      <div class="opm-list">${rowsHtml}</div>
    </div>`;
  // 738 — açıkken arkadaki sayfa kaymaz
  const kapat = () => { modal.remove(); document.documentElement.classList.remove('opm-kilit'); };
  modal.addEventListener('click', (e) => { if (e.target === modal) kapat(); });
  modal.querySelector('#onlineModalClose').addEventListener('click', kapat);
  document.body.appendChild(modal);
  document.documentElement.classList.add('opm-kilit');
}

// 936 — çevrim içi listesinden oyuncu profiline (kendisiyse kendi oyuncu sayfası)
function _opmProfil(uid) {
  const m = document.getElementById('onlinePlayersModal'); if (m) m.remove();
  document.documentElement.classList.remove('opm-kilit');
  if (!uid) return;
  if (typeof authUser !== 'undefined' && authUser && authUser.id === uid) { showPage('player', findNavBtn('player')); return; }
  if (typeof jrProfilAc === 'function') jrProfilAc(uid);
}

// Sayfa açılışında ilk fetch + 60sn'de bir tekrar (heartbeat + sayaç tazeleme)
// 🆕 Açılışta splash öncesi zaten çekiliyor. Bu, ağ yavaş olduğunda
//    (6 sn sınırına takılıp geçildiyse) devreye giren yedek tazeleme.
//    Sıra önemli: önce kendini çevrimiçi işaretle, sonra listeyi çek.
// 🆕 561 — last_seen artık YALNIZ 180 sn'lik presence yazıcısı ile yazılıyor
//   (_updateLastSeen). Buradaki 60 sn'lik ikinci yazıcı her dakika players satırını
//   güncelleyip takım arkadaşlarının ekranında ağır kadro yenilemesini tetikliyordu;
//   ayrıca her seferinde auth sunucusuna getUser() isteği atıyordu.
//   Çevrimiçi sayacı yalnız ana sayfa açıkken tazelenir.
setTimeout(async () => {
  // 956 — açılış az önce (30 sn) kendini yazdı ve sayacı çektiyse yedek atlanır
  const _ps956 = window._presenceSon956;
  if (_ps956 && Date.now() - _ps956.t < 30000 && _onlineCache.ts && Date.now() - _onlineCache.ts < 30000) return;
  try { if (typeof window._presenceYaz === 'function') await window._presenceYaz(true); } catch(e) {}
  try { await fetchOnlineStats(); } catch(e) {}
}, 8000);
setInterval(async () => {
  if (document.hidden) return;
  const _ap = document.querySelector('.page.active');
  if (!_ap || _ap.id !== 'page-home') return;
  try { await fetchOnlineStats(); } catch(e) {}
}, 60000);


// 🆕 INBOX POLL — realtime yedeği. Sadece DEĞİŞİKLİK olunca render eder (WhatsApp gibi).
// İnbox AÇIKKEN 2sn, KAPALIYKEN 8sn kontrol; veri aynıysa DOM'a hiç dokunmaz.
let _inboxPollCnt = 0, _inboxPollSon = 0;   // 956 — _inboxPollSon: anlık kanal sağlıklıyken son yoklama anı
setInterval(() => {
  if (document.hidden) return;
  if (typeof _inboxLoadFromServer !== 'function') return;
  const ov = document.getElementById('inboxOverlay');
  const isOpen = ov && ov.classList.contains('open');
  _inboxPollCnt++;
  let _hafif;
  if (window._rtKutuOk === true) {
    // 956 — anlık kanal (rt-my-inbox 'kutu' yayını her değişikliği zaten getiriyor) sağlıklıyken yoklama yalnız yedek:
    //   açıkken ~15 sn, kapalıyken 4 dk'da bir hafif kontrol (updated_at); 10 dk'da bir güvenlik için tam okuma.
    const _s = Date.now();
    if (_s - Math.max(_inboxPollSon, window._inboxSonOkuma || 0) < (isOpen ? 15000 : 240000)) return;
    _hafif = _s - (window._inboxSonTam || 0) < 600000;
  } else {
    // 🆕 Açıkken her tur (2sn), KAPALIYKEN her 15. tur (30sn).
    //   Eskiden kapalıyken 8sn'de bir sorgu atıyordu — boşta dururken bile
    //   dakikada ~8 istek demekti (pil + ısınma).
    if (!isOpen && (_inboxPollCnt % 15 !== 0)) return;
    // 🆕 563 — açıkken ara turlar hafif (yalnız updated_at), 15 turda bir tam okuma
    // 899 — kapalıyken de hafif (değiştiyse tam okuma); 150 turda (5 dk) bir tam okuma
    _hafif = isOpen ? (_inboxPollCnt % 15 !== 0) : (_inboxPollCnt % 150 !== 0);
  }
  _inboxPollSon = Date.now();
  _inboxLoadFromServer(_hafif).then(() => {
    if (typeof inboxUpdateBadge === 'function') inboxUpdateBadge();
    // 🆕 Veri değişmediyse hiçbir şey yapma — liste/sohbet olduğu gibi kalır
    if (!window._inboxChanged) return;
    if (isOpen) {
      if (_inboxView === 'detail' && _inboxCurrentMsg) {
        const fresh = getInboxMsgs().find(m => m.id === _inboxCurrentMsg.id);
        if (fresh) { _inboxCurrentMsg = fresh; inboxRenderDetail(fresh); }
      } else if (_inboxView === 'list' && typeof inboxRenderList === 'function') {
        inboxRenderList();
      }
    }
  }).catch(()=>{});
}, 2000);

