// ══ HOME — 4) Etkinlik Feed (canlılık hissi için bot haberleri) ══
//
// Tasarım: 8-10 haber kartı, her gün farklı (gün seed'i ile deterministik).
// Şablonlar: transfer, lig, turnuva, stadyum, kullanıcı eylemi.
// Her kart "demo haber" etiketli — gerçeği temsil etmediği belli.
//
// `forceRefresh=true` parametresi yenileme butonu için zaman seed'ini değiştirir.
let _hmFeedSeedNonce = 0;


// ── ANA MENÜ: SONRAKI MAÇ ÖNİZLEME ──
// ═══════════════════════════════════════════════════════════════════
//  TAKIM GÜCÜ TIER ROZETİ — Bronz/Gümüş/Altın/Zümrüt
//  1-24: Bronz, 25-49: Gümüş, 50-74: Altın, 75+: Zümrüt
// ═══════════════════════════════════════════════════════════════════
function _ratingTier(rating){
  if (rating == null || isNaN(rating)) return null;
  const r = Math.round(rating);
  if (r >= 75) return 'emerald';
  if (r >= 50) return 'gold';
  if (r >= 25) return 'silver';
  return 'bronze';
}
function _setRatingBadge(elId, rating, yzTip){
  const el = document.getElementById(elId);
  if (!el) return;
  const tier = _ratingTier(rating);
  try { _yzNm(elId, tier == null ? null : Math.round(rating), yzTip); } catch (e) {}   // 935
  if (tier == null) {
    el.innerHTML = '—';
    return;
  }
  el.innerHTML = `<span class="ovr-plaka tier-${tier}"><i>OVR</i><b><span>${Math.round(rating)}</span></b></span>`;   // 725
}

// 🆕 Ana sayfa maç önizleme: crest tıklama hookı
// Kendi takım → kendi takım sayfası
// Bot takım → ziyaretçi modunda (viewTeam)
function _hmAttachCrestClick(elId, teamObj, matchObj) {
  const el = document.getElementById(elId);
  if (!el || !teamObj) return;
  const teamName = teamObj.name;
  if (!teamName) return;
  // countryCode: önce takımdan, sonra maçtan
  let cc = teamObj.countryCode || teamObj.cc || (matchObj && (matchObj.countryCode || matchObj.cc)) || null;
  // teams DB'den ara (countryCode boşsa)
  if (!cc && true) {
    for (const xcc of _cftGetCountryCodes()) {
      const country = _cftGetCountry(xcc);
      if (!country || !country.leagues) continue;
      const found = country.leagues.some(lg => (lg.teams||[]).some(t => t.name === teamName));
      if (found) { cc = xcc; break; }
    }
  }
  el.style.cursor = 'pointer';
  el.onclick = (e) => {
    e.stopPropagation();
    const isUserTeam = (typeof _userTeam !== 'undefined' && _userTeam && _userTeam.teamName === teamName);
    if (isUserTeam) {
      if (typeof exitGuestMode === 'function' && typeof _viewingTeam !== 'undefined' && _viewingTeam) {
        try { exitGuestMode(true); return; } catch(_) {}
      }
      if (typeof showPage === 'function') {
        try { showPage('team', null); } catch(_) {}
      }
    } else {
      if (typeof viewTeam === 'function' && cc) {
        try { viewTeam(cc, teamName); } catch(err) { console.warn('viewTeam hata:', err); }
      }
    }
  };
}

// 🆕 ═══ SIRADAKİ 5 MAÇ ŞERİDİ (A1 · dikey kart) ═══
//   Kaynak: renderHomeNextMatch()'in ürettiği candidates[] — lig / turnuva /
//   milli / hazırlık hepsi kickoff'a göre sıralı. Sadece RAKİP gösterilir.

// Lig/turnuva adını kart genişliğine sığacak kadar kısalt
// 🆕 Takımın GÜNCEL lig adı — teams veritabanından okunur.
//    match_state.league_name maç oluşturulduğu andaki addır; terfi/düşme
//    sonrası eskir (4. Lig takımına "5. Lig" yazıyordu).
function _gercekLigAdi(takimAdi, ulkeKodu) {
  try {
    if (!takimAdi || typeof _cftGetCountry !== 'function') return null;
    const cc = ulkeKodu || (typeof _userTeam !== 'undefined' && _userTeam && _userTeam.countryCode) || null;
    if (!cc) return null;
    const c = _cftGetCountry(cc);
    if (!c || !Array.isArray(c.leagues)) return null;
    for (const lg of c.leagues) {
      if ((lg.teams || []).some(t => t && t.name === takimAdi)) return lg.name || null;
    }
  } catch(e) {}
  return null;
}
window._gercekLigAdi = _gercekLigAdi;

function _hmNxComp(ad) {
  if (!ad) return '';
  let t = String(ad).replace(/\s*·.*$/, '').trim();
  t = t.replace(/\bLigi\b/i, 'Lig').replace(/\bLeague\b/i, 'Lig');
  return t;
}

// Bir adaydan kart verisi çıkar — kullanıcının takımı hangi tarafsa RAKİBİ al
// 🆕 Ülke adından (veya kodundan) bayrak emojisi üretir.
//    Milli maç slotlarında "TÜR" gibi kısaltma yerine 🇹🇷 gösterilsin diye.
window._bayrakCache = window._bayrakCache || {};
function _hmUlkeBayrak(ad) {
  if (!ad) return '';
  const s = String(ad).trim();
  // 🆕 ÖNBELLEK — bu fonksiyon sonuç listesinde her satır için çağrılıyor
  //    ve her çağrıda TÜM ülkeler taranıyordu (telefon ısınma kaynağı).
  if (Object.prototype.hasOwnProperty.call(window._bayrakCache, s)) return window._bayrakCache[s];
  const _sonuc = _hmUlkeBayrakHesapla(s);
  window._bayrakCache[s] = _sonuc;
  return _sonuc;
}
function _hmUlkeBayrakHesapla(s) {
  perfSay('bayrak.hesap');
  const norm = x => String(x || '').toLocaleLowerCase('tr').replace(/[\s.'-]/g, '');
  try {
    // Zaten 2 harfli ülke kodu geldiyse
    if (/^[A-Za-z]{2}$/.test(s)) {
      const kod = s.toUpperCase();
      const c = (typeof _cftGetCountry === 'function') ? _cftGetCountry(kod) : null;
      if (c && c.flag) return c.flag;
      if (typeof ccToFlag === 'function') return ccToFlag(kod);
      return '';
    }
    const hedef = norm(s);
    // 1) Oyun veritabanındaki ülkeler (bayrak alanı hazır)
    if (typeof _cftAllEntries === 'function') {
      for (const [kod, c] of _cftAllEntries()) {
        if (!c) continue;
        if (norm(c.name) === hedef || norm(c.countryName) === hedef || norm(kod) === hedef) {
          if (c.flag) return c.flag;
          if (typeof ccToFlag === 'function') return ccToFlag(kod);
        }
      }
    }
    // 2) Genel ülke listesi (kayıt formunun da kullandığı tam liste)
    if (typeof CFT_ALL_COUNTRIES !== 'undefined' && Array.isArray(CFT_ALL_COUNTRIES) && typeof ccToFlag === 'function') {
      const t = CFT_ALL_COUNTRIES.find(x => x && norm(x.name) === hedef);
      if (t && t.code) return ccToFlag(t.code);
    }
    // 3) Milli takım etiketleri ("🇩🇪 Almanya") üzerinden ters arama
    if (typeof CFT_NAT_LABELS !== 'undefined' && CFT_NAT_LABELS && typeof ccToFlag === 'function') {
      for (const kod in CFT_NAT_LABELS) {
        const et = String(CFT_NAT_LABELS[kod] || '');
        const ad = et.replace(/^[^A-Za-zÇĞİÖŞÜçğıöşü]+/, '');
        if (norm(ad) === hedef) return ccToFlag(kod);
      }
    }
  } catch(e) {}
  return '';
}
window._hmUlkeBayrak = _hmUlkeBayrak;

function _hmNxItem(c) {
  const benim = (typeof _userTeam !== 'undefined' && _userTeam && _userTeam.teamName) || '';
  const d = new Date(c.time);
  const o = { d, tur: c.source, ev: true, ad: '?', kisa: '?', cc: null, comp: '', bayrak: '' };
  // 🆕 Takvim slotu (maç yok) — bilgi kartı
  if (c._takvim) {
    o.ad = c._takvim.baslik || '—';
    o.kisa = c._takvim.ikon || '📅';
    o.comp = c._takvim.alt || '';
    o.ev = null;                // EV/DEP rozeti gösterme
    o.takvim = true;
    o.bayrak = c._takvim.ikon || '📅';
    return o;
  }
  // 🆕 Sunucudan gelen sade satır — doğrudan kullan
  if (c._sunucu) {
    o.ad = c._sunucu.ad || '?';
    o.kisa = (o.ad || '?').slice(0, 3).toUpperCase();
    o.cc = c._sunucu.cc || null;
    o.ev = !!c._sunucu.ev;
    o.comp = _hmNxComp(c._sunucu.comp || '');
    // 🆕 Lig maçlarında güncel lig adı (donmuş league_name yerine)
    if (c.source === 'league') {
      const _g = _gercekLigAdi(benim, o.cc);
      if (_g) o.comp = _hmNxComp(_g);
    }
    // 🆕 Milli maç → kulüp arması yok; ülke bayrağı göster
    if (c.source === 'national') {
      o.bayrak = _hmUlkeBayrak(o.ad) || o.bayrak;
      if (typeof _ulkeKodu === 'function') o.cc = _ulkeKodu(o.ad) || o.cc;
    }
    return o;
  }
  try {
    if (c.source === 'league') {
      const L = c.league || {}, h = L.home || {}, a = L.away || {};
      o.ev = (h.name === benim);
      const r = o.ev ? a : h;
      o.ad = r.name || '?';
      o.kisa = (r.short || o.ad.slice(0, 3)).toUpperCase();
      o.cc = r.countryCode || r.cc || L.countryCode || null;
      // 🆕 Güncel lig adı (donmuş league_name yerine)
      o.comp = _hmNxComp(_gercekLigAdi(benim, o.cc) || L.leagueName || 'Lig');
    } else if (c.source === 'friendly') {
      const fm = c.friendly || {};
      o.ev = (fm.fromTeam === benim);
      o.ad = (o.ev ? fm.toTeam : fm.fromTeam) || '?';
      o.kisa = ((o.ev ? fm.toShort : fm.fromShort) || o.ad.slice(0, 3)).toUpperCase();
      o.cc = (o.ev ? fm.toCC : fm.fromCC) || null;
      o.comp = 'Hazırlık';
    } else if (c.source === 'tournament') {
      const t = c.tournament || {};
      o.ev = !!t.userIsHome;
      const r = (o.ev ? t.away : t.home) || {};
      o.ad = r.name || '?';
      o.kisa = (r.short || o.ad.slice(0, 3)).toUpperCase();
      o.cc = r.countryKey || r.countryCode || null;
      const L = { chm: 'Championship', eli: 'Elite', con: 'Convergence' };
      o.comp = L[t.trnType] || 'Turnuva';
    } else if (c.source === 'national') {
      const n = c.national || {}, m = n.match || {};
      o.ev = (m.home === n.cc);
      o.ad = (o.ev ? (m.awayName || m.away) : (m.homeName || m.home)) || '?';
      o.kisa = String((o.ev ? m.away : m.home) || '?').slice(0, 3).toUpperCase();
      o.bayrak = (o.ev ? m.awayFlag : m.homeFlag) || _hmUlkeBayrak(o.ad) || '';
      o.comp = 'EURO Cup';
    }
  } catch(e) {}
  return o;
}

