  if (t === 'champ' || t === 'championship') return 'champ';
  if (t === 'elite' || t === 'eli') return 'elite';
  if (t === 'conv' || t === 'convergence') return 'conv';
  if (t === 'enc' || t === 'euro' || t === 'natcup' || t === 'euronation') return 'enc';
