      const _liveNow = !!_uzR(r) || (!_pf && ((r.status === 'running') || (r.status === 'finished' && _cmS >= 90)));
      const _st = _liveNow ? 'L' : ((r.status === 'finished' || ((r.status === 'running') && _pf)) ? 'F' : 'S');
