// 🆕 Career History: user_player.career_history jsonb
let _careerHistoryCache = null;
let _careerHistorySaveTimer = null;

async function _careerHistoryLoadFromServer(_on956) {
  // ⚠️ VERİ KAYBI KORUMASI — 2026-08-18
  //   Eskiden catch bloğu da cache'i boş diziye düşürüyordu; alttaki backfill
  //   bunu "hiç geçmiş yok" sanıp TEK uydurma kayıtla sunucudaki gerçek
  //   (çok takımlı) geçmişin üzerine yazıyordu. Ağ hatası = kariyer silinmesi.
  //   Artık "gerçekten boş" ile "yüklenemedi" ayrı: yüklenemezse backfill YOK.
  window._careerHistoryLoadedOk = false;
  if (!window.sb || !authUser || !authUser.id) { _careerHistoryCache = []; return; }
  try {
    const { data, error } = _on956 ? await _on956 : await window.sb.from('user_player')   // 956 — açılış satırından
      .select('career_history')
      .eq('user_id', authUser.id)
      .maybeSingle();
    if (error) { console.warn('[career_history] yükleme hatası → backfill kilitli:', error);
                 _careerHistoryCache = []; return; }
    _careerHistoryCache = Array.isArray(data?.career_history) ? data.career_history : [];
    window._careerHistoryLoadedOk = true;
  } catch(e) {
    console.warn('[career_history] yükleme istisnası → backfill kilitli:', e);
    _careerHistoryCache = []; return;
  }

  // BACKFILL: history boşsa ve kullanıcının aktif takımı varsa, mevcut takımı kaydet.
  // Bu, eski hesaplar (career_history feature'ından önce katılmış) için tek seferlik düzeltme.
  // Yeni katılımlar artık ilgili akışta (joinTeamDirect/buyTeam/TM/inbox) push'lanıyor.
  try {
    if (window._careerHistoryLoadedOk &&
        _careerHistoryCache.length === 0 && typeof _userTeam !== 'undefined' && _userTeam && _userTeam.teamName) {
      const cc = _userTeam.countryCode;
      const country = (typeof _cftGetCountry === 'function') ? _cftGetCountry(cc) : null;
      const tierIdx = (typeof getUserRealTierIdx === 'function') ? getUserRealTierIdx() : 0;
      const lgName = (country && Array.isArray(country.leagues) && country.leagues[tierIdx])
        ? country.leagues[tierIdx].name : '';
      const joinTs = _userTeam.joinedAt || _userTeam.purchasedAt || Date.now();
      const entry = {
        teamName: _userTeam.teamName,
        countryCode: cc,
        leagueName: lgName,
        role: _userTeam.role || 'member',
        joinDate: new Date(joinTs).toISOString(),
        leaveDate: null,
        reason: ''
      };
      _careerHistoryCache = [entry];
      // Server'a kalıcı yaz
      try {
        await window.sb.from('user_player').update({
          career_history: _careerHistoryCache
        }).eq('user_id', authUser.id);
      } catch(e) { console.warn('[career_history] backfill yazma hatası:', e); }
    }
  } catch(e) { console.warn('[career_history] backfill exception:', e); }
}

function getCareerHistory() {
  return Array.isArray(_careerHistoryCache) ? _careerHistoryCache : [];
}

function _saveCareerHistory(list) {
  _careerHistoryCache = Array.isArray(list) ? list : [];
  // 🆕 Sunucudan yüklenmeden yazma — boş/eksik liste gerçek geçmişi ezmesin
  if (!window._careerHistoryLoadedOk) {
    console.warn('[career_history] KAYDETME İPTAL — geçmiş sunucudan yüklenmedi.');
    return;
  }
  if (window.sb && authUser && authUser.id) {
    clearTimeout(_careerHistorySaveTimer);
    _careerHistorySaveTimer = setTimeout(async () => {
      try {
        await window.sb.from('user_player').update({
          career_history: _careerHistoryCache
        }).eq('user_id', authUser.id);
      } catch(e) { console.warn('[career_history] save hata:', e); }
    }, 500);
  }
}

// Yardımcı: takım geçmişine ekle (kullanıcı yeni takıma katıldığında çağrılır)
function pushCareerHistory(entry) {
  const list = getCareerHistory().slice();
  list.push({
    teamName: entry.teamName,
    countryCode: entry.countryCode,
    leagueName: entry.leagueName || '',
    role: entry.role || 'member',
    joinDate: entry.joinDate || new Date().toISOString(),
    leaveDate: entry.leaveDate || null,
    reason: entry.reason || ''
  });
  _saveCareerHistory(list);
}

// Yardımcı: aktif takımın "leaveDate"ini set et (ayrılırken)
function _carCloseCurrentHistory(reason) {
  const list = getCareerHistory().slice();
  if (list.length > 0 && !list[list.length - 1].leaveDate) {
    list[list.length - 1].leaveDate = new Date().toISOString();
    list[list.length - 1].reason = reason || '';
    _saveCareerHistory(list);
  }
}

// Yardımcı: piyasa değeri snapshot kaydı (her render'da güncel snapshot eklenir)
function _carRecordMarketValue(value) {
  try {
    // 🆕 Supabase RAM cache'inden oku
    const list = Array.isArray(_marketValHistCache) ? _marketValHistCache : [];
    const todayKey = new Date().toISOString().slice(0, 10); // YYYY-MM-DD
    // Aynı gün için varsa güncelle, yoksa ekle
    const existing = list.findIndex(e => e.day === todayKey);
    if (existing >= 0) list[existing].value = value;
    else list.push({ day: todayKey, value });
    // Son 30 gün
    const trimmed = list.slice(-30);
    _marketValHistCache = trimmed;
    // Debounced Supabase write
    if (window.sb && authUser && authUser.id) {
      clearTimeout(_marketValHistSaveTimer);
      _marketValHistSaveTimer = setTimeout(async () => {
        try {
          await window.sb.from('user_player').update({
            market_val_history: trimmed
          }).eq('user_id', authUser.id);
        } catch(e) { console.warn('[mv_history] save hata:', e); }
      }, 1000);
    }
  } catch(e) {}
}

// Yarışmalara Göre kartı için sezon görünümü değiştirici
// view: 'all' | sezon numarası (int)
function carCompSetView(view) {
  window._carCompSeasonView = view;
  if (typeof renderCareerTab === 'function') renderCareerTab();
}

// Ana render fonksiyonu
function renderCareerPage() {
  // ─── Verileri topla ───
  let log = [];
  try { log = getUserMatchLog(); } catch(e) {}
  let trophies = getTrophies();
  let careerHist = [];
  try { careerHist = getCareerHistory(); } catch(e) {}

  const userPlayer = (typeof ROSTER_DATA !== 'undefined' && ROSTER_DATA.length)
    ? ROSTER_DATA.find(p => p.role === 'user') : null;

  const isInTeam = !!(typeof _userTeam !== 'undefined' && _userTeam);
  const cc = isInTeam ? _userTeam.countryCode : (authUser && authUser.nationality) || '';
  const country = (true && cc) ? _cftGetCountry(cc) : null;
  const flag = country ? country.flag : '🏳️';

  // ─── HERO ───
  const heroEl = document.getElementById('carHero');
  if (heroEl) {
    if (!authUser) {
      heroEl.innerHTML = '<div class="car-hero-loading">Henüz oyuncu profili yok</div>';
    } else {
      const playerName = authUser.name || 'İsimsiz Oyuncu';
      const posLabel = SUBPOS_LABEL[subPosOf({ pos: authUser.position || userPlayer?.pos, sub_pos: authUser.subPos })];
      const level = userPlayer?.level || 0;
      const overall = userPlayer?.overall || 10;

      // 🆕 Piyasa değeri TEK KAYNAK: oyun modeli. Kaptan override'ı kaldırıldı.
      let mv = _carEstimateMarketValue(userPlayer || { overall: overall, level: level });
      let isCaptainSet = false;
      _carRecordMarketValue(mv); // her render'da snapshot

      // Trend hesapla (son ile öncesi)
      let trendHtml = '';
      try {
        const mvList = Array.isArray(_marketValHistCache) ? _marketValHistCache : [];
        if (mvList.length >= 2) {
          const prev = mvList[mvList.length - 2].value;
          const diff = mv - prev;
          const fmt = (typeof formatMV === 'function') ? formatMV : _carFmtEUR;
          if (diff > 0) trendHtml = `<div class="car-mv-trend up">▲ +${fmt(diff)}</div>`;
          else if (diff < 0) trendHtml = `<div class="car-mv-trend down">▼ ${fmt(Math.abs(diff))}</div>`;
          else trendHtml = `<div class="car-mv-trend">─ değişim yok</div>`;
        }
      } catch(e) {}

      const teamName = isInTeam ? _userTeam.teamName : 'Serbest';
      const teamRoleLabel = isInTeam
        ? (_userTeam.role === 'captain' ? '👑 Kaptan' : (_userTeam.role === 'vice' ? '⭐ Yrd. Kaptan' : '👥 Üye'))
        : '🆓 Takımsız';

      heroEl.innerHTML = `
        <div class="car-hero-row">
          <div class="car-avatar">${authUser.avatarId ? '⚽' : '👤'}</div>
          <div class="car-info">
            <div class="car-name">${playerName}</div>
            <div class="car-meta-row">
              <span class="car-meta-pill">${flag} ${cc}</span>
              <span class="car-meta-pill">${posLabel}</span>
              <span class="car-meta-pill gold">Sv. ${level}</span>
              <span class="car-meta-pill">OVR ${overall}</span>
              <span class="car-meta-pill">${teamRoleLabel}</span>
            </div>
            <div class="car-meta-row" style="margin-top:6px">
              <span class="car-meta-pill" style="font-size:10px;font-weight:700">${isInTeam ? '🛡️ ' + teamName : '🆓 Takımsız'}</span>
            </div>
          </div>
        </div>
        <div class="car-mv-row">
          <div class="car-mv-block">
            <div class="car-mv-label">Piyasa Değeri${isCaptainSet ? ' · 👑 Kaptan' : ''}</div>
            <div class="car-mv-value" style="${isCaptainSet ? 'color:#ffd54f' : ''}">${(typeof formatMV === 'function') ? formatMV(mv) : _carFmtEUR(mv)}</div>
            ${trendHtml}
          </div>
        </div>
      `;
    }
  }

  // ─── KARİYER ÖZETİ (kümülatif — DB'den goals_total/assists_total/matches_played) ───
  // log array son 50 maçla sınırlı; bu yüzden kazanma/beraberlik/mağlubiyet için son 50'yi kullanırız,
  // toplam Maç/Gol/Asist için ise users tablosundaki kümülatif total alanlarını okuruz.
  const careerMatches = (userPlayer && userPlayer.matchesPlayed) || 0;
  const careerGoals   = (userPlayer && userPlayer.goalsTotal) || 0;
  const careerAssists = (userPlayer && userPlayer.assistsTotal) || 0;
  const stats = {
    matches: careerMatches,
    wins: log.filter(m => m.result === 'W').length,    // son 50 maç W/D/L
    draws: log.filter(m => m.result === 'D').length,
    losses: log.filter(m => m.result === 'L').length,
    goals: careerGoals,
    assists: careerAssists,
    yellowCards: log.reduce((s, m) => s + (m.yellowCards || 0), 0),
    redCards: log.reduce((s, m) => s + (m.redCards || 0), 0),
  };
  const winRate = stats.matches > 0 ? Math.round((stats.wins / Math.max(log.length, 1)) * 100) : 0;
  const goalAvg = stats.matches > 0 ? (stats.goals / stats.matches).toFixed(2) : '0.00';

  const statsEl = document.getElementById('carStatsGrid');
  if (statsEl) {
    statsEl.innerHTML = `
      <div class="car-stat-card"><div class="car-stat-value">${stats.matches}</div><div class="car-stat-label">Maç</div></div>
      <div class="car-stat-card"><div class="car-stat-value green">${stats.goals}</div><div class="car-stat-label">Gol</div></div>
      <div class="car-stat-card"><div class="car-stat-value acc">${stats.assists}</div><div class="car-stat-label">Asist</div></div>
      <div class="car-stat-card"><div class="car-stat-value">${winRate}%</div><div class="car-stat-label">Kazanma</div></div>
      <div class="car-stat-card"><div class="car-stat-value green">${stats.wins}</div><div class="car-stat-label">Galibiyet</div></div>
      <div class="car-stat-card"><div class="car-stat-value">${stats.draws}</div><div class="car-stat-label">Beraberlik</div></div>
      <div class="car-stat-card"><div class="car-stat-value red">${stats.losses}</div><div class="car-stat-label">Mağlubiyet</div></div>
      <div class="car-stat-card"><div class="car-stat-value">${goalAvg}</div><div class="car-stat-label">G/Maç</div></div>
    `;
  }

  // ─── BU SEZON ───
  // Bu sezonun başlangıç tarihinden sonraki maçlar
  let seasonStartMs = 0;
  try {
    const info = (typeof getSeasonInfo === 'function') ? getSeasonInfo() : null;
    if (info && info.seasonStart) seasonStartMs = new Date(info.seasonStart).getTime();
  } catch(e) {}
  const seasonLog = log.filter(m => {
    try { return new Date(m.date).getTime() >= seasonStartMs; } catch(e) { return false; }
  });
  const seasonStats = {
    matches: seasonLog.length,
    goals: seasonLog.reduce((s, m) => s + (m.goals || 0), 0),
    assists: seasonLog.reduce((s, m) => s + (m.assists || 0), 0),
    wins: seasonLog.filter(m => m.result === 'W').length,
    yellowCards: seasonLog.reduce((s, m) => s + (m.yellowCards || 0), 0),
    redCards: seasonLog.reduce((s, m) => s + (m.redCards || 0), 0),
  };
  const seasonStatsEl = document.getElementById('carSeasonStatsGrid');
  if (seasonStatsEl) {
    seasonStatsEl.innerHTML = `
      <div class="car-stat-card"><div class="car-stat-value">${seasonStats.matches}</div><div class="car-stat-label">Maç</div></div>
      <div class="car-stat-card"><div class="car-stat-value green">${seasonStats.goals}</div><div class="car-stat-label">Gol</div></div>
      <div class="car-stat-card"><div class="car-stat-value acc">${seasonStats.assists}</div><div class="car-stat-label">Asist</div></div>
      <div class="car-stat-card"><div class="car-stat-value">${seasonStats.wins}</div><div class="car-stat-label">Galibiyet</div></div>
      <div class="car-stat-card"><div class="car-stat-value" style="color:#ffc107">${seasonStats.yellowCards}</div><div class="car-stat-label">Sarı Kart</div></div>
      <div class="car-stat-card"><div class="car-stat-value red">${seasonStats.redCards}</div><div class="car-stat-label">Kırmızı</div></div>
    `;
  }

  // ─── YARIŞMALARA GÖRE DAĞILIM (stats_by_comp v2 — sezon kırılımlı) ───
  // Veri kaynağı: userPlayer.statsByComp — Edge function maç sonu her bucket'ın aktif sezonuna yazıyor.
  // Yapı: { lig: { s1: {g,a,m}, s2: {g,a,m} }, chm: { s1: {g,a,m} } }
  // Görünüm modları: "Tüm Zamanlar" (toplam) veya seçilen tek sezon (s1, s2, ...)
  // Her zaman 5 satır gösterilir (oynanmamış yarışmalar opak).
  const compGridEl = document.getElementById('carCompGrid');
  if (compGridEl) {
    const sbc = (userPlayer && userPlayer.statsByComp && typeof userPlayer.statsByComp === 'object')
      ? userPlayer.statsByComp : {};
    const COMPS = [
      { key: 'lig', icon: '🏟️', name: 'Lig',                cls: 'is-lig' },
      { key: 'chm', icon: '🏆', name: 'Şampiyonlar Ligi',    cls: 'is-chm' },
      { key: 'eli', icon: '🥈', name: 'Elit Lig',            cls: 'is-eli' },
      { key: 'con', icon: '🥉', name: 'Konferans Ligi',      cls: 'is-con' },
      { key: 'enc', icon: '🌍', name: 'EURO Nations Cup',    cls: 'is-enc' },
    ];
    const playedSeasons = statsByCompGetSeasons(sbc);
    const activeSeason = (typeof getSeasonInfo === 'function') ? (getSeasonInfo().season || 1) : 1;
    // View modu: 'all' | sezon numarası (int). Default = 'all'
    if (typeof window._carCompSeasonView === 'undefined') window._carCompSeasonView = 'all';
    const view = window._carCompSeasonView;

    // Veri çekici (view'a göre)
    const readStat = (bucket) => {
      if (view === 'all') return statsByCompGetTotal(sbc, bucket);
      return statsByCompGetSeason(sbc, bucket, view);
    };

    const totalMatches = COMPS.reduce((s, c) => s + readStat(c.key).m, 0);

    // Sezon seçici header
    let pillsHtml = '';
    if (playedSeasons.length > 0) {
      const allActive = view === 'all' ? ' active' : '';
      pillsHtml += `<button class="car-comp-pill${allActive}" onclick="carCompSetView('all')">Tüm Zamanlar</button>`;
      playedSeasons.forEach(sn => {
        const sActive = (view !== 'all' && view === sn) ? ' active' : '';
        const label = (sn === activeSeason) ? `Sezon ${sn} (Aktif)` : `Sezon ${sn}`;
        pillsHtml += `<button class="car-comp-pill${sActive}" onclick="carCompSetView(${sn})">${label}</button>`;
      });
    }

    let rowsHtml = '';
    if (totalMatches === 0) {
      rowsHtml = '<div class="car-comp-empty">Bu görünümde maç bulunmuyor</div>';
    } else {
      rowsHtml = COMPS.map(c => {
        const s = readStat(c.key);
        const m = s.m, g = s.g, a = s.a;
        const gpm = m > 0 ? (g / m).toFixed(2) : '—';
        const emptyCls = m === 0 ? ' is-empty' : '';
        const sub = m === 0 ? 'Bu görünümde maç yok' : `${m} maç · ortalama ${gpm} gol`;
        return `
          <div class="car-comp-row ${c.cls}${emptyCls}">
            <div class="car-comp-icon">${c.icon}</div>
            <div class="car-comp-info">
              <div class="car-comp-name">${c.name}</div>
              <div class="car-comp-sub">${sub}</div>
            </div>
            <div class="car-comp-nums">
              <div class="car-comp-num-box">
                <div class="car-comp-num-val">${m}</div>
                <div class="car-comp-num-lbl">Maç</div>
              </div>
              <div class="car-comp-num-box">
                <div class="car-comp-num-val gr">${g}</div>
                <div class="car-comp-num-lbl">Gol</div>
              </div>
              <div class="car-comp-num-box">
                <div class="car-comp-num-val ye">${a}</div>
                <div class="car-comp-num-lbl">Asist</div>
              </div>
            </div>
          </div>
        `;
      }).join('');
    }

    compGridEl.innerHTML = (pillsHtml ? `<div class="car-comp-pills">${pillsHtml}</div>` : '') + rowsHtml;
  }

  // ─── FORM (son 5 maç) ───
  const formEl = document.getElementById('carForm');
  if (formEl) {
    if (log.length === 0) {
      formEl.innerHTML = '<div class="car-form-empty">Henüz maç oynanmadı</div>';
    } else {
      const last5 = log.slice(-5);
      const cells = last5.map(m => {
        const cls = (m.result || '').toLowerCase();
        const _fk = window._ligKolon(); const lbl = m.result === 'W' ? _fk.g : (m.result === 'D' ? _fk.b : _fk.m);
        return `<div class="car-form-cell ${cls}">${lbl}</div>`;
      }).join('');
      // Eksikleri "?" ile doldur (sağdan)
      const padding = Array(5 - last5.length).fill('<div class="car-form-cell q">?</div>').join('');
      formEl.innerHTML = padding + cells;
    }
  }

  // ─── TAKIM GEÇMİŞİ ───
  const teamHistEl = document.getElementById('carTeamHistory');
  if (teamHistEl) {
    if (careerHist.length === 0) {
      teamHistEl.innerHTML = '<div class="car-table-empty">Takım geçmişi henüz yok</div>';
    } else {
      // En yeniden eskiye sırala
      const sorted = [...careerHist].reverse();
      teamHistEl.innerHTML = sorted.map(h => {
        const isCurrent = !h.leaveDate;
        const teamFlag = (_cftGetCountry(h.countryCode) || {}).flag || '🏳️';
        const startDate = h.joinDate ? new Date(h.joinDate).toLocaleDateString(window._tarihYerel()) : '—';
        const endDate = h.leaveDate ? new Date(h.leaveDate).toLocaleDateString(window._tarihYerel())
          : ((typeof T === 'function') ? T('Aktif') : 'Aktif');
        const days = isCurrent ? _carDaysSince(h.joinDate) : Math.floor((new Date(h.leaveDate) - new Date(h.joinDate)) / 86400000);

        // Bu takımdaki maç istatistikleri (varsa)
        const teamMatches = log.filter(m => {
          const teamName = h.teamName;
          return (m.home === teamName && m.userIsHome) || (m.away === teamName && !m.userIsHome);
        });
        const teamGoals = teamMatches.reduce((s, m) => s + (m.goals || 0), 0);
        const teamAssists = teamMatches.reduce((s, m) => s + (m.assists || 0), 0);

        return `
          <div class="car-table-row${isCurrent ? ' current' : ''}">
            <div class="car-team-flag">${teamFlag}</div>
            <div class="car-team-info">
              <div class="car-team-name">${h.teamName}${isCurrent ? ' <span style="color:#00e676;font-size:10px">●</span>' : ''}</div>
              <div class="car-team-period">${startDate} → ${endDate} · ${days} ${(typeof T === 'function') ? T('gün') : 'gün'}${h.leagueName ? ' · ' + h.leagueName : ''}</div>
            </div>
            <div class="car-team-stats">
              ${teamMatches.length}M · ${teamGoals}G · ${teamAssists}A
            </div>
          </div>
        `;
      }).join('');
    }
  }
  // 🆕 Transfer geçmişi (yoksa kariyer başlangıcı) — kendi profili
  try { if (typeof _ptrFillInto === 'function') _ptrFillInto('carTeamHistory', userPlayer, true); } catch(e) {}

  // ─── PİYASA DEĞERİ GRAFİĞİ ───
  const mvChartEl = document.getElementById('carMvChart');
  if (mvChartEl) {
    let mvList = Array.isArray(_marketValHistCache) ? _marketValHistCache : [];

    if (mvList.length === 0) {
      mvChartEl.innerHTML = '<div class="car-mv-empty">Piyasa değeri geçmişi yok</div>';
    } else {
      // 🆕 Çizgi grafik (transfermarkt tarzı) — son 30 nokta
      mvChartEl.innerHTML = _carMvChartHtml(mvList.slice(-30));
    }
  }

  // ─── TROFELER + SEZON KIRILIMI ───
  const _mySeasonRows = (typeof _carSeasonRows === 'function' && userPlayer) ? _carSeasonRows(userPlayer) : [];
  const _mySeasonHtml = _mySeasonRows.length
    ? ('<div class="car-season-sec-t">📅 Sezonluk Performans</div>' + _carSeasonListHtml(_mySeasonRows)) : '';
  const trophiesEl = document.getElementById('carTrophies');
  if (trophiesEl) {
    if (trophies.length === 0) {
      trophiesEl.innerHTML = '<div class="car-trophies-empty">Henüz kupa kazanılmadı</div>' + _mySeasonHtml;
    } else {
      trophiesEl.innerHTML = trophies.map(t => {
        let icon = '🏆';
        let name = t.leagueName || t.type || 'Kupa';
        let cupKey = null;
        if (t.type === 'champ') { cupKey = 'champ'; name = 'Championship'; }
        else if (t.type === 'elite') { cupKey = 'elite'; name = 'Elite Cup'; }
        else if (t.type === 'conv') { cupKey = 'conv'; name = 'Convergence'; }
        else if (t.type === 'enc') { icon = '🌍'; name = 'EURO Nations'; }
        else if (t.type === 'league') { icon = '🥇'; }
        const iconHtml = cupKey ? _cupLogoIMG(cupKey, 32) : `<div style="font-size:32px">${icon}</div>`;
        return `
          <div class="car-trophy">
            <div class="car-trophy-icon">${iconHtml}</div>
            <div class="car-trophy-name">${name}</div>
            <div class="car-trophy-season">Sezon ${t.season || '?'}</div>
          </div>
        `;
      }).join('');
    }
  }

  // ─── SON MAÇLAR (max 10) ───
  const matchesEl = document.getElementById('carMatches');
  if (matchesEl) {
    if (log.length === 0) {
      matchesEl.innerHTML = '<div class="car-table-empty">Henüz maç oynanmadı</div>';
    } else {
      const last10 = [...log].reverse().slice(0, 10);
      matchesEl.innerHTML = last10.map(m => {
        const cls = (m.result || '').toLowerCase();
        const _fk = window._ligKolon(); const lbl = m.result === 'W' ? _fk.g : (m.result === 'D' ? _fk.b : _fk.m);
        const userTeam = m.userIsHome ? m.home : m.away;
        const oppTeam = m.userIsHome ? m.away : m.home;
        const score = m.userIsHome ? `${m.hs}-${m.as}` : `${m.as}-${m.hs}`;

        const stats = [];
        if (m.goals) stats.push(`<span class="car-match-stat-g">⚽${m.goals}</span>`);
        if (m.assists) stats.push(`<span class="car-match-stat-a">🅰️${m.assists}</span>`);
        if (m.yellowCards) stats.push(`<span class="car-match-stat-y">🟨${m.yellowCards}</span>`);
        if (m.redCards) stats.push(`<span class="car-match-stat-r">🟥${m.redCards}</span>`);

        return `
          <div class="car-match-row">
            <div class="car-match-result ${cls}">${lbl}</div>
            <div class="car-match-teams">${userTeam} <span style="color:var(--text3)">vs</span> ${oppTeam}</div>
            <div class="car-match-score">${score}</div>
            <div class="car-match-stats">${stats.join('')}</div>
          </div>
        `;
      }).join('');
    }
  }
}


// 🆕 HOME — LİG SAHNESİ: Kullanıcı ülkesinin tüm liglerinin ilk 5 takımı, yatay scroll
// 713 — ana sayfa özetleri her tazelemede aynı HTML ile baştan kuruluyordu (armalar yeniden yüklenip titriyor,
//   ticker başa sarıyordu). İçerik aynıysa ve başka bir yazım araya girmediyse dokunulmaz.
function _hmYaz(el, html) {
  if (!el) return;
  if (el._hmSon === html && el._hmIlk && el._hmIlk === el.firstChild && el._hmIlk.isConnected) return;
  el.innerHTML = html; el._hmSon = html; el._hmIlk = el.firstChild;
}
function renderHomeLeagueScene() {
  const wrap = document.getElementById('homeLeagueScroll');
  if (!wrap) return;

  const _titleBox = document.getElementById('hmLeagueTitleBox');
  const _ticker   = document.getElementById('homeLeagueTicker');
  const _goster = (ac) => {
    const v = ac ? '' : 'none';
    if (_titleBox) _titleBox.style.display = v;
    if (_ticker)   _ticker.style.display   = v;
    wrap.style.display = v;
  };

  // 🆕 Ülke seçimi: takımı varsa takımın ülkesi, YOKSA oyuncunun uyruğu.
  //    Takımsız oyuncu da kendi ülkesinin lig özetini görsün.
  let cc = (typeof _userTeam !== 'undefined' && _userTeam && _userTeam.countryCode)
    ? _userTeam.countryCode : null;
  if (!cc && typeof getUserNationalityCC === 'function') {
    cc = getUserNationalityCC();
  }

  // 🆕 Oyunda o ülkenin ligi yoksa panel HİÇ görünmesin.
  //    (ör. oyuncu ABD'li ama oyunda ABD ligi yok → lig özeti çıkmaz)
  const country = cc ? _cftGetCountry(cc) : null;
  if (!country || !Array.isArray(country.leagues) || !country.leagues.length) {
    _goster(false);
    return;
  }
  _goster(true);

  const userTeamName = (typeof _userTeam !== 'undefined' && _userTeam && _userTeam.teamName)
    ? _userTeam.teamName : null;

  const cards = country.leagues.map((league, tierIdx) => {
    const tierColor = (typeof LG2_TIER_COLOR !== 'undefined' && LG2_TIER_COLOR[tierIdx]) || '#78909c';
    let standings = [];
    try {
      if (typeof calcLeagueStandings === 'function') {
        standings = calcLeagueStandings(cc, tierIdx);
      }
    } catch(e) {}

    const top5 = (standings || []).slice(0, 5);
    const userInLeague = top5.some(t => t && t.name === userTeamName);
    const userTeamInLg = (standings || []).some(t => t && t.name === userTeamName);

    let rowsHtml = '';
    if (top5.length === 0) {
      rowsHtml = '<div class="lg-scene-empty">Veri yok</div>';
    } else {
      rowsHtml = top5.map((t, i) => {
        const pos = i + 1;
        const isUser = t.name === userTeamName;
        const bg = t.bg || '#37474f';
        const tc = t.tc || '#fff';
        const short = t.short || (t.name || '').slice(0, 3).toUpperCase();
        return `
          <div class="lg-scene-row${isUser ? ' is-user' : ''}">
            <div class="lg-scene-rank">${pos}</div>
            ${inlineBadge({tag:'div', cls:'lg-scene-crest', name:t.name, bg, tc, short})}
            <div class="lg-scene-tname" title="${t.name || ''}">${t.name || '—'}</div>
            <div class="lg-scene-pts">${t.pts != null ? t.pts : 0}</div>
          </div>
        `;
      }).join('');
    }

    return `
      <div class="lg-scene-card" data-user="${userTeamInLg ? '1' : '0'}">
        ${_banBant(_BAN_TIER[Math.min(5, tierIdx)], (league.name || 'Lig'), _BAN_ALT[_BAN_TIER[Math.min(5, tierIdx)]],
          `<button class="bnt-go" onclick="event.stopPropagation();_lgSceneOpen('${cc}',${tierIdx})" title="Tam tablo" aria-label="${league.name || 'Lig'} tam puan durumu"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><line x1="7" y1="17" x2="17" y2="7"/><polyline points="7 7 17 7 17 17"/></svg></button>`,
          tierIdx)}
        <div class="lg-scene-list">${rowsHtml}</div>
      </div>
    `;
  }).join('');

  _hmYaz(wrap, cards || '<div class="lg-scene-empty">Bu ülkede lig yok.</div>');

  // 🆕 Lig özetlerinin altına maç sonuç ticker'ı çiz
  try { renderHomeLeagueTicker(); } catch(e) {}
}

// 🆕 LİG TİCKER — kullanıcı ülkesinin BUGÜNkü (UTC gün) lig maçlarını akan şeritte göster.
// Gün penceresi UTC 00:00 → 00:00 (TR saatiyle 03:00'da döner). Aynı gün içinde:
//   biten = skor, canlı = dakika+skor, başlamamış = başlama saati (yerel).
// 15 dakikalık sabit dilimlerde (00,15,30,45) yenilenir — _lgTickerScheduleNext kurar.
// Veri kaynağı: _matchStateCache.byKey (SONUÇLARIM ile aynı RAM cache — sahte üretim YOK)
function renderHomeLeagueTicker() {
  const wrap = document.getElementById('homeLeagueTicker');
  if (!wrap) return;

  // 🆕 524 — takımsızsa uyruğun ülkesi (lig sahnesiyle aynı)
  const cc = (typeof _hmSahneCC === 'function') ? _hmSahneCC() : null;
  if (!cc) { wrap.style.display = 'none'; return; }

  if (!_matchStateCache || !_matchStateCache.byKey) {
    wrap.style.display = 'none';
    return;
  }

  // Gün penceresi UTC 00:00 → ertesi UTC 00:00 (TR 03:00 dönümü)
  const now = new Date();
  const utcStart = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());
  const utcEnd = utcStart + 86400000;

  // Kullanıcı ülkesinin bu güne ait lig maçları (turnuva hariç). Canlı maçlar şeritte gösterilmez.
  const matches = [];
  for (const ms of (_msKova('ulke', cc) || Object.values(_matchStateCache.byKey))) {   // 958 — yalnız ülkenin lig maçları
    if (!ms || !ms.matchDateTime || ms.tournament_key) continue;
    if (ms.countryCode !== cc) continue;
    if (ms.status === 'running') continue;
    const t = new Date(ms.matchDateTime).getTime();
    if (isNaN(t) || t < utcStart || t >= utcEnd) continue;
    matches.push({ ms, t });
  }

  if (!matches.length) {
    // 🆕 Boş kutu "bozuk" duruyordu. Aynı kayar şerit mantığıyla,
    //    tekrarlanan bir bilgi yazısı döndürülüyor. Akış mantığı aynı.
    wrap.style.display = 'block';
    const bosItem = `
      <div class="lg-ticker-item bos">
        <span class="lg-ti-bos">Bugün lig maçı yok</span>
      </div>`;
    const tekrar = bosItem.repeat(6);
    _hmYaz(wrap, `<div class="lg-ticker-track lg-ticker-track-bos">${tekrar}${tekrar}</div>`);
    _lgTickerScheduleNext();
    return;
  }

  // Kronolojik: başlama saatine göre (erken bitenler → sonraki başlayacaklar)
  matches.sort((a, b) => a.t - b.t);

  wrap.style.display = 'block';

  const itemHtml = matches.map(({ ms }) => {
    const home = ms.home || '—';
    const away = ms.away || '—';
    if (ms.status === 'finished') {
      const hs = ms.home_score ?? 0, as = ms.away_score ?? 0;
      return `
        <div class="lg-ticker-item fin">
          <span class="lg-ti-team">${home}</span>
          <span class="lg-ti-score">${hs}-${as}</span>
          <span class="lg-ti-team">${away}</span>
        </div>`;
    }
    // başlamamış (scheduled) — başlama saati
    const hm = (typeof _getMatchHM === 'function') ? _getMatchHM(ms) : '';
    return `
      <div class="lg-ticker-item sched">
        <span class="lg-ti-team">${home}</span>
        <span class="lg-ti-time">${hm}</span>
        <span class="lg-ti-team">${away}</span>
      </div>`;
  }).join('');

  // Sürekli scroll için içeriği 2x kopyala (translateX(-50%) ile döngü tamamlanır)
  _hmYaz(wrap, `<div class="lg-ticker-track">${itemHtml}${itemHtml}</div>`);

  // Bir sonraki 15'lik dilimde yenile
  _lgTickerScheduleNext();
}

// 🆕 Bir sonraki çeyrek saat dilimine (xx:00, xx:15, xx:30, xx:45) kadar bekleyip yeniler.
// Sürekli interval YOK — her seferinde tek bir timeout kurulur, render içinde tekrar planlanır.
function _lgTickerScheduleNext() {
  if (window._lgTickerTimer) {
    clearTimeout(window._lgTickerTimer);
    window._lgTickerTimer = null;
  }
  const now = new Date();
  const ms = now.getMinutes() * 60000 + now.getSeconds() * 1000 + now.getMilliseconds();
  const quarter = 15 * 60000;
  const delay = quarter - (ms % quarter); // sonraki 00/15/30/45'e kalan süre
  window._lgTickerTimer = setTimeout(() => {
    const tEl = document.getElementById('homeLeagueTicker');
    if (!tEl || !document.body.contains(tEl)) {
      window._lgTickerTimer = null;
      return;
    }
    try { renderHomeLeagueTicker(); } catch(e) {}
  }, delay);
}

// 🆕 Lig sahnesi git butonu — o ligi aç
function _lgSceneOpen(cc, tierIdx) {
  try {
    if (typeof showPage === 'function') {
      const navBtn = (typeof findNavBtn === 'function') ? findNavBtn('leagues') : null;
      showPage('leagues', navBtn);
    }
    if (typeof lg2OpenLeague === 'function') {
      setTimeout(() => { try { lg2OpenLeague(cc, tierIdx); } catch(e) {} }, 50);
    }
  } catch(e) {}
}

// HOME — Günün maçları (sezon durumuna göre)
function renderHomeMatches() {
  const wrap = document.getElementById('homeMatchScroll');
  if(!wrap) return;
  const info = getSeasonInfo();

  if(info.preSeason) {
    // Sezon başlamadı — placeholder ekran
    wrap.innerHTML = `
      <div class="home-empty-card with-btn">
        <div class="hec-icon">⏳</div>
        <div class="hec-title">Sezon Henüz Başlamadı</div>
        <div class="hec-sub">Sezon 1 başlamak üzere — <b>${info.daysToStart} gün</b> sonra ilk maçlar oynanacak. Bu süreçte takımını gelişimine ve antrenmana odaklanabilirsin.</div>
        <button class="hec-btn" onclick="showPage('training', document.querySelectorAll('.nav-btn')[3])">⚡ Antrenmana Git</button>
      </div>
    `;
    return;
  }

  // Kullanıcının ülkesi (takımlıysa _userTeam.countryCode, değilse milliyet, default TR)
  const userCC = (typeof _userTeam !== 'undefined' && _userTeam && _userTeam.countryCode)
    ? _userTeam.countryCode
    : (authUser && authUser.nationality ? authUser.nationality : 'TR');
  const country = _cftGetCountry(userCC);

  if (!country || !country.leagues || country.leagues.length === 0) {
    wrap.innerHTML = `<div class="home-empty-card">
      <div class="hec-icon">⚽</div>
      <div class="hec-title">Lig Verisi Yok</div>
      <div class="hec-sub">Bu ülke için lig verisi bulunamadı.</div>
    </div>`;
    return;
  }

  // Cache'i bir kez oku
  let resultsCache = {};
  try { resultsCache = _matchResultsLoad(); } catch(e) {}

  // 🆕 Cache'ten takım çiftine göre lookup map oluştur (key formatı ne olursa olsun bulur)
  // Aynı takım çifti birden fazla maç olabilir (önceki sezonlardan) — listede tut
  const cacheLookupByTeams = {};
  for (const k in resultsCache) {
    const v = resultsCache[k];
    if (!v || typeof v.hs !== 'number') continue;
    // Value'da home/away yoksa key'den çıkarmaya çalış
    let home = v.home;
    let away = v.away;
    if (!home || !away) {
      // Key formatı: "season_day_home_away" veya "trn_X_season_day_home_away"
      const parts = k.split('_');
      if (parts[0] === 'trn') {
        // trn_KEY_season_day_home_away
        home = parts[4];
        away = parts.slice(5).join('_');
      } else {
        home = parts[2];
        away = parts.slice(3).join('_');
      }
    }
    if (!home || !away) continue;
    const teamKey = `${home}|${away}`;
    if (!cacheLookupByTeams[teamKey]) cacheLookupByTeams[teamKey] = [];
    cacheLookupByTeams[teamKey].push({ ...v, _key: k, _home: home, _away: away });
  }

  // 🆕 Cache içinde maç bulma helper'ı (key uyumsuzluğunda fallback)
  function findCachedMatch(homeName, awayName, targetSeason, targetDay) {
    const teamKey = `${homeName}|${awayName}`;
    const arr = cacheLookupByTeams[teamKey];
    if (!arr || !arr.length) return null;
    // 1. Tam eşleşme: aynı sezon + aynı day
    let best = arr.find(m => m.season === targetSeason && m.day === targetDay);
    if (best) return best;
    // 2. Aynı sezon (farklı day key'i)
    best = arr.find(m => m.season === targetSeason);
    if (best) return best;
    // 3. Sezon bilgisi yoksa: bugün playedAt olan
    const todayMs = today00.getTime();
    const tomorrowMs = todayMs + 86400000;
    best = arr.find(m => {
      const pAt = m.playedAt || 0;
      return pAt >= todayMs && pAt < tomorrowMs;
    });
    if (best) return best;
    // 4. En son tercih: en yeni playedAt
    return arr.sort((a, b) => (b.playedAt || 0) - (a.playedAt || 0))[0];
  }

  // Kullanıcının ülkesinin TÜM liglerinin bugünkü maçlarını topla
  // 🆕 Veri kaynağı: _matchStateCache (Supabase). Lokal buildLeagueFixture KULLANILMAZ.
  const todayMatches = [];
  const today00 = new Date();
  today00.setHours(0, 0, 0, 0);
  const tomorrow00 = new Date(today00.getTime() + 86400000);
  const seasonInfoToday = info.dayInSeason;

  // _matchStateCache'ten bu kullanıcının ülkesinin bugünkü maçlarını al
  if (_matchStateCache && _matchStateCache.dayMap) {
    const dayMatches = _matchStateCache.dayMap[seasonInfoToday] || [];
    dayMatches.forEach(m => {
      if (m.countryCode !== userCC) return;
      if (m.tournament_key) return; // turnuva ayrı render edilir
      
      const kickoffMs = m.matchDateTime ? new Date(m.matchDateTime).getTime() : 0;
      const _d = m.matchDateTime ? new Date(m.matchDateTime) : new Date();
      if (_d < today00 || _d >= tomorrow00) return;
      
      const _h = String(_d.getHours()).padStart(2, '0');
      const _mn = String(_d.getMinutes()).padStart(2, '0');
      const matchTimeStr = `${_h}:${_mn}`;
      
      // tier 1-based → leagues array index (0-based)
      const tierIdx = country.leagues.findIndex(l => l.tier === m.tier);
      const lg = tierIdx >= 0 ? country.leagues[tierIdx] : null;
      
      // Takım nesnelerini bul
      const homeTeam = (lg && lg.teams.find(t => t.name === m.home)) || { name: m.home, short: m.homeShort };
      const awayTeam = (lg && lg.teams.find(t => t.name === m.away)) || { name: m.away, short: m.awayShort };
      
      const day = m.day;
      const cacheKey = `${info.season}_${day}_${m.home}_${m.away}`;
      const cached = findCachedMatch(m.home, m.away, info.season, day);
      
      const nowMs = Date.now();
      // Canlı durum: match_state'te status='running' VEYA kickoff geçti ama match_results'ta yok
      const isLive = m.status === 'running' || 
                     (!cached && nowMs >= kickoffMs && nowMs < kickoffMs + 95*60*1000);
      
      todayMatches.push({
        home: homeTeam,
        away: awayTeam,
        leagueName: lg ? lg.name : m.leagueName,
        flag: country.flag,
        tierIdx,
        day,
        cacheKey,
        kickoffMs,
        scheduledTime: matchTimeStr,
        played: !!cached,
        isLive,
        hs: cached ? cached.hs : (m.status === 'running' ? m.home_score : null),
        as: cached ? cached.as : (m.status === 'running' ? m.away_score : null),
        playedAt: cached ? cached.playedAt : null,
        isUserMatch: !!(typeof _userTeam !== 'undefined' && _userTeam && (
          m.home === _userTeam.teamName || m.away === _userTeam.teamName
        ))
      });
    });
  }

  if (todayMatches.length === 0) {
    wrap.innerHTML = `<div class="home-empty-card">
      <div class="hec-icon">⚽</div>
      <div class="hec-title">Bugün Maç Yok</div>
      <div class="hec-sub">${country.flag} ${country.leagues[0].name} bugün maç yapmıyor. Yarın yeni maçlar var.</div>
    </div>`;
    return;
  }

  // 🚫 Otomatik simülasyon bloku KALDIRILDI.
  // Frontend bot-bot maçlarını lokal olarak üretmez.
  // Tüm maçlar Supabase Edge Function (tick-matches) tarafından oynanır,
  // sonuçlar match_state üzerinden cache'e (match_results) yansır.

  // Sıralama:
  //   1. CANLI maçlar en başta (kickoff'u en eski olan üstte)
  //   2. Diğer maçlar saatine göre
  todayMatches.sort((a, b) => {
    if (a.isLive && !b.isLive) return -1;
    if (!a.isLive && b.isLive) return 1;
    const ta = a.played && a.playedAt ? new Date(a.playedAt).toTimeString().slice(0, 5) : (a.scheduledTime || '99:99');
    const tb = b.played && b.playedAt ? new Date(b.playedAt).toTimeString().slice(0, 5) : (b.scheduledTime || '99:99');
    return ta.localeCompare(tb);
  });

  // 🆕 Global dizide sakla — kart tıklandığında veriye erişim için
  window._hmTodayMatches = todayMatches;

  const cards = todayMatches.map((m, idx) => {
    const homeShort = (m.home.short || m.home.name.slice(0, 3)).toUpperCase();
    const awayShort = (m.away.short || m.away.name.slice(0, 3)).toUpperCase();
    const userClass = m.isUserMatch ? ' playable' : '';
    const liveClass = m.isLive ? ' live' : '';

    // 🆕 Hava ikonu — maç tarihi + ev sahibi ülke kodu
    let weatherIcon = '';
    try {
      if (typeof pickWeatherForDate === 'function') {
        const matchDate = m.kickoff ? new Date(m.kickoff) : new Date();
        const homeCC = (m.home && (m.home.countryCode || m.home.cc)) || (m.countryCode) || 'TR';
        const seed = `${m.home.name}|${m.away.name}|${matchDate.toDateString()}`;
        const w = pickWeatherForDate(seed, matchDate, homeCC);
        if (w && w.label) {
          const m2 = w.label.match(/^(\S+)/u);
          weatherIcon = m2 ? m2[1] : '';
        }
      }
    } catch(e) {}

    let scoreCell, timeStr;
    if (m.played) {
      scoreCell = `<div class="match-score" style="font-size:22px;color:var(--text)">${m.hs} - ${m.as}</div>`;
      timeStr = _getMatchHM(m);
    } else if (m.isLive) {
      // CANLI: 🔴 CANLI etiketi
      scoreCell = `<div class="match-score" style="font-size:14px;color:#ef5350;font-weight:900;letter-spacing:1px">🔴 CANLI</div>`;
      timeStr = _getMatchHM(m);
    } else {
      scoreCell = `<div class="match-score" style="font-size:18px;color:var(--text2)">vs</div>`;
      timeStr = _getMatchHM(m);
    }

    let dotColor, labelPrefix;
    if (m.isLive) {
      dotColor = '#ef5350';
      labelPrefix = '🔴 ';
    } else if (m.isUserMatch) {
      dotColor = 'var(--gold)';
      labelPrefix = '⭐ Senin Maçın · ';
    } else {
      dotColor = 'var(--accent2)';
      labelPrefix = '';
    }

    // Hava badge: saat altına eklenir
    const timeWithWeather = weatherIcon
      ? `${timeStr} <span style="opacity:.7;margin-left:4px">${weatherIcon}</span>`
      : timeStr;

    return `
      <div class="match-card${userClass}${liveClass}" onclick="hmOpenMatchCard(${idx})">
        <div class="match-league"><div class="match-league-dot" style="background:${dotColor}"></div><span class="match-league-text">${labelPrefix}${m.flag} ${m.leagueName}</span></div>
        <div class="match-teams">
          <div class="match-team"><div class="team-logo-sm c1">${homeShort}</div><div class="match-team-name">${m.home.name}</div></div>
          <div>${scoreCell}<div class="match-score-sub">${timeWithWeather}</div></div>
          <div class="match-team"><div class="team-logo-sm c2">${awayShort}</div><div class="match-team-name">${m.away.name}</div></div>
        </div>
      </div>
    `;
  });

  wrap.innerHTML = cards.join('');
}

// 🆕 Günün maçları kartına tıklayınca akıllı dallandırma:
//   - Cache'te varsa → maç detayını göster (skor + istatistik)
//   - Saat gelmediyse → toast bildirimi
//   - Saat geldi cache yok → simulate + detay göster
function hmOpenMatchCard(idx) {
  const m = (window._hmTodayMatches || [])[idx];
  if (!m) return;

  // 🆕 CANLI BOT MAÇI → live overlay (gerçek motor) ile izle
  // Kullanıcı maçı CANLI durumdaysa → maç ekranı (oynayabilsin) açılsın (mevcut akış devam)
  if (m.isLive && !m.isUserMatch) {
    const matchData = {
      home: m.home.name,
      away: m.away.name,
      homeShort: m.home.short,
      awayShort: m.away.short,
      scheduledTime: m.scheduledTime,
      season: (typeof getSeasonInfo === 'function') ? (getSeasonInfo().season || 1) : 1,
      day: m.day,
      leagueName: m.leagueName,
      leagueFlag: m.flag,
      countryCode: (typeof _userTeam !== 'undefined' && _userTeam && _userTeam.countryCode) || 'TR',
      tierIdx: m.tierIdx
    };
    if (typeof liveMatchOpen === 'function') {
      liveMatchOpen(matchData, m.kickoffMs);
      return;
    }
  }

  // Kickoff Date hesapla
  const today = new Date();
  const [hh, mm] = (m.scheduledTime || '15:00').split(':').map(n => parseInt(n) || 0);
  const kickoff = new Date(today.getFullYear(), today.getMonth(), today.getDate(), hh, mm, 0, 0);

  // Cache kontrolü
  const info = (typeof getSeasonInfo === 'function') ? getSeasonInfo() : { season: 1, dayInSeason: 1 };
  const season = info.season || 1;
  // 🆕 m.cacheKey ve m.day fixture'tan geldi (renderHomeMatches'te set edildi)
  const day = (typeof m.day === 'number') ? m.day : (info.dayInSeason || 1);
  let cache = {};
  try { cache = _matchResultsLoad(); } catch(e) {}
  const cacheKey = m.cacheKey || `${season}_${day}_${m.home.name}_${m.away.name}`;

  // 🆕 Garanti bulma: takım çiftine göre cache'i tara (eski format key'leri için)
  function _hmFindCached() {
    if (cache[cacheKey]) return cache[cacheKey];
    // Aynı sezon + takım çifti
    for (const k in cache) {
      const v = cache[k];
      if (v && v.season === season && v.home === m.home.name && v.away === m.away.name) return v;
    }
    // Sadece takım çifti (sezon bilgisi yok eski cache'ler için)
    for (const k in cache) {
      const v = cache[k];
      if (v && v.home === m.home.name && v.away === m.away.name && typeof v.hs === 'number') return v;
    }
    return null;
  }
  const _existingCached = _hmFindCached();

  // Maç saati henüz gelmediyse → toast bildirimi (kullanıcı maçı dahil)
  if (!_existingCached && Date.now() < kickoff.getTime() - 60000) {
    const days = ['Paz','Pzt','Sal','Çar','Per','Cum','Cmt'];
    const months = ['Oca','Şub','Mar','Nis','May','Haz','Tem','Ağu','Eyl','Eki','Kas','Ara'];
    const dateStr = `${kickoff.getDate()} ${months[kickoff.getMonth()]} ${days[kickoff.getDay()]}`;
    const timeStr = m.scheduledTime || '—';
    if (typeof showJoinToast === 'function') {
      showJoinToast(`⏰ ${m.home.name} vs ${m.away.name} · ${dateStr} ${timeStr}'de başlayacak`);
    } else {
      alert(`Maç ${dateStr} ${timeStr}'de başlayacak`);
    }
    return;
  }

  // 🚫 Otomatik simulate bloku KALDIRILDI. Frontend skor üretmez.
  // Cache yoksa, Edge Function maçı oynamamış demektir → cache'te kalmaz, UI "henüz oynanmadı" der.

  // Match-screen'i aç + cache'ten detayları yansıt
  const cached = _existingCached || cache[cacheKey];

  // 🆕 Cache hit + kullanıcı maçı değil (veya kullanıcı maçı ama bot tarafından oynandı)
  // → match-screen yerine doğrudan maç sonu ekranını aç (SONUÇLAR-tarzı)
  // Kullanıcı maçı oynanmadıysa (preview) → eski match-screen akışı devam eder
  if (cached && typeof showHistoricalMatchResult === 'function') {
    // SONUÇLAR sayfasındaki gibi: ödül gizli, "Listeye Geri Dön" butonu (ana sayfaya döner)
    const matchObj = {
      season, day,
      home: { name: m.home.name, short: m.home.short || (m.home.name||'').slice(0,3).toUpperCase(), rating: m.home.rating || 75 },
      away: { name: m.away.name, short: m.away.short || (m.away.name||'').slice(0,3).toUpperCase(), rating: m.away.rating || 75 },
      hs: cached.hs, as: cached.as,
      isPast: true,
      comp: m.leagueName || '',
      competition: 'league'
    };
    if (typeof MS !== 'undefined') {
      MS._fromResults = true; // ödül gizle
      MS._returnMode = 'home'; // Ana Sayfa butonu
      // 🆕 Tıklama anındaki scroll konumunu kaydet — geri dönünce aynı yere scroll
      MS._returnScrollY = window.scrollY || document.documentElement.scrollTop || 0;
    }
    showHistoricalMatchResult(matchObj, null);
    return;
  }

  if (typeof openMatchScreen === 'function') {
    const venue = (m.home.name || 'Stadyum') + ' Stadyumu';
    const compFull = `⚽ ${m.leagueName || 'Lig'}`;

    // openMatchScreen v1: (homeName, awayName, hClass, aClass, hShort, aShort, league, venue, kickoffDate)
    openMatchScreen(
      m.home.name, m.away.name,
      'c1', 'c2',
      (m.home.short || m.home.name.slice(0,3)).toUpperCase(),
      (m.away.short || m.away.name.slice(0,3)).toUpperCase(),
      compFull, venue, kickoff
    );

    // MS state'e fixture ref kaydet (maç sonu cache yazımı için, ama zaten cache'de var)
    if (typeof MS !== 'undefined') {
      MS._fixtureRef = {
        season, day,
        comp: compFull,
        round: 'Hafta ' + (m.week || 1)
      };
    }

    // Cache hit ise: maç oynanmış → skor + istatistik + İstatistik sekmesi
    if (cached) {
      setTimeout(() => {
        const ms = document.getElementById('match-screen');
        if (ms) ms.classList.remove('preview-mode');

        const sH = document.getElementById('scoreH');
        const sA = document.getElementById('scoreA');
        const clk = document.getElementById('matchClock');
        const sb = document.getElementById('statusBadge');
        const btnStart = document.getElementById('btnStart');
        if (sH) sH.textContent = String(cached.hs);
        if (sA) sA.textContent = String(cached.as);
        if (clk) { clk.textContent = "90'"; clk.className = 'match-clock'; }
        if (sb) { sb.className = 'status-badge sb-ft'; sb.innerHTML = '🏁 Maç Sonu'; }
        if (btnStart) { btnStart.disabled = true; btnStart.textContent = '✓ Tamamlandı'; }

        // İstatistik DOM'unu kur + cache verisi ile doldur
        try {
          if (typeof initStats === 'function') initStats();
          if (cached.stats && typeof updateStats === 'function') {
            updateStats(cached.stats, 1);
          }
        } catch(e) {}

        // Olaylar listesini cache'ten doldur
        try {
          const evList = document.getElementById('evList');
          if (evList && cached.events && cached.events.length) {
            evList.innerHTML = '';
            const sortedEv = [...cached.events].sort((a,b) => (a.min||0) - (b.min||0));
            sortedEv.forEach(ev => {
              try { if (typeof addEvent === 'function') addEvent(ev); } catch(e) {}
            });
            if (!evList.children.length) {
              evList.innerHTML = '<div style="padding:30px 16px;text-align:center;color:var(--text3);font-size:12px">Maç tamamlandı — özel olay kaydı yok</div>';
            }
          } else if (evList) {
            evList.innerHTML = '<div style="padding:30px 16px;text-align:center;color:var(--text3);font-size:12px">Maç tamamlandı — olay kaydı yok</div>';
          }
        } catch(e) {}

        // Olaylar sekmesini ilk açık göster
        try {
          const tabs = document.querySelectorAll('.eng-tab');
          if (tabs && tabs.length >= 1 && typeof showEngTab === 'function') {
            showEngTab('events', tabs[0]);
          }
        } catch(e) {}
      }, 50);
    }
    // Cache yoksa: hmOpenMatchCard yukarıda her maç için simulate yapar — buraya gelinmemeli
  }
}
function renderHomeStats() {
  // Stats row (Sıralama/Puan/Gol Farkı) ana sayfadan kaldırıldı
  // Lig sayfasında zaten görüntüleniyor
}

// HOME — Avrupa Sahnesi (Lig Sahnesi modeli, aşama-bilinçli)
// Her turnuva kartı bugünün aşamasına göre içerik gösterir:
//  - Playoff aşaması: ilk 5 playoff eşleşmesi
//  - Grup aşaması: kullanıcının grubu (yoksa Grup A) standings
//  - Eleme turu (Son 16 / Çeyrek / Yarı / Final): o turun ilk 5 eşleşmesi
function renderHomeEuro() {
  const wrap = document.getElementById('homeEuroStrip');
  if(!wrap) return;
  const info = getSeasonInfo();
  // 🆕 529 — Kulüp turnuvaları (CHM/ELI/CON) 39. günden itibaren YENİ sezonu
  //   gösterir; EURO Nations Cup finali 40. günde oynandığı için o gerçek
  //   sezonda kalır.
  const _kupaSezon = (typeof _trnGosterSezon === 'function') ? _trnGosterSezon('champ')
    : ((typeof _etkinSezon === 'function') ? _etkinSezon() : info.season);

  if(info.preSeason) {
    _hmYaz(wrap, `
      <div class="home-empty-card">
        <div class="hec-icon">⏳</div>
        <div class="hec-title">Avrupa Sahnesi Bekleniyor</div>
        <div class="hec-sub">Sezon başlangıcına ${info.daysToStart||0} gün — turnuvalar 1. sezon sonunda hak kazananlarla başlar.</div>
      </div>
    `);
    return;
  }

  // Hak kazananlar var mı?
  let qual;
  try { qual = trn2GetQualifiers(_kupaSezon); } catch(e) { qual = null; }
  if (!qual || (!qual.champ.length && !qual.elite.length && !qual.conv.length)) {
    _hmYaz(wrap, `
      <div class="home-empty-card">
        <div class="hec-icon">🏆</div>
        <div class="hec-title">Avrupa Eşleşmeleri Hazır Değil</div>
        <div class="hec-sub">İlk sezon henüz tamamlanmadı — hak kazananlar belirleniyor.</div>
      </div>
    `);
    return;
  }

  const TRN_DEFS = [
    { key: 'champ', type: 'chm', label: 'Championship', tierColor: '#ffd54f', tier: 'CHM', logoKey: 'champ',  isEuro: false },
    { key: 'elite', type: 'eli', label: 'Elite',        tierColor: '#90caf9', tier: 'ELI', logoKey: 'elite',  isEuro: false },
    { key: 'conv',  type: 'con', label: 'Convergence',  tierColor: '#a5d6a7', tier: 'CON', logoKey: 'conv',   isEuro: false }
  ];
  // 🆕 EURO Nationals Cup — sadece Sezon 2+'dan itibaren
  if (info.season >= 2) {
    TRN_DEFS.push({ key: 'euro', type: 'enc', label: 'EURO Cup', tierColor: '#ce93d8', tier: 'EUR', logoKey: 'natcup', isEuro: true });
  }

  const userTeamName = (typeof _userTeam !== 'undefined' && _userTeam) ? _userTeam.teamName : null;
  // 🔑 ESKİ HATA: EURO Cup için KULÜBÜN ülkesi kullanılıyordu. Türk liginde
  //    oynayan bir Alman'a Türkiye'nin grubu gösteriliyordu. Milli takım
  //    turnuvasında ölçüt KULÜP değil UYRUKTUR.
  const userCountry  = (typeof getUserNationalityCC === 'function' && getUserNationalityCC())
                     || ((typeof authUser !== 'undefined' && authUser)
                          ? (authUser.nationality || authUser.countryCode) : null)
                     || ((typeof _userTeam !== 'undefined' && _userTeam) ? _userTeam.countryCode : null);

  const cards = TRN_DEFS.map(def => {
    const stage = _euGetCurrentStage(def.type, info.dayInSeason);
    let kartEk = '';
    let bodyHtml = '';
    let stageLabel = 'Grup Aşaması';
    let userInTrn = false;

    if (def.isEuro) {
      // ─── EURO Nationals Cup ───
      // Playoff yok, sadece group + knockout
      if (stage.type === 'group') {
        const r = _euRenderEuroGroupMini(info.season, userCountry);
        bodyHtml = r.html;
        userInTrn = r.userIn;
        stageLabel = String(stage.round || 'Grup Aşaması').replace(/\s*🎲/u, '');
        if (r.bekle) kartEk = ' enc-bekle';
      } else {
        // knockout: Son 16, Çeyrek, Yarı, Final
        const r = _euRenderEuroKnockoutMini(info.season, userCountry, stage.round);
        bodyHtml = r.html;
        userInTrn = r.userIn;
        stageLabel = stage.round || 'Eleme';
      }
    } else {
      // ─── Kulüp turnuvası (chm/eli/con) ───
      if (stage.type === 'playoff') {
        const r = _euRenderPlayoffMini(def.key, _kupaSezon, userTeamName);
        bodyHtml = r.html;
        userInTrn = r.userIn;
        stageLabel = 'Play-off';
      } else if (stage.type === 'po2') {
        const r = _euRenderPlayoff2Mini(def.key, _kupaSezon, userTeamName);
        bodyHtml = r.html;
        userInTrn = r.userIn;
        stageLabel = 'Play-off 2';
      } else if (stage.type === 'group') {
        const r = _euRenderGroupMini(def.key, _kupaSezon, userTeamName);
        bodyHtml = r.html;
        userInTrn = r.userIn;
        stageLabel = stage.round || 'Grup Aşaması';
      } else if (stage.type === 'knockout') {
        const r = _euRenderKnockoutMini(def.key, _kupaSezon, userTeamName, stage.round);
        bodyHtml = r.html;
        userInTrn = r.userIn;
        stageLabel = stage.round || 'Eleme';
      }
    }

    // 🆕 Turnuva logosu (kullanıcı yüklediği gerçek logolar)
    const logoHtml = (typeof _cupLogoIMG === 'function')
      ? _cupLogoIMG(def.logoKey, 24)
      : `<span style="font-family:Twemoji Country Flags,'Barlow Condensed';font-size:11px;font-weight:900;color:#0e0e16;background:${def.tierColor};padding:2px 4px;border-radius:4px">${def.tier}</span>`;

    return `
      <div class="lg-scene-card${kartEk}" data-kupa="${def.key}" data-user="${userInTrn ? '1' : '0'}">
        ${_banBant(def.logoKey, `${def.label} · ${stageLabel}`, _BAN_ALT[def.logoKey],
          `<button class="bnt-go" onclick="event.stopPropagation();_euSceneOpen('${def.key}')" title="Turnuva sayfasına git" aria-label="${def.label} turnuvasına git"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><line x1="7" y1="17" x2="17" y2="7"/><polyline points="7 7 17 7 17 17"/></svg></button>`)}
        <div class="lg-scene-list">${bodyHtml}</div>
      </div>
    `;
  }).join('');

  _hmYaz(wrap, cards);
}

// Bugünün turnuva aşamasını belirle.
// 🆕 ÖNCE tournament_state.phase (gerçek aşama — server tek kaynak), SONRA takvim fallback.
//   phase: playoff(PO1) | po2 | group | r32/r16/qf/sf | final
// 🆕 AŞAMA SIRASI — hem phase alanı hem fikstür için ortak ölçek
const _TRN_PHASE_ORDER = ['playoff','po2','group','r32','r16','qf','sf','final'];

// 🆕 Fikstürden gerçek aşama: kurulmuş EN İLERİ tur.
//   tournament_state.phase bazı turnuvalarda geride kalabiliyor (sunucu yalnızca
//   bazılarını ilerletiyor); fikstür ise turlar kurulunca doluyor. İkisinin
//   ilerisini alıyoruz — böylece Elite/Convergence de doğru aşamayı gösteriyor.
function _trnPhaseFromFixture(tkey, season) {
  try {
    if (typeof _tournamentStateGet !== 'function') return null;
    const st = _tournamentStateGet(tkey, season);
    const fx = (st && st.fixture) ? st.fixture : null;
    if (!fx) return null;
    const ko = (tkey === 'champ') ? ['r16','qf','sf','final'] : ['r32','r16','qf','sf','final'];
    let last = null;
    for (const ph of ko) {
      const pairs = fx[ph];
      if (Array.isArray(pairs) && pairs.length > 0) last = ph;
    }
    if (last) return last;
    if (fx.groups || fx.groupMatches) return 'group';
    if (fx.playoff2) return 'po2';
    if (fx.playoff) return 'playoff';
  } catch(e) {}
  return null;
}

// 🆕 Turnuvanın güncel aşaması — phase ile fikstürün İLERİ olanı
function _trnGuncelFaz(tkey, season) {
  let ph = null;
  try {
    const st = (typeof _tournamentStateGet === 'function') ? _tournamentStateGet(tkey, season) : null;
    if (st && st.phase) ph = st.phase;
  } catch(e) {}
  const fx = _trnPhaseFromFixture(tkey, season);
  const i1 = _TRN_PHASE_ORDER.indexOf(ph);
  const i2 = _TRN_PHASE_ORDER.indexOf(fx);
  if (i1 < 0 && i2 < 0) return null;
  return _TRN_PHASE_ORDER[Math.max(i1, i2)];
}
window._trnGuncelFaz = _trnGuncelFaz;

function _euGetCurrentStage(type, dayInSeason) {
  // 1) Gerçek aşama — tournament_state.phase VE fikstürün ilerisi (takvim değil)
  const _tkeyMap = { chm: 'champ', eli: 'elite', con: 'conv' };
  const _tkey = _tkeyMap[type];
  if (_tkey && typeof getSeasonInfo === 'function') {
    const _season = (typeof _trnGosterSezon === 'function') ? _trnGosterSezon(_tkey)
      : ((typeof _etkinSezon === 'function') ? _etkinSezon() : getSeasonInfo().season);
    const ph = _trnGuncelFaz(_tkey, _season);
    if (ph) {
      if (ph === 'playoff') return { type: 'playoff',  round: 'Play-off',   day: 0 };
      if (ph === 'po2')     return { type: 'po2',      round: 'Play-off 2', day: 0 };
      if (ph === 'group')   return { type: 'group',    round: 'Grup Aşaması', day: 0 };
      // r32/r16/qf/sf/final → knockout
      const _knLabel = { r32:'Son 32', r16:'Son 16', qf:'Çeyrek Final', sf:'Yarı Final', final:'Final' }[ph];
      if (_knLabel) return { type: 'knockout', round: _knLabel, day: 0 };
    }
  }

  // 2) Takvim fallback (phase yoksa — turnuva henüz kurulmamış)
  if (typeof SEASON_TEMPLATE === 'undefined') return { type: 'group', round: 'Grup Aşaması', day: 0 };

  let foundDay = null, foundRound = null;
  for (let d = dayInSeason; d >= 1; d--) {
    const evs = SEASON_TEMPLATE[d] || [];
    const ev = evs.find(e => e && e.type === type);
    if (ev) { foundDay = d; foundRound = ev.round || ''; break; }
  }
  if (!foundRound) {
    for (let d = dayInSeason + 1; d <= 40; d++) {
      const evs = SEASON_TEMPLATE[d] || [];
      const ev = evs.find(e => e && e.type === type);
      if (ev) { foundDay = d; foundRound = ev.round || ''; break; }
    }
  }
  if (!foundRound) return { type: 'group', round: 'Grup Aşaması', day: 0 };

  if (/Play-off 2/i.test(foundRound)) return { type: 'po2',     round: foundRound, day: foundDay };
  if (/Play-off/i.test(foundRound))   return { type: 'playoff', round: foundRound, day: foundDay };
  if (/Grup|Kura/i.test(foundRound))  return { type: 'group',   round: foundRound, day: foundDay };
  return { type: 'knockout', round: foundRound, day: foundDay };
}

// Maç satırı (playoff ve knockout için ortak format)
// ═══════════════════════════════════════════════════════════════
// 🆕 ŞAMPİYON BLOĞU (tasarım B · Podyum)
//   Final maçı oynanmışsa kartın altına eklenir. Kart genişliği ve
//   şekli değişmez; yalnızca alta bir bölüm gelir.
//   Kulüp turnuvalarında takım logosu, EURO Cup'ta ülke bayrağı.
// ═══════════════════════════════════════════════════════════════
// Turnuva parıltı renkleri — CHM mavi · ELI turuncu · CON yeşil · EURO altın
const _SB_ISIK = {
  champ: 'rgba(61,139,255,.80)',
  elite: 'rgba(255,122,26,.80)',
  conv:  'rgba(0,230,118,.75)',
  enc:   'rgba(255,214,0,.80)'
};
// (519) KULÜP TURNUVALARI · şampiyon bölümü "buğulu kupa" tasarımı:
//   arkada turnuvanın kupalı görseli bulanık/karartılmış, sağda kupa net, solda büyük
//   logo turnuva renginde parlıyor; altta ortalı "ŞAMPİYON · takım adı".
//   Görseller _CUP_BANNERS'tan (turnuvalar sayfasıyla aynı) — tek sefer CSS'e basılır.
// Kupa kırpıntıları (turnuva görsellerinden, yazısız) — net kupa katmanı için
// 957 — kupa kırpıntıları medya/g957/ dosyalarında
const _SB_KUPA_IMG = {
  champ: 'medya/g957/sbkupa-champ.7d7aa3d1.jpg',
  elite: 'medya/g957/sbkupa-elite.4fc00654.jpg',
  conv:  'medya/g957/sbkupa-conv.e19c4bc0.jpg',
  natcup: 'medya/g957/sbkupa-natcup.ed696930.jpg'
};
// Kupa kırpıntılarının en/boy oranı (kupa kesilmeden, tam boy sığsın diye)
const _SB_KUPA_ORAN = { champ: '182/240', elite: '182/240', conv: '182/240', natcup: '208/240' };
const _SB_KUPA_ANAHTAR = { champ: 'champ', elite: 'elite', conv: 'conv', enc: 'natcup' };
function _sbKupaCssKur() {
  if (document.getElementById('sbKupaCss') || typeof _CUP_BANNERS === 'undefined') return;
  try {
    const st = document.createElement('style');
    st.id = 'sbKupaCss';
    st.textContent = ['champ', 'elite', 'conv', 'natcup'].map(k => (_CUP_BANNERS[k] && _SB_KUPA_IMG[k])
      ? `.sbk-${k} .sbk-bg{background-image:url(${_CUP_BANNERS[k]})}.sbk-${k} .sbk-kupa{background-image:url(${_SB_KUPA_IMG[k]});aspect-ratio:${_SB_KUPA_ORAN[k]}}`
      : '').join('');
    document.head.appendChild(st);
  } catch (e) {}
}
// (521) Konfeti parçaları — yer/gecikme/süre sabit tohumla (her çizimde aynı, titreme yok)
function _sbKonfeti() {
  let t = 7, h = '';
  const r = () => { t = (t * 9301 + 49297) % 233280; return t / 233280; };
  for (let i = 0; i < 18; i++) {
    h += `<i style="left:${Math.round(2 + r() * 95)}%;animation-delay:${(r() * 3.8).toFixed(2)}s;animation-duration:${(3 + r() * 1.6).toFixed(2)}s"></i>`;
  }
  return h;
}
function _euSampiyonHtml(o) {
  if (!o || !o.ad) return '';
  const _kupaK = _SB_KUPA_ANAHTAR[o.trn];
  if (_kupaK && (o.bayrak ? o.trn === 'enc' : o.trn !== 'enc')) {
    _sbKupaCssKur();
    const ad = String(o.ad);
    const isik = _SB_ISIK[o.trn] || _SB_ISIK.enc;
    let lg;
    if (o.bayrak) {
      // Oyundaki ülke bayrağı (Twemoji Country Flags yazı tipiyle — önizleme paneliyle aynı)
      lg = `<span class="sbk-logo sbk-bayrak">${o.bayrak}</span>`;
    } else {
      lg = (typeof inlineBadge === 'function')
        ? inlineBadge({ cls: 'sbk-logo', name: ad, bg: o.bg || '#37474f', tc: o.tc || '#fff', short: o.kisa || ad.slice(0, 3).toUpperCase() })
        : `<div class="sbk-logo" style="background:${o.bg || '#37474f'};color:${o.tc || '#fff'}">${_escapeHtml(o.kisa || ad.slice(0, 3).toUpperCase())}</div>`;
    }
    return `
    <div class="eu-sampiyon sbk sbk-${_kupaK}" style="--sb-isik:${isik}">
      <div class="sbk-bg"></div><div class="sbk-kon">${_sbKonfeti()}</div><div class="sbk-kupa"></div>
      <div class="sbk-ust">${lg}</div>
      <div class="sbk-alt"><span class="sb-lbl">${o.sezon ? '<span data-noi18n>S' + Number(o.sezon) + '</span> Şampiyonu' : 'Şampiyon'}</span><span class="sb-ad" title="${_escapeHtml(ad)}">${_escapeHtml(ad)}</span></div>
    </div>`;
  }
  const ad = String(o.ad);
  const isik = _SB_ISIK[o.trn] || _SB_ISIK.enc;
  let ic;
  if (o.bayrak) {
    ic = `<div class="sb-logo sb-logo-flag">${o.bayrak}</div>`;
  } else if (typeof inlineBadge === 'function') {
    ic = inlineBadge({ cls: 'sb-logo', name: ad, bg: o.bg || '#37474f',
                       tc: o.tc || '#fff', short: o.kisa || ad.slice(0,3).toUpperCase() });
  } else {
    ic = `<div class="sb-logo" style="background:${o.bg||'#37474f'};color:${o.tc||'#fff'}">${
          _escapeHtml(o.kisa || ad.slice(0,3).toUpperCase())}</div>`;
  }
  return `
    <div class="eu-sampiyon" style="--sb-isik:${isik}">
      <div class="sb-halka">${ic}</div>
      <div class="sb-lbl">Şampiyon</div>
      <div class="sb-ad" title="${_escapeHtml(ad)}">${_escapeHtml(ad)}</div>
    </div>`;
}
window._euSampiyonHtml = _euSampiyonHtml;

function _euMatchRowHtml(m, userTeamName) {
  if (!m || !m.home || !m.away) return '';
  const isUserHome = m.home.name === userTeamName;
  const isUserAway = m.away.name === userTeamName;
  const isUserRow = isUserHome || isUserAway;
  const homeShort = (m.home.short || m.home.name.slice(0,3)).toUpperCase();
  const awayShort = (m.away.short || m.away.name.slice(0,3)).toUpperCase();
  const homeBg = m.home.bg || '#37474f';
  const awayBg = m.away.bg || '#37474f';
  const homeTc = m.home.tc || '#fff';
  const awayTc = m.away.tc || '#fff';
  // Skor: agg (twoLeg) → leg1+leg2, single-leg → hs/as, henüz oynanmadıysa "vs"
  let score = 'vs';
  if (m.leg1 && m.leg2) {
    const aggH = (m.leg1.hs||0) + (m.leg2.as||0);
    const aggA = (m.leg1.as||0) + (m.leg2.hs||0);
    score = `${aggH}-${aggA}`;
  } else if (typeof m.hs === 'number' && typeof m.as === 'number') {
    // (523) oynanmamış eşleşmede hs/as '' geliyor — eskiden "-" yazıyordu
    score = `${m.hs}-${m.as}`;
  }
  if (score !== 'vs' && m.pens && m.pens.homePens != null) {
    score += `<small class="eu-pen" data-noi18n>(${m.pens.homePens}-${m.pens.awayPens} P)</small>`;
  }
  return `
    <div class="lg-scene-row eu-match-row${isUserRow ? ' is-user' : ''}">
      <div class="eu-team-l">
        ${inlineBadge({cls:'eu-crest', name:m.home.name, bg:homeBg, tc:homeTc, short:homeShort})}
        <span class="eu-tname" title="${m.home.name||''}">${m.home.countryFlag||''} ${m.home.name||'—'}</span>
      </div>
      <div class="eu-score">${score}</div>
      <div class="eu-team-r">
        <span class="eu-tname" title="${m.away.name||''}">${m.away.name||'—'} ${m.away.countryFlag||''}</span>
        ${inlineBadge({cls:'eu-crest', name:m.away.name, bg:awayBg, tc:awayTc, short:awayShort})}
      </div>
    </div>
  `;
}

// Playoff aşaması — ilk 5 eşleşme
function _euRenderPlayoffMini(trnKey, season, userTeamName) {
  try {
    const qual = trn2GetQualifiers(season);
    if (!qual[trnKey] || !qual[trnKey].length) return { html: '<div class="lg-scene-empty">Veri yok</div>', userIn: false };
    const playoff = trn2BuildPlayoff(qual[trnKey], season, trnKey);
    if (!playoff || !playoff.length) return { html: '<div class="lg-scene-empty">Eşleşmeler hazırlanıyor</div>', userIn: false };
    let userIn = false;
    // Kullanıcının maçını öne al, en önemli 3 maç göster
    const sorted = playoff.slice();
    sorted.sort((a, b) => {
      const aU = (a.home && a.home.name === userTeamName) || (a.away && a.away.name === userTeamName);
      const bU = (b.home && b.home.name === userTeamName) || (b.away && b.away.name === userTeamName);
      return (bU?1:0) - (aU?1:0);
    });
    const top5 = sorted.slice(0, 5);
    const rows = top5.map(m => {
      const isUser = (m.home && m.home.name === userTeamName) || (m.away && m.away.name === userTeamName);
      if (isUser) userIn = true;
      return _euMatchRowHtml(m, userTeamName);
    }).join('');
    return { html: rows, userIn };
  } catch(e) { return { html: '<div class="lg-scene-empty">Veri okunamadı</div>', userIn: false }; }
}

// 🆕 Play-off 2 aşaması — ilk 5 eşleşme (ELI/CON)
function _euRenderPlayoff2Mini(trnKey, season, userTeamName) {
  try {
    if (typeof trn2BuildPlayoff2 !== 'function') return { html: '<div class="lg-scene-empty">Veri yok</div>', userIn: false };
    const po2 = trn2BuildPlayoff2(trnKey, season);
    if (!po2 || !po2.length) return { html: '<div class="lg-scene-empty">Eşleşmeler hazırlanıyor</div>', userIn: false };
    let userIn = false;
    const sorted = po2.slice();
    sorted.sort((a, b) => {
      const aU = (a.home && a.home.name === userTeamName) || (a.away && a.away.name === userTeamName);
      const bU = (b.home && b.home.name === userTeamName) || (b.away && b.away.name === userTeamName);
      return (bU?1:0) - (aU?1:0);
    });
    const top5 = sorted.slice(0, 5);
    const rows = top5.map(m => {
      const isUser = (m.home && m.home.name === userTeamName) || (m.away && m.away.name === userTeamName);
      if (isUser) userIn = true;
      return _euMatchRowHtml(m, userTeamName);
    }).join('');
    return { html: rows, userIn };
  } catch(e) { return { html: '<div class="lg-scene-empty">Veri okunamadı</div>', userIn: false }; }
}

// Grup aşaması — kullanıcının grubu (yoksa Grup A) standings
function _euRenderGroupMini(trnKey, season, userTeamName) {
  try {
    const qual = trn2GetQualifiers(season);
    if (!qual[trnKey] || !qual[trnKey].length) return { html: '<div class="lg-scene-empty">Veri yok</div>', userIn: false };
    const playoff = trn2BuildPlayoff(qual[trnKey], season, trnKey);
    const winners = playoff.map(m => m.winner).filter(Boolean);
    const groups = trn2BuildGroups(winners, season, trnKey);
    if (!groups || !groups.length) return { html: '<div class="lg-scene-empty">Gruplar hazırlanıyor</div>', userIn: false };

    // Kullanıcının grubu varsa onu, yoksa ilk grup (A)
    let selected = groups[0];
    let userInGroup = false;
    for (const g of groups) {
      if (g.teams && g.teams.some(t => t.name === userTeamName)) {
        selected = g; userInGroup = true; break;
      }
    }

    // Grup etiketi
    const letter = selected.letter || (selected.name || '?').replace('Grup ','').trim();
    const header = `<div class="eu-stage-label">${userInGroup ? '⭐ ' : ''}Grup ${letter}</div>`;

    // Puana göre sırala (eşitlikte averaj, sonra atılan gol) → ilk 4 sıra
    const sortedTeams = (selected.teams || []).slice().sort((a, b) => {
      const ap = a.pts||0, bp = b.pts||0;
      if (bp !== ap) return bp - ap;
      const agd = (a.gd!=null?a.gd:((a.gf||0)-(a.ga||0))), bgd = (b.gd!=null?b.gd:((b.gf||0)-(b.ga||0)));
      if (bgd !== agd) return bgd - agd;
      return (b.gf||0) - (a.gf||0);
    });
    const top4 = sortedTeams.slice(0, 4);

    const rows = top4.map((t, ti) => {
      const isUser = t.name === userTeamName;
      const bg = t.bg || '#37474f', tc = t.tc || '#fff';
      const short = t.short || (t.name||'').slice(0,3).toUpperCase();
      return `
        <div class="lg-scene-row${isUser ? ' is-user' : ''}">
          <div class="lg-scene-rank">${ti+1}</div>
          ${inlineBadge({tag:'div', cls:'lg-scene-crest', name:t.name, bg, tc, short})}
          <div class="lg-scene-tname" title="${t.name||''}">${t.countryFlag||''} ${t.name||'—'}</div>
          <div class="lg-scene-pts">${t.pts||0}</div>
        </div>
      `;
    }).join('');

    return { html: header + rows, userIn: userInGroup };
  } catch(e) { return { html: '<div class="lg-scene-empty">Veri okunamadı</div>', userIn: false }; }
}

// Eleme turu (Son 16 / Çeyrek / Yarı / Final) — o turdaki ilk 5 eşleşme
function _euRenderKnockoutMini(trnKey, season, userTeamName, roundLabel) {
  try {
    const qual = trn2GetQualifiers(season);
    if (!qual[trnKey] || !qual[trnKey].length) return { html: '<div class="lg-scene-empty">Veri yok</div>', userIn: false };
    const playoff = trn2BuildPlayoff(qual[trnKey], season, trnKey);
    const winners = playoff.map(m => m.winner).filter(Boolean);
    const groups = trn2BuildGroups(winners, season, trnKey);
    const bracket = trn2BuildBracket(groups, season, trnKey);
    if (!bracket || !bracket.length) return { html: '<div class="lg-scene-empty">Bracket hazırlanıyor</div>', userIn: false };

    // 🆕 Round label → bracket index — İSİM EŞLEŞMESİYLE.
    //   ESKİ HATA: indeks sabitti (Çeyrek=1, Yarı=2, Final=3). Bu yalnızca
    //   Championship için doğru; Elite/Convergence bracket'i "Son 32" ile
    //   başladığı için tüm turlar bir kayıyordu → başlık "Yarı Final" derken
    //   ekranda Çeyrek Final maçları listeleniyordu.
    const _sad = t => String(t || '').toLocaleLowerCase('tr')
      .replace(/[^a-zçğıöşü0-9]/g, '');
    const _hedef = _sad(roundLabel);
    let roundIdx = bracket.findIndex(r => {
      const n = _sad(r && r.name);
      return n && _hedef && (n.indexOf(_hedef) === 0 || _hedef.indexOf(n) === 0);
    });
    if (roundIdx < 0) {
      // Yedek: eski sıra mantığı, ama bracket uzunluğuna göre kaydırmalı
      const _ofs = (bracket.length >= 5) ? 1 : 0;   // Elite/Conv'de Son 32 var
      if (/Çeyrek/i.test(roundLabel))      roundIdx = 1 + _ofs;
      else if (/Yarı/i.test(roundLabel))   roundIdx = 2 + _ofs;
      else if (/Final/i.test(roundLabel))  roundIdx = 3 + _ofs;
      else if (/Son\s*16/i.test(roundLabel)) roundIdx = 0 + _ofs;
      else roundIdx = 0;
      if (roundIdx >= bracket.length) roundIdx = bracket.length - 1;
    }

    const round = bracket[roundIdx];
    if (!round || !round.matches || !round.matches.length) return { html: '<div class="lg-scene-empty">Tur bilgisi yok</div>', userIn: false };

    // 841 — berabere biten belirleyici maçın uzatma/penaltı bilgisi henüz yoksa iste (kazanan ondan çıkar)
    try {
      const _bek = round.matches.filter(m => m && m.belMk && !m.winner && !m.uzCanli
        && typeof m.hs === 'number' && m.hs === m.as).map(m => m.belMk);
      if (_bek.length) _hmPenIste(_bek);
    } catch(e) {}

    let userIn = false;
    // Kullanıcının maçını öne al, en önemli 3 maç göster
    const sorted = round.matches.slice();
    sorted.sort((a, b) => {
      const aU = (a.home && a.home.name === userTeamName) || (a.away && a.away.name === userTeamName);
      const bU = (b.home && b.home.name === userTeamName) || (b.away && b.away.name === userTeamName);
      return (bU?1:0) - (aU?1:0);
    });
    const top5 = sorted.slice(0, 5);
    const rows = top5.map(m => {
      const isUser = (m.home && m.home.name === userTeamName) || (m.away && m.away.name === userTeamName);
      if (isUser) userIn = true;
      return _euMatchRowHtml(m, userTeamName);
    }).join('');

    // 🆕 FİNAL turu ve maç oynandıysa → şampiyon bloğu
    let sampiyon = '';
    try {
      const _finalTur = /final/i.test(String(round.name || roundLabel || ''))
                     && !/yarı|çeyrek/i.test(String(round.name || roundLabel || ''));
      if (_finalTur && round.matches.length === 1) {
        const fm = round.matches[0];
        let kz = fm.winner || null;
        if (!kz && fm.hs != null && fm.as != null && fm.hs !== fm.as) {
          kz = (fm.hs > fm.as) ? fm.home : fm.away;
        }
        if (!kz && fm.leg1 && fm.leg2) {
          const aH = (fm.leg1.hs||0) + (fm.leg2.as||0);
          const aA = (fm.leg1.as||0) + (fm.leg2.hs||0);
          if (aH !== aA) kz = (aH > aA) ? fm.home : fm.away;
        }
        if (kz && kz.name) {
          sampiyon = _euSampiyonHtml({
            ad: kz.name, kisa: kz.short, bg: kz.bg, tc: kz.tc, bayrak: null, trn: trnKey
          });
        }
      }
    } catch(e) {}

    return { html: rows + sampiyon, userIn };
  } catch(e) { return { html: '<div class="lg-scene-empty">Veri okunamadı</div>', userIn: false }; }
}

// 🆕 SON EURO CUP ŞAMPİYONU
//   Yeni kura çekilene kadar Avrupa Sahnesi'ndeki EURO Cup kutusu boş
//   kalıyordu. Artık kulüp turnuvalarındaki (CHM/ELI/CON) şampiyon
//   rozetinin aynısı gösteriliyor — son şampiyon ülkenin bayrağıyla.
//   encEnsureState sunucuda kayıt yoksa null döner, hiçbir şey üretmez.
// 🆕 559 — Geçmiş sezonun finali: istemcideki maç sonuçları önbelleği yalnız içinde
//   bulunulan sezonu tutuyor. Yeni sezona geçince geçen sezonun final skoru bulunamıyor,
//   şampiyon kartı yerine "Gruplar hazırlanıyor" çıkıyordu. Final sonucu bir kez
//   sunucudan (match_results · enc · final) okunur, gelince kart yeniden çizilir.
const _encFinalSunucu = {};   // sezon → {ad,kod,bayrak,sezon} | false (yok) | null (yükleniyor)
function _encFinalSunucudanYukle(sz) {
  if (!window.sb || _encFinalSunucu[sz] !== undefined) return;
  _encFinalSunucu[sz] = null;
  try {
    window.sb.from('match_results')
      .select('home_team,away_team,home_score,away_score,pensWinner:data->>pensWinner,etWinner:data->>etWinner')
      .eq('season', sz).eq('tournament_key', 'enc').eq('tournament_phase', 'final').limit(1)
      .then(({ data, error }) => {
        const m = (!error && Array.isArray(data)) ? data[0] : null;
        let ad = null;
        if (m) {
          const hs = Number(m.home_score), as = Number(m.away_score);
          if (hs > as) ad = m.home_team;
          else if (as > hs) ad = m.away_team;
          else {
            const w = m.pensWinner || m.etWinner || null;
            if (w === m.home_team || w === m.away_team) ad = w;
          }
        }
        if (!ad) { _encFinalSunucu[sz] = false; return; }
        let kod = null;
        try { for (const cc of _cftGetCountryCodes()) { const c = _cftGetCountry(cc); if (c && c.name === ad) { kod = cc; break; } } } catch(e) {}
        const bayrak = (typeof _hmUlkeBayrak === 'function' && (_hmUlkeBayrak(kod) || _hmUlkeBayrak(ad))) || '🏳️';
        _encFinalSunucu[sz] = { ad, kod, bayrak, sezon: sz };
        try { if (typeof renderHomeEuro === 'function') renderHomeEuro(); } catch(e) {}
      }, () => { _encFinalSunucu[sz] = false; });
  } catch(e) { _encFinalSunucu[sz] = false; }
}
function _encSonSampiyon(season) {
  try {
    if (typeof encEnsureState !== 'function') return null;
    const bu = Number(season) || 0;
    for (let s = bu; s >= 2 && s >= bu - 5; s--) {
      if (_encFinalSunucu[s]) return _encFinalSunucu[s];   // 🆕 559: sunucudan gelen final
      const st = encEnsureState(s);
      const fm = st && st.knockout && st.knockout.final;
      if (!fm) continue;
      if (fm.uz) return null;   // 886 — final uzatma / penaltılarda: şampiyon henüz yok
      let kzKod = null, kzAd = null, kzBayrak = null;
      const _fs = _encSkor(fm);
      if (_fs && _fs.kazanan) {
        const ev = _fs.kazanan === 'home';
        kzKod = ev ? fm.home : fm.away;
        kzAd  = ev ? (fm.homeName || fm.home) : (fm.awayName || fm.away);
        kzBayrak = ev ? fm.homeFlag : fm.awayFlag;
      }
      if (!kzAd) continue;
      if (!kzBayrak && typeof _hmUlkeBayrak === 'function') {
        kzBayrak = _hmUlkeBayrak(kzKod) || _hmUlkeBayrak(kzAd) || '';
      }
      return { ad: kzAd, kod: kzKod, bayrak: kzBayrak || '🏳️', sezon: s };
    }
    // 🆕 559: önbellekte bulunamadı → son sezonların finalini sunucudan iste (bir kez)
    for (let s = bu; s >= 2 && s >= bu - 5; s--) _encFinalSunucudanYukle(s);
  } catch(e) {}
  return null;
}
window._encSonSampiyon = _encSonSampiyon;

// Kura hazır değilken gösterilecek gövde: mesaj + son şampiyon rozeti
// 🆕 544 — EURO Cup kura bekleme ekranı: son şampiyon kartı (final sonrasıyla aynı)
//   + üstte "Yeni turnuvaya N gün kaldı". Kura günü takvimden (SEASON_TEMPLATE).
function _encKuraBekleHtml(sonSezon) {
  const sm = _encSonSampiyon(sonSezon);
  if (!sm) return '';
  let kalan = null;
  try {
    const gun = getSeasonInfo().dayInSeason || 0;
    for (let g = 1; g <= 40; g++) {
      const ev = (SEASON_TEMPLATE[g] || []).find(e => e && e.type === 'enc' && /Kura/i.test(e.round || ''));
      if (ev) { kalan = g - gun; break; }
    }
  } catch(e) {}
  const not = (kalan != null && kalan > 0)
    ? '<span>Yeni turnuvaya</span> <b data-noi18n>' + kalan + '</b> <span>gün kaldı</span>'
    : '<span>Kura bugün çekiliyor</span>';
  return '<div class="enc-bk-not">' + not + '</div>'
       + _euSampiyonHtml({ ad: sm.ad, bayrak: sm.bayrak, trn: 'enc', sezon: sm.sezon });
}

function _encBeklemeHtml(season, mesaj) {
  // (519) Şampiyon bölümü yalnızca final oynandıktan sonra görünür — bekleme
  //   aşamalarında (Son 16 / Çeyrek / Yarı kurası) geçen sezonun şampiyonu gösterilmez.
  return '<div class="lg-scene-empty">' + mesaj + '</div>';
  const sm = _encSonSampiyon(season);
  if (!sm) return '<div class="lg-scene-empty">' + mesaj + '</div>';
  const rozet = (typeof _euSampiyonHtml === 'function')
    ? _euSampiyonHtml({ ad: sm.ad, bayrak: sm.bayrak, trn: 'enc' }) : '';
  return '<div class="lg-scene-empty" style="padding-bottom:4px">' + mesaj + '</div>'
       + rozet
       + '<div class="lg-scene-empty" style="padding-top:2px;font-size:10px;opacity:.75">'
       + 'Sezon ' + sm.sezon + ' şampiyonu</div>';
}

// ─── EURO NATIONALS CUP ───
// Maç formatı kulüp turnuvalarından farklı: { home: 'TR', homeName, homeFlag, hs, as, result, ... }
// Kullanıcı eşleşmesi ülke koduyla (countryCode) yapılır.

// 🆕 523 — ENC maç skoru tek yerden. encEnsureState skorları hg/ag, penaltıyı
//   {homePens, awayPens} olarak verir; kart ve şampiyon kontrolü ise hs/as ve
//   pens dizisi bekliyordu → skor hiç yazılmıyor, şampiyon hiç çıkmıyordu.
function _encSkor(m) {
  if (!m) return null;
  const h = (m.hg != null) ? m.hg : m.hs;
  const a = (m.ag != null) ? m.ag : m.as;
  if (typeof h !== 'number' || typeof a !== 'number') return null;
  if (m.uz) return { h, a, ph: null, pa: null, kazanan: null };   // 886 — uzatma / penaltılar sürüyor
  let ph = null, pa = null;
  if (m.pens) {
    if (Array.isArray(m.pens)) { ph = m.pens[0]; pa = m.pens[1]; }
    else { ph = m.pens.homePens; pa = m.pens.awayPens; }
  }
  let kazanan = (m.result === 'home' || m.result === 'away') ? m.result : null;
  if (!kazanan) {
    if (h > a) kazanan = 'home';
    else if (a > h) kazanan = 'away';
    else if (ph != null && pa != null && ph !== pa) kazanan = ph > pa ? 'home' : 'away';
  }
  return { h, a, ph, pa, kazanan };
}
window._encSkor = _encSkor;

function _euEuroMatchRowHtml(m, userCountry) {
  if (!m) return '';
  const isUserHome = m.home === userCountry;
  const isUserAway = m.away === userCountry;
  const isUserRow = isUserHome || isUserAway;
  const homeShort = (m.home || '??').toUpperCase();
  const awayShort = (m.away || '??').toUpperCase();
  // EURO milli takımları için temalı arka plan (her ülkenin bayrağı belirgin)
  const homeBg = '#37474f', awayBg = '#37474f';
  const homeTc = '#fff', awayTc = '#fff';
  // Skor: hs/as → "vs" eğer yoksa
  let score = 'vs';
  const _sk = _encSkor(m);
  if (_sk) {
    score = `${_sk.h}-${_sk.a}`;
    if (_sk.ph != null && _sk.pa != null) score += `<small class="eu-pen" data-noi18n>(${_sk.ph}-${_sk.pa} P)</small>`;
  }
  return `
    <div class="lg-scene-row eu-match-row${isUserRow ? ' is-user' : ''}">
      <div class="eu-team-l">
        <div class="eu-crest" style="background:transparent!important;border:none!important;box-shadow:none!important;display:flex;align-items:center;justify-content:center;font-size:16px;line-height:1">${m.homeFlag||'🏳️'}</div>
        <span class="eu-tname" title="${m.homeName||''}">${m.homeName||'—'}</span>
      </div>
      <div class="eu-score">${score}</div>
      <div class="eu-team-r">
        <span class="eu-tname" title="${m.awayName||''}">${m.awayName||'—'}</span>
        <div class="eu-crest" style="background:transparent!important;border:none!important;box-shadow:none!important;display:flex;align-items:center;justify-content:center;font-size:16px;line-height:1">${m.awayFlag||'🏳️'}</div>
      </div>
    </div>
  `;
}

// EURO Cup — Grup aşaması (kullanıcı ülkesinin grubu veya Grup A)
function _euRenderEuroGroupMini(season, userCountry) {
  try {
    // Sezon 2'den önce hiç state yok
    if (season < 2) return { html: '<div class="lg-scene-empty">Sezon 2\'de başlar</div>', userIn: false };
    if (typeof encEnsureState !== 'function') return { html: '<div class="lg-scene-empty">Veri yok</div>', userIn: false };

    const state = encEnsureState(season);
    if (!state || !state.groups || !state.groups.length) {
      // 🆕 544 — Kura çekilene kadar son şampiyon kartı + yeni turnuvaya kalan gün
      const _bk = _encKuraBekleHtml(season - 1);
      if (_bk) return { html: _bk, userIn: false, bekle: true };
      return { html: _encBeklemeHtml(season - 1, 'Gruplar hazırlanıyor'), userIn: false };
    }

    // Kullanıcının ülkesinin grubu varsa onu, yoksa Grup A
    let selected = state.groups[0];
    let userInGroup = false;
    if (userCountry) {
      for (const g of state.groups) {
        if ((g.teams || []).some(t => t.code === userCountry)) {
          selected = g; userInGroup = true; break;
        }
      }
    }

    // Standings hesaplama (encCalcStandings)
    let standings = [];
    try {
      if (typeof encCalcStandings === 'function') {
        standings = encCalcStandings(selected);
      } else {
        standings = selected.teams || [];
      }
    } catch(e) { standings = selected.teams || []; }

    const letter = selected.id || (selected.name || '?').replace('Grup ','').trim();
    const header = `<div class="eu-stage-label">${userInGroup ? '⭐ ' : ''}Grup ${letter} · 4 Ülke</div>`;

    // 4 ülke puanlarıyla
    // 🔑 ESKİ HATA: encCalcStandings 'Pts' (büyük harf) döndürüyor, burada
    //    't.pts' okunuyordu → puan hep 0 görünüyordu.
    // 🔧 SADECE PUAN — averaj/oynanan sütunu kaldırıldı.
    //    O ek sütun 4'lü grid'i bozuyor ve satırları kaydırıyordu.
    const rows = standings.map((t, ti) => {
      const isUser = t.code === userCountry;
      const _pts = (typeof t.Pts === 'number') ? t.Pts
                 : ((typeof t.pts === 'number') ? t.pts
                 : ((typeof t.points === 'number') ? t.points : 0));
      return `
        <div class="lg-scene-row${isUser ? ' is-user' : ''}">
          <div class="lg-scene-rank">${ti+1}</div>
          <div class="lg-scene-crest" style="background:transparent!important;border:none!important;box-shadow:none!important;display:flex;align-items:center;justify-content:center;font-size:16px;line-height:1">${t.flag||'🏳️'}</div>
          <div class="lg-scene-tname" title="${t.name||''}">${t.name||'—'}</div>
          <div class="lg-scene-pts">${_pts}</div>
        </div>
      `;
    }).join('');

    // 🆕 Yeşil buton bu grubu açsın (A grubunu değil)
    try { window._euUserGroupLetter = letter; } catch(e) {}

    return { html: header + rows, userIn: userInGroup };
  } catch(e) { return { html: '<div class="lg-scene-empty">Veri okunamadı</div>', userIn: false }; }
}

