function renderFixture() {
  const list = document.getElementById('fixtureList');
  if (!list) return;

  const info = (typeof getSeasonInfo === 'function') ? getSeasonInfo() : { season: 1, dayInSeason: 1 };
  const { season, dayInSeason } = info;
  const SEASON_LEN_L = (typeof SEASON_LEN !== 'undefined') ? SEASON_LEN : 40;

  // Sezon header
  const hdr = document.getElementById('fixSeasonHdr');
  if (hdr) {
    const sNum = document.getElementById('fixSeasonNum'); if (sNum) sNum.textContent = 'Sezon ' + season;
    const sDay = document.getElementById('fixSeasonDay'); if (sDay) sDay.textContent = 'Gün ' + dayInSeason + ' / ' + SEASON_LEN_L;
    const sFill = document.getElementById('fixSeasonFill'); if (sFill) sFill.style.width = (dayInSeason / SEASON_LEN_L * 100).toFixed(0) + '%';
    // 🆕 GERÇEK LİG: teams DB'den (terfi/düşme sonrası güncel), donmuş league_name'den değil
    try {
      const lgLine = document.getElementById('fixLeagueLine');
      if (lgLine && typeof _userTeam !== 'undefined' && _userTeam && _userTeam.countryCode) {
        const c = _cftGetCountry(_userTeam.countryCode);
        let lgName = '', lgFlag = (c && c.flag) || '🏳️', tierNo = null;
        if (c && Array.isArray(c.leagues)) {
          for (const lg of c.leagues) {
            if ((lg.teams || []).some(t => t && t.name === _userTeam.teamName)) {
              lgName = lg.name || ''; tierNo = lg.tier; break;
            }
          }
        }
        lgLine.innerHTML = lgName
          ? (lgFlag + ' <b style="color:var(--text)">' + lgName + '</b>' +
             (tierNo != null ? ' <span style="color:var(--text3)">· Kademe ' + tierNo + '</span>' : ''))
          : '';
      }
    } catch(e) {}
  }

  // Veri yoksa info mesajı
  if (!_matchStateCache || !_matchStateCache.byKey || !_userTeam) {
    list.innerHTML = '<div style="text-align:center;padding:32px;color:var(--text3)">Yükleniyor...</div>';
    return;
  }

  const userTeamName = _userTeam.teamName;
  // 🆕 GERÇEK LİG ADI — match_state.leagueName terfi/düşme sonrası eskimiş
  //   olabiliyor (4. Lig takımına "5. Lig" yazıyordu). Takımın bulunduğu ligi
  //   teams DB'den oku; bulunamazsa satırdaki ada düş.
  let _myLeagueName = null;
  try {
    const _c = (typeof _cftGetCountry === 'function' && _userTeam.countryCode)
      ? _cftGetCountry(_userTeam.countryCode) : null;
    if (_c && Array.isArray(_c.leagues)) {
      for (const lg of _c.leagues) {
        if ((lg.teams || []).some(t => t && t.name === userTeamName)) { _myLeagueName = lg.name || null; break; }
      }
    }
  } catch(e) {}
  // 🆕 Gün → hafta çevirimi (SEASON_TEMPLATE tek kaynak)
  const _haftaOf = (gun) => {
    try {
      const evs = (typeof SEASON_TEMPLATE !== 'undefined') ? (SEASON_TEMPLATE[gun] || []) : [];
      const ev = evs.find(e => e && e.type === 'lig' && e.week);
      if (ev) return ev.week;
    } catch(e) {}
    return gun;
  };
  const DAYS_TR = ['Paz','Pzt','Sal','Çar','Per','Cum','Cmt'];
  const MONTHS_TR = ['Oca','Şub','Mar','Nis','May','Haz','Tem','Ağu','Eyl','Eki','Kas','Ara'];

  // Kullanıcının tüm lig + turnuva maçlarını match_state'ten topla
  const matches = [];
  for (const ms of Object.values(_matchStateCache.byKey)) {
    if (!ms || !ms.matchDateTime) continue;
    if (ms.home !== userTeamName && ms.away !== userTeamName) continue;
    if (ms.tournament_key === 'friendly') continue;
    const t = new Date(ms.matchDateTime).getTime();
    if (isNaN(t)) continue;
    matches.push(ms);
  }
  matches.sort((a, b) => new Date(a.matchDateTime).getTime() - new Date(b.matchDateTime).getTime());

  if (matches.length === 0) {
    list.innerHTML = '<div style="text-align:center;padding:32px;color:var(--text3)">Henüz fikstür yok</div>';
    return;
  }

  // Render
  let html = '';
  for (const ms of matches) {
    const d = new Date(ms.matchDateTime);
    const dayNum = d.getDate();
    const wday = DAYS_TR[d.getDay()];
    const mon = MONTHS_TR[d.getMonth()];
    const hh = String(d.getHours()).padStart(2,'0');
    const mm = String(d.getMinutes()).padStart(2,'0');
    const timeStr = hh + ':' + mm;

    let isFinished = (ms.status === 'finished');
    let isLive = (ms.status === 'running');
    // 886 — eleme maçında uzatma / penaltılar sürerken (izleyici ekranı) maç canlıdır, sonuç yazılmaz
    const _uzF = (isFinished && typeof _uzListeDurum === 'function') ? _uzListeDurum(ms) : null;
    if (_uzF) { isFinished = false; isLive = true; _fxUzPlanla(_uzF.bitis); }
    const isCurrentDay = (ms.day === dayInSeason);
    const isUserHome = (ms.home === userTeamName);

    // Yarışma etiketi
    const TRN_LBL = {
      championship:'Champ.League', champ:'Champ.League',
      elite:'Elite League', conv:'Conv.League', convergence:'Conv.League',
      enc:'EURO Nations', euro:'EURO Cup', natcup:'EURO Nations'
    };
    // 🆕 528 — yeni sezon fikstürü (gün 39'da kurulur) ayırt edilsin
    const _yeniSezon = (ms.season != null && ms.season > season);
    const compLabel = (_yeniSezon ? '🆕 ' + (typeof T === 'function' ? T('Yeni Sezon') : 'Yeni Sezon') + ' · ' : '')
      + (ms.tournament_key
      ? ('🏆 ' + (TRN_LBL[ms.tournament_key] || ms.tournament_key))
      : ('⚽ ' + (_myLeagueName || ms.leagueName || 'Lig')));

    // Card class
    const cardCls = isLive ? 'lg2-fix-card today-card'
                  : isCurrentDay ? 'lg2-fix-card today-card'
                  : isFinished ? 'lg2-fix-card is-past-card'
                  : 'lg2-fix-card';

    // Skor / saat kısmı
    let scorePart;
    if (isFinished) {
      const hs = ms.home_score ?? 0;
      const as_ = ms.away_score ?? 0;
      const userScore = isUserHome ? hs : as_;
      const oppScore = isUserHome ? as_ : hs;
      let resultCls = (userScore > oppScore) ? 'w' : (userScore < oppScore ? 'l' : 'd');
      // 🆕 Eleme maçı berabere bittiyse penaltı sonucunu ve turu geçeni göster
      let _penAlt = '';
      if (ms.tournament_key && hs === as_ && ms.match_key) {
        const _pi = (typeof _penBilgi === 'function') ? _penBilgi(ms.match_key) : null;
        if (_pi && _pi.pens) {
          const _tf = _penKazananTaraf(_pi, ms.home_team, ms.away_team);
          const _benKazandi = (_tf === 'ev') === !!isUserHome;
          if (_tf) resultCls = _benKazandi ? 'w' : 'l';
          _penAlt = '<div class="lg2-fix-pen">P ' + _pi.pens[0] + '-' + _pi.pens[1] + '</div>';
        } else if (_pi === undefined) {
          (window._fxPenBekleyen = window._fxPenBekleyen || []).push(ms.match_key);
        }
      }
      scorePart = '<div class="lg2-fix-sc"><div class="lg2-fix-scv ' + resultCls + '">' + hs + '–' + as_ + '</div>'
                + _penAlt
                + '<div class="lg2-fix-time" style="font-size:9px;color:var(--text3);margin-top:1px">' + timeStr + '</div></div>';
    } else if (isLive) {
      const hs = _uzF ? _uzF.hs : (ms.home_score ?? 0);
      const as_ = _uzF ? _uzF.as : (ms.away_score ?? 0);
      const min = ms.sim_minute || 0;
      scorePart = '<div class="lg2-fix-sc"><div class="lg2-fix-scv" style="color:var(--accent)">' + hs + '–' + as_ + '</div>'
                + '<div class="lg2-fix-time" style="color:var(--accent);font-weight:900;font-size:10px">●' + (_uzF ? (_uzF.metin === 'PEN' ? 'PEN' : 'UZT') : min + "'") + '</div></div>';
    } else if (isCurrentDay) {
      scorePart = '<div class="lg2-fix-sc"><div class="lg2-fix-time" style="color:var(--accent);font-weight:900;font-size:10px">BUGÜN</div>'
                + '<div class="lg2-fix-time" style="color:var(--accent);font-weight:700;font-size:11px">' + timeStr + '</div></div>';
    } else {
      scorePart = '<div class="lg2-fix-sc"><div class="lg2-fix-time" style="font-size:12px;font-weight:700">' + timeStr + '</div></div>';
    }

    // 🆕 Bitmiş maç → tıklanabilir, maç sonu modalını aç (SONUÇLAR ile aynı modal).
    let cardOnclick = '';
    if (isFinished) {
      const mk = ms.matchKey || ms.match_key || `${ms.season}_${ms.day}_${ms.home}_${ms.away}`;
      if (!window._resCurrentMatches) window._resCurrentMatches = {};
      (window._rcmFx958 || (window._rcmFx958 = new Set())).add(mk);   // 958 — kendi fikstür kartlarının anahtarı (lig fikstürü bunları silmez)
      window._resCurrentMatches[mk] = {
        season: ms.season,
        day: ms.day,
        home: ms.home,
        away: ms.away,
        homeShort: (ms.home || '').slice(0,3).toUpperCase(),
        awayShort: (ms.away || '').slice(0,3).toUpperCase(),
        hs: ms.home_score ?? 0,
        as: ms.away_score ?? 0,
        played: true,
        leagueName: ms.tournament_key ? (TRN_LBL[ms.tournament_key] || ms.leagueName || 'Turnuva') : (ms.leagueName || 'Lig'),
        leagueFlag: (!ms.tournament_key && ms.countryCode && typeof _cftGetCountry === 'function' && _cftGetCountry(ms.countryCode)) ? (_cftGetCountry(ms.countryCode).flag || '') : '',
        matchKey: mk,
        countryCode: ms.countryCode,
        tier: ms.tier,
        tournament_key: ms.tournament_key,
        tournament_phase: ms.tournament_phase
      };
      cardOnclick = ' onclick="resOpenFinishedMatch(\'' + String(mk).replace(/'/g, "\\'") + '\')" style="cursor:pointer"';
    }

    html += '<div class="' + cardCls + '"' + cardOnclick + '>'
          + '<div class="lg2-fix-date">'
          +   '<div class="lg2-fix-d">' + dayNum + '</div>'
          +   '<div class="lg2-fix-w">' + mon + '</div>'
          +   '<div class="lg2-fix-w" style="font-size:9px;color:var(--text3);margin-top:-1px">' + wday + '</div>'
          + '</div>'
          + '<div class="lg2-fix-mid">'
          +   '<div class="lg2-fix-week">' + compLabel
          +     (ms.tournament_key ? '' : (' · Hafta ' + _haftaOf(ms.day))) + '</div>'
          +   '<div class="lg2-fix-teams">'
          +     '<div class="lg2-fix-tm">'
          +       inlineBadge({tag:'div', cls:'lg2-fix-ball', name:ms.home})
          +       '<span class="lg2-fix-tmn' + (isUserHome ? ' user-t' : '') + '">' + ms.home + '</span>'
          +     '</div>'
          +     scorePart
          +     '<div class="lg2-fix-tm away-tm">'
          +       inlineBadge({tag:'div', cls:'lg2-fix-ball', name:ms.away})
          +       '<span class="lg2-fix-tmn' + (!isUserHome ? ' user-t' : '') + '">' + ms.away + '</span>'
          +     '</div>'
          +   '</div>'
          + '</div>'
          + '</div>';
  }
  list.innerHTML = '<div class="lg2-fix-container">' + html + '</div>';

  // 🆕 Penaltıya kalan eleme maçlarının bilgisi eksikse tek sorguda çek,
  //    yalnızca yeni bilgi bulunduysa fikstürü bir kez yeniden çiz.
  try {
    const _bek = window._fxPenBekleyen || [];
    window._fxPenBekleyen = [];
    if (_bek.length && typeof _penYukle === 'function' && !window._fxPenYenileme) {
      window._fxPenYenileme = true;
      _penYukle(_bek).then(bulundu => {
        window._fxPenYenileme = false;
        if (bulundu && typeof renderFixture === 'function') {
          try { renderFixture(); } catch(e) {}
        }
      }).catch(() => { window._fxPenYenileme = false; });
    }
  } catch(e) {}

  // 🆕 GÜNCEL HAFTAYA ORTALA — sekme açıldığında liste başında değil,
  //   bugünkü/yaklaşan maçta başlasın. Kullanıcı yukarı-aşağı kaydırarak
  //   önceki ve sonraki haftalara ulaşır.
  try { _fixScrollToCurrent(); } catch(e) {}
}

// 🆕 Fikstürde güncel haftayı ekranın ortasına getir.
//   Not: sekme henüz görünür değilken ölçüm 0 döner; bu yüzden birkaç kez denenir.
function _fixScrollToCurrent(deneme) {
  const n = deneme || 0;
  if (n > 6) return;
  setTimeout(() => {
    try {
      const el = document.getElementById('fixtureList');
      const pane = document.getElementById('team-fixture');
      // Sekme görünür değilse ölçüm yapma, tekrar dene
      if (!el || !el.offsetParent || (pane && pane.style.display === 'none')) {
        return _fixScrollToCurrent(n + 1);
      }
      const kartlar = Array.from(el.querySelectorAll('.lg2-fix-card'));
      if (!kartlar.length) return _fixScrollToCurrent(n + 1);
      // Öncelik: canlı/bugünkü maç → yoksa ilk oynanmamış maç → yoksa son maç
      let hedef = el.querySelector('.lg2-fix-card.today-card')
              || kartlar.find(c => !c.classList.contains('is-past-card'))
              || kartlar[kartlar.length - 1];
      if (!hedef) return;
      // ⚠️ Eskiden `hedef.scrollIntoView(...)` çağrılıyordu. scrollIntoView
      //    hedefi görünür yapmak için ÜST KAPLARIN HEPSİNİ kaydırır —
      //    sayfa da kayıyor, sekme şeridi (Kadro/Diziliş/Sohbet/...)
      //    ekranın üstünden çıkıyordu. Sadece Fikstür'de olmasının sebebi
      //    buydu; diğer sekmeler böyle bir çağrı yapmıyor.
      //    Artık YALNIZCA liste kutusunun kendi scrollTop'u değişiyor.
      const kutuR = el.getBoundingClientRect();
      const kartR = hedef.getBoundingClientRect();
      const ortala = (kartR.top - kutuR.top) + el.scrollTop
                   - (el.clientHeight - kartR.height) / 2;
      const enFazla = Math.max(0, el.scrollHeight - el.clientHeight);
      const yeniTop = Math.max(0, Math.min(ortala, enFazla));
      if (typeof el.scrollTo === 'function') {
        el.scrollTo({ top: yeniTop, behavior: (n === 0 ? 'auto' : 'smooth') });
      } else {
        el.scrollTop = yeniTop;
      }
      // Layout oturduktan sonra bir kez daha (görsel/font yüklemesi kaydırabiliyor)
      if (n === 0) _fixScrollToCurrent(1);
    } catch(e) {}
  }, n === 0 ? 60 : 260);
}
function fixLoadMore(dir) {
  if(window._fixLoadMore) window._fixLoadMore(dir);
}

// 🆕 Takım fikstür sayfası — Hazırlık maçları bölümü (bilgi amaçlı, lig fikstüründen ayrı)
function _renderFriendlyFixtureSection() {
  if (typeof frmGetMatches !== 'function' || typeof _userTeam === 'undefined' || !_userTeam) return '';
  const all = frmGetMatches();
  if (!all.length) return '';

  // Kullanıcının takımıyla ilgili olanlar; +120dk geçmiş accepted maçları gizle
  const NOW = Date.now();
  const filtered = all.filter(m => {
    if (m.fromTeam !== _userTeam.teamName && m.toTeam !== _userTeam.teamName) return false;
    if (m.status === 'accepted') {
      if (m.playedAt) return false; // 🆕 Oynanmış hazırlık maçı
      const t = new Date(m.dateTime).getTime();
      if (!isNaN(t) && NOW > t + 120 * 60 * 1000) return false; // bitti
    }
    if (m.status === 'rejected') {
      // Sadece son 24 saat içindeki red mesajlarını göster
      if (m.respondedAt && NOW - m.respondedAt > 24 * 60 * 60 * 1000) return false;
    }
    return true;
  });
  if (!filtered.length) return '';

  // Sıralama: pending önce, sonra accepted (yakın tarih önce), rejected sona
  const STATUS_ORDER = { pending: 0, accepted: 1, rejected: 2 };
  filtered.sort((a, b) => {
    const sa = STATUS_ORDER[a.status] ?? 9;
    const sb = STATUS_ORDER[b.status] ?? 9;
    if (sa !== sb) return sa - sb;
    return new Date(a.dateTime).getTime() - new Date(b.dateTime).getTime();
  });

  const DAYS = ['Paz','Pzt','Sal','Çar','Per','Cum','Cmt'];
  const MONTHS = ['Oca','Şub','Mar','Nis','May','Haz','Tem','Ağu','Eyl','Eki','Kas','Ara'];

  const rows = filtered.map(m => {
    const isHome = m.fromTeam === _userTeam.teamName;
    const oppName = isHome ? m.toTeam : m.fromTeam;
    const oppShort = isHome ? (m.toShort || oppName.slice(0,3).toUpperCase()) : oppName.slice(0,3).toUpperCase();
    const oppBg = isHome ? (m.toBg || '#37474f') : '#37474f';
    const oppTc = isHome ? (m.toTc || '#fff') : '#fff';
    const venue = isHome ? '🏠' : '✈️';

    const d = new Date(m.dateTime);
    let dateStr = '—', timeStr = '—';
    if (!isNaN(d.getTime())) {
      dateStr = `${DAYS[d.getDay()]} ${d.getDate()} ${MONTHS[d.getMonth()]}`;
      timeStr = `${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;
    }

    let badge = '';
    if (m.status === 'pending') badge = '<span style="background:rgba(255,193,7,.18);color:#ffc107;padding:2px 7px;border-radius:6px;font-size:9px;font-weight:800">⏳ BEKLİYOR</span>';
    else if (m.status === 'accepted') badge = '<span style="background:rgba(0,230,118,.16);color:var(--accent);padding:2px 7px;border-radius:6px;font-size:9px;font-weight:800">✅ ONAYLI</span>';
    else if (m.status === 'rejected') badge = '<span style="background:rgba(239,83,80,.14);color:#ef5350;padding:2px 7px;border-radius:6px;font-size:9px;font-weight:800">❌ REDDEDİLDİ</span>';

    return `<div style="display:flex;align-items:center;gap:10px;padding:9px 12px;border-bottom:1px solid var(--border);${m.status==='rejected'?'opacity:.6;':''}">
      ${inlineBadge({tag:'div', cls:'frm-inb-opp', name:oppName, bg:oppBg, tc:oppTc, short:oppShort})}
      <div style="flex:1;min-width:0">
        <div style="font-size:12px;font-weight:700;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${venue} ${oppName}</div>
        <div style="font-size:10px;color:var(--text3);margin-top:2px">${dateStr} · ${timeStr}</div>
      </div>
      ${badge}
    </div>`;
  }).join('');

  return `<div style="background:var(--card);border:1px solid var(--border);border-radius:12px;margin-bottom:14px;overflow:hidden">
    <div style="padding:10px 14px;background:linear-gradient(135deg,rgba(0,230,118,.08),transparent);border-bottom:1px solid var(--border);display:flex;align-items:center;gap:8px">
      <div style="font-size:16px">⚽</div>
      <div style="font-family:Twemoji Country Flags,'Barlow Condensed',sans-serif;font-size:13px;font-weight:900;color:#ff9800;text-transform:uppercase;letter-spacing:.5px;flex:1">Hazırlık Maçları</div>
      <div style="font-size:10px;color:var(--text3);font-weight:700">${filtered.length}</div>
    </div>
    ${rows}
    <div style="padding:7px 12px;background:var(--bg2);font-size:9px;color:var(--text3);text-align:center;line-height:1.5">
      💡 Hazırlık maçları lig fikstürüne dahil değildir. Sadece bilgi amaçlı listelenir.
    </div>
  </div>`;
}

function fixFilter(type, btn) {
  _fixFilter = type;
  document.querySelectorAll('.fix-filter-btn').forEach(b=>b.classList.remove('active'));
  if(btn) btn.classList.add('active');
  renderFixture();
}

