  const bw = k[2] * f, bh = k[3] * f, cx = (k[0] + k[2] / 2) * f, cy = (k[1] + k[3] / 2) * f;
  const sc = Math.max(1.2, Math.min(2.8, cw * 0.78 / bw, ch * 0.72 / bh));
  const x = Math.min(0, Math.max(cw - cw * sc, cw / 2 - cx * sc)), y = Math.min(0, Math.max(ch - ch * sc, ch / 2 + ch * 0.04 - cy * sc));
