// misafirSev verilirse ziyaretçi görünümü: rozet yok, dokunma yok
function thmHaritaCiz(misafirSev) {
  const kutu = document.getElementById('thmHarita');
  if (!kutu) return;
  const misafir = !!misafirSev, kaynak = misafir ? misafirSev : (typeof FAC_LEVELS !== 'undefined' ? FAC_LEVELS : {});
  if (misafir !== THM.misafir) { THM.sec = null; THM.don = { s: 1, x: 0, y: 0 }; }
  THM.misafir = misafir;
  const yeni = !misafir && window._thmYeni && THM_META.t[window._thmYeni] ? window._thmYeni : null;
  window._thmYeni = null;
  if (yeni) THM.sec = yeni;
  const M = THM_META;
  THM.sev = {}; for (const id of M.sira) THM.sev[id] = thmLv(kaynak, id);
  const resimler = M.sira.map(id => {
    const l = THM.sev[id], k = M.t[id][l - 1][0];
    if (!misafir) _thmAlfa(id, l);
    return `<img data-id="${id}" class="${yeni === id ? 'thm-yeni' : ''}" src="${thmResim(id, l)}" alt="" decoding="async" style="left:${(k[0] / M.W * 100).toFixed(3)}%;top:${(k[1] / M.H * 100).toFixed(3)}%;width:${(k[2] / M.W * 100).toFixed(3)}%;height:${(k[3] / M.H * 100).toFixed(3)}%">`;
  }).join('');
  const _gt = M.sira.reduce((a, id) => a + THM.sev[id], 0), _gp = Math.round(_gt / (M.sira.length * 10) * 100);
  const gelisim = misafir ? `<div class="thm-gelisim${_gp >= 100 ? ' max' : ''}"><span>Gelişim</span><b data-noi18n>%${_gp}</b></div>` : '';   // 670
  const rozet = misafir ? '' : M.sira.map(id => `<div class="thm-rozet${THM.sev[id] >= 10 ? ' max' : ''}${THM.sec === id ? ' sec' : ''}" data-id="${id}">${THM_AD[id]}<b data-noi18n>${THM.sev[id]}</b></div>`).join('')
    + `<div class="thm-insa" data-id="${yeni || ''}" style="${yeni ? '' : 'display:none'}"></div>`
    + '<button type="button" class="thm-kapat" aria-label="Kapat"><svg viewBox="0 0 24 24"><path d="M6 6l12 12M18 6L6 18"/></svg></button>';
  kutu.innerHTML = `<div class="thm-sahne"><img class="thm-zemin" src="${thmResim(null)}" alt="" decoding="async">${resimler}</div>${gelisim}${rozet}`;
  kutu.classList.toggle('zum', !!THM.sec && !misafir);
  _thmUygula(kutu, THM.don);
  _thmZumla(kutu, _thmHedef(kutu));
  _thmKartVurgu();
  if (misafir) { kutu.onclick = null; return; }
  kutu.querySelectorAll('.thm-rozet').forEach(el => el.addEventListener('click', e => { e.stopPropagation(); thmSec(el.dataset.id); }));
  const kp = kutu.querySelector('.thm-kapat'); if (kp) kp.addEventListener('click', e => { e.stopPropagation(); thmSec(null); });
  kutu.onclick = e => {
    if (e.target.closest('.thm-rozet,.thm-kapat')) return;
    const r = kutu.getBoundingClientRect(), f = kutu.clientWidth / M.W, d = THM.don;
    const gx = ((e.clientX - r.left - d.x) / d.s) / f, gy = ((e.clientY - r.top - d.y) / d.s) / f;
    for (const id of M.sira.slice().reverse()) {
      const l = THM.sev[id], k = M.t[id][l - 1][0];
      if (gx < k[0] || gy < k[1] || gx > k[0] + k[2] || gy > k[1] + k[3]) continue;
      const a = _thmAlfaHesap(id + '-' + l);   // 958 — hazır değilse şimdi hesaplanır
      if (!a || typeof a === 'string') { thmSec(id); return; }
      const ix = Math.floor((gx - k[0]) / k[2] * a.width), iy = Math.floor((gy - k[1]) / k[3] * a.height);
      if (a.a[iy * a.width + ix] > 40) { thmSec(id); return; }
    }
    if (THM.sec) thmSec(null);
  };
  if (!window._thmBoyut) { window._thmBoyut = true; window.addEventListener('resize', () => { const k = document.getElementById('thmHarita'); if (k && k.querySelector('.thm-sahne')) _thmUygula(k, _thmHedef(k)); }); }
}

// 670 — ziyaretçi tesis özeti: ad · seviye çubuğu · Sv (geliştirme yok)
function thmOzetCiz(sev) {
  const k = document.getElementById('thmOzet');
  if (!k) return;
  const facs = (typeof FAC_DATA !== 'undefined') ? FAC_DATA : [];
  k.innerHTML = facs.map(f => {
    const l = thmLv(sev, f.id), mx = l >= 10 ? ' max' : '';
    const ik = THM_META.t[f.id] ? `<img src="${thmResim(f.id, l)}" alt="" decoding="async" onerror="this.parentNode.textContent='${f.icon}'">` : f.icon;
    return `<div class="thm-oz-s"><div class="thm-oz-r">${ik}</div><div class="thm-oz-ad">${THM_AD[f.id] || f.name}</div><div class="thm-oz-cb"><b class="${mx.trim()}" style="width:${l * 10}%"></b></div><div class="thm-oz-lv${mx}">Sv ${l}</div></div>`;
  }).join('');
}

// Mevcut seviyeler (localStorage'dan oku veya default)
let FAC_LEVELS = {};

// 🆕 Tesis seviyeleri TAKIM bazlı veri (team_data tablosu, data_key='facilities')
// Bootstrap'ta _userTeam yüklendikten sonra _facLevelsLoadFromServer çağrılır
async function _facLevelsLoadFromServer(toplu) {
  // ⚠️ VERİ KAYBI KORUMASI — 2026-08-18
  //   Yükleme başarısız olduğunda FAC_LEVELS varsayılan seviye-1 değerlerinde
  //   kalıyordu ve saveFacLevels() bunu kontrolsüz yazıyordu: bir tesis
  //   yükseltilince elmasla alınmış DİĞER tüm tesisler 1'e düşüyordu.
  //   Artık yükleme doğrulanmadan kaydetme yapılmıyor.
  window._facLevelsLoadedOk = false;
  if (!window.sb || !_userTeam || !_userTeam.countryCode || !_userTeam.teamName) {
    // Takım yoksa varsayılan: tüm tesisler seviye 1 (yazma kilitli kalır)
    FAC_LEVELS = {};
    if (typeof FAC_DATA !== 'undefined') {
      FAC_DATA.forEach(f => { FAC_LEVELS[f.id] = 1; });
    }
    return;
  }
  try {
    const _t956 = toplu && _tdTopluAl956(_userTeam.countryCode, _userTeam.teamName, 'facilities');   // 956 — ortak team_data yanıtı
    const { data, error } = _t956 ? await _t956 : await window.sb.from('team_data')
      .select('data')
      .eq('country_code', _userTeam.countryCode)
      .eq('team_name', _userTeam.teamName)
      .eq('data_key', 'facilities')
      .maybeSingle();
    if (error) { console.warn('[fac_levels] load hata → kaydetme KİLİTLİ:', error); return; }
    FAC_LEVELS = (data && data.data) ? data.data : {};
    // Eksik tesisleri varsayılan 1'e doldur
    if (typeof FAC_DATA !== 'undefined') {
      FAC_DATA.forEach(f => { if(!FAC_LEVELS[f.id] || FAC_LEVELS[f.id] < 1) FAC_LEVELS[f.id] = 1; });
    }
    window._facLevelsLoadedOk = true;   // 🆕 yalnız burada açılır
  } catch(e) { console.warn('[fac_levels] load istisnası → kaydetme KİLİTLİ:', e); }
}

// Tüm tesisler için varsayılan seviye 1 (FAC_DATA tanımlandıktan sonra doldurulur)
// Gerçek yükleme bootstrap'ta _facLevelsLoadFromServer ile yapılır
if (typeof FAC_DATA !== 'undefined') {
  FAC_DATA.forEach(f => { if(!FAC_LEVELS[f.id] || FAC_LEVELS[f.id] < 1) FAC_LEVELS[f.id] = 1; });
}

let _facLevelsSaveTimer = null;
function saveFacLevels() {
  // 🔒 598 — tesis seviyeleri yalnız sunucuda (tesis_yukselt) yazılır
  if (true) return;
  if (!window.sb || !_userTeam || !_userTeam.countryCode || !_userTeam.teamName) return;
  // 🆕 Sunucudan yüklenmeden yazma — varsayılan seviye-1 değerleri gerçek
  //    (elmasla alınmış) seviyelerin üstüne yazılmasın.
  if (!window._facLevelsLoadedOk) {
    console.warn('[fac_levels] KAYDETME İPTAL — tesisler sunucudan yüklenmedi.');
    return;
  }
  // Debounced 500ms
  clearTimeout(_facLevelsSaveTimer);
  _facLevelsSaveTimer = setTimeout(async () => {
    try {
      await window.sb.from('team_data').upsert({
        country_code: _userTeam.countryCode,
        team_name: _userTeam.teamName,
        data_key: 'facilities',
        data: FAC_LEVELS,
        updated_at: new Date().toISOString()
      }, { onConflict: 'country_code,team_name,data_key' });
    } catch(e) { console.warn('[fac_levels] save hata:', e); }
  }, 500);
}

// 🆕 Kadro maksimum boyutu — Takım Kapasitesi tesisi seviyesine bağlı (14 + lvl)
// Sv 1 → 15, Sv 2 → 16, ..., Sv 10 → 24
function getMaxRosterSize(){
  const lvl = (typeof FAC_LEVELS !== 'undefined' && FAC_LEVELS && FAC_LEVELS.capacity)
    ? FAC_LEVELS.capacity : 1;
  return 14 + lvl;
}

let _facUpgradeTarget = null;

function renderFacilities() {
  // Ziyaretçi modunda kullanıcının kendi tesisi yerine ziyaret edilen takımı göster
  if(typeof _viewingTeam !== 'undefined' && _viewingTeam) {
    return guestRenderFacilities();
  }
  // 🆕 Ziyaretçi görünümünden dönüldüyse orijinal tesis arayüzünü geri yükle
  try {
    const _fw = document.getElementById('team-facility');
    if (_fw && window._facOwnHtml != null && !document.getElementById('facGrid')) {
      _fw.innerHTML = window._facOwnHtml;
    }
  } catch(e) {}

  const grid = document.getElementById('facGrid');
  if(!grid) return;

  // 🆕 Eski üst özet barı kaldırıldı — bilgi artık info panelinde (openFacInfo)
  const existingSummary = document.querySelector('.dev-summary-bar');
  if(existingSummary) existingSummary.remove();

  // Info paneli satırları: her tesisin ne işe yaradığı (desc) + seviye
  const rowsEl = document.getElementById('facInfoRows');
  if(rowsEl) {
    rowsEl.innerHTML = FAC_DATA.map(f => {
      const lvl = FAC_LEVELS[f.id] || 1;
      return `<div class="fac-ip-row">
        <div class="fac-ip-row-ic">${f.icon}</div>
        <div class="fac-ip-row-body">
          <div class="fac-ip-row-top"><div class="fac-ip-row-name">${f.name}</div><div class="fac-ip-row-lvl">Sv ${lvl}/10</div></div>
          <div class="fac-ip-row-desc">${f.desc}</div>
        </div>
      </div>`;
    }).join('');
  }

  const _facYetkili = typeof userCanMakeOffer === 'function' && userCanMakeOffer();   // 954 — düğmeler yalnız kaptan / yardımcıda
  grid.innerHTML = FAC_DATA.map(fac => {
    const lvl    = FAC_LEVELS[fac.id] || 1;
    const maxLvl = 10;
    const isMax  = lvl >= maxLvl;
    const cost   = fac.cost(lvl);

    // Seviye çizgileri
    const dots = Array.from({length:maxLvl}, (_, i) => {
      const filled = i < lvl;
      const isMaxDot = filled && lvl === maxLvl;
      return `<div class="fac-dot ${filled?'filled':''} ${isMaxDot?'max':''}"></div>`;
    }).join('');

    const effectText = fac.effectLabel(lvl);
    const nextText   = !isMax ? fac.nextLabel(lvl) : null;

    const btnContent = isMax
      ? `<span class="fac-btn-cost">⭐</span><span class="fac-btn-lbl">MAX</span>`
      : `<span class="fac-btn-cost">💎 ${cost}</span>${(typeof facEurUcret === 'function') ? `<span class="fac-btn-arti">+</span><span class="fac-btn-eur" data-noi18n>${_kitKisa(facEurUcret(lvl))}</span>` : ''}<span class="fac-btn-lbl">GELİŞTİR</span>`;

    return `<div class="fac-card${isMax?' max':''}" data-fac="${fac.id}">
      <div class="fac-icon-box thm-bina">${thmKartResim(fac.id, lvl, fac.icon)}</div>
      <div class="fac-body">
        <div class="fac-row-top">
          <div class="fac-name">${fac.name}</div>
          <div class="fac-lvl-text">Sv ${lvl}/10</div>
        </div>
        <div class="fac-dots">${dots}</div>
        <div class="fac-eff">
          <span class="fac-eff-now">${effectText}</span>
          ${nextText
            ? `<span class="fac-eff-arrow">→</span><span class="fac-eff-next">${nextText}</span>`
            : `<span class="fac-eff-next maxed">Maksimum</span>`}
        </div>
      </div>
      ${_facYetkili ? `<button class="fac-btn ${isMax?'maxed':''}" ${isMax?'disabled':`onclick="openFacModal('${fac.id}')"`}>
        ${btnContent}
      </button>` : ''}
    </div>`;
  }).join('');
  try { thmHaritaCiz(); } catch (e) { console.warn('[tesis-harita]', e); }   // 669
}

// 🆕 Gelişim info panelini aç/kapat
function openFacInfo() {
  const ov = document.getElementById('facInfoOverlay');
  if(ov) ov.classList.add('open');
}
function closeFacInfo() {
  const ov = document.getElementById('facInfoOverlay');
  if(ov) ov.classList.remove('open');
}

function openFacModal(facId) {
  if (typeof userCanMakeOffer === 'function' && !userCanMakeOffer()) return;   // 954
  const fac = FAC_DATA.find(f => f.id === facId);
  if(!fac) return;
  const lvl  = FAC_LEVELS[facId] || 1;
  const next = lvl + 1;
  const cost = fac.cost(lvl);

  document.getElementById('facModalIcon').textContent   = fac.icon;
  try { thmPencereGorsel(facId, lvl); } catch (e) {}   // 669
  document.getElementById('facModalName').textContent   = fac.name;
  document.getElementById('facModalLvl').textContent    = `Seviye ${lvl} → ${next}`;
  document.getElementById('facModalEffect').textContent = `${fac.effectLabel(lvl)} ${fac.nextLabel(lvl)||''}`;
  // 686 — Takım Kapasitesi: sıradaki seviyede açılacak mevki koltuğu
  try {
    const _eskiSira = document.getElementById('facModalSira');
    if (_eskiSira) _eskiSira.remove();
    const _sk = (facId === 'capacity' && typeof _mkSiraKutu === 'function') ? _mkSiraKutu(lvl) : '';
    if (_sk) document.getElementById('facModalEffect').insertAdjacentHTML('afterend', _sk);
  } catch (e) {}
  document.getElementById('facModalCost').textContent   = cost;

  // 🆕 Kasa bakiyesini göster (gerçek kasadan, cüzdandan değil)
  const trsBal = (typeof trsTreasuryDiaBalance==='function') ? trsTreasuryDiaBalance() : 0;
  const balEl = document.getElementById('facModalTrsBal');
  const trsBox = document.getElementById('facModalTreasury');
  if(balEl) balEl.textContent = trsBal.toLocaleString('tr') + ' 💎';
  if(trsBox){
    if(trsBal < cost){
      trsBox.style.background = 'rgba(255,23,68,.1)';
      trsBox.style.borderColor = 'rgba(255,23,68,.3)';
      if(balEl) balEl.style.color = 'var(--red)';
    } else {
      trsBox.style.background = 'rgba(0,176,255,.08)';
      trsBox.style.borderColor = 'rgba(0,176,255,.2)';
      if(balEl) balEl.style.color = 'var(--accent2)';
    }
  }
  // 845 — elmas + euro birlikte: iki maliyet kutusu; ikisi de yetmeli
  let _yeter = trsBal >= cost;
  try {
    const _fc = document.querySelector('#facModal .fac-modal-cost'); if (_fc) _fc.style.display = 'none';
    const _y = (typeof facMaliyetCiz === 'function') ? facMaliyetCiz(cost, facEurUcret(lvl)) : undefined;
    if (typeof _y === 'boolean') _yeter = _y;
  } catch (e) {}
  // Yetersizse butonu pasifleştir
  const cBtn = document.getElementById('facModalConfirm');
  if(cBtn){
    if(!_yeter){
      cBtn.disabled = true;
      cBtn.style.opacity = '.45';
      cBtn.style.cursor = 'not-allowed';
      cBtn.textContent = 'Kasa Yetersiz';
    } else {
      cBtn.disabled = false;
      cBtn.style.opacity = '1';
      cBtn.style.cursor = 'pointer';
      cBtn.textContent = 'Geliştir ✓';
    }
  }

  _facUpgradeTarget = facId;
  document.getElementById('facModal').classList.add('open');
}

function closeFacModal() {
  document.getElementById('facModal').classList.remove('open');
  _facUpgradeTarget = null;
}

function _facToast(msg, bg, fg, sure, ek) {
  const t = document.createElement('div');
  t.style.cssText = 'position:fixed;bottom:90px;left:50%;transform:translateX(-50%);background:' + bg + ';color:' + (fg || '#fff') + ';padding:8px 18px;border-radius:20px;font-size:12px;font-weight:700;z-index:9999;font-family:Twemoji Country Flags,Barlow,sans-serif;white-space:nowrap;box-shadow:0 4px 16px rgba(0,0,0,.4)';
  t.textContent = msg;
  // 686 — ikinci satır (ör. "Forvet koltuğu açıldı")
  if (ek) {
    t.style.whiteSpace = 'normal'; t.style.textAlign = 'center'; t.style.width = 'max-content'; t.style.maxWidth = '92vw';
    const s2 = document.createElement('span'); s2.className = 'mk-toast2'; s2.textContent = ek; t.appendChild(s2);
  }
  document.body.appendChild(t);
  setTimeout(() => t.remove(), sure || 2200);
}

// 🔒 598 — Tesis yükseltme SUNUCUDA tek işlem: ücret kasadan düşülür ve seviye yazılır.
//   Eskiden ödeme ile seviye ayrı yazılıyordu; takımın herhangi bir üyesi seviyeleri
//   ücretsiz ve sınırsız yazabiliyordu (stadyum → sınırsız bilet geliri).
function confirmUpgrade() {
  if(!_facUpgradeTarget) return;

  // Yetki kontrolü: tesis yükseltme kararı kaptan/yardımcı kaptana ait (sunucu da denetler)
  if(typeof userCanMakeOffer === 'function' && !userCanMakeOffer()){
    closeFacModal();
    _facToast('🔒 Sadece kaptan ve yardımcı kaptan tesis geliştirebilir.', '#ef5350', '#fff', 2500);
    return;
  }

  const hedef  = _facUpgradeTarget;
  const fac    = FAC_DATA.find(f => f.id === hedef);
  const lvl    = FAC_LEVELS[hedef] || 1;
  const cost   = fac.cost(lvl);

  const _eurUcret = (typeof facEurUcret === 'function') ? facEurUcret(lvl) : 0;   // 845 — euro da
  const _kasaEur = (typeof trsGetData === 'function') ? (Number(trsGetData().eur) || 0) : 0;
  if((typeof trsTreasuryDiaBalance === 'function' && trsTreasuryDiaBalance() < cost) || _kasaEur < _eurUcret){
    closeFacModal();
    _facToast('❌ Kasada yeterli elmas veya euro yok', '#ef5350');
    return;
  }
  if(!window.sb){ closeFacModal(); _facToast('❌ Kaydetme başarısız oldu.', '#ef5350'); return; }
  if(window._facYukseltiliyor) return;
  window._facYukseltiliyor = true;

  const _kSec = (hedef === 'capacity' && typeof window._mkSecilen === 'function') ? window._mkSecilen() : null;   // 909
  (_kSec ? window.sb.rpc('tesis_yukselt_koltuk', { p_grup: _kSec }) : window.sb.rpc('tesis_yukselt', { p_tesis: hedef })).then(({ data, error }) => {
    window._facYukseltiliyor = false;
    if (data && data.treasury) {
      _trsCache = data.treasury;
      if (typeof trsRender === 'function') try { trsRender(); } catch(e) {}
      if (typeof trsSyncHeader === 'function') try { trsSyncHeader(); } catch(e) {}
    }
    if (error || !data || !data.ok) {
      console.warn('[tesis] yükseltilemedi:', error || data);
      closeFacModal();
      const kod = (data && data.error) || '';
      if (kod === 'kasa_yetersiz') {
        _facToast('❌ Kasada yeterli elmas veya euro yok', '#ef5350');   // 845
      } else if (kod === 'yetki_yok') {
        _facToast('🔒 Sadece kaptan ve yardımcı kaptan tesis geliştirebilir.', '#ef5350', '#fff', 2500);
      } else if (kod === 'max_seviye') {
        _facToast('🏁 Bu tesis en üst seviyede.', '#ef5350');
      } else if (kod === 'mevki_tavan') {
        _facToast('❌ Bu mevkide koltuk sınırına ulaşıldı.', '#ef5350');   // 909
      } else {
        _facToast('❌ Kaydetme başarısız oldu.', '#ef5350');
      }
      if (typeof _facLevelsLoadFromServer === 'function') _facLevelsLoadFromServer().then(() => { try { renderFacilities(); } catch(e) {} });
      return;
    }

    // Sunucunun yazdığı seviyeler
    if (data.facilities && typeof data.facilities === 'object') FAC_LEVELS = Object.assign({}, FAC_LEVELS, data.facilities);
    FAC_LEVELS[hedef] = Number(data.seviye) || (lvl + 1);
    window._facLevelsLoadedOk = true;

    // 🆕 Performans Merkezi yükseltildiyse → bonus enerji göstergesini tazele
    let _perfDelta = 0;
    if(hedef === 'performance') {
      try {
        if(typeof recomputeUserEnergyBonus === 'function') {
          const r = recomputeUserEnergyBonus();
          _perfDelta = r ? r.delta : 0;
        }
      } catch(e){}
    }

    closeFacModal();
    window._thmYeni = hedef;   // 669 — harita yeni binaya yakınlaşıp parlar
    renderFacilities();
    updateDevBadges();
    const yeniLvl = FAC_LEVELS[hedef];
    const ucret = Number(data.ucret) || cost;
    const _ucretEur = Number(data.ucret_eur) || 0;   // 845
    let _facMsg = _ucretEur > 0 ? `✅ ${fac.name} Seviye ${yeniLvl}! (-${ucret} 💎 + €${_ucretEur.toLocaleString('tr')} kasadan)` : `✅ ${fac.name} Seviye ${yeniLvl}! (-${ucret} 💎 kasadan)`;
    if(_perfDelta > 0) _facMsg += ` ⚡+${_perfDelta} bonus enerji takıma eklendi!`;
    // 686 — Takım Kapasitesi: açılan mevki koltuğu ikinci satırda; hero formaları tazelenir
    if (hedef === 'capacity' && data.koltuk && typeof window._mkDagYaz === 'function') window._mkDagYaz(data.koltuk, yeniLvl);   // 909
    const _mkEk = (hedef === 'capacity' && typeof _mkAcilanMetin === 'function') ? _mkAcilanMetin(yeniLvl, data.acilan) : '';
    _facToast(_facMsg, 'var(--accent)', 'var(--bg)', _mkEk ? 3200 : 2400, _mkEk);
    if (hedef === 'capacity') { try { if (typeof thKunyeTazele === 'function') thKunyeTazele(); } catch (e) {} }
  }).catch(e => {
    window._facYukseltiliyor = false;
    console.warn('[tesis] rpc hata:', e);
    closeFacModal();
    _facToast('❌ Kaydetme başarısız oldu.', '#ef5350');
  });
}

// ══ GELİŞİM HESAPLAMA ══
function calcDevLevel() {
  // 6 tesis x 10 seviye = toplam 60 puan maksimum
  // Tüm tesisler 1. seviyeden başlar (mevcut dahil)
  const total = Object.values(FAC_LEVELS).reduce((sum, lvl) => sum + lvl, 0);
  const maxTotal = Object.keys(FAC_DATA).length * 10; // 6 * 10 = 60
  const facCount = FAC_DATA.length; // 6
  const maxPts = facCount * 10; // 60
  const pct = Math.round((total / maxPts) * 100);
  return { total, maxPts, pct };
}

function updateDevBadges() {
  const { pct } = calcDevLevel();
  const pctStr = '%' + pct;
  
  // İsim yanındaki badge (eski sağ üst stat silindi, sadece bu kaldı)
  const badge = document.getElementById('teamHeroFacility');
  if(badge && !(typeof _viewingTeam !== 'undefined' && _viewingTeam)) {
    badge.textContent = pctStr;
    badge.style.color = pct === 100 ? '#ffd11a' : '#9fe06a';
  }
  
  // Lig tablosu badge
  const ltBadge = document.getElementById('ltDevBadge');
  if(ltBadge) ltBadge.textContent = pctStr;
  
  // Tesis sayfası özet barı
  updateDevSummary(pct);
}

function updateDevSummary(pct) {
  // 🆕 Gelişim % → info butonu + info paneli (eski özet barı kaldırıldı)
  const btnPct = document.getElementById('facInfoPct');
  if(btnPct) btnPct.textContent = '%' + pct;
  const ovPct = document.getElementById('facInfoOverallPct');
  if(ovPct) ovPct.textContent = '%' + pct;
  const ovFill = document.getElementById('facInfoOverallFill');
  if(ovFill) ovFill.style.width = pct + '%';
}


