// 🆕 Equipment Supabase user_player.equipment jsonb'de
let _eqDataCache = null;
let _eqDataSaveTimer = null;
let _eqDataLoaded = false;   // 🆕 Supabase'den equipment yüklendi mi (yazma koruması için)

async function _eqDataLoadFromServer(_on956) {
  if (!window.sb || !authUser || !authUser.id) { _eqDataCache = null; return; }
  try {
    const { data } = _on956 ? await _on956 : await window.sb.from('user_player')   // 956 — açılış satırından
      .select('equipment')
      .eq('user_id', authUser.id)
      .maybeSingle();
    _eqDataCache = (data && data.equipment && Object.keys(data.equipment).length > 0) ? data.equipment : null;
    _eqDataLoaded = true;   // 🆕 yükleme tamamlandı (boş gelse bile)
    // Ekipman sayfası açıksa yeniden render et (geç yükleme görünsün)
    try {
      const eqPage = document.getElementById('page-equipment');
      if (eqPage && eqPage.classList.contains('active') && typeof renderEquipment === 'function') {
        renderEquipment();
      }
    } catch(e) {}
  } catch(e) {}
}

// localStorage: slot durumları + dolap (artık Supabase, RAM cache)
function getEqData() {
  // 🆕 Yeni kullanıcılar BOŞ dolapla başlar — itemler mağazadan satın alınmalı
  const defaultData = {
    unlockedSlots: [true, false, false, false, false],
    activeSlots:   [null, null, null, null, null],
    wardrobe:      [],
  };
  if (!_eqDataCache) return defaultData;
  const d = JSON.parse(JSON.stringify(_eqDataCache));  // deep copy
  // Geriye dönük migrations
  if (Array.isArray(d.unlockedSlots) && d.unlockedSlots.length > 5) d.unlockedSlots = d.unlockedSlots.slice(0,5);
  if (Array.isArray(d.activeSlots)   && d.activeSlots.length   > 5) d.activeSlots   = d.activeSlots.slice(0,5);
  while ((d.unlockedSlots||[]).length < 5) (d.unlockedSlots = d.unlockedSlots||[]).push(false);
  while ((d.activeSlots  ||[]).length < 5) (d.activeSlots   = d.activeSlots  ||[]).push(null);
  if (!Array.isArray(d.wardrobe)) d.wardrobe = [];
  d.unlockedSlots[0] = true;   // 733 — ilk slot her zaman açık (sunucu da öyle sayar)
  return d;
}

function saveEqData(data, immediate) {
  // 🆕 KORUMA: equipment Supabase'den henüz yüklenmediyse YAZMA.
  //   Yoksa boş default dolap, sunucudaki gerçek item'leri ezer (item kaybı).
  if (!_eqDataLoaded) { console.warn('[equipment] yükleme bitmeden save engellendi'); return; }
  _eqDataCache = data;
  if (window.sb && authUser && authUser.id) {
    clearTimeout(_eqDataSaveTimer);
    const _doWrite = async () => {
      try {
        await window.sb.from('user_player').update({
          equipment: _eqDataCache
        }).eq('user_id', authUser.id);
      } catch(e) { console.warn('[equipment] save hata:', e); }
    };
    if (immediate) { _doWrite(); }            // 🆕 satın alma/kuşanma: anında yaz
    else { _eqDataSaveTimer = setTimeout(_doWrite, 500); }
  }
}

// 🆕 Ziyaretçi modu: bakılan oyuncunun ekipmanı (salt-okunur)
let _visitorEqCache = null;
let _visitorEqUid   = null;   // 🆕 önbellekteki ekipman KİMİN — yanlış kişiye uygulamayalım
function _eqIsVisitor(){ return !!(typeof _visitedPlayerData !== 'undefined' && _visitedPlayerData && _visitedPlayerData.player); }
async function _loadVisitorEq(player) {
  try {
    const uid = player && (player.userId || player.user_id || player.uid);
    _visitorEqUid = uid || null;
    if (!uid || !window.sb) { _visitorEqCache = null; _visitorEqUid = null; }
    else {
      // 🔴 `user_player` okuma politikası "sadece kendi satırın" diyor —
      //    başkasının ekipmanı oradan ASLA gelmiyordu ve profilde
      //    yalnızca temel yetenekler görünüyordu. Sunucu artık aynı
      //    veriyi herkese açık `players.equipment` sütununa da yazıyor
      //    (sync_player_equipment tetiği).
      const { data } = await window.sb.from('players').select('equipment').eq('user_id', uid).maybeSingle();
      _visitorEqCache = (data && data.equipment && Object.keys(data.equipment).length > 0) ? data.equipment : null;
    }
  } catch(e) { _visitorEqCache = null; }
  // 🔴 Ekipman geç geldiğinde SADECE ekipman sekmesi yenileniyordu;
  //    yetenek barları ilk render'daki HAM değerlerde kalıyordu.
  //    Yani "temel 40 + item 5 = 45" olması gereken yerde başkası 40
  //    görüyordu. Artık tüm oyuncu sayfası yeniden çiziliyor, böylece
  //    yetenekler ekipman bonusuyla hesaplanıyor.
  try {
    const ziyaretteyiz = (typeof _eqIsVisitor === 'function') && _eqIsVisitor();
    if (ziyaretteyiz && typeof renderPlayerPage === 'function') renderPlayerPage();
    else {
      const tab = document.getElementById('pl-equipment');
      if (tab && tab.style.display !== 'none' && typeof renderEquipment === 'function') renderEquipment();
    }
  } catch(e){}
}
function _getVisitorEqData() {
  const def = { unlockedSlots:[true,false,false,false,false], activeSlots:[null,null,null,null,null], wardrobe:[] };
  if (!_visitorEqCache) return def;
  const d = JSON.parse(JSON.stringify(_visitorEqCache));
  if (Array.isArray(d.unlockedSlots) && d.unlockedSlots.length > 5) d.unlockedSlots = d.unlockedSlots.slice(0,5);
  if (Array.isArray(d.activeSlots) && d.activeSlots.length > 5) d.activeSlots = d.activeSlots.slice(0,5);
  while ((d.unlockedSlots||[]).length < 5) (d.unlockedSlots = d.unlockedSlots||[]).push(false);
  while ((d.activeSlots||[]).length < 5) (d.activeSlots = d.activeSlots||[]).push(null);
  if (!Array.isArray(d.wardrobe)) d.wardrobe = [];
  d.unlockedSlots[0] = true;   // 733 — ilk slot her zaman açık
  return d;
}
