// Kart: nadirlik çerçevesi + görsel + ad + ana bonus (slot ve dolap aynı boy)
function _ekKart(item, no, satis) {
  return `<div class="ek-ki"><span class="ek-nd">${_EK_NADIR[item.rarity] || item.rarity || ''}</span>${no ? `<span class="ek-no">${no}</span>` : ''}`
    + `<div class="ek-img">${itemGorselHtml(item)}</div>${satis ? `<span class="ek-sat">${_EK_SVG.etiket}<span>Satışta</span></span>` : ''}`
    + `<div class="ek-alt"><b>${item.name}</b><i>${satis ? 'Satışta' : item.bonus}</i></div></div>`;
}

function renderSlots() {
  const row = document.getElementById('eqSlotsRow');
  if(!row) return;
  const ziyaret = _eqIsVisitor();
  let dolu = 0, acik = 0;
  row.innerHTML = SLOT_COSTS.map((cost, i) => {
    const unlocked  = _eqData.unlockedSlots[i];
    const activeId  = _eqData.activeSlots[i];
    const item      = activeId ? _eqData.wardrobe.find(w=>w.id===activeId) : null;
    const slotNum   = i + 1;
    if(!unlocked) {
      // Sıralı açılım: önceki slot açık değilse bu slot soluk görünür
      const sirada = i === 0 || _eqData.unlockedSlots[i - 1];
      return `<div class="ek-yuva kilit${sirada ? '' : ' sira'}"${ziyaret ? '' : ` onclick="openSlotModal(${i})"`}>`
        + `${_EK_SVG.kilit}<small>Slot ${slotNum}</small>${ziyaret ? '' : `<span class="ek-dia" data-noi18n>${_EK_SVG.elmas}${cost}</span>`}</div>`;
    }
    acik++;
    if(item) {
      dolu++;
      return `<div class="ek-kart r-${item.rarity}" onclick="openItemInfoModal('${item.id}', 'slot')" data-eq-drop="slot" data-eq-idx="${i}" data-eq-drag="slot" data-eq-item-id="${item.id}">${_ekKart(item, slotNum)}</div>`;
    }
    return `<div class="ek-yuva bos"${ziyaret ? '' : ` onclick="_eqSlotHint('empty')" data-eq-drop="slot" data-eq-idx="${i}"`}>`
      + `${_EK_SVG.arti}<small><span data-noi18n>Slot ${slotNum}</span> · <span>Boş</span></small></div>`;
  }).join('');
  const say = document.getElementById('eqSlotSay');
  if (say) say.textContent = dolu + '/' + acik;
  _ekBonusCiz();
  if (typeof eqInitAllDrag === 'function') eqInitAllDrag();
}

// Aktif bonuslar — kuşanılan itemlerin tüm bonusları, yetenek başına tavanla
let _ekBonusAcik = false;
function _ekBonusCiz() {
  const el = document.getElementById('eqBonus');
  if (!el) return;
  if (_eqIsVisitor()) { el.style.display = 'none'; el.innerHTML = ''; return; }
  const b = getEquippedBonuses(_eqData);
  const ad = {};
  SKILL_DEFS.ALL.forEach(c => c.skills.forEach(sk => { ad[sk.id] = sk.name; }));
  const idler = Object.keys(b).sort((x, y) => b[y] - b[x]);
  const toplam = idler.reduce((t, id) => t + b[id], 0);
  el.style.display = idler.length ? '' : 'none';
  el.classList.toggle('acik', _ekBonusAcik);
  el.innerHTML = `<button type="button" class="h" onclick="_ekBonusAc()"><i class="nb"></i>${_EK_SVG.yukari}<span>Aktif bonuslar</span>`
    + `<em><b data-noi18n>${idler.length}</b> <span>yetenek</span> · <b data-noi18n>+${toplam}%</b> <span>toplam</span></em>${_EK_SVG.asagi}</button>`
    + `<div class="c">${idler.map(id => `<span><span>${ad[id] || id}</span><b data-noi18n>+${b[id]}%</b></span>`).join('')}</div>`
    + `<div class="n">maçlarda geçerli · yetenek başına en fazla %${EQ_BONUS_TAVAN}</div>`;
}
function _ekBonusAc() {
  _ekBonusAcik = !_ekBonusAcik;
  const el = document.getElementById('eqBonus');
  if (el) el.classList.toggle('acik', _ekBonusAcik);
}

// Kendi açık pazar ilanların (sunucu). İlan verilince eşya dolaptan sunucuda düşer (598);
//   dolapta "Satışta" kartı olarak bunlardan gösterilir, dokununca geri alınabilir.
let _ekIlanlar = [];
async function _ekIlanYukle() {
  if (!window.sb || typeof authUser === 'undefined' || !authUser || !authUser.id) return;
  const { data, error } = await window.sb.from('item_listings').select('id,data')
    .eq('seller_user_id', authUser.id).eq('listed', true).order('created_at', { ascending: true }).limit(20);
  if (error) return;
  _ekIlanlar = (data || []).map(r => ({ id: r.id, itemId: (r.data && (r.data.itemId || r.data.id)) || null })).filter(l => l.itemId);
  if (!_eqIsVisitor() && document.getElementById('eqWardrobe')) renderWardrobe();
}
function _ekIlanBul(itemId) {
  return _ekIlanlar.find(l => l.itemId === itemId) || null;
}
function _ekIlanEsya(itemId) {
  const it = (typeof SHOP_ITEMS !== 'undefined') ? SHOP_ITEMS.find(i => i.id === itemId) : null;
  return it ? { id: it.id, name: it.name, icon: it.icon, rarity: it.rarity, bonus: (it.stats || [])[0] || '' } : null;
}

// Dolap kapasitesi 10 — slota takılı itemler dolapta yer kaplamaz (10 dolap + 5 aktif slot)
const EK_DOLAP_MAX = 10;
function _ekDolapSayi(eq) {
  const aktif = Array.isArray(eq && eq.activeSlots) ? eq.activeSlots : [];
  return ((eq && eq.wardrobe) || []).filter(w => w && !aktif.includes(w.id)).length;
}

function renderWardrobe() {
  const el = document.getElementById('eqWardrobe');
  if(!el) return;
  // Dolap kişiye özel — ziyaretçi görmez
  if (_eqIsVisitor()) { el.innerHTML = ''; return; }
  el.setAttribute('data-eq-drop', 'wardrobe');
  const MAX = EK_DOLAP_MAX;
  const visibleItems = _eqData.wardrobe.filter(item => !_eqData.activeSlots.includes(item.id));
  const satista = _ekIlanlar.map(l => _ekIlanEsya(l.itemId)).filter(Boolean);
  const emptyCount = Math.max(0, MAX - visibleItems.length - satista.length);
  const say = document.getElementById('eqDolapSay');
  if (say) say.textContent = visibleItems.length + '/' + MAX;
  let html = visibleItems.map(item =>
    `<div class="ek-kart r-${item.rarity}" onclick="wardrobeItemClick('${item.id}')" data-eq-drag="wardrobe" data-eq-item-id="${item.id}">${_ekKart(item, 0, false)}</div>`).join('')
    + satista.map(item => `<div class="ek-kart r-${item.rarity} satista" onclick="openItemInfoModal('${item.id}', 'ilan')">${_ekKart(item, 0, true)}</div>`).join('');
  for(let i = 0; i < emptyCount; i++) html += `<div class="ek-yuva bos">${_EK_SVG.arti}<small>Boş</small></div>`;
  el.innerHTML = html;
  if (typeof eqInitAllDrag === 'function') eqInitAllDrag();
}

// ── Slot kilidi açma — custom confirm modal ile direkt onay (sıralı açılım) ──
function openSlotModal(slotIdx) {
  if (_eqIsVisitor() || slotIdx === undefined || slotIdx === null) return;

  // 🆕 Sıralı açılım: önceki slot açılmadan bu slot açılamaz
  if (slotIdx > 0 && !_eqData.unlockedSlots[slotIdx - 1]) {
    showEqToast(`Önce Slot ${slotIdx}'i açmalısın!`, '#ef5350');
    return;
  }

  const cost = SLOT_COSTS[slotIdx];
  const bal = (typeof wlGetData === 'function') ? (wlGetData().dia || 0) : 0;

  // Yetersiz diamond — direkt uyarı (modal'a girmeden)
  if (bal < cost) {
    showEqToast(`Yetersiz Diamond! Gerekli: ${cost} 💎 · Mevcut: ${bal.toLocaleString('tr')} 💎`, '#ef5350');
    return;
  }

  // Yeterli — cftConfirm ile onay diyaloğu
  if (typeof cftConfirm === 'function') {
    cftConfirm({
      title: `Slot ${slotIdx + 1} Aç?`,
      message: `Bu slotu açmak için ${cost} 💎 harcanacak. (Mevcut: ${bal.toLocaleString('tr')} 💎)`,
      confirmText: `Evet, ${cost} 💎 ile Aç`,
      cancelText: 'İptal',
      danger: false,
      onConfirm: () => _doUnlockSlot(slotIdx)
    });
  } else {
    _doUnlockSlot(slotIdx);
  }
}

// 🔒 598 — slot kilidi SUNUCUDA açılır: ücret cüzdandan düşülür ve slot tek işlemde açılır.
//   Eskiden ödeme ve kilit ayrı yazılıyordu; slotlar konsoldan ücretsiz açılabiliyordu.
function _doUnlockSlot(slotIdx) {
  if (_eqIsVisitor()) return;
  const cost = SLOT_COSTS[slotIdx];
  const bal = (typeof wlGetData === 'function') ? (wlGetData().dia || 0) : 0;
  if (bal < cost) {
    showEqToast(`Yetersiz Diamond! Gerekli: ${cost} 💎 · Mevcut: ${bal.toLocaleString('tr')} 💎`, '#ef5350');
    return;
  }
  if (!window.sb) { showEqToast('❌ Bakiye düşülemedi.', '#ef5350'); return; }
  if (window._slotAciliyor) return;
  window._slotAciliyor = true;
  window.sb.rpc('slot_ac', { p_i: slotIdx }).then(({ data, error }) => {
    window._slotAciliyor = false;
    if (error || !data || !data.ok) {
      console.warn('[slot] açılamadı:', error || data);
      const kod = (data && data.error) || '';
      if (kod === 'insufficient') showEqToast(`Yetersiz Diamond! Gerekli: ${cost} 💎 · Mevcut: ${bal.toLocaleString('tr')} 💎`, '#ef5350');
      else if (kod === 'onceki_slot_kapali') showEqToast(`Önce Slot ${slotIdx}'i açmalısın!`, '#ef5350');
      else showEqToast('❌ Bakiye düşülemedi.', '#ef5350');
      return;
    }
    if (data.equipment && typeof data.equipment === 'object') {
      _eqDataCache = data.equipment;
      _eqData = getEqData();
    }
    if (typeof wlLoadFromServer === 'function') wlLoadFromServer().then(() => { if (typeof wlSyncHeader === 'function') wlSyncHeader(); });
    showEqToast('Slot ' + (slotIdx + 1) + ' kilidi açıldı!', 'var(--accent)');
    renderSlots();
  }).catch(e => {
    window._slotAciliyor = false;
    console.warn('[slot] rpc hata:', e);
    showEqToast('❌ Bakiye düşülemedi.', '#ef5350');
  });
}

