// ── Item yerleştirme ──
// 🆕 Slot tıklama hint toast (drag-drop'a yönlendir)
let _eqSlotHintCooldown = 0;
function _eqSlotHint(kind) {
  if (_eqIsVisitor()) return;
  // Spam koruması: 2 saniyede bir
  const now = Date.now();
  if (now - _eqSlotHintCooldown < 2000) return;
  _eqSlotHintCooldown = now;
  const msg = (kind === 'filled')
    ? '💡 Item\'i çıkarmak için dolaba sürükle'
    : '💡 Dolaptan item sürükleyerek bu slota bırak';
  if (typeof showEqToast === 'function') {
    showEqToast(msg, 'rgba(95,184,255,.9)');
  }
}

// 🚫 Eski item seç modalı kaldırıldı (drag-drop sistemi var)
// Geriye dönük uyumluluk için no-op stub'lar
function openPlaceModal(slotIdx) { _eqSlotHint(slotIdx != null && _eqData && _eqData.activeSlots && _eqData.activeSlots[slotIdx] ? 'filled' : 'empty'); }
function closePlaceModal() {}
function placeItemInSlot(itemId) {}

// 🆕 Item bilgi modali — slot veya dolap üstüne tıkla → tüm yetenek bonuslarını gör
// source: 'slot' | 'wardrobe'  (footer eylem butonu gösterimi için)
function openItemInfoModal(itemId, source) {
  if (typeof _eqData === 'undefined' || !_eqData) _eqData = getEqData();
  // Önce dolap, sonra SHOP_ITEMS (yedek)
  let item = (_eqData.wardrobe || []).find(w => w.id === itemId);
  if (!item && typeof SHOP_ITEMS !== 'undefined') {
    item = SHOP_ITEMS.find(i => i.id === itemId);
  }
  if (!item) return;

  const overlay = document.getElementById('itemInfoOverlay');
  if (!overlay) return;

  const rarCol = (typeof RARITY_COLORS !== 'undefined' && RARITY_COLORS[item.rarity]) || '#5fb8ff';

  // Rarity bar rengi (CSS var)
  document.getElementById('itemInfoModal').style.setProperty('--rarity-color', rarCol);

  itemGorselYaz(document.getElementById('itemInfoIcon'), item); // 🆕 554
  document.getElementById('itemInfoName').textContent = item.name || 'Item';
  document.getElementById('itemInfoRarity').textContent = _EK_NADIR[item.rarity] || item.rarity || '—';
  document.getElementById('itemInfoType').textContent = item.type || item.catLabel || '—';

  // Bonuslar listesi
  const statsEl = document.getElementById('itemInfoStats');
  const stats = Array.isArray(item.stats) ? item.stats : [];
  if (stats.length === 0) {
    statsEl.innerHTML = '<div style="font-size:11px;color:var(--text3);font-style:italic;text-align:center;padding:8px">Yetenek bonusu yok</div>';
  } else {
    statsEl.innerHTML = stats.map(s => {
      const m = String(s).match(/^(.+?)\s*\+(\d+)%/);
      if (m) {
        return `<div class="item-info-stat">
          <span class="item-info-stat-name">${m[1].trim()}</span>
          <span class="item-info-stat-val">+${m[2]}%</span>
        </div>`;
      }
      return `<div class="item-info-stat">
        <span class="item-info-stat-name">${s}</span>
        <span class="item-info-stat-val">—</span>
      </div>`;
    }).join('');
  }

  // Footer: eylem butonu (sadece dolaptan açıldıysa satış)
  const footEl = document.getElementById('itemInfoFoot');
  if ((source === 'wardrobe' || source === 'ilan') && !_eqIsVisitor()) {
    const iptal = source === 'ilan';
    const btnLabel = iptal ? '↩️ Satıştan Kaldır' : '💰 Satışa Çıkar';
    footEl.innerHTML = `<button class="cft-confirm-btn confirm" style="padding:8px 18px;font-size:12px" onclick="itemActionSellOrCancel('${item.id}', ${iptal})">${btnLabel}</button>`;
  } else if (source === 'slot') {
    footEl.innerHTML = '<span>🎒 Aktif slot · maçlarda yetenek bonusu aktif</span>';
  } else {
    footEl.innerHTML = '';
  }

  overlay.classList.add('open');
}

function closeItemInfoModal() {
  const overlay = document.getElementById('itemInfoOverlay');
  if (overlay) overlay.classList.remove('open');
}

function wardrobeItemClick(itemId) {
  if (_eqIsVisitor()) return;
  // 🆕 Tek tıklama: item bilgi modali (bonuslar görünür).
  //   Satış / satıştan kaldır eylemleri info modal içindeki butondan tetiklenir.
  openItemInfoModal(itemId, 'wardrobe');
}

// Item satış akışı (eskiden wardrobeItemClick tarafından yapılan iş — şimdi info modal butonundan)
function itemActionSellOrCancel(itemId, iptal) {
  if (_eqIsVisitor()) return;
  if (typeof _eqData === 'undefined' || !_eqData) _eqData = getEqData();
  const item = iptal ? _ekIlanEsya(itemId) : _eqData.wardrobe.find(w => w.id === itemId);
  if (!item) return;
  closeItemInfoModal();
  if (iptal) {
    if (typeof cftConfirm === 'function') {
      cftConfirm({
        title: 'Satıştan Kaldır?',
        message: `${item.name} pazar yerinden geri alınacak.`,
        confirmText: 'Evet, Geri Al',
        cancelText: 'İptal',
        danger: true,
        // 🆕 546 — iptal SUNUCUDA (market_cancel). Toast ve dolap yenileme
        //   _doCancelListing içinde, yalnızca sunucu onaylayınca yapılır.
        onConfirm: () => { _removeListingByItemId(itemId); }
      });
    }
    return;
  }
  if (typeof itemSellQuickOpen === 'function') itemSellQuickOpen(item);
}

function showEqToast(msg, color) {
  const t = document.createElement('div');
  t.style.cssText = `position:fixed;bottom:90px;left:50%;transform:translateX(-50%);
    background:${color};color:${color==='var(--accent)'||color==='var(--text2)'?'var(--bg)':'#fff'};
    padding:9px 18px;border-radius:20px;font-size:11px;font-weight:700;
    z-index:9999;font-family:Twemoji Country Flags,'Barlow Condensed',sans-serif;letter-spacing:.3px;
    text-align:center;line-height:1.5;max-width:290px;white-space:pre-line;
    box-shadow:0 4px 16px rgba(0,0,0,.5)`;
  t.textContent = msg;
  document.body.appendChild(t);
  setTimeout(()=>t.remove(), 2800);
}

// ══ 🆕 EKİPMAN SÜRÜKLE-BIRAK ══
// Pointer Events ile cross-device (desktop fare + mobile dokunmatik)
var _eqDragState = null;

// ══ 🆕 ITEM SATIŞ QUICK MODAL + LİSTİNG HELPERS ══
var _itemSellQuickItem = null;

// 🆕 546 — ESKİ HATA: dolaptan iptal yalnızca yerel listede `listed=false` yapıp
//   saveMarket() ile istemciden upsert ediyordu. item_listings'e istemciden
//   güncelleme RLS'e takılıyor, hata da kontrol edilmiyordu → iptal ekranda
//   görünüp veritabanına hiç yazılmıyor, oyuna tekrar girince ilan geri geliyordu.
//   Artık pazar yeri sayfasındaki "İlanı Geri Al" ile aynı sunucu çağrısı.
function _removeListingByItemId(itemId) {
  const l = _ekIlanBul(itemId);
  if (!l) return;
  _doCancelListing(l.id);
}

function itemSellQuickOpen(item) {
  if (!item) return;
  _itemSellQuickItem = item;
  const overlay = document.getElementById('itemSellQuickOverlay');
  const titleEl = document.getElementById('itemSellQuickTitle');
  const msgEl = document.getElementById('itemSellQuickMsg');
  const iconEl = document.getElementById('itemSellQuickIcon');
  const priceInp = document.getElementById('itemSellQuickPrice');
  if (!overlay) return;
  if (titleEl) titleEl.textContent = item.name + ' — Satışa Çıkar';
  if (msgEl) msgEl.textContent = `${item.bonus || ''} özelliğine sahip bu itemi pazar yerinde satışa çıkar. Önerilen fiyat aralığı: 100-800 💎.`;
  if (iconEl) itemGorselYaz(iconEl, item); // 🆕 554
  if (priceInp) {
    // Önerilen başlangıç fiyatı (rarity'ye göre)
    const suggested = item.rarity === 'elit' ? 600
                    : item.rarity === 'pro' ? 350
                    : item.rarity === 'rare' ? 250
                    : item.rarity === 'epic' ? 450
                    : item.rarity === 'legend' ? 800
                    : 100;
    priceInp.value = suggested;
    setTimeout(() => priceInp.focus(), 100);
  }
  overlay.classList.add('open');
}

function itemSellQuickClose() {
  const overlay = document.getElementById('itemSellQuickOverlay');
  if (overlay) overlay.classList.remove('open');
  _itemSellQuickItem = null;
}

function itemSellQuickConfirm() {
  if (!_itemSellQuickItem) return;
  const priceInp = document.getElementById('itemSellQuickPrice');
  const price = parseInt(priceInp?.value, 10);
  if (!price || price < 1) {
    showEqToast('Geçerli bir fiyat gir!', '#ef5350');
    return;
  }

  // Listingi oluştur
  if (typeof initMarketListings === 'function') initMarketListings();
  const itemId = _itemSellQuickItem.id;
  const myName = (typeof authUser !== 'undefined' && authUser && authUser.name) ? authUser.name : 'Sen';
  const listing = {
    id: 'usr_' + Date.now() + '_' + Math.floor(Math.random()*1000),
    itemId,
    seller: myName,
    price,
    listed: true,
    listedAt: Date.now()
  };
  if (typeof _marketListings !== 'undefined') {
    _marketListings.push(listing);
    saveMarket(listing);
  }

  showEqToast(_itemSellQuickItem.name + ' pazar yerine listelendi · ' + price + ' 💎', '#5fb8ff');
  itemSellQuickClose();
  renderWardrobe();

  // 🆕 Bot alıcı simülasyonu — 30sn-3dk arası rastgele satılır
  _scheduleAutoSell(listing);
}

// 🆕 Bot alıcı simülasyonu: listingden 30sn-180sn sonra satıldı bildirimi
function _scheduleAutoSell(listing) {
  // 🔒 A3 · SAHTE BOT ALICI SİMÜLASYONU KAPATILDI.
  //   Bu fonksiyon 30-180 sn sonra ilanı "satıldı" sayıp fiyatı doğrudan
  //   cüzdana yatırıyordu. GERÇEK bir alıcı yoktu — yani ilan ver, bekle,
  //   bedava elmas al. Pazar yeri artık tek dünya ve sunucuda:
  //   `market_buy` aksiyonu gerçek alıcıdan parayı düşüp satıcıya yatırıyor.
  if (true) return;
  const delayMs = 30000 + Math.floor(Math.random() * 150000); // 30sn-180sn
  setTimeout(() => {
    // Hâlâ listede mi? (kullanıcı geri çekmediyse)
    if (typeof _marketListings === 'undefined') return;
    const cur = _marketListings.find(l => l.id === listing.id);
    if (!cur || !cur.listed) return;

    // Sat: kullanıcının dolabından çıkar + diamond ekle + listingi pasifleştir + bildirim
    cur.listed = false;
    const eq = (typeof getEqData === 'function') ? getEqData() : null;
    if (eq && Array.isArray(eq.wardrobe)) {
      // Item dolapta mı? (kullanıcı silmemişse)
      const idx = eq.wardrobe.findIndex(w => w.id === listing.itemId);
      if (idx >= 0) {
        const sold = eq.wardrobe[idx];
        eq.wardrobe.splice(idx, 1);
        // Aktif slottaysa null'a çevir
        if (Array.isArray(eq.activeSlots)) {
          eq.activeSlots = eq.activeSlots.map(id => id === listing.itemId ? null : id);
        }
        if (typeof saveEqData === 'function') saveEqData(eq, true);
        // Diamond ekle (cüzdana)
        if (typeof trsAddIncome === 'function') {
          trsAddIncome('dia', listing.price, 'Pazar satışı: ' + (sold.name || 'item'));
        }
        // Bildirim
        _itemSoldNotifShow(sold.name || 'Item', listing.price);
      }
    }
    if (typeof saveMarket === 'function') saveMarket();
    // Pazar yeri sayfası açıksa yenile
    if (typeof renderMarket === 'function') {
      const shopPage = document.getElementById('page-shop');
      if (shopPage && shopPage.style.display !== 'none') renderMarket();
    }
    // Ekipman tabı açıksa yenile
    if (typeof renderEquipment === 'function') {
      const eqEl = document.getElementById('pl-equipment');
      if (eqEl && eqEl.style.display !== 'none') renderEquipment();
    }
  }, delayMs);
}

// 🆕 Mavi "Ürün Satıldı" bildirimi (sağ üst, antrenman bildirimine benzer)
function _itemSoldNotifShow(itemName, price) {
  if (!window._itemSoldNotifQueue) window._itemSoldNotifQueue = [];
  window._itemSoldNotifQueue.push({ itemName, price });
  _itemSoldProcessQueue();
}

function _itemSoldProcessQueue() {
  const notif = document.getElementById('itemSoldNotif');
  if (!notif) return;
  if (notif._showing) return;
  if (!window._itemSoldNotifQueue || !window._itemSoldNotifQueue.length) return;
  const next = window._itemSoldNotifQueue.shift();
  notif._showing = true;
  const skillEl = notif.querySelector('.tr-done-notif-skill');
  if (skillEl) skillEl.textContent = next.itemName + ' · +' + next.price + ' 💎';
  notif.classList.add('show');
  if (typeof _playNotifSound === 'function') _playNotifSound(); // 🆕 CHIME
  if (notif._hideTimer) clearTimeout(notif._hideTimer);
  notif._hideTimer = setTimeout(() => {
    notif.classList.remove('show');
    notif._hideTimer = null;
    notif._showing = false;
    setTimeout(_itemSoldProcessQueue, 450);
  }, 5000);
}

function itemSoldNotifClick() {
  const notif = document.getElementById('itemSoldNotif');
  if (notif) {
    if (notif._hideTimer) clearTimeout(notif._hideTimer);
    notif._hideTimer = null;
    notif.classList.remove('show');
    notif._showing = false;
  }
  // Mağaza > Pazar Yeri sekmesine yönlendir
  if (typeof showPage === 'function') {
    const navBtn = (typeof findNavBtn === 'function') ? findNavBtn('shop') : null;
    showPage('shop', navBtn);
    setTimeout(() => {
      if (typeof shopTab === 'function') shopTab('market');
    }, 100);
  }
  if (window._itemSoldNotifQueue) window._itemSoldNotifQueue.length = 0;
}

// 956 — _resumeAutoSells kaldırıldı: açılıştan 2 sn sonra pazar yerinin 500 ilanını yalnız kapalı bot satışı (_scheduleAutoSell:
//   if (true) return) için indiriyordu. İlanlar Mağaza açılınca / Ekipman sekmesinde / Satış Listesinde yüklenir.

// 🆕 Mobil scroll engelleme — touchmove'u kökten kilitle (sadece drag aktifken)
var _eqDragInProgress = false;

// ═══════════════════════════════════════════════════════════════════
//  🔧 SÜRÜKLEME KİLİDİ GÜVENLİK AĞI
//
//  Ekipman/diziliş sürüklemesi mobilde sayfayı kilitlemek için
//  `body { position:fixed; top:-<scroll>px }` yapıyor (iOS body-lock).
//  Kilidi `onUp` geri alıyor — ama `pointerup`/`pointercancel` HİÇ
//  gelmezse geri alınmıyor. Android'de bu oluyor: sürüklenen öğe
//  DOM'dan kaldırılırsa (kadro yeniden render olursa) tarayıcı olayı
//  düşürüyor.
//
//  Sonuç: sayfa görsel olarak normal görünüyor ama gerçekte kaydırılmış
//  ve konumu sabitlenmiş durumda — DOKUNMA KOORDİNATLARI KAYIYOR.
//  Alt menü viewport'a sabit olduğu için çalışmaya devam ediyor,
//  sayfa içeriğindeki butonlar cevap vermiyor. "İlk denemede çalışıyor,
//  sonra bozuluyor" tarifi tam olarak bu.
//
//  Bu yardımcı kilidi koşulsuz açar. Sayfa geçişlerinde, sekmeye
//  dönüşte ve bir bekçi zamanlayıcısında çağrılıyor.
// ═══════════════════════════════════════════════════════════════════
window._eqUnlockBody = function(zorla){
  try {
    if (_eqDragInProgress && !zorla) return false;
    try { document.removeEventListener('touchmove', _eqBlockTouchMove, { passive: false }); } catch(e) {}   // 957 — bırakma olayı kaybolduysa engel belgede kalmasın
    const b = document.body, h = document.documentElement;
    const kilitliydi = (b.style.position === 'fixed') || h.classList.contains('eq-drag-lock');
    if (!kilitliydi) return false;
    const y = Math.abs(parseInt(b.style.top || '0', 10)) || 0;
    h.classList.remove('eq-drag-lock');
    b.style.position = ''; b.style.top = ''; b.style.left = '';
    b.style.right = ''; b.style.width = '';
    _eqDragInProgress = false;
    if (y) { try { window.scrollTo(0, y); } catch(e) {} }
    console.warn('[eq] takılı sürükleme kilidi açıldı (scroll ' + y + ')');
    return true;
  } catch(e) { return false; }
};

// Bekçi: sürükleme başladı ama 6 saniyedir hiç hareket/bitiş yoksa aç.
(function(){
  var sonHareket = 0;
  ['pointermove','pointerup','pointercancel','touchend','touchcancel'].forEach(function(t){
    window.addEventListener(t, function(){ sonHareket = Date.now(); }, true);
  });
  setInterval(function(){
    if (!_eqDragInProgress) return;
    if (Date.now() - sonHareket > 6000) {
      try { window._eqUnlockBody(true); } catch(e) {}
    }
  }, 3000);
  // Sekmeye/uygulamaya dönüşte de kontrol et
  document.addEventListener('visibilitychange', function(){
    if (!document.hidden) { try { window._eqUnlockBody(true); } catch(e) {} }
  });
})();
function _eqBlockTouchMove(e) {
  // Sadece drag başladıysa engelle (yoksa native click event chain'i bozulur)
  if (!_eqDragInProgress) return;
  if (e.cancelable) e.preventDefault();
}

function eqInitAllDrag() {
  if (_eqIsVisitor()) return; // 🆕 ziyaretçi: düzenleme/sürükleme yok
  // Tüm draggable elementlere event ekle
  document.querySelectorAll('#pl-equipment [data-eq-drag]').forEach(el => {
    if (el._eqDragSetup) return; // tekrar bağlama
    el._eqDragSetup = true;
    el.addEventListener('pointerdown', _eqOnPointerDown);
    // 🆕 touchstart'tan hemen preventDefault (iOS native scroll'u erken kes)
    el.addEventListener('touchstart', function(e) {
      if (e.cancelable) e.preventDefault();
    }, { passive: false });
  });
}

function _eqOnPointerDown(e) {
  if (_eqIsVisitor()) return; // 🆕 ziyaretçi: sürükleme yok
  // Sadece sol click veya touch
  if (e.pointerType === 'mouse' && e.button !== 0) return;
  const sourceEl = e.currentTarget;
  const itemId = sourceEl.dataset.eqItemId;
  const source = sourceEl.dataset.eqDrag; // 'slot' veya 'wardrobe'
  const slotIdx = sourceEl.dataset.eqIdx ? parseInt(sourceEl.dataset.eqIdx, 10) : null;
  if (!itemId) return;

  const item = _eqData.wardrobe.find(w => w.id === itemId);
  if (!item) return;

  // 🆕 pointerdown'dan İTİBAREN tüm dokumana touchmove blokesi ekle
  // (iOS'te aşağı çekme overscroll'u erken durdurur)
  document.addEventListener('touchmove', _eqBlockTouchMove, { passive: false });

  const startX = e.clientX, startY = e.clientY;
  let dragging = false;
  let preview = null;
  let lastTarget = null;
  // 🆕 Sayfa scroll pozisyonunu kaydet (iOS body lock için)
  let savedScrollY = window.scrollY || window.pageYOffset || 0;

  // Click iptal etmek için flag — sürükleme gerçekleşince tıklama tetiklenmesin
  let clickShouldBlocked = false;

  function onMove(em) {
    const dx = em.clientX - startX;
    const dy = em.clientY - startY;
    const dist = Math.hypot(dx, dy);

    if (!dragging && dist > 8) {
      // Drag başlat
      dragging = true;
      _eqDragInProgress = true; // 🆕 touchmove blokesi şimdi aktif
      clickShouldBlocked = true;
      sourceEl.classList.add('eq-dragging');
      // 🆕 Sayfayı kilitle (mobilde scroll/zoom engellensin)
      document.documentElement.classList.add('eq-drag-lock');
      // 🆕 iOS body lock — position:fixed trick (en sert engel)
      document.body.style.position = 'fixed';
      document.body.style.top = `-${savedScrollY}px`;
      document.body.style.left = '0';
      document.body.style.right = '0';
      document.body.style.width = '100%';
      preview = document.createElement('div');
      preview.className = 'eq-drag-preview';
      itemGorselYaz(preview, item); // 🆕 554
      const rarCol = (typeof RARITY_COLORS !== 'undefined') ? (RARITY_COLORS[item.rarity] || '#5fb8ff') : '#5fb8ff';
      preview.style.borderColor = rarCol;
      preview.style.boxShadow = `0 12px 32px rgba(0,0,0,.7), 0 0 24px ${rarCol}80`;
      document.body.appendChild(preview);
      // Click'i engelle
      try { sourceEl.setPointerCapture(em.pointerId); } catch(_) {}
    }

    if (dragging) {
      // Touch scroll engelle (passive:false ile preventDefault çalışır)
      if (em.cancelable) em.preventDefault();
      preview.style.left = em.clientX + 'px';
      preview.style.top = em.clientY + 'px';
      // Drop hedefi tespit
      const elUnder = document.elementFromPoint(em.clientX, em.clientY);
      let target = elUnder ? elUnder.closest('[data-eq-drop]') : null;
      // Kilitli slot drop hedefi olamaz
      if (target && target.dataset.eqDrop === 'slot' && target.classList.contains('eq-slot-locked')) {
        target = null;
      }
      // Aynı slot'a kendine drop önle
      if (target && source === 'slot' && target.dataset.eqDrop === 'slot' &&
          parseInt(target.dataset.eqIdx, 10) === slotIdx) {
        target = null;
      }
      if (lastTarget && lastTarget !== target) {
        lastTarget.classList.remove('eq-drop-target');
      }
      // Vurgu SADECE slot için (dolap sessiz drop hedefi)
      if (target && target.dataset.eqDrop === 'slot') {
        target.classList.add('eq-drop-target');
        preview.classList.add('is-active');
      } else {
        if (preview) preview.classList.remove('is-active');
      }
      lastTarget = target;
    }
  }

  function onUp(eu) {
    window.removeEventListener('pointermove', onMove);
    window.removeEventListener('pointerup', onUp);
    window.removeEventListener('pointercancel', onUp);
    _eqDragInProgress = false; // 🆕 touchmove blokesini kapat
    // 🆕 touchmove blokesini kaldır
    document.removeEventListener('touchmove', _eqBlockTouchMove, { passive: false });
    // 🆕 Sayfa kilidini kaldır + scroll'u geri yükle
    document.documentElement.classList.remove('eq-drag-lock');
    document.body.style.position = '';
    document.body.style.top = '';
    document.body.style.left = '';
    document.body.style.right = '';
    document.body.style.width = '';
    if (savedScrollY) {
      window.scrollTo(0, savedScrollY);
    }

    if (dragging) {
      sourceEl.classList.remove('eq-dragging');
      if (preview) preview.remove();
      const target = lastTarget;
      document.querySelectorAll('.eq-drop-target').forEach(t => t.classList.remove('eq-drop-target'));
      if (target) {
        eqDropHandler(
          { source, itemId, slotIdx },
          { type: target.dataset.eqDrop, idx: target.dataset.eqIdx ? parseInt(target.dataset.eqIdx, 10) : null }
        );
      }
      // Click event'i bloke et (sürükleme sonrası tıklamaya geçmesin)
      if (clickShouldBlocked) {
        const blockClick = (ev) => {
          ev.stopPropagation();
          ev.preventDefault();
          sourceEl.removeEventListener('click', blockClick, true);
        };
        sourceEl.addEventListener('click', blockClick, true);
        setTimeout(() => sourceEl.removeEventListener('click', blockClick, true), 350);
      }
    } else {
      // 🆕 Sürüklenmedi — tıklamadır. Native click bazı browserlarda kayboluyor,
      // garanti olarak onclick handler'ı manuel tetikle (çift trigger önleyici flag ile)
      let nativeClickFired = false;
      const markNative = () => { nativeClickFired = true; };
      sourceEl.addEventListener('click', markNative, { once: true, capture: true });
      setTimeout(() => {
        try { sourceEl.removeEventListener('click', markNative, true); } catch(_) {}
        if (!nativeClickFired) {
          // Native click tetiklenmedi — onclick attribute'unu manuel çalıştır
          const oh = sourceEl.getAttribute('onclick');
          if (oh) {
            try { (new Function(oh)).call(sourceEl); } catch(_) {}
          } else {
            try { sourceEl.click(); } catch(_) {}
          }
        }
      }, 80);
    }
  }

  // passive:false — preventDefault çalışsın diye
  window.addEventListener('pointermove', onMove, { passive: false });
  window.addEventListener('pointerup', onUp);
  window.addEventListener('pointercancel', onUp);
}

// Drop işlemi — kaynak ve hedefe göre eyleme dök
function eqDropHandler(payload, dest) {
  if (_eqIsVisitor()) return; // 🆕 ziyaretçi: değişiklik yok
  // payload = { source: 'slot'|'wardrobe', itemId, slotIdx }
  // dest    = { type: 'slot'|'wardrobe', idx }
  const item = _eqData.wardrobe.find(w => w.id === payload.itemId);
  let changed = false;

  if (payload.source === 'wardrobe' && dest.type === 'slot') {
    // Dolap → Slot: kuşan
    if (!_eqData.unlockedSlots[dest.idx]) {
      showEqToast('Bu slot kilitli. Önce slotu aç.', '#ef5350');
      return;
    }
    _eqData.activeSlots[dest.idx] = payload.itemId;
    saveEqData(_eqData, true);
    showEqToast((item ? item.name : 'Item') + ' Slot ' + (dest.idx + 1) + '\'e kuşanıldı', 'var(--accent)');
    changed = true;
  }
  else if (payload.source === 'slot' && dest.type === 'wardrobe') {
    // Slot → Dolap: çıkar
    if (_ekDolapSayi(_eqData) >= EK_DOLAP_MAX) {
      showEqToast('Dolabın dolu. Önce dolaptan bir item çıkar.', '#ef5350');
      return;
    }
    _eqData.activeSlots[payload.slotIdx] = null;
    saveEqData(_eqData, true);
    showEqToast((item ? item.name : 'Item') + ' dolaba çıkarıldı', 'var(--text2)');
    changed = true;
  }
  else if (payload.source === 'slot' && dest.type === 'slot' && payload.slotIdx !== dest.idx) {
    // Slot → Slot: değiştir/taşı
    if (!_eqData.unlockedSlots[dest.idx]) {
      showEqToast('Hedef slot kilitli', '#ef5350');
      return;
    }
    const tmp = _eqData.activeSlots[dest.idx];
    _eqData.activeSlots[dest.idx] = _eqData.activeSlots[payload.slotIdx];
    _eqData.activeSlots[payload.slotIdx] = tmp;
    saveEqData(_eqData, true);
    showEqToast(tmp ? 'Slotlar yer değiştirdi' : 'Item Slot ' + (dest.idx + 1) + '\'e taşındı', 'var(--accent)');
    changed = true;
  }

  if (changed) {
    renderSlots(); renderWardrobe();
    // 🆕 Yetenekler değişti — skill tab açıksa yenile
    _refreshSkillsAfterEquipChange();
  }
}

// 🆕 Item kuşan/çıkar sonrası yetenekleri yenile (skill tab + FIFA bar + OVR)
function _refreshSkillsAfterEquipChange() {
  // Skill tab şu an görünüyor mu? Yoksa renderPlayerPage çağrılırsa mevcut tab kalır
  // Direkt renderPlayerPage çağırmak en güvenlisi (overall + FIFA bar + skill grid hepsi yenilenir)
  if (typeof renderPlayerPage === 'function' && document.getElementById('plName')) {
    // Player sayfası açıksa
    const plPage = document.getElementById('page-player');
    if (plPage && plPage.style.display !== 'none') {
      renderPlayerPage();
    }
  }
}


// ══ PİYASA DEĞERİ ══
function formatMarketVal(v) {
  if(v >= 1000000) return (v/1000000).toFixed(v%1000000===0?0:1) + 'M €';
  if(v >= 1000)    return Math.round(v/1000) + '.000 €';
  return v + ' €';
}

// ══ ESKİ MV SİSTEMİ — DEPRECATED ══
// 🆕 Piyasa değeri Supabase user_player tablosunda tutulur
// localStorage cleanup için bırakıldı, gerçek okuma RAM cache + Supabase'ten
let _marketValCache = null;          // null = yüklenmedi, sayı = yüklendi
let _marketValHistCache = null;       // null = yüklenmedi, array = yüklendi
let _marketValSaveTimer = null;
let _marketValHistSaveTimer = null;

async function _marketValLoadFromServer() {
  if (!window.sb || !authUser || !authUser.id) return;
  try {
    const { data, error } = await window.sb.from('user_player')
      .select('market_val, market_val_history')
      .eq('user_id', authUser.id)
      .maybeSingle();
    if (error) { console.warn('[marketval] load hata:', error); return; }
    if (data) {
      _marketValCache = data.market_val || 0;
      _marketValHistCache = Array.isArray(data.market_val_history) ? data.market_val_history : [];
    }
  } catch(e) { console.warn('[marketval] load exception:', e); }
}

function getMarketVal() {
  return _marketValCache || 0;
}

function setMarketVal(v) {
  _marketValCache = v;
  // Debounced Supabase write
  if (window.sb && authUser && authUser.id) {
    clearTimeout(_marketValSaveTimer);
    _marketValSaveTimer = setTimeout(async () => {
      try {
        await window.sb.from('user_player').update({
          market_val: v
        }).eq('user_id', authUser.id);
      } catch(e) { console.warn('[marketval] save hata:', e); }
    }, 500);
  }
}

function openMarketModal() {
  const user = authUser || {};
  // Sadece kaptan veya kullanıcı kendisi açabilir
  document.getElementById('marketInput').value = getMarketVal();
  document.getElementById('marketModal').classList.add('open');
}
function closeMarketModal() {
  document.getElementById('marketModal').classList.remove('open');
}
function setMarketPreset(v) {
  document.getElementById('marketInput').value = v;
}
function confirmMarketVal() {
  const v = parseInt(document.getElementById('marketInput').value);
  if(!v || v < 1000) { return; }
  setMarketVal(v);
  closeMarketModal();
  const t = document.createElement('div');
  t.style.cssText = 'position:fixed;bottom:90px;left:50%;transform:translateX(-50%);background:var(--gold);color:#000;padding:8px 18px;border-radius:20px;font-size:12px;font-weight:700;z-index:9999;font-family:Twemoji Country Flags,"Barlow Condensed",sans-serif';
  t.textContent = '✅ Piyasa değeri güncellendi: ' + formatMarketVal(v);
  document.body.appendChild(t);
  setTimeout(()=>t.remove(), 2500);
}


