  if (ust === 'ekipman') { _mgSay('items', SHOP_ITEMS.length); initMarketListings(); if (_marketListingsYuklendi) _mgSay('market', _marketListings.filter(l => l && l.listed).length); }   // 956 — yüklenmediyse sayıyı initMarketListings yazar
  if (alt === 'items')   renderShopItems();
