// ── Satın al ──
async function tmConfirmBuy(){
  if(!_tmBuyTargetId) return;
  const listing = tmGetListings().find(l => l.id === _tmBuyTargetId);
  if(!listing) return;

  // 🆕 2026-08-18 · TAKIM ALIMI SUNUCUDA
  //   Eskiden alıcının parası GERÇEKTEN düşüyordu ama ilan silme RLS'e
  //   takılıyordu (DELETE politikası satıcıya kilitli) ve hata kontrol
  //   edilmiyordu: aynı takım arka arkaya birden çok kişiye "satılıyor",
  //   her biri ödüyor, satıcı hiç para almıyordu. Başlangıç kasası da
  //   ölü kod yüzünden sunucuya hiç yazılmıyordu.
  //   Artık: ilan önce atomik kapatılır, sonra para alınır; kaptanlık,
  //   satıcı ödemesi ve başlangıç kasası aynı işlemde yapılır.
  szDurum('yuk');
  let _srv = null;
  try {
    const _res = await edgeCall('buy_team_listing', { listing: _tmBuyTargetId, fiyat: _tmBuyFiyat });
    const d = _res && _res.data;
    if (!_res.ok || !d || d.error) {
      const msg = {
        ilan_satildi: 'Bu takım az önce başkası tarafından alındı.',
        takim_satildi: 'Bu takımın artık bir sahibi var.',
        kendi_ilanin: 'Kendi ilanını satın alamazsın.',
        yetersiz_bakiye: 'Yeterli bakiyen yok.',
        ilan_bulunamadi: 'İlan bulunamadı.',
        takim_devredilemedi_para_iade: 'Takım devredilemedi, ödemen iade edildi.',
        sadece_elmas: 'Takımlar yalnız elmasla satılır.',
        fiyat_dusuk: 'İlan fiyatı en düşük fiyatın altında.',
        zaten_takimda: 'Önce mevcut takımından ayrılmalısın.',
        yabanci_dolu: 'Bu takımın yabancı oyuncu kontenjanı dolu (10/10).',
        fiyat_degisti: 'İlan fiyatı değişti. Yeni fiyatı görüp tekrar dene.'
      }[d && d.error] || ((typeof _mevkiDoluMetin === 'function') && _mevkiDoluMetin(d && d.error, d && d.grup)) || 'Satın alınamadı.';
      if(typeof showJoinToast === 'function') showJoinToast('❌ ' + msg);
      try { _tmCache = null; if (typeof tmRender === 'function') tmRender(); } catch(e) {}
      _tsaSifirla();
      tmCloseBuyConfirm();
      return;
    }
    _srv = d;
    try { if (typeof wlLoadFromServer === 'function') await wlLoadFromServer(); } catch(e) {}
  } catch(e) {
    if(typeof showJoinToast === 'function') showJoinToast('❌ Sunucuya ulaşılamadı.');
    tmCloseBuyConfirm();
    return;
  }

  // Yeni takıma kaptan olarak yerleş — 681: takım, rol ve forma numarası sunucunun yazdığından okunur
  //   (eskiden burada kurulan nesne kaydedilince sunucunun verdiği forma numarası 16+ ile eziliyordu)
  const _ayniTakim = !!(_userTeam && _userTeam.countryCode === listing.countryCode && _userTeam.teamName === listing.teamName);   // 699 — kendi takımını aldı
  const _eskiTk = _ayniTakim ? '' : _takimAnahtar();
  await userTeamLoadFromServer();
  const _energyDelta = await _takimDurumTazele(_eskiTk);   // 694 — yeni takımın her şeyi sunucudan

  // Career history: TM'den satın alınan takım (kaptan) — 699: kendi takımıysa mevcut satır kaptan olur
  if (_ayniTakim && typeof getCareerHistory === 'function' && typeof _saveCareerHistory === 'function') {
    try {
      const _kl = getCareerHistory().slice(), _ks = _kl[_kl.length - 1];
      if (_ks && _ks.teamName === listing.teamName && !_ks.leaveDate) { _ks.role = 'captain'; _saveCareerHistory(_kl); }
    } catch(e) {}
  } else if (typeof pushCareerHistory === 'function') {
    const lgName = (_cftGetCountry(listing.countryCode) && _cftGetCountry(listing.countryCode).leagues && _cftGetCountry(listing.countryCode).leagues[0])
      ? _cftGetCountry(listing.countryCode).leagues[0].name : '';
    pushCareerHistory({
      teamName: listing.teamName,
      countryCode: listing.countryCode,
      leagueName: lgName,
      role: 'captain',
      joinDate: new Date().toISOString(),
    });
  }

  // İlan sunucuda zaten silindi — sadece yerel önbellekten düşür
  try {
    if (Array.isArray(_tmCache)) _tmCache = _tmCache.filter(l => l && l.id !== _tmBuyTargetId);
  } catch(e) {}

  // UI güncelle
  if(typeof applyUserTeamUI === 'function') applyUserTeamUI();
  if(typeof renderRoster === 'function') renderRoster('all');
  if(typeof trsSyncHeader === 'function') trsSyncHeader();
  if(typeof renderSettings === 'function') renderSettings();

  // 🆕 MİSAFİR MODU KALINTISI — takım alındığı halde ana sayfada "Takıma Katıl"
  //   kartı ve ziyaretçi görünümü kalıyordu; ancak yeniden girişte düzeliyordu.
  //   Artık takım bilgisi sunucudan tazelenip tüm ana sayfa panelleri yeniden çiziliyor.
  try {
    if (typeof _viewingTeam !== 'undefined' && _viewingTeam && typeof exitGuestMode === 'function') {
      try { exitGuestMode(true); } catch(e) {}
    }
    const _tazele = () => {
      try { if (typeof applyUserTeamUI === 'function') applyUserTeamUI(); } catch(e) {}
      try { if (typeof updateHero === 'function') updateHero(); } catch(e) {}
      try { if (typeof renderHomeUserCard === 'function') renderHomeUserCard(); } catch(e) {}
      try { if (typeof renderHomeSmartAction === 'function') renderHomeSmartAction(); } catch(e) {}
      try { if (typeof renderHomeQuickAccessBadges === 'function') renderHomeQuickAccessBadges(); } catch(e) {}
      try { if (typeof renderHomeNextMatch === 'function') renderHomeNextMatch(true); } catch(e) {}
      try { if (typeof renderHomeSeasonBlock === 'function') renderHomeSeasonBlock(); } catch(e) {}
      try { if (typeof renderHomeLeagueScene === 'function') renderHomeLeagueScene(); } catch(e) {}
      try { if (typeof renderHomeEuro === 'function') renderHomeEuro(); } catch(e) {}
      try { if (typeof renderFixture === 'function') renderFixture(); } catch(e) {}
      try { if (typeof tfRender === 'function') tfRender(); } catch(e) {}
    };
    if (typeof userTeamLoadFromServer === 'function') {
      userTeamLoadFromServer().catch(()=>{}).then(_tazele);
    } else { _tazele(); }
  } catch(e) {}

  szDurum('imzali');
  let _mktToast = `🎉 ${listing.teamName} takımı senin oldu!`;
  if(_energyDelta > 0) _mktToast += ` ⚡+${_energyDelta} bonus enerji!`;
  if(typeof showJoinToast === 'function') showJoinToast(_mktToast);

  // Listeyi tazele
  renderTeamMarket();
}


// ── Diamond Paketleri ──
// 633 · Paket görseli tamamen SVG: 1-5 elmas yığını, 6 kadife kese, 7-8 sandık, 9 ışıklı altın sandık
const _DP_YIGIN = [[1],[2],[2,1],[3,2],[3,2,1]];
function _dpTas(x, y, w) { return '<use href="#ic-elmas-tas" x="' + x + '" y="' + y + '" width="' + w + '" height="' + (w * 56 / 64).toFixed(1) + '"/>'; }
function _dpPirilti(noktalar) {
  return noktalar.map(([x, y], k) => '<use href="#ic-yildiz4" class="dp-par" style="animation-delay:' + (k * .45) + 's;transform-origin:'
    + (x + 3.5) + 'px ' + (y + 3.5) + 'px" x="' + x + '" y="' + y + '" width="7" height="7"/>').join('');
}
function _dpIsinlar(altin) {
  let s = '<g class="dp-isin">';
  for (let k = 0; k < 12; k++) s += '<polygon points="47,34 53,34 50,-14" fill="url(#dp-' + (altin ? 'isinA' : 'isinG') + ')" transform="rotate(' + (k * 30) + ' 50 34)"/>';
  return s + '</g>';
}
function _dpYigin(i) {
  const sira = _DP_YIGIN[i], enCok = Math.max(...sira);
  const w = Math.min(46, 92 / (enCok * 0.82 + 0.18)), h = w * 56 / 64, yuk = (sira.length - 1) * h * 0.42 + h;
  const parca = [];
  sira.forEach((n, r) => {
    const y = (72 + yuk) / 2 - h - r * h * 0.42, x0 = (100 - (n * w * 0.82 + w * 0.18)) / 2;
    for (let k = 0; k < n; k++) parca.push({ x: x0 + k * w * 0.82, y: y + ((k * 7 + r * 3) % 3) - 1, r });
  });
  return '<ellipse cx="50" cy="40" rx="' + (30 + i * 2) + '" ry="' + (18 + i) + '" fill="url(#dp-hale)"/>'
    + parca.sort((p, q) => q.r - p.r).map(p => _dpTas(p.x.toFixed(1), p.y.toFixed(1), w.toFixed(1))).join('')
    + (i >= 3 ? _dpPirilti([[12,14],[82,20],[20,56]].slice(0, i - 2)) : '');
}
function _dpKese() {
  return '<ellipse cx="50" cy="40" rx="44" ry="30" fill="url(#dp-hale)"/>' + _dpTas(33, 8, 18) + _dpTas(49, 6, 18) + _dpTas(41, 14, 18)
    + '<path d="M33 29 Q19 42 25 57 Q31 66 50 66 Q69 66 75 57 Q81 42 67 29 Z" fill="url(#dp-kadife)" stroke="#1d0d38" stroke-width="1.2"/>'
    + '<ellipse cx="50" cy="28.5" rx="18" ry="4" fill="#1a0b31"/>' + _dpTas(36, 18, 16) + _dpTas(50, 17, 16)
    + '<path d="M31 30 Q50 36 69 30" fill="none" stroke="url(#dp-altin)" stroke-width="3.2" stroke-linecap="round"/>'
    + '<circle cx="50" cy="34" r="2.6" fill="url(#dp-altin)"/>' + _dpTas(72, 56, 14) + _dpPirilti([[14,16],[84,12],[10,50]]);
}
function _dpSandik(altin, dolu) {
  const govde = altin ? 'altin' : 'ahsap', serit = altin ? 'altinKoyu' : 'altin';
  const taslar = dolu >= 2
    ? [[22,22,16],[62,22,16],[33,13,18],[49,12,18],[41,20,18],[28,26,15],[57,26,15],[45,4,15]]
    : [[26,22,16],[58,22,16],[36,15,18],[48,16,18],[42,22,16]];
  return '<ellipse cx="50" cy="38" rx="48" ry="34" fill="url(#dp-' + (altin ? 'haleA' : 'hale') + ')"/>' + (dolu >= 2 ? _dpIsinlar(altin) : '')
    + '<path d="M23 34 L28 11 Q50 6 72 11 L77 34 Z" fill="url(#dp-ahsapIc)" stroke="url(#dp-' + serit + ')" stroke-width="2"/>'
    + '<path d="M28 11 Q50 6 72 11" fill="none" stroke="url(#dp-' + serit + ')" stroke-width="3"/>'
    + taslar.map(([x, y, w]) => _dpTas(x, y, w)).join('')
    + '<rect x="20" y="34" width="60" height="29" rx="4" fill="url(#dp-' + govde + ')" stroke="' + (altin ? '#8a5a08' : '#3b200a') + '" stroke-width="1.2"/>'
    + '<rect x="18" y="31" width="64" height="6" rx="2.5" fill="url(#dp-' + serit + ')"/>'
    + '<rect x="28" y="36" width="5" height="27" fill="url(#dp-' + serit + ')"/><rect x="67" y="36" width="5" height="27" fill="url(#dp-' + serit + ')"/>'
    + '<rect x="44.5" y="40" width="11" height="13" rx="2" fill="url(#dp-' + (altin ? 'altinKoyu' : 'altin') + ')"/>'
    + '<circle cx="50" cy="45" r="1.8" fill="#2a1606"/><rect x="49.2" y="45" width="1.6" height="4.5" fill="#2a1606"/>'
    + (dolu >= 3 ? _dpTas(8, 54, 14) + _dpTas(78, 55, 13) + _dpTas(16, 59, 11) : '')
    + _dpPirilti(altin ? [[8,10],[86,8],[4,40],[90,38],[50,0]] : [[10,12],[84,14],[6,44]].slice(0, dolu + 1));
}
function _dpGorsel(i) {
  const ic = i <= 4 ? _dpYigin(i) : i === 5 ? _dpKese() : i === 6 ? _dpSandik(false, 1) : i === 7 ? _dpSandik(false, 2) : _dpSandik(true, 3);
  return '<svg class="dp-gorsel" viewBox="0 0 100 72">' + ic + '</svg>';
}
function renderDiamondPacks() {
  const el = document.getElementById('diamondPackages');
  if(!el) return;
  // 764 — uygulamada (Play / App Store) ürün tanımlı değilse paket gösterilmez
  const _dpGoster = p => !(p.priceEur === 1 && typeof _playAktifMi === 'function' && _playAktifMi() && !(window._playFiyat && window._playFiyat['dia_1']));
  el.classList.toggle('dp-bes', DIAMOND_PACKS.filter(_dpGoster).length === 5);
  el.innerHTML = DIAMOND_PACKS.map((p,i) => {
    if (!_dpGoster(p)) return '';
    const total = p.amount + (p.bonus || 0);
    const bonusPct = p.amount > 0 ? Math.round((p.bonus / p.amount) * 100) : 0;
    const isBest = i === DIAMOND_PACKS.length - 1; // son paket = en büyük
    return `
    <div class="dp-card ${isBest?'dp-best':''}" onclick="buyDiamondPack(${i})">
      ${p.tag?`<div class="dp-tag">${p.tag}</div>`:''}
      ${_dpGorsel(i)}
      <div class="dp-amount">${total.toLocaleString('tr')}</div>
      ${p.bonus ? `<div class="dp-bonus">+${p.bonus.toLocaleString('tr')} bonus (+${bonusPct}%)</div>` : `<div class="dp-bonus" style="visibility:hidden">.</div>`}
      <div class="dp-price">${(window._playFiyat && window._playFiyat["dia_" + p.priceEur]) || p.price}</div>
      <div class="dp-btn">Satın Al</div>
    </div>
  `;
  }).join('');
  _bpKartCiz();   // 730
}

// ═══════════════════════════════════════════════════════════════════
//  XSOLLA ÖDEME — elmas paketi satın alma
//
//  AKIŞ:
//    1) Sunucudan ödeme jetonu iste (kullanıcı kimliği sunucuda
//       doğrulanır, tutar ve elmas miktarı SUNUCUDAKİ tablodan gelir).
//    2) Xsolla ödeme penceresini oyunun üzerinde aç.
//    3) Pencere kapanınca cüzdanı sunucudan yokla — elmas Xsolla'nın
//       webhook'u ile yatar, o yüzden birkaç saniye gecikebilir.
//
//  ⚠️ Bu dosyada elmas YATIRAN tek satır yok. İstemci sadece jeton
//     ister ve sonucu bekler. Elmas basma yetkisi tamamen sunucuda.
// ═══════════════════════════════════════════════════════════════════
const XSOLLA_FN     = SUPABASE_URL + '/functions/v1/xsolla';
const XSOLLA_WIDGET = 'https://cdn.xsolla.net/embed/paystation/1.2.3/widget.min.js';
let _xsWidgetYukleniyor = null;

function _xsWidgetYukle() {
  if (window.XPayStationWidget) return Promise.resolve(true);
  if (_xsWidgetYukleniyor) return _xsWidgetYukleniyor;
  _xsWidgetYukleniyor = new Promise((coz) => {
    const sc = document.createElement('script');
    sc.src = XSOLLA_WIDGET;
    sc.async = true;
    sc.onload  = () => coz(!!window.XPayStationWidget);
    sc.onerror = () => coz(false);
    document.head.appendChild(sc);
    setTimeout(() => coz(!!window.XPayStationWidget), 8000);
  });
  return _xsWidgetYukleniyor;
}

// Ödeme sonrası cüzdanı yokla — webhook birkaç saniye sürebilir.
//   ⚠️ Başlık ROZETİ bilerek güncellenmiyor: eski rakam ekranda kalsın ki
//   kutlamadan sonra uçan elmaslar sayacı yükseltebilsin.
//   Dönen değer: yatan elmas miktarı (yatmadıysa null).
async function _xsElmasBekle(oncekiDia, beklenenDia, tur) {
  const ONCE   = Number(oncekiDia) || 0;
  const HEDEF  = ONCE + (Number(beklenenDia) || 0);
  const ADIM   = Math.max(1, Number(tur) || 20);
  for (let i = 0; i < ADIM; i++) {                // varsayılan 20 × 1.5 sn ≈ 30 sn
    await new Promise(r => setTimeout(r, 1500));
    try {
      const c = await wlLoadFromServer();          // _wlCache tazelenir, rozet DONUK kalır
      const simdi = Number(c && c.dia) || 0;
      if (simdi >= HEDEF) return simdi - ONCE;
      if (simdi > ONCE)   return simdi - ONCE;     // kısmi/farklı tutar da olsa yakala
    } catch(e) {}
  }
  return null;
}

// 634 · Fiş sesleri: yazıcı (fiş bu sesin bastığı anlarda ilerler) + ödeme anında yazar kasa. Buton Sesi anahtarına bağlı.
const _FIS_SES = { yazici: 'fis-yazici.mp3?v=634', kasa: 'fis-kasa.mp3?v=634' };
const _fisBuf = {};
function _fisSesYukle(ad) {
  if (!_fisBuf[ad]) _fisBuf[ad] = fetch(_FIS_SES[ad]).then(r => r.arrayBuffer())
    .then(b => _cftGetAudioCtx().decodeAudioData(b))
    .catch(e => { _fisBuf[ad] = null; throw e; });
  return _fisBuf[ad];
}
function _fisSesCal(buf) {
  const c = _cftGetAudioCtx(), k = c.createBufferSource();
  k.buffer = buf; k.connect(c.destination); k.start();
}
// Yazıcı sesinin 50 ms'lik enerji dilimlerinden fişin çıkış kareleri
function _fisKareler(buf) {
  const d = buf.getChannelData(0), adim = Math.round(buf.sampleRate * 0.05), e = [];
  for (let i = 0; i < d.length; i += adim) {
    let t = 0; const son = Math.min(i + adim, d.length);
    for (let j = i; j < son; j++) t += d[j] * d[j];
    e.push(Math.max(0, Math.sqrt(t / (son - i)) - 0.02));
  }
  const top = e.reduce((a, b) => a + b, 0); let kum = 0;
  return [{ transform: 'translateY(-100%)', offset: 0 }].concat(e.map((v, i) => {
    kum += v;
    return { transform: 'translateY(' + (kum / top * 100 - 100).toFixed(1) + '%)', offset: Math.min(1, (i + 1) * adim / d.length) };
  }));
}

// 🎉 KUTLAMA — 633 · kâğıt fiş: yazdırılır, "HESABA GEÇTİ" mührü basılır, elmaslar cüzdana uçar
async function _xsKutlama(miktar, bitti) {
  miktar = Math.round(Number(miktar) || 0);
  if (miktar <= 0) { if (bitti) bitti(); return; }

  // Ana sayfaya dön (sayfa YENİDEN YÜKLENMEZ, sadece sekme değişir)
  try {
    if (typeof showPage === 'function') {
      showPage('home', (typeof findNavBtn === 'function') ? findNavBtn('home') : null);
    }
  } catch(e) {}

  const tr = n => n.toLocaleString('tr');
  const bekle = ms => new Promise(r => setTimeout(r, ms));
  const paket = DIAMOND_PACKS.find(p => p.amount + (p.bonus || 0) === miktar);
  const sesler = Promise.all([_fisSesYukle('yazici'), _fisSesYukle('kasa')]).catch(() => []);
  const ov = document.createElement('div');
  ov.className = 'xsf-ov';
  ov.style.top = Math.max(0, document.getElementById('topbar').getBoundingClientRect().bottom) + 'px';
  ov.innerHTML = '<div class="xsf-yuva"></div><div class="xsf-kap"><div class="xsf-fis">'
    + '<div class="xsf-ust"><span data-noi18n>CITY SOCCER CLUB</span><small>ELMAS SATIN ALMA</small></div>'
    + '<div class="xsf-kesik"></div>'
    + (paket ? '<div class="xsf-sat"><em>Paket</em><b data-noi18n>' + tr(paket.amount) + '</b></div>'
        + (paket.bonus ? '<div class="xsf-sat"><em><span>Bonus</span> (+' + Math.round(paket.bonus / paket.amount * 100) + '%)</em><b data-noi18n>' + tr(paket.bonus) + '</b></div>' : '')
        + '<div class="xsf-kesik"></div>' : '')
    + '<div class="xsf-top"><span>Toplam</span><b data-noi18n>+' + tr(miktar) + '<svg viewBox="0 0 64 56"><use href="#ic-elmas-tas"/></svg></b></div>'
    + '<div class="xsf-muhur">HESABA GEÇTİ</div>'
    + '</div></div>';
  document.body.appendChild(ov);
  requestAnimationFrame(() => ov.classList.add('acik'));

  const fis = ov.querySelector('.xsf-fis');
  const [yazici, kasa] = await sesler;
  const sesli = _cftButtonSoundEnabled && yazici;
  await bekle(250);
  if (sesli) { _sesKis(0.12, 0.3); _fisSesCal(yazici); }
  await fis.animate(yazici ? _fisKareler(yazici) : [{ transform: 'translateY(-100%)' }, { transform: 'translateY(0)' }],
    { duration: yazici ? yazici.duration * 1000 : 1100, easing: 'linear', fill: 'forwards' }).finished;
  await bekle(150);
  if (sesli) { if (kasa) _fisSesCal(kasa); _sesKis(1, 1.2); }
  await bekle(90);
  ov.querySelector('.xsf-muhur').classList.add('bas');
  await bekle(170);
  fis.classList.add('titre');
  await bekle(2400);

  const r = ov.querySelector('.xsf-top svg').getBoundingClientRect();
  fis.animate([{ transform: 'translateY(0)' }, { transform: 'translateY(-105%)' }], { duration: 420, easing: 'ease-in', fill: 'forwards' });
  ov.classList.remove('acik');
  setTimeout(() => ov.remove(), 450);
  // wlFlyReward başlıktaki ESKİ rakamdan başlayıp sayarak yükseltir
  wlFlyReward({ left: r.left, top: r.top, width: r.width, height: r.height }, 'dia', miktar, () => {
    try { window._WL_HOLD.dia = false; } catch(e) {}
    try { wlSyncHeader(); } catch(e) {}
    if (bitti) { try { bitti(); } catch(e) {} }
  });
}

// ═══════════════════════════════════════════════════════════════════
//  🔔 538 — BİLDİRİM ALTYAPISI (cihaz içi / local notification)
//  Sunucuya, FCM'e veya push jetonuna GEREK YOK: maç saatleri fikstürden
//  önceden bilindiği için hatırlatmalar doğrudan cihazda planlanır ve
//  uygulama kapalıyken de çalışır.
//    APK      → @capacitor/local-notifications
//    Tarayıcı → Notification API (sayfa açıkken) + uygulama içi şerit
//  Yeni bildirim türü eklemek: BLD_TIP listesine bir satır + _bldPlanla
//  içinde o türün zamanını üret. Gerisi (izin, kanal, ayar, iptal) hazır.
// ═══════════════════════════════════════════════════════════════════
// CSC26 logosu — bildirim şeridi ve tarayıcı bildirimi ikonu (88x88 png, ~6 KB)
// 957 — dosyada (medya/g957/)
const BLD_LOGO = 'medya/g957/bildirim-logo.80f659dd.png';
const BLD_ANAHTAR  = 'cft_bildirim';
const BLD_KANAL    = 'csc-mac';
const BLD_MAC_ONCE = 2 * 60 * 1000;        // maç başlangıcından 2 dk önce
const BLD_MAC_SONRA = 15 * 60 * 1000;      // maç bitişi (simülasyon ~12 dk, 15 dk güvenli)
const BLD_GUNLUK_SAAT = 12;                // günlük hediye hatırlatması (yerel saat)
const BLD_PENCERE  = 72 * 60 * 60 * 1000;  // kaç saat ilerisi planlansın
const BLD_WEB_UFUK = 6 * 60 * 60 * 1000;   // tarayıcıda timer ufku
let _bldWebZaman = [];
let _bldSonTarama = 0;
let _bldBasladi = false;

// 🆕 540 — Bildirim türleri. Yeni tür eklemek: buraya bir satır + _bldPlanUret
//   içine zamanını üreten küçük bir blok + ayarlar ekranına bir anahtar.
const BLD_TIPLER = ['mac2','macSonu','gunluk','fedSecim','sezon','anlik','antrenman'];
// 🔔 642 — telefon sunucu bildirimi alıyorsa bunlar sunucudan gelir (zamanında); yerelde planlanmaz
const BLD_SUNUCU_TIPLER = ['mac2','macSonu','gunluk'];
function _bldVarsayilan(){
  return { acik:true, mac2:true, macSonu:true, gunluk:true, fedSecim:true, sezon:true, anlik:true, antrenman:true };
}
function _bldAyar(){
  try { return Object.assign(_bldVarsayilan(), JSON.parse(localStorage.getItem(BLD_ANAHTAR) || 'null') || {}); }
  catch(e){ return _bldVarsayilan(); }
}
function _bldAyarYaz(y){ try { localStorage.setItem(BLD_ANAHTAR, JSON.stringify(y)); } catch(e){} }

// Capacitor LocalNotifications eklentisi (APK)
function _bldLN(){
  try { return (window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.LocalNotifications) || null; }
  catch(e){ return null; }
}
function _bldOrtam(){
  if (_bldLN()) return 'native';
  // 🆕 543 — Eklentisiz eski APK: WebView'in Notification API'si telefona bildirim
  //   gösteremez; burada izin sormak "soruldu" işaretini boşa harcıyordu.
  if (window.Capacitor) return 'yok';
  if (typeof Notification !== 'undefined') return 'web';
  return 'yok';
}

async function _bldIzinDurum(){
  let s = 'denied';
  const LN = _bldLN();
  if (LN) { try { const r = await LN.checkPermissions(); s = (r && r.display) || 'prompt'; } catch(e){ s = 'prompt'; } }
  else if (typeof Notification !== 'undefined') s = (Notification.permission === 'default') ? 'prompt' : Notification.permission;
  window._bldIzinSon = s;                          // Ayarlar > Ortam satırı gösterir
  return s;
}
async function _bldIzinIste(){
  const LN = _bldLN();
  if (LN) { try { const r = await LN.requestPermissions(); return (r && r.display) || 'denied'; } catch(e){ return 'denied'; } }
  if (typeof Notification !== 'undefined') { try { return await Notification.requestPermission(); } catch(e){ return 'denied'; } }
  return 'denied';
}

// match_key → sabit sayısal id (yeniden planlarken kopya oluşmasın)
function _bldId(anahtar){
  let h = 5381; const s = String(anahtar || '');
  for (let i = 0; i < s.length; i++) h = (((h * 33) ^ s.charCodeAt(i)) >>> 0);
  return (h % 2000000000) + 1;
}

// Bildirim metinleri — dil desteğiyle
function _bldT(x){ return (typeof T === 'function') ? T(x) : x; }
function _bldRakip(row, takim){ return ((row.home_team === takim) ? row.away_team : row.home_team) || ''; }
function _bldMacMetin(row, takim){
  return { baslik: _bldT('Maç başlıyor!'),
           govde: _bldRakip(row, takim) + ' ' + _bldT('maçına 2 dakika kaldı. Yerini al!') };
}
function _bldMacSonuMetin(row, takim){
  return { baslik: _bldT('Maç bitti!'),
           govde: _bldRakip(row, takim) + ' ' + _bldT('maçının sonucu hazır. Sonuca bak!') };
}

// Planlanacak tüm bildirimleri üret (tür tür)
function _bldPlanUret(rows, takim){
  const ay = _bldAyar(), simdi = Date.now(), liste = [];
  const ekle = (tip, anahtar, at, baslik, govde) => {
    if (!ay[tip]) return;
    if (_pushSunucuda && BLD_SUNUCU_TIPLER.includes(tip)) return;
    if (!isFinite(at)) return;
    if (at <= simdi + 15000) return;              // çok yakın / geçmiş
    if (at > simdi + BLD_PENCERE) return;         // pencere dışı
    liste.push({ tip:tip, id:_bldId(tip + ':' + anahtar), at:at, baslik:baslik, govde:govde, key:anahtar });
  };

  // ── Maç başlangıcı + maç sonucu ──
  for (const r of (rows || [])) {
    if (!r || !r.kickoff_at || r.status === 'finished') continue;
    const t = new Date(r.kickoff_at).getTime();
    if (!isFinite(t)) continue;
    const anahtar = r.match_key || (r.home_team + r.away_team + r.kickoff_at);
    const m1 = _bldMacMetin(r, takim);
    ekle('mac2', anahtar, t - BLD_MAC_ONCE, m1.baslik, m1.govde);
    const m2 = _bldMacSonuMetin(r, takim);
    ekle('macSonu', anahtar, t + BLD_MAC_SONRA, m2.baslik, m2.govde);
  }

  // ── Günlük giriş hediyesi (her gün yerel saat 12:00) ──
  //   Hediye zaten alındıysa BUGÜNÜN hatırlatması hiç kurulmaz; her taramada
  //   liste sıfırdan üretildiği için alındığı anda otomatik düşer.
  try {
    let bekleyen = true;
    if (typeof evGetStreak === 'function') {
      const s = evGetStreak();
      const g = s.login_streak || 0;
      bekleyen = (g >= 1) && !((s.streak_claimed || []).includes(g));
    }
    if (bekleyen) {
      for (let i = 0; i < 3; i++) {
        const d0 = new Date(simdi + i * 86400000);
        d0.setHours(BLD_GUNLUK_SAAT, 0, 0, 0);
        const g = d0.getFullYear() + '-' + (d0.getMonth() + 1) + '-' + d0.getDate();
        ekle('gunluk', g, d0.getTime(), _bldT('Günlük hediyen hazır!'),
             _bldT('Bugünkü giriş hediyeni henüz almadın. Serini bozma!'));
      }
    }
  } catch(e){}

  // ── 774 — Antrenman bitişi · 778: birbirine 5 dk yakın bitenler tek bildirim (en son bitenin anında) ──
  if (Array.isArray(_activeCache)) {
    const L = _activeCache.filter(a => a && a.id && a.endTime).sort((a, b) => Number(a.endTime) - Number(b.endTime));
    let grup = [];
    const yaz = () => {
      if (!grup.length) return;
      const son = grup[grup.length - 1];
      ekle('antrenman', grup.map(a => a.id).join('+'), Number(son.endTime), _bldT('Antrenman Tamamlandı!'),
           _bldT(grup.length === 1 ? (son.skillName || '') + ' antrenmanın bitti. Puanlarını topla!' : grup.length + ' antrenmanın bitti. Puanlarını topla!'));
      grup = [];
    };
    for (const a of L) { if (grup.length && Number(a.endTime) - Number(grup[0].endTime) > 5 * 60000) yaz(); grup.push(a); }
    yaz();
  }

  // ── Sezon takvimi: federasyon seçimi + yeni sezon ──
  try {
    if (typeof getSeasonInfo === 'function' && typeof _seasonRangeMs === 'function') {
      const S = getSeasonInfo().season || 1;
      for (const s of [S, S + 1]) {
        const ar = _seasonRangeMs(s);
        if (!ar || !isFinite(ar[0]) || !ar[0]) continue;
        // Seçim sezonun 1-3. günü açık; 1. günün TR saatiyle 12:00'sinde hatırlat
        ekle('fedSecim', 's' + s, ar[0] + 9 * 3600000,
             _bldT('Federasyon seçimi başladı'),
             _bldT('Oyunu kullan — seçim 3. günün akşamı kapanıyor.'));
        // Yeni sezon/fikstür 39. günde belli oluyor
        ekle('sezon', 's' + s, ar[0] + (SEZON_DONUS_GUNU - 1) * 86400000 + 8 * 3600000,
             _bldT('Yeni sezon başlıyor!'),
             _bldT('Yeni fikstür ve ligler belli oldu. Kadronu kontrol et!'));
      }
    }
  } catch(e){}

  liste.sort((a,b) => a.at - b.at);
  return liste.slice(0, 40);                      // Android kuyruk sınırına saygı
}

// Bekleyen tüm planları iptal et
async function _bldTemizle(){
  const LN = _bldLN();
  if (LN) {
    try {
      const p = await LN.getPending();
      const koru = !Array.isArray(_activeCache);   // 774
      const eski = ((p && p.notifications) || []).filter(n => !(koru && n.extra && n.extra.tip === 'antrenman'));
      if (eski.length) await LN.cancel({ notifications: eski.map(n => ({ id: n.id })) });
    } catch(e){}
  }
  _bldWebZaman.forEach(clearTimeout); _bldWebZaman = [];
}

// Tarayıcı/uygulama içi gösterim
function _bldGoster(baslik, govde){
  try {
    if (typeof Notification !== 'undefined' && Notification.permission === 'granted') {
      const n = new Notification(baslik, { body: govde, tag: 'csc-mac', icon: BLD_LOGO, badge: BLD_LOGO });
      n.onclick = function(){ try { window.focus(); if (typeof showPage === 'function') showPage('home', null); } catch(e){} n.close(); };
      return;
    }
  } catch(e){}
  _bldIcSerit(baslik, govde);
}

// Uygulama açıkken üstte beliren şerit (izin yoksa da kullanıcı haberdar olur)
function _bldIcSerit(baslik, govde, git){
  try {
    const eski = document.getElementById('bldSerit'); if (eski) eski.remove();
    const d = document.createElement('div');
    d.id = 'bldSerit';
    d.style.cssText = 'position:fixed;left:10px;right:10px;top:10px;z-index:99999;display:flex;gap:10px;align-items:center;'
      + 'padding:11px 13px;border-radius:13px;background:linear-gradient(160deg,#141a23,#0d1219);'
      + "border:1px solid rgba(0,230,118,.40);box-shadow:0 10px 26px -10px rgba(0,0,0,.8);font-family:Twemoji Country Flags,'Saira',sans-serif;"
      + 'cursor:pointer;animation:bldIn .25s ease';
    d.innerHTML = '<img src="' + BLD_LOGO + '" alt="" style="width:44px;height:44px;border-radius:11px;flex-shrink:0;'
      + 'box-shadow:0 2px 8px rgba(0,0,0,.55)"><div style="min-width:0">'
      + '<div style="font-family:Twemoji Country Flags,\'Oswald\',sans-serif;font-size:13px;font-weight:700;color:#fff">'
      + _escapeHtml(baslik) + '</div>'
      + '<div style="font-size:11.5px;font-weight:600;color:#c2c9d6;margin-top:2px">' + _escapeHtml(govde) + '</div></div>';
    d.onclick = function(){ d.remove(); try { if (git) git(); else if (typeof showPage === 'function') showPage('home', null); } catch(e){} };
    document.body.appendChild(d);
    setTimeout(() => { try { d.remove(); } catch(e){} }, 12000);
  } catch(e){}
}

// 🆕 540 — ANLIK OLAY KÖPRÜSÜ
//   Mesaj, kupon sonucu, haftalık yarış gibi olaylar önceden bilinemez.
//   Uygulama AÇIKKEN zaten ekrandaki bildirim şeridiyle gösteriliyor.
//   Uygulama ARKA PLANDAYKEN bu köprü aynı olayı telefon bildirimine çevirir.
//   (Uygulama tamamen kapalıyken bunlar için sunucu push'u — FCM — gerekir.)
async function _bldAnlik(baslik, govde){
  try {
    const ay = _bldAyar();
    if (!ay.acik || !ay.anlik) return false;
    if (!document.hidden) return false;                 // ekrandaysa şerit yeter
    if ((await _bldIzinDurum()) !== 'granted') return false;
    const LN = _bldLN();
    if (LN) {
      await LN.schedule({ notifications: [{
        id: 1900000000 + (Date.now() % 90000000),
        title: baslik, body: govde, channelId: BLD_KANAL,
        isExactNotification: false,
        extra: { tip: 'anlik' }
      }] });
      return true;
    }
    if (typeof Notification !== 'undefined' && Notification.permission === 'granted') {
      const n = new Notification(baslik, { body: govde, icon: BLD_LOGO, badge: BLD_LOGO });
      n.onclick = function(){ try { window.focus(); } catch(e){} n.close(); };
      return true;
    }
  } catch(e){ console.warn('[bld] anlık:', e && e.message); }
  return false;
}
window._bldAnlik = _bldAnlik;

// Asıl planlama
async function _bldPlanla(rows, takim){
  const ay = _bldAyar();
  await _bldTemizle();
  if (!ay.acik) return 0;
  const liste = _bldPlanUret(rows, takim);
  if (!liste.length) return 0;

  const LN = _bldLN();
  if (LN) {
    try {
      await LN.schedule({ notifications: liste.map(x => ({
        id: x.id, title: x.baslik, body: x.govde,
        schedule: { at: new Date(x.at), allowWhileIdle: true },
        // ⚠️ @capacitor/local-notifications 8.3+: varsayılan (true) her schedule()
        //   çağrısında sistemin "Alarmlar ve hatırlatıcılar" ekranını AÇIYOR.
        //   Tam alarm istemiyoruz (Play politikası) → esnek alarm, ekran açılmaz.
        isExactNotification: false,
        channelId: BLD_KANAL,
        // smallIcon verilmedi → eklenti varsayılanı (uygulama ikonu) kullanılır.
        // res/drawable/ic_stat_icon.png eklersen burada belirtip kullanabilirsin.
        extra: { tip: x.tip, match_key: x.key }
      })) });
    } catch(e){ console.warn('[bld] planlama hatası:', e && e.message); return 0; }
    console.info('[bld] ' + liste.length + ' maç hatırlatması planlandı (native)');
    return liste.length;
  }

  // Tarayıcı: sayfa açık kaldığı sürece
  let n = 0;
  for (const x of liste) {
    const gecikme = x.at - Date.now();
    if (gecikme <= 0 || gecikme > BLD_WEB_UFUK) continue;
    _bldWebZaman.push(setTimeout(() => _bldGoster(x.baslik, x.govde), gecikme));
    n++;
  }
  if (n) console.info('[bld] ' + n + ' maç hatırlatması kuruldu (tarayıcı)');
  return n;
}

// Yaklaşan maçları getir (kendi kulübün + uyruğunun milli maçları)
// 956 — satırlar yalnız mac2 / macSonu bildirimlerinde kullanılır: ikisini de sunucu gönderiyorsa (ya da ikisi de kapalıysa) sorgu yok.
//   Başlama saatleri sabit: zorunlu yeniden planlamada (antrenman, hediye, öne gelme) 12 dk'lık kendi önbelleği kullanılır;
//   10 dk'lık periyodik tarama her zaman taze okur.
let _bldMacOnb = null;
async function _bldMaclariGetir(takim, yeniden){
  const simdi = Date.now();
  try { const _ay = _bldAyar(); if (['mac2', 'macSonu'].every(t => !_ay[t] || (_pushSunucuda && BLD_SUNUCU_TIPLER.includes(t)))) return []; } catch(e) {}
  if (window._hmStripCache && window._hmStripCache.takim === takim
      && Array.isArray(window._hmStripCache.rows)
      && (simdi - window._hmStripCache.t) < 5 * 60 * 1000) {
    return window._hmStripCache.rows;
  }
  if (!window.sb) return [];
  let uyruk = null;
  try { uyruk = (typeof getUserNationalityCC === 'function' ? getUserNationalityCC() : null)
               || (window.authUser && window.authUser.nationality) || null; } catch(e){}
  if (yeniden && _bldMacOnb && _bldMacOnb.takim === takim && _bldMacOnb.uyruk === uyruk && simdi - _bldMacOnb.t < 12 * 60 * 1000) {
    return _bldMacOnb.rows.filter(r => r && new Date(r.kickoff_at).getTime() >= simdi - 5 * 60 * 1000);   // 956 — taze sorgunun süzgeci
  }
  let _hata = false;
  const nowIso = new Date(simdi - 5 * 60 * 1000).toISOString();
  const kolon = 'match_key,home_team,away_team,kickoff_at,status';
  let rows = [];
  if (takim) {
    try {
      const { data, error } = await window.sb.from('match_state').select(kolon)
        .or('home_team.eq.' + takim + ',away_team.eq.' + takim)
        .gte('kickoff_at', nowIso).neq('status', 'finished')
        .order('kickoff_at', { ascending: true }).limit(15);
      if (error) _hata = true;
      rows = data || [];
    } catch(e){ _hata = true; }
  }
  // Milli maçlar (EURO Nations Cup) — kadroda olmasan da uyruğunun maçı
  try {
    let ulkeAd = null;
    try { const c = (typeof _cftGetCountry === 'function' && uyruk) ? _cftGetCountry(uyruk) : null;
          ulkeAd = (c && (c.name || c.countryName)) || null; } catch(e){}
    if (uyruk) {
      const adlar = [ulkeAd, uyruk].filter(Boolean);
      const or = adlar.map(a => 'home_team.eq.' + a + ',away_team.eq.' + a).join(',');
      const { data: nt, error: _ne } = await window.sb.from('match_state').select(kolon)
        .eq('tournament_key', 'enc').or(or)
        .gte('kickoff_at', nowIso).neq('status', 'finished')
        .order('kickoff_at', { ascending: true }).limit(6);
      if (_ne) _hata = true;
      if (Array.isArray(nt) && nt.length) {
        const var_ = new Set(rows.map(r => r.match_key));
        for (const r of nt) if (!var_.has(r.match_key)) rows.push(r);
      }
    }
  } catch(e){ _hata = true; }
  if (!_hata) _bldMacOnb = { takim, uyruk, t: simdi, rows: rows.slice() };   // 956
  return rows;
}

// Tarama + planlama
async function _bldMacTara(zorla){
  try {
    if (_bldOrtam() === 'yok') return;
    const ay = _bldAyar();
    if (!ay.acik) { await _bldTemizle(); return; }
    if (!zorla && (Date.now() - _bldSonTarama) < 5 * 60 * 1000) return;
    if ((await _bldIzinDurum()) !== 'granted') return;
    _bldSonTarama = Date.now();
    const takim = (typeof _userTeam !== 'undefined' && _userTeam && _userTeam.teamName) || '';
    const rows = await _bldMaclariGetir(takim, zorla === true);   // 956 — zorunlu yeniden planlama önbelleği kullanabilir
    await _bldPlanla(rows, takim);
    if (_pushToken && !_pushKayitli) _pushKaydet();
  } catch(e){ console.warn('[bld] tarama hatası:', e && e.message); }
}

// ═══ 🔔 550 — FCM PUSH (uygulama tamamen kapalıyken mesaj/teklif/katılma isteği) ═══
//   APK: @capacitor/push-notifications + android/app/google-services.json
//   iOS: AppDelegate APNs jetonunu FCM jetonuna çevirip eklentiye verir
//   Jeton sunucuda public.push_tokens'a push_token_kaydet RPC'si ile yazılır;
//   gönderimi tick-matches (inboxSend) yapar. Ayar: Bildirimler + "Mesaj ve anlık olaylar".
let _pushToken = null, _pushKuruldu = false, _pushKayitli = false, _pushSunucuda = false;
function _pushPN(){
  try { return (window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.PushNotifications) || null; }
  catch(e){ return null; }
}
function _pushKaydet(){
  if (!_pushToken || !window.sb) return;
  const ay = _bldAyar();
  const dil = (typeof i18nLang === 'function') ? i18nLang() : 'tr';
  window.sb.rpc('push_token_kaydet', { p_token: _pushToken, p_platform: window.Capacitor.getPlatform(), p_dil: dil, p_aktif: !!(ay.acik && ay.anlik) })
    .then(({ error }) => { if (error) console.warn('[push] jeton kaydedilemedi:', error.message); else { _pushKayitli = true; _pushTercihKaydet(); } });
}
// 🔔 642 — sistem bildirimleri sunucudan gider: ayarlar ve cihazın saat dilimi sunucuya yazılır
function _pushTercihKaydet(){
  const ay = _bldAyar();
  const tercih = { acik: !!ay.acik };
  for (const t of BLD_TIPLER) tercih[t] = !!ay[t];
  window.sb.rpc('push_tercih_kaydet', { p_token: _pushToken, p_tercih: tercih, p_tz: Intl.DateTimeFormat().resolvedOptions().timeZone || null })
    .then(({ data, error }) => {
      if (error) { console.warn('[push] tercih kaydedilemedi:', error.message); return; }
      const once = _pushSunucuda;
      _pushSunucuda = (data === true);
      if (once !== _pushSunucuda) _bldMacTara(true);
    });
}
// 937 — bildirime dokunma: dinleyici hemen, iş oyun hazır olunca (ana sayfa çizildiği an)
let _bldHazir = false, _bldBekleyen = null;
function _bldDokunma(fn) { if (_bldHazir) { try { fn(); } catch (e) {} } else _bldBekleyen = fn; }
function _bldHazirOldu() { if (_bldHazir) return; _bldHazir = true; const f = _bldBekleyen; _bldBekleyen = null; if (f) { try { f(); } catch (e) {} } }
(function _bldDokunmaKur() {
  try {
    const P = window.Capacitor && window.Capacitor.Plugins; if (!P) return;
    const LN = P.LocalNotifications, PN = P.PushNotifications;
    if (LN && LN.addListener) LN.addListener('localNotificationActionPerformed', function (a) {
      const ex = (a && a.notification && a.notification.extra) || {};
      _bldDokunma(() => { if (ex.tip === 'antrenman') showPage('training', findNavBtn('training')); else showPage('home', null); });
    });
    if (PN && PN.addListener) PN.addListener('pushNotificationActionPerformed', function (a) {
      const v = (a && a.notification && a.notification.data) || {};
      _bldDokunma(() => {
        if (v.tip && v.tip !== 'inbox') { _pushAc(v.tip, v.tip === 'duello' ? v.mesajTipi : v.alt); return; }
        if (v.mesajTipi === 'chat') { _pushSohbetAc(v.conv); return; }
        inboxOpen();
      });
    });
  } catch (e) {}
})();
// Sistem bildirimine dokununca ilgili ekran
function _pushAc(tip, alt){
  const git = (sayfa) => showPage(sayfa, (typeof findNavBtn === 'function') ? findNavBtn(sayfa) : null);
  if (tip === 'gunluk') { git('events'); setTimeout(() => evShowTab('quests'), 200); }
  else if (tip === 'yaris') goToRaceTab(alt === 'rating' || alt === 'penalti' ? alt : 'train');
  else if (tip === 'duello') { _dlSekmeAyarla(/^fiske/.test(alt || '') ? 'fiske' : 'penalti'); git('entertainment'); }
  else if (tip === 'maas') inboxOpen();
  else if (tip === 'takim') {   // 961
    inboxOpen();
    if (alt) setTimeout(() => { try { if (getInboxMsgs().some(m => m && m.id === alt)) inboxOpenMsg(alt); } catch (e) {} }, 900);
  }
  else if (tip === 'yonetim') { Promise.resolve(typeof duyuruTara === 'function' ? duyuruTara() : null).catch(() => {}).then(() => inboxOpen()); }
  else if (tip === 'takipci') {
    git('cfc-media');
    setTimeout(() => { cfcMdTab('profile', document.querySelector('.cfcmd-tab[data-cfcmd-tab="profile"]')); cfcMdOpenFollows('followers'); }, 200);
  }
  else if (tip === 'satildi') git('team');
  else git('home');
}
// 737 — mesaj bildirimi: gelen kutusu sunucudan tazelenir, o kişinin sohbeti açılır
async function _pushSohbetAc(conv){
  // 937 — sohbet elde varsa beklemeden açılır (kutu açılınca zaten tazelenir); yoksa önce sunucudan
  const bul = () => getInboxMsgs().filter(m => m && m.type === 'chat');
  let s = bul();
  if (!(conv && s.some(x => x.id === conv))) { try { await _inboxLoadFromServer(); } catch(e){} s = bul(); }
  const yeni = (a, b) => (b.ts || 0) - (a.ts || 0);
  const m = (conv && s.find(x => x.id === conv)) || s.filter(x => !x.read).sort(yeni)[0] || s.sort(yeni)[0];
  inboxOpen();
  if (m) inboxOpenMsg(m.id);
}
async function _pushBaslat(){
  const PN = _pushPN();
  if (!PN || _pushKuruldu) return;
  _pushKuruldu = true;
  try {
    if (PN.createChannel) {
      try { await PN.createChannel({ id: 'csc-mesaj', name: _bldT('Mesajlar ve teklifler'),
        description: _bldT('Yeni mesaj, transfer teklifi ve katılma isteği'), importance: 5, visibility: 1, vibration: true }); } catch(e){}
    }
    PN.addListener('registration', function(t){ _pushToken = t && t.value; _pushKaydet(); });
    PN.addListener('registrationError', function(e){ console.warn('[push] kayıt hatası:', e && e.error); });
    // 937 — dokunma dinleyicisi açılışta kuruluyor (_bldDokunmaKur)
    // Uygulama açıkken Android bildirimi göstermez: sistem bildirimi üstte şerit olarak çıkar
    PN.addListener('pushNotificationReceived', function(n){
      const v = (n && n.data) || {};
      if (v.tip === 'duello') { if (/^fiske/.test(v.mesajTipi || '')) fkDurumTazele(true); else pdDurumTazele(true); return; }
      if (v.tip === 'takipci') _bnTazele(true);   // 728 — CSC Media çanı
      if (!v.tip || v.tip === 'inbox' || window.Capacitor.getPlatform() !== 'android') return;
      _bldIcSerit(n.title || '', n.body || '', () => _pushAc(v.tip, v.alt));
    });
    // İzni yerel bildirimler zaten istedi (Android'de aynı izin) — burada yeniden sorulmaz
    const iz = await PN.checkPermissions();
    if (iz && iz.receive === 'granted') await PN.register();
  } catch(e){ console.warn('[push] başlatılamadı:', e && e.message); }
}

// Açılış
async function _bldBaslat(){
  if (_bldBasladi) return; _bldBasladi = true;
  try {
    if (_bldOrtam() === 'yok') return;
    const LN = _bldLN();
    if (LN) {
      if (LN.createChannel) {
        const _Tk = (typeof T === 'function') ? T : (x => x);
        try { await LN.createChannel({ id: BLD_KANAL, name: _Tk('Maç hatırlatmaları'),
          description: _Tk('Maç başlamadan önce hatırlatma'), importance: 5, visibility: 1, vibration: true }); } catch(e){}
      }
      // 937 — dokunma dinleyicisi açılışta kuruluyor (_bldDokunmaKur)
    }
    const ay = _bldAyar();
    if (!ay.acik) return;
    let izin = await _bldIzinDurum();
    // 🆕 543 — "bir kez sor" işareti ortama göre tutulur (native / web). Eski APK'da
    //   konmuş bir işaret, güncellemeden sonra telefonun izin sorusunu engellemesin.
    const _sk = 'soruldu_' + _bldOrtam();
    if (izin !== 'granted' && !ay[_sk]) {
      ay[_sk] = true; _bldAyarYaz(ay);             // bir kez sor, bir daha rahatsız etme
      izin = await _bldIzinIste();
    }
    if (izin === 'granted') { await _bldMacTara(true); await _pushBaslat(); }
    try { bldAyarlariYansit(); } catch(e){}
  } catch(e){ console.warn('[bld] başlatma:', e && e.message); }
}

// ── Ayarlar ekranı ──
function bldAyarlariYansit(){
  try {
    const ay = _bldAyar();
    const a = document.getElementById('set-toggle-bildirim');
    if (a) a.classList.toggle('on', !!ay.acik);
    const oz = document.getElementById('set-bld-ozet');
    if (oz) oz.innerHTML = '<span>' + (ay.acik ? 'Açık' : 'Kapalı') + '</span> ›';
    for (const t of BLD_TIPLER) {
      const el = document.getElementById('set-toggle-bld-' + t);
      if (el) el.classList.toggle('on', !!(ay.acik && ay[t]));
      const sat = document.getElementById('set-row-bld-' + t);
      if (sat) sat.style.opacity = ay.acik ? '1' : '.45';
    }
  } catch(e){}
}
async function bldToggleAna(el){
  const ay = _bldAyar();
  ay.acik = !ay.acik;
  if (ay.acik) {
    let izin = await _bldIzinDurum();
    if (izin !== 'granted') { ay['soruldu_' + _bldOrtam()] = true; izin = await _bldIzinIste(); }
    if (izin !== 'granted') {
      ay.acik = false; _bldAyarYaz(ay); bldAyarlariYansit();
      _bldIcSerit(T('Bildirim izni kapalı'), T('Bildirimleri açmak için telefon ayarlarından izin vermelisin.'));
      return;
    }
  }
  _bldAyarYaz(ay); bldAyarlariYansit();
  await _bldMacTara(true);
  if (ay.acik) await _pushBaslat();
  _pushKaydet();
}
async function bldToggleTip(tip){
  const ay = _bldAyar();
  if (!ay.acik) { bldAyarlariYansit(); return; }
  if (BLD_TIPLER.indexOf(tip) < 0) return;
  ay[tip] = !ay[tip]; _bldAyarYaz(ay); bldAyarlariYansit();
  await _bldMacTara(true);
  _pushKaydet();
}
// 🔔 541 — TEST BİLDİRİMİ: zincirin tamamını 10 saniyede doğrular
//   (eklenti var mı → izin var mı → planlama çalışıyor mu → telefona düşüyor mu)
async function bldTestGonder(){
  const S = (b, g) => _bldIcSerit(_bldT(b), _bldT(g));
  try {
    const ortam = _bldOrtam();
    if (ortam === 'yok') {
      S('Bildirim eklentisi yüklü değil', 'APK bildirim eklentisi olmadan derlenmiş. Uygulamayı güncellemelisin.');
      return;
    }
    let izin = await _bldIzinDurum();
    if (izin !== 'granted') izin = await _bldIzinIste();
    if (izin !== 'granted') {
      S('Bildirim izni kapalı', 'Bildirimleri açmak için telefon ayarlarından izin vermelisin.');
      return;
    }
    const baslik = _bldT('Test bildirimi'), govde = _bldT('Bildirimler çalışıyor! Maç hatırlatmaları telefonuna gelecek.');
    const LN = _bldLN();
    if (LN) {
      await LN.schedule({ notifications: [{
        id: 1999999999, title: baslik, body: govde, channelId: BLD_KANAL,
        schedule: { at: new Date(Date.now() + 10000), allowWhileIdle: true },
        isExactNotification: false, extra: { tip: 'test' }
      }] });
      let bekleyen = 0;
      try { const p = await LN.getPending(); bekleyen = ((p && p.notifications) || []).length; } catch(e){}
      _bldIcSerit(_bldT('10 saniye içinde bildirim gelecek'),
        _bldT('Uygulamayı arka plana alıp bekle.') + ' ' + _bldT('Planlı bildirim:') + ' ' + bekleyen);
      return;
    }
    // Tarayıcı
    setTimeout(() => _bldGoster(baslik, govde), 10000);
    _bldIcSerit(_bldT('10 saniye içinde bildirim gelecek'), _bldT('Tarayıcı modunda sayfa açık kalmalı.'));
  } catch(e) {
    S('Test bildirimi gönderilemedi', String((e && e.message) || e).slice(0, 80));
  }
}
window.bldTestGonder = bldTestGonder;
// 🔔 548 — Ayarlar > Bildirim Ayarları modalı
function bldAyarAc(){
  bldAyarlariYansit();
  const ov = document.getElementById('bldOverlay');
  if (ov) ov.classList.add('open');
}
function bldAyarKapat(){
  const ov = document.getElementById('bldOverlay');
  if (ov) ov.classList.remove('open');
}
window.bldAyarAc = bldAyarAc;
window.bldAyarKapat = bldAyarKapat;
window.bldToggleAna = bldToggleAna;
window.bldToggleTip = bldToggleTip;
window.bldAyarlariYansit = bldAyarlariYansit;
window._bldMacTara = _bldMacTara;
window._bldBaslat = _bldBaslat;

// Uygulama öne geldiğinde + periyodik tazeleme
try {
  document.addEventListener('visibilitychange', function(){
    if (!document.hidden) { try { _bldMacTara(true); } catch(e){} }
  });
  // 956 — uygulamada (yerel bildirim eklentisi) arka planda tarama yok: planlar 72 saatlik sistem kuyruğunda, öne gelince zorunlu tarama var.
  //   Tarayıcıda sürer: oradaki hatırlatmalar sayfa içi zamanlayıcı (6 saat ufuk), arka plandaki sekmeye de yenileri eklenmeli.
  setInterval(function(){ try { if (document.hidden && _bldLN()) return; _bldMacTara(false); } catch(e){} }, 10 * 60 * 1000);
} catch(e){}

// ═══════════════════════════════════════════════════════════════════
//  GOOGLE PLAY BILLING
//  Tarayicida hicbir sey degismez: Xsolla akisi aynen calisir.
//  APK icinde ise Play Billing devreye girer — Play politikasi
//  uygulama icinde harici odeme sayfasi acilmasini yasakliyor.
//
//  Native taraf: PlayBilling.java (Android), AppleOdeme.swift (iOS, StoreKit 2).
//  iOS'ta Xsolla hic acilmaz; Apple de yalnizca kendi odemesine izin veriyor.
//  Cordova tabanli eklentiler burada CALISMIYOR: oyun sunucudan
//  yuklendigi icin Capacitor kendi koprusunu enjekte ediyor ama
//  Cordova uyumluluk katmani gelmiyor.
// ═══════════════════════════════════════════════════════════════════

// ═══ 730 — BAŞLANGIÇ PAKETİ (150 elmas + Hafif Krampon) ═══
//   Mağaza ürünü 'baslangic_paketi'. Mağaza ürünü vermiyorsa (ör. App Store onayı yok) hiç görünmez.
//   Pencere günde bir kez; ilk gösterimden 5 gün sonra biter; alınınca bir daha yok. Durum sunucuda (baslangic_durum).
const BP_URUN = 'baslangic_paketi';
const BP = { durum: null, basladi: false, gun: null, bekleyen: false, sirada: false };   // 731 — gun: son sorulan gün, bekleyen: bugünün penceresi henüz açılmadı
const _BP_TAS = '<svg class="bp-tas" viewBox="0 0 100 72"><ellipse cx="50" cy="40" rx="30" ry="18" fill="url(#dp-hale)"/><use href="#ic-elmas-tas" x="27" y="14.9" width="46" height="40.3"/></svg>';
const _BP_MTAS = '<svg class="bp-mtas" viewBox="0 0 64 56"><use href="#ic-elmas-tas" width="64" height="56"/></svg>';
const _BP_SAAT = '<svg class="bp-saat" viewBox="0 0 24 24"><circle cx="12" cy="13" r="8"/><path d="M12 9v4l2.5 2M9.5 2.5h5"/></svg>';
const _BP_YZ = '<svg viewBox="0 0 24 24"><path d="M12 0l2.6 9.4L24 12l-9.4 2.6L12 24l-2.6-9.4L0 12l9.4-2.6z"/></svg>';
function _bpVar() { return !!(window._playFiyat && window._playFiyat[BP_URUN]); }
function _bpAktif() { const d = BP.durum; return !!(d && !d.alindi && !d.bitti && d.bitis && Date.parse(d.bitis) > Date.now() && _bpVar()); }
function _bpKalan() {
  const ms = Math.max(0, Date.parse(BP.durum.bitis) - Date.now());
  const g = Math.floor(ms / 86400000), sa = Math.floor(ms % 86400000 / 3600000), dk = Math.max(1, Math.floor(ms % 3600000 / 60000));
  return g > 0 ? `<span>${g}g</span> <span>${sa}sa</span>` : sa > 0 ? `<span>${sa}sa</span> <span>${dk}dk</span>` : `<span>${dk}dk</span>`;
}
function _bpYildiz(poz) { return poz.map(([x, y, d]) => `<i class="bp-pz" style="left:${x}%;top:${y}%;animation-delay:-${d}s">${_BP_YZ}</i>`).join(''); }
function _bpKrampon() { return `<img src="${itemGorselUrl('pm8')}" alt="" draggable="false">`; }
function _bpIndirim() { return (typeof i18nAktif === 'function' && i18nAktif()) ? '−80%' : '−%80'; }
// Kart başlığı uzun dillerde (ör. Rusça) sığmazsa yazı küçülür
function _bpSigdir() {
  document.querySelectorAll('#bpKart .bp-k-orta b').forEach(el => {
    el.style.fontSize = '';
    let b = parseFloat(getComputedStyle(el).fontSize);
    while (el.scrollWidth > el.clientWidth + 1 && b > 11) { b -= 0.5; el.style.fontSize = b + 'px'; }
  });
}
function _bpFiyat() { return (window._playFiyat && window._playFiyat[BP_URUN]) || '€1'; }
function _bpKartCiz() {
  const el = document.getElementById('bpKart');
  if (!el) return;
  el.innerHTML = !_bpAktif() ? '' : `<div class="bp-kart" onclick="_bpAl()">${_bpYildiz([[8,18,0],[88,12,.6],[50,4,.9],[70,30,2.3]])}
    <div class="bp-k-sol"><div class="bp-kg">${_BP_TAS}</div><div class="bp-kg bp-krampon">${_bpKrampon()}</div></div>
    <div class="bp-k-orta"><b>BAŞLANGIÇ PAKETİ</b><span>150 Elmas + Hafif Krampon</span><small class="bp-kalan">${_BP_SAAT}${_bpKalan()}</small></div>
    <div class="bp-k-sag"><em data-noi18n>${_bpIndirim()}</em><button type="button" class="bp-al"><b data-noi18n>${_bpFiyat()}</b></button></div></div>`;
  if (el.innerHTML) { requestAnimationFrame(_bpSigdir); setTimeout(_bpSigdir, 400); }
}
function _bpModalAc() {
  if (document.getElementById('bpOv') || !_bpAktif()) return;
  if (BP.bekleyen) {   // 731 — gün, pencere ekrana gelince işaretlenir
    BP.bekleyen = false;
    try { Promise.resolve(window.sb.rpc('baslangic_durum', { p_gun: new Date().toLocaleDateString('sv'), p_goster: true })).catch(() => {}); } catch (e) {}
  }
  const ov = document.createElement('div');
  ov.id = 'bpOv'; ov.className = 'bp-ov';
  ov.onclick = (e) => { if (e.target === ov) ov.remove(); };
  ov.innerHTML = `<div class="bp-mod"><div class="bp-isik"></div>${_bpYildiz([[8,18,0],[88,12,.6],[14,62,1.2],[92,54,1.8],[50,4,.9],[70,30,2.3],[26,36,1.5]])}
    <button type="button" class="bp-x" aria-label="Kapat" onclick="document.getElementById('bpOv').remove()"><svg viewBox="0 0 24 24"><path d="M6 6l12 12M18 6L6 18"/></svg></button>
    <div class="bp-serit"><span>BAŞLANGIÇ PAKETİ</span></div>
    <div class="bp-sure bp-kalan">${_BP_SAAT}<span>Sınırlı süre</span> · ${_bpKalan()}</div>
    <div class="bp-ic">
      <div class="bp-kalem"><div class="bp-kg">${_BP_TAS}</div><b data-noi18n>150</b><span>ELMAS</span></div>
      <div class="bp-arti">+</div>
      <div class="bp-kalem"><div class="bp-kg bp-krampon">${_bpKrampon()}</div><b class="bp-ad">Hafif Krampon</b><span>Ekipman</span></div>
    </div>
    <div class="bp-deger"><s data-noi18n>260 ${_BP_MTAS}</s><em data-noi18n>${_bpIndirim()}</em></div>
    <button type="button" class="bp-al" onclick="_bpAl()"><span>Satın Al</span><b data-noi18n>${_bpFiyat()}</b></button></div>`;
  document.body.appendChild(ov);
}
// Ana sayfa açıkken ve önünde başka pencere yokken gösterilir (en çok 2 dk bekler)
//   731 — açılamazsa gün yanmaz; oyuncu ana sayfaya dönünce yeniden denenir
function _bpModalSira(n) {
  if (!BP.bekleyen) return;
  const ust = document.elementFromPoint(window.innerWidth / 2, window.innerHeight / 2);
  if (ust && ust.closest && ust.closest('#page-home')) { BP.sirada = false; _bpModalAc(); return; }
  if (BP.sirada && !n) return;   // bekleyen deneme zaten var
  BP.sirada = true;
  n = n || 0;
  if (n < 24) setTimeout(() => _bpModalSira(n + 1), 5000); else BP.sirada = false;
}
// 731 — günde bir kez sorulur (giriş, mağaza hazır, ana sayfa, uygulamaya dönüş — hangisi önce gelirse)
async function _bpBaslat() {
  const gun = new Date().toLocaleDateString('sv');
  if (BP.basladi || BP.gun === gun || (BP.durum && (BP.durum.alindi || BP.durum.bitti))) return;
  if (!_bpVar() || !window.sb || typeof authUser === 'undefined' || !authUser || !authUser.id) return;
  BP.basladi = true;
  let r = null;
  try { r = await window.sb.rpc('baslangic_durum', { p_gun: gun, p_goster: false }); } catch (e) {}
  BP.basladi = false;
  if (!r || r.error || !r.data) return;
  BP.gun = gun; BP.durum = r.data; BP.bekleyen = !!r.data.modal;
  _bpKartCiz();
  if (BP.bekleyen) setTimeout(_bpModalSira, 2500);
}
document.addEventListener('visibilitychange', () => { if (document.hidden) return; _bpBaslat(); if (BP.bekleyen) setTimeout(_bpModalSira, 1500); });
function _bpAl() { _playSatinAl(-1, { id: BP_URUN, dia: 150 }); }
function _bpAlindi() {
  BP.durum = { alindi: true }; BP.bekleyen = false;
  const ov = document.getElementById('bpOv'); if (ov) ov.remove();
  _bpKartCiz();
  try { _eqDataLoadFromServer(); } catch (e) {}
}
function _bpTeslimBildir(d) {
  if (!d || typeof d.esya !== 'boolean') return;
  showShopToast(d.esya ? '✅ Hafif Krampon dolabına eklendi!' : '✅ Hafif Krampon yerine 110 elmas eklendi.', '#00e676');
}
setInterval(() => {
  if (!BP.durum || BP.durum.alindi) return;
  if (!_bpAktif()) { _bpKartCiz(); const ov = document.getElementById('bpOv'); if (ov) ov.remove(); return; }
  document.querySelectorAll('.bp-kalan').forEach(el => {
    el.innerHTML = el.classList.contains('bp-sure') ? `${_BP_SAAT}<span>Sınırlı süre</span> · ${_bpKalan()}` : `${_BP_SAAT}${_bpKalan()}`;
  });
}, 60000);

const PLAY_FN = SUPABASE_URL + '/functions/v1/' + ((window.Capacitor && window.Capacitor.getPlatform && window.Capacitor.getPlatform() === 'ios') ? 'apple-verify' : 'play-verify');

// Play'den gelen yerel fiyatlar: { dia_3: '₺129,99', ... }
window._playFiyat = {};
let _playHazir = false;
let _playKuruluyor = false;

// Native eklentiye kisayol
function _pb() {
  try { return window.Capacitor && window.Capacitor.Plugins && (window.Capacitor.Plugins.PlayBilling || window.Capacitor.Plugins.AppleOdeme); }
  catch (e) { return null; }
}

// Magaza odemesi mi? iOS'ta eklenti olmasa bile Xsolla'ya dusulmez
function _playAktifMi() {
  try {
    const plat = window.Capacitor && typeof window.Capacitor.getPlatform === 'function' && window.Capacitor.getPlatform();
    return plat === 'ios' || (plat === 'android' && !!_pb());
  } catch (e) { return false; }
}

async function _playKur() {
  if (_playHazir || _playKuruluyor || !_playAktifMi()) return _playHazir;
  _playKuruluyor = true;
  try {
    const PB = _pb();

    await PB.baslat();

    const idler = (DIAMOND_PACKS || []).map(function (p) { return 'dia_' + p.priceEur; }).concat([BP_URUN]);
    const sonuc = await PB.urunleriGetir({ productIds: idler });

    const gelen = (sonuc && sonuc.urunler) || [];
    gelen.forEach(function (u) {
      if (u && u.productId && u.fiyat) window._playFiyat[u.productId] = u.fiyat;
    });
    window._playUrunler = gelen.length;

    _playHazir = true;
    PB.addListener('bekleyenVar', _playBekleyenleriIsle);
    _bpBaslat();   // 730 — başlangıç paketi (ürün mağazada varsa)

    // Fiyatlar geldi — magaza aciksa kartlari tazele
    try {
      if (typeof renderShop === 'function' &&
          document.getElementById('page-shop') &&
          document.getElementById('page-shop').classList.contains('active')) {
        renderShop();
      }
    } catch (e) {}

    // Yarim kalmis satin almalari tamamla
    _playBekleyenleriIsle();

    console.info('[play] hazir, urun sayisi', gelen.length);
  } catch (e) {
    console.warn('[play] kurulum hatasi', e);
    try { window._playSonHata = String((e && (e.message || e.errorMessage)) || e); } catch (x) {}
  } finally {
    _playKuruluyor = false;
  }
  return _playHazir;
}

// Jetonu sunucuya dogrulat. Basarili olursa urunu tuket.
// donus: { ok, dia, ad, tekrar } | null
async function _playDogrula(urunId, jeton) {
  try {
    let jwt = null;
    try {
      const { data } = await window.sb.auth.getSession();
      jwt = data && data.session && data.session.access_token;
    } catch (e) {}
    if (!jwt) return { ok: false, hata: 'Oturum bulunamadi' };

    const cevap = await fetch(PLAY_FN, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + jwt },
      body: JSON.stringify({ productId: urunId, purchaseToken: jeton }),
    }).then(function (r) { return r.json(); }).catch(function () { return null; });

    if (cevap && cevap.ok) {
      // Elmas yatti — urunu tuket ki tekrar satin alinabilsin.
      // Dogrulama BASARISIZ olursa TUKETMIYORUZ: jeton Play'de kalir,
      // uygulama tekrar acildiginda yeniden denenir, para bosa gitmez.
      try { await _pb().tuket({ purchaseToken: jeton }); } catch (e) {
        console.warn('[play] tuketilemedi', e);
      }
      return cevap;
    }

    console.warn('[play] dogrulama basarisiz', cevap);
    return cevap || { ok: false, hata: 'Sunucuya ulasilamadi' };
  } catch (e) {
    console.warn('[play] dogrulama hatasi', e);
    return { ok: false, hata: String(e) };
  }
}

// Odeme alinmis ama islenmemis satin almalar (ag koptu, uygulama kapandi)
async function _playBekleyenleriIsle() {
  if (!_playAktifMi()) return;
  try {
    const sonuc = await _pb().bekleyenler();
    const liste = (sonuc && sonuc.satinAlmalar) || [];
    for (const sa of liste) {
      if (!sa || !sa.productId || !sa.purchaseToken) continue;
      const r = await _playDogrula(sa.productId, sa.purchaseToken);
      if (r && r.ok && sa.productId === BP_URUN) _bpAlindi();   // 730
      if (r && r.ok && !r.tekrar) {
        try { await wlLoadFromServer(); } catch (e) {}
        try { wlSyncHeader(); } catch (e) {}
        try { showShopToast('✅ ' + r.dia + ' elmas hesabina gecti!', '#00e676'); } catch (e) {}
      }
    }
  } catch (e) {
    console.warn('[play] bekleyenler islenemedi', e);
  }
}

// Magaza kartindan cagrilir
async function _playSatinAl(idx, urun) {   // 730 — urun: { id, dia } (başlangıç paketi)
  const p = urun ? { amount: urun.dia, bonus: 0 } : DIAMOND_PACKS[idx];
  if (!p) return;
  const urunId = urun ? urun.id : 'dia_' + p.priceEur;

  try { showShopToast(window.Capacitor.getPlatform() === 'ios' ? '💳 Ödeme hazırlanıyor…' : '💳 Google Play aciliyor…', '#3b82f6'); } catch (e) {}

  if (!_playHazir) {
    const ok = await _playKur();
    if (!ok) {
      try { showShopToast('⚠️ Odeme sistemi hazir degil, tekrar dene.', '#ef4444'); } catch (e) {}
      return;
    }
  }

  // Rozeti dondur — kutlama sayana kadar baslik eski degerde kalsin
  try { window._WL_HOLD.dia = true; } catch (e) {}

  try {
    const { data: oturum } = await window.sb.auth.getSession();
    const satin = await _pb().satinAl({ productId: urunId, hesap: oturum && oturum.session && oturum.session.user.id });

    const dogrulama = await _playDogrula(urunId, satin.purchaseToken);

    if (!dogrulama || !dogrulama.ok) {
      try { window._WL_HOLD.dia = false; wlSyncHeader(); } catch (e) {}
      try {
        showShopToast('⏳ Odeme alindi, elmaslar birazdan yatacak.', '#f59e0b');
      } catch (e) {}
      return;
    }

    // Cuzdani sunucudan tazele. wlLoadFromServer _wlCache'i gunceller;
    // rozet _WL_HOLD.dia yuzunden donuk kalir, kutlama animasyonu
    // eski rakamdan sayarak yeni degere yukselir.
    try { await wlLoadFromServer(); } catch (e) {}

    const miktar = dogrulama.dia || ((p.amount || 0) + (p.bonus || 0));
    if (urun && urun.id === BP_URUN) _bpAlindi();   // 730
    const _sonra = function () { try { renderShop(); } catch (e) {} if (urun && urun.id === BP_URUN) _bpTeslimBildir(dogrulama); };
    if (typeof _xsKutlama === 'function') {
      _xsKutlama(miktar, _sonra);
    } else {
      try { window._WL_HOLD.dia = false; wlSyncHeader(); } catch (e) {}
      try { showShopToast('✅ ' + miktar + ' elmas hesabina gecti!', '#00e676'); } catch (e) {}
      _sonra();
    }

  } catch (h) {
    try { window._WL_HOLD.dia = false; wlSyncHeader(); } catch (e) {}

    const kod = (h && (h.code || h.errorCode)) || '';
    const mesaj = (h && (h.message || h.errorMessage)) || '';

    if (kod === 'IPTAL' || /iptal|cancel/i.test(mesaj)) return;   // vazgecti, sessiz

    if (kod === 'ZATEN_VAR') {
      // Onceki satin alma tuketilmemis — simdi isle
      try { showShopToast('⏳ Onceki alisverisin isleniyor…', '#f59e0b'); } catch (e) {}
      _playBekleyenleriIsle();
      return;
    }

    if (kod === 'BEKLEMEDE') {
      try { showShopToast('⏳ Odemen onay bekliyor.', '#f59e0b'); } catch (e) {}
      return;
    }

    try { showShopToast('⚠️ ' + (mesaj || 'Odeme tamamlanamadi'), '#ef4444'); } catch (e) {}
  }
}

// Uygulama acilinca Play'i hazirla (fiyatlar kartlarda gorunsun,
// yarim kalmis satin almalar tamamlansin)
(function _playOtoKur() {
  function dene() { if (_playAktifMi()) _playKur(); }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', dene);
  else dene();
  setTimeout(dene, 2500);
})();


async function buyDiamondPack(idx) {
  const p = DIAMOND_PACKS[idx];
  if (!p) return;

  // 🆕 APK icindeysek Xsolla'ya HIC gitmeden Play Billing'e gec.
  //    Play politikasi uygulama icinde harici odeme sayfasi
  //    acilmasini yasakliyor.
  if (_playAktifMi()) return _playSatinAl(idx);

  const toplam = (p.amount || 0) + (p.bonus || 0);
  const sku = 'dia_' + p.priceEur;

  try { showShopToast('💳 Ödeme hazırlanıyor…', '#3b82f6'); } catch(e) {}

  // ── 1) Oturum ──
  let jwt = null;
  try {
    const { data } = await window.sb.auth.getSession();
    jwt = data && data.session && data.session.access_token;
  } catch(e) {}
  if (!jwt) {
    try { showShopToast('⚠️ Önce giriş yapman gerekiyor.', '#ef4444'); } catch(e) {}
    return;
  }

  // Satın almadan önceki bakiye — sonradan karşılaştıracağız
  let oncekiDia = 0;
  try { const c = await wlLoadFromServer(); oncekiDia = Number(c && c.dia) || 0; } catch(e) {}

  // ── 2) Jeton ──
  let cevap = null;
  try {
    const r = await fetch(XSOLLA_FN + '?action=token', {
      method: 'POST',
      headers: {
        'Authorization': 'Bearer ' + jwt,
        'apikey': SUPABASE_KEY,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({ sku })
    });
    cevap = await r.json().catch(() => null);
  } catch(e) {
    console.warn('[xsolla] jeton isteği hatası', e);
  }

  if (!cevap || !cevap.ok || !cevap.token) {
    const kod = (cevap && cevap.error) || 'baglanti_hatasi';
    const mesajlar = {
      xsolla_ayarlari_eksik: 'Ödeme sistemi henüz yapılandırılmadı.',
      gecersiz_paket:        'Bu paket tanınmıyor.',
      oturum_yok:            'Önce giriş yapman gerekiyor.',
      yetkisiz_oturum:       'Oturumun düşmüş, tekrar giriş yap.',
      jeton_alinamadi:       'Ödeme sağlayıcısına bağlanılamadı.',
      baglanti_hatasi:       'Bağlantı kurulamadı, tekrar dene.'
    };
    try { showShopToast('⚠️ ' + (mesajlar[kod] || 'Ödeme başlatılamadı.'), '#ef4444'); } catch(e) {}
    console.warn('[xsolla] jeton alınamadı', cevap);
    return;
  }

  // ── 3) Ödeme penceresi ──
  const hazir = await _xsWidgetYukle();

  if (!hazir || !window.XPayStationWidget) {
    // Kütüphane yüklenemediyse doğrudan ödeme sayfasına yolla
    const taban = cevap.sandbox
      ? 'https://sandbox-secure.xsolla.com/paystation4/?token='
      : 'https://secure.xsolla.com/paystation4/?token=';
    window.open(taban + encodeURIComponent(cevap.token), '_blank', 'noopener');
    try { window._WL_HOLD.dia = true; } catch(e) {}
    _xsSonucBekle(oncekiDia, cevap.dia || toplam, 'done');
    return;
  }

  try {
    window.XPayStationWidget.init({
      access_token: cevap.token,
      sandbox: !!cevap.sandbox,
      lightbox: { width: '740px', height: '760px', spinner: 'round', spinnerColor: '#00e676' }
    });
    // Rozeti DONDUR: elmas sunucuda yatsa bile başlıktaki rakam
    // kutlama animasyonu sayana kadar eski değerinde kalsın.
    try { window._WL_HOLD.dia = true; } catch(e) {}

    let kapandi = false, durum = null;
    window.XPayStationWidget.on('status-done',     function(){ durum = 'done'; });
    window.XPayStationWidget.on('status-troubled', function(){ durum = 'troubled'; });
    window.XPayStationWidget.on('close', function(){
      if (kapandi) return; kapandi = true;
      _xsSonucBekle(oncekiDia, cevap.dia || toplam, durum);
    });
    window.XPayStationWidget.open();
  } catch(e) {
    console.warn('[xsolla] pencere açılamadı', e);
    try { window._WL_HOLD.dia = false; wlSyncHeader(); } catch(_) {}
    try { showShopToast('⚠️ Ödeme penceresi açılamadı.', '#ef4444'); } catch(_) {}
  }
}

// durum: 'done' (ödeme tamam) | 'troubled' (başarısız) | null (kullanıcı kapattı)
async function _xsSonucBekle(oncekiDia, beklenenDia, durum) {
  // ── Ödeme sağlayıcı "başarısız" dediyse beklemeye gerek yok ──
  if (durum === 'troubled') {
    try { window._WL_HOLD.dia = false; wlSyncHeader(); } catch(e) {}
    if (typeof showInfoModal === 'function') {
      showInfoModal({
        icon: '⚠️', iconColor: '#ef4444',
        title: 'Ödeme Tamamlanamadı',
        subtitle: 'Hesabından para çekilmedi',
        body: '<div class="info-modal-note">Ödeme sağlayıcı işlemi tamamlayamadı. '
            + 'Kartında sorun olabilir ya da banka işlemi onaylamamış olabilir. '
            + 'Farklı bir kart veya ödeme yöntemiyle tekrar deneyebilirsin.</div>'
      });
    } else {
      try { showShopToast('⚠️ Ödeme tamamlanamadı.', '#ef4444'); } catch(e) {}
    }
    return;
  }

  // ── Kullanıcı pencereyi kapattı: kısa bir yoklama yeter ──
  //    (durum bildirimi kaçmış olabilir; elmas yattıysa yine kutlarız)
  const iptalMi = (durum !== 'done');
  if (!iptalMi) { try { showShopToast('⏳ Ödemen kontrol ediliyor…', '#3b82f6'); } catch(e) {} }

  const kazanilan = await _xsElmasBekle(oncekiDia, beklenenDia, iptalMi ? 5 : 20);
  try { if (typeof renderDiamondPacks === 'function') renderDiamondPacks(); } catch(e) {}

  if (kazanilan != null) {
    _xsKutlama(kazanilan);
    return;
  }

  // Rozet dondurulmuştu — çöz
  try { window._WL_HOLD.dia = false; wlSyncHeader(); } catch(e) {}

  if (iptalMi) {
    // Ödeme yapılmadan kapatıldı; sessiz geç, kullanıcıyı korkutma
    try { showShopToast('Satın alma iptal edildi.', '#8a93a3'); } catch(e) {}
    return;
  }

  if (typeof showInfoModal === 'function') {
    showInfoModal({
      icon: '⏳', iconColor: '#f59e0b',
      title: 'Ödeme İşleniyor',
      subtitle: 'Elmaslar birkaç dakika içinde yatacak',
      body: '<div class="info-modal-note">Ödemen alındı ama elmaslar henüz görünmüyor. '
          + 'Bu genelde birkaç dakika içinde kendiliğinden düzelir — mağaza sayfasını '
          + 'yenileyip bakabilirsin. Yine olmazsa Ayarlar → Geri Bildirim üzerinden '
          + 'bize yaz, işlem kaydın bizde duruyor.</div>'
    });
  }
}

// ── Item Grid ──
function renderShopItems() {
  const filterEl = document.getElementById('itemFilterRow');
  if(filterEl && !filterEl.children.length) {
    filterEl.innerHTML = ITEM_CATS.map(c=>`
      <button class="item-filter-btn ${c.id===_shopItemFilter?'active':''}" onclick="setItemFilter('${c.id}',this)">
        ${c.icon} ${c.label}
      </button>
    `).join('');
  }

  const grid = document.getElementById('itemGrid');
  if(!grid) return;
  kmpBantKoy('shop-items', 'ekipman');
  const _katItems = _shopItemFilter==='all' ? SHOP_ITEMS : SHOP_ITEMS.filter(i=>i.cat===_shopItemFilter);
  // 🆕 555 — nadirlik filtresi (kategori ile birlikte çalışır) + her seçenekte kaç item olduğu
  const rarEl = document.getElementById('itemRarRow');
  if (rarEl) {
    const say = r => r==='all' ? _katItems.length : _katItems.filter(i=>i.rarity===r).length;
    rarEl.innerHTML = [['all','Tümü'],['elit','ELİT'],['pro','PRO'],['common','COMMON']].map(([r,lbl]) =>
      `<button class="irr-btn irr-${r}${_shopRarFilter===r?' active':''}" onclick="setItemRarFilter('${r}')">`
      + `${r==='all'?'':'<i class="irr-dot"></i>'}<span>${lbl}</span> <b data-noi18n>${say(r)}</b></button>`).join('');
  }
  const items = _shopRarFilter==='all' ? _katItems : _katItems.filter(i=>i.rarity===_shopRarFilter);
  const eq    = getEqData();
  const stocks = getShopStocks();

  // Stok limitleri
  const STOCK_LIMIT = {elit:50, pro:100, common:300};

  grid.innerHTML = items.map(item => {
    // 🆕 554 — B · oyun çerçevesi: görsel + nadirlik + kalan stok + ad, altında ana bonus ve fiyat
    const r       = RARITY_CFG[item.rarity] || RARITY_CFG.common;
    const owned   = eq.wardrobe.some(w=>w.id===item.id);
    const limit   = STOCK_LIMIT[item.rarity] || 300;
    const sold    = stocks[item.id] || 0;
    const left    = Math.max(0, limit - sold);
    const outOfStock = left <= 0;
    const az      = !outOfStock && left <= Math.round(limit*0.1);   // son %10 turuncu
    const durum   = owned ? 'owned' : outOfStock ? 'oos' : az ? 'az' : '';
    const onclickAttr = (owned || outOfStock) ? '' : `onclick="openShopBuyModal('${item.id}')"`;
    const gorsel  = itemGorselUrl(item.id) ? itemGorselHtml(item) : `<span class="shc-emo">${item.icon}</span>`;
    const ek      = (item.stats || []).length - 1;
    return `<div class="shc r-${item.rarity} ${durum}" ${onclickAttr}>
      <div class="shc-img">${gorsel}
        <span class="shc-rar">${r.label}</span>
        <span class="shc-stk">${left}/${limit}</span>
        <div class="shc-ad">${item.name}</div>
      </div>
      <div class="shc-alt">
        <div class="shc-stat"><span>${(item.stats||[''])[0]}</span>${ek>0?` <em>+${ek}</em>`:''}</div>
        <div class="shc-btn${!owned && !outOfStock && kmpYuzde('ekipman') ? ' kmp' : ''}">${owned ? '✓ Sahipsin' : outOfStock ? 'Stok Yok' : kmpEski('ekipman', item.price) + '💎 ' + kmpFiyat('ekipman', item.price)}</div>
      </div>
    </div>`;
  }).join('');
}

function setItemRarFilter(r) {   // 🆕 555
  _shopRarFilter = (r==='elit'||r==='pro'||r==='common') ? r : 'all';
  renderShopItems();
}
function setItemFilter(cat, btn) {
  _shopItemFilter = cat;
  document.querySelectorAll('.item-filter-btn').forEach(b=>b.classList.remove('active'));
  if(btn) btn.classList.add('active');
  renderShopItems();
}

// 863 — ekipman (Mağaza ve Satış Listesi) 6. seviyeden itibaren alınır; pazar ilanı en az mağazanın en ucuz eşyası kadar.
//   Kesin karar sunucuda (shop_buy / market_buy → seviye_yetersiz, item_listings → ilan_min_fiyat); bunlar ön kontrol.
const EKIPMAN_MIN_SEVIYE = 6;
function _pazarMinFiyat() {
  const L = (SHOP_ITEMS || []).map(i => Number(i && i.price) || 0).filter(x => x > 0);
  return L.length ? Math.min.apply(null, L) : 35;
}
function _ekSeviyeKilitli() {
  let sv = null;
  try {
    if (window._userProgressCache && typeof window._userProgressCache.level === 'number') sv = window._userProgressCache.level;
    else {
      const me = (typeof ROSTER_DATA !== 'undefined') ? ROSTER_DATA.find(p => p.role === 'user' && !p.isBot) : null;
      if (me && typeof me.level === 'number') sv = me.level;
    }
  } catch (e) {}
  if (sv === null || sv >= EKIPMAN_MIN_SEVIYE) return false;   // seviye bilinmiyorsa karar sunucuda
  if (typeof cftConfirm === 'function') {
    cftConfirm({
      title: `Seviye ${EKIPMAN_MIN_SEVIYE} Gerekli`,
      message: `Ekipman satın almak için ${EKIPMAN_MIN_SEVIYE}. seviyeye ulaşmalısın. Şu anki seviyen: ${sv}.`,
      confirmText: 'Tamam',
      cancelText: '',
      onConfirm: () => {}
    });
  } else {
    showShopToast(`❌ Ekipman satın almak için ${EKIPMAN_MIN_SEVIYE}. seviyeye ulaşmalısın.`, '#ef5350');
  }
  return true;
}

function openShopBuyModal(itemId) {
  const item = SHOP_ITEMS.find(i=>i.id===itemId);
  if(!item) {
    console.warn('openShopBuyModal: item bulunamadı', itemId);
    return;
  }
  if (_ekSeviyeKilitli()) return;   // 863

  const eq = getEqData();

  // 🆕 ÖN KONTROL 1: Bu item zaten sende mi?
  if(eq.wardrobe.some(w => w.id === item.id)) {
    if(typeof cftConfirm === 'function') {
      cftConfirm({
        title: 'Zaten Sahipsin',
        message: `${item.name} zaten dolabında. Aynı itemden ikinci kez satın alamazsın.`,
        confirmText: 'Tamam',
        cancelText: '',
        onConfirm: () => {}
      });
    } else {
      showShopToast('Zaten sahipsin.', '#ff9800');
    }
    return;
  }

  // 🆕 ÖN KONTROL 2: Dolap dolu mu? (10 slot limit) — UYARI VER
  if(_ekDolapSayi(eq) >= EK_DOLAP_MAX) {
    if(typeof cftConfirm === 'function') {
      cftConfirm({
        title: 'Dolap Dolu!',
        message: 'Dolabında 10 item var (max kapasite). Yeni item satın almadan önce dolaptan bir item satışa çıkar veya pazarda sat.',
        confirmText: 'Tamam',
        cancelText: '',
        danger: true,
        onConfirm: () => {}
      });
    } else {
      showShopToast('❌ Dolap dolu! Önce bir item çıkar.', '#ef5350');
    }
    return;
  }

  // Modal aç
  _buyTarget = {itemId, fromShop:true, price:kmpFiyat('ekipman', item.price), seller:'Mağaza', itemName:item.name};
  const r = (typeof RARITY_CFG !== 'undefined' ? RARITY_CFG[item.rarity] : null) || {color:'#5fb8ff', label:item.rarity};
  const iconEl = document.getElementById('buyModalIcon');
  const nameEl = document.getElementById('buyModalName');
  const sellerEl = document.getElementById('buyModalSeller');
  const statsEl = document.getElementById('buyModalStats');
  const priceEl = document.getElementById('buyModalPrice');
  const balEl = document.getElementById('buyModalBalance');
  const confBtn = document.getElementById('buyModalConfirmBtn');
  const rarityBar = document.getElementById('buyModalRarityBar');
  const overlayEl = document.getElementById('buyModal');

  if(!overlayEl) {
    console.error('openShopBuyModal: #buyModal HTML eksik');
    return;
  }

  if(iconEl) { itemGorselYaz(iconEl, item); iconEl.style.borderColor = r.color; } // 🆕 554
  if(nameEl) {
    nameEl.textContent = item.name;
    nameEl.style.color = r.color;
    nameEl.style.textShadow = `0 0 12px ${r.color}66, 0 1px 3px rgba(0,0,0,.5)`;
  }
  if(sellerEl) sellerEl.textContent = `Mağaza · ${r.label}`;
  // 🆕 554: ⚡ ayrı düğümde → "Karar Verme +6%" deseni çeviride tutar
  if(statsEl) statsEl.innerHTML = item.stats.map(s=>`<div class="buy-stat">⚡ <span>${s}</span></div>`).join('');
  if(priceEl) priceEl.innerHTML = kmpEski('ekipman', item.price) + _buyTarget.price.toLocaleString('tr');
  if(rarityBar) rarityBar.style.setProperty('--rarity-color', r.color);

  // 🆕 Bakiye göster — CÜZDANDAN (user_wallet)
  const bal = (typeof wlGetData === 'function') ? (wlGetData().dia || 0) : 0;
  const after = bal - _buyTarget.price;
  if(balEl) {
    if(after < 0) {
      balEl.classList.add('insufficient');
      balEl.innerHTML = `Bakiyen: <b>${bal.toLocaleString('tr')} 💎</b> · <span style="color:#ef5350">⚠️ ${Math.abs(after).toLocaleString('tr')} 💎 eksik</span>`;
    } else {
      balEl.classList.remove('insufficient');
      balEl.innerHTML = `Bakiyen: <b>${bal.toLocaleString('tr')} 💎</b> · Sonra: <b>${after.toLocaleString('tr')} 💎</b>`;
    }
  }
  if(confBtn) {
    confBtn.disabled = (after < 0);
    confBtn.textContent = (after < 0) ? 'Yetersiz Diamond' : 'Satın Al ✓';
  }

  overlayEl.classList.add('open');
}

async function confirmBuy() {
  try {
    if(!_buyTarget) {
      console.warn('confirmBuy: _buyTarget null');
      closeBuyModal();
      return;
    }

    // Para kontrolü — CÜZDANDAN (Supabase user_wallet)
    const wlBal = (typeof wlGetData === 'function') ? (wlGetData().dia || 0) : 0;
    if (wlBal < _buyTarget.price) {
      closeBuyModal();
      const bal = wlBal.toLocaleString('tr');
      if(typeof cftConfirm === 'function') {
        cftConfirm({
          title: 'Yetersiz Diamond',
          message: `Bu item için ${_buyTarget.price} 💎 gerekli ama sende sadece ${bal} 💎 var. Diamond paketi satın alabilirsin.`,
          confirmText: 'Tamam',
          cancelText: '',
          danger: true,
          onConfirm: () => {}
        });
      } else {
        showShopToast(`❌ Yetersiz Diamond! Gerekli: ${_buyTarget.price} 💎 · Mevcut: ${bal} 💎`, '#ef5350');
      }
      return;
    }

    // Dolap kontrolü (modal açılırken kontrol edilse de double-check)
    const eq = getEqData();
    if(_ekDolapSayi(eq) >= EK_DOLAP_MAX) {
      closeBuyModal();
      if(typeof cftConfirm === 'function') {
        cftConfirm({
          title: 'Dolap Dolu!',
          message: 'Dolabında 10 item var. Önce bir item satışa çıkar.',
          confirmText: 'Tamam',
          cancelText: '',
          danger: true,
          onConfirm: () => {}
        });
      } else {
        showShopToast('❌ Dolap dolu! Önce bir item çıkar.', '#ef5350');
      }
      return;
    }

    // Item zaten dolapta mı? (race condition koruma)
    const item = SHOP_ITEMS.find(i=>i.id===_buyTarget.itemId);
    if(!item) {
      closeBuyModal();
      console.error('confirmBuy: item SHOP_ITEMS\'te yok', _buyTarget.itemId);
      return;
    }
    if(eq.wardrobe.some(w=>w.id===item.id)) {
      closeBuyModal();
      showShopToast('Bu item zaten sende.', 'var(--text2)');
      return;
    }

    // 🆕 PAZAR YERİ ALIMI SUNUCUDA — ilan atomik olarak kapanır, satıcıya ödeme
    //   yapılır, aynı item ikinci kez satılamaz. (Eskiden ilana hiç dokunulmuyordu.)
    if (!_buyTarget.fromShop && _buyTarget.listingId) {
      const _lid = _buyTarget.listingId;
      const _price = _buyTarget.price;
      closeBuyModal();
      showShopToast('⏳ Satın alınıyor…', 'var(--text2)');
      try {
        const _res = await edgeCall('market_buy', { listing: _lid });
        const r = { ok: _res.ok }; const d = _res.data;
        if (!r.ok || !d || d.error) {
          const msg = {
            ilan_satildi: 'Bu item az önce başkası tarafından alındı.',
            seviye_yetersiz: `Ekipman satın almak için ${EKIPMAN_MIN_SEVIYE}. seviyeye ulaşmalısın.`,   // 863
            yetersiz_elmas: 'Yetersiz elmas.',
            kendi_ilanin: 'Kendi ilanını satın alamazsın.',
            ilan_bulunamadi: 'İlan bulunamadı.',
            zaten_sende: 'Bu item zaten sende.',
            dolap_dolu: 'Dolabın dolu. Önce bir item çıkar.',
            item_bulunamadi: 'Ürün tanınmıyor.',
            teslimat_basarisiz_para_iade: 'Teslim edilemedi, elmasların iade edildi.'
          }[d && d.error] || 'Satın alınamadı.';
          showShopToast('❌ ' + msg, '#ef5350');
          // listeyi tazele — satılmış ilan ekrandan kalksın
          try {
            _marketListings = await _marketListingsLoadFromServer();
            if (typeof renderMarket === 'function') renderMarket(_marketSearchQ || '');
          } catch(e) {}
          _buyTarget = null;
          return;
        }
        // 🆕 TESLİMAT ARTIK SUNUCUDA. Eskiden burada return YOKTU: kod
        //    aşağıdaki yerel yazma yoluna düşüyor, orada closeBuyModal()
        //    tarafından null yapılmış _buyTarget okunmaya çalışılıyor ve
        //    hata catch'e düşüyordu. Para gidiyor, ürün gelmiyordu.
        try { if (typeof wlLoadFromServer === 'function') await wlLoadFromServer(); } catch(e) {}
        try { if (typeof _eqDataLoadFromServer === 'function') await _eqDataLoadFromServer(); } catch(e) {}

        // İlanı listeden düşür
        try {
          const _i = _marketListings.findIndex(x => x && x.id === _lid);
          if (_i >= 0) _marketListings.splice(_i, 1);
        } catch(e) {}

        showShopToast('✅ ' + item.name + ' dolabına eklendi!', 'var(--accent)');

        try { if (typeof renderMarket === 'function') renderMarket(_marketSearchQ || ''); } catch(e) {}
        if (document.getElementById('eqWardrobe')) {
          try { if (typeof renderSlots === 'function') renderSlots(); } catch(_) {}
          try { if (typeof renderWardrobe === 'function') renderWardrobe(); } catch(_) {}
          try { if (typeof _refreshSkillsAfterEquipChange === 'function') _refreshSkillsAfterEquipChange(); } catch(_) {}
        }
        if (typeof achBump === 'function') achBump('item');
        _buyTarget = null;
        return;                       // 🆕 yerel yazma yolu ATLANIR
      } catch(e) {
        showShopToast('❌ Sunucuya ulaşılamadı.', '#ef5350');
        _buyTarget = null;
        return;
      }
    } else {
      // 🆕 2026-08-18 · MAĞAZADAN ALIM SUNUCUDA
      //   Eskiden elmas gerçekten düşüyordu ama item `user_player.equipment`
      //   tetikleyicisi tarafından sessizce geri alınıyordu: para gitti, mal
      //   gelmedi. Artık fiyat sunucuda SHOP_ITEMS'ten doğrulanıyor, ödeme ve
      //   teslimat aynı yerde yapılıyor, teslimat başarısızsa para iade ediliyor.
      closeBuyModal();
      showShopToast('⏳ Satın alınıyor…', 'var(--text2)');
      try {
        const _res = await edgeCall('shop_buy', { item: item.id });
        const d = _res && _res.data;
        if (!_res.ok || !d || d.error) {
          const msg = {
            yetersiz_bakiye: 'Yetersiz elmas.',
            seviye_yetersiz: `Ekipman satın almak için ${EKIPMAN_MIN_SEVIYE}. seviyeye ulaşmalısın.`,   // 863
            dolap_dolu: 'Dolabın dolu. Önce bir item çıkar.',
            zaten_sende: 'Bu item zaten sende.',
            item_bulunamadi: 'Item bulunamadı.',
            teslimat_basarisiz_para_iade: 'Teslim edilemedi, elmasların iade edildi.',
            stok_yok: 'Bu eşyanın stoğu tükendi.',
            stok_okunamadi: 'Stok kontrol edilemedi, tekrar dene.'
          }[d && d.error] || 'Satın alınamadı.';
          showShopToast('❌ ' + msg, '#ef5350');
          if (d && d.error === 'stok_yok') _shopStocksLoadFromServer().then(renderShopItems);
          _buyTarget = null;
          return;
        }
        // Cüzdanı ve dolabı sunucudan tazele — yerel tahmin yok
        try { if (typeof wlLoadFromServer === 'function') await wlLoadFromServer(); } catch(e) {}
        try { if (typeof _eqDataLoadFromServer === 'function') await _eqDataLoadFromServer(); } catch(e) {}
        showShopToast('✅ ' + item.name + ' dolabına eklendi!', 'var(--accent)');
        await _shopStocksLoadFromServer();
        if (typeof renderShopItems === 'function') renderShopItems();
        if (document.getElementById('eqWardrobe')) {
          try { if (typeof renderSlots === 'function') renderSlots(); } catch(_) {}
          try { if (typeof renderWardrobe === 'function') renderWardrobe(); } catch(_) {}
          try { if (typeof _refreshSkillsAfterEquipChange === 'function') _refreshSkillsAfterEquipChange(); } catch(_) {}
        }
        if (typeof achBump === 'function') achBump('item');
        _buyTarget = null;
        return;                       // 🆕 aşağıdaki yerel yazma yolu ATLANIR
      } catch(e) {
        showShopToast('❌ Sunucuya ulaşılamadı.', '#ef5350');
        _buyTarget = null;
        return;
      }
    }

    // Stok artır (mağaza item'i)
    if(_buyTarget.fromShop && typeof incrShopStock === 'function') incrShopStock(_buyTarget.itemId);
    // 🆕 Pazar yerinden alındıysa ilanı listeden düşür
    if (!_buyTarget.fromShop && _buyTarget.listingId) {
      try {
        const _i = _marketListings.findIndex(x => x && x.id === _buyTarget.listingId);
        if (_i >= 0) _marketListings.splice(_i, 1);
      } catch(e) {}
    }

    // Dolaba ekle
    eq.wardrobe.push({
      id: item.id,
      icon: item.icon,
      name: item.name,
      bonus: item.stats[0],
      stats: (item.stats || []).slice(),  // Tüm 5 stat'ı sakla (skill bonus hesabı için)
      type: item.catLabel,
      rarity: item.rarity
    });
    saveEqData(eq, true);   // 🆕 satın alma anında yaz (debounce bekleme — çıkışta kaybolmasın)
    if (typeof _eqData !== 'undefined') _eqData = eq;
    if(typeof achBump === 'function') achBump('item');   // 🆕 başarı: mağaza item sayacı

    closeBuyModal();
    showShopToast('✅ ' + item.name + ' dolabına eklendi!', 'var(--accent)');
    renderShopItems();  // stok güncellensin

    // 🆕 Ekipman tab açıksa dolabı + slotları + yetenekleri yenile
    if(document.getElementById('eqWardrobe')) {
      try { if(typeof renderSlots === 'function') renderSlots(); } catch(_) {}
      try { if(typeof renderWardrobe === 'function') renderWardrobe(); } catch(_) {}
      try { if(typeof _refreshSkillsAfterEquipChange === 'function') _refreshSkillsAfterEquipChange(); } catch(_) {}
    }
  } catch(err) {
    console.error('confirmBuy hata:', err);
    closeBuyModal();
    showShopToast('❌ Satın alma sırasında bir hata oluştu.', '#ef5350');
  }
}

function closeBuyModal() {
  document.getElementById('buyModal').classList.remove('open');
  _buyTarget = null;
}

// ── Pazar Yeri ──
function renderMarket(q) {
  // 🆕 557 — 3'lü kart ızgarası + mevki (kategori) / nadirlik filtresi + sıralama.
  //   Karta dokununca ilan detayı açılır (tüm bonuslar, satıcı, fiyat). Satın alma ve
  //   ilanı geri alma eskisi gibi openMarketBuy / cancelListing üzerinden yürür.
  initMarketListings();
  const el = document.getElementById('marketList');
  if(!el) return;
  const query = (q || _marketSearchQ).toLowerCase();
  const itemOf = l => SHOP_ITEMS.find(i => i.id === l.itemId);
  const tum = _marketListings.filter(l => l && l.listed && itemOf(l));
  const aranan = tum.filter(l => {
    if (!query) return true;
    const it = itemOf(l);
    const tr = String(it.name || '').toLowerCase();
    const cv = (typeof T === 'function') ? String(T(it.name) || '').toLowerCase() : '';
    return tr.includes(query) || cv.includes(query);
  });
  const katli = _mkKat === 'all' ? aranan : aranan.filter(l => itemOf(l).cat === _mkKat);
  const list  = (_mkRar === 'all' ? katli : katli.filter(l => itemOf(l).rarity === _mkRar)).slice();
  if (_mkSira === 'ucuz')        list.sort((x, y) => (Number(x.price) || 0) - (Number(y.price) || 0));
  else if (_mkSira === 'pahali') list.sort((x, y) => (Number(y.price) || 0) - (Number(x.price) || 0));
  else                           list.sort((x, y) => (y.createdAt || 0) - (x.createdAt || 0));

  // Filtre satırları
  const katEl = document.getElementById('mkKatRow');
  if (katEl) katEl.innerHTML = ITEM_CATS.map(c =>
    `<button class="item-filter-btn ${c.id === _mkKat ? 'active' : ''}" onclick="mkKatSec('${c.id}')">${c.icon} ${c.label}</button>`).join('');
  const rarEl = document.getElementById('mkRarRow');
  if (rarEl) {
    const say = r => r === 'all' ? katli.length : katli.filter(l => itemOf(l).rarity === r).length;
    rarEl.innerHTML = [['all','Tümü'],['elit','ELİT'],['pro','PRO'],['common','COMMON']].map(([r, lbl]) =>
      `<button class="irr-btn irr-${r}${_mkRar === r ? ' active' : ''}" onclick="mkRarSec('${r}')">`
      + `${r === 'all' ? '' : '<i class="irr-dot"></i>'}<span>${lbl}</span> <b data-noi18n>${say(r)}</b></button>`).join('');
  }
  const barEl = document.getElementById('mkBar');
  if (barEl) barEl.innerHTML = `<div class="mk-sayi"><b data-noi18n>${list.length}</b> <span>ilan</span></div>
    <div class="mk-sira">${[['yeni','En yeni'],['ucuz','En ucuz'],['pahali','En pahalı']].map(([k, t]) =>
      `<button class="${_mkSira === k ? 'aktif' : ''}" onclick="mkSiraSec('${k}')">${t}</button>`).join('')}</div>`;

  if(!tum.length) {
    el.innerHTML = `<div class="market-empty" style="padding:32px 20px;text-align:center">
      <div style="font-size:38px;margin-bottom:10px;opacity:.5">📭</div>
      <div style="font-size:14px;font-weight:800;color:var(--text);margin-bottom:6px;font-family:Twemoji Country Flags,'Barlow Condensed',sans-serif;letter-spacing:.5px">PAZAR BOŞ</div>
      <div style="font-size:11px;color:var(--text3);line-height:1.5;max-width:240px;margin:0 auto">Henüz satışta item yok. Dolabındaki bir itemi satışa çıkarmak için aşağıdaki <b style="color:var(--gold)">Item Sat</b> butonunu kullan.</div>
    </div>`;
    return;
  }
  if(!list.length) {
    el.innerHTML = `<div class="market-empty" style="padding:28px 20px;text-align:center">
      <div style="font-size:30px;margin-bottom:8px;opacity:.5">🔍</div>
      <div style="font-size:12px;color:var(--text3)">Bu filtrede ilan yok.</div></div>`;
    return;
  }

  el.innerHTML = list.map(listing => {
    const item = itemOf(listing);
    const r = RARITY_CFG[item.rarity] || RARITY_CFG.common;
    const isMe = _mkBenimMi(listing);
    const fiyat = Number(listing.price) || 0;
    const gorsel = itemGorselUrl(item.id) ? itemGorselHtml(item) : `<span class="shc-emo">${item.icon}</span>`;
    const ek = (item.stats || []).length - 1;
    return `<div class="shc r-${item.rarity} mk-kart${isMe ? ' mk-benim' : ''}" onclick="mkDetayAc('${_mkEsc(listing.id)}')">
      <div class="shc-img">${gorsel}
        <span class="shc-rar">${r.label}</span>
        ${isMe ? '<span class="mk-senin">SENİN</span>' : ''}
        <div class="shc-ad">${item.name}</div>
      </div>
      <div class="shc-alt">
        <div class="shc-stat"><span>${(item.stats || [''])[0]}</span>${ek > 0 ? ` <em>+${ek}</em>` : ''}</div>
        <div class="mk-satici${isMe ? ' benim' : ''}">${isMe ? '<span>senin ilanın</span>' : '👤 <span data-noi18n>' + _mkEsc(listing.seller) + '</span>'}</div>
        <div class="shc-btn">💎 ${fiyat.toLocaleString('tr-TR')}</div>
      </div>
    </div>`;
  }).join('');
}

// 🆕 557 — İlan detayı: görsel, nadirlik, mevki, TÜM bonuslar, satıcı, fiyat (+ mağaza fiyatı)
function mkDetayAc(listingId) {
  const l = _marketListings.find(x => String(x.id) === String(listingId));
  if (!l) return;
  const item = SHOP_ITEMS.find(i => i.id === l.itemId);
  if (!item) return;
  const ov = document.getElementById('mkDetay'), ic = document.getElementById('mkDetayIc');
  if (!ov || !ic) { openMarketBuy(l.id); return; }
  const r = RARITY_CFG[item.rarity] || RARITY_CFG.common;
  const isMe = _mkBenimMi(l);
  const kat = (ITEM_CATS.find(c => c.id === item.cat) || {}).label || item.catLabel || '';
  const fiyat = Number(l.price) || 0;
  const bonus = (item.stats || []).map(st => {
    const m = String(st).match(/^(.+?)\s*\+(\d+)%/);
    return `<div class="item-info-stat"><span class="item-info-stat-name">${m ? m[1].trim() : st}</span><span class="item-info-stat-val">${m ? '+' + m[2] + '%' : '—'}</span></div>`;
  }).join('');
  const id = _mkEsc(l.id);
  ic.innerHTML = `<div class="mkd-cizgi" style="background:${r.color}"></div>
    <button class="mkd-x" onclick="mkDetayKapat()">✕</button>
    <div class="mkd-ust">
      <div class="mkd-gorsel" style="border-color:${r.color};box-shadow:0 0 18px ${r.color}55">${itemGorselHtml(item)}</div>
      <div class="mkd-bilgi">
        <span class="mkd-rar" style="color:${r.color};border-color:${r.color}">${r.label}</span>
        <div class="mkd-ad">${item.name}</div>
        <div class="mkd-kat">${item.icon} <span>${kat}</span></div>
        <div class="mkd-satici">${isMe ? '<b class="benim">SENİN İLANIN</b>' : '<span>Satıcı:</span> <b data-noi18n>' + _mkEsc(l.seller) + '</b>'}</div>
      </div>
    </div>
    <div class="item-info-section-title mkd-baslik">⚡ Yetenek Bonusları</div>
    <div class="item-info-stats">${bonus}</div>
    <div class="mkd-fiyat">
      <div><div class="l">Fiyat</div><div class="v">💎 ${fiyat.toLocaleString('tr-TR')}</div></div>
      <div class="mkd-magaza"><div class="l">Mağaza fiyatı</div><div class="v">💎 ${(Number(item.price) || 0).toLocaleString('tr-TR')}</div></div>
    </div>
    <div class="mkd-btns">
      <button class="mkd-kapat" onclick="mkDetayKapat()">Kapat</button>
      ${isMe
        ? `<button class="mkd-geri" onclick="mkDetayKapat();cancelListing('${id}')">İlanı Geri Al</button>`
        : `<button class="mkd-al" onclick="mkDetayKapat();openMarketBuy('${id}')">💎 Satın Al</button>`}
    </div>`;
  ov.classList.add('open');
}
function mkDetayKapat() { const ov = document.getElementById('mkDetay'); if (ov) ov.classList.remove('open'); }
window.mkDetayAc = mkDetayAc; window.mkDetayKapat = mkDetayKapat;

function marketSearch(q) {
  _marketSearchQ = q;
  renderMarket(q);
}

function openMarketBuy(listingId) {
  const l = _marketListings.find(x=>x.id===listingId);
  if(!l) return;
  const item = SHOP_ITEMS.find(i=>i.id===l.itemId);
  if(!item) return;
  if (_ekSeviyeKilitli()) return;   // 863
  _buyTarget = {itemId:item.id, fromShop:false, price:l.price, seller:l.seller, listingId};
  { const _ic = document.getElementById('buyModalIcon'); itemGorselYaz(_ic, item); // 🆕 554
    if (_ic) _ic.style.borderColor = ((RARITY_CFG[item.rarity]||RARITY_CFG.common).color); }
  document.getElementById('buyModalName').textContent = item.name;
  document.getElementById('buyModalSeller').textContent = l.seller;
  document.getElementById('buyModalStats').innerHTML = item.stats.map(s=>`<div class="buy-stat">${s}</div>`).join('');
  document.getElementById('buyModalPrice').textContent = l.price;
  document.getElementById('buyModal').classList.add('open');
}

function cancelListing(listingId) {
  const listing = _marketListings.find(x => x.id === listingId);
  if (!listing || !listing.listed) return;

  // Item bilgisi (modal'da göster)
  const item = (typeof SHOP_ITEMS !== 'undefined') ? SHOP_ITEMS.find(i => i.id === listing.itemId) : null;
  const itemName = item ? item.name : 'Bu item';

  // 🆕 Önce onay sor
  if (typeof cftConfirm === 'function') {
    cftConfirm({
      title: 'İlanı Geri Al?',
      message: `${itemName} pazar yerinden geri alınacak ve dolabında tekrar kullanılabilir olacak.`,
      confirmText: 'Evet, Geri Al',
      cancelText: 'İptal',
      danger: true,
      onConfirm: () => _doCancelListing(listingId)
    });
  } else {
    // Fallback
    _doCancelListing(listingId);
  }
}

async function _doCancelListing(listingId) {
  // 🆕 İPTAL ARTIK SUNUCUDA. Eskiden burada yalnızca `listed=false`
  //    yapılıyordu; ürün satıcının dolabına GERİ KONMUYORDU. İlan
  //    verilirken dolaptan çıkarıldığı için iptal eden oyuncu ürününü
  //    tamamen kaybediyordu.
  showShopToast('⏳ İlan geri alınıyor…', 'var(--text2)');
  try {
    const _res = await edgeCall('market_cancel', { listing: listingId });
    const d = _res && _res.data;
    if (!_res.ok || !d || d.error) {
      const msg = {
        ilan_bulunamadi:    'İlan bulunamadı.',
        senin_ilanin_degil: 'Bu ilan sana ait değil.',
        ilan_zaten_kapali:  'Bu ilan zaten kapalı.',
        dolap_dolu:         'Dolabın dolu. Önce bir item çıkar.',
        item_bulunamadi:    'Ürün tanınmıyor.',
        dolaba_konamadi:    'Ürün dolabına konamadı, ilan açık bırakıldı.'
      }[d && d.error] || 'İlan geri alınamadı.';
      showShopToast('❌ ' + msg, '#ef5350');
      return;
    }
  } catch(e) {
    showShopToast('❌ Sunucuya ulaşılamadı.', '#ef5350');
    return;
  }

  // Listeden düşür + dolabı sunucudan tazele
  try {
    const idx = _marketListings.findIndex(x => x && x.id === listingId);
    if (idx !== -1) _marketListings.splice(idx, 1);
  } catch(e) {}
  try { if (typeof _eqDataLoadFromServer === 'function') await _eqDataLoadFromServer(); } catch(e) {}
  _ekIlanlar = _ekIlanlar.filter(x => x.id !== listingId);
  _ekIlanYukle();

  showShopToast('✅ İlan geri alındı, ürün dolabında.', 'var(--accent)');
  try { renderMarket(_marketSearchQ || ''); } catch(e) {}
  if (document.getElementById('eqWardrobe')) {
    try { if (typeof renderSlots === 'function') renderSlots(); } catch(_) {}
    try { if (typeof renderWardrobe === 'function') renderWardrobe(); } catch(_) {}
    try { if (typeof _refreshSkillsAfterEquipChange === 'function') _refreshSkillsAfterEquipChange(); } catch(_) {}
  }
}

// 🆕 546 — Yalnızca YENİ ilanı ekler. Eskiden kullanıcının bellekteki TÜM
//   ilanlarını `listed` değeriyle upsert ediyordu: iptal/satış gibi durum
//   değişiklikleri istemciden yazılmaya çalışılıyor (RLS'e takılıp sessizce
//   kayboluyor), bayat bir önbellek kapanmış ilanı yeniden açmaya çalışıyordu.
//   İptal (market_cancel) ve satış (market_buy) yalnızca sunucuda.
async function saveMarket(l) {
  if (!l || !window.sb || !authUser || !authUser.id) return false;
  const dataExtra = Object.assign({}, l);
  delete dataExtra.id; delete dataExtra.seller; delete dataExtra.sellerUserId;
  delete dataExtra.price; delete dataExtra.listed; delete dataExtra.createdAt;
  l.sellerUserId = authUser.id;
  const { error } = await window.sb.from('item_listings').insert({
    id: l.id,
    seller_name: l.seller || (authUser.name || 'Bilinmeyen'),
    seller_user_id: authUser.id,
    price: l.price || 0,
    listed: true,
    data: dataExtra,
    updated_at: new Date().toISOString()
  });
  // 598 — ilan verilince eşya satıcının dolabından SUNUCUDA düşer; dolap sunucudan tazelenir
  const _dolapTazele = () => {
    if (typeof _eqDataLoadFromServer !== 'function') return;
    _eqDataLoadFromServer().then(() => {
      try { if (typeof _eqData !== 'undefined') _eqData = getEqData(); } catch(e) {}
      try { if (typeof renderWardrobe === 'function' && document.getElementById('eqWardrobe')) renderWardrobe(); } catch(e) {}
      try { if (typeof renderSlots === 'function' && document.getElementById('eqWardrobe')) renderSlots(); } catch(e) {}
    });
  };
  _dolapTazele();
  if (!error) _ekIlanYukle();
  if (error) {
    console.warn('[market] ilan eklenemedi:', error.message || error);
    const i = _marketListings.indexOf(l);
    if (i !== -1) _marketListings.splice(i, 1);
    showShopToast(/ilan_sinir/.test(String(error.message || '')) ? '❌ En fazla 20 açık ilanın olabilir.'
      : /ilan_min_fiyat/.test(String(error.message || '')) ? `❌ En düşük fiyat ${_pazarMinFiyat()} 💎.`   // 863
      : '❌ İlan verilemedi, tekrar dene.', '#ef5350');
    try { if (typeof renderWardrobe === 'function' && document.getElementById('eqWardrobe')) renderWardrobe(); } catch(e) {}
    try { if (typeof renderMarket === 'function' && document.getElementById('marketList')) renderMarket(); } catch(e) {}
    return false;
  }
  return true;
}

// ── Satış Modalı ──
function openSellModal() {
  const eq = getEqData();
  const list = document.getElementById('sellWardrobeList');
  _sellItemId = null;
  document.getElementById('sellPriceWrap').style.display='none';
  { const _mn = _pazarMinFiyat(), _lb = document.getElementById('sellPriceLabel'), _in = document.getElementById('sellPriceInput');   // 863
    if (_lb) _lb.textContent = `Satış Fiyatı (en az ${_mn} 💎)`;
    if (_in) _in.min = String(_mn); }

  if(!eq.wardrobe.length) {
    list.innerHTML = '<div style="padding:20px;text-align:center;color:var(--text3);font-size:12px">Dolabında satılacak item yok.</div>';
  } else {
    list.innerHTML = eq.wardrobe.map(item=>{
      const r = RARITY_CFG[item.rarity]||RARITY_CFG.common;
      return `<div class="sell-item-row" onclick="selectSellItem('${item.id}',this)">
        <span class="sell-item-ic${itemGorselUrl(item.id)?' itm-gorselli':''}" style="font-size:22px">${itemGorselHtml(item)}</span>
        <div style="flex:1">
          <div style="font-size:12px;font-weight:700">${item.name}</div>
          <div style="font-size:10px;color:${r.color}">${r.label} · ${item.bonus}</div>
        </div>
        <div class="sell-item-select-circle" id="sellCircle_${item.id}"></div>
      </div>`;
    }).join('');
  }
  document.getElementById('sellModal').classList.add('open');
}

function selectSellItem(itemId, el) {
  _sellItemId = itemId;
  document.querySelectorAll('.sell-item-select-circle').forEach(c=>c.classList.remove('selected'));
  document.getElementById('sellCircle_'+itemId)?.classList.add('selected');
  document.getElementById('sellPriceWrap').style.display='block';
}

function closeSellModal() {
  document.getElementById('sellModal').classList.remove('open');
  _sellItemId = null;
}

function confirmSell() {
  if(!_sellItemId) return;
  const price = parseInt(document.getElementById('sellPriceInput').value);
  if(!price||price<1) { showShopToast('Geçerli bir fiyat gir!','#ef5350'); return; }
  if(price < _pazarMinFiyat()) { showShopToast(`❌ En düşük fiyat ${_pazarMinFiyat()} 💎.`,'#ef5350'); return; }   // 863
  const eq   = getEqData();
  const item = eq.wardrobe.find(w=>w.id===_sellItemId);
  if(!item) return;

  // Pazara ekle
  initMarketListings();
  const _yeniIlan = {
    id: 'ml_'+Date.now(),
    itemId: _sellItemId,
    seller: authUser?.name||'Sen',
    price,
    listed: true,
  };
  _marketListings.push(_yeniIlan);
  saveMarket(_yeniIlan);

  // Dolaptan çıkar
  eq.wardrobe = eq.wardrobe.filter(w=>w.id!==_sellItemId);
  // Aktif slottan da çıkar
  eq.activeSlots = eq.activeSlots.map(s=>s===_sellItemId?null:s);
  saveEqData(eq, true);

  closeSellModal();
  showShopToast('✅ '+(item.name)+' pazara çıkarıldı · 💎'+price, 'var(--gold)');
  renderMarket();
}

function showShopToast(msg, color) {
  const t = document.createElement('div');
  const textColor = (color==='var(--accent)'||color==='var(--gold)') ? 'var(--bg)' : '#fff';
  t.style.cssText = `position:fixed;bottom:90px;left:50%;transform:translateX(-50%);
    background:${color};color:${textColor};padding:9px 18px;border-radius:20px;
    font-size:11px;font-weight:700;z-index:9999;font-family:Twemoji Country Flags,'Barlow Condensed',sans-serif;
    text-align:center;max-width:290px;box-shadow:0 4px 16px rgba(0,0,0,.5)`;
  t.textContent = msg;
  document.body.appendChild(t);
  setTimeout(()=>t.remove(), 2600);
}


// 🆕 Mağaza stok takibi — Supabase shop_stocks tablosu (GLOBAL — herkes aynı)
let _shopStocksCache = null;
let _shopStocksLoading = null;

async function _shopStocksLoadFromServer() {
  if (!window.sb) return;
  try {
    const { data, error } = await window.sb.from('shop_stocks').select('item_id, sold_count');
    if (error) { _shopStocksCache = {}; return; }
    const map = {};
    (data || []).forEach(r => { map[r.item_id] = r.sold_count || 0; });
    _shopStocksCache = map;
  } catch(e) { _shopStocksCache = {}; }
}

function getShopStocks() {
  if (_shopStocksCache) return _shopStocksCache;
  // Henüz yüklenmedi — arkaplan yükleme tetikle, demo değerleri dön
  if (!_shopStocksLoading) {
    _shopStocksLoading = _shopStocksLoadFromServer().then(() => {
      _shopStocksLoading = null;
      try { if (typeof renderShopItems === 'function') renderShopItems(); } catch(e) {}
    });
  }
  return {
    'gk1':12, 'gk2':8,  'gk3':25, 'gk4':30,
    'atk1':18,'atk2':14,'atk3':40,'atk4':38,'atk5':42,
    'pm1':10, 'pm2':7,
    'def1':15,'def2':9,
    'men1':6, 'men2':4,
  };
}

async function incrShopStock(itemId) {
  if (!_shopStocksCache) _shopStocksCache = {};
  _shopStocksCache[itemId] = (_shopStocksCache[itemId] || 0) + 1;
  // Supabase'e yaz
  if (window.sb) {
    try {
      await window.sb.from('shop_stocks').upsert({
        item_id: itemId,
        sold_count: _shopStocksCache[itemId],
        updated_at: new Date().toISOString()
      }, { onConflict: 'item_id' });
    } catch(e) { console.warn('[shop_stocks] upsert hata:', e); }
  }
}


// ══ LİG v2 ══
const LG2_TIER_COLOR = ['#ffd600','#00b0ff','#00e676'];
// Klasman kalkanlarının renkleri: S, 1L, 2L, 3L, 4L, 5L
const LG2_KALKAN_RENK = ['#f8b224','#2f8cff','#3bb352','#fd6a1f','#b95cf6','#f0383a'];
const _LGK_OK = '<svg class="lgk-ok" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 5 16 12 9 19"/></svg>';

let _lg2Country   = null; // seçili ülke key
let _lg2TierIdx   = 0;    // seçili tier index
let _lg2ViewTab   = 'table'; // table | fixture | goals | assists | ratings

// Accordion — hangi ülke açık (null = hepsi kapalı)
let _lg2ExpandedCountry = null;

function lg2ToggleCountry(key) {
  _lg2ExpandedCountry = (_lg2ExpandedCountry === key) ? null : key;
  lg2RenderList();
}

// Kullanıcının takımı bu ülkenin hangi liginde (yoksa -1)
function _lg2BenimTier(cc) {
  if (typeof _userTeam === 'undefined' || !_userTeam || _userTeam.countryCode !== cc) return -1;
  const c = _cftGetCountry(cc);
  return c ? c.leagues.findIndex(l => (l.teams || []).some(t => t.name === _userTeam.teamName)) : -1;
}

function lg2RenderList() {
  // Ülke listesi açıldığında Ligim modu kalkar
  document.body.classList.remove('lg-myleague-mode');
  const _titleSpan = document.querySelector('#page-leagues > .hm-title-box .hm-title span');
  if (_titleSpan) _titleSpan.textContent = 'LİGLER';
  const el = document.getElementById('lg2CountryList');
  if(!el) return;

  let html = '';
  for (const [key, country] of _cftAllEntries()) {
    const acik = _lg2ExpandedCountry === key;
    const benim = _lg2BenimTier(key);
    html += `<div class="lgk-ulke${acik ? ' ac' : ''}">
      <div class="lgk-ulke-b" onclick="lg2ToggleCountry('${key}')"><span class="lgk-bay">${country.flag}</span><span class="lgk-ulke-ad">${country.name}</span><span class="lgk-ulke-sy">${country.leagues.length} lig · ${country.total} takım</span>${_LGK_OK}</div>`;
    if (acik) {
      html += '<div class="lgk-ulke-g">' + country.leagues.map((lg, ti) =>
        `<button class="lgk-lig${ti === benim ? ' ben' : ''}" style="--tc:${LG2_KALKAN_RENK[ti] || '#78909c'}" onclick="lg2OpenLeague('${key}',${ti})">${_banKalkanImg(ti, 44)}<span>${lg.teams.length} takım</span>${ti === benim ? '<em>Takımın</em>' : ''}</button>`
      ).join('') + '</div>';
    }
    html += '</div>';
  }
  el.innerHTML = html;
}

// 🆕 Hızlı erişim: LİGİM — kullanıcının kendi liginin detayına direkt git
function hmGoToMyLeague() {
  const navBtns = document.querySelectorAll('.nav-btn');
  if (typeof showPage === 'function') {
    showPage('leagues', navBtns[4]);
  }

  if (typeof _userTeam !== 'undefined' && _userTeam && _userTeam.countryCode && _userTeam.teamName) {
    const cc = _userTeam.countryCode;
    const teamName = _userTeam.teamName;

    // 🆕 Takımın gerçek tier'ını teams DB'den dinamik bul (klasman değişmiş olabilir)
    let tierIdx = -1;
    if (true && _cftGetCountry(cc) && Array.isArray(_cftGetCountry(cc).leagues)) {
      for (let ti = 0; ti < _cftGetCountry(cc).leagues.length; ti++) {
        const teams = _cftGetCountry(cc).leagues[ti].teams || [];
        if (teams.some(t => t.name === teamName)) {
          tierIdx = ti;
          break;
        }
      }
    }
    // Fallback: _userTeam.tierIdx (teams DB'de bulunamazsa)
    if (tierIdx < 0) {
      tierIdx = (typeof _userTeam.tierIdx === 'number') ? _userTeam.tierIdx : 0;
    }

    // 🆕 Ligim modu: sadece kullanıcının klasmanı (tier pill'leri gizlenir, geri butonu home'a döner)
    document.body.classList.add('lg-myleague-mode');
    // Başlığı LİGİM yap
    const _titleSpan = document.querySelector('#page-leagues > .hm-title-box .hm-title span');
    if (_titleSpan) _titleSpan.textContent = 'LİGİM';
    if (typeof lg2OpenLeague === 'function') {
      setTimeout(() => {
        try { lg2OpenLeague(cc, tierIdx); } catch(e) { console.warn('lg2OpenLeague hata:', e); }
      }, 30);
    }
  }
}

// 🆕 Hızlı erişim: TURNUVAM — kullanıcının kendi turnuvasına direkt git
// + EN GÜNCEL AŞAMAYI aç (groups / bracket)
// + Kullanıcının olduğu grup/maça scroll
// 887 — kullanıcının milli takımı bu sezonun EURO Cup'ında mı (ülke kodu ya da null)
function _hmMilliTurnuvada() {
  try {
    const info = (typeof getSeasonInfo === 'function') ? getSeasonInfo() : null;
    const cc = (typeof _hmMilliCC === 'function') ? _hmMilliCC() : null;
    if (!info || info.preSeason || !cc || typeof encEnsureState !== 'function') return null;
    const st = encEnsureState(info.season);
    if (!st || !Array.isArray(st.groups)) return null;
    const ad = (typeof _ulkeAdi === 'function') ? _ulkeAdi(cc) : null;
    return st.groups.some(g => (g.teams || []).some(t => t && (t.code === cc || (ad && t.name === ad)))) ? cc : null;
  } catch (e) { return null; }
}
// 887 — Turnuvam → EURO Cup: güncel aşama (gruplar / eleme), kullanıcının grubu ve satırı
function _hmEuroAc() {
  const info = getSeasonInfo();
  showPage('tournaments', (typeof findNavBtn === 'function' && findNavBtn('tournaments')) || document.querySelectorAll('.nav-btn')[5]);
  setTimeout(() => {
    try {
      const st = (typeof encLoad === 'function') ? encLoad(info.season) : null;
      const eleme = (info.dayInSeason || 1) >= 37 || !!(st && ['final', 'sf', 'qf', 'r16'].find(ph => Array.isArray(st[ph]) && st[ph].length > 0));
      _encSubTab = eleme ? 'knockout' : 'groups';
      delete _trkSecim.enc;
      trn2Tab('euroNation', document.querySelector(`.trn2-tab[onclick*="'euroNation'"]`));
      setTimeout(() => {
        const el = document.querySelector('#trn2Content .trk-gk.on .lgk-tr.ben, #trn2Content .trk-po.ben, #trn2Content .trk-ek.ben');
        if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }, 200);
    } catch (e) { console.warn('[887] EURO Cup açılamadı:', e); }
  }, 30);
}
let _hmTrnEncDenendi = false;
function hmGoToMyTournament() {
  const navBtns = document.querySelectorAll('.nav-btn');

  // 🆕 getUserTurnuva() Sezon 1 için teams DB sırasından, Sezon 2+ için _userTeam.europeanCup'tan döner
  const userTrn = (typeof getUserTurnuva === 'function') ? getUserTurnuva() : null;

  // 887 — milli takım EURO Cup'taysa: EURO döneminde (gün 34+) ya da kulübün Avrupa kupası yoksa EURO Cup açılır
  const _kulupKupa = typeof _userTeam !== 'undefined' && !!_userTeam && !!userTrn;
  const _gunT = (typeof getSeasonInfo === 'function') ? (getSeasonInfo().dayInSeason || 1) : 1;
  if (_gunT >= 34 || !_kulupKupa) {
    if (_hmMilliTurnuvada()) { _hmEuroAc(); return; }
    // EURO verisi henüz yüklenmediyse bir kez yükleyip yeniden dene
    const _sz = (typeof getSeasonInfo === 'function') ? getSeasonInfo().season : null;
    if (!_hmTrnEncDenendi && _sz && typeof encLoad === 'function' && !encLoad(_sz) && typeof _encLoadFromServer === 'function') {
      _hmTrnEncDenendi = true;
      _encLoadFromServer(_sz).then(() => hmGoToMyTournament()).catch(() => hmGoToMyTournament());
      return;
    }
  }

  if (typeof _userTeam === 'undefined' || !_userTeam || !userTrn) {
    if (typeof showJoinToast === 'function') {
      showJoinToast('🏆 Takımın bu sezon Avrupa turnuvasına hak kazanamadı. Lig sıralamanı yükselt!');
    }
    return;
  }

  // 🆕 EN GÜNCEL AŞAMAYI belirle — sezon takvimine göre
  // SEASON_TEMPLATE:
  //   Gün 1-3:  Play-off oynandı + Gruplar belli → 'groups'
  //   Gün 2-14: Grup maçları oynanıyor → 'groups'
  //   Gün 19-33: Eleme (Son 16 → Final) → 'bracket'
  //   Gün 34+:  Eleme bitti (Final 33. gün), istatistik → 'bracket'
  function _pickCurrentSubTab() {
    try {
      const info = (typeof getSeasonInfo === 'function') ? getSeasonInfo() : null;
      if (!info) return 'groups';
      const d = info.dayInSeason || 1;
      // Champions ilk grup maçı gün 4, Elite gün 3, Convergence gün 2
      // Son 16 ilk maç gün 19 (con), 20 (eli), 21 (chm)
      // Gün 19+: eleme zamanı → bracket
      if (d >= 19) return 'bracket';
      // Onun dışında gruplar
      return 'groups';
    } catch(e) { return 'groups'; }
  }
  const targetSubTab = _pickCurrentSubTab();

  // Turnuva sayfasını aç
  if (typeof showPage === 'function') {
    showPage('tournaments', navBtns[5]);
  }

  const TRN_KEY_MAP = { chm: 'champ', eli: 'elite', con: 'conv' };
  const trnKey = TRN_KEY_MAP[userTrn];

  if (!trnKey) return;

  // 1) Önce üst tab'ı (champ/elite/conv) seç
  setTimeout(() => {
    try {
      if (typeof trn2Tab === 'function') {
        const tabBtns = document.querySelectorAll('.trn2-tab');
        const tabBtn = Array.from(tabBtns).find(b => {
          const oc = b.getAttribute('onclick') || '';
          return oc.indexOf("'" + trnKey + "'") >= 0;
        });
        trn2Tab(trnKey, tabBtn || null);
      }

      // 2) Güncel alt sekme; grup / tur seçimi kullanıcının yerine döner
      _trkSecim[trnKey] = {};
      trn2SubTab(trnKey, targetSubTab, null);
      // 3) Kullanıcının satırına kaydır
      setTimeout(() => {
        const el = document.querySelector('#trn2Content .trk-gk.on .lgk-tr.ben, #trn2Content .trk-po.ben, #trn2Content .trk-ek.ben');
        if (el) el.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }, 200);
    } catch(e) { console.warn('trn2Tab hata:', e); }
  }, 30);
}

// Lig aç → detay görünümüne geç
function lg2OpenLeague(countryKey, tierIdx) {
  _lg2Country = countryKey;
  _lg2TierIdx = tierIdx;
  _lg2ViewTab = 'table';

  // 🆕 Katmanlı yükleme: bu ülkenin sezonluk maçları cache'te yoksa talep üzerine çek,
  //   gelince açık görünümü tazele (puan tablosu / fikstür).
  try {
    if (typeof _msEnsureCountry === 'function') {
      _msEnsureCountry(countryKey).then(() => {
        const det = document.getElementById('lg-view-detail');
        if (!det || det.style.display === 'none') return;
        if (_lg2ViewTab === 'table' && typeof lg2RenderTable === 'function') lg2RenderTable();
        else if (_lg2ViewTab === 'fixture' && typeof lg2RenderFixture === 'function') lg2RenderFixture();
      });
    }
  } catch(e) {}

  const country = _cftGetCountry(countryKey);
  if(!country) return;

  _lg2HeroCiz();
  _lg2SeviyeCiz();

  // Görünümü değiştir
  document.getElementById('lg-view-list').style.display   = 'none';
  document.getElementById('lg-view-detail').style.display = 'block';

  // Tab sıfırla
  document.querySelectorAll('.lg2-vtab').forEach(b=>b.classList.remove('active'));
  document.querySelectorAll('.lg2-vtab')[0].classList.add('active');

  lg2RenderTable();
}

// Lig başlığı: bayrak + klasman kalkanı, sezon · hafta · takım sayısı, sezon takvimi çubuğu
function _lg2HeroCiz() {
  const el = document.getElementById('lg2Hero');
  const country = _cftGetCountry(_lg2Country);
  if (!el || !country) return;
  const ti = _lg2TierIdx, lig = country.leagues[ti] || { teams: [] };
  const info = getSeasonInfo();
  const gun = info.preSeason ? 0 : Math.max(1, Math.min(SEASON_LEN, info.dayInSeason || 1));
  const hafta = gun <= 15 ? gun : (gun >= 19 && gun <= 33 ? gun - 3 : 0);
  const durum = !gun ? '<span>Sezon başlamadı</span>'
    : hafta ? `<span><b>${hafta}. Hafta</b></span><span data-noi18n>/ 30</span>`
    : `<span><b>${gun <= 18 ? 'Ara transfer' : 'Sezon sonu'}</b></span>`;
  const w = n => (n / SEASON_LEN * 100) + '%';
  const yuzde = gun / SEASON_LEN * 100;
  el.style.setProperty('--tc', LG2_KALKAN_RENK[ti] || '#78909c');
  el.innerHTML = `${_banKalkanImg(ti, 150, 'lgk-wm')}
    <div class="lgk-h-ust">${_banKalkanImg(ti, 62)}<div class="lgk-h-yazi">
      <div class="lgk-h-ulke"><span class="lgk-bay">${country.flag}</span><span>${country.name}</span></div>
      <div class="lgk-h-alt"><span>Sezon ${info.season}</span><i>·</i>${durum}<i>·</i><span>${lig.teams.length} takım</span></div>
    </div></div>
    <div class="lgk-h-ser">
      <div class="lgk-h-bar"><i style="width:${w(15)}"></i><i class="ar" style="width:${w(3)}"></i><i style="width:${w(15)}"></i><i class="sn" style="width:${w(SEASON_LEN - 33)}"></i>
        <u style="width:${yuzde}%"></u>${gun ? `<em class="${yuzde < 9 ? 'bas' : yuzde > 91 ? 'son' : ''}" style="left:${yuzde}%"><span>Gün ${gun}</span></em>` : ''}</div>
      <div class="lgk-h-bet"><span style="width:${w(15)}">1. Devre</span><span style="width:${w(3)}">Transfer</span><span style="width:${w(15)}">2. Devre</span><span style="width:${w(SEASON_LEN - 33)}">Sezon sonu</span></div>
    </div>`;
}

// Klasman seçici: ülkedeki her lig için kalkan; kullanıcının ligi yeşil noktalı
function _lg2SeviyeCiz() {
  const el = document.getElementById('lg2TierPills');
  const country = _cftGetCountry(_lg2Country);
  if (!el || !country) return;
  const benim = _lg2BenimTier(_lg2Country);
  el.style.gridTemplateColumns = `repeat(${country.leagues.length},1fr)`;
  el.innerHTML = country.leagues.map((lg, ti) =>
    `<button class="lgk-sev-b${ti === _lg2TierIdx ? ' on' : ''}" style="--tc:${LG2_KALKAN_RENK[ti] || '#78909c'}" onclick="lg2SwitchTier(${ti})">${_banKalkanImg(ti, 34)}${ti === benim ? '<i></i>' : ''}</button>`
  ).join('');
}

function lg2SwitchTier(ti) {
  _lg2TierIdx = ti;
  _lg2HeroCiz();
  _lg2SeviyeCiz();
  _lg2IcerikCiz();
}

function _lg2IcerikCiz() {
  if (_lg2ViewTab === 'fixture')      lg2RenderFixture();
  else if (_lg2ViewTab === 'goals')   lg2RenderStat('goals');
  else if (_lg2ViewTab === 'assists') lg2RenderStat('assists');
  else if (_lg2ViewTab === 'ratings') lg2RenderStat('rating');
  else                                lg2RenderTable();
}

// 🆕 Ligler başlığındaki GERİ butonu:
//   • Lig detayındaysa → ülke listesine döner
//   • Ligim modundaysa veya listedeyse → bir önceki sayfaya
function lg2HeaderBack() {
  try {
    const det = document.getElementById('lg-view-detail');
    const inDetail = det && det.style.display && det.style.display !== 'none';
    const myMode = document.body.classList.contains('lg-myleague-mode');
    if (inDetail && !myMode) { lg2BackToList(); return; }
    if (inDetail && myMode) {
      document.body.classList.remove('lg-myleague-mode');
      const _t = document.querySelector('#page-leagues > .hm-title-box .hm-title span');
      if (_t) _t.textContent = 'LİGLER';
      const _lvL = document.getElementById('lg-view-list');
      const _lvD = document.getElementById('lg-view-detail');
      if (_lvL) _lvL.style.display = 'block';
      if (_lvD) _lvD.style.display = 'none';
    }
  } catch(e) {}
  if (typeof goBackPage === 'function') goBackPage();
}

function lg2BackToList() {
  // 🆕 Ligim modunda iken: home'a dön + mode kalk
  if (document.body.classList.contains('lg-myleague-mode')) {
    document.body.classList.remove('lg-myleague-mode');
    // Başlığı LİGLER'e çevir
    const _titleSpan = document.querySelector('#page-leagues > .hm-title-box .hm-title span');
    if (_titleSpan) _titleSpan.textContent = 'LİGLER';
    const navBtns = document.querySelectorAll('.nav-btn');
    if (typeof showPage === 'function' && navBtns.length > 0) {
      showPage('home', navBtns[0]);
    }
    return;
  }
  document.getElementById('lg-view-list').style.display   = 'block';
  document.getElementById('lg-view-detail').style.display = 'none';
}

function lg2ViewTab(tab, btn) {
  _lg2ViewTab = tab;
  document.querySelectorAll('.lg2-vtab').forEach(b=>b.classList.remove('active'));
  if(btn) btn.classList.add('active');
  _lg2IcerikCiz();
}

// Lig sayfası — gol/asist/reyting render
// 🆕 TEK DÜNYA: önce o ligin TÜM takımlarını DB'den yükle, sonra sırala (cihazdan bağımsız).
async function lg2RenderStat(statType) {
  const el = document.getElementById('lg2DetailContent');
  if(!el || typeof renderStatList !== 'function') return;
  const _cc = _lg2Country, _ti = _lg2TierIdx;
  const country = _cftGetCountry(_cc);
  const teams = (country && country.leagues && country.leagues[_ti] && country.leagues[_ti].teams) || [];
  const needLoad = teams.some(t => !_teamRosterCache[_cc + ':' + t.name]);
  if (needLoad) {
    el.innerHTML = '<div class="lst-empty"><div class="lst-empty-icon">⏳</div>Sıralama yükleniyor…</div>';
    if (typeof _loadAllLeagueRostersForRanking === 'function') {
      try { await _loadAllLeagueRostersForRanking(_cc, _ti); } catch(e){}
    }
    // Yükleme sırasında kullanıcı başka lige/ülkeye geçtiyse bu sonucu yazma
    if (_lg2Country !== _cc || _lg2TierIdx !== _ti) return;
  }
  el.innerHTML = renderStatList(_cc, _ti, statType);
}


// ═══════════════════════════════════════
//   OYUNCU SEZON İSTATİSTİKLERİ (Gol/Asist/Reyting)
// ═══════════════════════════════════════
//
// 🆕 Sezon istatistikleri artık server'dan (players tablosu goals_total/assists_total/
//    match_ratings) okunur — frontend hesap/üretim YAPMAZ.


// 🆕 Eski migration — artık gerek yok, server playerStats üretiyor.
// JSON.stringify(4500 maç) çok yavaştı, no-op yapıldı.
function _migrateMatchPlayerStats() {
  // Boş bırakıldı; server-side playerStats üretildiğinde frontend okur.
}

// 🆕 TEK DÜNYA SIRALAMA — o ligin TÜM takımlarının roster'ını DB'den yükle.
//   Sıralama _teamRosterCache'ten beslendiği için, cache eksikse sıralama cihazdan
//   cihaza değişir. Bu fonksiyon eksik takımları paralel yükleyip cache'i tamamlar.
async function _loadAllLeagueRostersForRanking(countryCode, tierIdx) {
  if (!window.sb) return;
  const country = _cftGetCountry(countryCode);
  if (!country || !country.leagues || !country.leagues[tierIdx]) return;
  const teams = country.leagues[tierIdx].teams || [];
  const missing = teams.filter(t => {
    const key = countryCode + ':' + t.name;
    return !_teamRosterCache[key];
  });
  if (!missing.length) return; // hepsi zaten yüklü
  // 🆕 565 — eksik takımlar TEK toplu sorguyla (aynı dönüşüm, aynı önbellek)
  try { await _kadrolariTopluYukle(countryCode, missing.map(t => t.name)); } catch(e) {}
}

function computePlayerStats(countryCode, tierIdx, opts) {
  // 🆕 GERÇEK OYUNCULAR — _calcPlayerStatsFromCache lineup'tan gerçek 22 oyuncuyu okur.
  //   Eski guestGenerateRoster (uydurma roster) SİLİNDİ.
  const country = _cftGetCountry(countryCode);
  if(!country || !country.leagues || !country.leagues[tierIdx]) return [];
  const teams = country.leagues[tierIdx].teams || [];
  const teamNames = teams.map(t => t.name);
  const teamMap = {};
  teams.forEach(t => { teamMap[t.name] = t; });

  let allStats = {};
  try { allStats = (typeof _calcPlayerStatsFromCache === 'function') ? _calcPlayerStatsFromCache(teamNames, opts) : {}; } catch(e) {}

  const players = [];
  Object.entries(allStats).forEach(([sk, s]) => {
    // sk = "TeamName_PlayerName"
    const idx = sk.indexOf('_');
    if (idx <= 0) return;
    const teamName = sk.slice(0, idx);
    const playerName = sk.slice(idx + 1);
    const team = teamMap[teamName];
    if (!team) return; // bu tier'de değilse atla
    const _rc = (s.ratingCount != null) ? s.ratingCount : s.matches;
    const rating = _rc > 0
      ? Math.round((s.ratingSum / _rc) * 10) / 10
      : 0;
    players.push({
      name: playerName,
      pos: s.pos || '',
      subPos: s.subPos || null,
      teamName,
      teamShort: team.short || (teamName || '').slice(0, 3).toUpperCase(),
      teamBg: team.bg || 'rgba(255,255,255,.08)',
      teamTc: team.tc || '#90caf9',
      countryCode,
      flag: country.flag,
      goals: s.goals,
      assists: s.assists,
      rating,
      matches: s.matches,
      userId: s.userId || null,
      avatarId: s.avatarId || null,   // 921
      uyruk: s.nation && s.nation !== '🏳️' ? s.nation : country.flag,
      isUser: false,
    });
  });

  // 🆕 Kullanıcı işaretle — kanonik kimlik: user_id === authUser.id (isim eşleşmesi değil)
  try {
    const myId = (window.authUser || {}).id;
    if (myId) players.forEach(pl => { if (pl.userId && pl.userId === myId) pl.isUser = true; });
  } catch(e) {}

  return players;
}
function _posLabel3(pos) {
  return pos === 'FWD' ? 'For' :
         pos === 'MID' ? 'Ort' :
         pos === 'DEF' ? 'Def' :
         pos === 'GK'  ? 'Klc' : pos;
}

function _rankClass(rank) {
  if(rank === 1) return 'gold';
  if(rank === 2) return 'silver';
  if(rank === 3) return 'bronze';
  return '';
}

const _LG2_ISTAT_IKON = {
  goals: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="color:#00e676"><circle cx="12" cy="12" r="8.5"/><path d="M12 7.5l2.6 1.9-1 3.1h-3.2l-1-3.1Z"/><path d="M12 7.5V4M14.6 9.4l3-1M13.6 12.5l1.9 2.6M10.4 12.5l-1.9 2.6M9.4 9.4l-3-1"/></svg>',
  assists: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="color:#00b0ff"><path d="M4 16c5 .5 9-1.5 12-7"/><path d="M13 4l4 1-1 4"/><circle cx="5" cy="18.5" r="1.8" fill="currentColor" stroke="none"/></svg>',
  rating: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="color:#ffd600"><path d="M12 3.5l2.6 5.3 5.9.9-4.3 4.1 1 5.8L12 17l-5.2 2.6 1-5.8L3.5 9.7l5.9-.9Z"/></svg>',
};
// Tıklanınca profil: ziyaretçi profil / kendi profil
function _statTik(p) {
  if (p.tiksiz) return '';
  if (!window._statListPlayerCache) window._statListPlayerCache = [];
  const i = window._statListPlayerCache.length;
  window._statListPlayerCache.push({
    name: p.name, pos: p.pos, teamName: p.teamName,
    countryCode: p.countryCode, flag: p.flag,
    rating: typeof p.rating === 'number' ? p.rating : 7.0,
    isUser: !!p.isUser, userId: p.userId || null
  });
  return p.isUser
    ? `onclick="if(typeof openPlayerModalSelfFromRanking==='function')openPlayerModalSelfFromRanking()"`
    : `onclick="statListViewPlayer(${i})"`;
}
function _statDeger(p, statType) {
  if (statType === 'goals')   return [p.goals, 'gol'];
  if (statType === 'assists') return [p.assists, 'asist'];
  return [p.rating.toFixed(1), 'rating'];
}
// 921 — oyuncu avatarı (çerçevesiz; botta silik siluet), adın başında uyruk bayrağı, altta küçük takım logosu + takım adı
function _statAv(p, cls, bay) {
  const id = p.isUser ? _evMyAv() : (p.avatarId || (p.userId && _cnYarisAv[p.userId]) || '');
  const a = id && AVATAR_OPTIONS.find(x => x.id === id);
  const ek = bay && !p.milli && p.uyruk ? `<span class="ist-avb">${p.uyruk}</span>` : '';
  return a && (a.image || a.url) ? `<div class="ist-av ${cls}"><img src="${_avatarSrc(a)}" alt="" loading="lazy">${ek}</div>`
    : `<div class="ist-av ${cls} bos">${_EV_SIL}${ek}</div>`;
}
function _statTk(p, cls, tag) {
  const lg = p.milli ? `<span class="ist-bay">${p.flag || '🏳️'}</span>`
    : inlineBadge({ tag: 'span', cls: 'ist-tlogo', name: p.teamName, cc: p.countryCode, bg: p.teamBg, tc: p.teamTc, short: p.teamShort });
  return `<${tag} class="${cls}ist-tk">${lg}<span class="ist-tad">${p.teamName}</span></${tag}>`;
}

function _statRowHtml(p, rank, statType) {
  const [v, u] = _statDeger(p, statType);
  return `<div class="lgk-ir${p.isUser ? ' ben' : ''}" ${_statTik(p)}><div class="lgk-ir-rk">${rank}</div>${_statAv(p, 'b')}<div class="lgk-ir-a"><b>${!p.milli && p.uyruk ? `<span class="ist-bay">${p.uyruk}</span>` : ''}${p.name}</b>${_statTk(p, '', 'span')}</div><div class="lgk-ir-v"><b>${v}</b><small>${u}</small></div></div>`;
}

// İlk 3 kürsü kartı
function _statPodyumHtml(p, rank, statType) {
  const [v, u] = _statDeger(p, statType);
  return `<div class="lgk-pd s${rank}${p.isUser ? ' ben' : ''}" ${_statTik(p)}><div class="lgk-pd-md">${rank}</div>${_statAv(p, rank === 1 ? 'p1' : 'p', true)}<div class="lgk-pd-ad">${p.name}</div>${_statTk(p, 'lgk-pd-tk ', 'div')}<div class="lgk-pd-v">${v}<small>${u}</small></div></div>`;
}

// 🆕 Stat list satırına tıklayınca: ziyaretçi profil aç (bot için DB'den gerçek veri)
function statListViewPlayer(idx) {
  const cache = window._statListPlayerCache || [];
  const p = cache[idx];
  if (!p) return;
  if (p.isUser) {
    if (typeof openPlayerModalSelfFromRanking === 'function') openPlayerModalSelfFromRanking();
    return;
  }
  // 🆕 TEK DÜNYA: OVR/pos/level UYDURULMAZ — sadece isim+takım+ülke geçilir,
  //   openPlayerModal DB'den gerçek overall/abilities/pos/level'i çözer.
  const player = {
    name: p.name,
    nation: p.flag,
    nationality: p.countryCode || '',
    pos: p.pos || 'MID',
    team_name: p.teamName,
    country_code: p.countryCode || '',
    user_id: p.userId || null,
    role: 'member'
  };
  if (typeof openPlayerModal === 'function') {
    openPlayerModal(player, {
      teamName: p.teamName,
      countryCode: p.countryCode || '',
      teamLookupName: p.teamName,
      isOwnTeam: false
    });
  }
}

// Bir lig için top 25 sıralama HTML'i üretir
// Gol / asist / reyting listesi (kürsü + ilk 25 + kullanıcının sırası) — lig ve turnuvalar ortak
function _istatListeHtml(players, statType, altMetin, reytingAd) {
  let sorted;
  if(statType === 'goals') {
    sorted = [...players].sort((a,b) => b.goals - a.goals || b.assists - a.assists || (a.name>b.name?1:-1));
  } else if(statType === 'assists') {
    sorted = [...players].sort((a,b) => b.assists - a.assists || b.goals - a.goals || (a.name>b.name?1:-1));
  } else {
    sorted = [...players].sort((a,b) => b.rating - a.rating || b.goals - a.goals || (a.name>b.name?1:-1));
  }
  const top25 = sorted.slice(0, 25);
  const kursu = top25.length >= 3;
  const rows = top25.slice(kursu ? 3 : 0).map((p, i) => _statRowHtml(p, i + (kursu ? 4 : 1), statType)).join('');

  // Kullanıcı ilk 25'te değilse, ayrıca alt kısımda göster
  const userIdx = sorted.findIndex(p => p.isUser);
  const userBlock = userIdx >= 25
    ? `<div class="lgk-senin">Senin sıralaman</div><div class="lgk-ls">${_statRowHtml(sorted[userIdx], userIdx + 1, statType)}</div>` : '';

  _oyAvIste(top25.concat(userIdx >= 25 ? [sorted[userIdx]] : []).filter(p => !p.isUser && !p.avatarId).map(p => p.userId), _trnCanliCiz);   // 921
  const titleMap = { goals: 'Gol Kralı', assists: 'Asist Kralı', rating: reytingAd };
  return `<div class="lgk-istat"><div class="lgk-is-bas">${_LG2_ISTAT_IKON[statType]}<b>${titleMap[statType]}</b><span>${altMetin}</span></div>`
    + (kursu ? `<div class="lgk-pod">${[1, 0, 2].map(i => _statPodyumHtml(top25[i], i + 1, statType)).join('')}</div>` : '')
    + (rows ? `<div class="lgk-ls">${rows}</div>` : '') + userBlock + '</div>';
}

function renderStatList(countryCode, tierIdx, statType) {
  const players = computePlayerStats(countryCode, tierIdx, { buckets: ['lig'] });
  if(!players.length) {
    return '<div class="lst-empty"><div class="lst-empty-icon">📊</div>Bu lig için henüz veri yok.</div>';
  }
  // Sezon başında (lig henüz başlamadıysa) gol/asist kralı listesi boş durum
  if(statType !== 'rating' && Math.max(...players.map(p => p[statType] || 0)) === 0) {
    return `<div class="lst-info">📅 Sezon henüz başlamadı veya yeterince ilerlemedi — ${statType==='goals'?'gol':'asist'} kralı listesi sezonun ilerleyen günlerinde görünecek.</div>`;
  }
  const subText = statType === 'rating'
    ? 'Sezon ortalama maç reytingleri'
    : `Sezonda atılan toplam ${statType==='goals'?'gol':'asist'}`;
  return _istatListeHtml(players, statType, subText, 'Sezon Reytingi');
}

// ── Ortak Lig Tablosu Hesaplayıcı ──
// Hem Sıralamalar/lig sayfası hem Takım/Puan Tablosu aynı veri kaynağını kullansın.
// Sezon ilerlemesine orantılı: gün 1 → 0 puan, gün 33+ → tam puanlar.
// opts: {season, progress} ile override edilebilir (örn. önceki sezonun final tablosunu çekmek için).
// 🆕 calcLeagueStandings MEMO: aynı maç verisi (loadedAt) için tekrar tam tarama yapma.
let _lgStandCache = {};
let _lgStandCacheAt = -1;
// 🆕 529 — ETKİN SEZON: Sezon dönüşü (küme düşme/çıkma + yeni fikstür + yeni
//   Avrupa kuraları) 39. günde yapılıyor. Bu yüzden 39. günden itibaren lig
//   tabloları, lig fikstürü ve Avrupa turnuvaları YENİ sezonu gösterir.
//   (EURO Nations Cup finali 40. günde oynandığı için o gerçek sezonda kalır.)
const SEZON_DONUS_GUNU = 39;
// 🆕 533 — Kulüp turnuvası için gösterilecek sezon: SONRAKİ sezonun kurası
//   sunucuda kurulmuşsa (39. günde kurulur) onu göster. Gün hesabına değil,
//   verinin kendisine bakar; saat dilimi / gün kayması sorun çıkarmaz.
function _trnGosterSezon(trnKey) {
  try {
    const s = (typeof getSeasonInfo === 'function') ? (getSeasonInfo().season || 1) : 1;
    if (!trnKey || trnKey === 'enc' || trnKey === 'euroNation') return s;
    const _k = (trnKey === 'euro') ? 'natcup' : trnKey;
    const st = (typeof _tournamentStateGet === 'function') ? _tournamentStateGet(_k, s + 1) : null;
    const fx = st && st.fixture;
    const varMi = !!(st && (st.phase || (fx && (
      (Array.isArray(fx.playoff) && fx.playoff.length) ||
      (Array.isArray(fx.groups) && fx.groups.length) ||
      (Array.isArray(fx.r32) && fx.r32.length) ||
      (Array.isArray(fx.r16) && fx.r16.length)))));
    return varMi ? (s + 1) : s;
  } catch(e) { return (typeof getSeasonInfo === 'function') ? getSeasonInfo().season : 1; }
}
window._trnGosterSezon = _trnGosterSezon;

function _etkinSezon() {
  try {
    const info = (typeof getSeasonInfo === 'function') ? getSeasonInfo() : null;
    if (!info || info.preSeason) return info ? info.season : 1;
    if (info.dayInSeason >= SEZON_DONUS_GUNU) return info.season + 1;
    // 🆕 533 — Gün hesabına ek güvence: sonraki sezonun LİG fikstürü önbellekte
    //   varsa (sunucu 39. günde kurar) yeni sezon gösterilir.
    try {
      if (_matchStateCache && _matchStateCache.byKey) {
        const s2 = info.season + 1;
        for (const m of (_msKova('sezonLig', s2) || Object.values(_matchStateCache.byKey))) {   // 958 — yalnız o sezonun lig maçları
          if (m && m.season === s2 && m.tier != null && !m.tournament_key) return s2;
        }
      }
    } catch(e) {}
    return info.season;
  } catch(e) { return 1; }
}
window._etkinSezon = _etkinSezon;

function calcLeagueStandings(countryCode, tierIdx, opts) {
  // 🆕 SUPABASE TEK KAYNAK — eski _matchResultsLoad cache + lokal fikstür hesabı kaldırıldı.
  //   _matchStateCache.byKey'den ülke+tier'a uyan finished maçları okur, puan tablosu üretir.
  const country = _cftGetCountry(countryCode);
  if (!country) return [];
  const league = country.leagues[tierIdx];
  if (!league) return [];

  const season = (opts && typeof opts.season === 'number') ? opts.season
    : ((typeof _etkinSezon === 'function') ? _etkinSezon()
       : ((typeof getSeasonInfo === 'function') ? getSeasonInfo().season : 1));
  const tier1 = tierIdx + 1; // 0-based → 1-based

  // 🆕 MEMO: maç verisi değişmediyse cache'ten dön (her render'da tüm maç taraması yapma)
  const _msAt = (typeof _matchStateCache === 'object' && _matchStateCache && _matchStateCache.loadedAt) || 0;
  if (_msAt !== _lgStandCacheAt) { _lgStandCache = {}; _lgStandCacheAt = _msAt; }
  const _lgKey = countryCode + '|' + tierIdx + '|' + season;
  if (_lgStandCache[_lgKey]) return _lgStandCache[_lgKey].map(o => ({ ...o }));

  // Tüm takımlar için sıfır istatistik başlat
  const stats = {};
  league.teams.forEach((t, idx) => {
    stats[t.name] = { ...t, idx, played:0, g:0, b:0, m:0, ag:0, ay:0, gd:0, pts:0 };
  });

  // match_state'ten finished maçları çek
  if (_matchStateCache && _matchStateCache.byKey) {
    for (const ms of (_msKova('lig', countryCode + '|' + tier1 + '|' + season) || Object.values(_matchStateCache.byKey))) {   // 958 — yalnız bu lig+sezon
      if (!ms) continue;
      if (ms.tournament_key) continue;            // sadece lig
      if (ms.countryCode !== countryCode) continue;
      if (ms.tier !== tier1) continue;
      if (ms.season !== season) continue;
      if (ms.status !== 'finished') continue;     // sadece bitmiş
      const hs = Number(ms.home_score) || 0;
      const as_ = Number(ms.away_score) || 0;
      const home = ms.home;
      const away = ms.away;
      if (stats[home]) {
        stats[home].played++;
        stats[home].ag += hs;
        stats[home].ay += as_;
        if (hs > as_) { stats[home].g++; stats[home].pts += 3; }
        else if (hs === as_) { stats[home].b++; stats[home].pts += 1; }
        else { stats[home].m++; }
      }
      if (stats[away]) {
        stats[away].played++;
        stats[away].ag += as_;
        stats[away].ay += hs;
        if (as_ > hs) { stats[away].g++; stats[away].pts += 3; }
        else if (as_ === hs) { stats[away].b++; stats[away].pts += 1; }
        else { stats[away].m++; }
      }
    }
  }

  const halfWeeks = league.teams.length - 1;
  const arr = Object.values(stats).map(t => ({
    ...t,
    gd: t.ag - t.ay,
    total: halfWeeks * 2
  }));
  arr.sort((a, b) => {
    if (b.pts !== a.pts) return b.pts - a.pts;
    if (b.gd !== a.gd) return b.gd - a.gd;
    return b.ag - a.ag;
  });
  const _lgOut = arr.map((t, i) => ({ ...t, pos: i + 1 }));
  _lgStandCache[_lgKey] = _lgOut;
  return _lgOut.map(o => ({ ...o }));
}

// Sıralama bölge (renk) hesabı — top/bottom tier göz önünde
function getStandingsZone(pos, isTop, isBottom) {
  if(isTop) {
    // Süper Lig: her sıra için Avrupa Cup ataması
    if(pos === 1) return 'chm-d';   // CHM Doğrudan
    if(pos === 2) return 'chm-p';   // CHM Play-off
    if(pos === 3) return 'eli-d';   // ELI Doğrudan
    if(pos === 4) return 'eli-p';   // ELI Play-off
    if(pos === 5) return 'con-d';   // CON Doğrudan
    if(pos === 6) return 'con-p';   // CON Play-off
    if(pos >= 13) return 'rel';
    return 'normal';
  }
  if(isBottom) {
    if(pos <= 4) return 'promo';
    return 'normal';
  }
  if(pos <= 4) return 'promo';
  if(pos >= 13) return 'rel';
  return 'normal';
}

// Bölge renkleri — ortak (lig tablosu, takım puan tablosu, arşiv)
const LG2_BOLGE_RENK = { 'chm-d':'#1976d2','chm-p':'#64b5f6','eli-d':'#2e7d32','eli-p':'#81c784',
                         'con-d':'#e65100','con-p':'#ffb74d', promo:'#00e676', rel:'#ef5350' };

function _lgLejant(isTop, isBottom) {
  const c = (z, no, metin, kupa) => `<span><i style="background:${LG2_BOLGE_RENK[z]}"></i><b>${no}</b>${kupa ? _cupLogoInline(kupa, 14) : ''}<span>${metin}</span></span>`;
  if (isTop) return c('chm-d', 1, 'CHM Doğrudan', 'champ') + c('chm-p', 2, 'CHM Play-off', 'champ')
    + c('eli-d', 3, 'ELI Doğrudan', 'elite') + c('eli-p', 4, 'ELI Play-off', 'elite')
    + c('con-d', 5, 'CON Doğrudan', 'conv') + c('con-p', 6, 'CON Play-off', 'conv') + c('rel', '13-16', 'Küme Düşme');
  return c('promo', '1-4', 'Üst Lige Yükselme')
    + (isBottom ? '<span class="lgk-lej-not">En alt lig — küme düşme yok</span>' : c('rel', '13-16', 'Alt Lige Düşme'));
}

// Puan tablosu HTML — sıra rozeti ve satır bölge renginde
function _lgPuanTablosu(teams, cc, tierIdx, totalTiers, userTeamName) {
  const isTop = tierIdx === 0, isBottom = tierIdx === totalTiers - 1;
  const K = window._ligKolon();
  let h = `<div class="lgk-tb"><div class="lgk-th"><span>#</span><span>${K.t}</span><span>${K.o}</span><span>${K.g}</span><span>${K.b}</span><span>${K.m}</span><span>${K.ay}</span><span>${K.av}</span><span style="color:${LG2_KALKAN_RENK[tierIdx] || '#78909c'}">${K.p}</span></div>`;
  teams.forEach((t, i) => {
    const pos = i + 1, z = getStandingsZone(pos, isTop, isBottom);
    const tip = z === 'normal' ? '' : ' dz';
    const av = t.ag - t.ay;
    h += `<div class="lgk-tr${tip}${t.name === userTeamName ? ' ben' : ''}" data-z="${z}" style="--z:${LG2_BOLGE_RENK[z] || 'transparent'}" onclick="viewTeam('${cc}', '${(t.name || '').replace(/'/g, "\\'")}')">
      <div class="lgk-rk">${pos}</div>
      <div class="lgk-tm">${inlineBadge({ tag: 'div', cls: 'lgk-arma', team: t })}<span>${t.name}</span></div>
      <span class="lgk-n">${t.played}</span><span class="lgk-n">${t.g}</span><span class="lgk-n">${t.b}</span><span class="lgk-n">${t.m}</span>
      <span class="lgk-ay">${t.ag}:${t.ay}</span><span class="lgk-av ${av > 0 ? 'pz' : av < 0 ? 'ng' : 'sif'}">${av > 0 ? '+' + av : av}</span><b class="lgk-pt">${t.pts}</b>
    </div>`;
  });
  return h + `</div><div class="lgk-lej">${_lgLejant(isTop, isBottom)}</div>`;
}

// Takım sayfası (Puan Tablosu sekmesi) için render

// ── Kullanıcının lig bağlamını döndür: hangi ülke, hangi tier (lig kademesi), takım nesnesi vs.
// Kullanıcı takımsızsa null döner (puan durumu/fikstür ziyaretçi mode'da zaten kapalı).
function getUserLeagueContext() {
  if(typeof _userTeam === 'undefined' || !_userTeam || !_userTeam.countryCode) return null;
  const cc = _userTeam.countryCode;
  const country = (true) ? _cftGetCountry(cc) : null;
  if(!country || !country.leagues) return null;

  // Takımı teams DB'de bul, hangi tier'da olduğunu tespit et
  let userTier = 0;
  let userTeamObj = null;
  for(let i = 0; i < country.leagues.length; i++) {
    const t = country.leagues[i].teams.find(x => x.name === _userTeam.teamName);
    if(t) { userTier = i; userTeamObj = t; break; }
  }
  if(!userTeamObj) {
    // Takım teams DB'de bulunamadı → tier 0 fallback
    userTier = 0;
    userTeamObj = country.leagues[0].teams[0];
  }

  return {
    countryCode: cc,
    tierIdx: userTier,
    country,
    leagueName: country.leagues[userTier].name,
    userTeamName: _userTeam.teamName,
    userTeam: userTeamObj,
  };
}

// Kullanıcının lig fikstürü için "FIX_TEAMS uyumlu" 16 takım nesnesi oluştur.
// USR = kullanıcı takımı (FIX_TEAMS.ANK yerine), diğer 15 = LIG_OPP yerine.
// Returns: { user: {...}, opps: [{...}×15] }
function getUserFixTeams() {
  const ctx = getUserLeagueContext();
  if(!ctx) return null;
  const { country, tierIdx, userTeamName } = ctx;
  const teams = country.leagues[tierIdx].teams;

  // Kullanıcı takımı + 15 rakip
  const userT = teams.find(t => t.name === userTeamName) || teams[0];
  const opps  = teams.filter(t => t.name !== userT.name).slice(0, 15);

  // FIX_TEAMS uyumlu obje üret
  const toFix = (t, isUser) => ({
    short: t.short || (t.name||'').slice(0,3).toUpperCase(),
    name: t.name,
    bg: t.bg || 'rgba(255,255,255,.08)',
    tc: t.tc || '#90caf9',
    user: !!isUser,
  });

  return {
    user: toFix(userT, true),
    opps: opps.map(t => toFix(t, false)),
  };
}

function renderTeamLeagueTable() {
  const el = document.getElementById('teamLeagueTableBody');
  if(!el) return;
  const ctx = getUserLeagueContext();
  if(!ctx) return;
  el.innerHTML = _lgPuanTablosu(calcLeagueStandings(ctx.countryCode, ctx.tierIdx), ctx.countryCode, ctx.tierIdx, ctx.country.leagues.length, ctx.userTeamName);
}

// ── Puan tablosu ──
// 🆕 553 — GEÇEN SEZON: Puan sekmesinde "bu sezon / geçen sezonun final tablosu" seçimi.
//   Geçen sezon, o sezonun GERÇEK maç sonuçlarından (match_results) ve o sezonki
//   takımlarla kurulur — yükselen/düşen takımlar kendi yerlerinde görünür.
let _lg2TabloSezon = null;            // null = bu sezon, sayı = geçmiş sezon
const _lg2GecmisCache = {};
function lg2TabloSezonSec(s) { _lg2TabloSezon = (typeof s === 'number') ? s : null; lg2RenderTable(); }
async function _lg2GecmisYukle(cc, tier1, sezon) {
  const k = cc + '|' + tier1 + '|' + sezon;
  if (_lg2GecmisCache[k]) return _lg2GecmisCache[k];
  if (!window.sb) return null;
  const { data, error } = await window.sb.from('match_results')
    .select('home_team,away_team,home_score,away_score')
    .eq('season', sezon).eq('country_code', cc).eq('tier', tier1)
    .is('tournament_key', null).limit(1000);
  if (error) { console.warn('[lig] geçen sezon okunamadı:', error.message); return null; }
  const st = {};
  const ekle = (ad) => {
    if (!st[ad]) {
      const t = (typeof _cftFindTeam === 'function' && _cftFindTeam(cc, ad)) || { name: ad };
      st[ad] = { ...t, name: ad, played: 0, g: 0, b: 0, m: 0, ag: 0, ay: 0, pts: 0 };
    }
    return st[ad];
  };
  for (const r of (data || [])) {
    if (r.home_score == null || r.away_score == null) continue;
    const h = ekle(r.home_team), a = ekle(r.away_team);
    const hs = Number(r.home_score) || 0, as_ = Number(r.away_score) || 0;
    h.played++; a.played++; h.ag += hs; h.ay += as_; a.ag += as_; a.ay += hs;
    if (hs > as_) { h.g++; h.pts += 3; a.m++; }
    else if (hs < as_) { a.g++; a.pts += 3; h.m++; }
    else { h.b++; a.b++; h.pts++; a.pts++; }
  }
  const arr = Object.values(st).map(t => ({ ...t, gd: t.ag - t.ay }))
    .sort((x, y) => (y.pts - x.pts) || (y.gd - x.gd) || (y.ag - x.ag) || String(x.name).localeCompare(String(y.name), 'tr'));
  _lg2GecmisCache[k] = arr;
  return arr;
}
function _lg2SezonSecici(sBu, gecmis) {
  if (sBu < 2) return '';
  const cip = (s, etiket, aktif, hedef) =>
    `<button class="lg2-sz-cip${aktif ? ' aktif' : ''}"${aktif ? '' : ` onclick="lg2TabloSezonSec(${hedef})"`}>`
    + `<span>Sezon</span> <b data-noi18n>${s}</b><span data-noi18n> · </span><span>${etiket}</span></button>`;
  return `<div class="lg2-sz-secici">${cip(sBu, 'Bu sezon', !gecmis, 'null')}${cip(sBu - 1, 'Final tablosu', gecmis, sBu - 1)}</div>`
    + (gecmis ? '<div class="lg2-sz-not">Geçen sezonun son hâli — renkler o sezon kazanılan Avrupa bileti ve küme düşmeyi gösterir.</div>' : '');
}

function lg2RenderTable() {
  const el = document.getElementById('lg2DetailContent');
  if(!el) return;

  const country = _cftGetCountry(_lg2Country);
  if(!country) return;
  const league  = country.leagues[_lg2TierIdx];
  if(!league)   return;

  const totalTiers  = country.leagues.length;
  const tierIdx     = _lg2TierIdx; // 0 = en üst lig

  // 🆕 553 — bu sezon mu, geçen sezonun final tablosu mu?
  const _sBu = (typeof _etkinSezon === 'function') ? _etkinSezon() : getSeasonInfo().season;
  const _gecmis = (typeof _lg2TabloSezon === 'number' && _lg2TabloSezon >= 1 && _lg2TabloSezon < _sBu);
  const _secici = _lg2SezonSecici(_sBu, _gecmis);
  let teams;
  if (_gecmis) {
    const _cc = _lg2Country, _t1 = tierIdx + 1, _sz = _lg2TabloSezon;
    teams = _lg2GecmisCache[_cc + '|' + _t1 + '|' + _sz];
    if (!teams) {
      el.innerHTML = _secici + '<div class="lg-scene-empty" style="padding:30px 10px">Yükleniyor…</div>';
      _lg2GecmisYukle(_cc, _t1, _sz).then(() => {
        if (_lg2Country === _cc && _lg2TierIdx === tierIdx && _lg2TabloSezon === _sz && _lg2ViewTab === 'table') lg2RenderTable();
      });
      return;
    }
    if (!teams.length) {
      el.innerHTML = _secici + '<div class="lg-scene-empty" style="padding:30px 10px">Bu lig için geçen sezon kaydı bulunamadı.</div>';
      return;
    }
  } else {
    // Tüm takımları puan tablosu ile hesapla (ortak fonksiyon)
    teams = calcLeagueStandings(_lg2Country, tierIdx);
  }

  const userTeamName = (typeof _userTeam !== 'undefined' && _userTeam && _userTeam.teamName)
    ? _userTeam.teamName
    : (authUser?.teamName || '');
  el.innerHTML = _secici + _lgPuanTablosu(teams, _lg2Country, tierIdx, totalTiers, userTeamName);
}

// ── Fikstür ──
function lg2RenderFixture() {
  const el = document.getElementById('lg2DetailContent');
  if(!el) return;
  const _rcmY958 = new Set();   // 958 — bu çizimin kart anahtarları

  const country = _cftGetCountry(_lg2Country);
  if(!country) return;
  const league  = country.leagues[_lg2TierIdx];
  if(!league)   return;

  const info = (typeof getSeasonInfo === 'function') ? getSeasonInfo() : { preSeason: false, seasonStart: new Date() };

  // Sezon başlamadıysa placeholder
  if(info.preSeason) {
    el.innerHTML = `<div style="text-align:center;padding:48px 20px;color:var(--text2)">
      <div style="font-size:52px;margin-bottom:14px">⏳</div>
      <div style="font-family:Twemoji Country Flags,'Barlow Condensed',sans-serif;font-size:22px;font-weight:900;color:var(--text);margin-bottom:8px">Fikstür Henüz Hazır Değil</div>
      <div style="font-size:12px;line-height:1.5">Sezon 1 başlangıcına <b>${info.daysToStart||0} gün</b>.<br>Lig fikstürü sezon başında oluşturulacak.</div>
    </div>`;
    return;
  }

  const { season, seasonStart } = info;
  // 🆕 529 — 39. günden itibaren yeni sezon fikstürü gösterilir
  const _fixSezon = (typeof _etkinSezon === 'function') ? _etkinSezon() : season;
  const today    = new Date();
  const DAYS_TR  = ['Paz','Pzt','Sal','Çar','Per','Cum','Cmt'];
  const MONTHS_F = ['Ocak','Şubat','Mart','Nisan','Mayıs','Haziran','Temmuz','Ağustos','Eylül','Ekim','Kasım','Aralık'];
  const MONTHS_S = ['Oca','Şub','Mar','Nis','May','Haz','Tem','Ağu','Eyl','Eki','Kas','Ara'];

  const teams = league.teams;
  const n     = teams.length;
  if(n < 2) {
    el.innerHTML = `<div style="text-align:center;padding:48px 20px;color:var(--text3)">Yetersiz takım sayısı.</div>`;
    return;
  }

  // 🆕 Fikstür kaynağı: match_state cache (Supabase tek doğruluk kaynağı)
  // Eski buildLeagueFixture (lokal hesap) artık kullanılmıyor — saatler/günler yanlış üretiyordu
  const _tier1based = league.tier;  // teams tablosundaki gerçek tier (1-based)
  const _allFromMs = (_matchStateCache && _matchStateCache.byKey) ? Object.values(_matchStateCache.byKey) : [];
  const _filtered = _allFromMs.filter(m => 
    m.countryCode === _lg2Country && 
    m.tier === _tier1based &&
    !m.tournament_key &&
    m.season === _fixSezon       // 🆕 sadece BU sezon (geçmiş sezon maçları karışmasın)
  );
  // 🆕 Cache boşsa async yükle, yüklendikten sonra tekrar render
  if (_allFromMs.length === 0 && typeof _loadAllMatchStateFromServer === 'function' && !window._lg2FixLoadingFlag) {
    window._lg2FixLoadingFlag = true;
    // 956 — yeniden çizimi _msLoadCore içindeki _msRefreshActivePage yapıyor (page-leagues); buradaki dal
    //   yanlış sayfa adına baktığı için hiç çalışmıyordu (düzeltilse iki kez çizer, yükleme hatasında döngüye girerdi)
    _loadAllMatchStateFromServer().then(() => { window._lg2FixLoadingFlag = false; });
  }
  
  // _filtered → fixture formatına çevir (eski koda uyumlu)
  // hafta hesabı: SEASON_TEMPLATE'e göre gün 1-15 = hafta 1-15, gün 19-33 = hafta 16-30
  const _dayToWeek = (d) => (d <= 15) ? d : (d - 3);
  // Aynı hafta içindeki maçları gruplama (match index için)
  const _weekMatches = {};  // { week: [match,...] }
  for (const m of _filtered) {
    const w = _dayToWeek(m.day);
    if (!_weekMatches[w]) _weekMatches[w] = [];
    _weekMatches[w].push(m);
  }
  
  const fixture = [];
  for (const wStr of Object.keys(_weekMatches).sort((a,b) => +a - +b)) {
    const w = +wStr;
    const weekMatches = _weekMatches[w];
    // Bu haftadaki maçları kickoff zamanına göre sırala
    weekMatches.sort((a, b) => new Date(a.matchDateTime).getTime() - new Date(b.matchDateTime).getTime());
    weekMatches.forEach((m, idx) => {
      const homeTeam = teams.find(t => t.name === m.home) || { name: m.home, short: m.homeShort };
      const awayTeam = teams.find(t => t.name === m.away) || { name: m.away, short: m.awayShort };
      const kickoffDate = m.matchDateTime ? new Date(m.matchDateTime) : new Date();
      const _h = String(kickoffDate.getHours()).padStart(2, '0');
      const _mn = String(kickoffDate.getMinutes()).padStart(2, '0');
      fixture.push({
        week: w,
        match: idx + 1,
        date: kickoffDate,
        matchTime: `${_h}:${_mn}`,
        homeTeam,
        awayTeam,
        matchKey: `${m.season}_${m.day}_${m.home}_${m.away}`,
        // Canlı/skor durumu (match_state'ten)
        status: m.status,
        sim_minute: m.sim_minute,
        home_score: m.home_score,
        away_score: m.away_score
      });
    });
  }

  // 🆕 SUPABASE TEK KAYNAK — _matchResultsLoad cache referansı kaldırıldı.
  //   f objesi zaten match_state'ten home_score/away_score/status taşıyor (yukarıda set edildi).

  const matches = fixture.map(f => {
    // Gerçek kickoff zamanı ile maç bitti mi kontrol et
    const _mt = f.matchTime || '15:00';
    const [_hh, _mm] = _mt.split(':').map(n => parseInt(n)||0);
    const _matchKickoff = new Date(f.date);
    _matchKickoff.setHours(_hh, _mm, 0, 0);

    // Status: 'finished' = bitmiş, 'running' = canlı
    const isFinished = (f.status === 'finished');
    const isLive = (f.status === 'running');
    const isPast = isFinished;
    const isToday = f.date.toDateString() === today.toDateString();

    let hs = null, as2 = null, result = null;
    if (isFinished || isLive) {
      hs = (typeof f.home_score === 'number') ? f.home_score : null;
      as2 = (typeof f.away_score === 'number') ? f.away_score : null;
      if (isFinished && hs !== null && as2 !== null) {
        result = hs > as2 ? 'w' : hs < as2 ? 'l' : 'd';
      }
    }

    // Hafta → gün (SEASON_TEMPLATE ile aynı: 1-15 → 1-15, 16-30 → 19-33)
    const dayInSeason = (f.week <= 15) ? f.week : (f.week + 3);

    return {
      week: f.week, match: f.match, date: f.date,
      homeTeam: f.homeTeam, awayTeam: f.awayTeam,
      hs, as: as2, result, isPast, isLive, isToday, dk: f.sim_minute,
      matchTime: f.matchTime,
      dayInSeason
    };
  });

  // Bugünün sezon günü
  const _info = (typeof getSeasonInfo === 'function') ? getSeasonInfo() : { dayInSeason: 1 };
  const _todayDay = _info.dayInSeason || 1;

  // Seçili gün (state'te tut → sekme değiştirip dönüldüğünde korunur)
  if (typeof window._lg2FixSelectedDay !== 'number') {
    window._lg2FixSelectedDay = _todayDay;
  }
  // Eğer seçili gün geçersizse sıfırla
  if (window._lg2FixSelectedDay < 1 || window._lg2FixSelectedDay > SEASON_LEN) {
    window._lg2FixSelectedDay = _todayDay;
  }
  const selectedDay = window._lg2FixSelectedDay;

  // ── TAKVİM: 4 satır × 10 sütun ──
  // 🆕 Özel günler:
  //   16-18: Ara transfer dönemi (kırmızımsı)
  //   34-40: Sezon sonu transfer + EURO Cup (mavimsi)
  function _dayKind(d) {
    if (d >= 16 && d <= 18) return 'transfer-mid';
    if (d >= 34 && d <= 40) return 'season-end';
    return null;
  }

  let calHtml = '<div class="lg2-cal-grid">';
  for (let d = 1; d <= SEASON_LEN; d++) {
    const isPastDay = d < _todayDay;
    const isToday   = d === _todayDay;
    const isFuture  = d > _todayDay;
    const isSel     = d === selectedDay;
    const kind      = _dayKind(d);
    const cls = [
      'lg2-cal-day',
      isPastDay ? 'is-past' : '',
      isToday   ? 'is-today' : '',
      isFuture  ? 'is-future' : '',
      isSel     ? 'is-selected' : '',
      kind      ? `is-${kind}` : ''
    ].filter(Boolean).join(' ');
    calHtml += `<button class="${cls}" data-month="DAY" onclick="lg2SelectFixDay(${d})">
      <span class="lg2-cal-day-n">${d}</span>
    </button>`;
  }
  calHtml += '</div><div class="lgk-cal-lej"><span><i class="bg"></i>Bugün</span><span><i class="sec"></i>Seçili</span><span><i class="ar"></i>Ara transfer</span><span><i class="sn"></i>Sezon sonu</span></div>';

  // ── O günün maçları VEYA özel dönem bilgisi ──
  const selectedKind = _dayKind(selectedDay);
  const dayMatches = matches.filter(m => m.dayInSeason === selectedDay);
  let listHtml = '<div class="lg2-fix-container">';

  if (selectedKind === 'transfer-mid') {
    // Ara transfer dönemi
    listHtml += `
      <div class="lg2-cal-info-card transfer-mid-card">
        <div class="lg2-cal-info-icon">💼</div>
        <div class="lg2-cal-info-title">Ara Dönem</div>
        <div class="lg2-cal-info-sub">Sezon Günü ${selectedDay}</div>
        <div class="lg2-cal-info-text">
          Bu günlerde lig maçları oynanmaz. Kadronu güçlendirmek, sakat veya formdan düşen oyuncularını toparlamak için sezon ortasında iyi bir fırsattır.
        </div>
        <div class="lg2-cal-info-tags">
          <span class="lg2-cal-info-tag">⏸️ Lig Tatili</span>
          <span class="lg2-cal-info-tag">🔄 Kadro Yenileme</span>
        </div>
      </div>
    `;
  } else if (selectedKind === 'season-end') {
    // Sezon sonu transfer + EURO Cup
    listHtml += `
      <div class="lg2-cal-info-card season-end-card">
        <div class="lg2-cal-info-icon">🏆</div>
        <div class="lg2-cal-info-title">Sezon Sonu Dönemi</div>
        <div class="lg2-cal-info-sub">Sezon Günü ${selectedDay}</div>
        <div class="lg2-cal-info-text">
          Lig sezonu sona erdi. Bu dönemde milli takımların katıldığı
          <b>EURO Cup</b> turnuvası başlar.
          Bir sonraki sezon hazırlıkları için kadronu yeniden şekillendirme zamanı.
        </div>
        <div class="lg2-cal-info-tags">
          <span class="lg2-cal-info-tag">${_cupLogoInline('natcup',14)}EURO Cup</span>
          <span class="lg2-cal-info-tag">📋 Yeni Sezon Hazırlığı</span>
        </div>
      </div>
    `;
  } else if (dayMatches.length === 0) {
    listHtml += `<div style="text-align:center;padding:32px 16px;color:var(--text3);font-size:12px">Bu gün maç yok.</div>`;
  } else {
    // Tarih başlığı
    const firstM = dayMatches[0];
    const dateLabel = `${DAYS_TR[firstM.date.getDay()]} ${firstM.date.getDate()} ${MONTHS_F[firstM.date.getMonth()]} ${firstM.date.getFullYear()}`;
    listHtml += `<div class="lg2-fix-month">${dateLabel}${selectedDay === _todayDay ? ' · <span style="color:var(--accent)">Bugün</span>' : ''}</div>`;

    const benimTakim = (typeof _userTeam !== 'undefined' && _userTeam) ? _userTeam.teamName : null;
    dayMatches.forEach(m => {
      let scoreHtml, durum;
      if (m.isLive) {
        durum = 'canli';
        scoreHtml = `<div class="lgk-sc canli"><b>${m.hs ?? 0}–${m.as ?? 0}</b><i>● ${m.dk || 0}'</i></div>`;
      } else if (m.isPast && m.hs !== null) {
        durum = 'bitti';
        scoreHtml = `<div class="lgk-sc"><b>${m.hs}–${m.as}</b></div>`;
      } else {
        durum = 'plan';
        scoreHtml = `<div class="lgk-sc plan">${m.isToday ? '<i class="bg">Bugün</i>' : ''}<b>${m.matchTime || '15:00'}</b></div>`;
      }

      // Biten maç: maç sonu modalı (resOpenFinishedMatch, matchKey ile)
      let cardOnclick = '';
      if (durum === 'bitti') {
        const mk = `${season}_${m.dayInSeason}_${m.homeTeam.name}_${m.awayTeam.name}`;
        if (!window._resCurrentMatches) window._resCurrentMatches = {};
        _rcmY958.add(mk);   // 958
        window._resCurrentMatches[mk] = {
          season: season,
          day: m.dayInSeason,
          home: m.homeTeam.name,
          away: m.awayTeam.name,
          homeShort: m.homeTeam.short || m.homeTeam.name.slice(0,3).toUpperCase(),
          awayShort: m.awayTeam.short || m.awayTeam.name.slice(0,3).toUpperCase(),
          hs: m.hs, as: m.as,
          played: true,
          leagueName: league.name,
          leagueFlag: ''
        };
        cardOnclick = ` onclick="resOpenFinishedMatch('${mk.replace(/'/g, "\\'")}')"`;
      }

      const ben = benimTakim && (m.homeTeam.name === benimTakim || m.awayTeam.name === benimTakim);
      listHtml += `<div class="lgk-mac ${durum}${ben ? ' ben' : ''}${cardOnclick ? ' tik' : ''}"${cardOnclick}>
        <div class="lgk-mac-t"><b>${m.date.getDate()}</b><span>${DAYS_TR[m.date.getDay()]}</span></div>
        <div class="lgk-mac-o">
          <div class="lgk-mac-ust">${_banKalkanImg(_lg2TierIdx, 14)}<span>H${m.week} · M${m.match}</span></div>
          <div class="lgk-mac-tk">
            <div class="lgk-tk">${inlineBadge({tag:'div', cls:'lgk-arma f', team:m.homeTeam})}<span>${m.homeTeam.name}</span></div>
            ${scoreHtml}
            <div class="lgk-tk dep"><span>${m.awayTeam.name}</span>${inlineBadge({tag:'div', cls:'lgk-arma f', team:m.awayTeam})}</div>
          </div>
        </div>
      </div>`;
    });
  }
  listHtml += '</div>';

  el.innerHTML = calHtml + listHtml;
  // 958 — RAM: önceki lig fikstürü çiziminin artık hiçbir kartta olmayan kayıtları silinir
  //   (her lig/gün ziyareti ~10 kayıt ekliyordu; Sonuçlar ve kendi fikstür kartlarının anahtarlarına dokunulmaz)
  try {
    const es = window._rcmLg2958, rc = window._resCurrentMatches;
    if (es && rc) {
      const fx = window._rcmFx958, rs = new Set(window._resClickableMatches || []);
      es.forEach(k => { if (!_rcmY958.has(k) && !(fx && fx.has(k)) && !rs.has(k)) delete rc[k]; });
    }
    window._rcmLg2958 = _rcmY958;
  } catch (e) {}
}

// 🆕 Fikstür takviminden gün seç → re-render (state korunur)
