// 🆕 Supabase player_transfer_listings tablosu
let _tfListCache = null;
let _tfListLoading = null;

async function _tfListLoadFromServer() {
  if (!window.sb) return [];
  try {
    const { data, error } = await window.sb.from('player_transfer_listings')
      .select('*')
      .order('created_at', { ascending: false })
      .limit(500);
    if (error) { console.warn('[tf_list] load hata:', error); return []; }
    try { _tfIlanKanalAc(); } catch (e) {}   // 854 — değişiklikler herkese anında
    return (data || []).map(r => Object.assign({
      id: r.id,
      sellerUserId: r.seller_user_id,
      createdAt: new Date(r.created_at).getTime()
    }, r.data || {}));
  } catch(e) { return []; }
}

// Transfer listesi: Supabase
function getTfList() {
  if (_tfListCache === null) {
    if (!_tfListLoading) {
      _tfListLoading = _tfListLoadFromServer().then(arr => {
        _tfListCache = arr;
        _tfListLoading = null;
        try {
          if (typeof tfRender === 'function' && document.getElementById('page-transfers') && document.getElementById('page-transfers').classList.contains('active')) {
            tfRender();
          }
        } catch(e) {}
      });
    }
    return [];
  }
  return _tfListCache;
}

// 854 — ilanları yalnız sunucu yazar (ilan_ac / ilan_kaldir / satin_al); burada yalnız yerel önbellek
function saveTfList(list) {
  _tfListCache = Array.isArray(list) ? list : [];
}

