function sctTemizle() { if (_sctLider()) _sct.sec = []; else _sct.lig = []; _sctSecimYaz(); }
function _sctSalla() { const k = document.getElementById('sctSecKart'); if (!k) return; k.classList.remove('sct-salla'); void k.offsetWidth; k.classList.add('sct-salla'); }
