  const L = _sctLider(), m = _sctMod();
  if (!L && !_sct.lig.length) { _sctSalla(); rosterToast('Önce aradığın ligi seç.', 'err'); return; }   // 932 — kaptanda mevki isteğe bağlı
  if (_sctBakiye() < s.ucret) { rosterToast(L ? 'Takım kasasında yeterli elmas yok.' : 'Yeterli elmasın yok.', 'err'); return; }
  _sct.mesgul = true;
  const secim = L ? { mevkiler: _sct.sec.slice(), yapi: _sct.yapi } : { ligler: _sct.lig.slice(), ulke: _sct.ulke };
  const istek = edgeCall('scout_tara', {}, { body: { scout: lv, secim } }).then(r => r.data || { error: 'baglanti' }).catch(() => ({ error: 'baglanti' }));
  _sctRadar(s, m, secim);
