  _sct.mesgul = false;
  if (cevap.error) { sctKapat(); rosterToast(_sctHata(cevap), 'err'); return; }
  _sct.rapor = cevap.bos ? { scout: lv, mod: L ? 'oyuncu' : 'takim', secim, sonuc: [], bos: true } : cevap.rapor;
  _sct.durum = {};
