// ═══════════════════════════════════════════════════════════════
//  KATILMA İSTEĞİ — oyuncu bilgisi + orantılı ilk maaş
// ═══════════════════════════════════════════════════════════════

// Maaş günleri ve sezon uzunluğu — tek doğru kaynak
const JR_ODEME_GUNLERI = [10, 20, 30, 40];
const JR_SEZON_GUN = 40;

// İlk maaş orantılıdır: oyuncu sezonun ortasında katılırsa yalnızca
// sahada geçirdiği günlerin karşılığını alır. Katılım günü SAYILIR.
//   15. gün katılan → 20. günde 6 günlük (15,16,17,18,19,20)
//   38. gün katılan → 40. günde 3 günlük, sonra yeni sezon sıfırdan
function jrIlkOdeme(sezonMaasi, katilimGunu) {
  const maas = Number(sezonMaasi) || 0;
  const gun = Number(katilimGunu) || 1;
  const gunluk = maas / JR_SEZON_GUN;
  const odemeGunu = JR_ODEME_GUNLERI.find(g => g >= gun);
  if (odemeGunu == null) return null;                    // sezon bitmiş
  const gunSayisi = odemeGunu - gun + 1;
  return { odemeGunu, gunSayisi, tutar: Math.round(gunluk * gunSayisi) };
}

// Bakılan oyuncunun kadro kartı verisi — `players` herkese açık okunur.
let _jrOyuncuCache = {};
async function _jrOyuncuCek(uid) {
  if (!uid) return null;
  if (Object.prototype.hasOwnProperty.call(_jrOyuncuCache, uid)) return _jrOyuncuCache[uid];
  _jrOyuncuCache[uid] = null;                            // tekrar istek atma
  try {
    if (!window.sb) return null;
    // ⚠️ `market_value` BU TABLODA YOK — o ad takım/ülke tablosuna ait.
    //    Listede bulununca PostgREST tüm sorguyu hata döndürüyor, kod da
    //    catch ile sessizce boş geçiyordu: kartta ne OVR ne yetenek ne
    //    uyruk görünüyordu, "Profili Gör" de aynı fonksiyona bağlı
    //    olduğu için hiçbir şey yapmıyordu.
    const { data, error } = await window.sb.from('players')
      .select('id, num, name, pos, pos_group, sub_pos, ek_mevki, ozel_yetenek, ozel_aktif, nationality, nation, level, xp, overall, rating, abilities, avatar, avatar_id, team_name, country_code, role, is_bot, user_team_data')
      .eq('user_id', uid).maybeSingle();
    if (error) { console.warn('[jr] oyuncu okunamadı:', error.message || error); return null; }
    if (!data) return null;

    // 🆕 AVATAR YEDEĞİ — `players.avatar_id` boş kalabiliyor (eski kayıtlar,
    //    kayıt akışının değiştiği dönemde açılan hesaplar). Avatar seçimi
    //    `profiles` tablosuna da yazılıyor; boşsa oradan tamamlıyoruz.
    //    Yoksa kart, oyuncunun gerçek avatarı yerine mevkiye göre üretilen
    //    yedek emojiyi (sarı kafa) gösteriyordu.
    if (!data.avatar_id) {
      try {
        const { data: pf } = await window.sb.from('profiles')
          .select('avatar_id').eq('id', uid).maybeSingle();
        if (pf && pf.avatar_id) data.avatar_id = pf.avatar_id;
      } catch(e) {}
    }

    _jrOyuncuCache[uid] = data;
    return _jrOyuncuCache[uid];
  } catch(e) { return null; }
}

// Oyuncu adı başkasının girdisi — HTML olarak basılmadan önce kaçırılır
function _jrEsc(x) {
  return String(x == null ? '' : x)
    .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
    .replace(/"/g,'&quot;').replace(/'/g,'&#39;');
}

// "Profili Gör" — DOĞRUDAN oyuncu profil sayfasına geçer.
//   ⚠️ Eskiden `openPlayerModal` açıyordu ve hiçbir şey olmuyor gibi
//   görünüyordu: gelen kutusu perdesi z-index 7000, oyuncu modalı 5500 —
//   modal gelen kutusunun ARKASINDA açılıyordu. Üstelik perde tam opak.
//   Artık gelen kutusu kapatılıyor ve `playerViewProfile` ile doğrudan
//   ziyaretçi profiline geçiliyor (modal adımı yok).
window.jrProfilAc = async function(uid) {
  try {
    const oy = await _jrOyuncuCek(uid);
    if (!oy) {
      console.warn('[jr] profil açılamadı — oyuncu satırı okunamadı:', uid);
      if (typeof tfShowToast === 'function') tfShowToast('❌ Oyuncu bilgisi okunamadı', '#ef5350');
      return;
    }
    const player = {
      name: oy.name, pos: oy.pos, posGroup: oy.pos_group, subPos: oy.sub_pos, ekMevki: oy.ek_mevki || [], oy: oy.ozel_yetenek || [], oyAktif: oy.ozel_aktif,
      nationality: oy.nationality, nation: oy.nation,
      level: oy.level, xp: oy.xp, overall: oy.overall, rating: oy.rating || oy.overall,
      abilities: oy.abilities, avatar: oy.avatar, avatar_id: oy.avatar_id,
      userId: uid, user_id: uid, isBot: !!oy.is_bot, role: oy.role || 'member',
      num: oy.num || 0, id: oy.id || null,
      user_team_data: oy.user_team_data || null
    };
    const ctx = {
      teamName: oy.team_name || 'Serbest',
      countryCode: oy.country_code || oy.nationality || '',
      teamLookupName: oy.team_name || null,
      isOwnTeam: false
    };
    // Gelen kutusunu kapat — yoksa profil sayfası perdenin altında kalır
    try { if (typeof inboxClose === 'function') inboxClose(); } catch(e) {}
    if (typeof playerViewProfile === 'function') {
      await playerViewProfile(JSON.stringify({ player, ctx }));
    } else if (typeof openPlayerModal === 'function') {
      openPlayerModal(player, ctx);
    }
  } catch(e) { console.warn('[jr] profil açılamadı:', e); }
};

// Kaptanın kadro doluluğu — kaç kişi, kaç yabancı
function _jrKadroDurumu() {
  try {
    if (typeof ROSTER_DATA === 'undefined' || !Array.isArray(ROSTER_DATA)) return null;
    const cc = (typeof _userTeam !== 'undefined' && _userTeam) ? _userTeam.countryCode : null;
    const toplam = ROSTER_DATA.length;
    const yabanci = cc ? ROSTER_DATA.filter(p => p && p.nationality && p.nationality !== cc).length : 0;
    const limit = (typeof CFT_FOREIGN_LIMIT !== 'undefined') ? CFT_FOREIGN_LIMIT : 10;
    return { toplam, max: (typeof getMaxRosterSize === 'function') ? getMaxRosterSize() : 15, yabanci, yabanciMax: limit };
  } catch(e) { return null; }
}

function inboxRenderDetail(msg) {
  document.getElementById('inboxDetailTitle').textContent = msg.subject;

  const body = document.getElementById('inboxDetailBody');

  // Ana mesaj — 578: karbon başlık (gönderen kutusu + tarih + konu)
  _gkYanitGizle(false);
  _sohbetBaslik(msg);
  let html = _gkDetayBas(msg);
  // 685 — destek talebi: konuşma balonları + Cevapla / kapandı
  if (typeof _destekCiz === 'function' && _destekCiz(msg, html, body)) return;
  // 578 — para fişi (kâğıt) / maç kartı / düz sistem mesajı (karbon)
  if (_gkOzelGovde(msg, html, body)) return;

  // 🆕 Turnuva bildirimi mi? (kura / sonuç / grup / şampiyon)
  if (msg.trnData) {
    html += `<div class="inbox-detail-text">${_gkE(msg.body).replace(/\n/g,'<br>')}</div>`;
    try { html += _trnMesajKarti(msg.trnData); } catch(e) { console.warn('[trn kart]', e); }
    html += _gkEylemHtml(msg);
    body.innerHTML = html;
    _gkYanitGizle(true);
    try { _trnKartArmalar(body); } catch(e) {}
    return;
  }

  // Transfer teklifi mi?
  if(msg.type === 'contract_renewal_request' && msg.renewalRequest) {
    // 🆕 Kaptana gelen yenileme talebi kartı
    const rr = msg.renewalRequest;
    const _f = v => v>=1000000?(v/1000000).toFixed(2)+'M €':v>0?Math.round(v/1000)+'K €':'0 €';
    const status = rr.status || 'pending';
    const _rrBaska = !!(rr.kararVeren && rr.kararVeren !== ((typeof authUser !== 'undefined' && authUser && authUser.name) || ''));   // 860
    const raiseSign = (rr.raisePercent || 0) >= 0 ? '+' : '';
    html += `<div class="inbox-detail-text">${_gkE(msg.body).replace(/\n/g,'<br>')}</div>
      <div class="inbox-transfer-card">
        <div class="inbox-tc-title">📋 Yenileme Talebi</div>
        <div class="inbox-tc-row"><span class="inbox-tc-label">Oyuncu</span><span class="inbox-tc-val">${rr.playerName||'—'}</span></div>
        <div class="inbox-tc-row"><span class="inbox-tc-label">Mevcut Maaş</span><span class="inbox-tc-val" style="opacity:.7">${_f(rr.oldSalary)}</span></div>
        <div class="inbox-tc-row"><span class="inbox-tc-label">İlk İmza Maaşı</span><span class="inbox-tc-val" style="opacity:.6;font-size:11px">${_f(rr.firstSalary)}</span></div>
        <div class="inbox-tc-row"><span class="inbox-tc-label">Talep Edilen Maaş</span><span class="inbox-tc-val" style="color:var(--accent)">${_f(rr.seasonSalary)} <small style="opacity:.65">(${raiseSign}%${rr.raisePercent})</small></span></div>
        <div class="inbox-tc-row"><span class="inbox-tc-label">Taksit (4× gün 10/20/30/40)</span><span class="inbox-tc-val">${_f(Math.round(rr.seasonSalary/4))}</span></div>
        ${status !== 'pending'
          ? `<div style="margin-top:8px;padding:8px;border-radius:8px;font-size:11px;font-weight:700;text-align:center;background:${status==='accepted'?'rgba(0,230,118,.15)':'rgba(239,83,80,.12)'};color:${status==='accepted'?'var(--accent)':'#ef5350'}">${status==='accepted'?(_rrBaska?'✅ Onaylandı':'✅ Onayladın'):status==='rejected'?(_rrBaska?'❌ Reddedildi':'❌ Reddettin'):'⚠️ Geçersiz'}${_rrBaska ? `<span data-noi18n> · ${_jrEsc(rr.kararVeren)}</span>` : ''}</div>`
          : ''}
      </div>`;
  } else if(msg.type === 'contract_renewal' && msg.renewalData) {
    // 🆕 Sözleşme yenileme bildirimi (oyuncuya gelen) — sistemce hesaplanmış maaş + Talep Gönder butonu
    const rd = msg.renewalData;
    const _f = v => v>=1000000?(v/1000000).toFixed(2)+'M €':v>0?Math.round(v/1000)+'K €':'0 €';
    const status = msg.renewalStatus;
    const raiseSign = (rd.raisePercent || 0) >= 0 ? '+' : '';
    const newSal = rd.seasonSalary || rd.yearlySalary || 0;
    const oldSal = rd.oldSalary || rd.oldYearlySalary || 0;
    const firstSal = rd.firstSalary || oldSal;
    html += `<div class="inbox-detail-text">${_gkE(msg.body).replace(/\n/g,'<br>')}</div>
      <div class="inbox-transfer-card">
        <div class="inbox-tc-title">📋 Sözleşme Yenileme</div>
        <div class="inbox-tc-row"><span class="inbox-tc-label">Mevcut Maaş</span><span class="inbox-tc-val" style="opacity:.7">${_f(oldSal)}</span></div>
        <div class="inbox-tc-row"><span class="inbox-tc-label">İlk İmza Maaşı</span><span class="inbox-tc-val" style="opacity:.6;font-size:11px">${_f(firstSal)}</span></div>
        <div class="inbox-tc-row"><span class="inbox-tc-label">Yeni Sezon Maaşı</span><span class="inbox-tc-val" style="color:var(--accent)">${_f(newSal)} <small style="opacity:.65">(${raiseSign}%${rd.raisePercent})</small></span></div>
        <div class="inbox-tc-row"><span class="inbox-tc-label">Taksit (4× gün 10/20/30/40)</span><span class="inbox-tc-val">${_f(Math.round(newSal/4))}</span></div>
        <div class="inbox-tc-row"><span class="inbox-tc-label">Kalan Gün</span><span class="inbox-tc-val" style="color:#ff9800">${rd.daysLeft} gün</span></div>
        ${status ? `<div style="margin-top:8px;padding:8px;border-radius:8px;font-size:11px;font-weight:700;text-align:center;background:${status==='accepted'?'rgba(0,230,118,.15)':'rgba(239,83,80,.12)'};color:${status==='accepted'?'var(--accent)':'#ef5350'}">
          ${status==='accepted'?'✅ Yenilendi':status==='rejected'?'❌ Reddedildi':'📤 Talep Gönderildi'}
        </div>` :
        ''}
      </div>`;
  } else if(msg.type === 'transfer' && msg.transferData && msg.transferData.tur === 'sozlesme') {
    // 854 — kaptandan sözleşmesiz oyuncuya sözleşme teklifi
    const td = msg.transferData;
    const _f = v => v>=1000000?(v/1000000).toFixed(2)+'M €':v>0?Math.round(v/1000)+'K €':'0 €';
    const maas = Number(td.seasonSalary || td.yearlySalary || 0), sure = Number(td.durationSeasons || 1), imza = Number(td.signingDiamond || 0);
    const durum = msg.offerStatus || 'invalid';   // 963 — sözleşme teklifi kalktı
    html += `<div class="inbox-detail-text">${_gkE(msg.body).replace(/\n/g,'<br>')}</div>
      <div class="inbox-transfer-card">
        <div class="inbox-tc-title">📋 Sözleşme Teklifi</div>
        <div class="inbox-tc-row"><span class="inbox-tc-label">Kulüp</span><span class="inbox-tc-val" data-noi18n>${_jrEsc(td.buyerTeam || '')}</span></div>
        <div class="inbox-tc-row"><span class="inbox-tc-label">Sezon Maaşı</span><span class="inbox-tc-val" data-noi18n>${_f(maas)}</span></div>
        <div class="inbox-tc-row"><span class="inbox-tc-label">Her Taksit (×4/sezon)</span><span class="inbox-tc-val">${_f(Math.round(maas/4))} · gün 10/20/30/40</span></div>
        <div class="inbox-tc-row"><span class="inbox-tc-label">Sözleşme Süresi</span><span class="inbox-tc-val"><span data-noi18n>${sure}</span> <span>sezon</span></span></div>
        ${td.bitisSezon ? `<div class="inbox-tc-row"><span class="inbox-tc-label">Bitiş</span><span class="inbox-tc-val">${Number(td.bitisSezon)}. sezon sonu</span></div>` : ''}
        ${Number(td.signingBonus) > 0 ? `<div class="inbox-tc-row"><span class="inbox-tc-label">İmza Parası € (oyuncuya)</span><span class="inbox-tc-val" style="color:var(--gold)" data-noi18n>${Number(td.signingBonus).toLocaleString('tr-TR')} €</span></div>` : ''}
        <div class="inbox-tc-row" style="border-bottom:none"><span class="inbox-tc-label">İmza Elması (oyuncuya)</span><span class="inbox-tc-val" style="color:var(--accent2)">${imza > 0 ? imza.toLocaleString('tr-TR') + ' 💎' : 'Yok'}</span></div>
        ${durum ? `<div style="margin-top:8px;padding:8px;border-radius:8px;font-size:11px;font-weight:700;text-align:center;background:${durum==='accepted'?'rgba(0,230,118,.15)':'rgba(239,83,80,.12)'};color:${durum==='accepted'?'var(--accent)':'#ef5350'}">${durum==='accepted'?'✅ Kabul Edildi':durum==='invalid'?'⚠️ Geçersiz':durum==='withdrawn'?'↩️ Teklif geri çekildi':'❌ Reddedildi'}</div>`
          : (msg.sent ? '' : `<div class="inbox-tc-actions">
          <button class="inbox-tc-accept" onclick="inboxAcceptTransfer('${msg.id}')">✓ Kabul Et</button>
          <button class="inbox-tc-reject" onclick="inboxRejectTransfer('${msg.id}')">✕ Reddet</button>
        </div>`)}
      </div>`;
  } else if(msg.type === 'transfer' && msg.transferData) {
    const td = msg.transferData;
    function fmtFee(v){ return v>=1000000?(v/1000000).toFixed(2)+'M €':v>0?Math.round(v/1000)+'K €':'Ücretsiz'; }
    function fmtDia(v){ return v>0 ? v.toLocaleString('tr-TR')+' 💎' : 'Yok'; }
    // 🆕 Yeni alanlar (eski format desteği için fallback)
    const transferFee     = td.transferFee     ?? td.fee ?? 0;
    const signingDiamond  = td.signingDiamond  ?? 0;            // 💎 imza parası (€ değil)
    const yearlySalary    = td.yearlySalary    ?? (td.wage ? td.wage * 52 * 1000 : 0);
    const durationSeasons = td.durationSeasons ?? td.contract ?? 1;
    // 889 — sözleşmesiz teklif ve € imza parası
    const _tdSure = td.sozlesmesiz ? '<span>Sözleşmesiz</span>' : `<span data-noi18n>${durationSeasons}</span> <span>sezon</span>`;
    const _tdEur = Number(td.signingBonus) > 0 ? `<div class="inbox-tc-row"><span class="inbox-tc-label">İmza Parası € (oyuncuya)</span><span class="inbox-tc-val" style="color:var(--gold)" data-noi18n>${Number(td.signingBonus).toLocaleString('tr-TR')} €</span></div>` : '';
    // 🔴 KART İKİ TARAFA GÖRE DEĞİŞİR
    //   Aynı mesaj tipi hem alıcıya (gönderdiğim kopya) hem SATAN
    //   kulübün kaptanına düşüyor. Eskiden tek görünüm vardı ve satan
    //   kaptana alıcının maaş yükü ("Yıllık Ücret", "Toplam Sözleşme
    //   Maliyeti") gösteriliyordu — onu ilgilendirmeyen rakamlar.
    //   Ayrıca taksit "×2/sezon" yazıyordu; oyunda maaş 4 taksit
    //   (gün 10/20/30/40). Teklif modalı da 4 taksit gösteriyor.
    const inst = Math.round(yearlySalary / 4);
    const showFee = transferFee > 0;
    // Satıcı mıyım? (mesaj bana geldiyse ve satıcı takım benim takımım)
    const _benimTakim = (typeof _userTeam !== 'undefined' && _userTeam) ? _userTeam.teamName : null;
    const satiyorum = !msg.sent && !td.isFree && !!td.sellerTeam && td.sellerTeam === _benimTakim;   // 846 — kişisel teklif oyuncunun kendisine

    // Oyuncu kartı verisi — `players` tablosundan (herkese açık)
    const _tfUid = td.playerUserId || td.sellerUserId || null;
    const oyT = (_tfUid && _jrOyuncuCache[_tfUid]) || null;
    if (_tfUid && !Object.prototype.hasOwnProperty.call(_jrOyuncuCache, _tfUid)) {
      _jrOyuncuCek(_tfUid).then(r => {
        if (r && _inboxCurrentMsg && _inboxCurrentMsg.id === msg.id) {
          try { inboxRenderDetail(msg); } catch(e) {}
        }
      });
    }
    const tfAv = (typeof getAvatarEmoji === 'function')
      ? (getAvatarEmoji(oyT ? oyT.avatar_id : null, oyT ? oyT.pos : null) || '👤') : '👤';
    const tfMevki = (oyT && (oyT.sub_pos || oyT.pos)) || '—';
    const tfSeviye = (oyT && oyT.level != null) ? oyT.level : '—';
    const tfOvr = oyT ? ((typeof getPlayerMainOverall === 'function')
                  ? getPlayerMainOverall({ ...oyT, role:'member', isBot:false, userId:_tfUid })
                  : (oyT.overall || 10)) : '—';
    const tfBayrak = (oyT && oyT.nation) || '';

    const kdT = satiyorum ? _jrKadroDurumu() : null;
    // 590 — kabul edildiği halde işareti kaybolmuş teklif: oyuncu zaten o takımdaysa buton gösterilmez
    const tfDurum = msg.offerStatus || (satiyorum ? 'invalid' : null) || ((!msg.sent && td.isFree && typeof _userTeam !== 'undefined' && _userTeam
      && _userTeam.teamName === td.buyerTeam && _userTeam.countryCode === td.buyerCountryCode) ? 'accepted' : null);

    html += `<div class="inbox-detail-text">${_gkE(msg.body).replace(/\n/g,'<br>')}</div>
      <div class="inbox-transfer-card">
        <div class="inbox-tc-title">${satiyorum ? '⚽ Oyuncuna Gelen Transfer Teklifi' : '⚽ Transfer Teklifi'}</div>

        <div class="jr-oyuncu">
          <div class="jr-av">${tfAv}</div>
          <div class="jr-ust">
            <div class="jr-ad">${_jrEsc(td.playerName || '')}</div>
            <div class="jr-rozetler">
              <span class="jr-rz jr-rz-pos">${tfMevki}</span>
              <span class="jr-rz jr-rz-lv">Seviye ${tfSeviye}</span>
            </div>
            <div class="jr-uyruk">${tfBayrak} ${satiyorum ? 'senin kadrondan' : (td.sellerTeam || '')}</div>
          </div>
          <div class="jr-ovr"><div class="jr-ovr-n">${tfOvr}</div><div class="jr-ovr-l">OVR</div></div>
        </div>

        ${satiyorum ? `
          ${showFee ? `<div class="tf-kasa-kutu">
            <div class="tf-kasa-l">Bonservis — takım kasasına</div>
            <div class="tf-kasa-n">${fmtFee(transferFee)}</div>
            <div class="tf-kasa-a">Sistem belirledi · kulüp kasasına yatar, cüzdana değil</div>
          </div>` : `<div class="jr-not">Bu oyuncu <b>serbest</b> — bonservis yok.</div>`}
          <div class="inbox-tc-row"><span class="inbox-tc-label">Alıcının Ödeyeceği Maaş</span><span class="inbox-tc-val">${fmtFee(yearlySalary)} /sezon</span></div>
          <div class="inbox-tc-row"><span class="inbox-tc-label">Senin Maaş Yükün</span><span class="inbox-tc-val" style="color:var(--accent)">−${fmtFee(inst)} /taksit</span></div>
          ${kdT ? `<div class="inbox-tc-row"><span class="inbox-tc-label">Kadron</span><span class="inbox-tc-val">${kdT.toplam}/${kdT.max} → <span style="color:#ef9a9a">${kdT.toplam-1}/${kdT.max}</span></span></div>` : ''}
          <div class="jr-not">Kabul edersen bonservis <b>takım kasasına</b> yatar, oyuncu ${_jrEsc(td.buyerTeam || 'alıcı takıma')} kadrosuna geçer ve maaşı artık onların kasasından ödenir.</div>
        ` : `
          ${showFee ? `<div class="inbox-tc-row"><span class="inbox-tc-label">Bonservis ${td.sellerTeam ? '('+_jrEsc(td.sellerTeam)+' kasasına)' : ''}</span><span class="inbox-tc-val" style="color:var(--gold)">${fmtFee(transferFee)}</span></div>` : ''}
          <div class="inbox-tc-row"><span class="inbox-tc-label">Sezon Maaşı</span><span class="inbox-tc-val">${fmtFee(yearlySalary)}</span></div>
          <div class="inbox-tc-row" style="border-bottom:none"><span class="inbox-tc-label">Her Taksit (×4/sezon)</span><span class="inbox-tc-val">${fmtFee(inst)} · gün 10/20/30/40</span></div>
        `}

        ${tfDurum ? `<div style="margin-top:8px;padding:8px;border-radius:8px;font-size:11px;font-weight:700;text-align:center;background:${tfDurum==='accepted'?'rgba(0,230,118,.15)':'rgba(239,83,80,.12)'};color:${tfDurum==='accepted'?'var(--accent)':'#ef5350'}">
          ${tfDurum==='accepted'?'✅ Kabul Edildi':tfDurum==='invalid'?'⚠️ Geçersiz':'❌ Reddedildi'}${msg.kararVeren ? `<span data-noi18n> · ${_jrEsc(msg.kararVeren)}</span>` : ''}
        </div>` :
        (msg.sent ? '' : `<div class="inbox-tc-actions">
          <button class="inbox-tc-accept" onclick="inboxAcceptTransfer('${msg.id}')">${satiyorum ? '✓ Kabul Et, Sat' : '✓ Kabul Et'}</button>
          <button class="inbox-tc-reject" onclick="inboxRejectTransfer('${msg.id}')">✕ Reddet</button>
        </div>
        ${_tfUid ? `<button class="jr-profil-btn" onclick="jrProfilAc('${_tfUid}')">Profili Gör</button>` : ''}`)}
      </div>`;
  } else if (msg.type === 'friendly_response' && msg.friendlyData) {
    // 🆕 Hazırlık maçı cevabı kartı
    const fd = msg.friendlyData;
    const accepted = fd.status === 'accepted';
    const statusColor = accepted ? 'var(--accent)' : '#ef5350';
    const statusBg = accepted ? 'rgba(0,230,118,.15)' : 'rgba(239,83,80,.12)';
    const statusIcon = accepted ? '✅' : '❌';
    const statusText = accepted ? 'KABUL EDİLDİ' : 'REDDEDİLDİ';
    html += `<div class="inbox-detail-text">${_gkE(msg.body).replace(/\n/g,'<br>')}</div>
      <div class="inbox-transfer-card">
        <div class="inbox-tc-title">⚽ Hazırlık Maçı</div>
        <div class="inbox-tc-row" style="align-items:center">
          <span class="inbox-tc-label">Rakip</span>
          <span class="inbox-tc-val" style="display:flex;align-items:center;gap:6px">
            ${inlineBadge({cls:'inbox-opp-mini', name:fd.opponent, bg:fd.opponentBg, tc:fd.opponentTc, short:fd.opponentShort})}
            ${fd.opponent}
          </span>
        </div>
        <div class="inbox-tc-row"><span class="inbox-tc-label">Lig</span><span class="inbox-tc-val">${fd.league}</span></div>
        <div class="inbox-tc-row"><span class="inbox-tc-label">Tarih</span><span class="inbox-tc-val" style="color:var(--accent2)">${fd.dateStr}</span></div>
        <div class="inbox-tc-row"><span class="inbox-tc-label">Saat</span><span class="inbox-tc-val" style="color:var(--accent2)">${fd.timeStr}</span></div>
        <div style="margin-top:8px;padding:9px;border-radius:8px;font-size:12px;font-weight:800;text-align:center;background:${statusBg};color:${statusColor};letter-spacing:.6px">
          ${statusIcon} ${statusText}
        </div>
      </div>`;
  } else if (msg.type === 'join_request_incoming' && msg.joinReqIncomingData) {
    // 🆕 Gelen katılma isteği — kaptan/yardımcı için oyuncu kartı + onay/red
    const d = msg.joinReqIncomingData;
    const fmt = v => v >= 1e6 ? (v/1e6).toFixed(2)+'M €' : v >= 1e3 ? Math.round(v/1e3)+'K €' : v+' €';
    const isApproved = msg.offerStatus === 'approved';
    const isRejected = msg.offerStatus === 'rejected';
    const maas = Number(d.seasonSalary || d.yearlySalary || 0);
    const _jrSozsuz = d.tip === 'sozlesmesiz';   // 859

    // Oyuncunun kadro verisi `players` tablosundan okunur (herkese açık).
    // Mesajın içine gömmüyoruz: mesaj Edge fonksiyonundan geçerken
    // bilinmeyen alanlar elenebiliyor ve kart boş kalıyordu.
    const oy = (d.requestorUserId && _jrOyuncuCache[d.requestorUserId]) || null;
    if (d.requestorUserId && !Object.prototype.hasOwnProperty.call(_jrOyuncuCache, d.requestorUserId)) {
      _jrOyuncuCek(d.requestorUserId).then(r => {
        // Veri geldi → yalnızca AYNI mesaj hâlâ açıksa bir kez yeniden çiz
        if (r && _inboxCurrentMsg && _inboxCurrentMsg.id === msg.id) {
          try { inboxRenderDetail(msg); } catch(e) {}
        }
      });
    }

    // Avatar — oyuncunun seçtiği görsel, yoksa mevkiye göre varsayılan
    let avHtml = '👤';
    try {
      if (typeof getAvatarEmoji === 'function') {
        avHtml = getAvatarEmoji(oy ? oy.avatar_id : null, oy ? oy.pos : null) || '👤';
      }
    } catch(e) {}

    const bayrak = (oy && oy.nation) || '🏳️';
    const uyruk  = (oy && oy.nationality) || '';
    const mevki  = (oy && (oy.sub_pos || oy.pos)) || '—';
    const seviye = (oy && oy.level != null) ? oy.level : '—';
    const ovr    = oy ? ((typeof getPlayerMainOverall === 'function')
                        ? getPlayerMainOverall({ ...oy, role:'member', isBot:false, userId:d.requestorUserId })
                        : (oy.overall || 10)) : '—';
    // Piyasa değeri `players` tablosunda tutulmuyor (yalnız kişinin kendi
    // `user_player` satırında) — başkası okuyamıyor, o yüzden gösterilmiyor.

    // Dört hat ortalaması
    const hatOrt = (grup) => {
      try {
        const ab = oy && oy.abilities && oy.abilities[grup];
        if (!ab || typeof ab !== 'object') return '—';
        const v = Object.values(ab).filter(x => typeof x === 'number');
        return v.length ? Math.round(v.reduce((a,b)=>a+b,0)/v.length) : '—';
      } catch(e) { return '—'; }
    };

    const kd = _jrKadroDurumu();
    const kadroYazi = kd
      ? `${kd.toplam}/${kd.max} · yabancı ${kd.yabanci}/${kd.yabanciMax}`
      : '—';
    const kadroDolu = !!(kd && kd.toplam >= kd.max);

    // İlk maaş orantılı — bugünkü oyun gününe göre
    let bugunGun = 1;
    try { if (typeof getSeasonInfo === 'function') bugunGun = getSeasonInfo().day || 1; } catch(e) {}
    const ilk = jrIlkOdeme(maas, bugunGun);
    const ilkYazi = ilk
      ? `${fmt(ilk.tutar)} — ${ilk.odemeGunu}. günde (${ilk.gunSayisi} günlük)`
      : 'sezon bitti, ilk ödeme yeni sezonda';

    html += `<div class="inbox-detail-text">${_gkE(msg.body).replace(/\n/g,'<br>')}</div>
      <div class="inbox-transfer-card" style="background:rgba(0,230,118,.05);border-color:rgba(0,230,118,.25)">

        <div class="jr-oyuncu">
          <div class="jr-av">${avHtml}</div>
          <div class="jr-ust">
            <div class="jr-ad">${_jrEsc(d.requestorName || '')}</div>
            <div class="jr-rozetler">
              <span class="jr-rz jr-rz-pos">${mevki}</span>
              <span class="jr-rz jr-rz-lv">Seviye ${seviye}</span>
            </div>
            <div class="jr-uyruk">${bayrak} ${uyruk}</div>
          </div>
          <div class="jr-ovr"><div class="jr-ovr-n">${ovr}</div><div class="jr-ovr-l">OVR</div></div>
        </div>

        <div class="jr-hatlar">
          <div><span>KL</span><b>${hatOrt('GK')}</b></div>
          <div><span>DF</span><b>${hatOrt('DEF')}</b></div>
          <div><span>OS</span><b>${hatOrt('MID')}</b></div>
          <div><span>FW</span><b>${hatOrt('FWD')}</b></div>
        </div>

        <div class="inbox-tc-title" style="color:#00e676;margin-top:10px">Önerdiği şartlar</div>
        <div class="inbox-tc-row"><span class="inbox-tc-label">Sezon Maaşı</span><span class="inbox-tc-val">${fmt(maas)}</span></div>
        <div class="inbox-tc-row"><span class="inbox-tc-label">Tam Taksit</span><span class="inbox-tc-val">${fmt(Math.round(maas/4))} × 4 (gün 10/20/30/40)</span></div>
        <div class="inbox-tc-row"><span class="inbox-tc-label">İlk Ödeme</span><span class="inbox-tc-val" style="color:var(--accent2)">${ilkYazi}</span></div>
        <div class="inbox-tc-row" style="border-bottom:none"><span class="inbox-tc-label">Kadro Durumu</span><span class="inbox-tc-val" style="color:${kadroDolu?'#ef5350':'var(--accent)'}">${kadroYazi}</span></div>


        ${(isApproved || isRejected) ?
          `<div style="margin-top:8px;padding:8px;border-radius:8px;font-size:11px;font-weight:700;text-align:center;background:${isApproved?'rgba(0,230,118,.15)':'rgba(239,83,80,.12)'};color:${isApproved?'var(--accent)':'#ef5350'}">
            ${isApproved?'✅ Onaylandı — Takıma katıldı':'❌ Reddedildi'}${msg.kararVeren ? `<span data-noi18n> · ${_jrEsc(msg.kararVeren)}</span>` : ''}
          </div>` :
          `<div class="inbox-tc-actions">
            <button class="inbox-tc-accept" onclick="inboxApproveJoinRequest('${msg.id}')">✓ Onayla</button>
            <button class="inbox-tc-reject" onclick="inboxRejectJoinRequest('${msg.id}')">✕ Reddet</button>
          </div>
          ${d.requestorUserId ? `<button class="jr-profil-btn" onclick="jrProfilAc('${d.requestorUserId}')">Profili Gör</button>` : ''}`}
      </div>`;
  } else if (!(msg.type === 'chat' && (msg.thread||[]).length)) {
    html += `<div class="inbox-detail-text">${_gkE(msg.body).replace(/\n/g,'<br>')}</div>`;
  }
  if (msg.type === 'chat' && msg.thread?.length) {
    html += _sohbetBaloncuk(msg);
  } else if(msg.thread?.length) {
    html += '<div style="margin-top:14px;margin-bottom:6px;font-size:9px;color:var(--text3);text-transform:uppercase;letter-spacing:.5px">Konuşma</div>';
    const myName = (authUser||{}).name || 'Sen';
    const myId   = (authUser||{}).id;
    msg.thread.forEach(t => {
      const isMine = t.fromId ? (t.fromId === myId) : (t.from === myName);
      html += `<div class="inbox-thread-msg ${isMine?'sent':'received'}">
        <div class="inbox-thread-bubble">${_gkE(modFiltre(t.body))}</div>
        <div class="inbox-thread-meta">${_gkE(t.from)} · ${_gkE(t.time)}</div>
      </div>`;
    });
  }

  body.innerHTML = html;
  // 🆕 Layout reflow sonrası garanti scroll (innerHTML hemen scrollHeight güncellemeyebilir)
  requestAnimationFrame(() => {
    body.scrollTop = body.scrollHeight;
    // İkinci frame — bazı tarayıcılarda font/asset yüklenmesi sonrası
    requestAnimationFrame(() => { body.scrollTop = body.scrollHeight; });
  });

  // Transfer mesajlarında yanıt barı göster ama placeholder değiştir
  const replyInput = document.getElementById('inboxReplyInput');
  if(replyInput) replyInput.placeholder = msg.type==='transfer'?'Transfer hakkında yanıtla...':'Yanıtla...';
}

// ── Transfer kabul/red ──
async function inboxAcceptTransfer(msgId) {
  const msgs = getInboxMsgs();
  const idx  = msgs.findIndex(m=>m.id===msgId);
  if(idx===-1) return;

  const td = msgs[idx].transferData;
  if(!td){ tfShowToast('❌ Teklif verisi bozuk', 'var(--red)'); return; }

  // 🆕 TRANSFER DÖNEMİ KONTROLÜ
  // Serbest oyuncu (isFree) → her zaman kabul edilebilir, transfer dönemi gerekmez.
  // Sadece sözleşmeli (kontratlı) oyuncu transferinde dönem kontrolü yapılır.
  const _isContracted = (td.isFree === false) || (td.isFree == null && td.contractStatus === 'active');
  if (_isContracted && typeof _enforceTransferWindow === 'function') {
    const r = _enforceTransferWindow('Sözleşmeli oyuncu transferi');
    if (r.blocked) {
      if (typeof tfShowToast === 'function') tfShowToast('⛔ Transfer dönemi kapalı', 'var(--red)');
      return;
    }
  }

  // 🆕 Yeni alanlar (eski format desteği için fallback)
  const transferFee     = td.transferFee     ?? td.fee ?? 0;
  const signingBonus    = td.signingBonus    ?? 0;
  const yearlySalary    = td.yearlySalary    ?? (td.wage ? td.wage * 52 * 1000 : 0);
  const durationSeasons = td.durationSeasons ?? td.contract ?? 1;
  const fmt = v => v>=1e6 ? (v/1e6).toFixed(2)+'M €' : v>=1e3 ? Math.round(v/1e3)+'K €' : v+' €';

  // Bu mesaj kime ait? Karşı taraf (alıcı kulüp) bonservis + imza parasını ödeyecek.
  // Single-player'da: kullanıcı hem alıcı hem oyuncu konumunda olabilir.
  // Sadeleştirme: kullanıcı (alıcı taraf) kasasından bonservis + imza parası kontrolü.
  // 🆕 2026-08-18 · TRANSFER TAMAMEN SUNUCUDA
  //   Eskiden bonservis+imza kasadan GERÇEKTEN düşüyor, oyuncu taşıma ise
  //   players tetikleyicisi tarafından sessizce geri alınıyordu: para gitti,
  //   oyuncu gelmedi, hata da dönmedi. Ayrıca tutarlar istemcide üretildiği
  //   için 1 € bonservisle yıldız transfer etmek mümkündü.
  //   Artık tek çağrı: tutar doğrulanır, para alıcı kasasından çıkar,
  //   satıcı kasasına girer, oyuncu taşınır. Taşınamazsa para iade edilir.
  tfShowToast('⏳ Transfer işleniyor…', 'var(--text2)');
  let _sonuc = null;
  try {
    const _res = await edgeCall('accept_transfer_offer', { msg: msgId });
    const d = _res && _res.data;
    _sonuc = d;
    if (!_res.ok || !d || d.error) {
      const msg = {
        kasa_yetersiz: 'Kasada yeterli bakiye yok.',
        bonservis_tavani_asildi: 'Bonservis bedeli bu oyuncu için fazla yüksek.',
        imza_tavani_asildi: 'İmza bedeli fazla yüksek.',
        yetki_yok: 'Bu teklifi kabul etme yetkin yok.',
        oyuncu_bulunamadi: 'Oyuncu bulunamadı.',
        oyuncu_belirsiz: 'Aynı isimde birden çok oyuncu var, transfer yapılamadı.',
        teklif_bulunamadi: 'Teklif bulunamadı.',
        oyuncu_tasinamadi_para_iade: 'Oyuncu taşınamadı, ödeme iade edildi.',
        oyuncu_serbest_degil: 'Oyuncu artık serbest değil, başka bir takıma katılmış.',
        transfer_donemi_kapali: 'Transfer dönemi kapalı.',
        teklif_eski: 'Bu teklif eski sürümde gönderildi. Kulüpten yeniden teklif göndermesini iste.',
        teklif_gecersiz: 'Teklif artık geçerli değil (teklifi yapan kulüpten ayrılmış ya da oyuncu takım değiştirmiş).',
        teklif_okunamadi: 'Teklif okunamadı, biraz sonra tekrar dene.',
        sozlesme_aktif: 'Sözleşmen sürüyor; transfer için kulübünün onayı gerekir.',
        yabanci_dolu: 'Alıcı takımın yabancı oyuncu kontenjanı dolu (10/10).',
        kadro_dolu: 'Alıcı takımın kadrosu dolu.',
        teklif_isleniyor: 'Bu teklif zaten işleniyor.',
        kaptan_devretmeli: 'Kaptan transfer olamaz. Önce kaptanlığı bir takım arkadaşına devret.',
        teklif_sozlesmeli: 'Sözleşmen sürüyor; bu kişisel teklif geçersiz.',   // 854
        teklif_geri_cekildi: 'Kulüp bu teklifi geri çekti.',   // 860
        zaten_sozlesmeli: 'Sözleşmen zaten var.'
      }[d && d.error] || ((typeof _mevkiDoluMetin === 'function') && _mevkiDoluMetin(d && d.error, d && d.grup)) || 'Transfer tamamlanamadı.';
      tfShowToast('❌ ' + msg, 'var(--red)');
      // 854 — geçersiz kalan teklifin butonları kalkar
      if (d && ['teklif_sozlesmeli', 'zaten_sozlesmeli', 'teklif_gecersiz', 'teklif_geri_cekildi'].includes(d.error)) {
        const _m = getInboxMsgs().find(m => m && m.id === msgId);
        if (_m) { _m.offerStatus = d.error === 'teklif_geri_cekildi' ? 'withdrawn' : 'invalid'; saveInboxMsgs(getInboxMsgs()); if (_inboxCurrentMsg && _inboxCurrentMsg.id === msgId) inboxRenderDetail(_m); }
      }
      return;
    }
    if (d.zaten_transfer_edildi) {
      tfShowToast('Bu transfer zaten tamamlanmış.', 'var(--text2)');
    }
    // Kasa ve cüzdanı sunucudan tazele — yerel tahmin yok
    try { if (typeof _trsLoadFromServer === 'function') await _trsLoadFromServer(); } catch(e) {}
    try { if (typeof wlLoadFromServer === 'function') await wlLoadFromServer(); } catch(e) {}
  } catch(e) {
    tfShowToast('❌ Sunucuya ulaşılamadı.', 'var(--red)');
    return;
  }

  // 590 — Mesaj HEMEN "kabul edildi" olur (sunucu da işaretledi). Eskiden işaret en sonda,
  //   uzun tazelemelerden sonra eski mesaj dizisine yazılıyordu; arada gelen kutusu sunucudan
  //   yeniden yüklenince kayboluyor, "Kabul Et" butonu mesajda kalıyordu.
  const _kabulIsaretle = () => {
    const _m = getInboxMsgs().find(m => m && m.id === msgId);
    if (_m && _m.offerStatus !== 'accepted') { _m.offerStatus = 'accepted'; saveInboxMsgs(getInboxMsgs()); }
    if (_m && _inboxCurrentMsg && _inboxCurrentMsg.id === msgId) inboxRenderDetail(_m);
  };
  _kabulIsaretle();
  const _amIThePlayer = !!(td.playerUserId && authUser && td.playerUserId === authUser.id) || !!td.isFree;

  // 592 — sözleşmeyi sunucu kurar (accept_transfer_offer); eskiden kabul eden kişinin tarayıcısı
  //   yazıyordu: satıcı kaptan kabul edince sözleşme kaptanın kendi hesabına yazılıyordu.

  // 🆕 players yazımı KALDIRILDI — accept_transfer_offer aksiyonu oyuncuyu
  //   service_role ile zaten taşıdı. Buradaki istemci yazımı tetikleyici
  //   tarafından sessizce geri alınıyordu. Burada sadece ekranı tazeliyoruz.
  try {
    if (_amIThePlayer) {
      const _eskiTk = _takimAnahtar();
      await userTeamLoadFromServer();
      await _takimDurumTazele(_eskiTk);   // 694 — yeni takımın her şeyi sunucudan
    } else if (typeof _userTeam !== 'undefined' && _userTeam && td.buyerCountryCode) {
      if (typeof _rosterRefreshFromServer === 'function') {
        try { await _rosterRefreshFromServer(td.buyerCountryCode); } catch(e){}
      }
      if (typeof renderRoster === 'function') renderRoster('all');
    }
  } catch(e) { console.warn('[transfer] UI tazeleme hata:', e); }

  _kabulIsaretle();   // tazelemeler sırasında kutu sunucudan yeniden yüklendiyse işaret korunur

  // Transfer listesinden oyuncuyu çıkar
  if(td.listingId) {
    const tfList = getTfList().filter(l=>l.id!==td.listingId);
    saveTfList(tfList);
  }

  inboxUpdateBadge();
  if(typeof trsSyncHeader === 'function') trsSyncHeader();

  // 590 — Oyuncu kendisi kabul ettiyse tebrik: forma töreni
  if (_amIThePlayer && _userTeam && _userTeam.teamName) {
    const _sz = (_sonuc && _sonuc.sozlesme) || (_userTeam.contract) || {};
    ktTebrikAc({ takim: _userTeam.teamName, cc: _userTeam.countryCode, num: (_sonuc && _sonuc.num) || _userTeam.num,
                 sure: ((_sonuc && _sonuc.sozlesmesiz) || td.sozlesmesiz) ? 0 : (_sz.durationSeasons || durationSeasons), maas: _sz.seasonSalary || yearlySalary, rol: _userTeam.role || 'member',   // 889
                 sozlesme: td.tur === 'sozlesme' });   // 854
    return;
  }

  let toastMsg = `✅ Transfer kabul edildi! ${td.playerName||'Oyuncu'} → takıma katıldı.`;   // 963
  if(transferFee > 0)  toastMsg += ` Bonservis: ${fmt(transferFee)}`;
  if(signingBonus > 0) toastMsg += ` · İmza: ${fmt(signingBonus)}`;
  tfShowToast(toastMsg, 'var(--accent)');
}

function inboxRejectTransfer(msgId) {
  const msgs = getInboxMsgs();
  const idx  = msgs.findIndex(m=>m.id===msgId);
  if(idx===-1) return;
  msgs[idx].offerStatus = 'rejected';
  saveInboxMsgs(msgs);
  inboxRenderDetail(msgs[idx]);
  inboxUpdateBadge();
  tfShowToast('❌ Teklif reddedildi.', '#ef5350');
  // 854 — ret sunucuya: teklif kapanır (kaptan yeniden önerebilir), sözleşme teklifinde kaptana haber gider
  if (msgs[idx].transferData && !msgs[idx].sent) { try { edgeCall('teklif_red', {}, { body: { msg: msgId } }).catch(() => {}); } catch (e) {} }
}

// ── Yanıt gönder ──
async function inboxSendReply() {
  const input = document.getElementById('inboxReplyInput');
  if(!input || !input.value.trim()) return;
  const body   = modFiltre(input.value.trim());
  const myName = (authUser||{}).name || 'Sen';
  const myId   = (authUser||{}).id;

  const cur = _inboxCurrentMsg;
  if (!cur) return;
  const peerId = cur.peerId || cur.fromUserId;
  if (!peerId) { input.value = ''; return; }   // sohbet değil (sistem mesajı) → gönderme

  const convId   = (cur.id && cur.id.indexOf('dm_') === 0) ? cur.id : _inboxConvId(myId, peerId);
  const peerName = cur.peerName || cur.from || 'Kullanıcı';
  const peerAvId = cur.peerAvatarId || null;
  const item     = { id: _inboxSatirId(), from: myName, fromId: myId, avatarId: (authUser||{}).avatarId || null, body, time: _inboxTimeStr(), ts: Date.now() };   // 910

  const msgs = getInboxMsgs();
  const e = _inboxUpsertChat(msgs, convId, { id: peerId, name: peerName, avatarId: peerAvId }, item, { read: true });
  saveInboxMsgs(msgs);
  _inboxCurrentMsg = e;
  input.value = '';
  inboxRenderDetail(e);
  input.focus();  // 🆕 gönderdikten sonra klavye açık kalsın

  await _inboxDeliverChat(peerId, convId, { id: myId, name: myName, avatarId: (authUser||{}).avatarId||null }, item);
}

// ── Yeni mesaj compose ──
function inboxOpenCompose(toName) {
  inboxShowCompose();
  const inp = document.getElementById('inboxComposeTo');
  if (inp) {
    inp.value = toName || '';
    // 🆕 Hazır alıcı varsa kutu kilitli (profil kartından gelen kişi değişmesin)
    inp.readOnly = !!window._inboxComposeTarget;
  }
  const bodyEl = document.getElementById('inboxComposeBody');
  if (bodyEl) bodyEl.value = '';
  // chip sıfırla
  const chip = document.getElementById('inboxComposeChip');
  if (chip) chip.style.display = 'none';
  // 🆕 Hazır alıcı (profil kartından geldi) varsa username çözme — chip dışarıda set edilir.
  if (window._inboxComposeTarget) return;
  if (toName && typeof _inboxComposeResolveTo === 'function') _inboxComposeResolveTo(toName);
}

// 🆕 Alıcı kutusuna yazılınca avatarlı chip göster (profiles'tan çöz)
let _inboxComposeResolveTimer = null;
async function _inboxComposeResolveTo(val) {
  // Kullanıcı elle yazmaya başladıysa hazır alıcıyı iptal et (username moduna dön)
  window._inboxComposeTarget = null;
  const chip = document.getElementById('inboxComposeChip');
  if (!chip) return;
  const username = String(val || '').replace(/^@+/, '').trim().toLowerCase();
  if (username.length < 2 || !window.sb) { chip.style.display = 'none'; return; }
  clearTimeout(_inboxComposeResolveTimer);
  _inboxComposeResolveTimer = setTimeout(async () => {
    try {
      const { data: prof } = await window.sb.from('profiles')
        .select('id, name, username')
        .ilike('username', username)
        .maybeSingle();
      if (!prof) { chip.style.display = 'none'; return; }
      const { data: _pp } = await window.sb.from('players')
        .select('avatar_id').eq('user_id', prof.id).maybeSingle();
      const _avId = (_pp && _pp.avatar_id) || null;
      const avEl = document.getElementById('inboxComposeChipAv');
      const nmEl = document.getElementById('inboxComposeChipNm');
      if (nmEl) nmEl.textContent = prof.name || ('@' + prof.username);
      if (avEl) {
        const avImg = (typeof getAvatarEmoji === 'function') ? getAvatarEmoji(_avId) : null;
        avEl.innerHTML = (avImg && /<img/.test(avImg)) ? avImg : (avImg || '👤');
      }
      chip.style.display = 'inline-flex';
    } catch(e) { chip.style.display = 'none'; }
  }, 300);
}

async function inboxSendCompose() {
  const toRaw   = document.getElementById('inboxComposeTo').value.trim();
  const body    = modFiltre(document.getElementById('inboxComposeBody').value.trim());
  if(!body) { alert('Mesaj boş olamaz!'); return; }
  if (!window.sb) { alert('Bağlantı yok, sayfayı yenile.'); return; }

  // 🆕 Alıcıyı bul: profil kartından geldiyse hazır hedef, yoksa username çöz
  let toId, toName, toAvatarId;
  if (window._inboxComposeTarget && window._inboxComposeTarget.id) {
    toId = window._inboxComposeTarget.id;
    toName = window._inboxComposeTarget.name || 'Kullanıcı';
    toAvatarId = window._inboxComposeTarget.avatarId || null;
  } else {
    const username = toRaw.replace(/^@+/, '').trim().toLowerCase();
    if (!username) { alert('Geçerli bir kullanıcı adı gir.'); return; }
    const { data: prof, error } = await window.sb.from('profiles')
      .select('id, name, username')
      .ilike('username', username)
      .maybeSingle();
    if (error || !prof) { alert(`Kullanıcı bulunamadı: @${username}`); return; }
    toId = prof.id;
    toName = prof.name || ('@' + prof.username);
    const { data: _pp } = await window.sb.from('players').select('avatar_id').eq('user_id', prof.id).maybeSingle();
    toAvatarId = (_pp && _pp.avatar_id) || null;
  }

  // Kendine gönderme engeli
  if (authUser && toId === authUser.id) { alert('Kendine mesaj gönderemezsin.'); return; }

  const myName = (authUser||{}).name || 'Sen';
  const myId   = (authUser||{}).id;
  const convId = _inboxConvId(myId, toId);
  const item   = { id: _inboxSatirId(), from: myName, fromId: myId, avatarId: (authUser||{}).avatarId || null, body, time: _inboxTimeStr(), ts: Date.now() };   // 910

  // Alıcının sohbetine ekle (gerçek teslim) — karşı tarafın gözünde ben'in avatarı
  const ok = await _inboxDeliverChat(toId, convId, { id: myId, name: myName, avatarId: (authUser||{}).avatarId||null }, item);
  if (!ok) { alert('Mesaj gönderilemedi.'); return; }

  // Kendi sohbetime ekle — benim gözümde peer'in avatarı
  const msgs = getInboxMsgs();
  const e = _inboxUpsertChat(msgs, convId, { id: toId, name: toName, avatarId: toAvatarId }, item, { read: true });
  saveInboxMsgs(msgs);

  window._inboxComposeTarget = null; // hedefi temizle
  // 🆕 Gönderdikten sonra sohbeti aç (devam edebilsin)
  _inboxCurrentMsg = e;
  inboxOpenMsg(e.id);
  inboxUpdateBadge();
  tfShowToast(`✅ Gönderildi: ${toName}`, 'var(--accent2)');
}

// ── Transfer teklifi → Inbox mesajı ──
// 🆕 Yeni offer yapısı: offer.transferFee, offer.signingBonus, offer.yearlySalary, offer.durationSeasons
async function inboxSendTransferOffer(target, _legacyWage, _legacyContract, offer) {
  function fmtEur(v){ return v>=1000000?(v/1000000).toFixed(2)+'M €':v>0?Math.round(v/1000)+'K €':'Ücretsiz'; }
  function fmtDia(v){ return v>0 ? v.toLocaleString('tr-TR') + ' 💎' : '—'; }
  const myName = (authUser||{}).name || 'Teklif Yapan';
  const now    = new Date().toLocaleDateString('tr');
  // 🆕 Transfer teklifleri KİŞİ değil TAKIM adından görünür (Artvin Yönetimi gibi).
  //   Teklifi sunan kullanıcının takım adı + bayrağı.
  let _myTeamName = myName; // fallback: takımsızsa kişi adı
  try {
    if (typeof _userTeam !== 'undefined' && _userTeam && _userTeam.teamName) {
      const _fl = (typeof ccToFlag === 'function' && _userTeam.countryCode) ? ccToFlag(_userTeam.countryCode) + ' ' : '';
      _myTeamName = _fl + _userTeam.teamName;
    }
  } catch(e) {}

  // External (profil modal'ından gelen) teklif: kontrat durumuna göre farklı format
  const isExternal = !!target._external;
  const isFree     = isExternal && (target._contractStatus === 'free' || target._contractStatus === 'none');   // 846 — sözleşmesiz üye de
  const _sozsuz    = isExternal && target._contractStatus === 'none';
  const isActive   = isExternal && target._contractStatus === 'active';

  // 🆕 Yeni offer yapısı (eski yapı backward compat ile)
  const transferFee    = offer.transferFee     ?? offer.fee ?? target.fee ?? 0;
  const signingDiamond = offer.signingDiamond  ?? 0;                  // 💎
  const seasonSalary   = offer.seasonSalary    ?? offer.yearlySalary
                          ?? (_legacyWage ? _legacyWage * 52 * 1000 : 0);
  const inst           = Math.round(seasonSalary / 4);                 // 4 taksit (gün 10/20/30/40)
  const signingBonus    = Math.max(0, Number(offer.signingBonus) || 0);   // 889 — € imza parası (oyuncu cüzdanına)
  const sozlesmesiz     = !!offer.sozlesmesiz;                           // 889
  const yearlySalary    = seasonSalary;               // backward-compat alias
  const durationSeasons = offer.durationSeasons ?? 1;

  // Şart bloğu — yeni 4-taksit yapısı
  const termsBlock = [
    isFree ? null : `• Bonservis: ${fmtEur(transferFee)} (${target.seller||'satıcı kulüp'} kasasına)`,
    `• Sezonluk Maaş: ${fmtEur(seasonSalary)} (4 taksit, gün 10/20/30/40)`,
    `   ↳ Her taksit: ${fmtEur(inst)}`,
    signingDiamond > 0 ? `• İmza Parası: ${fmtDia(signingDiamond)} (oyuncu elmas cüzdanına)` : null,
    signingBonus > 0 ? `• İmza Parası: ${signingBonus.toLocaleString('tr-TR')} € (oyuncu cüzdanına)` : null,
  ].filter(Boolean).join('\n');

  // Subject ve body external durumlara göre özelleştir
  let incomingSubject, incomingBody, sentSubject, sentBody;
  if(isFree) {
    // Boşta — doğrudan oyuncuya kişisel teklif (bonservis yok)
    incomingSubject = `Kişisel Teklif — ${target.playerId}`;
    incomingBody = `${_myTeamName} sana doğrudan kişisel bir transfer teklifi sundu.\n\n${termsBlock}\n\n`   // 963
      + `Kulüp onayı gerekmiyor — kabul edersen takıma katılırsın${_sozsuz ? ' ve şimdiki takımından ayrılırsın' : ''}.`;
    sentSubject = `Teklif Gönderildi — ${target.playerId}`;
    sentBody = `${target.playerId} adlı oyuncuya kişisel teklif gönderdin.\n\n${termsBlock}`;
  } else if(isActive) {
    // Aktif kontrat — önce kulübe (takım liderine) resmi teklif
    incomingSubject = `Resmi Transfer Teklifi — ${target.playerId}`;
    incomingBody = `${_myTeamName}, oyuncumuz ${target.playerId} için kulübümüze resmi bir transfer teklifi sundu.\n\nKontrat Durumu: ${target._contractLabel || 'Aktif'}\n${termsBlock}\n\nKulüp yönetimi olarak teklifi değerlendirip oyuncu ile görüşme izni verip vermeyeceğimize karar vereceğiz.`;
    sentSubject = `Resmi Teklif — ${target.playerId} (${target.seller})`;
    sentBody = `${target.seller} kulübüne ${target.playerId} için resmi transfer teklifi gönderdin.\nKulüp onay verirse oyuncu ile kişisel görüşmeye geçebilirsin.\n\n${termsBlock}`;
  } else {
    // 🆕 LEGACY DALI — Pazar yeri (transfer listesi) artık bu yola uğramıyor.
    console.warn('[inboxSendTransferOffer] Beklenmeyen non-external çağrı — pazar yeri artık tfConfirmPurchase kullanır.');
    incomingSubject = `Transfer Bildirimi — ${target.playerId}`;
    incomingBody = `${_myTeamName} ${target.playerId} ile ilgili bir bildirim gönderdi.\n\n${termsBlock}`;
    sentSubject = `Bildirim Gönderildi — ${target.playerId}`;
    sentBody = `${target.seller} adlı oyuncuya bildirim gönderdin.\n\n${termsBlock}`;
  }

  // Satıcıya/kulübe gelen mesaj
  const incomingMsg = {
    id: 'tf_msg_'+Date.now(),
    from: _myTeamName,
    fromAvatar: '⚽',
    type: 'transfer',
    subject: incomingSubject,
    body: incomingBody,
    time: now,
    read: false,
    thread: [],
    transferData: {
      playerName:      target.playerId,
      // 🆕 Yeni alanlar
      transferFee,
      signingBonus,
      signingDiamond,
      yearlySalary,
      durationSeasons,
      sozlesmesiz,   // 889
      // Backward compat
      fee:      transferFee,
      wage:     _legacyWage || Math.round(yearlySalary / 52000),
      contract: durationSeasons,
      listingId: target.id,
      offerId:   offer.id,
      external:  isExternal,
      contractStatus: target._contractStatus || null,
      sellerTeam:     target.seller || null,
      // 🆕 Transfer gerçekleştirme bilgileri (kabul edilince oyuncu buraya gider)
      playerDbId:       target._playerDbId || null,
      // 🆕 Oyuncunun hesap kimliği — satan kaptanın kartında avatar/OVR
      //    `players` tablosundan bununla çekiliyor.
      playerUserId:     (target._playerRef && (target._playerRef.userId || target._playerRef.user_id)) || null,
      sellerCountryCode: target._countryCode || null,
      buyerTeam:        target._buyerTeam || null,
      buyerCountryCode: target._buyerCountryCode || null,
      buyerUserId:      target._buyerUserId || null,
      isFree:           isFree,
    },
  };

  // Benim gönderdiğim kopyası (sent)
  const sentMsg = {
    id: 'tf_sent_'+Date.now(),
    from: myName,
    to: target.seller,
    fromAvatar: '⚽',
    type: 'transfer',
    subject: sentSubject,
    body: sentBody,
    time: now,
    read: true,
    thread: [],
    sent: true,
    transferData: {
      playerName: target.playerId,
      transferFee, signingBonus, yearlySalary, durationSeasons, sozlesmesiz,
      fee: transferFee, wage: _legacyWage || 0, contract: durationSeasons,
      external: isExternal,
      contractStatus: target._contractStatus || null,
    },
  };

  // 🆕 Teklifi GERÇEK alıcının sunucu inbox'una teslim et
  //   Serbest oyuncu → doğrudan oyuncuya · Kontratlı → satıcı kulüp kaptanına (860 — üye oyuncuysa yardımcılara da)
  let recipientId = null, _ekAlicilar = [];
  if (isFree) {
    const pr = target._playerRef || {};
    recipientId = pr.userId || pr.user_id || null;
    if (!recipientId && target._countryCode && target.seller && typeof _teamRosterCache !== 'undefined') {
      const roster = _teamRosterCache[target._countryCode + ':' + target.seller];
      if (Array.isArray(roster)) {
        const c = roster.find(r => r && r.name === target.playerId);
        if (c) recipientId = c.userId || c.user_id || null;
      }
    }
    // 846 — hâlâ bulunamadıysa sunucudan (oyuncu kimliği ya da ad + takım)
    if (!recipientId && window.sb && target.playerId) {
      try {
        let q = window.sb.from('players').select('user_id');
        if (target._playerDbId) q = q.eq('id', target._playerDbId);
        else {
          q = q.eq('name', target.playerId).eq('is_bot', false);
          q = (_sozsuz && target.seller && target._countryCode) ? q.eq('team_name', target.seller).eq('country_code', target._countryCode) : q.is('team_name', null);
        }
        const { data: _al } = await q.limit(2);
        if (Array.isArray(_al) && _al.length === 1) recipientId = _al[0].user_id || null;
      } catch (e) {}
    }
  } else {
    if (typeof _loadRealCaptainsFromServer === 'function') {
      _invalidateRealCaptainsCache();
      await _loadRealCaptainsFromServer(target._countryCode || undefined);
    }
    const entry = _realCaptainsCache[(target._countryCode||'') + ':' + (target.seller||'')];
    recipientId = entry ? entry.captainUserId : null;
    // 860 — üye oyuncu için teklif yardımcı kaptanlara da gider; ilk karar geçerli (sunucu diğer kopyaları kapatır)
    const _rf = target._playerRef || {};
    if (recipientId && _rf.role !== 'vice' && _rf.role !== 'captain') {
      try { _ekAlicilar = (await _k860Yardimcilar(target._countryCode, target.seller)).filter(u => u && u !== recipientId); } catch (e) {}
    }
  }
  if (!recipientId || typeof inboxSendToUser !== 'function') {
    console.warn('[teklif] alıcı user_id çözülemedi — teslim edilemedi:', target.playerId);
    return false;
  }
  const _ok = await inboxSendToUser(recipientId, incomingMsg);
  if (!_ok) return false;
  for (const _u of _ekAlicilar) { try { await inboxSendToUser(_u, JSON.parse(JSON.stringify(incomingMsg))); } catch (e) {} }   // 860
  // Gönderenin kendi kutusuna "gönderildi" kopyası — yalnız teklif ulaştıysa (846)
  const msgs = getInboxMsgs();
  msgs.unshift(sentMsg);
  saveInboxMsgs(msgs);
  inboxUpdateBadge();
  return true;
}



