  for (let i = 0; i < ed.length; i++) { const a = i === 0 ? ana : ed[i - 1]; const [x1, y1] = _GL_XY[a], [x2, y2] = _GL_XY[ed[i]]; cizgi += `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${i ? '#ffd600' : '#29b6ff'}" stroke-width="1.6" opacity=".9"/>`; }
  const yz = (x, y, b, r, k) => `<text x="${x}" y="${(y + b * .37).toFixed(1)}" text-anchor="middle" font-family="Barlow Condensed,sans-serif" font-weight="900" font-size="${b}" fill="${r}">${k}</text>`;
