// ═══════════════════════════════════════
//   TAKIM KASASI (TEAM TREASURY)
// ═══════════════════════════════════════
// Kasa verisi Supabase team_data tablosunda tutulur (data_key='treasury' ve 'treasury_log')
// localStorage anahtarları sadece temizlik için tanımlı (legacy cleanup)
const TRS_KEY     = 'cft_treasury';     // legacy - cleanup için tanımlı
const TRS_LOG_KEY = 'cft_treasury_log'; // legacy - cleanup için tanımlı

// Yeni kullanıcı başlangıcı: kasa boş (takım yokken kasa anlamsız).
// Takım satın alındığında kalkış sermayesi otomatik enjekte edilir.
// Hem euro hem elmas tutar — kullanıcı bağışıyla doldurulur, ödüllerle dolar.
const TRS_DEFAULT = { eur: 0, dia: 0, totalIn: 0, totalOut: 0, donCount: 0 };

let _trsDonateType = 'eur'; // 'eur' | 'dia' — kullanıcı seçer

// 🆕 RAM cache - bootstrap'ta server'dan doldurulur
let _trsCache = null;
let _trsLogCache = null;
let _trsSaveTimer = null;
let _trsLogSaveTimer = null;

// Server'dan kasa verisini yükle (bootstrap ve takım değişimi sonrası)
async function _trsLoadFromServer(toplu) {
  if (!window.sb || !_userTeam || !_userTeam.countryCode || !_userTeam.teamName) {
    _trsCache = null;
    _trsLogCache = null;
    return;
  }
  try {
    const _t956 = toplu && _tdTopluAl956(_userTeam.countryCode, _userTeam.teamName, ['treasury', 'treasury_log']);   // 956 — ortak team_data yanıtı
    const { data, error } = _t956 ? await _t956 : await window.sb.from('team_data')
      .select('data_key, data')
      .eq('country_code', _userTeam.countryCode)
      .eq('team_name', _userTeam.teamName)
      .in('data_key', ['treasury', 'treasury_log']);
    if (error) { console.warn('[treasury] load hata:', error); return; }
    _trsCache = null;
    _trsLogCache = null;
    for (const row of (data || [])) {
      if (row.data_key === 'treasury') _trsCache = row.data;
      else if (row.data_key === 'treasury_log') _trsLogCache = row.data;
    }
  } catch(e) { console.warn('[treasury] load hata:', e); }
}

// 🆕 ATOMİK KASA — istemci optimistic (anlık UI) + sunucu RPC (delta, satır kilidi).
//   Eski 'tüm objeyi upsert' yöntemi sunucu yazımlarını (maç ödülü vb.) eziyordu.
//   Artık delta gönderiyoruz; dönüşte _trsCache sunucu otoriter değeriyle eşitlenir.
function _trsApplyLocal(d_eur, d_dia, kind, source){
  const c = Object.assign({}, TRS_DEFAULT, _trsCache || {});
  c.eur = (Number(c.eur)||0) + (d_eur||0);
  c.dia = (Number(c.dia)||0) + (d_dia||0);
  const amt = Math.abs(d_eur||0) + Math.abs(d_dia||0);
  if(kind==='in') c.totalIn = (Number(c.totalIn)||0) + amt;
  else if(kind==='out') c.totalOut = (Number(c.totalOut)||0) + amt;
  _trsCache = c;
  if(source){
    const entry = {ts:Date.now(), type:(kind==='out'?'out':'in'), cur:((d_dia&&!d_eur)?'dia':'eur'), amount:amt, source};
    if(Array.isArray(_trsLogCache)) _trsLogCache.unshift(entry); else _trsLogCache=[entry];
  }
  if(typeof trsSyncHeader==='function') trsSyncHeader();
}

function _trsRpcApply(d_eur, d_dia, kind, source, extra){
  if(!window.sb || !_userTeam || !_userTeam.countryCode || !_userTeam.teamName) return;
  // 🔒 597 — Takım kasası tarayıcıdan artık yalnız HARCANABİLİR (kasa_harca).
  //   team_treasury_apply sunucuya kapatıldı: eskiden herkes konsoldan HERHANGİ bir takımın
  //   kasasına para ekleyebiliyor ya da başka takımın kasasını boşaltabiliyordu.
  //   Takım ve yetki (kaptan/yardımcı) sunucuda bulunur; istemciden takım adı gitmez.
  //   Gelirler (maç, ödül, transfer, devralma sermayesi) zaten sunucuda yazılıyor.
  if ((Number(d_eur)||0) >= 0 && (Number(d_dia)||0) >= 0) {
    if (typeof _trsLoadFromServer === 'function') _trsLoadFromServer().then(()=>{ if(typeof trsRender==='function') trsRender(); if(typeof trsSyncHeader==='function') trsSyncHeader(); });
    return;
  }
  window.sb.rpc('kasa_harca', { p_eur:d_eur||0, p_dia:d_dia||0, p_kaynak: source ? String(source).slice(0, 80) : null })
    .then(({data,error})=>{
      if(error){ console.warn('[treasury] rpc hata:', error); }
      if(data && data.ok && data.treasury){
        _trsCache = data.treasury;
        if(typeof trsRender==='function') trsRender();
        if(typeof trsSyncHeader==='function') trsSyncHeader();
      } else if(typeof _trsLoadFromServer==='function'){
        _trsLoadFromServer().then(()=>{ if(typeof trsRender==='function') trsRender(); if(typeof trsSyncHeader==='function') trsSyncHeader(); });
      }
    }).catch(e=>console.warn('[treasury] rpc hata:', e));
}

function trsGetData(){
  if (_trsCache) return Object.assign({}, TRS_DEFAULT, _trsCache);
  return Object.assign({}, TRS_DEFAULT);
}

function trsSaveData(d){
  // RAM cache anında güncelle
  _trsCache = Object.assign({}, _trsCache || {}, d);
  // 🔒 TAKIM KASASI İSTEMCİDEN YAZILMAZ.
  //   Kasa hareketleri sunucudaki team_treasury_apply RPC'si ile yapılır.
  //   Burada yalnızca ekran önbelleği tutulur.
  if (false && window.sb && _userTeam && _userTeam.countryCode && _userTeam.teamName) {
    clearTimeout(_trsSaveTimer);
    _trsSaveTimer = setTimeout(async () => {
      try {
        await window.sb.from('team_data').upsert({
          country_code: _userTeam.countryCode,
          team_name: _userTeam.teamName,
          data_key: 'treasury',
          data: _trsCache,
          updated_at: new Date().toISOString()
        }, { onConflict: 'country_code,team_name,data_key' });
      } catch(e) { console.warn('[treasury] save hata:', e); }
    }, 500);
  }
  // Header senkronizasyonu — her kayıt sonrası DOM güncelle
  trsSyncHeader();
}

// ── Header senkronizasyonu ──
// money-display ve diamond-display her zaman cft_treasury'den okur.
function trsSyncHeader() {
  // Header'daki tüm para göstergeleri ARTIK CÜZDANDAN okunur (kasadan değil).
  // Bu fonksiyon backward-compat için kalır; gerçek iş wlSyncHeader'da yapılır.
  try {
    if(typeof wlSyncHeader === 'function') wlSyncHeader();
  } catch(e) {}
}


// 🆕 Kasa: içinde bulunulan sezonun zaman aralığı [başlangıç, bitiş) — ms
function _trsSeasonRange() {
  try {
    const info = (typeof getSeasonInfo === 'function') ? getSeasonInfo() : null;
    const sN = (info && info.season) || 1;
    if (typeof _seasonRangeMs === 'function') return _seasonRangeMs(sN);
    if (info && info.seasonStart) {
      const st = new Date(info.seasonStart).getTime();
      const len = (typeof SEASON_LEN !== 'undefined' ? SEASON_LEN : 40) * 86400000;
      return [st, st + len];
    }
  } catch(e) {}
  return [0, Infinity];
}

// 🆕 Hesap hareketleri modalı (bütçe/elmas kutusuna tıklayınca)
function trsOpenLogModal(cur) {
  window._trslCur = (cur === 'dia') ? 'dia' : 'eur';
  const ov = document.getElementById('trsLogOverlay');
  if (!ov) return;
  trsRenderLogModal();
  ov.classList.add('open');
  try { document.body.style.overflow = 'hidden'; } catch(e) {}
}
function trsCloseLogModal() {
  const ov = document.getElementById('trsLogOverlay');
  if (ov) ov.classList.remove('open');
  try { document.body.style.overflow = ''; } catch(e) {}
}
function trsRenderLogModal() {
  const cur = window._trslCur || 'eur';
  const isDia = cur === 'dia';
  const body = document.getElementById('trslBody');
  if (!body) return;
  let sN = 1;
  try { sN = (getSeasonInfo().season) || 1; } catch(e) {}
  const [sStart, sEnd] = _trsSeasonRange();

  const icEl = document.getElementById('trslIcon');
  if (icEl) icEl.textContent = isDia ? '💎' : '💶';
  const tEl = document.getElementById('trslTitle');
  if (tEl) tEl.textContent = isDia ? 'Elmas Hareketleri' : 'Bütçe Hareketleri';
  const sEl = document.getElementById('trslSub');
  if (sEl) sEl.textContent = 'Sezon ' + sN + ' · en yeni üstte';

  const all = (typeof trsGetLog === 'function' ? trsGetLog() : []).filter(e => e && e.cur === cur);
  const thisSeason = all.filter(e => typeof e.ts === 'number' && e.ts >= sStart && e.ts < sEnd);
  const older = all.filter(e => typeof e.ts === 'number' && e.ts < sStart);

  // Özet
  let sumIn = 0, sumOut = 0;
  thisSeason.forEach(e => {
    if (e.type === 'in' || e.type === 'don') sumIn += (e.amount || 0);
    else sumOut += (e.amount || 0);
  });
  const unit = isDia ? '' : ' €';
  const inEl = document.getElementById('trslIn');
  if (inEl) inEl.textContent = '+' + sumIn.toLocaleString('tr') + unit;
  const outEl = document.getElementById('trslOut');
  if (outEl) outEl.textContent = '−' + sumOut.toLocaleString('tr') + unit;

  // Devir: bu sezon başındaki bakiye = güncel bakiye − bu sezonun net hareketi
  let bal = 0;
  try {
    const d = (typeof trsGetData === 'function') ? trsGetData() : {};
    bal = isDia ? (Number(d.dia) || 0) : (Number(d.eur) || 0);
  } catch(e) {}
  const carry = bal - (sumIn - sumOut);

  const fmtDT = (ts) => {
    const dt = new Date(ts);
    return dt.toLocaleDateString('tr', { day: '2-digit', month: 'short', year: 'numeric' }) +
           ' · ' + dt.toLocaleTimeString('tr', { hour: '2-digit', minute: '2-digit' });
  };
  const rowHtml = (e) => {
    const isIn = (e.type === 'in' || e.type === 'don');
    const cls = e.type === 'don' ? 'don' : (isIn ? 'in' : 'out');
    const ico = e.type === 'don' ? '🤝' : (isIn ? '▲' : '▼');
    const amt = (isIn ? '+' : '−') + (e.amount || 0).toLocaleString('tr') + unit;
    const by = e.by ? ' · ' + e.by : '';
    return `<div class="trsl-row">
      <div class="trsl-ic ${cls}">${ico}</div>
      <div class="trsl-inf"><div class="t">${(e.source || 'İşlem')}${by}</div><div class="m">${fmtDT(e.ts)}</div></div>
      <div class="trsl-amt ${isIn ? 'in' : 'out'}">${amt}</div>
    </div>`;
  };

  let h = '';
  // En üstte bu sezon (en yeni önce)
  h += '<div class="trsl-sec">Sezon ' + sN + '</div>';
  if (thisSeason.length) {
    h += thisSeason.slice().sort((a, b) => (b.ts || 0) - (a.ts || 0)).map(rowHtml).join('');
  } else {
    h += '<div class="trsl-empty">Bu sezon henüz işlem yok.</div>';
  }

  // Devir satırı
  h += '<div class="trsl-sec">Sezon Başı</div>';
  h += `<div class="trsl-row">
      <div class="trsl-ic carry">↪</div>
      <div class="trsl-inf"><div class="t">Önceki sezondan devir</div><div class="m">${isFinite(sStart) && sStart > 0 ? fmtDT(sStart) : '—'}</div></div>
      <div class="trsl-amt carry">${carry.toLocaleString('tr')}${unit}</div>
    </div>`;

  // Önceki sezonların hareketleri
  if (older.length) {
    h += '<div class="trsl-sec">Önceki Sezonlar</div>';
    h += older.slice().sort((a, b) => (b.ts || 0) - (a.ts || 0)).slice(0, 60).map(rowHtml).join('');
  }

  body.innerHTML = h;
}
// ESC ile kapat
document.addEventListener('keydown', function(e) {
  if (e.key === 'Escape') {
    const o = document.getElementById('trsLogOverlay');
    if (o && o.classList.contains('open')) trsCloseLogModal();
  }
});

function trsGetLog(){
  return Array.isArray(_trsLogCache) ? _trsLogCache : [];
}

function trsSaveLog(log){
  // Sadece son 100 işlemi tut
  const trimmed = log.slice(0, 100);
  _trsLogCache = trimmed;
  // 597 — Kasa günlüğünü yalnız sunucu yazar (team_treasury_apply); burada ekran önbelleği.
  if (false && window.sb && _userTeam && _userTeam.countryCode && _userTeam.teamName) {
    clearTimeout(_trsLogSaveTimer);
    _trsLogSaveTimer = setTimeout(async () => {
      try {
        await window.sb.from('team_data').upsert({
          country_code: _userTeam.countryCode,
          team_name: _userTeam.teamName,
          data_key: 'treasury_log',
          data: trimmed,
          updated_at: new Date().toISOString()
        }, { onConflict: 'country_code,team_name,data_key' });
      } catch(e) { console.warn('[treasury_log] save hata:', e); }
    }, 500);
  }
}

function trsAddLog(entry){
  const log = trsGetLog();
  log.unshift(Object.assign({ts: Date.now()}, entry));
  trsSaveLog(log);
}

// ── Public API: diğer modüller tarafından çağrılır ──

// Gelir ekle (maç ödülü, lig/turnuva ödülü vs.)
// 'dia' → kişisel cüzdan, 'eur' → takım kasası
function trsAddIncome(currency, amount, source){
  if(!amount || amount<=0) return;
  if(currency==='dia'){
    // Elmas → cüzdana
    wlAddDia(amount, source);
    return;
  }
  // Euro → takım kasası: 597 — gelirleri sunucu yazar (maç geliri, ödüller);
  //   burada yalnız gerçek bakiye sunucudan tazelenir (eskiden aynı ödül bir de tarayıcıdan yazılıyordu).
  setTimeout(() => { try { _trsRpcApply(0, 0, 'in', source||'Gelir'); } catch(e) {} }, 1500);
}

// Gider düş (transfer, tesis, mağaza vs.). Yeterli bakiye yoksa false döner.
// 'dia' → kişisel cüzdandan, 'eur' → takım kasasından
function trsDeduct(currency, amount, reason){
  if(!amount || amount<=0) return false;
  if(currency==='dia'){
    // Elmas → cüzdandan düş
    return wlDeductDia(amount, reason);
  }
  // Euro → takım kasasından (ATOMİK RPC delta; yerelde ön kontrol, kesin kontrol sunucuda)
  const d = trsGetData();
  if((Number(d.eur)||0) < amount) return false;
  _trsApplyLocal(-amount, 0, 'out', reason||'Gider');
  _trsRpcApply(-amount, 0, 'out', reason||'Gider');
  trsRender();
  return true;
}

// Bakiye kontrolü (transfer öncesi)
// 'dia' → cüzdana bakar, 'eur' → kasaya bakar
function trsCanAfford(currency, amount){
  if(currency==='dia') return wlCanAffordDia(amount);
  const d = trsGetData();
  return d.eur >= amount;
}

function trsGetBalance(currency){
  if(currency==='dia') return wlGetBalance();
  const d = trsGetData();
  return d.eur;
}

// 🆕 KASA-Diamond helper'ları — `trs*('dia')` cüzdana yönleniyor (legacy).
// Bu fonksiyonlar GERÇEK takım kasasına erişir. Tesis yükseltme gibi
// "takım giderleri" buradan ödenir.
function trsTreasuryDiaBalance(){
  const d = trsGetData();
  return d.dia || 0;
}

function trsTreasuryDiaCanAfford(amount){
  const d = trsGetData();
  return (d.dia || 0) >= amount;
}

function trsTreasuryDiaDeduct(amount, reason){
  if(!amount || amount<=0) return false;
  const d = trsGetData();
  if((Number(d.dia) || 0) < amount) return false;
  // ATOMİK RPC delta (kasadan elmas düş)
  _trsApplyLocal(0, -amount, 'out', reason||'Gider');
  _trsRpcApply(0, -amount, 'out', reason||'Gider');
  if(typeof trsRender === 'function') trsRender();
  return true;
}

// ── UI ──
