function trsUpdateMyBalance(){
  // Cüzdandan seçilen para birimini göster (donate UI için)
  const bal = (typeof wlGetBalance === 'function') ? wlGetBalance(_trsDonateType) : 0;
  const el = document.getElementById('trsMyBalance');
  if(!el) return;
  el.textContent = _trsDonateType==='dia'
    ? bal.toLocaleString('tr') + ' 💎'
    : bal.toLocaleString('tr') + ' €';
}

// 934e — takım kasasına bağış 10. seviyeden itibaren
const BAGIS_MIN_SEVIYE = 10;
function _bagisSeviye() {
  try {
    if (window._userProgressCache && typeof window._userProgressCache.level === 'number') return window._userProgressCache.level;
    const me = (typeof ROSTER_DATA !== 'undefined') ? ROSTER_DATA.find(p => p.role === 'user' && !p.isBot) : null;
    if (me && typeof me.level === 'number') return me.level;
  } catch (e) {}
  return null;
}
function _bagisKilitli() { const sv = _bagisSeviye(); return sv !== null && sv < BAGIS_MIN_SEVIYE; }
function _bagisKilitCiz() {
  const b = document.querySelector('#team-treasury .trs-donate-btn'); if (!b) return;
  const k = _bagisKilitli();
  if (b.classList.contains('kilit') === k && b.dataset.c) return;
  b.dataset.c = '1';
  b.classList.toggle('kilit', k); b.disabled = k;
  if (b.parentElement) b.parentElement.classList.toggle('kilit', k);
  b.innerHTML = k ? '<svg viewBox="0 0 24 24"><rect x="5" y="11" width="14" height="10" rx="2"/><path d="M8 11V7a4 4 0 0 1 8 0v4"/></svg><span>10. seviye gerekli</span>' : 'Bağışla';
}

// Bağış: cüzdandan kasaya transfer (€ veya 💎)
function trsDonate(){
  const amtEl = document.getElementById('trsDonateAmount');
  const amount = parseInt(amtEl?.value||'0')||0;
  const cur = _trsDonateType; // 'eur' | 'dia'

  if(amount<=0){ trsToast('Geçerli bir tutar gir.', 'var(--red)'); return; }

  // Takım kontrolü: bağış yapmak için kasanın olması lazım (= takım sahibi olmalı)
  if(typeof _userTeam !== 'undefined' && !_userTeam){
    trsToast('Önce bir takıma sahip olmalısın.', 'var(--red)');
    return;
  }

  // 934e — herkes bağış yapabilir; 10. seviye şartı (kaptan / yardımcı dahil). Kesin karar sunucuda (kasa_bagis).
  if(_bagisKilitli()){ trsToast('Bağış için 10. seviye gerekli.', 'var(--red)'); return; }

  // Cüzdan bakiyesi yeterli mi?
  if(!wlCanAfford(cur, amount)){
    const lbl = cur==='dia' ? 'elmas' : 'euro';
    trsToast(`Cüzdanında yeterli ${lbl} yok.`, 'var(--red)');
    return;
  }

  // 597 — Bağış TEK sunucu işlemi: cüzdandan düşme + kasaya ekleme birlikte (biri olmazsa hiçbiri).
  //   Takım ve yetki sunucuda bulunur (kasa_bagis).
  if (!window.sb) { trsToast('Bağış yapılamadı.', 'var(--red)'); return; }
  const _eur = cur==='eur'?amount:0, _dia = cur==='dia'?amount:0;
  _wlApplyLocal(-_eur, -_dia, 'out');
  _trsApplyLocal(_eur, _dia, 'in', 'Bağış');
  window.sb.rpc('kasa_bagis', { p_eur:_eur, p_dia:_dia }).then(({data,error})=>{
    if (!error && data && data.ok) {
      const w = data.cuzdan || {};
      _wlCache = { eur:Number(w.eur)||0, dia:Number(w.dia)||0, total_in:Number(w.total_in)||0, total_out:Number(w.total_out)||0,
                   totalIn:Number(w.total_in)||0, totalOut:Number(w.total_out)||0, ..._wlKp(w) };   // 941
      if (data.treasury) _trsCache = data.treasury;
      try { _wlGunlukOnbellek = null; } catch(e) {}
      if(typeof wlSyncHeader==='function') wlSyncHeader();
      trsRender();
      if(cur==='eur'){
        trsToast(`🤝 ${amount.toLocaleString('tr')} € kasaya bağışlandı!`, 'var(--accent)');
      } else {
        trsToast(`🤝 ${amount.toLocaleString('tr')} 💎 kasaya bağışlandı!`, 'var(--accent2)');
      }
      return;
    }
    const kod = (data && data.error) || (error && error.message) || '';
    const mesaj = kod === 'seviye_yetersiz' ? 'Bağış için 10. seviye gerekli.'
                : kod === 'yetki_yok' ? '🔒 Sadece kaptan ve yardımcı kaptan bağış yapabilir.'
                : kod === 'insufficient' ? (cur==='dia' ? 'Cüzdanında yeterli elmas yok.' : 'Cüzdanında yeterli euro yok.')
                : kod === 'takim_yok' ? 'Önce bir takıma sahip olmalısın.'
                : 'Bağış yapılamadı.';
    trsToast(mesaj, 'var(--red)');
    try { if (typeof wlLoadFromServer === 'function') wlLoadFromServer().then(()=>{ if(typeof wlSyncHeader==='function') wlSyncHeader(); }); } catch(e) {}
    try { if (typeof _trsLoadFromServer === 'function') _trsLoadFromServer().then(()=>{ trsRender(); if(typeof trsSyncHeader==='function') trsSyncHeader(); }); } catch(e) {}
  }).catch(e => { console.warn('[bağış]', e); trsToast('Bağış yapılamadı.', 'var(--red)'); });

  // Etkinlik: bağış sayacı
  try{
    if(typeof evRefreshBadge === 'function') evRefreshBadge();
  }catch(e){}

  amtEl.value = '';
  trsRender();
}

