// ═══ 913 — KAPTANLAR (Kaptan Puanı · Kupa Sayısı) ═══
//   Sunucu kaptan_puan tablosunu 30 dakikada bir yazar; burada yalnız okunur (ilk 100, 60 sn önbellek).
let _rkKaptanMod = 'puan', _rkKaptanSeq = 0;
function rkSetKaptanMod(mod){
  _rkKaptanMod = mod === 'kupa' ? 'kupa' : 'puan';
  const a = document.getElementById('rkKaptanModPuan'), b = document.getElementById('rkKaptanModKupa');
  if(a) a.classList.toggle('active', _rkKaptanMod === 'puan');
  if(b) b.classList.toggle('active', _rkKaptanMod === 'kupa');
  rkRenderCaptains();
}
const _rkKpE = x => String(x == null ? '' : x).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function _rkKaptanAc(i){
  const k = (window._rkKaptanlar || [])[i];
  if(!k || typeof openPlayerModal !== 'function') return;
  openPlayerModal({ name: k.ad, userId: k.user_id, user_id: k.user_id, role: 'captain', isBot: false }, { countryCode: k.cc || '', teamName: k.takim || '' });
}
function _rkKaptanYeniden(){   // 922
  const rows = window._rkKaptanlar, list = document.getElementById('rkCaptainsList');
  if(!list || _rkActiveTab !== 'captains' || !Array.isArray(rows) || !rows.length) return;
  const ben = (typeof authUser !== 'undefined' && authUser && authUser.id) || null;
  if(_rkSearchActive){ list.innerHTML = '<div class="lst-list">' + rows.map(k => rkCaptainRow(k, '·', k.user_id === ben, false)).join('') + '</div>'; return; }
  const ust = rows.filter(k => k._rank), html = _rkKursuListe(ust, (k, i, kz) => rkCaptainRow(k, i + 1, k.user_id === ben, kz));
  list.innerHTML = html;
  const c = _rkListCache['captains|' + _rkKaptanMod]; if(c) c.html = html;
}
function rkCaptainRow(k, rank, isMe, kz){
  const kupaMod = _rkKaptanMod === 'kupa';
  const deger = kupaMod ? (k.kupa || 0) : (k.puan || 0);
  const birim = kupaMod ? 'kupa' : 'puan';
  const c = (typeof _cftGetCountry === 'function' && _cftGetCountry(k.cc)) || {};
  const v = k.takim ? _rkTeamVisuals(k.cc, k.takim) : {};
  if(k.user_id && !isMe && !(k.user_id in _cnYarisAv)) _oyAvIste([k.user_id], _rkKaptanYeniden);
  const benUy = isMe ? ((((typeof ROSTER_DATA !== 'undefined' && ROSTER_DATA) || []).find(r => r && r.role === 'user') || {}).nation || (window.authUser && authUser.nationality ? ccToFlag(authUser.nationality) : '')) : '';
  const avId = isMe ? _evMyAv() : (_cnYarisAv[k.user_id] || ''), bay = benUy || _oyUyr[k.user_id] || c.flag || '';
  const tk = _rkTk('', k.takim || null, k.cc, v.bg, v.tc, v.short, c.flag, c.name);
  const tik = `onclick="_rkKaptanAc(${k._i})" style="cursor:pointer"`;
  if(kz){
    return `<div class="rk-kz rk-kz${rank} ist-rk ${isMe?'is-user':''}" ${tik}>
      <div class="rk-kz-m">${rank}</div>
      <div class="rk-kz-ar">${_rkAv(avId, rank === 1 ? 'p1' : 'p', bay)}</div>
      <div class="rk-kz-ad ${isMe?'user-mark':''}"><span data-noi18n>${_rkKpE(k.ad)}</span></div>
      <div class="rk-kz-alt ist-tk">${tk}</div>
      <div class="rk-kz-v" data-noi18n>${deger.toLocaleString('tr')}</div>
      <div class="rk-kz-b">${birim}</div>
      <div class="rk-kz-alt2"></div>
    </div>`;
  }
  return `<div class="lst-row ist-rk ${isMe?'is-user':''}" ${tik}>
    <div class="lst-rank ${(typeof _rankClass === 'function') ? _rankClass(rank) : rkNumCls(rank)}">${rank}</div>
    ${_rkAv(avId, 'b')}
    <div class="lst-info-col">
      <div class="lst-pname ${isMe?'user-mark':''}"><span class="ist-bay">${bay}</span><span class="ist-nm" data-noi18n>${_rkKpE(k.ad)}</span></div>
      <div class="lst-psub ist-tk">${tk}</div>
    </div>
    <div>
      <div class="lst-stat-val ${rank<=3?'gold':''}" data-noi18n>${deger.toLocaleString('tr')}</div>
      <div class="lst-stat-unit">${birim}</div>
    </div>
  </div>`;
}
async function rkRenderCaptains(){
  const list = document.getElementById('rkCaptainsList'), meEl = document.getElementById('rkCaptainMe');
  if(!list) return;
  if(_rkSearchActive){ rkRenderSearch(); return; }
  const key = 'captains|' + _rkKaptanMod, cached = _rkListCache[key];
  if(cached && (Date.now() - cached.at) < _RK_LIST_TTL){ list.innerHTML = cached.html; if(meEl) meEl.innerHTML = cached.meHtml || ''; window._rkKaptanlar = cached.rows; return; }
  if(!window.sb){ if(!cached) list.innerHTML = '<div class="lst-empty"><div class="lst-empty-icon">⚠️</div>Bağlantı yok</div>'; return; }
  if(cached){ list.innerHTML = cached.html; if(meEl) meEl.innerHTML = cached.meHtml || ''; }
  else list.innerHTML = '<div class="lst-empty"><div class="lst-empty-icon">⏳</div>Sıralama yükleniyor…</div>';
  const seq = ++_rkKaptanSeq, kupaMod = _rkKaptanMod === 'kupa';
  let rows = null;
  try{
    let q = window.sb.from('kaptan_puan').select('user_id, ad, cc, takim, puan, kupa, kupa_puan');
    q = kupaMod ? q.gt('kupa', 0).order('kupa', { ascending: false }).order('kupa_puan', { ascending: false }).order('puan', { ascending: false })
                : q.order('puan', { ascending: false });
    const { data, error } = await q.limit(100);
    if(!error && Array.isArray(data)) rows = data;
  }catch(e){}
  if(seq !== _rkKaptanSeq || _rkActiveTab !== 'captains') return;
  if(!rows){ if(!cached) list.innerHTML = '<div class="lst-empty"><div class="lst-empty-icon">⚠️</div>Yüklenemedi — sekmeye tekrar dokun</div>'; return; }
  const ben = (typeof authUser !== 'undefined' && authUser && authUser.id) || null;
  rows.forEach((k, i) => { k._i = i; k._rank = i + 1; });
  window._rkKaptanlar = rows;
  const html = rows.length ? _rkKursuListe(rows, (k, i, kz) => rkCaptainRow(k, i + 1, k.user_id === ben, kz))
    : '<div class="lst-empty"><div class="lst-empty-icon">🏆</div>Henüz sıralamada kaptan yok</div>';
  list.innerHTML = html;
  // Kendi sıran (listede yoksa)
  let meHtml = '';
  if(ben && !rows.some(k => k.user_id === ben)){
    try{
      const { data: m } = await window.sb.from('kaptan_puan').select('user_id, ad, cc, takim, puan, kupa, kupa_puan').eq('user_id', ben).maybeSingle();
      if(m && (!kupaMod || m.kupa > 0)){
        const { count } = await window.sb.from('kaptan_puan').select('user_id', { count: 'exact', head: true }).gt(kupaMod ? 'kupa' : 'puan', kupaMod ? m.kupa : m.puan);
        m._i = rows.length; rows.push(m); window._rkKaptanlar = rows;
        meHtml = '<div class="lst-list" style="margin-top:8px">' + rkCaptainRow(m, (count || 0) + 1, true, false) + '</div>';
      }
    }catch(e){}
  }
  if(seq !== _rkKaptanSeq || _rkActiveTab !== 'captains') return;
  if(meEl) meEl.innerHTML = meHtml;
  _rkListCache[key] = { html, meHtml, rows, at: Date.now() };
}
async function _rkSearchCaptainsServer(q){
  const el = document.getElementById('rkCaptainsList'); if(!el || !window.sb) return;
  let rows = [];
  try{
    const { data } = await window.sb.from('kaptan_puan').select('user_id, ad, cc, takim, puan, kupa, kupa_puan')
      .ilike('ad', '%' + q.replace(/[%_,()]/g, '') + '%').order(_rkKaptanMod === 'kupa' ? 'kupa' : 'puan', { ascending: false }).limit(30);
    rows = Array.isArray(data) ? data : [];
  }catch(e){}
  if(_rkActiveTab !== 'captains' || !_rkSearchActive) return;
  const ben = (typeof authUser !== 'undefined' && authUser && authUser.id) || null;
  rows.forEach((k, i) => { k._i = i; });
  window._rkKaptanlar = rows;
  el.innerHTML = rows.length ? '<div class="lst-list">' + rows.map(k => rkCaptainRow(k, '·', k.user_id === ben, false)).join('') + '</div>'
    : '<div class="lst-empty"><div class="lst-empty-icon">🔍</div>Eşleşen sonuç yok</div>';
  const me = document.getElementById('rkCaptainMe'); if(me) me.innerHTML = '';
}

// ── Takım satırı ──
function rkTeamRow(t, rank, isMe, kz){
  const isMarket = _rkTeamMode === 'market';
  const score = isMarket ? _carFmtEUR(t.mv||0) : (_rkTeamMode === 'coef' ? (Number(t.cf)||0).toFixed(2) : (t.o||0));
  const isZero = _rkTeamMode === 'coef' && (t.cf||0)===0;
  // Coef sıralamasında 0 puanlı (Avrupa dışı) takımlara özel görsel
  const scoreStyle = isZero ? 'opacity:.4' : '';
  const unit = isMarket ? 'piyasa değeri' : (_rkTeamMode === 'coef' ? 'puan' : 'yetenek');
  // Tıklanabilirlik: countryCode varsa viewTeam'e yönlendir
  const cc = t.countryCode || '';
  const clickAttr = cc ? `onclick="viewTeam('${cc}', '${(t.n||'').replace(/'/g, "\\'")}')" style="cursor:pointer"` : '';
  // Takım logosu (Lig sayfasıyla aynı görsel — bg/tc/short)
  const teamBg = t.bg || '#444';
  const teamTc = t.tc || '#fff';
  const teamShort = t.short || (t.n||'').slice(0,3).toUpperCase();

  if(kz){   // 822 — kürsü kartı
    return `<div class="rk-kz rk-kz${rank} ${isMe?'is-user':''}" ${clickAttr}>
      <div class="rk-kz-m">${rank}</div>
      <div class="rk-kz-ar">${inlineBadge({tag:'div', cls:'lst-team-logo', name:t.n, cc:t.countryCode, bg:teamBg, tc:teamTc, short:teamShort})}</div>
      <div class="rk-kz-ad ${isMe?'user-mark':''}"><span>${t.n}</span></div>
      <div class="rk-kz-alt">${t.f} ${t.cn} · ${t.lg}</div>
      <div class="rk-kz-v${String(score).length > 5 ? ' uzun' : ''}" style="${scoreStyle}">${score}</div>
      <div class="rk-kz-b">${unit}</div>
      <div class="rk-kz-yz">${_yzHtml(t.o, 't')}</div>
      <div class="rk-kz-alt2">${cc ? _bgnMini('takim', cc + '|' + t.n) : ''}</div>
    </div>`;
  }
  // Lig sayfasındaki _statRowHtml ve oyuncu sıralamasındaki rkPlayerRow ile AYNI yapı
  return `<div class="lst-row ${isMe?'is-user':''}" ${clickAttr}>
    <div class="lst-rank ${(typeof _rankClass === 'function') ? _rankClass(rank) : rkNumCls(rank)}">${rank}</div>
    ${inlineBadge({tag:'div', cls:'lst-team-logo', name:t.n, cc:t.countryCode, bg:teamBg, tc:teamTc, short:teamShort})}
    <div class="lst-info-col">
      <div class="lst-pname ${isMe?'user-mark':''}">${t.n}</div>
      <div class="lst-psub">${t.f} ${t.cn} · ${t.lg}${cc ? _bgnMini('takim', cc + '|' + t.n) : ''}</div>
    </div>
    <div>
      <div class="lst-stat-val ${rank<=3 && !isZero?'gold':''}" style="${scoreStyle}">${score}</div>
      <div class="lst-stat-unit">${unit}</div>
      <div class="lst-yz">${_yzHtml(t.o, 't')}</div>
    </div>
  </div>`;
}

// ── Render: Takımlar ──
// ── Render: Takımlar ── (🆕 tek hafif top-50 sorgusu; tüm tablo taraması YOK)
// 🆕 Sıralama liste cache'i — hızlı sekme/sayfa geçişleri yeniden SORGULAMASIN.
let _rkListCache = {};        // key → { html, meHtml, mapped, at }
let _rkTeamsSeq = 0;
let _rkPlayersSeq = 0;
const _RK_LIST_TTL = 60000;   // 60sn taze say

async function rkRenderTeams(){
  const list = document.getElementById('rkTeamsList');
  const meEl = document.getElementById('rkTeamMe');
  if(!list) return;
  if(_rkSearchActive){ rkRenderSearch(); return; }
  const key = 'teams|' + _rkTeamMode;
  const cached = _rkListCache[key];
  // Taze cache → ANINDA göster, sorgu YOK
  if(cached && (Date.now()-cached.at) < _RK_LIST_TTL){
    list.innerHTML = cached.html;
    if(meEl) meEl.innerHTML = cached.meHtml || '';
    window.RK_TOP_TEAMS = cached.mapped || [];
    return;
  }
  if(!window.sb){ if(!cached) list.innerHTML='<div class="lst-empty"><div class="lst-empty-icon">⚠️</div>Bağlantı yok</div>'; return; }
  const col = (_rkTeamMode==='market') ? 'market_value' : (_rkTeamMode==='coef' ? 'team_points' : 'team_ovr');
  // Eski içerik varsa koru (boş ekran/flicker yok); yoksa spinner
  if(cached){ list.innerHTML = cached.html; if(meEl) meEl.innerHTML = cached.meHtml||''; }
  else { list.innerHTML = '<div class="lst-empty"><div class="lst-empty-icon">⏳</div>Sıralama yükleniyor…</div>'; }
  const seq = ++_rkTeamsSeq;
  let rows=[], ok=false;
  try{
    const { data, error } = await window.sb.from('teams')
      .select('country_code, name, team_ovr, team_points, market_value')
      .order(col, { ascending:false, nullsFirst:false })
      .limit(50);
    if(!error && Array.isArray(data)){ rows=data; ok=true; }
    else if(error) console.warn('[rkTeams] sorgu:', error);
  }catch(e){ console.warn('[rkTeams] exception:', e); }
  if(seq!==_rkTeamsSeq) return;          // daha yeni render başladı
  if(_rkActiveTab!=='teams') return;     // sekme değişti
  if(!ok){ if(!cached) list.innerHTML='<div class="lst-empty"><div class="lst-empty-icon">⚠️</div>Yüklenemedi — sekmeye tekrar dokun</div>'; return; }
  const myCC=(typeof _userTeam!=='undefined'&&_userTeam)?_userTeam.countryCode:null;
  const myName=(typeof _userTeam!=='undefined'&&_userTeam)?_userTeam.teamName:null;
  const mapped = rows.map(r=>{
    const v=_rkTeamVisuals(r.country_code, r.name);
    return {
      n:r.name, countryCode:r.country_code, f:v.flag, cn:v.countryName, lg:v.leagueName,
      o:Math.round(Number(r.team_ovr)||0), cf:Number(r.team_points)||0, mv:Number(r.market_value)||0,
      bg:v.bg, tc:v.tc, short:v.short,
      _isMe: !!(myCC && myName && r.country_code===myCC && r.name===myName),
    };
  });
  // 🆕 Kendi takımın: gösterilen piyasa değeri = kadrodaki oyuncuların TOPLAMI (hero ile birebir).
  //    Botlar zaten teams.market_value = oyuncu toplamı; tek istisna kullanıcı takımı (oyuncusu skills/abilities farkı).
  try {
    const _me = mapped.find(t=>t._isMe);
    if(_me && typeof calculateTeamValue==='function'){
      const _v = calculateTeamValue({ name:_me.n, countryCode:_me.countryCode });
      if(_v>0) _me.mv = _v;
    }
  } catch(e){}
  window.RK_TOP_TEAMS = mapped;
  const html = _rkKursuListe(mapped, (t,i,kz)=>rkTeamRow(t,i+1,!!t._isMe,kz));   // 822
  list.innerHTML = html;
  let meHtml = '';
  try { meHtml = await _rkRenderTeamMe(col, mapped); } catch(e){}
  _rkListCache[key] = { html, meHtml: meHtml||'', mapped, at: Date.now() };
}

// "Senin takımın" alt paneli — top-50 dışındaysa ucuz sayım sorgusuyla sıra
async function _rkRenderTeamMe(col, top50){
  const meEl=document.getElementById('rkTeamMe');
  if(!(typeof _userTeam!=='undefined' && _userTeam && _userTeam.teamName)){ if(meEl) meEl.innerHTML=''; return ''; }
  if(top50.some(t=>t._isMe)){ if(meEl) meEl.innerHTML=''; return ''; }
  const cc=_userTeam.countryCode, tn=_userTeam.teamName;
  let myRank='—', myOvr=0, myCf=0, myMv=0;
  try{
    const { data:mt } = await window.sb.from('teams')
      .select('team_ovr, team_points, market_value').eq('country_code',cc).eq('name',tn).maybeSingle();
    if(mt){ myOvr=Math.round(Number(mt.team_ovr)||0); myCf=Number(mt.team_points)||0; myMv=Number(mt.market_value)||0; }
    try { if(typeof calculateTeamValue==="function"){ const _v=calculateTeamValue({name:tn, countryCode:cc}); if(_v>0) myMv=_v; } } catch(e){} // 🆕 kendi takımın: oyuncu toplamı (hero ile aynı)
    const myVal = (col==='market_value')?myMv:(col==='team_points'?myCf:myOvr);
    const { count } = await window.sb.from('teams').select('name',{count:'exact',head:true}).gt(col, myVal);
    if(typeof count==='number') myRank=count+1;
  }catch(e){}
  const v=_rkTeamVisuals(cc,tn);
  const t={n:tn, countryCode:cc, f:v.flag, cn:v.countryName, lg:v.leagueName, o:myOvr, cf:myCf, mv:myMv, bg:v.bg, tc:v.tc, short:v.short, _isMe:true};
  const html = '<div class="rk-me-bas">Senin takımın</div>'
    + '<div class="lst-list">' + rkTeamRow(t, myRank, true) + '</div>';
  const meEl2=document.getElementById('rkTeamMe'); if(meEl2 && _rkActiveTab==='teams') meEl2.innerHTML = html;
  return html;
}

// ── Render: Oyuncular ──
// Oyuncu sıralama modu: 'skill' (yetenek/overall) | 'level' (seviye)
let _rkPlayerMode = 'skill';

function rkSetPlayerMode(mode){
  _rkPlayerMode = mode;
  const sBtn = document.getElementById('rkPlayerModeSkill');
  const lBtn = document.getElementById('rkPlayerModeLevel');
  if(sBtn) sBtn.classList.toggle('active', mode==='skill');
  if(lBtn) lBtn.classList.toggle('active', mode==='level');
  // Info text güncelle
  const info = document.getElementById('rkPlayerInfoText');
  if(info){
    info.textContent = mode === 'level'
      ? 'En İyi 50 Oyuncu — seviye (level) sırasıyla'
      : 'En İyi 50 Oyuncu — yetenek puanına göre';
  }
  rkRenderPlayers();
}

async function rkRenderPlayers(){
  const list = document.getElementById('rkPlayersList');
  const meEl = document.getElementById('rkPlayerMe');
  if(!list) return;
  if(_rkSearchActive){ rkRenderSearch(); return; }
  const key = 'players|' + _rkPlayerMode;
  const cached = _rkListCache[key];
  // Taze cache → ANINDA göster, sorgu YOK
  if(cached && (Date.now()-cached.at) < _RK_LIST_TTL){
    list.innerHTML = cached.html;
    if(meEl) meEl.innerHTML = cached.meHtml || '';
    window._rkPlayersTop50 = cached.mapped || [];
    return;
  }
  if(!window.sb){ if(!cached) list.innerHTML = '<div class="lst-empty"><div class="lst-empty-icon">⚠️</div>Bağlantı yok</div>'; return; }
  const metric = (_rkPlayerMode==='level') ? 'level' : 'overall';
  const second = (metric==='level') ? 'overall' : 'level';
  if(cached){ list.innerHTML = cached.html; if(meEl) meEl.innerHTML = cached.meHtml||''; }
  else { list.innerHTML = '<div class="lst-empty"><div class="lst-empty-icon">⏳</div>Sıralama yükleniyor…</div>'; }
  const seq = ++_rkPlayersSeq;
  let rows=[], ok=false;
  try{
    const { data, error } = await window.sb.from('players')
      .select('id, user_id, name, pos, sub_pos, ek_mevki, ozel_yetenek, ozel_aktif, country_code, team_name, overall, level, avatar, avatar_id, gender, nation')
      .order(metric, { ascending:false, nullsFirst:false })
      .order(second, { ascending:false, nullsFirst:false })
      .limit(50);
    if(!error && Array.isArray(data)){ rows=data; ok=true; }
    else if(error) console.warn('[rkPlayers] sorgu:', error);
  }catch(e){ console.warn('[rkPlayers] exception:', e); }
  if(seq!==_rkPlayersSeq) return;        // daha yeni render başladı
  if(_rkActiveTab!=='players') return;   // sekme değişti
  if(!ok){ if(!cached) list.innerHTML='<div class="lst-empty"><div class="lst-empty-icon">⚠️</div>Yüklenemedi — sekmeye tekrar dokun</div>'; return; }
  const mapped = rows.map(r => _rkMapPlayerRow(r));
  window._rkPlayersTop50 = mapped;
  const html = _rkKursuListe(mapped, (p,i,kz)=>rkPlayerRow(p, i+1, !!p._isMe, kz));   // 822
  list.innerHTML = html;
  let meHtml = '';
  try { meHtml = await _rkRenderPlayerMe(metric, mapped); } catch(e){}
  _rkListCache[key] = { html, meHtml: meHtml||'', mapped, at: Date.now() };
}

// players satırını sıralama görünümü objesine çevir (ortak)
function _rkMapPlayerRow(r){
  const v=_rkTeamVisuals(r.country_code, r.team_name);
  const myUid=(window.authUser&&authUser.id)||null;
  return {
    n:r.name, f:r.nation || v.flag, c:r.team_name || 'Serbest',   // 820 — uyruk bayrağı
    p:r.pos, subPos:r.sub_pos||null, ek:r.ek_mevki||[], o:r.overall||10, lv:r.level||0,
    av:r.avatar || '🧑', avatar_id:r.avatar_id || null,
    gender:r.gender || null, isBot:!r.user_id,
    cc:r.country_code, teamName:r.team_name,
    teamBg:v.bg, teamTc:v.tc, teamShort:v.short,
    userId:r.user_id || null,
    _isMe: !!(myUid && r.user_id===myUid),
  };
}

// "Senin sıran" alt paneli — top-50 dışındaysa ucuz sayım sorgusuyla sıra
async function _rkRenderPlayerMe(metric, top50){
  const meEl=document.getElementById('rkPlayerMe');
  if(top50.some(p=>p._isMe)){ if(meEl) meEl.innerHTML=''; return ''; }
  const me=(typeof ROSTER_DATA!=='undefined') ? ROSTER_DATA.find(r=>r.role==='user') : null;
  const myOverall=me?(me.overall||10):10, myLevel=me?(me.level||0):0;
  const myVal=(metric==='level')?myLevel:myOverall;
  let myRank='—';
  try{
    const { count } = await window.sb.from('players').select('id',{count:'exact',head:true}).gt(metric, myVal);
    if(typeof count==='number') myRank=count+1;
  }catch(e){}
  const myName=me?.name || (window.authUser&&authUser.name) || 'Oyuncu';
  const myPos=me?.pos || 'MID';
  const myAvatar=me?.avatar || '🙂';
  const cc=(typeof _userTeam!=='undefined'&&_userTeam)?_userTeam.countryCode:'TR';
  const tn=(typeof _userTeam!=='undefined'&&_userTeam)?_userTeam.teamName:null;
  const v=_rkTeamVisuals(cc, tn);
  const html = '<div class="rk-me-bas">Senin sıran</div>'
    + '<div class="lst-list">' + rkPlayerRow(
        {n:myName, f:(me && me.nation) || (window.authUser && authUser.nationality && typeof ccToFlag === 'function' ? ccToFlag(authUser.nationality) : '') || v.flag,   // 820
         c:(tn||'Serbest'), p:myPos, o:myOverall, lv:myLevel, av:myAvatar, isUser:true,
         teamBg:v.bg, teamTc:v.tc, teamShort:v.short, cc, _isMe:true},
        myRank, true
      ) + '</div>';
  const meEl2=document.getElementById('rkPlayerMe'); if(meEl2 && _rkActiveTab==='players') meEl2.innerHTML = html;
  return html;
}

// Takım görselleri (logo renk/kısaltma) + bayrak/ülke/lig adı — gömülü CFT_DB'den (ağ YOK)
function _rkTeamVisuals(cc, teamName){
  let bg='#444', tc='#fff', short=(teamName||'').slice(0,3).toUpperCase()||'XX', flag='🏳️', countryName='', leagueName='';
  try{
    const country=(typeof _cftGetCountry==='function') ? _cftGetCountry(cc) : null;
    if(country){
      flag=country.flag || flag;
      countryName=country.name || '';
      for(const lg of (country.leagues||[])){
        const t=(lg.teams||[]).find(x=>x && x.name===teamName);
        if(t){ bg=t.bg||bg; tc=t.tc||tc; short=t.short||short; leagueName=lg.name||''; break; }
      }
    }
  }catch(e){}
  return { bg, tc, short, flag, countryName, leagueName };
}

// 🆕 Oyuncu araması — sunucuda ilike (yerel tam liste indirme YOK)
let _rkPlayerSearchSeq=0;
async function _rkSearchPlayersServer(rawQ){
  const el=document.getElementById('rkPlayersList');
  if(!el || !window.sb) return;
  const seq=++_rkPlayerSearchSeq;
  el.innerHTML='<div class="lst-empty"><div class="lst-empty-icon">⏳</div>Aranıyor…</div>';
  const metric=(_rkPlayerMode==='level')?'level':'overall';
  const second=(metric==='level')?'overall':'level';
  const safe=String(rawQ||'').replace(/[%_\\]/g,'');
  let rows=[];
  try{
    const { data } = await window.sb.from('players')
      .select('id, user_id, name, pos, sub_pos, ek_mevki, ozel_yetenek, ozel_aktif, country_code, team_name, overall, level, avatar, avatar_id, gender, nation')
      .ilike('name', '%'+safe+'%')
      .order(metric,{ascending:false,nullsFirst:false}).order(second,{ascending:false,nullsFirst:false})
      .limit(60);
    if(Array.isArray(data)) rows=data;
  }catch(e){ console.warn('[rkSearchPlayers]', e); }
  if(seq!==_rkPlayerSearchSeq) return;            // daha yeni arama başladı
  if(!_rkSearchActive || _rkActiveTab!=='players') return;
  const mapped=rows.map(r=>_rkMapPlayerRow(r));
  window._rkPlayersTop50=mapped;
  el.innerHTML = mapped.length
    ? '<div class="lst-list">'+mapped.map((p,i)=>rkPlayerRow(p,i+1,!!p._isMe)).join('')+'</div>'
    : '<div class="lst-empty"><div class="lst-empty-icon">🔍</div>Eşleşen sonuç yok</div>';
  const me1=document.getElementById('rkPlayerMe'); if(me1) me1.innerHTML='';
}

// ── Render: Ülkeler ──
// ═══════════════════════════════════════════════════════════════
// MİLLİ TAKIM SIRALAMASI — UEFA Coefficient sistemi
// FIFA Ranking benzeri başlangıç puanı + EURO National Cup performansı
// ═══════════════════════════════════════════════════════════════

// Her ülke için FIFA-tarzı başlangıç puanı (gerçek sıralamaya yakın değerler)
// Daha yüksek = daha güçlü milli takım
const RK_NT_BASE = {
  'EN': 1850, 'FR': 1840, 'ES': 1810, 'IT': 1790, 'PT': 1780, 'NL': 1770,
  'DE': 1760, 'BE': 1740, 'HR': 1720, 'CH': 1690, 'DK': 1680, 'AT': 1670,
  'PL': 1640, 'UA': 1620, 'SE': 1600, 'CZ': 1580, 'TR': 1570, 'HU': 1540,
  'NO': 1520, 'RO': 1510, 'SC': 1490, 'GR': 1480, 'IE': 1470, 'RS': 1460,
  'SK': 1440, 'FI': 1420, 'IL': 1400, 'BG': 1380, 'AL': 1360, 'AZ': 1320,
  'KZ': 1300, 'RU': 1750, // RU özel — eski güç
};

// 🆕 Milli takım puanları EDGE'de hesaplanır (world_state.data.nation_points).
//   Eski lokal seed/tur-çarpanı hesabı kaldırıldı — uydurma yok, edge tek kaynak.
function rkCalcNational() {
  const np = (typeof _worldStateCache !== 'undefined' && _worldStateCache && _worldStateCache.nation_points)
    ? _worldStateCache.nation_points : {};
  const results = _cftAllEntries().map(([cc, country]) => {
    const total = parseFloat(((np[country.name] || 0)).toFixed(1));
    return { code: cc, n: country.name, f: country.flag, base: 0, total, gain: total };
  });
  results.sort((a, b) => b.total - a.total);
  return results.map((r, i) => ({ ...r, rank: i + 1 }));
}

// 821 — Milli takımlar: Başarı Puanı (EURO Cup) / Yetenek (kadronun OVR ortalaması: sunucunun hazır değeri, nt_power)
//   Yetenek bir kez istenir; sonra sunucu değer değişince 'csc-milli-ovr' kanalından yeni değeri kendisi yollar (sorgu yok).
//   Kanal yalnız Sıralama sayfası açıkken dinlenir; bağlanınca (yeniden bağlanınca da) arada kaçan olmasın diye bir kez istenir.
let _rkNtMode = 'puan', _rkNtOvr = null, _rkNtOvrAt = 0, _rkNtOvrYuk = null, _rkNtSur = 0;
let _rkNtKanal = null, _rkNtKanalOk = false, _rkNtKanalAt = 0, _rkNtKanalT = 0, _rkNtCizT = 0;
function rkSetNationalMode(mode){
  _rkNtMode = mode;
  const pB = document.getElementById('rkNationalModePuan'), oB = document.getElementById('rkNationalModeOvr');
  if(pB) pB.classList.toggle('active', mode === 'puan');
  if(oB) oB.classList.toggle('active', mode === 'ovr');
  const info = document.getElementById('rkNationalInfoText');
  if(info) info.textContent = mode === 'ovr' ? 'Milli Takım Sıralaması — kadronun yetenek ortalaması' : 'Milli Takım Sıralaması — EURO National Cup performansı';
  rkRenderNational();
}
function _rkNtOvrGetir(){
  if(_rkNtOvrYuk) return _rkNtOvrYuk;
  if(!window.sb) return Promise.resolve(_rkNtOvr);
  const basla = Date.now();
  _rkNtOvrYuk = window.sb.from('team_data').select('country_code,ovr:data->ovr').eq('data_key', 'nt_power').then(({ data, error }) => {
    if(!error && Array.isArray(data)){ const m = {}; data.forEach(r => { if(r && r.country_code) m[r.country_code] = Number(r.ovr) || 0; }); _rkNtOvr = m; _rkNtOvrAt = basla; _rkNtSur++; }
    return _rkNtOvr;
  }).catch(() => _rkNtOvr).finally(() => { _rkNtOvrYuk = null; });
  return _rkNtOvrYuk;
}
function _rkNtGorunur(){
  const pg = document.getElementById('page-rankings');
  return !!(pg && pg.classList.contains('active') && _rkActiveTab === 'national' && _rkNtMode === 'ovr');
}
function _rkNtTazeCiz(){
  if(!_rkNtGorunur()) return;
  if(_rkSearchActive) rkRenderSearch(); else rkRenderNational();
}
function _rkNtKanalAc(){
  if(_rkNtKanal || !window.sb || typeof window.sb.channel !== 'function') return;
  _rkNtKanalAt = Date.now();
  // Bağlantı gelmezse yine de bir kez: elimizdeki değer kanal kapalıyken kalmış olabilir
  clearTimeout(_rkNtKanalT);
  _rkNtKanalT = setTimeout(() => { _rkNtKanalT = 0; if(_rkNtKanal && !_rkNtKanalOk && _rkNtOvr && _rkNtOvrAt < _rkNtKanalAt) _rkNtOvrGetir().then(_rkNtTazeCiz); }, 5000);
  try {
    _rkNtKanal = window.sb.channel('csc-milli-ovr')
      .on('broadcast', { event: 'ovr' }, m => _rkNtOvrOlay(m && m.payload))
      .subscribe(st => {
        const ok = st === 'SUBSCRIBED';
        if(ok && !_rkNtKanalOk){
          clearTimeout(_rkNtKanalT); _rkNtKanalT = 0;
          const yeniden = _rkNtOvrAt && _rkNtOvrAt < _rkNtKanalAt;   // kanal kapalıyken ya da koptuğu sırada alınmış değer
          _rkNtKanalAt = Date.now();
          if(yeniden) _rkNtOvrGetir().then(_rkNtTazeCiz);
        }
        if(!ok && _rkNtKanalOk) _rkNtKanalAt = Date.now();
        _rkNtKanalOk = ok;
      });
  } catch(e) { _rkNtKanal = null; _rkNtKanalOk = false; }
}
function _rkNtKanalKapat(){
  if(!_rkNtKanal) return;
  try { window.sb.removeChannel(_rkNtKanal); } catch(e) {}
  _rkNtKanal = null; _rkNtKanalOk = false;
  clearTimeout(_rkNtKanalT); clearTimeout(_rkNtCizT); _rkNtKanalT = _rkNtCizT = 0;
}
// Sunucu: "şu milli takımın yeteneği şimdi bu" — değer yayınla gelir, istek atılmaz
function _rkNtOvrOlay(p){
  const cc = p && typeof p.cc === 'string' ? p.cc : '', o = p ? Number(p.o) : NaN;
  if(!_rkNtOvr || !/^[A-Z]{2,3}$/.test(cc) || !Number.isFinite(o) || o < 0 || o > 200) return;
  if(_rkNtOvr[cc] === o) return;
  _rkNtOvr[cc] = o; _rkNtSur++;
  if(!_rkNtCizT) _rkNtCizT = setTimeout(() => { _rkNtCizT = 0; _rkNtTazeCiz(); }, 400);   // aynı anda gelenler tek çizim
}
function rkCalcNationalOvr(){
  const m = _rkNtOvr || {};
  const results = _cftAllEntries().map(([cc, country]) => ({ code: cc, n: country.name, f: country.flag, v: m[cc] || 0, ovr: Math.round(m[cc] || 0) }));
  results.sort((a, b) => b.v - a.v || String(a.n).localeCompare(String(b.n), 'tr'));
  return results.map((r, i) => ({ ...r, rank: i + 1 }));
}
function rkRenderNational() {
  const list = document.getElementById('rkNationalList');
  if(!list) return;
  if(_rkSearchActive){ rkRenderSearch(); return; }
  const myCC = (typeof _userTeam !== 'undefined' && _userTeam) ? _userTeam.countryCode : 'TR';
  if(_rkNtMode === 'ovr'){
    _rkNtKanalAc();
    const ciz = () => { if(_rkNtMode !== 'ovr' || _rkActiveTab !== 'national' || _rkSearchActive) return;
      list.innerHTML = _rkKursuListe(rkCalcNationalOvr(), (c, i, kz) => rkNationalRow(c, c.code === myCC, kz)); };   // 822
    if(_rkNtOvr) ciz(); else { list.innerHTML = '<div class="lst-empty"><div class="lst-empty-icon">⏳</div>Sıralama yükleniyor…</div>'; _rkNtOvrGetir().then(() => { if(_rkNtOvr) ciz(); }); }
    return;
  }
  const data = rkCalcNational();
  list.innerHTML = _rkKursuListe(data, (c, i, kz) => rkNationalRow(c, c.code === myCC, kz));   // 822
}

function rkRenderCountries(){
  const list = document.getElementById('rkCountriesList');
  if(!list) return;
  if(_rkSearchActive){ rkRenderSearch(); return; }
  const data = rkCalcCountries();
  const curSeason = (typeof getSeasonInfo === 'function') ? getSeasonInfo().season : 1;
  const winStart = curSeason - 4;
  const displaySeasons = (curSeason <= 5) ? [1,2,3,4,5] : [curSeason-4,curSeason-3,curSeason-2,curSeason-1,curSeason];
  const myCC = (typeof _userTeam !== 'undefined' && _userTeam) ? _userTeam.countryCode : 'TR';
  list.innerHTML = '<div class="lst-list">' + data.map(c => rkCountryRow(c, displaySeasons, winStart, curSeason, c.code === myCC)).join('') + '</div>';
}

// ── Milli / Ülke satırı (normal render + arama ORTAK kullanır) ──
function rkNationalRow(c, isMe, kz){
  const ovrMod = c.ovr != null;   // 821 — Yetenek sekmesi
  const gainTxt = ovrMod ? '' : c.gain > 0 ? `+${c.gain.toFixed(2)}` : (c.gain < 0 ? c.gain.toFixed(2) : '\u2014');
  const gainCls = c.gain > 0 ? 'rk-nt-gain-pos' : (c.gain < 0 ? 'rk-nt-gain-neg' : 'rk-nt-gain-zero');
  if(kz){   // 822 — kürsü kartı
    return `<div class="rk-kz rk-kz${c.rank} ${isMe?'is-user':''}" onclick="ntViewAsGuest('${c.code}')" style="cursor:pointer">
      <div class="rk-kz-m">${c.rank}</div>
      <div class="rk-kz-ar"><div class="rk-flag">${c.f}</div></div>
      <div class="rk-kz-ad ${isMe?'user-mark':''}"><span>${c.n}</span></div>
      <div class="rk-kz-alt">Milli Takım · A Sınıfı</div>
      <div class="rk-kz-v">${ovrMod ? c.ovr : c.total.toFixed(2)}</div>
      <div class="rk-kz-b">${ovrMod ? 'yetenek' : 'puan'}</div>
      <div class="rk-kz-yz">${_yzHtml(ovrMod ? c.ovr : _yzNtO(c.code), 'n')}</div>
      <div class="rk-kz-alt2">${ovrMod ? '' : `<span class="rk-nt-gain ${gainCls}">${gainTxt}</span>`}${_bgnMini('milli', c.code)}</div>
    </div>`;
  }
  return `<div class="lst-row clickable ${isMe?'is-user':''}" onclick="ntViewAsGuest('${c.code}')" style="cursor:pointer">
      <div class="lst-rank ${(typeof _rankClass === 'function') ? _rankClass(c.rank) : rkNumCls(c.rank)}">${c.rank}</div>
      <div class="rk-flag">${c.f}</div>
      <div class="lst-info-col">
        <div class="lst-pname ${isMe?'user-mark':''}">${c.n}</div>
        <div class="lst-psub" style="margin-bottom:2px">Milli Takım · A Sınıfı</div>
        <div class="rk-nt-meta">${ovrMod ? '' : `<span class="rk-nt-gain ${gainCls}">${gainTxt}</span>`}${_bgnMini('milli', c.code)}</div>
      </div>
      <div>
        <div class="lst-stat-val ${c.rank<=3?'gold':''}">${ovrMod ? c.ovr : c.total.toFixed(2)}</div>
        <div class="lst-stat-unit">${ovrMod ? 'yetenek' : 'puan'}</div>
        <div class="lst-yz">${_yzHtml(ovrMod ? c.ovr : _yzNtO(c.code), 'n')}</div>
      </div>
    </div>`;
}

function rkCountryRow(c, displaySeasons, winStart, curSeason, isMe){
  const chips = displaySeasons.map(ds => {
    const idx = ds - winStart;
    const v = (ds <= curSeason && idx >= 0 && idx <= 4) ? c.s[idx] : 0;
    const isCur = ds === curSeason;
    const empty = !(v > 0);
    return `<div class="rk-cnt-szchip ${isCur?'cur':''} ${empty?'empty':''}">
        <div class="rk-cnt-szchip-lbl">${ds}.Sz</div>
        <div class="rk-cnt-szchip-val">${empty ? '\u2014' : v.toFixed(2)}</div>
      </div>`;
  }).join('');
  return `<div class="lst-row rk-cnt-r ${isMe?'is-user':''}">
      <div class="lst-rank ${(typeof _rankClass === 'function') ? _rankClass(c.rank) : rkNumCls(c.rank)}">${c.rank}</div>
      <div class="rk-flag">${c.f}</div>
      <div class="rk-cnt-nameblock">
        <div class="lst-pname ${isMe?'user-mark':''}">${c.n}</div>
        <div class="lst-psub">${c.clubs} kulüp</div>
      </div>
      <div class="rk-cnt-szrow">${chips}</div>
      <div class="rk-cnt-totalblock">
        <div class="lst-stat-val ${c.rank<=3?'gold':''}">${c.total.toFixed(2)}</div>
        <div class="lst-stat-unit">toplam</div>
      </div>
    </div>`;
}

// ═══ SIRALAMA ARAMA + KURAL (INFO) ═══
let _rkSearchActive = false;
let _rkSrcCache = null;

function _rkLower(s){
  return (s||'').replace(/İ/g,'i').replace(/I/g,'ı').toLocaleLowerCase('tr');
}

function _rkClearSearchInput(){
  const inp = document.getElementById('rkSearchInput');
  if(inp) inp.value = '';
  _rkSearchActive = false;
  _rkSrcCache = null;
  const w = inp ? inp.closest('.rk-search') : null;
  if(w) w.classList.remove('has-val');
}

// Aramaya açık takımlar — her kademe (getTop50Teams sadece 1. ligi taradığı için yetmez)
function getAllTeamsForSearch(){
  const myCC   = (typeof _userTeam!=='undefined'&&_userTeam)?_userTeam.countryCode:null;
  const myName = (typeof _userTeam!=='undefined'&&_userTeam)?_userTeam.teamName:null;
  const all = [];
  for(const [code, country] of _cftAllEntries()){
    if(!country.leagues) continue;
    for(const lg of country.leagues){
      for(const team of (lg.teams||[])){
        const isMe = !!(myCC&&myName&&code===myCC&&team.name===myName);
        all.push({
          n:team.name, f:country.flag, cn:country.name, countryCode:code, lg:lg.name,
          o:(typeof _teamPowerFromPlayers==='function')?_teamPowerFromPlayers(code,team.name,team.rank):(team.teamOvr||10),
          oz:team.oz||0,
          mv:(typeof calculateTeamValue==='function')?calculateTeamValue({name:team.name,countryCode:code}):0,
          cf:(team.teamPoints||0),
          bg:team.bg, tc:team.tc, short:team.short, rank:team.rank, _isMe:isMe,
        });
      }
    }
  }
  return all;
}

// Aktif sekmenin TAM (sıralı) listesi — oturum içinde cache'lenir
function _rkSearchListFor(tab){
  const key = tab+'|'+_rkTeamMode+'|'+_rkPlayerMode+'|'+_rkNtMode+(_rkNtMode === 'ovr' && _rkNtOvr ? _rkNtSur : '');   // 821
  if(_rkSrcCache && _rkSrcCache.key===key) return _rkSrcCache.list;
  let list;
  if(tab==='teams'){
    const mode=_rkTeamMode;
    list = getAllTeamsForSearch().sort((a,b)=>
      ((mode==='market')?((b.mv||0)-(a.mv||0)):(mode==='coef')?((b.cf||0)-(a.cf||0)):((b.o||0)-(a.o||0)))
      ||((b._isMe?1:0)-(a._isMe?1:0))||((b.oz||0)-(a.oz||0))||(a.n>b.n?1:-1)
    ).map((t,i)=>({...t,_rank:i+1}));
  } else if(tab==='national'){
    list = (_rkNtMode === 'ovr' && _rkNtOvr) ? rkCalcNationalOvr() : rkCalcNational();   // 821
  } else if(tab==='countries'){
    list = rkCalcCountries();
  } else {
    list = buildRkPlayerList().slice();
    if(_rkPlayerMode==='level') list.sort((a,b)=>(b.lv||0)-(a.lv||0)||(b.o||0)-(a.o||0)||((b._isMe?1:0)-(a._isMe?1:0))||(a.n>b.n?1:-1));
    else list.sort((a,b)=>(b.o||0)-(a.o||0)||((b._isMe?1:0)-(a._isMe?1:0))||(a.n>b.n?1:-1));
  }
  _rkSrcCache = {key, list};
  return list;
}

// 🆕 Takım araması — SUNUCUDA ilike (yerel tüm-takım taraması + calculateTeamValue fetch fırtınası YOK).
//    İlk 50 dışındaki takımlar da GERÇEK değerle görünür (team_ovr/team_points/market_value).
let _rkTeamSearchSeq=0;
async function _rkSearchTeamsServer(rawQ){
  const el=document.getElementById('rkTeamsList');
  if(!el || !window.sb) return;
  const seq=++_rkTeamSearchSeq;
  el.innerHTML='<div class="lst-empty"><div class="lst-empty-icon">⏳</div>Aranıyor…</div>';
  const col=(_rkTeamMode==='market')?'market_value':(_rkTeamMode==='coef'?'team_points':'team_ovr');
  const safe=String(rawQ||'').replace(/[%_\\]/g,'');
  let rows=[];
  try{
    const { data } = await window.sb.from('teams')
      .select('country_code, name, team_ovr, team_points, market_value')
      .ilike('name','%'+safe+'%')
      .order(col,{ascending:false,nullsFirst:false})
      .limit(60);
    if(Array.isArray(data)) rows=data;
  }catch(e){ console.warn('[rkSearchTeams]', e); }
  if(seq!==_rkTeamSearchSeq) return;            // daha yeni arama başladı
  if(!_rkSearchActive || _rkActiveTab!=='teams') return;
  const myCC=(typeof _userTeam!=='undefined'&&_userTeam)?_userTeam.countryCode:null;
  const myName=(typeof _userTeam!=='undefined'&&_userTeam)?_userTeam.teamName:null;
  const mapped=rows.map((r,i)=>{
    const v=_rkTeamVisuals(r.country_code, r.name);
    return { n:r.name, countryCode:r.country_code, f:v.flag, cn:v.countryName, lg:v.leagueName,
      o:Math.round(Number(r.team_ovr)||0), cf:Number(r.team_points)||0, mv:Number(r.market_value)||0,
      bg:v.bg, tc:v.tc, short:v.short,
      _isMe: !!(myCC && myName && r.country_code===myCC && r.name===myName), _rank:i+1 };
  });
  // Kendi takımın market = kadro toplamı (hero ile birebir)
  try { const _me=mapped.find(t=>t._isMe); if(_me && typeof calculateTeamValue==='function'){ const _v=calculateTeamValue({name:_me.n,countryCode:_me.countryCode}); if(_v>0) _me.mv=_v; } } catch(e){}
  el.innerHTML = mapped.length
    ? '<div class="lst-list">'+mapped.map(t=>rkTeamRow(t,t._rank,!!t._isMe)).join('')+'</div>'
    : '<div class="lst-empty"><div class="lst-empty-icon">🔍</div>Eşleşen sonuç yok</div>';
  const me2=document.getElementById('rkTeamMe'); if(me2) me2.innerHTML='';
}

function rkSearchOnInput(){
  const inp = document.getElementById('rkSearchInput');
  if(!inp) return;
  const w = inp.closest('.rk-search'); if(w) w.classList.toggle('has-val', !!inp.value);
  const q = _rkLower(inp.value.trim());
  if(q.length < 3){
    if(_rkSearchActive){ _rkSearchActive = false; rkRerenderActive(); }
    return;
  }
  _rkSearchActive = true;
  // Oyuncu araması sunucuda; diğerleri yerel (CFT_DB / world_state)
  if(_rkActiveTab==='players'){ _rkSearchPlayersServer(q); return; }
  if(_rkActiveTab==='teams'){ _rkSearchTeamsServer(q); return; }
  if(_rkActiveTab==='captains'){ _rkSearchCaptainsServer(q); return; }   // 913
  rkRenderSearch();
}

function rkRenderSearch(){
  const tab = _rkActiveTab;
  // Oyuncu araması sunucuda yapılır (yerel tam liste yok)
  if(tab==='players'){
    const inp=document.getElementById('rkSearchInput');
    const q=(inp?inp.value:'').trim();
    if(q.length>=3) _rkSearchPlayersServer(_rkLower(q));
    return;
  }
  if(tab==='teams'){
    const inp=document.getElementById('rkSearchInput');
    const q=(inp?inp.value:'').trim();
    if(q.length>=3) _rkSearchTeamsServer(_rkLower(q));
    return;
  }
  if(tab==='captains'){   // 913
    const inp=document.getElementById('rkSearchInput');
    const q=(inp?inp.value:'').trim();
    if(q.length>=3) _rkSearchCaptainsServer(_rkLower(q));
    return;
  }
  const list = _rkSearchListFor(tab);
  let el, nameOf, rowOf, byIndex=false;
  if(tab==='teams'){
    el=document.getElementById('rkTeamsList'); nameOf=t=>t.n; rowOf=t=>rkTeamRow(t,t._rank,!!t._isMe);
  } else if(tab==='national'){
    const myCC=(typeof _userTeam!=='undefined'&&_userTeam)?_userTeam.countryCode:'TR';
    el=document.getElementById('rkNationalList'); nameOf=c=>c.n; rowOf=c=>rkNationalRow(c,c.code===myCC);
  } else if(tab==='countries'){
    const cur=(typeof getSeasonInfo==='function')?getSeasonInfo().season:1;
    const ws=cur-4; const disp=(cur<=5)?[1,2,3,4,5]:[cur-4,cur-3,cur-2,cur-1,cur];
    const myCC=(typeof _userTeam!=='undefined'&&_userTeam)?_userTeam.countryCode:'TR';
    el=document.getElementById('rkCountriesList'); nameOf=c=>c.n; rowOf=c=>rkCountryRow(c,disp,ws,cur,c.code===myCC);
  } else { return; }
  if(!el) return;
  const inp=document.getElementById('rkSearchInput');
  const q=_rkLower((inp?inp.value:'').trim());
  const rows=[];
  for(let i=0;i<list.length;i++){
    if(_rkLower(nameOf(list[i])).includes(q)){
      rows.push(byIndex ? rowOf(list[i],i) : rowOf(list[i]));
      if(rows.length>=60) break;
    }
  }
  el.innerHTML = rows.length
    ? '<div class="lst-list">'+rows.join('')+'</div>'
    : '<div class="lst-empty"><div class="lst-empty-icon">🔍</div>Eşleşen sonuç yok</div>';
  const me1=document.getElementById('rkPlayerMe'); if(me1) me1.innerHTML='';
  const me2=document.getElementById('rkTeamMe'); if(me2) me2.innerHTML='';
}

function rkSearchClear(){
  _rkClearSearchInput();
  rkRerenderActive();
}

function rkOpenInfo(){
  const m=document.getElementById('rkInfoModal');
  const t=document.getElementById('rkInfoTitle');
  const b=document.getElementById('rkInfoBody');
  if(!m||!b) return;
  const r=_rkInfoContent(_rkActiveTab);
  if(t) t.textContent=r.title;
  b.innerHTML=r.html;
  m.classList.add('open');
}
function rkCloseInfo(){
  const m=document.getElementById('rkInfoModal');
  if(m) m.classList.remove('open');
}
