// 734 — Takım Arıyorum → paylaşan oyuncunun kartı · Futbolcu Arıyorum → takım sayfası (ziyaretçi)
async function cfcMdTplAc(b) {
  const d = b.dataset;
  if (d.k === 'tpl-team') { if (d.cc && d.t && typeof viewTeam === 'function') viewTeam(d.cc, d.t); return; }
  const ad = String(d.a || '').replace(/^user:/, '').replace(/^@+/, '').toLowerCase().replace(/[,()%*'"\\]/g, '');
  if (!ad || !window.sb || b.disabled) return;
  b.disabled = true;
  const { data } = await window.sb.from('profiles').select('id').or('username.ilike.' + ad + ',username.ilike.@' + ad).limit(1);
  b.disabled = false;
  const uid = data && data[0] && data[0].id;
  if (!uid) { if (typeof tfShowToast === 'function') tfShowToast('Oyuncu bulunamadı', '#ef5350'); return; }
  openPlayerModal({ userId: uid, user_id: uid, name: d.n || '' }, {});
}
// Ortak uyarı — işlem sunucuda gerçekleşmediyse kullanıcı bilsin
function _cfcMdUyar(mesaj) {
  try { if (typeof tfShowToast === 'function') tfShowToast('❌ ' + mesaj, '#ef5350'); }
  catch(e) {}
}

// 934 — dokununca anında yansır; sunucu tek küçük istekle onaylar (art arda dokunuşlar sırayla gider)
function cfcMdToggleLike(postId) { _csmTepki(postId, 'like'); }
function cfcMdToggleDislike(postId) { _csmTepki(postId, 'dislike'); }
function _csmTepki(id, tur) {
  const p = _csm.post[id]; if (!p || !window.sb) return;
  const eski = { my: p.my, l: p.likeC, d: p.dislikeC };
  if (p.my === 'like') p.likeC--; else if (p.my === 'dislike') p.dislikeC--;
  if (p.my === tur) p.my = null;
  else { p.my = tur; if (tur === 'like') p.likeC++; else p.dislikeC++; }
  p.likeC = Math.max(0, p.likeC); p.dislikeC = Math.max(0, p.dislikeC);
  _csmCiz(id);
  const no = (_csm.seq[id] = (_csm.seq[id] || 0) + 1);
  const geri = () => { if (no === _csm.seq[id]) { p.my = eski.my; p.likeC = eski.l; p.dislikeC = eski.d; _csmCiz(id); } };
  _csm.zincir[id] = (_csm.zincir[id] || Promise.resolve())
    .then(() => window.sb.rpc('csm_tepki', { p_post: id, p_tur: tur }))
    .then(({ data, error }) => {
      if (error || !data || !data.ok) { geri(); _cfcMdUyar(tur === 'like' ? 'Beğeni kaydedilemedi' : 'İşlem kaydedilemedi'); return; }
      if (no === _csm.seq[id]) { p.my = data.my || null; p.likeC = data.l || 0; p.dislikeC = data.dl || 0; _csmCiz(id); }
    }, geri);
}

async function cfcMdToggleRepost(postId) {
  const r = await _socialAdapter.toggleRepost(postId);
  if (r && r.hata) _cfcMdUyar('Yeniden paylaşım şu an kullanılamıyor');
  cfcMdRender();
}

// 🆕 Sil onay akışı — basit modal, native confirm yerine
let _cfcMdPendingDeleteId = null;
function cfcMdAskDelete(postId) {
  _cfcMdPendingDeleteId = postId;
  const ov = document.getElementById('cfcMdDelOverlay');
  if (ov) ov.classList.add('open');
}
function cfcMdCloseDelModal() {
  _cfcMdPendingDeleteId = null;
  const ov = document.getElementById('cfcMdDelOverlay');
  if (ov) ov.classList.remove('open');
}
async function cfcMdConfirmDelete() {
  const id = _cfcMdPendingDeleteId;
  cfcMdCloseDelModal();
  if (!id) return;
  try {
    const res = await _socialAdapter.deletePost(id);
    if (res && res.deleted) {
      if (typeof tfShowToast === 'function') tfShowToast('🗑️ Gönderi silindi', '#ef5350');
      _csmGonderiCikar(id);   // 934 — sayfa yeniden yüklenmez
    } else {
      const reason = res && res.reason === 'forbidden' ? 'Bu gönderiyi silemezsin' : 'Gönderi bulunamadı';
      if (typeof tfShowToast === 'function') tfShowToast('❌ ' + reason, '#ef5350');
    }
  } catch(e) {
    console.error('[CFC Media] Sil hatası:', e);
    if (typeof tfShowToast === 'function') tfShowToast('❌ Silinemedi', '#ef5350');
  }
}

// ── Yardımcılar ──
function _cfcMdLikeCount(p) {
  if (!p) return 0;
  if (typeof p.likeCount === 'number') return p.likeCount;
  if (Array.isArray(p.likes)) return p.likes.length;
  return 0;
}
function _cfcMdDislikeCount(p) {
  if (!p) return 0;
  if (typeof p.dislikeCount === 'number') return p.dislikeCount;
  if (Array.isArray(p.dislikes)) return p.dislikes.length;
  return 0;
}
function _cfcMdEscape(s) {
  return String(s || '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}
function _cfcMdRelTime(ts) {
  const diff = (Date.now() - ts) / 1000;
  if (diff < 60) return Math.floor(diff) + 'sn';
  if (diff < 3600) return Math.floor(diff/60) + 'dk';
  if (diff < 86400) return Math.floor(diff/3600) + 'sa';
  if (diff < 604800) return Math.floor(diff/86400) + 'g';
  return new Date(ts).toLocaleDateString('tr');
}

// 🆕 Takipçi sayısı (yerel/single-user modunda dürüst hesaplama)
// - Kendi takipçim → 0 (yerel oyun, kimse beni takip edemez)
// - Başkasının takipçisi → ben onu takip ediyorsam 1, değilsem 0
// Backend gelince burası adapter'a taşınıp gerçek sayı döner.
// Takipçi sayısı — kendi profilim için cache, ziyaretçi profilinde async server sayımı
// (cfcMdRenderProfile içinde async olarak doldurulur)
function cfcMdGetFollowerCount(userId) {
  if (!userId) return 0;
  const my = cfcMdGetMyProfile();
  if (userId === my.id) {
    return _cfcMdFollowersCache.length;
  }
  // Başkasının takipçi sayısı için cache (async olarak doldurulur)
  return _cfcMdOtherFollowerCounts[userId] || 0;
}

// Ziyaret edilen kullanıcı için takipçi+takip eden sayılarını çek
let _cfcMdOtherFollowerCounts = {};
let _cfcMdOtherFollowingCounts = {};
async function cfcMdLoadUserFollowStats(userId) {
  if (!userId || !window.sb) return { followers: 0, following: 0 };
  try {
    const [ferRes, fingRes] = await Promise.all([
      window.sb.from('social_follows').select('follower_id', { count: 'exact', head: true }).eq('following_id', userId),
      window.sb.from('social_follows').select('following_id', { count: 'exact', head: true }).eq('follower_id', userId),
    ]);
    const followers = ferRes.count || 0;
    const following = fingRes.count || 0;
    _cfcMdOtherFollowerCounts[userId] = followers;
    _cfcMdOtherFollowingCounts[userId] = following;
    return { followers, following };
  } catch(e) { return { followers: 0, following: 0 }; }
}

// 🆕 Toplu sayım — bir kullanıcının postlarındaki toplam like + dislike (server'dan)
async function cfcMdGetUserStats(userId) {
  if (!userId || !window.sb) return { postCount: 0, totalLikes: 0, totalDislikes: 0 };
  try {
    const { data: posts } = await window.sb.from('social_posts')
      .select('id').eq('author_id', userId);
    const postCount = (posts || []).length;
    if (postCount === 0) return { postCount: 0, totalLikes: 0, totalDislikes: 0 };
    const postIds = posts.map(p => p.id);
    const { data: reacts } = await window.sb.from('social_likes')
      .select('reaction').in('post_id', postIds);
    let totalLikes = 0, totalDislikes = 0;
    (reacts || []).forEach(r => {
      if (r.reaction === 'like') totalLikes++;
      else if (r.reaction === 'dislike') totalDislikes++;
    });
    return { postCount, totalLikes, totalDislikes };
  } catch(e) {
    console.warn('[social] userStats:', e);
    return { postCount: 0, totalLikes: 0, totalDislikes: 0 };
  }
}

// ─────────────────────────────────────────────────────────────
// 🆕 ARAMA / ZİYARETÇİ PROFİL — Instagram tarzı kullanıcı arama
// ─────────────────────────────────────────────────────────────

// Kayıtlı kullanıcıları getir (Supabase profiles tablosundan)
// Async olduğu için arama açılışında awaitlenir, sonuçlar _cfcMdUsersCache'e atılır
let _cfcMdUsersCache = null;
let _cfcMdUsersCacheTs = 0;

// 🆕 ÖLÇEK: eskiden TÜM profiles + TÜM gerçek oyuncular çekiliyordu (20 bin
//   kullanıcıda arama her açıldığında 40 bin satır). Artık arama sunucuda yapılıyor:
//   en fazla 50 sonuç, oyuncu satırları da yalnızca o 50 kullanıcı için.
let _cfcMdUsersCacheQ = null;
function _cfcMdAramaTemizle(q) {
  return String(q || '').trim().slice(0, 40).replace(/[,()%*'"\\]/g, ' ').trim();
}

async function cfcMdLoadKnownUsers(query) {
  if (!window.sb) { _cfcMdUsersCache = []; return []; }
  const q = _cfcMdAramaTemizle(query);
  // 30 saniye cache (aynı arama tekrar tekrar istek atmasın)
  if (_cfcMdUsersCache && _cfcMdUsersCacheQ === q && (Date.now() - _cfcMdUsersCacheTs) < 30000) {
    return _cfcMdUsersCache;
  }
  try {
    let _pq = window.sb.from('profiles').select('id, username, name, nationality');
    if (q) _pq = _pq.or('username.ilike.%' + q + '%,name.ilike.%' + q + '%');
    const profRes = await _pq.order('username').limit(50);
    const _ids = (profRes.data || []).map(p => p.id).filter(Boolean);
    const playersRes = _ids.length
      ? await window.sb.from('players').select('user_id, user_team_data, avatar_id').in('user_id', _ids)
      : { data: [] };
    if (profRes.error) { console.warn('[social] users:', profRes.error); _cfcMdUsersCache = []; return []; }
    // user_id → user_team_data
    const teamByUid = {};
    const avByUid = {};
    for (const row of (playersRes.data || [])) {
      if (row.user_id && row.user_team_data) teamByUid[row.user_id] = row.user_team_data;
      if (row.user_id && row.avatar_id) avByUid[row.user_id] = row.avatar_id;
    }
    const myId = cfcMdGetMyId();
    const users = (profRes.data || []).map(p => {
      const handle = '@' + (p.username || '').replace(/^@+/, '').toLowerCase();
      const id = 'user:' + (p.username || '').replace(/^@+/, '').toLowerCase();
      const avId = avByUid[p.id] || null;
      let avHTML = '⚽';
      if (avId && typeof getAvatarEmoji === 'function') {
        avHTML = getAvatarEmoji(avId, null);
      }
      const t = teamByUid[p.id];
      return {
        id,
        name: p.name || p.username || 'Kullanıcı',
        handle,
        avatar: avHTML,
        avatarId: avId,
        team: t && t.teamName ? t.teamName : null,
        teamCc: t && t.countryCode ? t.countryCode : null,
        country: p.nationality || (t && t.countryCode) || null,
        isMe: id === myId,
      };
    });
    _cfcMdUsersCache = users;
    _cfcMdUsersCacheTs = Date.now();
    _cfcMdUsersCacheQ = q;
    return users;
  } catch(e) { console.warn('[social] users hata:', e); _cfcMdUsersCache = []; return []; }
}

// 🆕 Arama kutusu: 300 ms bekleyip sunucuda arar, sonra listeyi çizer.
let _cfcMdSearchTimer = null;
function cfcMdSearchInput(v) {
  const q = v;
  cfcMdRenderSearchResults(q);              // elde olan sonuçlarla anında süz
  if (_cfcMdSearchTimer) clearTimeout(_cfcMdSearchTimer);
  _cfcMdSearchTimer = setTimeout(async () => {
    try { await cfcMdLoadKnownUsers(q); } catch(e) {}
    await _cfcMdRozetYukle(cfcMdGetKnownUsers().map(u => u.id));
    cfcMdRenderSearchResults(q);
  }, 300);
}

// 🆕 Arama sonucu dışında, KİMLİĞİ bilinen kullanıcılar (takipçi listesi, ziyaret
//   edilen profil) ayrı bir cache'te tutulur; arama sonucu değişince kaybolmasınlar.
let _cfcMdUsersExtra = [];

function cfcMdGetKnownUsers() {
  // Sync API — arama cache'i + kimlikle çözülmüş kullanıcılar
  const a = _cfcMdUsersCache || [];
  if (!_cfcMdUsersExtra.length) return a;
  const gorulen = new Set(a.map(u => u.id));
  return a.concat(_cfcMdUsersExtra.filter(u => !gorulen.has(u.id)));
}

// 🆕 Belirli kullanıcıları (user:<kullanıcıadı>) sunucudan çöz — takipçi/takip listesi için.
async function cfcMdLoadUsersByIds(ids) {
  if (!window.sb) return;
  const adlar = [...new Set((ids || [])
    .map(x => String(x || '').replace(/^user:/, '').replace(/^@+/, '').toLowerCase())
    .filter(Boolean)
    .map(x => x.replace(/[,()%*'"\\]/g, '')))].slice(0, 200);
  const bilinen = new Set(cfcMdGetKnownUsers().map(u => u.id));
  const eksik = adlar.filter(a2 => !bilinen.has('user:' + a2));
  if (!eksik.length) return;
  try {
    const profRes = await window.sb.from('profiles')
      .select('id, username, name, nationality')
      .or(eksik.map(a2 => 'username.ilike.' + a2).join(','))
      .limit(200);
    const _ids = (profRes.data || []).map(p => p.id).filter(Boolean);
    const playersRes = _ids.length
      ? await window.sb.from('players').select('user_id, user_team_data, avatar_id').in('user_id', _ids)
      : { data: [] };
    const teamByUid = {}, avByUid = {};
    for (const row of (playersRes.data || [])) {
      if (row.user_id && row.user_team_data) teamByUid[row.user_id] = row.user_team_data;
      if (row.user_id && row.avatar_id) avByUid[row.user_id] = row.avatar_id;
    }
    const myId = cfcMdGetMyId();
    for (const p of (profRes.data || [])) {
      const uname = (p.username || '').replace(/^@+/, '').toLowerCase();
      const id = 'user:' + uname;
      if (_cfcMdUsersExtra.some(u => u.id === id)) continue;
      const avId = avByUid[p.id] || null;
      const t = teamByUid[p.id];
      _cfcMdUsersExtra.push({
        id,
        name: p.name || p.username || 'Kullanıcı',
        handle: '@' + uname,
        avatar: (avId && typeof getAvatarEmoji === 'function') ? getAvatarEmoji(avId, null) : '⚽',
        avatarId: avId,
        team: t && t.teamName ? t.teamName : null,
        teamCc: t && t.countryCode ? t.countryCode : null,
        country: p.nationality || (t && t.countryCode) || null,
        isMe: id === myId,
      });
    }
    if (_cfcMdUsersExtra.length > 400) _cfcMdUsersExtra = _cfcMdUsersExtra.slice(-400);
  } catch(e) { console.warn('[social] kullanıcı çözme hata:', e); }
}

async function cfcMdOpenSearch() {
  const ov = document.getElementById('cfcMdSearchOverlay');
  const inp = document.getElementById('cfcMdSearchInput');
  if (!ov) return;
  ov.classList.add('open');
  if (inp) { inp.value = ''; inp.blur(); }
  // 683 — klavye kendiliğinden açılmaz: arama çubuğu ve kişiler görünür, kutuya dokununca klavye açılır
  if (_cfcMdUsersCache && _cfcMdUsersCache.length) cfcMdRenderSearchResults('');
  // 🆕 Önce server'dan kayıtlı kullanıcıları yükle, sonra render
  try { await cfcMdLoadKnownUsers(''); } catch(e) {}
  await _cfcMdRozetYukle(cfcMdGetKnownUsers().map(u => u.id));
  if (!inp || !inp.value) cfcMdRenderSearchResults('');
}

function cfcMdCloseSearch() {
  const ov = document.getElementById('cfcMdSearchOverlay');
  if (!ov) return;
  ov.classList.remove('open');
  // Klavyeyi kapat (mobil)
  const inp = document.getElementById('cfcMdSearchInput');
  if (inp) inp.blur();
}

function cfcMdRenderSearchResults(query) {
  const container = document.getElementById('cfcMdSearchResults');
  if (!container) return;
  const users = cfcMdGetKnownUsers();
  const q = String(query || '').trim().toLowerCase();
  // Self önce, sonra alfabetik
  const filtered = users
    .filter(u => {
      if (!q) return true;
      const hay = (u.name + ' ' + u.handle).toLowerCase();
      return hay.indexOf(q) !== -1;
    })
    .sort((a, b) => {
      if (a.isMe && !b.isMe) return -1;
      if (!a.isMe && b.isMe) return 1;
      return a.name.localeCompare(b.name, 'tr');
    });

  if (!filtered.length) {
    container.innerHTML = `<div class="cfcmd-search-empty">
      <div class="cfcmd-search-empty-icon">${_CFCMD_IK.ara}</div>
      ${q ? 'Eşleşen kullanıcı bulunamadı.' : 'Henüz kayıtlı kullanıcı yok.'}
    </div>`;
    return;
  }

  const label = q ? 'SONUÇLAR' : 'KAYITLI KULLANICILAR';
  const items = filtered.map(u => {
    const flag = (u.country && _uyrukUlke(u.country).flag) || '';
    const countryName = (u.country && _uyrukUlke(u.country).name) || u.country || '';
    const parts = [];
    if (flag || countryName) parts.push(`${flag} ${_cfcMdEscape(countryName)}`.trim());
    if (u.team) parts.push(_cfcMdEscape(u.team));
    const subText = parts.join(' · ');
    return `
    <div class="cfcmd-search-item" onclick="cfcMdViewProfile('${u.id}')">
      <div class="cfcmd-search-avatar">${u.avatar || '⚽'}</div>
      <div class="cfcmd-search-meta">
        <div class="cfcmd-search-name">
          ${_cfcMdEscape(u.name)}${_cfcMdTik(u.id)}
          ${u.isMe ? '<span class="me-tag">Sen</span>' : ''}
        </div>
        ${subText ? `<div class="cfcmd-search-handle">${subText}</div>` : ''}
      </div>
      <span class="cfcmd-search-chev">${_CFCMD_IK.sag}</span>
    </div>`;
  }).join('');

  container.innerHTML = `
    <div class="cfcmd-search-section-lbl">${label} · ${filtered.length}</div>
    ${items}
  `;
}

// 635 — oyuncu kartındaki @kullanıcı adından gelince açılacak profil
let _cfcMdAcilisProfil = null;

// Profile aç — kendisi ise normal, başkası ise ziyaretçi modu
function cfcMdViewProfile(userId) {
  const my = cfcMdGetMyProfile();
  // 🆕 Açık olabilecek modalları kapat
  cfcMdCloseSearch();
  if (typeof cfcMdCloseFollows === 'function') cfcMdCloseFollows();
  // Kendisi mi?
  if (!userId || userId === my.id) {
    _cfcMdViewingUserId = null;
  } else {
    _cfcMdViewingUserId = userId;
  }
  // 🆕 Profile sekmesi UI'sını manuel aç (cfcMdTab _cfcMdViewingUserId'i sıfırlar!)
  _cfcMdCurrentTab = 'profile';
  document.querySelectorAll('.cfcmd-tab').forEach(t => {
    t.classList.toggle('active', t.getAttribute('data-cfcmd-tab') === 'profile');
  });
  const elGlobal = document.getElementById('cfcMdGlobal');
  const elNational = document.getElementById('cfcMdNational');
  const elFollowing = document.getElementById('cfcMdFollowing');
  const elProfile = document.getElementById('cfcMdProfile');
  if (elGlobal) elGlobal.style.display = 'none';
  if (elNational) elNational.style.display = 'none';
  if (elFollowing) elFollowing.style.display = 'none';
  if (elProfile) elProfile.style.display = 'block';
  cfcMdRender();
}

