function cfcMdFollowsTab(tab) {
  _cfcMdFollowsActiveTab = (tab === 'followers') ? 'followers' : 'following';
  document.querySelectorAll('.cfcmd-follows-tab').forEach(t => {
    t.classList.toggle('active', t.getAttribute('data-follows-tab') === _cfcMdFollowsActiveTab);
  });
  // Filtreyi temizle (sekme değiştiğinde temiz başla)
  const inp = document.getElementById('cfcMdFollowsInput');
  if (inp) inp.value = '';
  cfcMdRenderFollowsList('');
  _cfcMdTkpGordu();   // 938
}

function cfcMdRenderFollowsList(query) {
  const container = document.getElementById('cfcMdFollowsList');
  if (!container) return;

  // ID listesi → user objelerine resolve
  let users;
  let emptyMsg;
  let emptyIcon;
  if (_cfcMdFollowsActiveTab === 'following') {
    const ids = cfcMdGetFollowing();
    users = ids.map(_cfcMdResolveUserById).filter(Boolean);
    emptyIcon = _CFCMD_IK.kisiler;
    emptyMsg = 'Henüz kimseyi takip etmiyorsun.';
  } else {
    const ids = cfcMdGetFollowersList();
    users = ids.map(_cfcMdResolveUserById).filter(Boolean);
    emptyIcon = _CFCMD_IK.kisiler;
    emptyMsg = 'Henüz takipçin yok.<br><span style="font-size:11px;opacity:.7">Backend bağlandığında burada gözükecek.</span>';
  }

  // Filtre uygula
  const q = String(query || '').trim().toLowerCase();
  const filtered = q
    ? users.filter(u => (u.name + ' ' + u.handle).toLowerCase().indexOf(q) !== -1)
    : users;

  // Alfabetik sırala — 938: takipçiler sunucu sırasıyla (son takip eden üstte)
  if (_cfcMdFollowsActiveTab !== 'followers') filtered.sort((a, b) => a.name.localeCompare(b.name, 'tr'));

  // Boş durumlar
  if (!filtered.length) {
    if (!users.length) {
      container.innerHTML = `<div class="cfcmd-search-empty">
        <div class="cfcmd-search-empty-icon">${emptyIcon}</div>
        ${emptyMsg}
      </div>`;
    } else {
      container.innerHTML = `<div class="cfcmd-search-empty">
        <div class="cfcmd-search-empty-icon">${_CFCMD_IK.ara}</div>
        Eşleşen kullanıcı yok.
      </div>`;
    }
    return;
  }

  // Items — search-item ile aynı stiller
  const followingNow = cfcMdGetFollowing();
  const items = filtered.map(u => {
    const isFollowing = followingNow.includes(u.id);
    // "Following" sekmesinde küçük unfollow ipucu olarak takip durumu rozetli olabilir
    // Ama tıklamayla profile gitmek ana akış — sadece chevron göster
    const flag = (u.country && _uyrukUlke(u.country).flag) || '';
    const countryName = (u.country && _uyrukUlke(u.country).name) || u.country || '';
    const parts = [];
    if (flag || countryName) parts.push(`${flag} ${_cfcMdEscape(countryName)}`.trim());
    if (u.team) parts.push(_cfcMdEscape(u.team));
    const subText = parts.join(' · ');
    return `<div class="cfcmd-search-item" onclick="cfcMdViewProfile('${u.id}')">
      <div class="cfcmd-search-avatar">${u.avatar || '⚽'}</div>
      <div class="cfcmd-search-meta">
        <div class="cfcmd-search-name">${_cfcMdEscape(u.name)}${_cfcMdTik(u.id)}${_cfcMdFollowsActiveTab === 'followers' && _cfcMdYeniTkp && _cfcMdYeniTkp.has(u.id) ? '<span class="cfcmd-yeni">Yeni</span>' : ''}</div>
        ${subText ? `<div class="cfcmd-search-handle">${subText}</div>` : ''}
      </div>
      <span class="cfcmd-search-chev">${_CFCMD_IK.sag}</span>
    </div>`;
  }).join('');

  const label = _cfcMdFollowsActiveTab === 'following'
    ? `TAKİP ETTİKLERİM · ${filtered.length}`
    : `TAKİPÇİLERİM · ${filtered.length}`;
  container.innerHTML = `
    <div class="cfcmd-search-section-lbl">${label}</div>
    ${items}
  `;
}

