      //   değişen tek şey çevrimiçi damgasıdır → kadro yeniden çekilmez, yerelde işlenir.
      const _rtOyuncuImza = {};
      const _rtSadeceDamga = (payload) => {
        if (!payload || payload.eventType !== 'UPDATE' || !payload.new || payload.new.id == null) return false;
        const n = payload.new, parca = [];
        Object.keys(n).sort().forEach(k => {
          if (k === 'last_seen' || k === 'updated_at') return;
          const v = n[k];
          if (v !== null && typeof v === 'object') return;   // jsonb alanlar (TOAST'ta gelmeyebilir)
          parca.push(k + '=' + String(v));
        });
        const imza = parca.join('|'), onceki = _rtOyuncuImza[n.id];
        _rtOyuncuImza[n.id] = imza;
        if (onceki === undefined || onceki !== imza) return false;
        try {
          const r = (typeof ROSTER_DATA !== 'undefined' && Array.isArray(ROSTER_DATA)) ? ROSTER_DATA.find(x => x && x.id === n.id) : null;
          if (r && n.last_seen) {
            r.lastSeen = n.last_seen;
            const ms = new Date(n.last_seen).getTime();
            const esik = (typeof ONLINE_THRESHOLD_MS !== 'undefined') ? ONLINE_THRESHOLD_MS : 5 * 60 * 1000;
            r.isOnline = !!ms && (Date.now() - ms < esik);
          }
        } catch(e) {}
        return true;
      };

      // 🆕 ÖLÇEK: filtresiz abonelik, dünyadaki HER oyuncu satırı değişiminde
      //   (çevrimiçi damgası, maç istatistikleri) tüm istemcileri uyandırıyordu.
